    val cum = Array.ofDim[Long](as.length + 1)
    REP(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  def solve2(): Boolean = {
    val N, M = ni()
    if (M % 2 == 1) return false

    val (a, b) = na2(M, -1)
    val g = packUGraph(N, a, b)
    val (_, p, q) = traceBfs(g)

    val ans = ArrayBuffer[(Int, Int)]()
    val dp = Array.ofDim[Int](N)
    debug(q)
    val qr = Array.ofDim[Int](N)
    REP(N) { i =>
      qr(q(i)) = i
    }
    REP_r(N) { i =>
      val v = q(i)
      var cnt = 0
      REP(g(v).length) { j =>
        val u = g(v)(j)
        if (u != p(v) && qr(u) < qr(v)) { // qr(v) > qr(u) の場合はこのエッジを既に処理している
          debug(s"v:$v u:$u")
          cnt += 1
          ans += v -> u
        }
      }
      val par = (dp(v) % 2) ^ (cnt % 2)
      // 帳尻あわせ
      if (par == 1) {
        ans += v -> p(v)
      } else if (v != 0) {
        ans += p(v) -> v
        dp(p(v)) += 1
      }
    }

    debug(ans.mkString(" "))

    assert(M == ans.length)
    REP(M) { i =>
      val e = ans(i)
      out.println(s"${e._1+1} ${e._2+1}")
    }

    true
  }

  def solve(): Unit = {
    if (!solve2()) out.println(-1)
  }

  def packUGraph(n: Int, from: Array[Int], to: Array[Int]): Array[Array[Int]] = {
    val t = new Array[Array[Int]](n)
    val p = new Array[Int](n)
    val m = from.length
    REP(m)(i => p(from(i)) += 1)
    REP(m)(i => p(to(i)) += 1)
    REP(n)(i => t(i) = new Array(p(i)))
    REP(m) { i =>
      p(from(i)) -= 1
      t(from(i))(p(from(i))) = to(i)
      p(to(i)) -= 1
      t(to(i))(p(to(i))) = from(i)
    }
    t
  }

  /**
    * @return (depth, parent, queue)
    */
  def traceBfs(g: Array[Array[Int]], rt: Int = 0): (Array[Int], Array[Int], Array[Int]) = {
    val n = g.length
    val INF = 1e9.toInt + 10
    val q, p = Array.ofDim[Int](n)
    q(0) = rt
    p(rt) = -1
    val d = Array.fill[Int](n)(INF)
    d(rt) = 0
    var cur = 0
    var last = 1
    while (cur < last) {
      val v = q(cur)
      REP(g(v).length) { i =>
        val u = g(v)(i)
        if (d(u) == INF) {
          d(u) = d(v) + 1
          p(u) = v
          q(last) = u
          last += 1
        }
      }
      cur += 1
    }
    (d, p, q)
  }
}

