struct UnionFind {
    vector<int> par; // 親ノード
    vector<int> rank; // ランク

    UnionFind(int n = 1) {
        init(n);
    }

    void init(int n = 1) {
        par.resize(n); rank.resize(n);
        for (int i = 0; i < n; ++i) par[i] = i, rank[i] = 0;
    }

    int root(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            int r = root(par[x]);
            return par[x] = r;
        }
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        return true;
    }
};

struct Edge
{
public:
    Edge(int to, int dir) : to(to), dir(dir) {}
    int to;
    int dir;
};

using Edges = vector<Edge>;
using Graph = vector<Edges>;

void DFS(Graph& g, int curr, int prev, vector<bool>& visited)
{
    visited[curr] = true;

    for (const auto& e : g[curr])
    {
        if (e.dir == 0)
        {
            if (visited[e.to])
            {
                continue;
            }

            DFS(g, e.to, curr, visited);
        }
    }

    if (prev == -1)
    {
        return;
    }

    int outNum = 0;
    for (const auto& e : g[curr])
    {
        if (e.dir == 1)
        {
            ++outNum;
        }
    }

    if (outNum % 2 == 0)
    {
        for (auto& e : g[curr])
        {
            if (e.to == prev)
            {
                e.dir = -1;

                for (auto& f : g[prev])
                {
                    if (f.to == curr)
                    {
                        f.dir = 1;
                        break;
                    }
                }

                break;
            }
        }
    }
    else
    {
        for (auto& e : g[curr])
        {
            if (e.to == prev)
            {
                e.dir = 1;

                for (auto& f : g[prev])
                {
                    if (f.to == curr)
                    {
                        f.dir = -1;
                        break;
                    }
                }

                break;
            }
        }
    }
}

void _main()
{
