        --A; --B;

        if (uf.issame(A, B))
        {
            g[A].emplace_back(B, 1);
            g[B].emplace_back(A, -1);
        }
        else
        {
            uf.merge(A, B);

            g[A].emplace_back(B, 0);
            g[B].emplace_back(A, 0);
        }
    }

    if (M % 2 != 0)
    {
        cout << -1 << endl;
        return;
    }

    vector<bool> visited(N, false);
    DFS(g, 0, -1, visited);

    rep(i, 0, N)
    {
