//Union-Find 
//0-indexed 注意！！
struct UnionFind {
  //data[idx]はノードの「根」もしくは「親」を格納している（必ずしも根ではない！）
  //  Q. 「根」じゃないの？
  //  初めは「根」を入れてるのだが、別のところでuniteが起きると情報が古くなる。
  //  だからfind_root()で再帰的に求めないと間違いが起こり得る。
  //  ちなみに「根」ノードのdata[idx]は直接アクセスしてok（最後にuniteされたものなので）
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1); //ノードが属する根の番号を格納（根の場合はマイナス要素数を格納）
  }

  //併合　成功したらtrue, 既に同じ木ならfalse
  bool unite(int x, int y) {
    x = find_root(x), y = find_root(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  bool isSameGroup(int x, int y){
    x = find_root(x), y = find_root(y);
    if(x == y) return true;
    else return false;
  }

  //ノードが属する根の番号を返す（引数が根だった場合はその番号をそのまま帰す）
  int find_root(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find_root(data[k]));
  }

  //ノードが属する木に属するノードの数を返す
  int count(int k) {
    return (-data[find_root(k)]);
  }

  //木の数（接続していないグラフの数）を返す
  //根となっているノード（data[k]が負のもの）を数えるだけ
  int count_trees() {
    int ans = 0;
    for (int each_d : data){
      if (each_d < 0){
        ans += 1;
      }
    }
    return ans;
  }
};


//深さ優先探索　隣接リスト表現（重みなし）
//何か他に変数を持ちたい場合（ansなど）、グローバルで宣言してしまうこと
using AdjList_Unweighted = vector<vector<int> >;
vector<bool> seen;
int dfs(AdjList_Unweighted &graph, int node_id, int p_nodeid){
  seen[node_id]=true;

  //行きがけの処理はここで

  for(auto each_adj : graph[node_id]){
    if(seen[each_adj]){
      continue;
    }
    stree_odegs[node_id] += dfs(graph, each_adj, node_id);
  }

  //帰りがけの処理はここで
  //辺は帰りがけに繋ぐ
  if (node_id==0){ //終わり
    return 0;
  }
  else if (stree_odegs[node_id]%2==0){
    //自分が偶数なら、親から出すので親の出次数は+1
    o_edge(p_nodeid, node_id); br();
    return 1;
  }
  else{
    //自分が奇数なら、自分から出すので親は+-0
    o_edge(node_id, p_nodeid); br();
    return 0;
  }

}

// ----- library end ----- //




int main() {

  int N = ii();
  int M = ii();

  stree_odegs.assign(N+1, 0); //出次数 (便宜上[N]を0の親とする)

  if (M%2 == 1){
    oi(-1); br();
    return 0;
  }

  //隣接リスト表現（重みなし）
  AdjList_Unweighted Adjs(N);
  UnionFind UF(N);

  int a, b;
  while(cin >> a >> b){
    a--;
    b--; //0-indexedに
    if(UF.unite(a, b)){
      //今連結した = 今まで連結していなかった = 全域木に入れる辺
      Adjs[a].PB(b);
      Adjs[b].PB(a);
    }
    else{
      //既に連結していた = 全域木に入れない辺なので、出力&出次数++
      o_edge(a, b); br(); //a -> b とする
      stree_odegs[a]++;
    }
  }

  //全域木にDFSをかける（根は0にしておく）
  seen.assign(N, false);
  dfs(Adjs, 0, N); //グラフと、最初に探索するノードIDを渡す


// -- main() end -- //
}

