//gが二部グラフかどうかを判定
//return=true二部グラフ構築可能、false不可能
//seen=0未訪問、1黒、-1白
bool isBipartiteGraph(vector<vector<ll>> &g,ll v,vector<ll> &seen){
	for(ll nextv:g[v]){
		if(seen[nextv]!=0){
			if(seen[nextv]==seen[v])return false;
			else continue;
		}
		seen[nextv]=-1*seen[v];
		bool b=isBipartiteGraph(g,nextv,seen);
		if(!b)return false;
	}
	return true;
}



