bool dfs(int x,int bf) {
	vis[x] = true;
	bool c = false;
	for (edge e : v[x]) {
		if (!e.rev)c ^= true;
	}
	for (int i = 0; i < v[x].size(); ++i) {
		if (!vis[v[x][i].to]) {
			if (dfs(v[x][i].to, x)) {
				c ^= true;
				v[x][i].rev ^= true;
			}
		}
	}
	if (c) {
		for (edge &e : v[x]) {
			if (e.to == bf) {
				e.rev ^= true;
				break;
			}
		}
		return true;
	}
	return false;
}


