int main() {
    int n, m;
    cin >> n >> m;
    vector<int> g[n];
    vector<int> deg(n, 0);
    vector<pair<int, int>> edge;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        edge.emplace_back(a, b);
        g[a].push_back(i);
        g[b].push_back(i);
        deg[a]++; deg[b]++;
    }

    if (m & 1) { cout << -1 << '\n'; return 0; }

    vector<int> idx(n);
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int l, int r) { return (deg[l] < deg[r]); });

    vector<bool> used(m, false);
    vector<pair<int, int>> ans;
    for (int v : idx) {
        int max_deg = 0, id = -1;
        if (deg[v] & 1) {
            for (int i : g[v]) if (not used[i]) {
                int a = edge[i].first == v ? edge[i].second : edge[i].first;
                if (chmax(max_deg, deg[a])) id = i;
            }
            int u = edge[id].first == v ? edge[id].second : edge[id].first;
            used[id] = true; deg[v]--;
            ans.emplace_back(v, u);
        }
        for (int i : g[v]) if (not used[i]) {
            int u = edge[i].first == v ? edge[i].second : edge[i].first;
            used[i] = true; deg[u]--;
            ans.emplace_back(u, v);
        }
    }

