const int MAX_V = (int)1e5 + 77;

vector<int> g[MAX_V];
int n, m, d[MAX_V];
bool met[MAX_V];
set<pii> dir_edges;

inline void invert(int v, int u)
{
	//cout << "inverting " << v + 1 << " -- " << u + 1 << endl;

	pii ed1 = {v, u}, ed2 = {u, v};

	if(dir_edges.count(ed1))
	{
		dir_edges.erase(ed1);
		dir_edges.insert(ed2);

		//--d[ed1.first];
		//++d[ed2.first];
	}
	else
	{
		dir_edges.erase(ed2);
		dir_edges.insert(ed1);

		//--d[ed2.first];
		//++d[ed1.first];
	}
}

int dfs(int v)
{
	met[v] = true;
	int cnt = 0;

	for(auto& u: g[v])
	{
		if(met[u])
			continue;

		int subtree = dfs(u);

		if(subtree & 1)
			invert(v, u);

		cnt += subtree;
	}

	return cnt + (d[v] & 1);
}

void solve()
{
	cin >> n >> m;

	for(int i = 0; i < m; ++i)
	{
		int v, u;
		cin >> v >> u;
		--v, --u;

		dir_edges.emplace(v, u);
		++d[v];

		g[v].push_back(u);
		g[u].push_back(v);
	}

	if(m & 1)
	{
		cout << NIL << endl;
		return;
	}

	dfs(0);

	for(auto& ed: dir_edges)
		cout << ed.first + 1 << " " << ed.second + 1 << endl;
}

int main()
{
	fast_io();
	solve();

	return 0;
}

