vector<int> adj[maxn];

int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }

void dfs(int u, int parent) {
  for(auto v : adj[u]) {
    if(v != parent) dfs(v, u);
  }
  if(parent == -1) return;
  if(deg[u] & 1) ansu[tot] = u, ansv[tot] = parent, ++tot;
  else ansu[tot] = parent, ansv[tot] = u, deg[parent] ^= 1, ++tot;
}

