	for (int i = 0; i < M; ++i) {
		llong to, from;
		cin >> to >> from;
		edges[to].push_back(lpair(from, i));
		edges[from].push_back(lpair(to, i));
	}

	bool check = true;
	for (auto &edge : edges)
		check &= edge.size() % 2 == 0;

	if (check == false) {
		cout << -1 << endl;
		return 0;
	}
	return 1;

	vector<llong> cnt(N+1, 0), usedV(N+1, 0), usedE(M, 0);
	vector<lpair> ans;
	queue<llong> q;
	q.push(1);
	while (q.size()) {
		llong now = q.front();
		q.pop();
		if (usedV[now]) continue;
		usedV[now]++;

		for (auto edge : edges[now]) {
			if (usedE[edge.second]) continue;
			usedE[edge.second]++;

			if (cnt[now] & 1) {
				ans.push_back(lpair(edge.first, now));
				cnt[now]++;
			} else {
				ans.push_back(lpair(now, edge.first));
				cnt[edge.first]++;
			}

			q.push(edge.first);
		}
	}

	check = true;
	for (auto c : cnt)
		check &= c%2 == 0;

	if (check) {
		for (auto edge : ans)
			cout << edge.first << " " << edge.second << endl;
