void dfs(int u) {
  vis[u] = 1;
  for (int i : adj[u]) {
    int v = u ^ l[i] ^ r[i];
    if (!vis[v]) {
      par[v] = i;
      tree[i] = 1;
      d[v] = d[u] + 1;
      dfs(v);
    }
  }
}

