    scanf("%d %d", &l[i], &r[i]);
    adj[l[i]].push_back(i);
    adj[r[i]].push_back(i);
  }

  dfs(1);

  for (int i = 1; i <= m; ++i) {
    if (!tree[i]) deg[l[i]] ^= 1;
  }

  vector<int> id(n - 1);
  iota(id.begin(), id.end(), 2);
  sort(id.begin(), id.end(), [](int i, int j) { return d[i] > d[j]; });

  for (int u : id) {
    int e = par[u];
    if(deg[u] ^ (l[e] == u)) swap(l[e], r[e]); 
    deg[l[e]] ^= 1;
  }

  for (int i = 1; i <= m; ++i) {
    printf("%d %d\n", l[i], r[i]);
  }
}

