struct UnionFind{
  vector<int> p;
  int g;
  void init(int n){
    p.assign(n, -1);
    g = n;
  }
  int find(int a){
    return p[a] < 0 ? a : p[a] = find(p[a]);
  }
  bool merge(int a, int b){
    a = find(a);
    b = find(b);
    if(a==b) return 0;
    g--;
    if(p[a]>p[b]) swap(a, b);
