          if (visited[edge.to]) continue;
          used_edges[edge.to] = edge.id;
          dfs(edge.to, v);
        }

        if (out_degrees[v] % 2 == 1) {
          int edge_id = used_edges[v];
          if (edge_id < 0) return;
          int reverse_edge_id = edges[edge_id].reverse_id;
          if (is_actives[edge_id]) {
            out_degrees[edges[edge_id].from]--;
            out_degrees[edges[edge_id].to]++;
            is_actives[edge_id] = false;
            is_actives[reverse_edge_id] = true;
          } else {
            out_degrees[edges[edge_id].to]++;
            out_degrees[edges[edge_id].from]--;
            is_actives[edge_id] = true;
            is_actives[reverse_edge_id] = false;
          }
        }
      });

  dfs(0, -1);

  for (int i = 0; i < 2 * m; i++) {
    if (is_actives[i]) {
      cout << edges[i].from + 1 << " " << edges[i].to + 1 << endl;
    }
  }
}

