struct MyEdge {
    //! 辺id
    int id;
    //! 端点
    int a;
    //! 端点
    int b;

    int in_dfs;

    int dir;
    /**
     * @brief Construct a new Edge object
     * @param id 辺番号
     * @param a 辺に接続する頂点番号
     * @param b 辺に接続する頂点番号
     */
    MyEdge(int id = 0, int a = 0, int b = 0, int c = 0, int d = 0)
        : id(id), a(a), b(b), in_dfs(c), dir(d) {}
    /**
     * @brief 辺における，vの対になってる頂点番号を取得する
     * @param v 頂点番号
     * @return int vじゃない方の頂点番号
     */
    inline int versus(const int v) const { return a ^ b ^ v; }
};
int deg[112345];

Graph<MyEdge> g(112345, 112345);

void dfs(int v, vector<int>& used) {
    used[v] = 1;
    for (int ei : g[v]) {
        auto& e     = g.i2e(ei);
        const int u = e.versus(v);
        if (used[u]) continue;
        dfs(u, used);
        if (deg[u] % 2) {
            e.dir = 1 - e.dir;
            deg[v]++;
        }
    }
}
