const int maxn = 100010;
int n, m, u[maxn], v[maxn], d[maxn], fa[maxn];
bool tmp[maxn], vis[maxn];
set<pair<int, int> > ans;
vector<int> V, G[maxn];

void dfs1(int v, int f) {
    vis[v] = 1, fa[v] = f;
    for (int u : G[v]) {
        if (!vis[u]) d[v]++, ans.insert({v, u}), dfs1(u, v);
        else if (!ans.count({u, v})) d[v]++, ans.insert({v, u});
    }
}

void dfs2(int v) {
    vis[v] = 1;
    for (int u : G[v]) if (!vis[u]) {
        dfs2(u), tmp[v] ^= tmp[u];
    }
    if (tmp[v]) {
        assert(v != 1);
        ans.erase({fa[v], v});
        ans.insert({v, fa[v]});
    }
}

int main() {
