    for (int i = 1; i <= m; i++) {
        scanf("%d %d", &u[i], &v[i]);
        G[u[i]].push_back(v[i]), G[v[i]].push_back(u[i]);
    }
    dfs1(1, 0);
    assert(accumulate(d + 1, d + n + 1, 0) == m);
    for (int i = 1; i <= n; i++) {
        if (d[i] & 1) V.push_back(i);
    }
    assert(V.size() % 2 == 0);
    for (int i = 0; i < V.size(); i += 2) {
        tmp[V[i]] ^= 1, tmp[V[i + 1]] ^= 1;
    }
    memset(vis, 0, sizeof(vis)), dfs2(1);
