using namespace std;
typedef pair<int,int> ii;
int n,m;
int deg[100005];
bool parity[100005];
vector<int> al[100005];
priority_queue<ii, vector<ii>, greater<ii> > pq;
int main(){
    scanf("%d%d",&n,&m);
    if (m&1){
        printf("-1\n");
        return 0;
    }
    int a,b;
    while (m--){
        scanf("%d%d",&a,&b);
        al[a].push_back(b);
        al[b].push_back(a);
        deg[a]++;
        deg[b]++;
    }

    for (int x=1;x<=n;x++){
        pq.push(ii(deg[x],x));
    }

    int node,dn;
    bool out;
    while (!pq.empty()){
        dn=pq.top().first,node=pq.top().second,pq.pop();
        if (deg[node]<dn || dn==0) continue;

        if (parity[node]^(deg[node]&1)) out=true;
        else out=false;
        for (auto &it:al[node]){
            if (deg[it]){
                if (out && (deg[it]>1 || parity[it])){
                    printf("%d %d\n",it,node);
                    out=false;
                    parity[it]^=true;
                }
                else printf("%d %d\n",node,it);
                deg[it]--;
                pq.push(ii(deg[it],it));
            }

            deg[node]=0;
        }
    }
}

