int getOther(Edge e, int v)
{
    return v ^ e.u ^ e.v;
}

void dfs(int v)
{
    used[v] = true;
    for (int i : g[v])
    {
        int u = getOther(edges[i], v);
        if (!used[u])
        {
            dfs(u);
            if (col[u])
            {
                col[u] ^= 1;
                col[v] ^= 1;
                edges[i].rev = true;
            }
        }
    }
}

