void dfs(Graph &G, const int v, std::vector<bool> &visited,
         std::vector<int> &out) {
  visited[v] = true;
  for (auto &e : G[v]) {
    int c = std::get<0>(e);

    if (charge % 2 == 1) {
    // if (out[v] % 2 == 1 and charge % 2 == 0) {
      std::get<2>(e) = 1;
      int idx = std::get<1>(e);
