void dfs(int curr, int prev) {
    parent[curr] = prev;
    for(auto e : adj[curr]) {
        int next;
        if(e->u == curr) next = e->v;
        else next = e->u;
        if(parent[curr] != next && parent[next] == -1) {
            dfs(next, curr);
            e->spanning = true;
        }
    }
}

void setDirection(int curr) {
    for(auto e : adj[curr]) {
        if(e->spanning) {
            int next;
            if(e->u == curr) next = e->v;
            else next = e->u;
            if(parent[curr] != next) {
                setDirection(next);
                if(out[next] % 2 == 0) {
                    if(curr == e->u) {
                        e->dir = 1;
                        out[curr]++;
                    } else {
                        e->dir = -1;
                        out[next]++;
                    }
                } else {
                    if(curr == e->u) {
                        e->dir = -1;
                        out[next]++;
                    } else {
                        e->dir = 1;
                        out[curr]++;
                    }
                }
            }
        }
    } 
}


