        cout << v + 1 << ' ' << w + 1 << '\n';
        ++out[v];
      } else {
        cout << w + 1 << ' ' << v + 1 << '\n';
        ++out[w];
      }
      if (--d[w] == 1) que.push(w);
    }
  }
}

