map<int,int> M;
map<int,bool> mm[100000];

signed main() {
    cin >> n >> m;
    rep(i,m) {
        cin >> a >> b;--a,--b;
        M[a]++;
        M[b]++;
        v[a].pb(b);
        v[b].pb(a);
        mm[min(a,b)][max(a,b)] = true;
    }
    if (m%2) {
        cout << -1 << endl;
        return 0;
    } else {
        rep(i,n) {
            priority_queue<pair<int,int>> pq;
            vector<int> V;
            rep(j,v[i].size()) {
                if (!mm[min(i,v[i][j])][max(i,v[i][j])]) continue;
                if (M[v[i][j]]%2) V.pb(v[i][j]);
                else pq.push(mp(M[v[i][j]],v[i][j]));
            }
            int border=V.size()/2*2;
            if (pq.size()) border = V.size();
            rep(j,border) {
                ans.pb(mp(i,V[j]));
                mm[min(i,V[j])][max(i,V[j])] = false;
                M[i]--;
                M[V[j]]--;
            }
            if (border%2) border=1;
            border += (pq.size()-border)/2*2;
            rep(j,border) {
                int tmp = pq.top().se;pq.pop();
                ans.pb(mp(i,tmp));
                mm[min(i,tmp)][max(i,tmp)] = false;
                M[i]--;
                M[tmp]--;
            }
        }
    }
    rep(i,m) cout << ans[i].fi+1 << " " << ans[i].se+1 << endl;
}

