struct union_find_set{
	int fa[maxn];
	void init(){for (int i=1;i<=n;i++) fa[i]=i;}
	int find(int x){return fa[x]==x?x:fa[x]=find(fa[x]);}
	bool merge(int x,int y){
		x=find(x),y=find(y); if (x==y) return 0;
		return fa[x]=y,1;
	}
}u;

void add(int a,int b,int c){son[++tot]=b,pre[tot]=now[a],now[a]=tot,val[tot]=c;}
void link(int a,int b){add(a,b,b),add(b,a,b);}

void dfs(int x,int fa){
	for (int p=now[x];p;p=pre[p])
		if (son[p]!=fa){
			dfs(son[p],x);
			if (!deg[son[p]]) ans[++cnt]=mp(x+son[p]-val[p],val[p]);
			else ans[++cnt]=mp(val[p],x+son[p]-val[p]);
			deg[x]^=deg[son[p]];
		}
}

int main(){
	n=read(),m=read();
	if (m&1){puts("-1"); return 0;}
	u.init();
	for (int i=1;i<=m;i++){
		int x=read(),y=read(); deg[x]^=1;
		if (u.merge(x,y)) link(x,y);
		else ans[++cnt]=mp(x,y);
	}
	dfs(1,0);
	for (int i=1;i<=m;i++) printf("%d %d\n",ans[i].ff,ans[i].ss);
    return 0;
}

