        g[y].push_back(x);
        if (dsu::unite(x, y)) {
            r[x].push_back(y);
            r[y].push_back(x);
        }
    }
    dfs(0);
    vector<int> odd;
    rep(v, 0, n) if (deg[v] % 2 == 1) odd.push_back(v);
    if (odd.size() % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }
    lca::dfs(0, 0);
    while (!odd.empty()) {
        int x = odd.back();
        odd.pop_back();
        int y = odd.back();
        odd.pop_back();
        reverse_on_path(x, y);
    }
    restore(0, 0);
    rep(i, 0, n) assert(deg[i] % 2 == 0);
    for(const auto& e : ans) {
        cout << e.fst + 1 << ' ' << e.snd + 1 << '\n';
    }

    return 0;
}

