public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    void make_spanning(int v){
        vis[v] = true;
        for (auto &&u : E[v]) {
            if(vis[u]) { continue; }
            make_spanning(u);
            sE.emplace_back(v, u);
        } // end u
    }

    void run(){
        is >> N >> M;
        if(!is) return;
        for (int i = 0; i < M; ++i) {
            int A, B; is >> A >> B;
            E[A].insert(B); E[B].insert(A);
