const int maxn = 100005;
std::vector<par> G[maxn];
bool a[maxn], vis[maxn];
par edge[maxn];
bool ans[maxn];

void dfs(int u) {
	vis[u] = true;
	for(par p : G[u])
		if(not vis[p.first]) {
			dfs(p.first);
			if(a[p.first]) {
				a[u] ^= 1;
				a[p.first] ^= 1;
				ans[p.second] ^= 1;
			}
		}
}

int main() {
	int n = input(), m = input();
	for(int i = 1; i <= m; i ++) {
		int u = input(), v = input();
		G[u].push_back(par(v, i));
		G[v].push_back(par(u, i));
		edge[i] = par(u, v);
		a[u] ^= 1;
	}
	dfs(1);
	if(a[1])
		puts("-1");
	else {
		for(int i = 1; i <= m; i ++) {
			if(ans[i]) std::swap(edge[i].first, edge[i].second);
			printf("%d %d\n", edge[i].first, edge[i].second);
		}
	}
}

