vector<pair<i64, i64>> ans;

namespace dfs1 {
  void dfs(int v) {
    cnt[v] = 1;
    for(auto [t, i]: G[v]) {
      if(cnt[t]) continue;
      used[i] = 1;
      dfs(t);
    }
  }
}

namespace dfs2 {
  void dfs(int v, int f) {
    for(auto [t, i]: G[v]) {
      if(t == f) continue;
      if(!used[i]) continue;
      dfs(t, v);
    }
    if(cnt[v]) { 
      ans.emplace_back(v, f);
      cnt[v] ^= 1;
    }
    else {
      ans.emplace_back(f, v);
      cnt[f] ^= 1;
    }
  }
}

int main() {
  cin >> N >> M;
  G.resize(N);
  used.resize(M);
