    G[A[i]].emplace_back(B[i], i);
    G[B[i]].emplace_back(A[i], i);
  }
  if(M % 2 == 1) {
    cout << -1 << endl;
    return 0;
  }

  dfs1::dfs(0);
  cnt.assign(N, 0);
  rep(i,0,M) {
    if(!used[i]) {
      cnt[A[i]] ^= 1;
      ans.emplace_back(A[i], B[i]);
