void solve() {
    int n,m;
    cin >> n >> m;
    VVI es(n);
    int a,b;
    REP(i,0,m) {
        cin >> a >> b;
        --a; --b;
        es[a].push_back(b);
        es[b].push_back(a);
    }
    if (m % 2 == 1) {
        cout << -1 << endl;
        return;
    }
    set<PII> s;
    VI en(n);
    REP(i,0,n) en[i] = es[i].size();
    //auto it = min_element(all(en));
    priority_queue<PII,std::vector<PII>,std::greater<PII>> q;
    // REP(i,0,n) if (en[i] == *it) q.emplace(en[i], i);
    REP(i,0,n) q.emplace(en[i], i);
    VP ans;
    VI cnt(n);
    vector<bool> fin(n);
    while (!q.empty()) {
        auto p = q.top();
        q.pop();
        int rem = p.first, index = p.second;
        if (fin[index]) continue;
        /*
        dump(index);
        dump(rem);
        dump(cnt[index]);
        dump(en[index]);
        */
        fin[index] = true;
        if ((cnt[index] + en[index]) % 2 == 1) {
            int last = -1;
            REP(i,0,es[index].size()) {
                if (s.count(MP(index,es[index][i])) != 0) continue;
                s.emplace(MP(index,es[index][i]));
                s.emplace(MP(es[index][i],index));
                en[es[index][i]]--;
                en[index]--;
                q.emplace(en[es[index][i]], es[index][i]);
                if (en[index] == 0) {
                    last = i;
                    break;
                }
                cnt[index]++;
                ans.pb(index, es[index][i]);
            }
            if (last == -1) {
                cout << -1 << endl;
                return;
            }
            cnt[es[index][last]]++;
            ans.pb(es[index][last], index);
        } else {
            REP(i,0,es[index].size()) {
                if (s.count(MP(index,es[index][i])) != 0) continue;
                s.emplace(MP(index,es[index][i]));
                s.emplace(MP(es[index][i],index));
                en[es[index][i]]--;
                en[index]--;
                q.emplace(en[es[index][i]], es[index][i]);
                cnt[index]++;
                ans.pb(index, es[index][i]);
            }
        }
    }
    VI cs(n);
    for (auto &p: ans) cs[p.first]++;
    REP(i,0,n) if (cs[i] % 2 != 0) {
        cout << -1 << endl;
        return;
    }
    for (auto &p: ans) cout << p.first + 1 << " " << p.second + 1 << endl;
}

