const int N = 1e5+1, iters = 1000;

int n, m;
vector<pair<int, int>> edges;

int deg[N];

int main(){
    srand(time(NULL));
    ios_base::sync_with_stdio(false);
    cout.tie(0);
    cin.tie(0);
    cin >> n >> m;
    edges.resize(m);
    for(int i = 0; i < m; ++i){
        cin >> edges[i].x >> edges[i].y;
        --edges[i].x; --edges[i].y;
    }
    for(int _ = 0; _ < iters; ++_){
        random_shuffle(edges.begin(), edges.end());
        for(int i = 0; i < n; ++i)
            deg[i] = 0;
        vector<pair<int, int>> ans;
        for(auto edge : edges){
            if(deg[edge.x] == 0)
                swap(edge.x, edge.y);
            ans.push_back(edge);
            deg[edge.x] ^= 1;
        }
        bool fail = false;
        for(int i = 0; i < n; ++i)
            if(deg[i]){
                fail = true;
                break;
            }
        if(!fail){
            for(auto el : ans)
                cout << el.x+1 << ' ' << el.y+1 << '\n';
            return 0;
        }
    }
    cout << "-1\n";
}

