vector < int > g[maxN];
int edges = 0;
vector < pair < int, int > > ans;
bool used[maxN];
int total[maxN];
void dfs(int v, int par) {
    used[v] = true;
    for (int to : g[v]) {
        if (used[to] && to != par) {
            ans.emplace_back(v, to);
            total[v] ^= 1;
        }
    }
    for (int to : g[v]) {
        if (!used[to]) dfs(to, v);
    }
    if (v != 1) {
        if (total[v] == 1) {
            ans.emplace_back(v, par);
            total[v] = 0;
        } else {
            ans.emplace_back(par, v);
            total[par] ^= 1;
        }
    }
}
