    }
    vector<set<int>> ab(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        ab[a - 1].insert(b - 1);
        ab[b - 1].insert(a - 1);
    }
    int num = 0;
    while (num < m) {
        vector<pair<int, int>> v;
        for (int i = 0; i < n; ++i) {
            if (ab[i].size() == 1) {
                int src = *ab[i].begin();
                v.push_back({ src, i });
            }
        }
        num += v.size();
        for (pair<int, int> p : v) {
            ab[p.second].erase(p.first);
        }

        bool next = true;
        for (int i = 0; i < n; ++i) {
            if (ab[i].size() % 2 != 0) {
                for (set<int>::iterator it = ab[i].begin(); it != ab[i].end(); ++it) {
                    if (ab[*it].size() % 2 != 0) {
                        next = false;
                        ab[*it].erase(i);
                        ab[i].erase(*it);
                        num += 2;
                        break;
                    }
                }
            }
        }

        if (v.empty() && next) {
            for (int i = 0; i < n; ++i) {
                if (ab[i].size() > 0) {
                    ab[i].erase(*ab[i].begin());
                    ++num;
                    break;
                }
