            edge[graph[idx][i]]--;
            que.push(make_pair(graph[idx][i], idx));
            p.insert(make_pair(graph[idx][i], idx));
            p.insert(make_pair(idx, graph[idx][i]));

            if(edge[graph[idx][i]] % 2 == 0){
                next.push(graph[idx][i]);
            }
        }
    }

    while(!next.empty()){
        dfs(next.front());
        next.pop();
    }

    return;
}

