int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj_list(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        adj_list[a].push_back(b);
        adj_list[b].push_back(a);
    }
    if (m % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }
    vector<int> dfs_num(n, -1);
    vector<int> edge_count(n, 0);
    vector<pair<int, int>> result;
    int num_visited = 0;
    function<void (int)> dfs = [&](int i) {
        dfs_num[i] = num_visited++;
        int count = 0;
        for (int j : adj_list[i]) {
            if (dfs_num[j] == -1) {
                dfs(j);
                count += edge_count[j] + 1;
                if (edge_count[j] % 2 == 0) {
                    result.push_back(make_pair(i, j));
                } else {
                    result.push_back(make_pair(j, i));
                }
            } else if (dfs_num[j] > dfs_num[i]) {
                result.push_back(make_pair(i, j));
                ++count;
            }
        }
        edge_count[i] = count;
    };
    dfs(0);
    for (auto edge : result) {
        cout << edge.first+1 << " " << edge.second+1 << "\n";
    }
    return 0;
}

