using namespace std;
set<int> G[100010];
int n,mx = 10000000,a[100010];
pair<int,int> t[200010];
vector<pair<int,int>> v;
void built(){
	for(int i = n-1;i>0;i--){
		t[i] = min(t[i<<1],t[i<<1|1]);
	}
}

void update(int p,int y){
	int x = t[p+n].first;
	for(t[p+=n] = {x - y,p};p>1;p >>= 1){
		t[p>>1] = min(t[p],t[p^1]);
	}
}

pair<int,int> query(int l, int r){
	pair<int,int> mn = {mx,-1};
	for(l += n, r += n; l<r; l >>= 1,r >>= 1){
		if(l&1) mn = min(mn,t[l++]);
		if(r&1) mn = min(mn,t[--r]);
	}
	return mn;
}

int main(){
	int i,m;
	cin >> n >> m;
	cout << m << endl;
	if(m&1){
		cout << -1 << endl;
		return 0;
	}
	for(i=0;i<m;i++){
		int a,b; cin >> a >> b;
		a--; b--;
		G[a].insert(b);
		G[b].insert(a);
	}
	for(i=0;i<n;i++){
		t[i + n] = {G[i].size(),i};
	}
	built();
	while(v.size()<m){
		auto p = query(0,n);
		if(p.first==0){
			update(p.second,-10000000);
			continue;
		}
		int ver = p.second;
		int e = *G[ver].begin();
		G[ver].erase(e); G[e].erase(ver);
		update(ver,1); update(e,1);
		if(a[ver]&1){
			v.push_back({ver,e}); a[ver]++;
		}else{
			v.push_back({e,ver}); a[e]++;
		}
	}
	for(i=0;i<n;i++){
		if(a[i]&1){
			cout << "NO" << endl;
			return 0;
		}
	}
	for(i=0;i<m;i++){
		cout << v[i].first + 1 << " " << v[i].second + 1 << endl;
	}
}

