template< typename T >
T kruskal(Edges< T > &edges, int V) {
  sort(begin(edges), end(edges), [](const edge< T > &a, const edge< T > &b) {
    return (a.cost < b.cost);
  });
  UnionFind tree(V);
  T ret = 0;
  for(auto &e : edges) {
    if(!tree.same(e.src, e.to)) {
        ret += e.cost;
        tree.unite(e.src, e.to);
        MST.eb(e.src, e.to, 1);
        st.insert(PII(e.src,e.to));
        adj[e.src].eb(e.to);
        adj[e.to].eb(e.src);

    }
  }
  return (ret);
}

