/*
 * 重み無しグラフで、辺集合表現から隣接集合表現へ変換
 */
template<bool Directed, typename N>
std::vector<std::unordered_set<N>> edges2neighsets(const std::vector<std::pair<N, N>>& edges, N n)
{
	std::vector<std::unordered_set<N>> neighs(n);
	for (const auto& edge : edges) {
		auto a = std::get<0>(edge);
		auto b = std::get<1>(edge);
		neighs[a].insert(b);
		if (Directed)
			neighs[b].insert(a);
	}
	return neighs;
}

/*
 * 重み付きグラフで、辺集合表現から隣接集合表現へ変換
 */
template<bool Directed, typename N, typename W>
std::vector<std::unordered_map<N, W>> edges2neighsets(const std::vector<std::tuple<N, N, W>>& edges, N n)
{
	std::vector<std::unordered_set<N>> neighs(n);
	for (const auto& edge : edges) {
		auto a = std::get<0>(edge);
		auto b = std::get<1>(edge);
		auto w = std::get<2>(edge);
		neighs[a].insert({b, w});
		if (Directed)
			neighs[b].insert({a, w});
	}
	return neighs;
}


/*
 * 重み無し無向グラフの隣接集合表現を受け取り、深さ優先探索してノードをポストオーダーで列挙して関数を呼ぶ
 */
template<typename N, typename F>
void graph_depthfirst_postorder_call(const std::vector<std::unordered_set<N>>& neighs, N n, const F& fn, N start = 0);

template<typename N, typename F>
void graph_depthfirst_postorder_call_impl(std::vector<char>& arrived, const std::vector<std::unordered_set<N>>& neighs, N cur, const F& fn)
{
	for (auto neigh : neighs[cur]) {
		if (arrived[neigh])
			continue;
		arrived[neigh] = 1;
		graph_depthfirst_postorder_call_impl(arrived, neighs, neigh, fn);
	}
	fn(cur);
}

template<typename N, typename F>
void graph_depthfirst_postorder_call(const std::vector<std::unordered_set<N>>& neighs, N n, const F& fn, N start /* = 0 */)
{
	std::vector<char> arrived(n);
	arrived[start] = 1;
	graph_depthfirst_postorder_call_impl(arrived, neighs, start, fn);
}


/*
 * 重み無し無向グラフの隣接集合表現を受け取り、深さ優先探索してノードをポストオーダーで列挙して返す
 */
template<typename N>
std::vector<N> graph_depthfirst_postorder_enum(const std::vector<std::unordered_set<N>>& neighs, N n, N start = 0)
{
	std::vector<N> nodes(n);
	size_t num = 0;
	graph_depthfirst_postorder_call(neighs, n, [&nodes, &num](N node){
		nodes[num++] = node;
	}, start);
	return nodes;
}


int main()
{
	int N, M;
	std::vector<std::pair<int, int>> E;

	std::cin >> N >> M;
	E.resize(M);
	for (auto& e : E) {
		std::cin >> e.first >> e.second;
		--e.first;
		--e.second;
	}

	if (M % 2 == 1) {
		std::cout << "-1\n";
		return 0;
	}

	auto neighs = edges2neighsets<false>(E, N);
	auto nodes = graph_depthfirst_postorder_enum(neighs, N);

	std::vector<char> parity(N);
	for (auto node : nodes) {
		for (auto neigh : neighs[node]) {
			if (parity[node]) {
				std::cout << (node + 1) << " " << (neigh + 1) << "\n";
				parity[node] = 0;
			} else {
				std::cout << (neigh + 1) << " " << (node + 1) << "\n";
				parity[neigh] ^= 1;
			}
			neighs[neigh].erase(node);
		}
	}
}

