void dfs(int cur, vector<vector<int>> &g, vector<bool> &used, set<pair<int, int>> &edges) {

  used[cur] = true;
  for (auto nxt : g[cur]) {
    if (used[nxt]) continue;

    edges.insert({min(cur, nxt), max(cur, nxt)});
    dfs(nxt, g, used, edges);
  }
}

void dfs2(int cur, int par, vector<vector<int>> &tree, vector<int> &deg, vector<pair<int, int>> &ans) {

  for (auto nxt : tree[cur]) {
    if (nxt == par) continue;
    dfs2(nxt, cur, tree, deg, ans);
  }

  if (deg[cur] % 2 == 0) {
    if (par == -1) return;
    ans.push_back({par + 1, cur + 1});
    deg[par]++;
  } else {
    ans.push_back({cur + 1, par + 1});
  }

}

