bool dfs (int u, int p ) {
  bool id = s[u] == '1' ? 1 : 0;
  for (int v : g[u]) {
    if (v == p) continue;
    bool k = dfs(v, u);
    if (k == 0) continue;
    else if (id){
      used.erase({u, v});
      used.insert({v, u});
      id = 0;
    }
  }
  return id;
}

