void solve() {
    i64 N = RD();
    i64 M = RD();

    if(M%2 != 0) {
        PRINTLN(-1);
        return;
    }

    vector<vector<i64>> G(N);
    REP(_, M) {
        i64 a = RD1();
        i64 b = RD1();
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    enum State { UNVISITED, VISITING, VISITED };
    vector<State> states(N, UNVISITED);
    auto ans = vec_reserve<pair<i64,i64>>(M);
    auto dfs = FIX([&](auto&& self, i64 v, i64 p) -> i64 {
        states[v] = VISITING;

        i64 out = 0;
        for(i64 to : G[v]) {
            if(to == p) continue;
            if(states[to] == VISITED) continue;

            if(states[to] == UNVISITED) {
                out += self(to, v);
            }
            else if(states[to] == VISITING) {
                ans.emplace_back(v, to);
                ++out;
            }
            else { ASSERT(false); }
        }

        states[v] = VISITED;
        if(p == -1) return -1;

        if(out%2 == 0) {
            ans.emplace_back(p, v);
            return 1;
        }
        else {
            ans.emplace_back(v, p);
            return 0;
        }
    });
    dfs(0, -1);

    // 1-based
    for(auto& e : ans) {
        ++e.first;
        ++e.second;
    }
    ALL(for_each, ans, LIFT(PRINTLN));
}

signed main() {


    solve();

    return 0;
}

