        else {
          ans.push_back({i, tmp[j]});
          num[i] = !num[i];
        }
        edge[tmp[j]].erase(i);
        edge[i].erase(tmp[j]);
        if(edge[tmp[j]].size() == 1) qu.push(tmp[j]);
      }
      if(!bfs()) break;
    }
