}

bool bfs() {
  while(!qu.empty()) {
    int now = qu.front();
    qu.pop();
    if(edge[now].size() == 0) {
      if(num[now]) {
        ans.erase(ans.begin(), ans.end());
        return 0;
      }
      continue;
    }
    vector<int> tmp;
    for(auto to : edge[now]) tmp.push_back(to);
    int tsize = tmp.size();
    for(int j = 0; j < tsize; ++j) {
      int to = tmp[j];
      if(num[now]) {
        ans.push_back({now, to});
        num[now] = 0;
      }
      else {
        ans.push_back({to, now});
        num[to] = !num[to];
      }
      edge[now].erase(to);
      edge[to].erase(now);
      if(edge[to].size() == 1) qu.push(to);
    }
  }
  return 1;
}

