typedef pair<ll, ll> P;
vec d;
struct edge {
    ll from, to, cost, id, dir;
};
vector<vector<edge>> graph;

void dijkstra (ll s, ll V) {
    priority_queue<P, vector<P>, greater<P>> que;
    d.assign(V, inf);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        ll v = p.second;
        if (d[v] < p.first) continue;
        for (edge e : graph[v]) {
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

vec depth;
void dfs (ll v, ll from) {
    for (auto nv : graph[v]) {
        if (nv.to == from) continue;
        if (depth[nv.to] != -1) continue;
        depth[nv.to] = depth[v] + 1;
        dfs(nv.to, v);
    }
}

