vector<pair<int, int>> ans;
void addAns(int a, int b, int c) {
	ans.emplace_back(b, a);
	ans.emplace_back(b, c);
}

void dfs(int v, int p, int d)
{
	depth[v] = d;
	int with = 0;

	for (int u : neigh[v]) {
		if (u == p) continue;

		else if (depth[u] == 0) {
			// front edge forward
			dfs(u, v, d + 1);

			if (debt[u]) {
				if (with) {
					addAns(with, v, u);
					with = 0;
				}
				else {
					with = u;
				}
			}
		}
		else if (depth[u] > depth[v]) {
			continue;
		}
		else {
			if (with) {
				addAns(with, v, u);
				with = 0;
			}
			else {
				with = u;
			}
		}
	}

	if (with) {
		addAns(with, v, p);
	}
	else {
		debt[v] = true;
	}
}

