  union_find uf(n);
  VVI graph(n);
  VI out(n);
  rep(m) {
    int u = IN, v = IN;
    u--; v--;
    if (uf.same(u, v)) {
      OUT(u+1, v+1);
      out[u] ^= 1;
    } else {
      graph[u].push_back(v);
      graph[v].push_back(u);
      uf.merge(u, v);
    }
  }
  fix([&](auto f, auto v, auto par)->int{
    int o = out[v];
    for (auto next : graph[v]) if (next != par) o ^= f(next, v);
    if (par != -1) {
      if (o) OUT(v+1, par+1);
      else OUT(par+1, v+1);
    }
    return !o;
  })(0, -1);
}

