            gh.ed[nowl.second].ju = !gh.ed[nowl.second].ju;
            gh.co[nowl.first] = !gh.co[nowl.first];
            gh.co[now] = !gh.co[now];
        }
        dfs(gh, nowl.first, now, nowl.second);
    }
    if (gh.co[now]){
        gh.co[now] = !gh.co[now];
        gh.co[fo] = !gh.co[fo];
        gh.ed[k].ju = !gh.ed[k].ju;
    }
    return;
}


