    g[a[i]].push_back(b[i]);
    g[b[i]].push_back(a[i]);
  }
  if (m & 1) {
    printf("-1\n");
    return 0;
  }


  vi topo;
  deque<int> que = {0};
  vector<bool> arrived(n, false);
  arrived[0] = true;
  topo.push_back(0);
  while (!que.empty()) {
    int u = que.front();
    que.pop_front();
    for (int v : g[u]) {
      if (arrived[v]) {
        continue;
      }
      arrived[v] = true;
      que.push_back(v);
      topo.push_back(v);
    }
  }
  //debug(topo);
  vi topo_rev(n);
  rep (i, n) {
    topo_rev[topo[i]] = i;
  }
  //debug(topo_rev);
  vvi ge(n);
  rep (i, m) {
    int u = a[i];
    int v = b[i];
    if (topo_rev[u] > topo_rev[v]) {
      swap(u, v);
    }
    ge[u].push_back(v);
  }
  //debug(ge);

  vector<bool> is_odd(n, false);
  vvi edges;
  for (int i = n-1; i >= 0; --i) {
    int u = topo[i];
    int cnt_to = 0;
    int cnt_from = 0;
    for (int v : ge[u]) {
      if (is_odd[v]) {
        edges.push_back(vi{v, u});
        is_odd[v] = false;
        cnt_from += 1;
      } else {
        edges.push_back(vi{u, v});
        cnt_to += 1;
      }
    }
    if (cnt_to & 1) {
      is_odd[u] = true;
    }
  }

  for (auto && edge : edges) {
