int main(){
  ll n,m;
  cin>>n>>m;
  for(int i=0;i<=n;i++) used[i]=false;
  for(int i=0;i<m;i++){
    int a,b;
    cin>>a>>b;
    node[a].push_back(b);
    node[b].push_back(a);
    cnt[a]++;
    cnt[b]++;
  }
  if(m%2==1){
    cout<<-1<<endl;
    return 0;
  }
  priority_queue<P,vector<P>,greater<P>> pque;
  for(int i=1;i<=n;i++){
    pque.push(P(cnt[i],i));
  }
  vector<P> ans;
  while(!pque.empty()){
    P p=pque.top();
    pque.pop();
    ll pos=p.second;
