    //cout<<"P:"<<pos<<endl;
    used[pos]=true;
    bool f=false;
    for(int i=0;i<node[pos].size();i++){
      ll to=node[pos][i];
      if(!used[to]){
        cnt[to]--;
        if(!f&&cn2[pos]%2==1){
          ans.push_back(P(pos,to));
          pque.push(P(cnt[to],to));
        }
        else{
          ans.push_back(P(to,pos));
          pque.push(P(cnt[to],to));
          cn2[to]++;
        }
        f=true;
      }
    }
  }

