vector<pair<int, int> > ans;
int o[100005];

void dfs(int pos) {
  visited[pos] = true;
  for (int i = 0; i < graph[pos].size(); i++) {
    Edge& n = graph[pos][i];
    if (!visited[n.to]) {
      if (o[pos] % 2 == 1) {
        n.direction = 2;
        o[pos]++;
        ans.emplace_back(pos+1, n.to+1);
      } else {
        n.direction = 1;
        ans.emplace_back(n.to+1, pos+1);
        o[n.to]++;
      }
    }
  }
  if (o[pos] % 2 == 1) {
    ok = false;
  }
  for (int i = 0; i < graph[pos].size(); i++) {
    Edge n = graph[pos][i];
    if (!visited[n.to]) {
      dfs(n.to);
    }
  }
}

