	int to, rev_i, dir; // 1 -> 0
};

using EdgeVec = std::vector<Edge>;
using EdgeLists = std::vector<EdgeVec>;

int N, M;
EdgeLists edges;
std::vector<bool> visited;

void dfs(int, int, int);
bool solve();

int main()
{
	if (!solve())
	{
		puts("-1");
		return 0;
	}
	for (int i{}; i < N; i++)
		for (auto& f: edges[i])
		{
			if (f.to < i) continue;
			if (f.dir == 1) printf("%d %d\n", i + 1, f.to + 1);
			else printf("%d %d\n", f.to + 1, i + 1);
		}

	return 0;
}

bool solve()
{
	scanf("%d%d", &N, &M);
	edges.resize(N);
	for (int i{}; i < M; i++)
	{
		int A, B;
		scanf("%d%d", &A, &B);
		A--; B--;
		edges[A].push_back({B, (int)edges[B].size(), -1});
		edges[B].push_back({A, (int)edges[A].size() - 1, -1});
	}
	if (M % 2 == 1) return false;
	visited.resize(N);
	dfs(0, -1, -1);
	return true;
}

void dfs(int index, int parent, int edge_index)
{
	if (visited[index]) return;
	visited[index] = true;
	for (int i{}; i < (int)edges[index].size(); i++)
		dfs(edges[index][i].to, index, i);

	int in_count{};
	for (auto& e: edges[index])
		if (e.dir == 1)
			in_count++;
	// outの数が偶数になるように調整したい
	if (parent == -1) return;
	if (((int)edges[index].size() - in_count) % 2)
	{
		edges[parent][edge_index].dir = 0;
		edges[index][edges[parent][edge_index].rev_i].dir = 1;
		in_count++;
	}
	for (auto& e: edges[index])
	{
		if (e.dir != -1) continue;
		e.dir = 0;
		edges[e.to][e.rev_i].dir = 1;
	}
}

