const int N = 1e5+1;
int p[N], n, m;
void init()
{
  for (int i = 1; i <= n; ++i) p[i] = i;
}
int pa(int x)
{
  return x==p[x]?x:p[x]=pa(p[x]);
}
bool merge(int x, int y)
{
  x = pa(x), y = pa(y);
  if (x != y)
    {
      p[x] = y;
      return true;
    }
  return false;
}
vector<int> g[N];
int cnt[N];
void answer(int u, int v)
{
  ++cnt[u];
  printf("%d %d\n", u, v);
}
void dfs(int cur, int p)
{
  for (auto nxt : g[cur])
    if (nxt != p)
      dfs(nxt, cur);
  if (cnt[cur]%2 == 1)
    {
      assert(p);
      answer(cur, p);
    }
  else
    {
      if (p) answer(p, cur);
    }
}

int main()
{
  scanf("%d %d", &n, &m);
  init();
  for (int i = 1; i <= m; ++i)
    {
      int u, v; scanf("%d %d", &u, &v);
      if (merge(u, v)) g[u].pb(v), g[v].pb(u);
      else answer(u, v);
    }
  if (m % 2 == 1)
    {
      puts("-1");
      return 0;
    }
  dfs(1, 0);
}

