#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = (int)(n) - 1; (i) >= 0; -- (i))
#define REP3R(i, m, n) for (int i = (int)(n) - 1; (i) >= (int)(m); -- (i))
#define ALL(x) begin(x), end(x)
using namespace std;

vector<pair<int, int> > solve(int n, int m, const vector<vector<int> > & g) {
    // tree expansion
    vector<int> unexpand;
    vector<int> parent;
    unordered_set<int64_t> used;
    function<void (int)> expand = [&](int i) {
        int a = unexpand[i];
        for (int b : g[a]) {
            int64_t e = max<int64_t>(a, b) * n + min<int64_t>(a, b);
            if (not used.count(e)) {
                used.insert(e);
                int j = unexpand.size();
                unexpand.push_back(b);
                parent.push_back(i);
                expand(j);
            }
        }
    };
    constexpr int unexpand_root = 0;
    constexpr int root = 0;
    unexpand.push_back(unexpand_root);
    parent.push_back(-1);
    expand(root);
    assert (unexpand.size() == m + 1);
    assert (parent.size() == m + 1);

    // decide from leaves
    vector<pair<int, int> > edges;
    vector<int> outdegree(m + 1);
    REP3R (i, 1, m + 1) {
        if (outdegree[i] % 2 == 0) {
            ++ outdegree[parent[i]];
            edges.emplace_back(unexpand[parent[i]], unexpand[i]);
        } else {
            ++ outdegree[i];
            edges.emplace_back(unexpand[i], unexpand[parent[i]]);
        }
    }
    if (outdegree[root] % 2 == 1) {
        edges.clear();
    }
    assert (edges.empty() == (m % 2 == 1));
    return edges;
}

int main() {
    int n, m; cin >> n >> m;
    vector<vector<int> > g(n);
    REP (i, m) {
        int a, b; cin >> a >> b;
        -- a; -- b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    auto edges = solve(n, m, g);
    if (edges.empty()) {
        cout << -1 << endl;
    } else {
        for (auto e : edges) {
            cout << e.first + 1 << ' ' << e.second + 1 << endl;
        }
    }
    return 0;
}

