void bfs(int v){
	vis.reset();
	mem(par,-1);
	queue<int>q;q.push(v);
	par[v]=-1;
	vis[v]=true;
	while(!q.empty()){
		int e=q.front();		
		q.pop();
		if(odd.count(e)){
			odd.erase(e);
			while(par[e]!=-1){
				rev(e,par[e]);
				e=par[e];
			}
			return;
		}
		for(auto f:g[v]){
			if(vis[f])continue;
			vis[f]=true;
			par[f]=e;
			q.push(f);
		}
	}
}

