int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n, m;
  cin >> n >> m;

  vector<vector<Edge>> graph(n);
  vector<Edge> edges;
  vector<int> is_actives(2 * m);
  vector<int> out_degrees(n);
  for (int i = 0; i < m; i++) {
    int v1, v2;
    cin >> v1 >> v2;
    v1--; v2--;
    Edge e1({v1, v2, 2 * i, 2 * i + 1});
    Edge e2({v2, v1, 2 * i + 1, 2 * i});
    graph[v1].push_back(e1);
    graph[v2].push_back(e2);
    edges.push_back(e1);
    edges.push_back(e2);
    is_actives[2 * i] = true;
    out_degrees[v1]++;
  }

  if (m % 2 == 1) {
    cout << -1 << endl;
    return 0;
  }

  vector<int> visited(n, 0);
  vector<int> used_edges(n, -1);
  function<int(int, int, int)> dfs =
      function<int(int, int, int)>([&] (int s, int v, int parent) {
        visited[v] = 1;
        if (v != s && out_degrees[v] % 2 == 1) {
          return v;
        }

        for (const auto& edge : graph[v]) {
          if (is_actives[edge.id]) {
            if (edge.to == parent) continue;
            if (visited[edge.to]) continue;
            used_edges[edge.to] = edge.id;
            int dfs_value = dfs(s, edge.to, v);
            if (dfs_value >= 0) return dfs_value;
          }
        }

        return -1;
      });

  for (int s = 0; s < n; s++) {
    if (out_degrees[s] % 2 == 1) {
      int t = dfs(s, s, -1);
      int cur = t;
      while (cur != s) {
        Edge used_edge = edges[used_edges[cur]];
        is_actives[used_edge.id] = false;
        is_actives[used_edge.reverse_id] = true;
        out_degrees[used_edge.from]--;
        out_degrees[used_edge.to]++;

        cur = used_edge.from;
      }
    }
  }

  for (int i = 0; i < 2 * m; i++) {
    if (is_actives[i]) {
      cout << edges[i].from + 1 << " " << edges[i].to + 1 << endl;
    }
  }
}

