        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if(m % 2 == 1){
        cout << -1 << endl;
        return 0;
    }

    depth[0] = 0;
    DFS(0,-1);

    for(auto x : ans){
        cout << x.first + 1 << " " << x.second + 1 << endl;
    }
    return 0;
}

