int dfs(auto& G, auto& vis, int v, int p) {
    vis[v] = true;
    int sum = 0;
    for (auto &e : G[v]) {
        if (e.to == p) continue;
        if (!vis[e.to]) {
            e.direction = dfs(G, vis, e.to, v);
            G[e.to][e.rev].direction = e.direction ^ 1;
