// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

template <class T>
struct fix_point: private T {
  explicit constexpr fix_point(T &&func): T(std::forward<T>(func)) { }
  template <class... Args>
  constexpr decltype(auto) operator () (Args &&... args) const {
    return T::operator()(*this, std::forward<Args>(args)...);
  }
};

template <class T>
constexpr decltype(auto) make_fix_point(T &&func) {
  return fix_point<T>(std::forward<T>(func));
}

int main() {
  int N, M;
  std::cin >> N >> M;
  if (M % 2 == 1) {
    std::cout << "-1\n";
    return 0;
  }
  std::vector<std::vector<int>> graph(N);
  for (int i: range(0, M)) {
    int a, b;
    std::cin >> a >> b;
    --a; --b;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }
  std::map<std::pair<int, int>, bool> state;
  std::vector<bool> visited(N);
  std::stack<std::pair<int, int>> stack;
  make_fix_point([&](auto dfs, int u, int p) -> void {
    visited[u] = true;
    if (p != -1) {
      stack.push({ u, p });
    }
    for (int v: graph[u]) {
      if (v != p) {
        if (visited[v]) {
          state[std::minmax(u, v)] = (u < v);
        }
        else {
          dfs(v, u);
        }
      }
    }
  })(0, -1);
  while (!stack.empty()) {
    int u = stack.top().first;
    int p = stack.top().second;
    bool odd = false;
    for (int v: graph[u]) {
      if (v != p) {
        odd ^= state[std::minmax(u, v)] ^ (u < v);
      }
    }
    state[std::minmax(u, p)] = odd ^ (u < p);
    stack.pop();
  }
  for (auto p: state) {
    int u = p.first.first;
    int v = p.first.second;
    if (p.second) {
      std::swap(v, u);
    }
    std::cout << u + 1 << ' ' << v + 1 << '\n';
  }
  return 0;
}

