				cnt[edge.first]++;
				nokori[now]--;
				nokori[edge.first]--;
			}

			q.push(edge.first);
		}
	}

	bool check = true;
	for (auto c : cnt)
		if (c % 2 == 1)
			check = false;

	if (ans.size() != M || check == false) {
		return 1;
		cout << -1 << endl;
	} else {
		for (auto edge : ans)
			cout << edge.first << " " << edge.second << endl;
	}

	return 0;
}

