void init(int n)
{
    for(int i=1;i<=n;i++)
    {
        p[i]=i;
        r[i]=0;
    }
}
int find(int x)
{
    if(p[x]==x) return x;
    else return p[x]=find(p[x]);
}
void unite(int x,int y)
{
    x=find(x);
    y=find(y);
    if(x==y) return;
    if(r[x]<r[y]) p[x]=y;
    else
    {
        p[y]=x;
        if(r[x]==r[y]) r[x]++;
    }
}
bool same(int x,int y)
{
    return find(x)==find(y);
}
void add_edge(int u,int v)
{
    G[u].push_back(v);
    G[v].push_back(u);
}
struct node
{
    int x,y,z;
};
vector<node> ans;
int dfs(int v,int p)
{
    int last=0;
    for(auto to:G[v])
    {
        if(to==p) continue;
        int ret=dfs(to,v);
        if(ret==0)
        {
            if(last==0) last=to;
            else
            {
                ans.push_back((node){last,v,to});
                last=0;
            }
        }
        else ans.push_back((node){ret,to,v});
    }
    return last;
}
