bool dfs(int v,int p){
	if(vis[v]==1)return false;
	if(vis[v]==2)return true;
	vis[v]=1;
	int a=-1;
	for(auto to:g[v]){
		if(dfs(to,v)){
			if(a==-1){
				a=to;
			}else{
				ans(v,a);
				ans(v,to);
				a=-1;
			}
		}
	}
	vis[v]=2;
	if(a==-1)return true;
	ans(v,p);
	ans(v,a);
	return false;
}

