#include<bits/stdc++.h>
using namespace std;
#define int long long 

signed main(void){

  int N,M; cin >> N >> M;

  if( M % 2 == 1 ){ cout << "-1" << endl; return 0;}

  vector<vector<int>> to(M);

  for(int i = 0; i < M; i++){ 
    int a,b; cin >> a >> b;
    a--; b--;
    to[a].push_back(b);
    to[b].push_back(a);
  }

  vector<pair<int,int>> depth(N);
  for(int i = 0; i < N; i++){ 
    depth[i] = {-1,i};
  }
  depth[0] = {0,0};

  queue<int> Q; Q.push(0);

  while(!Q.empty()){ 

    int p = Q.front(); Q.pop();

    for(auto q : to[p]){ 
      if( depth[q].first != -1 ){ continue;}

      depth[q].first = depth[p].first+1;

      Q.push(q);

    }
  }

  sort(depth.rbegin(),depth.rend()); //深い順にソートする

  vector<bool> used(N,false);
  vector<bool> even(N,true);

  //depthが深いから決めていく

  set<pair<int,int>> ans;

  for(int i = 0; i < N; i++){ 

    int p = depth[i].second;

    for(auto q : to[p]){
      if( used[q] ){ continue; } //全て埋めてしまった点については何も見ない

      if( even[p] ){ // qからpに辺をはる
        even[q] = !even[q];
        ans.insert({q,p});
      }
      else{ //pからqに辺をはる
        even[p] = true;
        ans.insert({p,q});
      }
    }

    used[p] = true;
  }

  for(auto ne : ans ){ 
    cout << ne.first+1 << " " << ne.second+1 << endl;
  }

  return 0;
}

