void dfs1(int v, int p) {
  use[v] = true;
  REP(i, g[v].size()) {
    int to = g[v][i];
    if (to == p) continue;
    if (!use[to]) {
      dfs1(to, v);
    } else if (v < to) {
      ans.push_back(P(v, to));
      out[v]++;
    }
  }
}

void dfs2(int v, int p) {
  use[v] = true;
  REP(i, g[v].size()) {
    int to = g[v][i];
    if (to == p) continue;
    if (!use[to]) {
      dfs2(to, v);
    }
  }
  if (p != -1) {
    if (out[v] % 2) {
      ans.push_back(P(v, p));
      out[v]++;
    } else {
      ans.push_back(P(p, v));
      out[p]++;
    }
  }
}

