		G[a].push_back((edge){b,(int)G[b].size(),-1});
		G[b].push_back((edge){a,(int)G[a].size()-1,-1});
	}
	int id=0;
	for(int i=1;i<N;i++)
	{
		if(cnt[id]>cnt[i])id=i;
	}
	vector<int>used(N,0);
	queue<int>P;
	P.push(id);
	used[id]=1;
	while(!P.empty())
	{
		int u=P.front();P.pop();
		int pre=-1;
		for(int i=0;i<G[u].size();i++)
		{
			if(G[u][i].F!=-1)continue;
			if(pre<0)
			{
				pre=i;
			}
			else
			{
				G[u][pre].F=G[u][i].F=1;
				G[G[u][pre].to][G[u][pre].rev].F=0;
				G[G[u][i].to][G[u][i].rev].F=0;
				pre=-1;
			}
			if(used[G[u][i].to]==0)
			{
				used[G[u][i].to]=1;
				P.push(G[u][i].to);
			}
		}
	}
	for(int i=0;i<N;i++)
	{
		for(edge&e:G[i])
		{
			if(e.F==1)cout<<i+1<<" "<<e.to+1<<endl;
		}
	}
}

