int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    vector<vi> adj(n);

    for (int i = 0; i < m; ++i){
        int u, v; cin >> u >> v;
        u--; v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> vis(n);
    vector<pii> ans;
    set<pii> seen;
    vector<int> deg(n);
    vector<pii> tree;

    auto check = [&](int a, int b){
        if (a > b) swap(a, b);
        if (seen.find(pii(a, b)) == seen.end()){
            seen.insert(pii(a, b));
            return true;
        } else {
            return false;
        }
    };

    function<void(int,int)> dfs = [&](int s, int p){
        vis[s] = true;

        for (auto u : adj[s]){
            if (u == p) continue;

            if (vis[u]){
                if (check(s, u)){
                    ans.push_back({s, u});
                    deg[s] ^= 1;
                }
            } else {
                dfs(u, s);
            }
        }


        if (p != -1){
            deg[s] ^= 1;
            tree.push_back(pii(s, p));
        }
    };

    dfs(0, -1);

    for (auto e : tree){
        if (deg[e.first]){
            deg[e.first] ^= 1;
            deg[e.second] ^= 1;
            swap(e.first, e.second);
        }

        ans.push_back(e);
