using namespace std;

struct node {
	int parent;
	int cost;
};

class union_find_tree {
public:
	int n;
	vector<node> pv;
	vector<int> hight;

	union_find_tree(int sz) {
		n = sz;
		for (int i = 0; i < n; ++i) {
			pv.push_back({ i,0 });
			hight.push_back(0);
		}
	}

	int find_root(int x) {
		if (pv[x].parent == x)return x;
		else return pv[x].parent = find_root(pv[x].parent);
	}

	void unite(int x, int y) {
		x = find_root(x);
		y = find_root(y);
		if (x == y) {
			pv[x].cost++;
			return;
		}
		if (hight[x] < hight[y]) {
			pv[x].parent = y;
			pv[y].cost += pv[x].cost + 1;
			pv[x].cost = 0;
		}
		else {
			pv[y].parent = x;
			pv[x].cost += pv[y].cost + 1;
			pv[y].cost = 0;
			if (hight[x] == hight[y])++hight[x];
		}
	}

	bool same(int x, int y) {
		return find_root(x) == find_root(y);
	}

	int get_val(int x) {
		int r = find_root(x);
		return pv[r].cost;
	}
};

signed main() {
