int buttle(ll a,ll b,ll aa,ll bb){
	ll ab = max(1LL,a / bb);
	ll aab = max(1LL,aa / b);
	if (ab == aab) {
		ll ar = a - ab * bb;
		ll aar = aa - aab * b;
		if (ar > 0 && aar > 0) return 0;
		if (ar <= 0 && aar <= 0) return 0;
		if (ar <= 0) return -1;
		if (aar <= 0) return 1;
	}

	if (ab > aab) {
		return 1;
	}
	else if (ab < aab)
		return -1;
	else return 0;

}
