{
  bool odd = false;
  ll nokori = 0;
  set<ll> rin;
};

int main(int argc, char const *argv[])
{
  ll n, m;
  cin >> n >> m;
  vector<ll> a(m), b(m);
  vector<vector<ll>> edge(n, vector<ll>(0));
  vector<node> v(n);
  ll muko = m;
  REP(i, m)
  {
    cin >> a[i] >> b[i];
    a[i]--;
    b[i]--;
    v[a[i]].nokori++;
    v[a[i]].nokori++;
    v[a[i]].rin.insert(b[i]);
    v[b[i]].rin.insert(a[i]);
  }
  if (m % 2 == 1)
  {
    cout << -1 << endl;
    return 0;
  }
  REP(i, n)
  {
    if (v[i].nokori == 1)
    {
      v[i].nokori == 0;
      ll tmp = *v[i].rin.begin();
      v[i].rin.erase(tmp);
      v[tmp].nokori--;
      v[tmp].rin.erase(i);
      v[tmp].odd = !v[tmp].odd;
      edge[tmp].push_back(i);
      muko--;
    }
  }
  priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> pqNode;
  REP(i, n)
  {
    pqNode.push({v[i].nokori, i});
  }
  while (muko > 0)
  {
    pair<ll, ll> t = pqNode.top();
    node *top = &v[t.second];
    if ((*top).nokori == 0)
    {
      pqNode.pop();
      continue;
    }
    for (auto e : (*top).rin)
    {
      node *pea = &v[e];
      if ((*top).odd || (*top).nokori % 2 == 0)
      {
        (*top).odd = !(*top).odd;
        edge[t.second].push_back(e);
      }
      else
      {
        (*pea).odd = !(*pea).odd;
        edge[e].push_back(t.second);
      }
      (*pea).rin.erase(t.second);
      (*top).nokori--;
      (*pea).nokori--;
      muko--;
      pqNode.pop();
      pqNode.push({(*pea).nokori, e});
    }
    (*top).rin.clear();
    //    sort(ALL(syou));
  }
  REP(i, n)
  {
    if (v[i].odd)
    {
      cout << -1 << endl;
      return 0;
    }
  }
  // output
  REP(i, n)
  {
    for (auto e : edge[i])
    {
      cout << i + 1 << " " << e + 1 << endl;
    }
  }
  return 0;
}

