int n,m,vis[MAXN];
struct node{
	int rt,cnt;
	vector<int>P,T;
	bool operator < (const node &a)const{
		if(this->cnt%2==a.cnt%2)
			return this->cnt<a.cnt;
		return (this->cnt%2)>(a.cnt%2);
	}
}s[MAXN];
priority_queue<node>Q;
struct tree{int x,y;}w[MAXN];
void bfs(){
	while(!Q.empty())Q.pop();
	for(int i=1;i<=n;i++)
		Q.push(s[i]);
	while(!Q.empty()){
		node u=Q.top();Q.pop();
		int size=u.P.size();
		int first=0;
		if(u.cnt%2){
			for(;first<size;first++)
				if(!vis[u.T[first]])
					break;
			int v=u.P[first];
			int id=u.T[first];
			u.cnt--;
			vis[id]=u.rt;
			s[v].cnt--;
		}
		for(int i=0;i<size;i++){
			int v=u.P[i];
			int id=u.T[i];
			if(!vis[id]){
				u.cnt--;
				vis[id]=v;
				s[v].cnt--;
			}
		}

	}
}
