{
    int need = n + 1;
    int res = 0;
    for (int i = 1; i <= n; i++) {
        int num = 1, den = 1;
        for (int j = 1; j <= n; j++) {
            if (i == j) continue;
            num *= (need - j);
            den *= (i - j);
        }
        res += get(i) * num / den;
    }
    return res;
