using lint = long long;

struct RandNum {

	mt19937 mt;
	RandNum() : mt(chrono::steady_clock::now().time_since_epoch().count()) {}

	lint operator()(lint a, lint b) {
		uniform_int_distribution<lint> dist(a, b);
		return dist(mt);
	}
	lint operator() (lint b) { return (*this)(0LL, b); }

	template<class Ite>
	void shuf(Ite first, Ite last) { shuffle(first, last, mt); }

};

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;

	if (M % 2 == 1) {
		cout << -1 << "\n";
		return 0;
	}

	int u, v;
	map<pair<int,int>, int> dir;
	vector<vector<int>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		u--, v--;
		edge[u].emplace_back(v);
		edge[v].emplace_back(u);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	stack<int> que;
	RandNum ran;
	for (int i = 0; i < N; i++) {
		if (out[i] == 1) {
			que.emplace(i);
		}
	}

	while (!que.empty()) {

		int now = que.top();
		que.pop();
		if (out[now] == 0) continue;

		bool random = true;
		for (const auto &e : edge[now]) {
			if (out[e] == 1) {
				dir[{min(now, e), max(now, e)}] *= -1;
				out[now] ^= 1;
				out[e] ^= 1;
				random = false;
				break;
			}
		}

		if (random) {
			int next = edge[now][ran(edge[now].size() - 1)];
			dir[{min(now, next), max(now, next)}] *= -1;
			out[now] ^= 1;
			out[next] ^= 1;
			que.emplace(next);
		}

	}

	for (auto &e : dir) {
		if(e.second == 1) printf("%d %d\n", e.first.first + 1, e.first.second);
		else printf("%d %d\n", e.first.second + 1, e.first.first);
	}

	return 0;
}

