const int N = 100 * 1000 + 13;

int n, m;
vector<int> g[N];

bool read () {
	if (scanf("%d%d", &n, &m) != 2)
		return false;
	forn(i, n)
		g[i].clear();
	forn(i, m){
		int v, u;
		scanf("%d%d", &v, &u);
		--v, --u;
		g[v].pb(u);
		g[u].pb(v);
	}
	return true;
}

int used[N];
vector<pair<int, pt>> ans;
vector<int> q[N];

void dfs(int v, int p) {
	used[v] = 1;
	for (int to : g[v]) {
		if (to == p) continue;
		if (used[to] == 1) q[v].pb(to);
		else if (used[to] == 0) dfs(to, v);
	}
	while (sz(q[v]) > 1) {
		int u1 = q[v].back();
		q[v].pop_back();
		int u2 = q[v].back();
		q[v].pop_back();
		ans.pb(mp(u1, mp(v, u2)));
	}
	if (sz(q[v]) == 1 && p != -1) {
		ans.pb(mp(p, mp(v, q[v].back())));
	} else if (p != -1) {
		q[p].pb(v);
	}	
	used[v] = 2;
}

void solve() {
    if (m % 2) {
        printf("-1\n");
        return;
    }
	ans.clear();
	memset(used, 0, sizeof(used));
	forn(i, n) q[i].clear();
	forn(i, n) if (used[i] == 0)
		dfs(i, -1);
    if (sz(ans) != m / 2) {
        printf("-1\n");
        return;
    }
	forn(i, sz(ans)) {
        printf("%d %d\n", ans[i].y.x + 1, ans[i].x + 1);
        printf("%d %d\n", ans[i].y.x + 1, ans[i].y.y + 1);
    }
}

