    E.emplace_back(u, v);
    ++c[v];
  }

  LinearSystemIncidence<ll> LSI(n, E);
  auto sol = LSI.solve(c);

  if (sol.first) {
    rep(i, m) {
      if (sol.second[i] == 0) swap(E[i].first, E[i].second);
      ++E[i].first;
      ++E[i].second;
    }
    rep(i, m) cout << E[i].first << " " << E[i].second << "\n";
  }
  else cout << -1 << "\n";
  return 0;
}

