#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

struct Vertex
{
    vector<ll> n;
    ll m = 0;
};

ll N, M;
Vertex V[100005];
pll A[100005];
pll E[100005];
bool U[100005];

bool solve()
{
    if (M % 2 == 1)
        return false;

#if true
    //sort(V, V + N, [](Vertex a, Vertex b) { return (ll)a.n.size() < (ll)b.n.size(); });
    queue<ll> q;
    REP(i, N)
    {
        if (V[i].n.size() % 2 == 1)
        {
            REP(j, V[i].n.size())
            {
                ll n = V[i].n[j];
                if (V[n].n.size() % 2 == 0)
                    q.push(n);
            }
        }
    }
    ll m = 0;
    if (q.empty())
    {
        ll min = 0;
        REP(i, N)
        {
            if (V[min].n.size() > V[i].n.size())
                min = i;
        }
        REP(i, V[min].n.size())
        {
            ll n = V[min].n[i];
            A[m++] = pll(n + 1, min + 1);
            V[n].m++;
            q.push(n);
        }
        U[min] = true;
    }

    while (!q.empty())
    {
        ll t = q.front();
        q.pop();
        if (U[t])
            continue;
        if ((V[t].n.size() - V[t].m) % 2 == 1 || (V[t].n.size() - V[t].m) <= 0)
            continue;

        REP(i, V[t].n.size())
        {
            ll n = V[t].n[i];
            if (U[n])
                continue;
            A[m++] = pll(t + 1, n + 1);
            V[n].m++;
            if ((V[n].n.size() - V[n].m) % 2 == 0 && V[n].n.size() - V[n].m > 0)
                q.push(n);
        }
        U[t] = true;
    }
#else

#endif

    return true;
}

int main()
{
    cin >> N >> M;
    REP(i, M)
    {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        V[a].n.push_back(b);
        V[b].n.push_back(a);
        E[i] = pll(std::min(a, b), std::max(a, b));
    }

    if (!solve())
    {
        cout << -1 << endl;
    }
    else
    {
        REP(i, M)
        {
            cout << A[i].first << " " << A[i].second << endl;
        }
    }
    return 0;
}

