{
  REP(j,SIZ(G[id]))
    {
      int k = G[id][j];

      if( k != par and cango[k] )
	{
	  cango[k] = false;
	  direct(k,id);
	}
    }


  if( par == -1 )
    {
      return;
    }

  if( outdeg[id] % 2 == 1 )
    {
      ++ outdeg[id];
      edge.push_back(make_pair(id+1,par+1)); 
    }
  else
    {
      ++ outdeg[par];
      edge.push_back(make_pair(par+1,id+1));
    }


}


