struct Edge {
	int to, ort, rev;
};

vector<vector<Edge>> edg;
vector<int> cntout;
vector<pair<int, int>> par;

int main() {
	int n, m; cin >> n >> m;
	if (m & 1) {
		cout << -1 << endl;
		return 0;
	}
	edg = decltype(edg)(n);
	cntout = decltype(cntout)(n);
	for (int i = 0; i < m; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		edg[a].push_back({ b, 1, (int)edg[b].size() });
		edg[b].push_back({ a, -1, (int)edg[a].size() - 1 });
		cntout[a]++;
	}

	deque<int> que;
	par = decltype(par)(n, { -1, -1 });
	{
		bool vis[100003] = {};
		deque<int> q;
		q.push_back(0);
		while (!q.empty()) {
			int pos = q.front();
			q.pop_front();
			vis[pos] = true;
			bool flag = true;
			for (int i = 0; i < (int)edg[pos].size(); i++) {
				auto e = edg[pos][i];
				if (vis[e.to]) continue;
				flag = false;
				vis[e.to] = true;
				par[e.to] = { pos, i };
				q.push_back(e.to);
			}
			if (flag) que.push_back(pos);
		}
	}
	while (!que.empty()) {
		int pos = que.front();
		que.pop_front();
		if ((cntout[pos]&1) && par[pos].first != -1) {
			auto &e = edg[par[pos].first][par[pos].second];
			e.ort *= -1;
			edg[e.to][e.rev].ort *= -1;
			cntout[pos]--;
			cntout[par[pos].first]++;
		}
		if (par[pos].first != -1) que.push_back(par[pos].first);
	}


	bool check = true;
	for (int i = 0; i < n; i++) {
		check &= cntout[i] % 2 == 0;
	}
	if (!check) {
		cout << "-1" << endl;
		return 0;
	}
	for (int i = 0; i < n; i++) {
		for (const auto &e : edg[i]) {
			if (e.ort == 1) {
				cout << i + 1 << " " << e.to + 1 << endl;
			}
		}
	}
	return 0;
}

