    st[v].insert(u);
    G[u].push_back(v);
    G[v].push_back(u);
  }

  dfs(0);
  // DEBUG_VEC(perm);

  vi score(n);
  vector<pii> ans;
  rep (i, n - 2) {
    int u = perm[i];
    if (score[u] % 2 == 0) {
      for (auto itr = st[u].begin(); itr != st[u].end(); itr++) {
        int v = *itr;
        score[v]++;
        st[v].erase(u);
        ans.push_back(pii(v, u));
      }
    }
    else {
      auto itr = st[u].begin();
      int v = *itr;
      score[u]++;
      st[v].erase(u);
      ans.push_back(pii(u, v));
      itr++;
