        int v = *itr;
        score[v]++;
        st[v].erase(u);
        ans.push_back(pii(v, u));
      }        
    }
  }

  int u = perm[n - 2], v = perm[n - 1];
  assert(score[u] % 2 != score[v] % 2);
  if (score[u] % 2) {
    ans.push_back(pii(u, v));
  }
  else {
    ans.push_back(pii(v, u));
  }
  assert(ans.size() == m);
  rep (i, ans.size()) {
    cout << ans[i].first + 1 << " " << ans[i].second + 1 << endl;
  }
}

