//ここから編集する
class Solve {
public:
    int N, M;
    vector<set<int>> G;
    set<pair<int, int>> edges;
    set<pair<int, int>> ans;
//    vector<int> rest;
    vector<int> deg;

    void solve() {
        cin >> N >> M;
//        rest.resize(N);
        deg.resize(N);
        G.resize(N);
        for (int i = 0; i < M; ++i) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            if (a > b) swap(a, b);
            edges.emplace(a, b);
//            rest[a]++;
//            rest[b]++;
            G[a].insert(b);
            G[b].insert(a);
        }


        if (M % 2) {
            cout << -1 << endl;
            return;
        }

        queue<int> que;
        for (int i = 0; i < N; ++i) {
            if (G[i].size() == 1) {
                que.push(i);
            }
        }

        auto addedge = [&](int from, int to) {
//            if ((G[from].size() + deg[from]) % 2) swap(to, from);
            G[to].erase(from);
            G[from].erase(to);
            deg[from]++;
//            if (G[from].size() == 1) {
//                que.push(from);
//            }

            pair<int, int> e{from, to};
            ans.insert(e);
            if (e.first > e.second) swap(e.first, e.second);
            edges.erase(e);
        };

        while (!edges.empty()) {
            if (que.empty()) {
                //ランダムに頂点を選び、割り振る
                auto e = *edges.begin();
                if ((G[e.first].size() + deg[e.first]) % 2 == 1) {
                    //一つだけこっちに来る
                    int to = e.first;
                    int from = e.second;
                    addedge(from, to);
                }
                vector<int> nexts;
                for (auto e : G[e.first]) nexts.push_back(e);
                for (auto next : nexts) {
                    int from = e.first;
                    int to = next;
                    addedge(from, to);
                }

                //関係があった頂点全てに対し、残り次数が1のやつをたぴ
//                nexts.push_back(e.first);
                for (auto e : nexts) {
                    if (G[e].size() == 1) {
                        que.push(e);
                    }
                }


            } else {
                int to = que.front();
                que.pop();
                int from = *G[to].begin();
                if (deg[to] % 2) swap(to, from);
                G[to].erase(from);
                G[from].erase(to);
                deg[from]++;
                if (G[from].size() == 1) {
                    que.push(from);
                }
                if (G[to].size() == 1) {
                    que.push(to);
                }

                pair<int, int> e{from, to};
                ans.insert(e);
                if (e.first > e.second) swap(e.first, e.second);
                edges.erase(e);

            }
        }

        for (auto e : ans) {
            cout << e.first + 1 << " " << e.second + 1 << endl;
        }

        for (auto e : deg) {
            if (e % 2) {
                cerr << "Dame case" << endl;
                exit(-1);
            }
        }


    }
};


