int dfs(int cur, int eid){
	vis[cur] = 1;
	for(int u: g[cur]){
		int next = e[u].u + e[u].v - cur;
		if(vis[next] == 1) continue;
		f[cur] ^= dfs(next, u);
	}
	if(f[cur]){
		if(eid != -1) e[eid].flip ^= 1;
	}
	return f[cur];
}

