const int N = 1e5 + 233;

int n, m, tot, vis[N], out[N];

struct Edge { int x, y; } E[N];
struct Node { int y, id, t; };
std::vector<Node> G[N];

void dfs1(int x, int fa) {
  vis[x] = 1;
  for (int i = 0; i < G[x].size(); ++i) {
    int y = G[x][i].y;
    if (y == fa) G[x][i].t = 1;
    else if (!vis[y]) {
      G[x][i].t = 1; dfs1(y, x);
    } else if (!E[G[x][i].id].x) {
      E[G[x][i].id] = { x, y };
      ++out[x];
    }
  }
}

void dfs2(int x, int fa) {
  for (auto w : G[x]) {
    if (!w.t || w.y == fa) continue;
    int y = w.y; dfs2(y, x);
    if (out[y] & 1)
      E[w.id] = { y, x };
    else {
      ++out[x];
      E[w.id] = { x, y };
    }
  }
}

