class UnionFind
{
public:
    vector<int> par;
    vector<int> sz;

    UnionFind(int N){
        par = vector<int>(N);
        REP(i, N) par[i] = i;
        sz = vector<int>(N, 1);
    }

    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(sz[x] < sz[y]) swap(x, y);

        par[y] = x;
        sz[x] += sz[y];
    }

    bool is_union(int x, int y){
        x = find(x);
        y = find(y);
        return x == y;
    }

    int union_size(int x){
        return sz[find(x)];
    }

};


struct edge{int to, cost;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec num;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
    }

    void add_Directed_edge(int from, int to, int cost = 1){
        G[from].push_back(edge({to, cost}));
    }

    void add_Undirected_edge(int v1, int v2, int cost = 1){
        add_Directed_edge(v1, v2, cost);
        add_Directed_edge(v2, v1, cost);
    }

    void dfs(int v, pairs &ans, int p = -1){
        for(auto e: G[v]) if(e.to != p){
            dfs(e.to, ans, v);
        }

        if(p != -1 && num[v] % 2 == 0){
            ans.pb(Pii(p, v));
            num[p]++;
        }else{
            ans.pb(Pii(v, p));
        }
    }

};

signed main(){

    int N, M; cin >> N >> M;
    Graph G(N);
    UnionFind UF(N);

    if(M % 2){
        Out(-1);
        return 0;
    }

    vec num(N, 0);
    pairs ans;
    int a, b;
    REP(i, M){
        cin >> a >> b;
        a--; b--;
        if(!UF.is_union(a, b)){
            UF.unite(a, b);
            G.add_Undirected_edge(a, b);
        }else{
            ans.pb(Pii(a, b));
            num[a]++;
        }
    }
    G.num = num;
    G.dfs(0, ans);
    REP(i, M) cout << ans[i].f + 1 << " " << ans[i].s + 1<< endl;

    return 0;
}

