ll N, M, Q, X, Y, Z, A, B, C, D, E, F, G;

int found = 0;

int check[100005];

int out_degree[100005];

vector<int> AdjList[200005];

vector<pli> EdgeList;

void dfs(int x){
	int last = 0, cnt = 0;
	for (auto it : AdjList[x]){
		if (EdgeList[it].second != 0) continue;
		cnt++;
		last = it;
	}
	if ((cnt+out_degree[x])%2==0){
		for (auto it : AdjList[x]){
			if (EdgeList[it].second != 0) continue;
			if (x == EdgeList[it].first.first) EdgeList[it].second = 1;
			else EdgeList[it].second = 2;
			out_degree[x]++;
		}
	}
	else{
		for (auto it : AdjList[x]){
			if (EdgeList[it].second != 0) continue;
			if (it == last){
				if (x == EdgeList[it].first.first) EdgeList[it].second = 2;
				else EdgeList[it].second = 1;
				out_degree[last]++;
			}
			if (x == EdgeList[it].first.first) EdgeList[it].second = 1;
			else EdgeList[it].second = 2;
			out_degree[x]++;
		}
		dfs(last);
	}
}

void dfs2(int x, int p){
	if (p != -1 && out_degree[x]%2==0){
		found = 1;
		return;
	}
	for (auto it : AdjList[x]){
		auto k = EdgeList[it];
		if (x == k.first){
			dfs2(k.second,x);
		}
		else{
			dfs2(k.first,x);
		}
		if (found){
			EdgeList[it].second = 3 - EdgeList[it].second;
			return;
		}
	}

}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cin >> N >> M;
	if (M%2!=0){
		cout << "-1\n";
		return 0;
	}
	for (int i = 1; i <= M; ++i){
		cin >> A >> B;
		if (A > B) swap(A,B);
		EdgeList.push_back(pli(pl(A,B),0));
		AdjList[A].push_back(i-1);
		AdjList[B].push_back(i-1);
	}
	for (int i = 1; i <= N; ++i){
		if (!check[i]){
			dfs(i);
		}
	}
	for (int i = 1; i <= N; ++i){
		if (out_degree[i]%2!=0){
			found = 0;
			dfs2(i,-1);
		}
	}
	for (int i = 0; i < M; ++i){
		if (EdgeList[i].second == 1){
			cout << EdgeList[i].first.first << ' ' << EdgeList[i].first.second << '\n';
		}
		else cout << EdgeList[i].first.second << ' ' << EdgeList[i].first.first << '\n';
	}
}

