		odd[u] = !odd[u];

		list[make_pair(u, v)] = 0;

		graph[u].push_back(v);
		graph[v].push_back(u);
	}

	for (i = 1; i <= n; i++)
	{
		tot = tot && !odd[i] || !tot&&odd[i];
	}

	if (tot)
	{
