    ll N, M;
    cin >> N >> M;
    vl A(M), B(M);
    vector<vl> adj;
    adj.resize(N);
    map<pair<int, int>, int> index_of_edge;
    bool rev[M] = {};
    bool odd[N] = {};
    FOR(i, 0, M) {
        cin >> A[i] >> B[i];
        A[i]--;
        B[i]--;
        adj[A[i]].push_back(B[i]);
        adj[B[i]].push_back(A[i]);
        odd[A[i]] = !odd[A[i]];
        index_of_edge[make_pair(A[i], B[i])] = i;
        index_of_edge[make_pair(B[i], A[i])] = i;
    }
    if (M % 2) {
        cout << "-1" << endl;
        return 0;
    }
    ll bfs[N] = {};
    queue<int> que;
    que.push(0);
    bfs[0] = 1;
    while (que.size()) {
        ll f = que.front();
        que.pop();
        for (auto x : adj[f]) {
            if (!bfs[x]) {
                bfs[x] = bfs[f] + 1;
                que.push(x);
            }
        }
    }

    priority_queue<pair<int, int>> pque;
    FOR(i, 0, N) {
        pque.push(make_pair(bfs[i], i));
    }

    while (pque.size()) {
        auto p = pque.top();
        pque.pop();
        if (odd[p.second]) {
            for (auto x : adj[p.second]) {
                if (bfs[x] < bfs[p.second]) {
                    auto idx = index_of_edge[make_pair(x, p.second)];
                    rev[idx] = !rev[idx];
                    odd[x] = !odd[x];
                    odd[p.second] = !odd[p.second];
                    break;
                }
            }
            assert(!odd[p.second]);
        }
    }

    FOR(i, 0, M) {
        if (rev[i]) {
            cout << B[i] + 1 << ' ' << A[i] + 1 << endl;
        } else {
            cout << A[i] + 1 << ' ' << B[i] + 1 << endl;
        }
    }
}

