int visit[100000];

bool dfs(int c, int p, int depth, vector<vector<vector<int>>> &edges, vector<pii> &ret) {
    bool end = false;
    for (auto &e : edges[c]) {
        if (e[0] == p)
            continue;
        if (e[2] != 0)
            continue;
        e[2] = 1;
        edges[e[0]][e[1]][2] = 1;
        if (depth % 2 == 0)
            ret.emplace_back(e[0], c);
        else
            ret.emplace_back(c, e[0]);

        end = dfs(e[0], c, depth + 1, edges, ret);
        if (end)
            break;
        else {
            e[2] = 0;
            edges[e[0]][e[1]][2] = 0;
            ret.pop_back();
        }
    }
    if (!end) {
        if (depth % 2 == 0)
            end = true;
    }
    return end;
}

