int e1[100000];
int e2[100000];
set<int> es[100000];
int parity[100000];
set<int> sing, many;

void pp(int a, int b) {
    printf("%d %d\n", a+1, b+1);
}

void errrr(int v, int e) {
    es[v].erase(e);
    if (es[v].size() == 1) {
        many.erase(v);
        sing.insert(v);
    } else if (es[v].size() == 0) {
        sing.erase(v);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n = gi();
    int m = gi();
    if (m%2) {
        printf("-1\n");
        return 0;
    }

    for (int i = 0; i < m; i++) {
        e1[i] = gi()-1;
        e2[i] = gi()-1;
        es[e1[i]].insert(i);
        es[e2[i]].insert(i);
    }

    for (int i = 0; i < n; i++)
        if (es[i].size() == 1)
            sing.insert(i);
        else
            many.insert(i);

    memset(parity, 0, sizeof(parity));
    while (sing.size() || many.size()) {
        if (sing.size()) {
            int v = *(sing.begin());
            int e = *(es[v].begin());
            int v2 = (e1[e] == v ? e2[e] : e1[e]);
            if (parity[v]) {
                pp(v, v2);
            } else {
                pp(v2, v);
                parity[v2] ^= 1;
            }
            sing.erase(v);
            errrr(v2, e);
        } else {
            int v = *(many.begin());
            int e = *(es[v].begin());
            int v2 = (e1[e] == v ? e2[e] : e1[e]);
            pp(v, v2);
            parity[v] ^= 1;
            errrr(v, e);
            errrr(v2, e);
        }
    }

    return 0;
}

