	edge &e;
};

int main(void) {
	int n, m;
	cin >> n >> m;
	vector <edge> edges(m);
	vector <vector <int>> graph(n + 1);
	for (int i = 0; i < m; i++) {
		cin >> edges[i].u >> edges[i].v;
		graph[edges[i].u].push_back(i);
		graph[edges[i].v].push_back(i);
	}

	if (m % 2) {
		cout << -1 << endl;
		return 0;
	}

	vector <bool> vis(n + 1);
	queue <int> q;
	stack <node> tree;

	q.push(1);
	vis[1] = true;

	while (!q.empty()) {
		auto u = q.front();
		q.pop();
		for (auto i: graph[u]) {
			auto &e = edges[i];
			int v = u ^ e.u ^ e.v;
			if (!vis[v]) {
				vis[v] = true;
				q.push(v);
				tree.push({v, e});
			}
		}
	}

	while (!tree.empty()) {
		auto u = tree.top();
		tree.pop();
		int cnt = 0;
		for (auto i: graph[u.v]) {
			auto &e = edges[i];
			cnt += e.rev ^ (e.u == u.v);
		}
		u.e.rev = cnt % 2;
	}

	for (auto e: edges) {
		if (e.rev) {
			cout << e.v << " " << e.u << endl;
		} else {
			cout << e.u << " " << e.v << endl;
		}
	}
	return 0;
}

