int main() {
    int N, M; scanf("%d%d", &N, &M);
    if(M % 2) drop("-1");

    map< pair<int, int>, int > E2N;
    vector<int> group(M), visited(N), deg(N);
    vector< pair<int, int> > ans(M);
    vector< vector<int> > G(N);
    for(int i=0; i<M; i++) {
        int u, v; scanf("%d%d", &u, &v);
        u--; v--;
        G[u].emplace_back(v);
        G[v].emplace_back(u);
        E2N[ make_pair(u, v) ] = i;
        E2N[ make_pair(v, u) ] = i;
    }

    auto dfs1 = [&](auto&& self, int cur, int par) -> void {
        visited[cur] = true;
        for(auto to : G[cur]) {
            if(to == par) continue;
            int k = E2N[ make_pair(cur, to) ];
            if(visited[to]) {
                if(group[k]) continue;
                group[k] = 1;
                deg[cur]++;
                ans[k] = make_pair(cur, to);
            }
            else {
                group[k] = 0;
                self(self, to, cur);
            }
        }
    };

    auto dfs2 = [&](auto&& self, int cur, int par) -> void {
        for(auto to : G[cur]) {
            if(to == par) continue;
            int k = E2N[ make_pair(cur, to) ];
            if(group[k]) continue;
            self(self, to, cur);
            if(deg[to] % 2) {
                deg[to]++;
                ans[k] = make_pair(to, cur);
            }
            else {
                deg[cur]++;
                ans[k] = make_pair(cur, to);
            }
        }
    };

    dfs1(dfs1, 0, -1);
    dfs2(dfs2, 0, -1);
    for(int i=0; i<M; i++) printf("%d %d\n", ans[i].first + 1, ans[i].second + 1);
    return 0;
}

