vector<vector<int>> construct(const vector<vector<int>> &adj) {
    int n = adj.size();
    vector<int> deg(n);
    for (int i = 0; i < n; i++) deg[i] = adj[i].size();
    set<pair<int, int>> es, used;
    vector<bool> visited(n);
    for (int i = 0; i < n; i++) {
        for (int a : adj[i]) {
            if (i < a) {
                es.insert({i, a});
            }
        }
    }
    vector<vector<int>> ret(n);
    auto add_edge = [&](int a, int b) {
        ret[a].push_back(b);
        deg[a]--;
        deg[b]--;
        used.insert({min(a, b), max(a, b)});
    };
    function<void(int)> dfs = [&](int v) {
        for (int s : adj[v]) {
            if (!visited[s]) {
                if (deg[v] & 1) {
                    add_edge(s, v);
                } else if (deg[s] & 1) {
                    add_edge(v, s);
                } else {
                    add_edge(v, s);
                }
                visited[s] = true;
                dfs(s);
            }
        }
    };
    visited[0] = true;
    dfs(0);
    for (auto &e : es) {
        if (used.count(e) == 0) {
            int v = e.first, s = e.second;
            if (deg[v] & 1) {
                add_edge(s, v);
            } else if (deg[s] & 1) {
                add_edge(v, s);
            } else {
                add_edge(v, s);
            }
        }
    }
    return ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    if (m & 1) {
        cout << -1 << endl;
        return 0;
    }

    vector<vector<int>> adj(n), sol;
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    sol = construct(adj);
    for (int i = 0; i < n; i++) {
        for (int a : sol[i]) {
            cout << i + 1 << ' ' << a + 1 << '\n';
        }
    }
}

