    }
    if(m % 2 == 1){
        p(-1);
    }else{
        ll idx = 0;
        for(i=1;i<=n;i++){
            if(even[i] % 2 == 0){
                check[i] = true;
                continue;
            }else{
                idx = z[i];
                while(1){
                    if(idx > m){
                        idx = 0;
