                    ll v = table[idx].first;
                    ll nv = table[idx].second;
                    if(v != i || check[nv]){
                        //pe("//");pe(v);p(nv);
                        idx++;
                        continue;
                    }
                    even[v]--;
                    even[nv]++;
                    swap(table[idx].first,table[idx].second);
                    idx++;
                    check[v] = true;
                    break;
                }
            }
        }
        for(i=0;i<m;i++){
            pe(table[i].first);p(table
                [i].second);
        }
    }
