    return 0;
  }
  vector<pair<int,int>>dlist;
  Graph<true, int> H(N);
  for(int i = 0; i < N; ++i){
    if(G.E[i].size() == 1){
      int to = G.E[i].begin() -> first;
      H.connect(to, i, 1);
      dlist.push_back({to,i});

      cout << to+1 << ' ' << i+1 << endl;
    }
  }
  for(auto&&e:dlist){
    G.unconnect(e.first, e.second);
  }
  for(int i = 0; i < N; ++i){
    unordered_map<int, int> mp = G.E[i];
