// dirは 入が0 出が1
int recursive(int c, int dir) {
    for(auto x : node[c]) {
        if(node[c].count(x) == 0 || node[x].empty()) continue; // guard
        node[c].erase(x);
        node[x].erase(c);
        if (dir) {
            check[x]++;
            ans.emplace_back(x, c);
        } else {
            check[c]++;
            ans.emplace_back(c, x);
        }
        recursive(x, 1 - dir);
    }
}

