int par[100005];

vector<int> tedge[100005];

int f(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = f(par[x]);
	}
}

void dfs(int cur, int prev, int edgeid){
	for(auto id: tedge[cur]){
		int to = a[id] + b[id] - cur;
		if(to != prev){
			dfs(to, cur, id);
		}
	}
	if(edgeid == -1){
		return;
	}
	if(deg[cur] & 1){
		// point parent edge to cur
		a[edgeid] = prev;
		b[edgeid] = cur;
		deg[cur]++;
	}else{
		// point parent edge to parent
		a[edgeid] = cur;
		b[edgeid] = prev;
		deg[prev]++;
	}
}

