int h[maxn], mem;
int fa[maxn][20];
int dep[maxn];
bool vis[maxn];
bool du[maxn];
int ansx[maxn], ansy[maxn], top;
bool sum[maxn];
void pre()
{
    memset(h, -1, sizeof(h));
    mem = 0;
    top = 0;
    memset(vis, 0, sizeof(vis));
    memset(fa, 0, sizeof(fa));
    memset(du, 0, sizeof(du));
    memset(sum, 0, sizeof(sum));
}

void add( int u, int v )
{
    e[mem].v = v;
    e[mem].next = h[u];
    h[u] = mem++;
}

void dfs(int u, int f)
{
    vis[u] = 1;
    dep[u] = dep[f] + 1;
    fa[u][0] = f;
    for(int i=1; i<20; i++)
        fa[u][i] = fa[fa[u][i-1]][i-1];
    for(int i=h[u]; i+1; i=e[i].next)
    {
        int v = e[i].v;
        if(v==f) continue;
        if(vis[v]){
            if(dep[u]<dep[v]||(dep[u]==dep[v]&&u<v))
            {
                du[u] ^= 1;
                ansx[top] = u;
                ansy[top++] = v;
            }
            continue;
        }
        du[u]^=1;
        dfs(v, u);
    }
}

vector<int> last;

int findfa(int u, int v)
{
    if(dep[u]<dep[v]) swap(u, v);
    for(int i=19; i>=0; i--)
    {
        if(dep[fa[u][i]] >= dep[v])
            u = fa[u][i];
    }
    if(u==v) return u;
    for(int i=19; i>=0; i--)
    {
        if(fa[u][i]!=fa[v][i]){
            u = fa[u][i];
            v = fa[u][i];
        }
    }
    return fa[u][0];
}

void change(int u, int v)
{
    int f = findfa(u, v);
    // du[f] ^= 1;
    du[u] ^= 1;
    du[v] ^= 1;

}

bool dfsans(int u, int f)
{
    vis[u] = 1;
    //printf("dfsans %d %d\n", u, f);
    bool now=du[u];
    for(int i=h[u]; i+1; i=e[i].next)
    {
        int v = e[i].v;
        if(v==f) continue;
        if(vis[v]) continue;
        bool flag = dfsans(v, u);
        if(flag){
            ansx[top] = v;
            ansy[top] = u;
        }
        else{
            ansx[top] = u;
            ansy[top] = v;
        }
        top++;
        now ^= flag;
    }
    return now;
