int main(){
    int n, m;
    std::cin >> n >> m;
    std::vector<pii> E;
    std::vector<int> c(n);
    for(int i = 0; i < m; i++){
        int u, v;
        std::cin >> u >> v;
        u--; v--;
        E.emplace_back(u, v);
        c[u] ^= 1;
    }

    LinearSystemIncidence<int> LSI(n, E, true);
    auto res = LSI.solve(c);

    if(res.first){
        for(int i = 0; i < m; i++){
            if(res.second[i]) std::swap(E[i].first, E[i].second);
            std::cout << E[i].first + 1 << " " << E[i].second + 1 << '\n';
        }
    }
    else std::cout << -1 << '\n';
}

