vector<Edge>MST(vector<Edge> edges){

	int cost = 0;
	vector<Edge> result;
	for (int i = 0; i < n; i++)
		make_set(i);
	sort(edges.begin(), edges.end());
	for (Edge e : edges) {
		if (find_set(e.u) != find_set(e.v)) {
			cost += e.weight;
			result.push_back(e);
			union_sets(e.u, e.v);
		}
		else {ans.pb(mp(e.u , e.v)) ;deg[e.u]++ ;}
	}
	return result ;
}
void dfs(int u){
	visited[u] = true ;
	vi tmp ;
	for(int x : ad[u]){
		if(!visited[x]) dfs(x) ;
		else tmp.pb(x) ;
	}
	if((deg[u] + tmp.size()) % 2 == 0){
		for(int x : tmp){
			ans.pb(mp(u , x)) ;
		}
	}
	else{
		int x1 = -1 ;
		for(int x : tmp){
			ans.pb(mp(x , u)) ;
			deg[x]++ ;
			x1 = x ;
			break ;
		}
		for(int x : tmp){
			if(x != x1){
				ans.pb(mp(u , x)) ;
			}
		}
	}
}
