using namespace std;

vector<int> vis, deg;
vector<vector<int>> g;
vector<pair<int, int>> p;

void dfs(int u) {
  vis[u] = 1;
  for (auto to : g[u]) {
    int v = (p[to].first == u) ? p[to].second : p[to].first;
    if (vis[v]) continue;
    p[to].first = u, p[to].second = v;
    dfs(v);
  }
}

void adjust(int u, int par) {
  vis[u] = 1;
  for (auto to : g[u]) {
    int v = p[to].second;
    if (vis[v]) continue;
    adjust(v, to);
  }
  if (deg[u]&1) {
    swap(p[par].first, p[par].second);
    deg[p[par].first] ^= 1;
    deg[p[par].second] ^= 1;
  }
}

int main() {

  ios::sync_with_stdio(false);
  cout.tie(nullptr);
  cin.tie(nullptr);

  int n, m;
  cin >> n >> m;

  g.resize(n);
  deg.assign(n, 0);

  for (int i = 0; i < m; ++i) {
    int u, v;
    cin >> u >> v;

    --u; --v;
    g[u].push_back((int)p.size());
    g[v].push_back((int)p.size());
    p.emplace_back(u, v);
  }

  if (m&1) {
    cout << -1 << '\n';
    return 0;
  }

  vis.assign(n, 0);
  dfs(0);
  for (int i = 0; i < m; ++i) {
    deg[p[i].first] ^= 1;
  }
  vis.assign(n, 0);
  adjust(0, -1);

  for (int i = 0; i < m; ++i) {
    cout << p[i].first + 1 << " " << p[i].second + 1 << '\n';
  }
}

