ll memo[100010];
int a[100010];
int n, m;

ll calc(int x) {
	if (a[x] == 1) return 0;
	if (x > n) return 0;
	if (x == n) return 1;
	ll& res = memo[x];
	if (~res) return res;
	res = 0;
	res += calc(x + 1);
	res %= INF;
	res += calc(x + 2);
	res %= INF;
	return res;
}

int buttle(ll a,ll b,ll aa,ll bb){
	ll ab = max(1LL,a / bb);
	ll aab = max(1LL,aa / b);
	if (ab == aab) {
		ll ar = a - ab * bb;
		ll aar = aa - aab * b;
		if (ar > 0 && aar > 0) return 0;
		if (ar <= 0 && aar <= 0) return 0;
		if (ar <= 0) return -1;
		if (aar <= 0) return 1;
	}

	if (ab > aab) {
		return 1;
	}
	else if (ab < aab)
		return -1;
	else return 0;

}
struct edge {
	int ind, f, t;
	edge(int _ind, int _f, int _t) :ind(_ind), f(_f), t(_t) {}
};
queue<edge> ed[100010];
pair<int, int> e[100010];
bool use[100010];
int ocount[100010];
int ucount[100010];
int mcount[100010];
void rec(int x,int ind) {

	int ecount = 0;
	while (!ed[x].empty()) {
		edge p = ed[x].front();
		ed[x].pop();
		int nex = p.t;
		int ni = p.ind;
		if (use[ni]) continue;
		use[ni] = true;
		ucount[x]++;
		ucount[nex]++;

		mcount[x]++;
		if (e[ni].first != x) swap(e[ni].first, e[ni].second);
		if (ucount[x] == ocount[x]) {
			if (mcount[x] % 2 != 0) {
				if (e[ni].first == x) swap(e[ni].first, e[ni].second);
				mcount[x]--;
				mcount[nex]++;
			}
		}
		rec(nex,  ni);
		ecount++;
	}
	if (ecount == 0) {
		if (mcount[x] % 2 != 0) {
			if (e[ind].first != x) {
				mcount[x]++;
				mcount[e[ind].first]--;
				swap(e[ind].first, e[ind].second);
			}
		}
	}

}
