using namespace chrono;
auto start=system_clock::now();
ll n,m;
void random(vector<unordered_set<ll>>_g){
    random_device rr;
    mt19937 rand(rr());
    vector<vector<ll>>g(n);
    rep(n)g[i]=vector<ll>(_g[i].begin(),_g[i].end());
    vector<ll>cnt(n);
    vector<unordered_map<ll,ll>>path(n);
    queue<ll>q;
    rep(n)each(j,g[i])if(i<j){
        path[i][j]=1;
        path[j][i]=0;
        cnt[i]^=1;
    }
    rep(n)if(cnt[i]&1)q.push(i);
    while(q.size()&&duration_cast<milliseconds>(system_clock::now()-start).count()<1997){
        ll from=q.front();
        q.pop();
        if(cnt[from]%2==0)continue;
        ll to=g[from][rand()%g[from].size()];
        cnt[from]^=1;
        cnt[to]^=1;
        path[from][to]^=1;
        path[to][from]^=1;
        if(cnt[to]&1)q.push(to);
    }
    if(q.empty()){
        rep(n)each(j,path[i])if(j.second)out(i+1,j.first+1);
    }
    else out(-1);
    exit(0);
}
signed main(){
    in(n,m);
    if(m&1)return out(-1);
    vector<pll>ans;
    vector<ll>cnt(n);
    vector<unordered_set<ll>>g(n);
    rep(m){
        LL(a,b);
        a--;b--;
        g[a].insert(b);
        g[b].insert(a);
    }
    pq<pll>q;
    rep(n)q.emplace(g[i].size(),i);
    while(q.size()){
        ll from=q.top().second;
        q.pop();
        if(g[from].empty())continue;
        auto p=g[from].begin();
        ll to,max=0;
        rep(10){
            if(p==g[from].end())break;
            if(chmax(max,ll(g[*p].size())))to=*p;
        }
        if(cnt[from]){
            ans.emplace_back(from+1,to+1);
            cnt[from]^=1;
        }
        else{
            ans.emplace_back(to+1,from+1);
            cnt[to]^=1;
        }
        g[from].erase(to);
        g[to].erase(from);
        q.emplace(g[to].size(),to);
        if(g[from].size())q.emplace(g[from].size(),from);
    }
    each(i,cnt)if(i)random(g);
    each(i,ans)out(i);
}

