const int MX = 100001; //check the limits, dummy

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);

    int N; cin >> N; int M; cin >> M;

    vector<set<int> > graph(N);
    bool odd[N]; F0R(i, N) odd[i] = false;

    F0R(i, M) {
        int A, B; cin >> A >> B; A--; B--;
        graph[A].insert(B); graph[B].insert(A);
    }

    priority_queue<pi> pq;
    F0R(i, N) {
        if (sz(graph[i]) == 1) {
            pq.push(mp(MX, i));
        } else {
            pq.push(mp(sz(graph[i]), i));
        }

    }
    vpi newGraph;
    while (!pq.empty()) {
        pi val = pq.top(); pq.pop();
        int deg = val.first; if (deg == MX) deg = 1;
        if (deg != sz(graph[val.s])) continue;
        int cur = val.s;
        if (deg == 0) {
            continue;
        } else if (deg == 1) {
            int nxt = *graph[cur].begin();
            graph[cur].erase(nxt);
            graph[nxt].erase(cur);
            if (sz(graph[nxt]) == 1) {
                pq.push(mp(MX, nxt));
            } else {
                pq.push(mp(sz(graph[nxt]), nxt));
            }
            if (odd[cur]) {
                newGraph.pb(mp(cur, nxt));
                odd[cur] = false;
            } else {
                newGraph.pb(mp(nxt, cur));
                odd[nxt] = !odd[nxt];
            }
        } else {
            int nxt = *graph[cur].begin();
            graph[cur].erase(nxt);
            graph[nxt].erase(cur);
            if (sz(graph[nxt]) == 1) {
                pq.push(mp(MX, nxt));
            } else {
                pq.push(mp(sz(graph[nxt]), nxt));
            }
            if (sz(graph[cur]) == 1) {
                pq.push(mp(MX, cur));
            } else {
                pq.push(mp(sz(graph[cur]), cur));
            }
            newGraph.pb(mp(cur, nxt));
            odd[cur] = !odd[cur];

        }
    }

    F0R(i, N) {
        if (odd[i]) {
            cout << "-1" << endl;
            return 0;
        }
    }

    F0R(i, sz(newGraph)) {
        cout << newGraph[i].f +1 << " " << newGraph[i].s + 1 << endl;
    }

    return 0;
}

