            curd[v]++;
            gg[graph[v][i]].v = 1;
        }
        else
        {
            ans.push_back({u, v});
            curd[u]++;
            gg[graph[v][i]].v = 1;
        }
        dfs(u);
    }
}

int in[500000];
int out[500000];
int up[500000];
int Timer = 1;

void fs(int root, int par)
{
    if (in[root] != 0)
        return;
    in[root] = Timer++;
    up[root] = in[root];
    for (int i = 0; i < graph[root].size(); i++)
    {
        int u = gg[graph[root][i]].a + gg[graph[root][i]].b - root;
        if (u == par) continue;
        if (in[u] != 0)
        {
            up[root] = min(up[root], in[u]);
        }
        else
        {
            fs(u, root);
            up[root] = min(up[root], up[u]);
            if (up[u] > in[root])
            {
                gg[graph[root][i]].is_br = 1;
            }
        }
    }
    out[root] = Timer++;
}

