int Btimer = 1;

void dfs_no_briges(int v)
{
    if (color[v] != 0)
        return;
    color[v] = flag;
    for (int i = 0; i < graph[v].size(); i++)
    {
        int u = gg[graph[v][i]].a + gg[graph[v][i]].b - v;
        if (gg[graph[v][i]].is_br == 1)
        {
            continue;
        }
        else
        {
            if (color[u] == 0)
            {
                dfs_no_briges(u);
            }
        }
    }
}

void Dfs(int v)
{
    if (Bin[v] != 0) return;
    dp[v] = res[v];
    Bin[v] = Btimer++;
    for (int i = 0; i < bridge_tree[v].size(); i++)
    {
        int u = bridge_tree[v][i];
        if (Bin[u] == 0)
        {
            Dfs(u);
            dp[v] += dp[u] + 1;
        }
    }
    Bout[v] = Btimer++;
}

