void hierholzer(int u) {
	mark[u] = 1;
	for (int v : adj[u]) if (still.find({u, v}) != still.end()) {
		still.erase({u, v});
		still.erase({v, u});
		hierholzer(v);
	}
	path.push_back(u);
}

