int calc(int now, int prev, graph &src, graph &ans, vector<bool> &arrived) {
	//cout << now << endl;
	if(arrived[now]) {
		return 1;
	}
	arrived[now] = true;
	int pre = -1;
	for(int i = 0; i < src[now].size(); i++) {
		int next = src[now][i];
		if(next==prev) continue;
		if(next==-1) continue;
		int res = calc(next,now,src,ans,arrived);
		if(res==1) {
			if(pre==-1) {
				pre = next;
			}else {
				ans[now].push_back(pre);
				ans[now].push_back(next);
				//cout << now << "," << pre << "," << next << endl;
				src[now][pre] = -1;
				src[now][next] = -1;
				pre = -1;
			}
		}
	}
	if(pre!=-1) {
		if(prev!=-1) {
			ans[now].push_back(pre);
			ans[now].push_back(prev);
			//cout << now << "," << pre << "," << prev << endl;
			src[now][pre] = -1;
			src[now][prev] = -1;
			pre = -1;
			return 0;
		}
	}
	return 1;
	//return (pre==-1)?0:1;
}

