bool isUsed(int from, int to) {
    if (from > to) swap(from, to);
    return used[pll(from,to)];
}

void output(int from, int to) {
    printf("%d %d\n", from+1, to+1);
    if (from > to) swap(from, to);
    used[pll(from,to)] = true;
}

bool dfs(int v, int parent = -1) {
    if (visited[v]) return isUsed(parent, v);
    visited[v] = true;

    bool isOdd = false;
    for (auto to : G[v]) {
        if (isUsed(v, to)) continue;
        if (to == parent) continue;
        if (!dfs(to, v)) {
            isOdd = !isOdd;
            output(v, to);
        }
    }
    if (isOdd) output(v, parent);
    return isOdd;
}

