        V[b].node.push_back(a);
    }
    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    SegmentTree<pll> seg([](pll a, pll b) {
        if (a.first < b.first)
            return a;
        return b;
    }, pll(INF, INF));
    seg.init(N);
    REP(i, N) {
        seg.set(i, pll(V[i].node.size(), i));
    }

    memset(C, 0, sizeof(C));
