class SegmentTree {
private:
    struct Info {
        int value, index;

        Info() {}

        Info(int value, int index) {
            this->value = value;
            this->index = index;
        }
    };

    Info func(Info a, Info b) {
        return a.value <= b.value ? a : b;
    }

    int bottomSt, bottomEd;
    vector<Info> a;
    vector<int> rs, re;
    vector<Info> cand;

    Info set(int n) {
        int left = 2 * n + 1;
        int right = 2 * n + 2;
        if (left <= a.size() - 1) {
            a[n] = func(set(left), set(right));
            rs[n] = rs[left];
            re[n] = re[right];
        }
        return a[n];
    }

    void search(int s, int t, int n) {
        if (s <= rs[n] && re[n] <= t) {
            cand.push_back(a[n]);
            return;
        }
        int left = 2 * n + 1;
        int right = 2 * n + 2;
        if (s <= re[left]) search(s, t, left);
        if (rs[right] <= t) search(s, t, right);
    }

public:
    SegmentTree() {}

    SegmentTree(vector<int> &v) {
        bottomEd = 0;
        for (int i = 1, plus = 1; plus < v.size(); i++) {
            plus *= 2;
            bottomEd += plus;
        }
        a.resize(bottomEd + 1);
        rs.resize(bottomEd + 1);
        re.resize(bottomEd + 1);

        Info invalid = Info(0, -1);
        bottomSt = bottomEd / 2;

        for (int i = bottomSt; i <= bottomEd; i++) {
            int j = i - bottomEd / 2;
            a[i] = j < v.size() ? Info(v[j], j) : invalid;
            rs[i] = j;
            re[i] = j;
        }

        set(0);
    }

    int get(int index) {
        return a[bottomSt + index].value;
    }

    void update(int index, int x) {
        int pt = bottomSt + index;
        Info X = Info(x, index);
        a[pt] = X;
        while (pt > 0) {
            pt = (pt - 1) / 2;
            a[pt] = func(a[2 * pt + 1], a[2 * pt + 2]);
        }
    }

    Info find(int s, int t) {
        cand.clear();
        search(s, t, 0);
        Info ret = cand[0];
        for (int i = 1; i < cand.size(); i++) {
            ret = func(ret, cand[i]);
        }
        return ret;
    }
};

class Info {
public:
    int minValue;
    int minArg;
    int start, end;

    Info() {}

    Info(int value, int arg, int start, int end) {
        minValue = value;
        minArg = arg;
        this->start = start;
        this->end = end;
    }

    bool operator<(const Info &a) const {
        return minValue > a.minValue;
