struct UnionFind {
  vector<int> par, rank;

  UnionFind(int n = 1) : par(n), rank(n, 0) { iota(begin(par), end(par), 0); }

  int root(int x) {
    return (par[x] == x) ? x : par[x] = root(par[x]);
  }
  bool isSame(int x, int y) {
    return root(x) == root(y);
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    if (rank[x] < rank[y]) swap(x, y);
    rank[x] += rank[y];
    par[y] = x;
  }
};

