    for (int x : st[cur]) if (!visit[x]) ++sz;
    if (sz % 2 == 0) {
        for (int x : st[cur]) {
            if (!visit[x]) ans[cur].push_back(x);
        }
    } else {
        int rem;
        for (int x : st[cur]) {
