int root = 0;
vector<vector<int> > g, parent;
vector<int> depth, deg, rev, leaf;
vector<bool> used;
vector<P> es;

void dfs(int v, int p, int d){
    parent[0][v] = p;
    depth[v] = d;
    used[v] = true;
    int cnt = 0;
    for(auto u : g[v]){
        if(used[u]) continue;
        dfs(u, v, d+1);
        cnt++;
    }
    if(cnt==0) leaf.push_back(v);
}

void init(){
    int n = g.size();
    parent.resize(31, vector<int>(n));
    depth.resize(n);
    used.resize(n);
    dfs(root, -1, 0);
    for(int k=0;k<30;k++){
        for(int i=0;i<n;i++){
            if(parent[k][i] < -1) parent[k+1][i] = -1;
            else parent[k+1][i] = parent[k][parent[k][i]];
        }
    }
}

int lca(int u, int v){
    if(depth[u] > depth[v]) swap(u, v);
    for(int k=0;k<30;k++){
        if((depth[v] - depth[u]) >> k & 1){
            v = parent[k][v];
        }
        if(u == v) return u;
    }
    for(int k=29; k>=0; k++){
        if(parent[k][u] != parent[k][v]){
            u = parent[k][u];
            v = parent[k][v];
        }
    }
    return parent[0][u];
}

int main() {
