        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
        es.push_back(P(a,b));
        deg[a]++;
    }
    if(m%2){
        cout << -1 << endl;
        return 0;
    }
    init();
    vector<int> odd;
    for(int i=0;i<n;i++){
        if(deg[i]%2) odd.push_back(i);
    };
    for(int i=0;i<int(odd.size());i+=2){
        int u = odd[i], v = odd[i+1], w;
        w = lca(u, v);
        rev[u]++;
        rev[v]++;
        rev[w]-=2;
    }
    queue<int> que;
    for(auto v : leaf) que.push(v);
    while(!que.empty()){
        int v = que.front();
        que.pop();
        if(v == root) continue;
        rev[parent[0][v]] += rev[v];
        que.push(parent[0][v]);
    }
    for(int i=0;i<m;i++){
        int a, b;
        a = es[i].first;
        b = es[i].second;
        if(rev[b]%2) swap(a, b);
        cout << a+1 << " " << b+1 << endl;
    }
    return 0;
}

