                        vis[mp(node,adj[node][j])] = 1;
                        vis[mp(adj[node][j],node)] = 1;

                        in[node]++;
                    }
                }
            }
            else
            {
                for(j=0;j<adj[node].size();j++)
                {
                    if(!vis[mp(node,adj[node][j])])
                    {
                        edge[mp(node,adj[node][j])] = 1;
                        edge[mp(adj[node][j],node)] = -1;

                        vis[mp(node,adj[node][j])] = 1;
                        vis[mp(adj[node][j],node)] = 1;

                        in[adj[node][j]]++;
                    }
                }
            }
        }

        vis.clear();
        bool valid = 1;
        for(i=1;i<=n;i++)
        {
            if((adj[i].size()-in[i])&1 == 1)
            {
                valid = 0;
                break;
            }
        }

        if(valid)
        {
            for(i=1;i<=n;i++)
            {
                for(j=0;j<adj[i].size();j++)
                {
                    if(!vis[mp(i,adj[i][j])])
                    {
                        vis[mp(i,adj[i][j])] = 1;
                        vis[mp(adj[i][j],i)] = 1;


                        if(edge[mp(i,adj[i][j])] == 1)
                            cout<<i<<" "<<adj[i][j];
                        else
                            cout<<adj[i][j]<<" "<<i;
                        cout<<endl;
                    }
                }
            }
        }
        else
            cout<<-1<<endl;
	}



