template<bool Directed, class WeightType>
struct Graph{  
  int V;
  vector<unordered_map<int, WeightType>> E;
  Graph(){}
  Graph(const int v):V(v), E(v){};

  void connect(const int from, const int to, const WeightType w){
    E[from][to] = w;
    if(!Directed) E[to][from] = w;
  }

  void unconnect(const int from, const int to){
    E[from].erase(to);
    if(!Directed) E[to].erase(from);
  }

  WeightType getWeight(const int from, const int to)const
  { return E[from].count(to)?E[from][to]:1e+9; }

  bool isConnected(const int from, const int to)const
  { return E[from].count(to) != 0; }


};

int main(){
  int N, M; cin >> N >> M;
  Graph<false, int> G(N);
  for(int i = 0; i < M; ++i){
    int x, y;cin >> x >> y;x--;y--;
    G.connect(x, y, 1);
  }
  if(M%2 == 1){
    cout << -1 << endl;
    return 0;
  }
  Graph<true, int> H(N);
  for(int i = 0; i < N; ++i){
    if(G.E[i].size() == 1){
      int to = G.E[i].begin() -> first;
      H.connect(to, i, 1);
      G.unconnect(to, i);

      cout << to+1 << ' ' << i+1 << endl;
    }
  }

  for(int i = 0; i < N; ++i){
    unordered_map<int, int> mp = G.E[i];
    int cnt = mp.size();
    if((cnt + H.E[i].size())%2 == 1)cnt--;
    for(auto&&e:mp){
      if(cnt == 0)break;
      cnt--;
      H.connect(i, e.first, 1);
      G.unconnect(i, e.first);
      cout << i+1 << ' ' << e.first + 1 << endl;
    }
  }

  return 0; 
}

