    if (m%2 == 1) quit(-1);

    vector<int> v(n);
    rep (i,m) v[es[i].fst] ^= 1;

    vector<vector<edge>> g(n);
    UnionFind uf(n);
    rep (i,m) {
        int a,b; tie(a,b) = es[i];
        if (uf.same(a,b)) continue;
        uf.unite(a,b);
        g[a].pb({b,i});
        g[b].pb({a,i});
    }

    def (dfs, int x, int p) -> void {
        for (auto e : g[x]) {
            const int y = e.to;
            if (y == p) continue;
            dfs(y,x);
            if (v[y]) {
                swap(es[e.id].fst, es[e.id].snd);
                v[y] ^= 1;
                v[x] ^= 1;
            }
        }
    };
    dfs(0,-1);
    assert(count(all(v),1) == 0);

    rep (i,m) cout << es[i].fst+1 << " " << es[i].snd+1 << "\n";

}

