void Main(){
    int N,M; cin >> N >> M;
    vector<Edge> edge(M);
    VVI adj(N);
    map<P,int> m;
    REP(i,M){
        Edge e; cin >> e.from >> e.to; e.from--; e.to--;
        edge[i] = e;
        adj[e.from].push_back(e.to);
        adj[e.to].push_back(e.from);
        m[P(e.from,e.to)] = i;
        m[P(e.to,e.from)] = i;
    }

    VI d(N,INF);
    queue<P> que; que.emplace(0,0);
    while(!que.empty()){
        P p = que.front(); que.pop();
        if(d[p.first] < INF) continue;
        d[p.first] = p.second;
        for(int& e : adj[p.first]) que.emplace(e, p.second+1);
    }

    VI path(N,0);
    REP(i,M){
        Edge e = edge[i];
        if(d[e.from]-1 == d[e.to]) path[e.from] = e.to;
    }

    VI guki(N,0);
    REP(i,M) guki[edge[i].from] ^= 1;

    auto c = [&](int i, int j){return d[i]<d[j];};

    priority_queue<int,VI,decltype(c)> q(c); REP(i,N-1) if(guki[i+1] == 1) q.push(i+1);
    while(!q.empty()){
        int v = q.top(); q.pop();
        if(guki[v] == 0) continue;

        int to = path[v];
        int i = m[P(v,to)];
        guki[v] ^= 1;
        guki[to] ^= 1;
        edge[i].dir ^= 1;
        if(guki[to] == 1 && to!=0) q.push(to);
    }

    REP(i,N-1){
        if(guki[i+1] == 1){
            s = 1;
            return;
        }
    }

    if(guki[0] == 1) cout << -1 << en;
    else{
        REP(i,M){
            int from = edge[i].from+1, to = edge[i].to+1;
            if(edge[i].dir == 1) swap(from,to);
            cout << from << " " << to << en;
        }
    }
    return;
}

