const int maxn = 101010 * 2;
struct Edge{
    int x, y, nxt;
    int stu;
}e[maxn];
int head[maxn];
int siz[maxn];
int cnt_edge;

void addedge(int x, int y){
    e[cnt_edge].x = x;
    e[cnt_edge].y = y;
    e[cnt_edge].nxt = head[x];
    head[x] = cnt_edge;
    cnt_edge ++;
    e[cnt_edge].x = y;
    e[cnt_edge].y = x;
    e[cnt_edge].nxt = head[y];
    head[y] = cnt_edge;
    cnt_edge ++;
}

void dfs(int x){
    // printf("%d\n", x);
    siz[x] = 0;
    for(int i = head[x]; ~i; i = e[i].nxt){
        if(siz[e[i].y] == 0) continue;
        e[i].stu = 1;
        e[i ^ 1].stu = -1;
        siz[e[i].y] --;
    }
    // return ;
    for(int i = head[x]; ~i; i = e[i].nxt){
        if(siz[e[i].y] == 0) continue;
        if(siz[e[i].y] & 1) continue;
        dfs(e[i].y);
    }
}

int main(){
    memset(head, -1, sizeof head);
    int n, m;
    scanf("%d%d", &n, &m);
    for(int i = 1; i <= m; i ++){
        int x, y;
        scanf("%d%d", &x, &y);
        addedge(x, y);
        siz[x] ++, siz[y] ++;
    }

    if(m & 1){
