using namespace std;

const int MAX_N = 100 * 1000, MAX_M = 100 * 1000;
vector<int> adjLis[MAX_N + 1], adjInd[MAX_N + 1], EdgeDir[MAX_N + 1];
bitset<MAX_N + 1> markVer, isOddDeg;
stack<int> path;

void dfs(int preVer, int v) {
    markVer[v] = true;
    int u;
    if (isOddDeg[v]) {
        path.push(v);
        if (path.size() > 1) {
            isOddDeg[v] = false;
            int w;
            while (path.size() > 1) {
                u = path.top();
                path.pop();
                w = path.top();
                for (int i = 0; i < adjLis[u].size(); i++) {
                    if (adjLis[u][i] == w) {
                        EdgeDir[u][i] = !EdgeDir[u][i];
                        EdgeDir[w][adjInd[u][i]] = !EdgeDir[w][adjInd[u][i]];
                        break;
                    }
                }
            }
            isOddDeg[w] = false;
            path.pop();
        }
    } else if (!path.empty())
        path.push(v);
    for (int i = 0; i < adjLis[v].size(); i++) {
        u = adjLis[v][i];
        if (!markVer[u])
            dfs(v, u);
    }
    if (!path.empty())
        if (!isOddDeg[v]) {
            path.pop();
            if (path.top() != preVer) {
                path.push(v);
                path.push(preVer);
            }
        } else
            path.push(preVer);
}

