        adjLis[B[i]].push_back(A[i]);
        adjInd[A[i]].push_back(adjLis[B[i]].size() - 1);
        adjInd[B[i]].push_back(adjLis[A[i]].size() - 1);
        EdgeDir[A[i]].push_back(true);
        EdgeDir[B[i]].push_back(false);
        isOddDeg[A[i]] = !isOddDeg[A[i]];
    }
