struct unionfind{
	vector<int> p;
	unionfind(int N){
		p = vector<int>(N, -1);
	}
	int root(int x){
		if (p[x] == -1){
			return x;
		} else {
			p[x] = root(p[x]);
			return p[x];
		}
	}
	bool same(int x, int y){
		return root(x) == root(y);
	}
	void unite(int x, int y){
		x = root(x);
		y = root(y);
		p[x] = y;
	}
};
int main(){
	int N, M;
	cin >> N >> M;
	unionfind UF(N);
	vector<vector<int>> E(N);
	vector<int> c(N, 0);
	vector<pair<int, int>> ans;
	for (int i = 0; i < M; i++){
		int A, B;
		cin >> A >> B;
		A--;
		B--;
		if (UF.same(A, B)){
			ans.push_back(make_pair(A, B));
			c[A] = 1 - c[A];
		} else {
			E[A].push_back(B);
			E[B].push_back(A);
			UF.unite(A, B);
		}
	}
	vector<int> deg(N);
	for (int i = 0; i < N; i++){
		deg[i] = E[i].size();
	}
