    for ( auto e : G[root] )
    {
        if ( visited[e.to] || e.to == par ) continue;

        visited[e.to] = true;

        dfs( e.to, root );
    }

    int remains = num_edges[root] - ( num_edges[root] % 2 );
    for ( auto e : G[root] )
    {
        if ( remains == 0 ) break;

        Direction &d = directions[e.idx];
        if ( d.is_defined() ) continue;

        d.from = root;
        d.to = e.to;

        num_edges[root]--;
        num_edges[e.to]--;

        remains--;
    }
}

void init( int N, int M )
{
    for ( int i = 0; i < N; i++ ) num_edges[i] = 0;
    for ( int i = 0; i < M; i++ ) directions[i] = {-1, -1};
}

int main( int argc, char **argv )
{
    int N, M;
    cin >> N >> M;

    init( N, M );

    for ( int i = 0; i < M; i++ )
    {
        int A, B;
        cin >> A >> B;

        add_edge( A - 1, B - 1, i );
    }

    if ( M % 2 == 1 ) { cout << -1 << endl; }
    else
    {
        dfs( 0, -1 );

        for ( int i = 0; i < M; i++ )
        {
            cout << ( directions[i].from + 1 );
            cout << " ";
            cout << ( directions[i].to + 1 );
            cout << endl;
        }
    }

    return 0;
}

