int main()
{
    int N, M; cin >> N >> M;
    if (M % 2 != 0) {
        cout << -1 << endl;
        return 0;
    }
    vector<map<int, int>> G(N);
    vector<int> number(N, 1e9);
    for (int i = 0; i < M; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a][b] = G[b][a] = 0;
    }
    vector<int> I;
    int t = 0;
    function<void(int)> recur = [&](int node) {
        number[node] = t++;
        for (auto &p : G[node]) {
            if (number[p.first] > number[node]) recur(p.first);
        }
        I.push_back(node);
    };
    recur(0);
    for (int node : I) {
        int plus = 0;
        int zero = 0;
        for (auto &p : G[node]) {
            if (p.second == +1) plus++;
            else if (p.second == 0 && number[p.first] > number[node]) {
                p.second = +1;
                G[p.first][node] = -1;
                plus++;
            } else if (p.second == 0) zero++;
        }
        if ((plus + zero) % 2 == 1) zero--;
        for (auto &p : G[node]) {
            if (p.second == 0 && zero) {
                p.second = +1;
                G[p.first][node] = -1;
                zero--;
            }
        }
    }
    for (int node = 0; node < N; node++) {
        for (auto &p : G[node]) {
            if (p.second == +1) {
                cout << node+1 << ' ' << p.first+1 << '\n';
            }
        }
    }
    return 0;
}

