#include <bits/stdc++.h>
using namespace std;
using pii = pair<int, int>;

vector<int> adj[100009];
int d[100009], o[100009];

struct info { int v; };

bool operator <(info PP, info QQ) {
	return d[PP.v] < d[QQ.v];
}

set<info> st;
set<pii> edg;

int main() {
	int N, M; scanf("%d%d",&N,&M);
	for(int i=1; i<=M; i++) {
		int u, v; scanf("%d%d",&u,&v);
		++d[u]; ++d[v];
		adj[u].push_back(v);
		adj[v].push_back(u);
		edg.insert({u, v});
		edg.insert({v, u});
	}
	for(int i=1; i<=N; i++) {
		st.insert({i});
	}
	vector<pii> ans;
	while(M--) {
		int now = (*st.begin()).v;
		st.erase({now});
		int it;
		while(1) {
			if(adj[now].empty()) return !printf("-1");
			it = adj[now].back(); adj[now].pop_back();
			if(edg.find({now, it}) != edg.end()) {
				edg.erase({now, it});
				edg.erase({it, now});
				break;
			}
		}
		st.erase({it});
		--d[now]; --d[it];
		if(o[now] & 1) {
			++o[now];
			ans.push_back({now, it});
		}
		else {
			++o[it];
			ans.push_back({it, now});
		}
		if(d[now]) st.insert({now});
		if(d[it]) st.insert({it});
	}
	for(int i=1; i<=N; i++) if(o[i] & 1) return !printf("-1");
	for(auto& it: ans) printf("%d %d\n", it.first, it.second);
	return 0;
}

