int main() {
    li n, m;
    cin >> n >> m;
    rep(i, m) {
        li a, b;
        cin >> a >> b;
        a--;
        b--;
        edges[a].insert(b);
        edges[b].insert(a);
    }
    if (m % 2 > 0) {
        puts("-1");
        return 0;
    }


    priority_queue<PI> pq;
    rin{
        if (sz(edges[i]) > 1) {
            pq.push({ -sz(edges[i]), i});
        }
    }

    while (!pq.empty()) {
        li now = pq.top().S;
        pq.pop();
        if (visited[now]) {
            continue;
        }
        //p2(now, sz(edges[now]));
        visited[now] = true;
        if (sz(edges[now]) < 2) {
            puts("-1");
            return 0;
        }

        vector<PI> p;
        for (auto && next : edges[now]) {
            p.pb({sz(edges[next]), next});
        }
        sort(allof(p));
        reverse(allof(p));
        rep(i, sz(p) / 2) {
            rep(j, 2) {
                li next = p[i * 2 + j].S;
                res.pb({now + 1, next + 1});
                edges[next].erase(now);
                edges[now].erase(next);
                if (sz(edges[next]) > 1) {
                    pq.push({ -sz(edges[next]), next});
                } else {
                    visited[next] = true;
                }
            }
        }
    }
