/*
M should be divisible by 2.

I first build the dfs-tree, now each edge is oriented towards the bottom
*/
int const nmax = 100000;
std::vector<int> g[1 + nmax];
std::vector<std::pair<int,int>> sol;
int seen[1 + nmax], dp[1 + nmax];
int in_stack[1 + nmax];

void dfs(int node, int parent) {
  seen[node] = 1;
  in_stack[node] = 1;
  for(int h = 0; h < g[node].size(); h++) {
    int to = g[node][h];
    if(to == parent)
      continue;
    if(seen[to] == 0) {
      dfs(to, node);
    } else if(in_stack[to] == 1) {
      dp[to] ^= 1;
      sol.push_back({to, node});
    }
  }
  in_stack[node] = 0;
  if(parent == 0)
    return ;
  if(dp[node] == 1) {
    sol.push_back({node, parent});
    dp[node] ^= 1;
  } else {
    sol.push_back({parent, node});
    dp[parent] ^= 1;
  }
}

int main() {
  int n, m;
  std::cin >> n >> m;
  for(int i = 1; i <= m; i++) {
    int x, y;
    std::cin >> x >> y;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  if(m % 2 == 0) {
    dfs(1, 0);
    for(int i = 0; i < sol.size(); i++)
      std::cout << sol[i].first << " " << sol[i].second << '\n';
  } else
    std::cout << -1;
  return 0;
}

