vector<pair<int, int>> g[100005], gmst[100005];
vector<pair<int, int>> edges, resedges;
int outdeg[100005];
bool inmst[100005];
int dsu[100005];

int dfind(int x) { return x == dsu[x] ? x : dsu[x] = dfind(dsu[x]); }
void dmerge(int u, int v) {
	u = dfind(u), v = dfind(v);
	if (u == v) return;
	dsu[u] = v;
}

void dfs(int n, int p = -1) {
	//printf("%d -> %d\n", p, n);
	// edge info to parent
	pair<int, int> hint;
	for (auto c : gmst[n]) if (c.first != p) dfs(c.first, n); else hint = c;
	// post-process
	if (p != -1) {
		int eid = hint.second;
		if (outdeg[n] % 2 == 1) {
			// choose up
			resedges[eid] = {n, p};
			outdeg[n]++;
		} else {
			resedges[eid] = {p, n};
			outdeg[p]++;
		}
	}
}

int main() {
	cin.tie(0)->sync_with_stdio(0);
	cin.exceptions(cin.failbit);

	int n, m; read(n, m);

	if (m % 2 == 1)
		die(-1);

	rep(i, 0, 100005) dsu[i] = i;
	edges = vector<pair<int, int>>(m);
	resedges = vector<pair<int, int>>(m);

	for (int i = 0; i < m; i++) {
		read(edges[i].first, edges[i].second);
		g[edges[i].first].push_back({edges[i].second, i});
		g[edges[i].second].push_back({edges[i].first, i});
	}

	// calculate mst
	rep(i, 0, m) {
		if (dfind(edges[i].first) != dfind(edges[i].second)) {
			dmerge(edges[i].first, edges[i].second);
			gmst[edges[i].first].push_back({edges[i].second, i});
			gmst[edges[i].second].push_back({edges[i].first, i});
			inmst[i] = true;
		}
	}

	// arbitrary edges 
	rep(i, 0, m) if (!inmst[i]) {
		outdeg[edges[i].first]++;
		resedges[i] = edges[i];
	}

	// other edges
	dfs(1);

	rep(i, 0, m) write(resedges[i].first, resedges[i].second);
}

