int rt=-1;
void dfs(int u,int f)
{
	vis[u]=1;
	for(int i=0;i<G[u].size();i++)
	{
		int v=G[u][i];
		if(vis[v]||v==f) continue;
		T[u].push_back(v);
		T[v].push_back(u);
		dfs(v,u);
	}
}
int Find(int x)
{
	if(ft[x]==x)
		return x;
	return ft[x]=Find(ft[x]);
}
bool Union(int x,int y)
{
	int u=Find(x),v=Find(y);
	if(u==v) return 0;
	if(u>v) ft[u]=v;
	else ft[v]=u;
	return 1;	
}
void dfs2(int u,int f)
{
	//printf("%d\n",u);
	for(int i=0;i<T[u].size();i++)
	{
		int v=T[u][i];
		if(v==f) continue;
		dfs2(v,u);
	}
	if(u==rt) return ;
	if(d[u]&1) ans[++cnt].u=u,ans[cnt].v=f,d[u]++;
	else ans[++cnt].u=f,ans[cnt].v=u;
}
void Init()
{
	for(int i=1;i<=n;i++)
		ft[i]=i;
	int tot=0;
	for(int i=1;i<=m;i++)
	{
		if(Union(edge[i].u,edge[i].v))
		{
			T[edge[i].u].push_back(edge[i].v);
			T[edge[i].v].push_back(edge[i].u);
			if(rt==-1) rt=edge[i].u;
			vis[i]=1;
			tot++;
		}
		if(tot==n-1) break;
	}
	cnt=0;
	for(int i=1;i<=m;i++)
		if(!vis[i])
		{
			ans[++cnt].u=edge[i].u,ans[cnt].v=edge[i].v;
			d[edge[i].u]++;
		}
	dfs2(rt,-1);
}
