int solve(int s) {
  int ret = 0;
  queue<int> que;
  for (int i = 0; i < MAX; i++) {
    color[i] = WHITE;
  }

  que.push(s);

  int counter = 0;

  while (!que.empty()) {
    int u = que.front();
    que.pop();
    if (color[u] == BLACK) continue;
    int adjNum = 0;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j];
      if (color[v] == WHITE) adjNum++;
    }
    int base;
    if (adjNum % 2 == 0) {
      base = adjNum;
    } else base = adjNum - 1;
    if (base != 0) color[u] = BLACK;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j];
      if (color[v] == BLACK) continue;
      que.push(v);
      if (base > 0) {
        ans.pb(make_pair(u, v));
        base--;
        ret++;
      }
    }
  }
  return ret;
};

