class graph {
  public:
    graph(int n) {
        v.resize(n);
        send.resize(n);
        receive.resize(n);
    }

    vector<vector<int>> v;
    vector<vector<int>> send;
    vector<vector<int>> receive;
};

int main() {
    // source
    int n, m;
    cin >> n >> m;

    graph g(n + 1);

    rep(i, m) {
        int a, b;
        cin >> a >> b;
        g.v[a].push_back(b);
        g.v[b].push_back(a);
    }
    if (m % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    rep(i, n + 1) {
        if (g.v[i].size() == 1) {
            g.receive[i].push_back(g.v[i][0]);
            g.send[g.v[i][0]].push_back(i);
        }
    }

    rep(i, n + 1) {
        if (g.v[i].size() == g.send[i].size() + g.receive[i].size()) {
            continue;
        }

        if (g.send[i].size() % 2 == 0) {
            rep(j, g.v[i].size()) {
                auto iter0 =
                    find(g.send[i].begin(), g.send[i].end(), g.v[i][j]);
                auto iter1 =
                    find(g.receive[i].begin(), g.receive[i].end(), g.v[i][j]);

                if (iter0 == g.send[i].end() && iter1 == g.receive[i].end()) {
                    g.receive[i].push_back(g.v[i][j]);
                    g.send[g.v[i][j]].push_back(i);
                }
            }
        } else {

            rep(j, g.v[j].size()) {
                auto iter0 =
                    find(g.send[i].begin(), g.send[i].end(), g.v[i][j]);
                auto iter1 =
                    find(g.receive[i].begin(), g.receive[i].end(), g.v[i][j]);

                if (iter0 == g.send[i].end() && iter1 == g.receive[i].end()) {
                    g.send[i].push_back(g.v[i][j]);
                    g.receive[g.v[i][j]].push_back(i);
                    break;
                }
            }
        }
    }

    rep(i, n + 1) {
        int a = i;
        rep(j, g.send[i].size()) { cout << a << " " << g.send[i][j] << endl; }
    }

    return 0;
}

ll comb(ll a, ll b) {
    if (a < b) {
        return 0;
    }

    ll v[a + 1][a + 1] = {};

    rep(i, a + 1) {
        v[i][0] = 1;
        v[i][i] = 1;
    }

    repd(k, 2, a + 1) {
        repd(j, 1, k) { v[k][j] = v[k - 1][j - 1] + v[k - 1][j]; }
    }

    return v[a][b];
}

