vector<int> outdeg;
void dfs(int u,int e){
	vis[u] = true;
	for(auto v:adj[u])
	if(v!=e){
		if(!vis[v]){
			child[u].push_back(v);
			outdeg[u]++;
			dfs(v,u);
		}
		else{
			if(edges.count({u,v})==0&&edges.count({v,u})==0)
			{
				edges.insert({u,v});
				outdeg[u]++;
			}
		}
	}
}
void assdir(int u,int e){
	for(auto v:child[u])
	{
		assdir(v,u);
	}
	if(e!=-1)
	{
		if(outdeg[u]&1){
			outdeg[u]+=1;
			outdeg[e]-=1;
			edges.insert({u,e});
		}
		else edges.insert({e,u});
	}
}
