using namespace std;

void solve(int N, vector<vector<int>>& E)
{
	vector<char>used(N);
	vector<int>level(N);
	vector<int>output(N);

	priority_queue<pair<int, int>>Q;
	for (int i = 0; i < N; i++)
	{
		Q.push(make_pair(E[i].size() % 2, i));
		level[i] = E[i].size() % 2;
	}

	vector<pair<int, int>>ans;
	while (Q.size())
	{
		int l = Q.top().first;
		int v = Q.top().second; Q.pop();
		if (used[v])continue;
		if (level[v] != l)continue;
		used[v] = true;

		for (int j = 0; j < E[v].size(); j++)
		{
			int u = E[v][j];
			if (used[u])continue;

			if (l)
			{
				output[u]++;
				ans.push_back(make_pair(u + 1, v + 1));
				l--;
			}
			else
			{
				level[u] ^= 1;
				output[v]++;
				ans.push_back(make_pair(v + 1, u + 1));
			}

			Q.push(make_pair(level[u], u));
		}
	}

	bool flag = true;
	for (int i = 0; i < N; i++)
	{
		if (output[i] % 2 != 0)flag = false;
	}

	if (flag)
	{
		for (int i = 0; i < ans.size(); i++)
		{
			cout << ans[i].first << " " << ans[i].second << endl;
		}
	}
	else
	{
		cout << -1 << endl;
		return;
	}
}

int main()
{
	int N, M; cin >> N >> M;
	vector<vector<int>>E(N);
	for (int i = 0; i < M; i++)
	{
		int a, b; cin >> a >> b;
		a--; b--;

		E[a].push_back(b);
		E[b].push_back(a);
	}

	if (M % 2)
	{
		cout << -1 << endl;
		return 0;
	}

	solve(N, E);

	return 0;
}

