		int it;
		while(1) {
			it = adj[now].back(); adj[now].pop_back();
			if(edg.find({now, it}) != edg.end()) {
				edg.erase({now, it});
				edg.erase({it, now});
				break;
			}
		}
		st.erase({it});
		--d[now]; --d[it];
		if(o[now] & 1) {
			++o[now];
			ans.push_back({now, it});
		}
		else {
			++o[it];
			ans.push_back({it, now});
		}
		if(d[now] > 0) st.insert({now});
		if(d[it] > 0) st.insert({it});
	}
	for(int i=1; i<=N; i++) if((o[i] & 1) || d[i] != 0) return !printf("-1");
	if((int)ans.size() != M) return !printf("-1");
	for(auto& it: ans) printf("%d %d\n", it.first, it.second);
	return 0;
}

