        {
            int next = tree[now];
            if (next == -1) continue;
            if (count[now] % 2 == 0) update(next, now);
            else update(now, next);
            if (check[tree[now]]) explore.push(tree[now]);
            check[tree[now]] = false;
            treeCount[tree[now]]--;
        }
        auto temp = G[now];
        for (auto next : temp) update(next, now);
    }
