void solve(vector<set<int>>& g, vector<set<int>>& res){
  ll n = g.size();


  rep(i, n){
    if(g[i].size() == 1){
      int to = *g[i].begin();
      g[i].erase(to);
      g[to].erase(i);
      res[to].insert(i);
      i = min(i, to-1);
    }
  }

  rep(i, n){
    if(2 <= g[i].size()){
      int to = *g[i].begin();
      g[i].erase(to);
      g[to].erase(i);
      res[to].insert(i);
      return solve(g, res);
    }
  }
  return;
}


