		int a = in--, b = in--;
		g[a].pb(b);
		g[b].pb(a);
		edges[i] = mp(a, b);
	}

	if (m % 2 == 1) {
		out.exit(-1);
	}

	VI parent; VP depth;
	tie(parent, depth) = SpanningTree(g, 0);
	RSort(depth);

	VI cnt(n); VB used(m);
	rep(i, m) {
		auto e = edges[i];
		if (parent[e.first] != e.second && parent[e.second] != e.first) {
			out(e.first + 1, e.second + 1);
			used[i] = true;
			cnt[e.first]++;
		}
	}

	rep(i, n - 1) {
		int e = depth[i].second;
		if (cnt[e] % 2 == 0) {
			out(parent[e] + 1, e + 1);
			cnt[parent[e]]++;
		} else {
			out(e + 1, parent[e] + 1);
			cnt[e]++;
		}
	}
}

