    queue<int> que;
    que.push(0);

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (auto sv : graph[v]) {
            if (rank[sv] >= 0) continue;
            rank[sv] = rank[v] + 1;
            que.push(sv);
