	auto itr = edges.begin();
	while (itr != edges.end()) {
		int u = itr->first, v = itr->second;
		if (same(u, v)) { score[u] ^= 1; itr++; ans.push_back({ u,v }); }
		else {
			G[u].push_back(v);
			unite(u, v);
			itr++;
		}
	}
	dfs(0, 0);
	if (score[0] & 1) {
		print(-1); return;
	}
