#define K 300001

int n, m;
vector<int> nxt[K];

vector<pair<int, int> > res;

int visited[K];
int deg[K];

int DFS(int u, int par) {
    visited[u] = 1;
    deg[u] = 0;

    FOR(i, 0, nxt[u].size()) {
        int t = nxt[u][i];

        if (t == par) continue;
        if (visited[t]) {
            if (u > t) {
                deg[u]++;
                res.pb(mp(u, t));
            }
        } else {
            int sol = DFS(t, u);

            if (sol % 2) {
                res.pb(mp(t, u));
            } else {
                deg[u]++;
                res.pb(mp(u, t));
            }
        }
    }

    return deg[u] % 2;
}

int main() {
    scanf("%d%d", &n, &m);

    FOE(i, 1, m) {
        int u, v; scanf("%d%d", &u, &v);

        nxt[u].pb(v);
        nxt[v].pb(u);
    }

    if (m % 2) {
        puts("-1");
        return 0;
    }

    DFS(1, -1);

    FOE(i, 1, m) printf("%d %d\n", res[i - 1].first, res[i - 1].second);
}

