int ts[101010];
int timestamp = 0;

void dfs(Graph &G, vector<int> &visit, vector<int> &ord, int now){
    visit[now] = 1;
    repe(i, G[now]){
        if(!visit[i.first]){
            dfs(G, visit, ord, i.first);
        }
    }
    ord.push_back(now);
    ts[now] = timestamp++;
}


int main(){
    int n, m;
