        cout << -1 << endl;
        return 0;
    }
    rep(i, n) rem[i] = G[i].size();

    vector<int> visit(n, 0), ord;
    dfs(G, visit, ord, 0);
    // repe(i, ord){
    //     cout << i+1 << endl;
    // }

    vector<pair<int, int>> ans;
    repe(i, ord){
        while(rem[i] >= 2){
            deque<pair<int, int>> select;
            repe(j, G[i]){
                if(used[j.second]) continue;
                if(ts[j.first] < ts[i]) select.push_front(j);
                else select.push_back(j);
            }
            // repe(j, select){
            //     cout << i << " " << j.first << " / ";
            // }
            // cout << endl;
            if(select.size() < 2){
                cout << -1 << endl;
