            repe(j, select){
                used[j.second] = 1;
                ans.emplace_back(i, j.first);
                rem[i]--;
                rem[j.first]--;
                if(++tmp >= 2) break;
            }
        }
    }
    repe(i, ans){
        cout << i.first+1 << " " << i.second+1 << endl;
    }

}

