signed main() {
    int N, M;
    cin >> N >> M;
    vector<set<int>> G(N + 1);
    vector<int> count(N + 1, 0);
    for (int i = 0; i < M; i++) {
        int A, B;
        cin >> A >> B;
        G[A].insert(B);
        G[B].insert(A);
        count[A]++;
        count[B]++;
    }
    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }
    set<int> odd, remain;
    for (int i = 1; i <= N; i++) {
        if (count[i] % 2 == 1) odd.insert(i);
        remain.insert(i);
    }
    vector<int> twoOut(N + 1, 0);
    vector<pair<int, int>> ans;
    auto update = [&](int from, int to) {
        ans.emplace_back(from, to);
        twoOut[from]++;
        count[from]--;
        count[to]--;
        G[from].erase(to);
        G[to].erase(from);
        if (count[from] % 2 == 0) odd.erase(from);
        else odd.insert(from);
        if (count[to] % 2 == 0) odd.erase(to);
        else odd.insert(to);
        if (count[from] == 0) remain.erase(from);
        if (count[to] == 0) remain.erase(to);
    };
    while (!remain.empty()) {
        if (!odd.empty()) {
            int now = *odd.begin();
            int to = *G[now].begin();
            if (twoOut[now] % 2 == 0) update(to, now);
            else update(now, to);
            continue;
        }
        int now = *remain.begin();
        int to = *G[now].begin();
        update(now, to);
    }
    for (auto temp : ans) {
        cout << temp.first << " " << temp.second << endl;
    }
}

