using namespace std;
int N, M;
vector<pair<int, int> > edges, result;
int total_deg[101010], out_deg[101010];
int assert_out_deg[101010];
int main(){
	cin >> N >> M;
	for(int i = 0; i < M; i++){
		int A, B;
		cin >> A >> B;
		edges.push_back(make_pair(min(A, B), max(A, B)));
		total_deg[A]++, total_deg[B]++;
	}
	if(M % 2 == 1)return cout << -1 << '\n', 0;

	sort(edges.begin(), edges.end());
	for(int i = 0; i < M; i++){
		int A = edges[i].first;
		int B = edges[i].second;

		if((total_deg[B] == 1 && out_deg[B] == 1) || (total_deg[A] == 1 && out_deg[A] == 0)){
			result.push_back(make_pair(B, A));
			total_deg[A] --;
			total_deg[B] --;
			out_deg[B] = (out_deg[B] + 1) % 2;
		}
		else if((out_deg[A] == 1 && total_deg[A] == 1) || (out_deg[B] == 0 && total_deg[B] == 1)){
			result.push_back(make_pair(A, B));
			total_deg[A] --;
			total_deg[B] --;
			out_deg[A] = (out_deg[A] + 1) % 2;
		}
		else if(out_deg[A] == 0 && out_deg[B] == 1){
			result.push_back(make_pair(B, A));
			total_deg[A] --;
			total_deg[B] --;
			out_deg[B] = (out_deg[B] + 1) % 2;
		}
		else{
			result.push_back(make_pair(A, B));
			total_deg[A] --;
			total_deg[B] --;
			out_deg[A] = (out_deg[A] + 1) % 2;
		}
	}
	for(int i = 0; i < M; i++){
		assert_out_deg[result[i].first] ^= 1;
	}
	for(int i = 1; i <= N; i++){
		assert(assert_out_deg[i] == 0);
	}

	for(int i = 0; i < M; i++){
		cout << result[i].first << " " << result[i].second << "\n";
	}
}

