{
	int to,p,nxt;
}e[1000001];
int head[1000001];
void add_edge(int u,int v)
{
	e[++edge_num].to=v;
	e[edge_num].nxt=head[u];
	head[u]=edge_num;
}
int vis[1000001];
int out[1000001];
void dfs(int u,int fa)
{
	vis[u]=1;
	vector<int>v;
	for(int i=head[u];i!=-1;i=e[i].nxt)
	{
		int to=e[i].to;
		if(vis[to]==0)
		{
			v.push_back(i);
			dfs(to,u);
		}
		else if(e[i].p==0&&to!=fa)
		{
			e[i].p=1;
			e[i^1].p=-1;
			out[u]++;
		}
	}
	for(int i=0;i<v.size();i++)
	{
		int x=v[i];
		if(out[e[x].to]%2==1)
			e[x^1].p=1,e[x].p=-1;
		else
			e[x].p=1,e[x^1].p=-1,out[u]++;
	}
}
