        if(u > v) swap(u, v);
        deg[u]++;
        deg[v]++;
        edge_list[u].push_back(i);
        edge_list[v].push_back(i);
        edges.push_back({u, v});
    }

    if(m % 2) {
        cout << "-1\n";
        return 0;
    }

    vector<int> verts(n);
    iota(verts.begin(), verts.end(), 1);
