using namespace std;

struct Unionfind {
  // tree number
  vector<int> par;
  // tree rank
  vector<int> treerank;
  // constructor
  Unionfind(int n = 1) { stree(n + 1); }
  // make and initialization
  void stree(int n = 1) {
    par.assign(n, -1);
    treerank.assign(n, 0);
  }
  // search root
  int root(int x) {
    if(par[x] < 0) return x;
    return par[x] = root(par[x]);
  }
  // is same?
  bool issame(int x, int y) { return root(x) == root(y); }

  // add
  // already added, return 0
  bool uni(int x, int y) {
    x = root(x);
    y = root(y);
    if(x == y) return 0;
    if(treerank[x] > treerank[y]) swap(x, y);
    if(treerank[x] == treerank[y]) ++treerank[y];
    par[y] -= size(x);
    par[x] = y;
    return 1;
  }
  int size(int x) { return -par[root(x)]; }
};

struct data {
  int from, to;
};

bool operator<(const data &l, const data &r) {
  if(l.from != r.from) return l.from < r.from;
  return l.to < r.to;
}

int n, m;
set<int> edge[100005];
vector<bool> num;
vector<data> ans;
queue<int> qu;
Unionfind uf;

void solve();
bool bfs();

int main() {
  cin >> n >> m;
  num.assign(n, 0);
  uf = Unionfind(n);
  for(int i = 0; i < m; ++i) {
    int a, b;
    cin >> a >> b;
    if(!uf.issame(--a, --b)) {
      uf.uni(a, b);
      edge[a].insert(b);
      edge[b].insert(a);
    }
    else {
      ans.push_back({a, b});
      num[a] = !num[a];
    }
  }
  if(m % 2)
    cout << -1 << endl;
  else {
    solve();
    for(int i = 0; i < m; ++i)
      cout << ans[i].from + 1 << " " << ans[i].to + 1
           << endl;
  }
  return 0;
}

void solve() {
  for(int i = 0; i < n; ++i)
    if(edge[i].size() == 1) qu.push(i);
  bfs();
}

bool bfs() {
  while(!qu.empty()) {
    int now = qu.front();
    qu.pop();
    if(edge[now].size() == 0) {
      if(num[now]) {
        ans.erase(ans.begin(), ans.end());
        return 0;
      }
      continue;
    }
    vector<int> tmp;
    for(auto to : edge[now]) tmp.push_back(to);
    int tsize = tmp.size();
    for(int j = 0; j < tsize; ++j) {
      int to = tmp[j];
      if(num[now]) {
        ans.push_back({now, to});
        num[now] = 0;
      }
      else {
        ans.push_back({to, now});
        num[to] = !num[to];
      }
      edge[now].erase(to);
      edge[to].erase(now);
      if(edge[to].size() == 1) qu.push(to);
    }
  }
  return 1;
}

