/* constant */

const int MAX_N = 100000;
const int MAX_M = 100000;

/* typedef */

typedef long long ll;
typedef vector<int> vi;
typedef queue<int> qi;
typedef pair<int,int> pii;
typedef vector<pii> vpii;

/* global variables */

int ps[MAX_N], pes[MAX_N], cns[MAX_N];
vpii nbrs[MAX_N];
pii es[MAX_M];
bool vused[MAX_N], eused[MAX_M], ens[MAX_N];

/* subroutines */

/* main */

int main() {
  int n, m;
  scanf("%d%d", &n, &m);

  if (m & 1) {
    puts("-1");
    return 0;
  }

  for (int i = 0; i < m; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    a--, b--;
    nbrs[a].push_back(pii(b, i));
    nbrs[b].push_back(pii(a, i));
    es[i] = pii(a, b);
  }

  ps[0] = pes[0] = -1;
  vused[0] = true;
  qi q;
  q.push(0);

  while (! q.empty()) {
    int u = q.front(); q.pop();
    int &up = ps[u];
    vpii &nbru = nbrs[u];

    for (vpii::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
      int &v = vit->first, &ei = vit->second;
      if (v != up) {
	if (vused[v]) {
	  if (! eused[ei]) {
	    //printf(" %d(%d,%d)\n", ei, es[ei].first, es[ei].second);
	    ens[es[ei].first] ^= 1;
	    eused[ei] = true;
	  }
	}
	else {
	  cns[u]++;
	  ps[v] = u;
	  pes[v] = ei;
	  vused[v] = true;
	  q.push(v);
	}
      }
    }
  }

  //for (int u = 0; u < n; u++)
  //printf("%d %d %d %d\n", u, ps[u], pes[u], ens[u]);

  for (int u = 0; u < n; u++)
    if (cns[u] == 0) q.push(u);

  while (! q.empty()) {
    int u = q.front(); q.pop();
    int &up = ps[u], &ep = pes[u];

    if (up >= 0) {
      if (ens[u])
	es[ep] = pii(u, up), ens[u] ^= 1;
      else
	es[ep] = pii(up, u), ens[up] ^= 1;

      if (--cns[up] == 0) q.push(up);
    }
  }  

  for (int i = 0; i < m; i++)
    printf("%d %d\n", es[i].first + 1, es[i].second + 1);
  return 0;
}

