            //assert(Nyuji[e_to] >= 0);
            //assert(Nyuji[node] >= 0);
            isEdgeUsed[e_id] = true;
        }
    }

    // 次数が偶数のものへ移動
    for(auto& e_to : graph[node]) {
        if(Nyuji[e_to] % 2 == 0 && !isNodeUsed[e_to]) {
            dfs(e_to);
        }
    }
}

