template<typename T>
struct LinearSystemIncidence {
  struct Edge {
    int id, to;
    bool fwd;
    Edge(int i, int t, bool f) : id(i), to(t), fwd(f) {}
  };

  int n, m;
  vector<T> x;
  vector<bool> seen;
  vector<vector<Edge>> G;

  LinearSystemIncidence(int n, vector<pair<int, int>> &E) : n(n), m(E.size()), G(n) {
    for (int i = 0; i < m; ++i) {
      G[E[i].first].emplace_back(i, E[i].second, true);
      G[E[i].second].emplace_back(i, E[i].first, false);
    }
  }

  T dfs(vector<T> &b, int u) {
    seen[u] = true;
    T res = b[u];
    for (Edge e : G[u]) {
      if (seen[e.to]) continue;
      T tmp = dfs(b, e.to);
      x[e.id] = tmp * (e.fwd ? 1 : -1);
      x[e.id] %= 2;
      if (x[e.id] < 0) x[e.id] += 2;
      res += tmp;
    }
    return res;
  }

  pair<bool, vector<T>> solve(vector<T> &b) {
    x.assign(m, 0);
    seen.assign(n, false);
    for (int s = 0; s < n; ++s) {
      if (seen[s]) continue;
      if (dfs(b, s)%2) return make_pair(false, vector<T>());
    }
    return make_pair(true, move(x));
  }
};


