int n, m; 
vector<int> g[100100], h[100100];
int depth[100100], cnt[100100];

void dfs(int v, int d, int p) {
    depth[v] = d;
    for(auto& nv: g[v]) {
        if(nv == p) continue;
        if(depth[nv] != -1 && depth[nv] <= d + 1) {
            h[nv].push_back(v);
            cnt[nv] ++;
        }
        if(depth[nv] == -1) dfs(nv, d + 1, v);
    }
    if(p == -1) return;
    if(cnt[v] % 2 == 0) {
        cnt[p] ++;
        h[p].push_back(v);
    } else {
        cnt[v] ++;
        h[v].push_back(p);
    }
}

void solve() {
	cin >> n >> m;
