    }
    rep(i, m) {
        int a, b; cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    rep(i, 100100) {
        depth[i] = -1;
        cnt[i] = 0;
    }
    dfs(0, 0, -1);
    rep(v, n) {
        for(auto nv: h[v]) {
            cout << v + 1 << " " << nv + 1 << endl;
        }
    }
}

