#include <bits/stdc++.h>
using namespace std;
const int N = 1e5+3;
vector <pair <int,int> > adj[N];
int outdeg[N], deg[N];
bool vis[N], ck[N];
int n, m;
int E = 0;
vector <pair <int,int> > ans;

void dfs(int u)
{
	E += adj[u].size();
	vis[u] = true;
	for(auto v : adj[u])
	{
		int ver = v.first;
		if(vis[ver] == true)
			continue;
		dfs(ver);
	}
}

queue <int> q;
void solve(int s)
{
	q.push(s);
	vis[s] = true;
	while(q.size() > 0)
	{
		int u = q.front();
		q.pop(); 
		for(auto v:adj[u])
		{
			int ver = v.first,
				nedge = v.second;

			if(ck[nedge] == true)
				continue;

			if(deg[u] % 2 == 1 && (deg[u] - outdeg[u]) % 2 == 1)
			{
				outdeg[ver]++;
				deg[u]--;
				ans.push_back({ver, u});
			}

			else
			{
				outdeg[u]++;
				deg[ver]--;
				ans.push_back({u, ver});
			}

			if(vis[ver] == false)
			{
				ck[nedge] = true;
				vis[ver] = true;
//				deg[ver]--;
				q.push(ver);
			}
			ck[nedge] = true;
		}
	}
}	

int main()
{
	int res = 1;
	cin >> n >> m;
	for(int i=1;i<=m;i++)
	{
		int x, y;
		cin >> x >> y;
		deg[x]++, deg[y]++;
		adj[x].push_back({y, i});
		adj[y].push_back({x, i});
	}

	for(int i=1;i<=n;i++)
	{	 
		if(vis[i] == true)
			continue;
		E = 0;
		dfs(i);
		E /= 2;
//		cout << E << '\n';
		res = res & ((E % 2) == 0);
	}
	memset(vis, 0, sizeof(vis));
	if(res == 0)
		return cout << -1, 0;
	else
	{
		for(int i=1;i<=n;i++)
		{
			if(vis[i] == false)
				solve(i);
		}
		for(auto u:ans)
		{
			cout << u.first << ' ' << u.second << '\n';
		}
	}
}

