#include <stdio.h>
#include <vector>
#include <set>
#include <map>

void decrement(int node, std::vector<std::set<int>> &edges, std::map<int, std::set<int>> &degree_by){
	int size = edges[node].size();
	if(size == 0){
		printf("Fatal error: Tried to erase empty (node %d)\n", node);
		throw "??";
	}
	degree_by[size].erase(node);
	if(degree_by[size].empty()) degree_by.erase(size);
	degree_by[size-1].insert(node);
}

int main(void){

	// Input
	int v, e; scanf("%d %d", &v, &e);
	std::vector<std::set<int>> edges(v+1);
	for(int i=0; i<e; i++){
		int a1, a2; scanf("%d %d", &a1, &a2);
		edges[a1].insert(a2);
		edges[a2].insert(a1);
	}

	// If edge num is odd -> Impossible
	if(e%2 == 1){
		printf("-1");
		return 0;
	}

	// Degree sorting - careful update
	std::map<int, std::set<int>> degree_by;
	for(int i=1; i<=v; i++) degree_by[edges[i].size()].insert(i); 

	// Go search
	int currentsaved = 0, targetsaved = e; // initial 2e
	std::vector<std::vector<int>> saveddegree(v+1);
	while(currentsaved < targetsaved){

		// Pop minimal from degree_by
		auto lowest = degree_by.begin();
		int thisdegree = lowest->first;
		int thisnode = *(lowest->second.begin());
		lowest->second.erase(thisnode);
		if(lowest->second.empty()) degree_by.erase(thisdegree);

		// Set target degree
		int targetdegree = (saveddegree[thisnode].size() % 2);
		if(targetdegree == 1 && edges[thisnode].size() == 0){
			printf("Unknown case\n");
			throw "??";
		}
		/*if(targetsaved - currentsaved < thisdegree - targetdegree){ // If too much removal
			targetdegree = thisdegree - (targetsaved - currentsaved);
			if(targetdegree % 2 != saveddegree[thisnode].size() % 2) targetdegree++;
		}*/

		// Removing random edges to make incoming edges
		while(edges[thisnode].size() > targetdegree){
			int anydest = *edges[thisnode].begin(); // Make thisnode <- anydest
			decrement(anydest, edges, degree_by);
			edges[thisnode].erase(anydest);
			edges[anydest].erase(thisnode);
			saveddegree[anydest].push_back(thisnode);
			currentsaved++;
		}
		// Removing remaining edges to make outgoing edges
		while(!edges[thisnode].empty()){
			int anydest = *edges[thisnode].begin(); // Make thisnode -> anydest
			decrement(anydest, edges, degree_by);
			edges[thisnode].erase(anydest);
			edges[anydest].erase(thisnode);
			saveddegree[thisnode].push_back(anydest);
			currentsaved++;
		}
	}
	for(int s=1; s<=v; s++)
		for(auto d: saveddegree[s]) 
			printf("%d %d\n", s, d);
	return 0;
}

#include <cstdio>
#include <vector>

using namespace std;
vector<int> eds[100008];
vector<int> dirs[100008];
vector<int> revs[100008];
int degs[100008];
int used[100008];
vector<int> seqs[100008];

int run1(int beg, int cur) {
	for(int i=0;i<eds[cur].size();i++) {
		if(dirs[cur][i] == 0) {
			int to = eds[cur][i];
			int rv = revs[cur][i];
			dirs[cur][i] = 1;
			dirs[to][rv] = 1;
			seqs[beg].push_back(i);
			if(to == beg) return 1;
			if(run1(beg, to)) return 1;
		}
	}
	return 0;
}
void run2() {
	int cs = 2;
	int cur = 1;
	used[1] = 0;
	for(int i=0;i<seqs[1].size();i++) {
		dirs[cur][seqs[1][i]] = cs;
		int to = eds[cur][seqs[1][i]];
		int rv = revs[cur][seqs[1][i]];
		revs[to][rv] = 5 - cs;
		cs = 5 - cs;
		if(used[to] == 0) {
			used[to] = 1;
			int cur2 = to;
			for(int j=0;j<seqs[to].size();j++) {
				dirs[cur2][seqs[to][j]] = cs;
				int to2 = eds[cur2][seqs[to][j]];
				int rv2 = revs[cur2][seqs[to][j]];
				dirs[to2][rv2] = 5 - cs;
				cs = 5 - cs;
				cur2 = to2;
			}
		}
		cur = to;
	}
}

int main() {
	int N, M;
	scanf("%d%d",&N, &M);
	if(M%2) {
		printf("-1\n");
		return 0;
	}
	for(int i=0;i<M;i++) {
		int a, b;
		scanf("%d%d",&a, &b);
		degs[a]++;
		degs[b]++;
		eds[a].push_back(b);
		dirs[a].push_back(0);
		revs[a].push_back(eds[b].size());
		eds[b].push_back(a);
		dirs[b].push_back(0);
		revs[b].push_back(eds[a].size() - 1);
	}
	for(int i=1;i<=N;i++) {
		if(degs[i] % 2) {
			printf("-1\n");
			return 0;
		}
	}
	for(int i=1;i<=N;i++) {
		while(1) {
			if(run1(i, i) == 0) break;
		}
	}
	run2();
	for(int i=1;i<=N;i++) {
		for(int j=0;j<eds[i].size();j++) {
			if(dirs[i][j] == 2) printf("%d %d\n", i, eds[i][j]);
		}
	}
	return 0;
}

