using namespace std;

typedef pair<int, int> II;
vector<vector<int>> g;
vector<vector<int>> g2;
set<II> used;
vector<int> hist;

void dfs(int v) {
	const vector<int>& e = g[v];
	for (int i = 0; i < e.size(); ++i) {
		int nx = e[i];
		II key(min(v, nx), max(v, nx));
		if (used.find(key) == used.end()) {
			used.insert(key);
			dfs(nx);
		}
	}
	hist.push_back(v);
}

int main(int argc, char *argv[]) {
	int n, m;
	cin >> n >> m;
	g.clear();
	g.resize(n);
	for (int i = 0; i < m; ++i) {
		int a, b;
		cin >> a >> b;
		--a, --b;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	used.clear();
	hist.clear();
	dfs(0);

	g2.clear();
	g2.resize(n);
	for (int i = 1; i < hist.size(); ++i) {
		int a = hist[i - 1];
		int b = hist[i];
		if (i % 2) {
			g2[a].push_back(b);
		} else {
			g2[b].push_back(a);
		}
	}
	for (int i = 0; i < n; ++i) {
		const vector<int>& e = g2[i];
		if (e.size() % 2) {
			cout << "-1" << endl;
			return 0;
		}
	}
	for (int i = 0; i < n; ++i) {
		const vector<int>& e = g2[i];
		for (int j = 0; j < e.size(); ++j) {
			cout << (i + 1) << " " << (e[j] + 1) << endl;
		}
	}
	return 0;
}

