void decrement(int node, std::vector<std::set<int>> &edges, std::map<int, std::set<int>> &degree_by){
	int size = edges[node].size();
	if(size == 0){
		printf("Fatal error: Tried to erase empty (node %d)\n", node);
		throw "??";
	}
	degree_by[size].erase(node);
	if(degree_by[size].empty()) degree_by.erase(size);
	if(size-1 > 0) degree_by[size-1].insert(node);
}
void makeOutgoing(int start, int end,
	std::vector<std::set<int>> &edges, std::vector<std::vector<int>> &saveddegree){
	edges[start].erase(end);
	edges[end].erase(start);
	saveddegree[start].push_back(end);
}

int main(void){

	// Input
	int v, e; scanf("%d %d", &v, &e);
	std::vector<std::set<int>> edges(v+1);
	for(int i=0; i<e; i++){
		int a1, a2; scanf("%d %d", &a1, &a2);
		edges[a1].insert(a2);
		edges[a2].insert(a1);
	}

	// If edge num is odd -> Impossible
	if(e%2 == 1){
		printf("-1");
		return 0;
	}

	// Degree sorting - careful update
	std::map<int, std::set<int>> degree_by;
	for(int i=1; i<=v; i++) degree_by[edges[i].size()].insert(i); 

	// Go search
	int currentsaved = 0, targetsaved = e; // initial 2e
	std::vector<std::vector<int>> saveddegree(v+1);
	while(currentsaved < targetsaved){

		// Pop minimal from degree_by
		auto lowest = degree_by.begin();
		int thisdegree = lowest->first;
		int thisnode = *(lowest->second.begin());
		lowest->second.erase(thisnode);
		if(lowest->second.empty()) degree_by.erase(thisdegree);

		// Set target degree
		/*int targetdegree = (saveddegree[thisnode].size() % 2);
		if(targetdegree == 1 && edges[thisnode].size() == 0){
			printf("Unknown case\n");
			throw "??";
		}*/
		/*if(targetsaved - currentsaved < thisdegree - targetdegree){ // If too much removal
			targetdegree = thisdegree - (targetsaved - currentsaved);
			if(targetdegree % 2 != saveddegree[thisnode].size() % 2) targetdegree++;
		}*/

		// Critical first
		std::vector<int> criticals;
		for(auto anydest: edges[thisnode]){
			if(saveddegree[anydest].size() % 2 == 1 && edges[anydest].size() == 1)
				criticals.push_back(anydest);
		}
		for(auto anydest: criticals){ // critical should be starting point
			decrement(anydest, edges, degree_by);
			makeOutgoing(anydest, thisnode, edges, saveddegree);
			currentsaved++;
		}

		int targetdegree = (saveddegree[thisnode].size() % 2);

		// Removing random edges to make incoming edges
		while(edges[thisnode].size() > targetdegree){
			int anydest = *edges[thisnode].begin(); // Make thisnode <- anydest
			decrement(anydest, edges, degree_by);
			makeOutgoing(anydest, thisnode, edges, saveddegree);
			currentsaved++;
		}
		// Removing remaining edges to make outgoing edges
		while(!edges[thisnode].empty()){
			int anydest = *edges[thisnode].begin(); // Make thisnode -> anydest
			decrement(anydest, edges, degree_by);
			makeOutgoing(thisnode, anydest, edges, saveddegree);
			currentsaved++;
		}
	}
	for(int s=1; s<=v; s++)
		for(auto d: saveddegree[s]) 
			printf("%d %d\n", s, d);
	return 0;
}

