struct UFS{
	int fa[N];
	void init(int n){
		for(int i=0;i<=n;i++)fa[i]=i;
	}
	int find(int x){
		return fa[x]==x?x:fa[x]=find(fa[x]);
	}
	bool merge(int a,int b){
		a=find(a);
		b=find(b);
		if(a==b)return false;
		fa[a]=b;
		return true;
	}
}ufs;
void dfs(int x,int fa=-1){
	for(vector<int>::iterator it=es[x].begin();it!=es[x].end();++it){
		if(*it!=fa){
			dfs(*it,x);
		}
	}
	if(fa!=-1){
		if(d[x]==1){
			printf("%d %d\n",x,fa);
			d[x]^=1;
		}
		else{
			printf("%d %d\n",fa,x);
			d[fa]^=1;
		}
	}
}
