        int u = pa.first;
        if(u == p){
            continue;
        }
        dfs(u, v);
    }

    vector<int> x;
    for(P pa : g[v]){
        int u = pa.first;
        int e = pa.second;
        if(d[e] != 0){
            continue;
        }
        x.push_back(e);
    }

