	return x;
}
int he[N], ne[N], e[N], cnt = 1, vis[N], dir[N], d[N], n, m, dep[N];
void add(int u, int v, int p) {
	ne[++cnt] = he[u]; he[u] = cnt; e[cnt] = v;
	ne[++cnt] = he[v]; he[v] = cnt; e[cnt] = u;
}
void init() {
	memset(he, 0, sizeof(he)); cnt = 1;
	memset(dir, -1, sizeof(dir));
	memset(d, 0, sizeof(d));
	memset(dep, 0, sizeof(dep));
	memset(vis, 0, sizeof(vis));
}
int id(int x) {
	return x / 2;
}
void dfs(int x, int f) {
	vis[x] = 1; dep[x] = dep[f] + 1;
	for (int i = he[x]; i; i = ne[i]) {
		if (e[i] == f) continue;
		if (vis[e[i]] && dep[e[i]] < dep[x]) {
			if (i & 1) dir[id(i)] = 1; else dir[id(i)] = 0;
			d[e[i]] ^= 1;
			continue;
		}
		if (!vis[e[i]]) dfs(e[i], x);
	}
}
void getans(int x, int pr) {
	for (int i = he[x]; i; i = ne[i]) {
		if (i == (pr ^ 1)) continue;
		if (dir[id(i)] != -1) continue;
		getans(e[i], i);
	}
	if (!d[x]) d[e[pr ^ 1]] ^= 1;
	dir[id(pr)] = d[x] ^ (pr & 1) ^ 1;
}
void solve() {
	n = read(), m = read();
	init();
	map<int, P> mp;
	for (int i = 1; i <= m; i++) {
		int u = read(), v = read();
		mp[i] = { u,v };
		add(u, v, i);
	}
	if (m & 1) { puts("-1"); return; }
	dfs(1, 0);
	getans(1, 0);
	for (int i = 1; i <= m; i++) printf("%lld %lld\n", (dir[i]?mp[i].first:mp[i].second),(dir[i]?mp[i].second:mp[i].first));
}
int main() {
	solve();
	return 0;
}

