vector<pair<int,int>> graph[100001],edges;
int n,m,deg[100001],ans[100001];

void bfs(int curr){
    map<int,pair<int,int>> from;
    set<int> seen;
    seen.insert(curr);
    queue<int> q;
    for(pair<int,int> i : graph[curr]){
        from[i.first] = {curr,i.second};
        seen.insert(i.first);
        q.push(i.first);
    }
    int found;
    while(q.size()){
        int a = q.front();
        q.pop();
        if(deg[a] == 1){
            found = a;
            break;
        }
        for(pair<int,int> i : graph[a]){
            if(seen.count(i.first)){
                continue;
            }
            seen.insert(i.first);
            from[i.first] = {a,i.second};
        }
    }
    deg[curr] ^= 1;
    deg[found] ^= 1;
    while(from.find(found) != from.end()){
        pair<int,int> a = from[found];
        ans[a.second] ^= 1;
        found = a.first;
    }
}

