vector<bool> visited(100010);
vector<vector<int>> tree(100010);
vector<vector<int>> G(100010);
vector<int> outdeg(100010);
vector<P> ansedge;

set<P> edge;

void make_tree(int cv){
    visited[cv] = true;

    for(auto nv : G[cv]){
        if(!visited[nv]){
            edge.erase(minmax(cv,nv));
            tree[cv].emplace_back(nv);
            tree[nv].emplace_back(cv);
            make_tree(nv);
        }
    }

    return ;
}

void dfs(int cv, int par){

    for(auto nv : tree[cv]){
        if(nv == par) continue;

        dfs(nv, cv);
    }

    if(cv == 0) return ;

    if(outdeg[cv] % 2){
        ansedge.emplace_back(cv, par);
        outdeg[cv]++;
    }
    else{
        ansedge.emplace_back(par, cv);
        outdeg[par]++;
    }

    return ;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m; cin>>n>>m;
    for(int i=0; i<m; i++){
        int a, b; cin>>a>>b;
        a--, b--;
        edge.emplace(minmax(a, b));
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    if(m % 2){
        cout << -1 << endl;
        return 0;
    }

    make_tree(0);

    for(auto i : edge){
        outdeg[i.first]++;
        ansedge.emplace_back(i);
    }

    dfs(0, -1);

    for(auto i : ansedge){
        cout << i.first + 1 << " " << i.second + 1 << endl;
    }
}

