typedef pair<int, int> edge;

const int MAX_N = 1e5 + 1;
const int MAX_M = 1e5 + 1;

int u[MAX_M], v[MAX_M];
int color[MAX_N], cnt[MAX_N];
bool is_visited[MAX_N];
vector<int> graph[MAX_N], tree[MAX_N];
map<edge, bool> in_tree;
vector<edge> ans;

void make_tree(int node) {
    color[node] = 2;
    for (int i = 0; i < graph[node].size(); i++) {
        if (color[graph[node][i]]) continue;
        color[graph[node][i]] = 1;
        tree[node].push_back(graph[node][i]);
        tree[graph[node][i]].push_back(node);
        in_tree[edge(node, graph[node][i])] = true;
        in_tree[edge(graph[node][i], node)] = true;
    }
    for (int i = 0; i < tree[node].size(); i++) {
        if (color[tree[node][i]] == 1) make_tree(tree[node][i]);
    }
}

void decide_direction(int node, int prev) {
    is_visited[node] = true;
    for (int i = 0; i < tree[node].size(); i++) {
        if (is_visited[tree[node][i]]) continue;
        decide_direction(tree[node][i], node);
    }
    if (prev < 0) return;
    if (cnt[node] % 2) {
        cnt[node]++;
        ans.push_back(edge(node, prev));
    }
    else {
        cnt[prev]++;
        ans.push_back(edge(prev, node));
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N, M;
    cin >> N >> M;
    for (int i = 0; i < M; i++) {
        cin >> u[i] >> v[i];
        u[i]--, v[i]--;
        graph[u[i]].push_back(v[i]);
        graph[v[i]].push_back(u[i]);
    }
    if (M % 2) {
        cout << -1 << endl;
        return 0;
    }
    make_tree(0);
    for (int i = 0; i < M; i++) {
        if (in_tree[edge(u[i], v[i])]) continue;
        cnt[u[i]]++;
        ans.push_back(edge(u[i], v[i]));
    }
    decide_direction(0, -1);
    for (int i = 0; i < M; i++) {
        cout << ans[i].first + 1 << ' ' << ans[i].second + 1 << endl;
    }
    return 0;
}

