		--a; --b;
		uf.unite(a, b);
		v[a].push_back({ b,-1 });
		v[b].push_back({ a,-1 });
	}
	for (int i = 0; i < n; ++i) {
		if (uf.get_val(i) % 2 == 1) {
			cout << -1 << endl;
			return 0;
		}
	}
	for (int i = 0; i < n; ++i) {
		vector<int> not_decided;
		int now_degree = 0;
