int calc(int now, int prev, graph &src, graph &ans, vector<bool> &arrived) {
	//cout << prev<<"->"<<now << endl;
	if(arrived[now]) {
		//cout << prev<<"->"<<now << " : " << ((src[now][prev])?1:0) << endl;;
		return (src[now][prev])?1:0;
	}
	arrived[now] = true;
	int pre = -1;
	//for(int i = 0; i < src[now].size(); i++) {
		//int next = src[now][i];
	for(P p : src[now]) {
		int next = p.first;
		//cout << "in" << now << "," << next << endl;
		bool liv = p.second;
		if(next==prev) continue;
		if(!liv) continue;
		int res = calc(next,now,src,ans,arrived);
		if(res==1) {
			if(pre==-1) {
				pre = next;
			}else {
				ans[now][pre] = true;
				ans[now][next] = true;
				//cout << now << "," << pre << "," << next << endl;
				src[pre][now] = false;
				src[next][now] = false;
				src[now][pre] = false;
				src[now][next] = false;
				pre = -1;
			}
		}
	}
	if(pre==-1) return 1;
	else {
		if(prev==-1) return 0;
		else {
			ans[now][pre] = true;
			ans[now][prev] = true;
			//cout << now << "," << pre << "," << next << endl;
			src[pre][now] = false;
			src[prev][now] = false;
			src[now][pre] = false;
			src[now][prev] = false;
			return 0;
		}
	}
}

