  vector<set<int>> ones(n);
  vector<ii> ans;

  auto del = [&](int u, int v) {
    g[u].erase(v);
    g[v].erase(u);
    if (ones[u].count(v)) ones[u].erase(v);
    if (ones[v].count(u)) ones[v].erase(u);
  };
  queue<int> q;
  REP (i, n) {
    if (g[i].size() == 1) {
      q.push(i);
      ones[i].insert(*g[i].begin());
    }
  }
  int idx = 0;
  while (1) {
    if (q.empty()) {
      while (idx < n && g[idx].size() == 0) idx++;
      if (idx == n) break;
      q.push(idx);
    }
    int v = q.front(); q.pop();
    if (g[v].size() == 0) continue;
    int u = *g[v].begin();
    ans.push_back({u, v});
    del(u, v);
    int v2 = ones[u].size() ? *ones[u].begin() : *g[u].begin();
    ans.push_back({u, v2});
    del(u, v2);

    for (int i : {u, v, v2}) {
      if (g[i].size() == 1) {
        int j = *g[i].begin();
        ones[j].insert(i);
        q.push(i);
      }
    }
  }

  for (auto p : ans) cout << p.fi + 1 << " " << p.se + 1 << endl;
}

