int found = 0;

int check[100005];

int out_degree[100005];

vector<int> AdjList[200005];

vector<pli> EdgeList;

void dfs(int x){
	//cout << x << '\n';
	check[x] = 1;
	int last = 0, cnt = 0;
	for (auto it : AdjList[x]){
		if (EdgeList[it].second != 0) continue;
		cnt++;
		last = it;
	}
	if ((cnt+out_degree[x])%2==0){
		for (auto it : AdjList[x]){
			if (EdgeList[it].second != 0) continue;
			if (x == EdgeList[it].first.first) EdgeList[it].second = 1;
			else EdgeList[it].second = 2;
			out_degree[x]++;
		}
	}
	else{
		for (auto it : AdjList[x]){
			if (EdgeList[it].second != 0) continue;
			if (it == last){
				if (x == EdgeList[it].first.first){
					out_degree[EdgeList[it].first.second]++;
					EdgeList[it].second = 2;
				} 
				else{
					out_degree[EdgeList[it].first.first]++;
					EdgeList[it].second = 1;
				} 

				continue;
			}
			if (x == EdgeList[it].first.first) EdgeList[it].second = 1;
			else EdgeList[it].second = 2;
			out_degree[x]++;
		}
		dfs(last);
	}
}

void dfs2(int x, int p){
	if (p != -1 && out_degree[x]%2==0){
		found = 1;
		return;
	}
	for (auto it : AdjList[x]){
		auto k = EdgeList[it];
		if (x == k.first.first){
			if (k.first.second == p) continue;
			dfs2(k.first.second,x);
		}
		else{
			if (k.first.first == p) continue;
			dfs2(k.first.first,x);
		}
		if (found){
			EdgeList[it].second = 3 - EdgeList[it].second;
			return;
		}
	}

}

