	}
	for (int i = 1; i <= N; ++i){
		if (!check[i]){
			dfs(i);
		}
	}
	for (int i = 1; i <= N; ++i){
		if (out_degree[i]%2!=0){
			found = 0;
			dfs2(i,-1);
		}
	}
	for (int i = 0; i < M; ++i){
		if (EdgeList[i].second == 1){
