    for (int i = 0; i < adj[u].size(); i++) {
      int v = adj[u][i];
      if (!visited[v]) {
        bfsQueue.push(v);
        treeEdgeStack.emplace(u, v);
        parent[v] = u;
        visited[v] = true;
