  while (treeEdgeStack.size() > 0) {
    pair<int, int> e = treeEdgeStack.top();
    treeEdgeStack.pop();
    if (count[e.second] % 2 == 0) {
      results.push_back(to_string(e.first) + " " + to_string(e.second));
      count[e.first] += 1;
    } else {
      results.push_back(to_string(e.second) + " " + to_string(e.first));
      count[e.second] += 1;
    }
