// 有向グラフの接続行列 B に対し，線形方程式 Bx = c を (必要なら mod 2 で) 解くライブラリ
template<typename T>
struct LinearSystemIncidence {
  struct Edge {
    int id, to; bool fwd;
    Edge(int i, int t, bool f) : id(i), to(t), fwd(f) {}
  };

  int n, m;
  bool mod2;
  vector<T> x;
  vector<bool> seen;
  vector<vector<Edge>> G;

  LinearSystemIncidence(int n, vector<P> &E, bool mod2=false) : n(n), m(E.size()), G(n), mod2(mod2) {
    rep(i, m) {
      G[E[i].first].emplace_back(i, E[i].second, true);
      G[E[i].second].emplace_back(i, E[i].first, false);
    }
  }

  T dfs(vector<T> &c, int u) {
    seen[u] = true;
    T res = c[u];
    for (Edge e : G[u]) {
      if (seen[e.to]) continue;
      T tmp = dfs(c, e.to);
      if (e.fwd) x[e.id] = tmp;
      else x[e.id] = -tmp;
      res += tmp;
      if (mod2) {
        x[e.id] %= 2;
        if (x[e.id] < 0) x[e.id] += 2;
      }
    }
    if (mod2) res %= 2;
    return res;
  }

  pair<bool, vector<T>> solve(vector<T> &c) {
    x.assign(m, 0);
    seen.assign(n, false);
    rep(u, n) {
      if (seen[u]) continue;
      if (dfs(c, u)) return {false, vector<T>()};
    }
    return {true, move(x)};
  }
};


int main() {
  int n, m; cin >> n >> m;
  vector<P> E;
  V c(n+1);
  rep(i, m) {
    int u, v; cin >> u >> v;
    E.emplace_back(u, v);
    c[u] ^= 1;
  }

  LinearSystemIncidence<int> LSI(n+1, E, true);
  auto sol = LSI.solve(c);

  if (sol.first) {
    rep(i, m) {
      if (sol.second[i]) swap(E[i].first, E[i].second);
      cout << E[i].first << " " << E[i].second << "\n";
    }
  }
  else cout << -1 << "\n";
  return 0;
}

