bool dfs(int u, int fa) {
	int s = 0;
    vis[u] = 1;
    dep[u] = dep[fa] + 1;
	for ( auto v:g[u] ) {
		if ( !vis[v] ) {
			s ^= dfs(v, u);
		} else {
			if ( dep[v] > dep[u] ) {
				p[++xb] = u;
                q[xb] = v;
				s ^= 1;
			}
