void dfs(int v) {
	const vector<int>& e = g[v];
	for (int i = 0; i < e.size(); ++i) {
		int nx = e[i];
		II key(min(v, nx), max(v, nx));
		if (used.find(key) == used.end()) {
			used.insert(key);
			dfs(nx);
		}
	}
	hist.push_back(v);
	if (hist.size() >= 2) {
		int prev = hist[hist.size() - 2];
		if (g2[prev].size() % 2) {
			g2[prev].push_back(v);
		} else {
			g2[v].push_back(prev);
		}
	}
}

