int loop(int v, int p, int dep) {
	// debug(v, p);
	used[v] = true;
	d[v] = dep;
	int cnt = 0;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		if(!used[n]) {
			cnt += loop(n, v, dep + 1);
		}
		else {
			// debug(v, n);
			if(d[v] > d[n]) {
				ans.pb(pi(v, n));
				cnt++;
			}
		}
	}
	if(p == -1) return 0;
	else {
		if(cnt % 2) {
			ans.pb(pi(v, p));
			return 0;
		}
		else {
			ans.pb(pi(p, v));
			return 1;
		}
	}
}

