  if( E % 2 == 1 ){
    cout << -1 << endl; return 0;
  }
  //以下、適切に配置すれば可能な場合

  vector<vector<int>> to(V);

  for(int i = 0; i < E; i++){ 
    int a,b; cin >> a >> b; a--; b--;
    to[a].push_back(b); to[b].push_back(a);
  }

  vector<pair<int,int>> depth(V);
  for(int i = 0; i < V; i++){ depth[i] = {-1,i};} //第二成分はノード番号

  depth[0].first = 0;
  queue<int> Q; Q.push(0);

  while(!Q.empty()){ //BFSの要領で0を基準に木としての深さをマーク
    int p = Q.front(); Q.pop();
    for(auto u : to[p]){ 
      if( depth[u].first != -1 ){ //すでに記録済み
        continue;
      }
      depth[u].first = depth[p].first+1;
      Q.push(u);
    }
  }

  vector<bool> used(V,false);
  vector<bool> even(V,true);

  vector<pair<int,int>> ans;

  //次に、depthが深いノードから順次向きを決めて行く

  sort(depth.rbegin(),depth.rend());

  for(int i = 0; i < V; i++){ 
    int p = depth[i].second;
    for(auto u : to[p] ){ 
      if(used[u]){ continue;} //すでにuから伸びる辺の向きは全て決め終わってしまった場合

      if(even[p]){ //pの出次数が偶数↪︎uからpに向けて向きをつける
        ans.push_back({u,p});
        even[u] = !even[u];
      }
      else{ // pからuに向きをつける
        ans.push_back({p,u});
        even[p] = !even[p];
      }

    }//for-auto

    used[p] = true;
  }//for-i

  for(auto ne : ans){ cout << ne.first+1 << " " << ne.second+1 << endl;}

  return 0;
}

