struct node 
{
    int deg, par, idx;
};
bool operator < (const node& a, const node& b) {
    if (a.deg == b.deg)
        if (a.par == b.par)
            return a.idx < b.idx; 
        else 
            return a.par > b.par; 
    else 
        return a.deg < b.deg; 
}

int32_t main()
{
    #ifdef DEBUG
    //freopen("B.txt","r",stdin);
    //freopen("","w",stdout);
    #endif
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n,m;
    cin >> n >> m; 
    fill1(degree,0); 
    fill1(parity,0); 
    fill1(processed,false); 
    vector<pair<int,int>> edges; 

    for0(i,m) {
        int a,b;
        cin >> a >> b; 
        adj[a].push_back(b); 
        adj[b].push_back(a); 
        degree[a]++;
        degree[b]++; 
    }

    set<node> nodes; 
    for (int i=1; i<=n; i++) {
        nodes.insert((node){degree[i],parity[i],i}); 
    }

    bool ok = true; 
    int cnt = 0; 
    while (sz(nodes) > 0) {
        cnt++; 
        node top = *nodes.begin(); 
        int u = top.idx; 
        // pr(u) pr(degree[u]) pr(parity[u]) nl 
        nodes.erase(nodes.begin());

        for (int v : adj[u]) {
            if (not processed[v]) {
                nodes.erase((node){degree[v],parity[v],v});
                if (parity[u]) {
                    // edge points from u 
                    edges.push_back({u,v}); 
                    parity[u] ^= 1; 
                }
                else {
                    // edge points into u 
                    edges.push_back({v,u}); 
                    parity[v] ^= 1;
                } 
                degree[v]--;
                degree[u]--; 
                nodes.insert((node){degree[v],parity[v],v}); 
            }
        }    
        if (parity[u]) {
            ok = false; 
            break; 
        }        
        processed[u] = true; 
    }

    if (ok) {
        assert(sz(edges) == m); 
        for (pair<int,int> e : edges) {
            cout << e.first << " " << e.second << endl; 
        }
    }
    else 
        cout << -1 << endl; 
    return 0;
}

