#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

struct Vertex
{
    vector<ll> n;
    ll m = 0;
};

ll N, M;
Vertex V[100005];
pll A[100005];
pll E[100005];
bool U[100005];

bool solve()
{
    if (M % 2 == 1)
        return false;

    queue<ll> q;
    REP(i, N)
    {
        if (V[i].n.size() % 2 == 0)
        {
            q.push(i);
        }
    }

    ll m = 0;
    while (!q.empty())
    {
        ll t = q.front();
        q.pop();
        if (U[t])
            continue;
        if ((V[t].n.size() - V[t].m) % 2 == 1)
            continue;
        REP(j, V[t].n.size())
        {
            ll n = V[t].n[j];
            if (U[n])
                continue;
            A[m++] = pll(t + 1, n + 1);
            V[n].m++;
            if ((V[n].n.size() - V[n].m) % 2 == 0)
                q.push(n);
        }
        U[t] = true;
    }

    return true;
}

