struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  //木の根なら-(size of tree) それ以外は木の根のindexが入っている。                 
  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

struct edge{
  int from,to;
};

void dfs(int *depth, vector<int> *gv, int s, int d){
  depth[s]=d;
  //  cout << gv[s][0] << endl;
  //  cout << depth[1] << endl;
  rep(i,gv[s].size()){
    if(depth[gv[s][i]]==-1){
      dfs( depth, gv, gv[s][i], d+1);
    }
  }
}

