    a--;b--;
    g.push_back({a,b});
  }
  if(M%2==1){
    cout << -1 << endl;
    return 0;
  }
  UnionFind gra(N);//全域木作成用のunion-find
  vector<int > gv[N];//全域木
  vector<int > ans[N];//回答用の有向グラフ
  int V[N];//出るへんの数 mod2
  rep(i,N) V[i] = 0;
  rep(i,M){
    edge &e=g[i];
    if(gra.unite(e.from,e.to)){
      gv[e.from].pb(e.to);
      gv[e.to].pb(e.from);
    }
    else{
      ans[e.from].pb(e.to);
      V[e.from]+=1;
      V[e.from]%=2;
