    int vi=p[i].second;
    rep(j,gv[vi].size()){
      int k=gv[vi][j];
      if(depth[k] < depth[vi]){
	if(V[vi]==0){
	  ans[k].pb(vi);
	  V[k]=1;
	}
	else{
	  ans[vi].pb(k);
	  V[vi]=0;
	}
      }
    }
  }

  rep(i,N){
    rep(j,ans[i].size()){
      cout << i+1 << " " << ans[i][j]+1 << endl;
    }
  }

  return 0;


