void built(){
	for(int i = n-1;i>0;i--){
		t[i] = min(t[i<<1],t[i<<1|1]);
	}
}

void update(int p,int y){
	int x = t[p+n].first;
	for(t[p+=n] = {x - y,p};p>1;p >>= 1){
		t[p>>1] = min(t[p],t[p^1]);
	}
}

pair<int,int> query(int l, int r){
	pair<int,int> mn = {mx,-1};
	for(l += n, r += n; l<r; l >>= 1,r >>= 1){
		if(l&1) mn = min(mn,t[l++]);
		if(r&1) mn = min(mn,t[--r]);
	}
	return mn;
}

