void dfs(int now){
  used[now]=true;
  for(int i=0;i<g[now].size();i++){
    int nex=g[now][i];
    int a=min(now,nex),b=max(now,nex);
    if(used[nex]) continue;
    treeEdges[mp[mkp(a,b)]]=1;
    dfs(nex);
  }
}

int solve(int now){
  used[now]=true;
  for(int i=0;i<g[now].size();i++){
    int nex=g[now][i];
    int a=min(now,nex);
    int b=max(now,nex);
    if(used[nex]) continue;
    if(treeEdges[mp[mkp(a,b)]]==false) continue;
    int x=solve(nex);
    int c=-1;
    if(now>nex) c=1;
    if(x==1){
      num[now]^=1;
      ans[mp[mkp(a,b)]]=-c;
    }else ans[mp[mkp(a,b)]]=c;
  }

  if(num[now]==1){
    return 0;
  }else{
    return 1;
  }
}

