		int i = change[z].second;
		if (c[i] % 2) {
			rep(j, vec[i].size()) {
				if (g[i] < g[vec[i][j]]) {
					ans.insert(make_pair(i,vec[i][j]));
					break;
				}
			}
			bool f = false;
			rep(j, vec[i].size()) {
				if (g[i] < g[vec[i][j]]) {
					if (f) {
						ans.insert(make_pair(vec[i][j],i));
						c[vec[i][j]]++;
					}
					f = true;
				}
			}
		}
		else {
			rep(j, vec[i].size()) {
				if (g[i] < g[vec[i][j]]) {
					ans.insert(make_pair(vec[i][j],i));
					c[vec[i][j]]++;
				}
			}
		}
	}
	if (c[change[n - 1].second] % 2)cout << -1 << endl;
	else for (P p : ans)cout << p.first << " " << p.second << endl;
	return 0;
}

