#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

int main() {
    ll N, M;
    cin >> N >> M;

    struct Edge {
        ll to, id;
    };

    vector<vector<Edge>> connect(N);
    for (ll i = 0; i < M; i++) {
        ll A, B;
        cin >> A >> B;
        A--; B--;
        connect[A].push_back({ B, i });
        connect[B].push_back({ A, i });
    }

    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    struct Element {
        ll dim, node;
        bool operator<(const Element& rhs) const {
            return dim > rhs.dim;
        }
    };
    priority_queue<Element> pq;
    vector<ll> remainder(N);
    vector<ll> dim(N, 0);
    vector<bool> used_node(N, false);
    vector<bool> used_edge(M, false);
    for (ll i = 0; i < N; i++) {
        pq.push({ (ll)connect[i].size(), i });
        remainder[i] = connect[i].size();
    }

    vector<pair<ll, ll>> ans;

    while (!pq.empty()) {
        auto t = pq.top();
        pq.pop();

        if (remainder[t.node] % 2 != dim[t.node]) {
            for (const auto& e : connect[t.node]) {
                if (used_edge[e.id]) {
                    continue;
                }
                ans.push_back({ e.to, t.node });
                used_edge[e.id] = true;
                remainder[e.to]--;
                remainder[t.node]--;
                dim[e.to]++;
                pq.push({ remainder[e.to], e.to });
                break;
            }
        }

        for (const auto& e : connect[t.node]) {
            if (remainder[t.node] == 0) {
                break;
            }

            if (used_edge[e.id]) {
                continue;
            }
            ans.push_back({ t.node, e.to });
            used_edge[e.id] = true;
            remainder[e.to]--;
            remainder[t.node]--;
            pq.push({ remainder[e.to], e.to });
        }
    }

    for (const auto& p : ans) {
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }
}

