int getParent(int x){
	return (p[x] == x) ? x:getParent(p[x]);
}

void conn(int a, int b){
	int pa = getParent(a), pb = getParent(b);
	if(pa != pb){
		if(lvl[pa] < pb)
			p[pa] = pb;
		else
			p[pb] = pa;
		if(lvl[pa] == lvl[pb])
			lvl[pa]++;
	}
}

void dfs(int pos, int prev){
	visited[pos] = true;
	for(int i : adj[pos]){
		if(visited[i])
			continue;
		dfs(i, pos);
	}
	if(par[pos] == 1){
		e.push_back(ii(pos, prev));
		par[pos] = 1-par[pos];
	}else if(pos != 0){
		e.push_back(ii(prev, pos));
		par[prev] = 1-par[prev];
	}
}

