namespace adaptor = boost::adaptors;

std::vector<std::set<int>> set_tree(int N,std::vector<std::set<int>>const& graph)
{
	boost::dynamic_bitset<> flag(N);
	std::vector<std::set<int>> tree(N);
	std::queue<std::pair<int, int>> queue;
	queue.emplace(*std::begin(graph[0]), 0);
	while (queue.size())
	{
		int i, p;
		std::tie(i, p) = queue.front();
		queue.pop();
		if (flag[i])
		{
			continue;
		}
		flag[i] = true;
		tree[i].emplace(p);
		tree[p].emplace(i);
		for (auto n : graph[i])
		{
			queue.emplace(n, i);
		}
	}
	return tree;
}

boost::optional<std::vector<std::pair<int, int>>> run(int N, int M, std::vector<std::set<int>> graph)
{
	std::vector<std::pair<int, int>> directed;
	auto tree = set_tree(N, graph);
	std::queue<int> queue;
	std::vector<int> count(N);
	auto edge_set = [&](int from, int to)
	{
		directed.emplace_back(from, to);
		graph[from].erase(to);
		tree[from].erase(to);
		graph[to].erase(from);
		tree[to].erase(from);
		++count[from];
		if (tree[from].size() == 1)
		{
			queue.emplace(from);
		}
		if (tree[to].size() == 1)
		{
			queue.emplace(to);
		}
	};
	for (auto i : boost::irange(0, N))
	{
		if (tree[i].size() == 1)
		{
			queue.emplace(i);
		}
	}
	while (queue.size())
	{
		auto i = queue.front();
		queue.pop();
		if (tree[i].size() == 0)
		{
			continue;
		}
		auto n = *std::begin(tree[i]);
		if (graph[i].size() == 1)
		{
			if (count[i] % 2 == 1)
			{
				edge_set(i, n);
			}
			else
			{
				edge_set(n, i);
			}
			continue;
		}
		if (count[i] % 2 == 1)
		{
			auto k = *std::begin(graph[i]);
			if (k == n)
			{
				k = *std::next(std::begin(graph[i]));
			}
			edge_set(i, k);
		}
		if (graph[i].size() % 2 == 0)
		{
			auto ite = std::begin(graph[i]);
			auto end = std::end(graph[i]);
			while (ite != end)
			{
				auto k = *ite;
				++ite;
				edge_set(i, k);
			}
		}
		else
		{
			auto ite = std::begin(graph[i]);
			auto end = std::end(graph[i]);
			while (ite != end)
			{
				auto k = *ite;
				++ite;
				if (k != n)
				{
					edge_set(i, k);
				}
			}
		}
	}
	if (std::all_of(count.begin(), count.end(), [](int i) {return i % 2 == 0; }))
	{
		return directed;
	}
	else
	{
		return boost::none;
	}
}

