int main() {

	int N, M;
	scanf_s("%d%d", &N, &M);

	if (M % 2 == 1) {
		printf("-1\n");
		return 0;
	}

	int u, v;
	map<pair<int, int>, int> dir;
	vector<vector<int>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		scanf_s("%d%d", &u, &v);
		u--, v--;
		edge[u].emplace_back(v);
		edge[v].emplace_back(u);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	stack<int> que;
	vector<int> used(N);
	int idx = 1;
	que.emplace(0);
	while (!que.empty()) {

		int now = que.top();
		que.pop();

		int fliping = out[now];
		DMP(now);
		DMP(fliping);

		if (!used[now]) used[now] = idx++;

		bool all_used = true;
		for (const auto &e : edge[now]) {
			if (!used[e]) {
				dir[minmax(now, e)] ^= fliping;
				out[now] ^= fliping;
				out[e] ^= fliping;
				que.emplace(e);
				all_used = false;
				break;
			}
		}

		if (all_used) {
			for (const auto &e : edge[now]) {
				if (used[e] < used[now]) {
					dir[minmax(now, e)] ^= fliping;
					out[now] ^= fliping;
					out[e] ^= fliping;
					que.emplace(e);
					all_used = false;
				}
			}
		}

		if (all_used) break;

	}


	for (int i = 0; i < N; i++) {
		DMP(out[i]);
	}
	for (int i = 0; i < N; i++){
		DMP(used[i]);
	}

	for (auto &e : dir) {
