int get(int x){
	if(fa[x]==x)return x;
	fa[x]=get(fa[x]);
	return fa[x];	
}
void uni(int x,int y){
	fa[get(x)]=get(y);	
}
void dfs(int now,int fa){
	for(int i=0;i<side[now].size();i++){
		int v=side[now][i];if(v==fa)continue;
		dfs(v,now);
		if(out[v]&1){printf("%d %d\n",v,now);}
		else{out[now]++;printf("%d %d\n",now,v);}	
	}
	return;
}
