            }
            used[temp] = true;
            finish++;
            for(auto e: E[temp]){
                if(!used[e]){
                    if(even[temp] % 2 == 0){
                        ans.push_back(make_pair(e, temp));
                        even[e]++;
                    }
                    else{
                        ans.push_back(make_pair(temp, e));
                        even[temp]++;
