ll N, M;
vector<set<ll>> G;

vb passed;
vpl ans;

ll dfs(ll now, ll par){
    passed[now] = true;

    vl rem; ll cnt = 0;
    for(ll c : G[now]){
        if(c != par && !passed[c]){
            cnt += dfs(c, now);
        }
        else if(c != par){
            rem.pb(c);
        }
    }

    if(par == -1) return 0;

    ll tot = cnt;
    for(ll c : rem){
        tot++;
        ans.pb({now, c});
    }

    ll res;
    if(tot%2 == 1){
        res = 0;
        ans.pb({now, par});
    }
    else{
        res = 1;
        ans.pb({par, now});
    }
    return res;
}

