        cout << -1 << endstr; return 0;
    }
    G = vector<set<ll>>(N);
    rep(_, M){
        ll a, b; cin >> a >> b; a--; b--;
        G[a].insert(b); G[b].insert(a);
    }
    passed = vb(N, false);
    dfs(0, -1);
    for(auto p : ans){
        cout << p.ff+1 << " " << p.ss+1 << endstr;
    }
    return 0;
}

