void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

bool st[100100],visited[100100];
int a[100100],b[100100],ufp[100100],ufr[100100],d[100100],e[100100];

vector<P> g[100100],s;

void ufinit(int n){
	int i;
	for(i=0; i<n; ++i){
		ufp[i] = i;
		ufr[i] = 1;
	}
}

int ufind(int x){
	if(x != ufp[x]){
		ufp[x] = ufind(ufp[x]);
	}
	return ufp[x];
}

void unionf(int x, int y){
	x = ufind(x);
	y = ufind(y);
	if(x==y){
		return;
	}
	if(ufr[x]<ufr[y]){
		swap(x,y);
	}
	ufr[x] += ufr[y];
	ufp[y] = x;
}

void dfs(int v, int p=-1){
	int u,i;
	for(i=(g[v].l_ength()-1); i>=0; --i){
		u = g[v][i].first;
		if(u==p){
			continue;
		}
		d[u] = d[v]+1;
		e[u] = g[v][i].second;
		s.push_back(P(d[u],u));
		dfs(u,v);
	}
}

