	int n,m,i,t;
	cin >> n >> m;
	ufinit(n);
	for(i=0; i<m; ++i){
		cin >> a[i] >> b[i];
		--a[i]; --b[i];
		st[a[i]] = (!st[a[i]]);
		if(ufind(a[i])==ufind(b[i])){
			continue;
		}
		unionf(a[i],b[i]);
		g[a[i]].push_back(P(b[i],i));
		g[b[i]].push_back(P(a[i],i));
	}
	if(m%2){
		cout << "-1" << endl;
		return 0;
	}
	dfs(0);
	sort(s.begin(),s.end(),greater<P>());
	for(i=0; i<n; ++i){
		if(st[s[i].second]){
			t = e[s[i].second];
			swap(a[t],b[t]);
			st[a[t]] = (!st[a[t]]);
			st[b[t]] = (!st[b[t]]);
		}
	}
	for(i=0; i<m; ++i){
		++a[i]; ++b[i];
		cout << a[i] << " " << b[i] << endl;
	}
	return 0;
}

