int dfs(vector<set<int>> &g, vector<int> &used, int v) {
    used[v] = 1;
    int out = 0;
    for (auto u: g[v]) {
        if (used[u] == 1) continue;
        if (used[u] == 2 || !dfs(g, used, u)) {
            g[u].erase(v);
            out++;
        } else {
            g[v].erase(u);
        }
    }
    used[v] = 2;
    return out%2;
}

