static const int MAX = 100005;
static const int WHITE = 0; // 未到達
static const int GRAY = 1; // 到達
static const int BLACK = 2; // 探索済み

int N, M;

int color[MAX];
vector<int> adj[MAX];

vector<pair<int, int>> ans;

int solve (int s) {
  int ret;
  queue<int> que;
  for (int i = 0; i < MAX; i++) {
    color[i] = WHITE;
  }

  que.push(s);

  while (!que.empty()) {
    int u = que.front();
    que.pop();
    color[u] = BLACK;
    int adjNum = 0;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j];
      if (color[v] == WHITE) adjNum++;
    }
    int base;
    if (adjNum % 2 == 0) {
      base = adjNum;
    } else base = adjNum - 1;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j];
      if (color[v] == BLACK) continue;
      if (base > 0) {
        que.push(v);
        ans.pb(make_pair(u, v));
        base--;
        ret++;
      }
    }
  }
  return ret;
};

