void make_V()
{
  UnionFind uf{N};
  for (auto e : E)
  {
    int a, b;
    tie(a, b) = e;
    if (!uf.is_same(a, b))
    {
      uf.merge(a, b);
      V[a].push_back(b);
      V[b].push_back(a);
    }
    else
    {
      ans.push_back(e);
      cnt[a]++;
    }
  }
}

void dfs(int v, int p = -1)
{
  for (auto w : V[v])
  {
    if (p != w)
    {
      dfs(w, v);
    }
  }
  if (p == -1)
  {
    return;
  }
  if (cnt[v] % 2 == 1)
  {
    ans.push_back(edge(v, p));
  }
  else
  {
    ans.push_back(edge(p, v));
  }
}

void solve()
{
  make_V();
  dfs(0);
}

