                pt[lt] ^= 1;
            }
            return;
        }
        else
        {
            tr[p].push_back(v);
        }
    }
    vst[v] = 1;

    for (int u : g[v])
    {
        if (u != p)
        {
            tree(g, v, u);
        }
    }
}

void solve(int p, int v)
{
    for (int u : tr[v])
    {
        solve(v, u);
    }

    if (p == -1)
    {
        return;
    }

    if (pt[v] == 0)
    {
        ans.insert(pr(p, v));
        pt[p] ^= 1;
    }
    else
    {
        ans.insert(pr(v, p));
        pt[v] ^= 1;
    }
}

