    --a;--b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  vector<int> dis(n, n);
  queue<int> q;
  q.push(0);
  dis[0] = 0;
  vector<int> parent(n, -1);
  while(!q.empty()) {
    int i = q.front();
    q.pop();
    for (int d : g[i]) {
      if (dis[d] <= dis[i]) continue;
      q.push(d);
      dis[d] = dis[i]+1;
      parent[d] = i;
    }
  }
  vector<tuple<int,int>> v;
