const int M = 100001;

vector<int> graph[M];
int par[M];
int visit[M];
int out[M]; // 出て行く辺の本数
vector<int> order; // 親子の順
set<ll> dir;

void bfs(int start) {
  queue<int> remain;
  remain.push(start);
  visit[start] = 1;
  while (remain.size() > 0) {
    ll from = remain.front(); remain.pop();
    order.push_back(from);
    for (ll to: graph[from]) {
      if (visit[to] != 0) {
        if (par[from] == to) continue;
        if (dir.find(to*M+from) != dir.end()) continue;
        dir.insert(from*M+to);
        out[from] += 1;
        continue;
      }
      remain.push(to);
      par[to] = from;
      visit[to] = 1;
    }
  }
}

int main() {
  memset(par, 0, sizeof(par));
  memset(visit, 0, sizeof(visit));
  memset(out, 0, sizeof(out));

  int n, m;
