  for (int i = 0; i < m; ++i) {
    int from, to;
    cin >> from >> to;
    graph[from].push_back(to);
    graph[to].push_back(from);
  }
  if (m % 2 == 1) {
    cout << -1 << endl;
    return 0;
  }
  bfs(1);
  for (int i = n-1; i > 0; --i) {
    ll v = order[i];
    ll p = par[v];
    if (out[v] % 2 == 0) {
      dir.insert(p*M+v);
      out[p] += 1;
    }
    else {
      dir.insert(v*M+p);
      out[v] += 1;
    }
  }
  // cout << order << endl;
