typedef pair<int, int>P;
const int MOD = 998244353; const int MAX = 200020;
const double pi = acos(-1); const double EPS = 1e-12;
const ll INF = 1e18;
int siz[MAX];//錬結成分のサイズ
int par[MAX];//親
int Rank[MAX];//木の深さ

//n要素で初期化
void init(int n) {
	REP(i, n) {
		par[i] = i;
		Rank[i] = 0;
		siz[i] = 1;
	}
}

//木の根を求める
int find(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = find(par[x]);//経路圧縮(根に直接つなぎなおす)もしつつ
	}
}

//xとyの属する集合を併合
void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)return;
	//低いほうを高いほうにつなげる(効率化)
	if (Rank[x] < Rank[y]) {
		par[x] = y;
		siz[x] += siz[y];
		siz[y] = siz[x];
	}
	else {
		siz[y] += siz[x];
		siz[x] = siz[y];
		par[y] = x;
		if (Rank[x] == Rank[y])Rank[x]++;
	}
}

//xとyが同じ集合に属するか否か
bool same(int x, int y) {
	return find(x) == find(y);
}
vector<P>ans;
vector<int>G[100010];
int score[100010];
set<P>edges;
void dfs(int n, int pre) {
	for (auto nxt : G[n]) {
		if (pre == nxt)continue;
		dfs(nxt, n);
	}
	if (n != 0) {
		if (!(score[n] & 1)) {
			score[pre] ^= 1;
			ans.push_back({ pre,n });
		}
		else {
			ans.push_back({ n,pre });
		}
	}
}

void solve() {
	int N, M; cin >> N >> M;
	REP(i, M) {
		int u, v; cin >> u >> v;
		u--, v--;
		edges.insert({ u,v });
	}
	if (M & 1) { print(-1); return; }
	init(N+1);
	auto itr = edges.begin();
	//while (itr != edges.end()) {
	for(auto p:edges){
		//int u = itr->first, v = itr->second;
		int u = p.first, v = p.second;
		if (same(u, v)) { score[u] ^= 1; itr++; ans.push_back({ u,v }); }
		else {
			G[u].push_back(v);
			unite(u, v);
			itr++;
		}
	}
	dfs(0, 0);
	if (score[0] & 1) {
		print(-1); return;
	}
	else {
		if (ans.size() != M) {
			print(-1); return;
		}
		REP(i, M) {
			pe(ans[i].first+1); print(ans[i].second+1);
		}
	}
}


