bool dfs(int p, int r)
{
	int x = 0;

	D[p] = D[r] + 1;
	chk[p] = 1;

	for(int &t: T[p]){
		if(!chk[t]){
			if(dfs(t, p)) x ++;
		}
		else if(t != r){
			if(D[t] < D[p]){
				A.emplace_back(p, t);
