#define MAX_N 100000
#define MAX_M 100000

using namespace std;

struct Edge
{
    int to, idx;
};
vector<Edge> G[MAX_N];

struct Direction
{
    int from, to;

    bool is_defined() { return from >= 0 and to >= 0; }
};
Direction directions[MAX_M];

int num_edges[MAX_N];

void add_edge( int u, int v, int eidx )
{
    G[u].push_back( {v, eidx} );
    G[v].push_back( {u, eidx} );
    num_edges[u]++;
    num_edges[v]++;
}

bool visited[MAX_N];

void dfs( int root, int par )
{
    int eidx;

    for ( auto e : G[root] )
    {
        if ( e.to == par )
        {
            eidx = e.idx;
            continue;
        }
        if ( visited[e.to] ) continue;

        visited[e.to] = true;

        dfs( e.to, root );
    }

    int out = 0;
    for ( auto e : G[root] ) out += directions[e.idx].from == root;

    int remains = num_edges[root];
    if ( ( out + remains ) % 2 == 1 )
    {
        directions[eidx].from = par;
        directions[eidx].to = root;

        num_edges[root]--;
        num_edges[par]--;
        remains--;
    }

    for ( auto e : G[root] )
    {
        if ( remains == 0 ) break;

        Direction &d = directions[e.idx];
        if ( d.is_defined() ) continue;

        d.from = root;
        d.to = e.to;

        num_edges[root]--;
        num_edges[e.to]--;

        remains--;
    }
}

void init( int N, int M )
{
    for ( int i = 0; i < N; i++ ) num_edges[i] = 0;
    for ( int i = 0; i < M; i++ ) directions[i] = {-1, -1};
}

int main( int argc, char **argv )
{
    int N, M;
    cin >> N >> M;

    init( N, M );

    for ( int i = 0; i < M; i++ )
    {
        int A, B;
        cin >> A >> B;

        add_edge( A - 1, B - 1, i );
    }

    if ( M % 2 == 1 ) { cout << -1 << endl; }
    else
    {
        dfs( 0, -1 );

        for ( int i = 0; i < M; i++ )
        {
            if ( !directions[i].is_defined() )
            {
                cout << -1 << endl;
                return 0;
            }
        }

        for ( int i = 0; i < M; i++ )
        {
            cout << ( directions[i].from + 1 );
            cout << " ";
            cout << ( directions[i].to + 1 );
            cout << endl;
        }
    }

    return 0;
}

