void dfs(ll pos){
  for(int i=0;i<node[pos].size();i++){
    ll to=node[pos][i].first;
    if(!used[to]){
      used[to]=true;
      node2[pos].push_back(to);
      used2[node[pos][i].second]=true;
      dfs(to);
    }
  }
}
ll dfs2(ll pos){
  ll sum=cnt[pos];
  for(int i=0;i<node2[pos].size();i++){
    ll son=node2[pos][i];
    sum+=dfs2(son);
  }
  if(par[pos]==pos) return 0;
  if(sum%2==0){
    ans.push_back(P(par[pos],pos));
    return 1;
  }
  else{
    ans.push_back(P(pos,par[pos]));
    return 0;
  }
}
