const ll MAX = 1e5+5;
ll N, M;
vector<ll> G[MAX];
vector<ll> visit(MAX, 0);
vector<ll> cnt(MAX, 0);
vector<pair<ll, ll>> edges;
set<pair<ll, ll>> rev;

int dfs(ll now, ll prev) {
  visit[now] = 1;
  for (ll i : G[now]) {
    if (visit[i]) continue;
    dfs(i, now);
  }

  if ( cnt[now] % 2 ) {
    cnt[now]++;
    cnt[prev]--;
    rev.insert({now, prev});
    rev.insert({prev, now});
    // cout << SP << now << SP << prev << BR;
  }
  return 0;
}

int ans() {
  for (auto e: edges) {
    if ( rev.find(e) != rev.end() ) {
      cout << e.first << SP << e.second << BR;
    } else {
      cout << e.second << SP << e.first << BR;
    }
  }
  return 0;
}

