namespace dfs1 {
  void dfs(int v) {
    cnt[v] = 1;
    for(auto e: G[v]) {
      int t = e.first;
      int i = e.second;
      if(cnt[t]) continue;
      used[i] = 1;
      dfs(t);
    }
  }
}

namespace dfs2 {
  void dfs(int v, int f) {
    for(auto e: G[v]) {
      int t = e.first;
      int i = e.second;
      if(t == f) continue;
      if(!used[i]) continue;
      dfs(t, v);
    }
    if(cnt[v]) { 
      ans.emplace_back(v, f);
      cnt[v] ^= 1;
    }
    else {
      ans.emplace_back(f, v);
      cnt[f] ^= 1;
    }
  }
}

