bool DFS(int R, vector< vector<int> > & G, vector<int> & par, vector<int> & dep, vector<int> & used, vector< pair<int, int> > & ans) {
	vector<int> free;
	for(auto v : G[R]) {
		if(par[v] == -1) {
			par[v] = R;
			dep[v] = dep[R]+1;
			DFS(v, G, par, dep, used, ans);
			if(!used[v]) free.push_back(v);
		}
		if(par[v] != R && par[R] != v && dep[v] < dep[R]) free.push_back(v); // backlink
	}
	while((int)free.size() >= 2) {
		int v = free.back();
		free.pop_back();
		int u = free.back();
		free.pop_back();
		ans.push_back({R, u});
		ans.push_back({R, v});
	}
	if(!free.empty()) {
		if(par[R] == R) return false;
		ans.push_back({R, free[0]});
		ans.push_back({R, par[R]});
		used[R] = true;
	}
	return true;
}

