	return l.deg < r.deg;
}


int main()
{
	int n,m; cin>>n>>m;
	map<pair<int,int>,int> vis;
	if(m%2 == 1){ cout<<"-1"; return 0;}

	vector<int> g[MAX]; ds a[MAX];

	for(int i=0;i<m;i++){
		int u,v; cin>>u>>v; g[u].pb(v); g[v].pb(u);
	}

	for(int i=1;i<=n;i++){
		a[i].id=i;
		a[i].deg=g[i].size();
	}

	sort(a+1,a+n+1,cmp);

	for(int i=1;i<=n;i++){
		int sz = g[a[i].id].size();
		int j=0; int taken=0;
		while(j < sz){
			int y = g[a[i].id][j];
			int x = a[i].id;
			if(!vis[mp(min(x,y),max(x,y))] and taken%2 == 0 and j==sz-1) break;
