using vi=vector<int>;
using vvi=vector<vi>;
using pii=pair<int,int>;
using vpii=vector<pii>;
using vvpii=vector<vpii>;


bool dfs(const vvi& g, int par, int v, vi& vis, vi& outdeg, vvi& dg) {
    //cerr << "DBG vis " << v << endl;
    vis[v] = 1;
    for (int w: g[v]) {
        if (w == par || vis[w] == 2)
            continue;
        if (vis[w] == 1) {
            ++outdeg[v];
            dg[v].pb(w);
        }
        else {
            bool tmp = dfs(g, v, w, vis, outdeg, dg);
            assert(tmp);
        }
    }
    if (outdeg[v]%2 == 1) {
        if (par < 0)
            return false;
        ++outdeg[v];
        dg[v].pb(par);
    }
    else if (par >= 0) {
        ++outdeg[par];
        dg[par].pb(v);
    }
    vis[v] = 2;
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vvi g(n);
    for (int i=0; i<n; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].pb(b);
        g[b].pb(a);
    }

    vi outdeg(n,0);
    vvi dg(n);
    vi vis(n,0);
    if (!dfs(g, -1, 0, vis, outdeg, dg))
        cout << "-1\n";
    else {
        for (int i=0; i<n; ++i) {
            for (int v: dg[i])
                cout << i+1 << " " << v+1 << "\n";
        }
    }
}

