int n, m;
int c[100005], vs[100005];
vector<int> g[100005];
vector<pair<int,int> > res;
struct dsu{
	vector<int> p;
	void setup(int u){
		p.assign(u + 1, -1);
	}
	int f(int u){
		return (p[u] < 0 ? u : p[u] = f(p[u]));
	}
	bool j(int u, int v){
		u = f(u), v = f(v);
		if(u == v) return false;
		if(p[u] > p[v]) swap(u, v);
		p[u] += p[v];
		p[v] = u;
		return true;
	}
}ds;
void dfs(int u, int p){
	for(int v: g[u])
		if(v != p)
			dfs(v, u);
	if(u == 1) return;
	if(c[u]) res.push_back({u, p});
	else c[p] ^= 1, res.push_back({p, u}); 
}
signed main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> n >> m;
	ds.setup(n);
	if(m&1) return cout << -1, 0;
	for(int i = 1 ; i <= m ; i ++){
		int u, v;
		cin >> u >> v;
		if(ds.j(u, v)){
			g[u].push_back(v);
			g[v].push_back(u);
		} else{
			c[u] ^= 1;
			res.push_back({u, v});
		}
	}
	dfs(1, 0);
	for(pair<int,int> e: res)
		cout << e.first << " " << e.second << endl;
}

