int deg[100005];
void dfs(int u, int p){
    vis[u] = 1;
    for(int i=0;i<g[u].size();i++){
        int j = g[u][i];
        int v = b[j];
        if(v == u) v = a[j];
        if(vis[v]) continue;
        dfs(v, u);
    }

    int idx = -1;
    for(int i=0;i<g[u].size();i++){
        int j = g[u][i];
        if(ok[j]) continue;
        int v = b[j], r = 0;
        if(v == u) v = a[j], r = 1;
        if(v == p){
            idx = j;
            continue;
        }
        ok[j] = 1;
        deg[u]++;
        rev[idx] = r;
    }
    if(idx != -1){
        int j = idx;
        int v = b[j], r = 0;
        if(v == u) v = a[j], r = 1;

        ok[idx] = 1;
        if(deg[u]%2 == 1){
            deg[u]++;
            rev[idx] = r;
        }
        else{
            deg[p]++;
            rev[idx] = 1-r;
        }
    }
}
