void dfs (int v) {
    //cout << "  --dfs in " << v << endl;
    visited[v] = true;

    vi vis, notVis;
    for (int u : adj[v]) {
        if (dir[{u, v}] == 0) {
            if (!visited[u]) notVis.pb(u);
            else vis.pb(u);
        }
    }
    if ((notVis.size() & 1) && (vis.size() & 1)) {
        for (int u : vis) {
            dir[{v,u}] = 1;
            dir[{u,v}] = -1;
        }
        for (int u : notVis) {
            dir[{v,u}] = 1;
            dir[{u,v}] = -1;
        }
    } else if ((notVis.size()%2==0) && (vis.size()%2==0)) {
        for (int u : vis) {
            dir[{v,u}] = 1;
            dir[{u,v}] = -1;
        }
        for (int u : notVis) {
            dir[{v,u}] = 1;
            dir[{u,v}] = -1;
        }
    } else {
        if (vis.size() > 1){
            FOR(i, 0, (vis.size()/2)*2 - 1) {
                int u = vis[i];
                dir[{v,u}] = 1;
                dir[{u,v}] = -1;
            }
        }
        if (notVis.size() > 1) {
            FOR(i, 0, (notVis.size()/2)*2 - 1) {
                int u = vis[i];
                dir[{v,u}] = 1;
                dir[{u,v}] = -1;
            }
        }
    }

    //cout << " --dfs a in " << v << endl;

    for (int u : adj[v])
        if (!visited[u])
            dfs(u);

    //cout << " --ending dfs in " << v << endl;
}

