template<class T>
struct LinearSystemIncidence{
private:
    struct Edge{
        int id, to;
        bool fwd;
        Edge() = default;

        Edge(int id_, int to_, bool fwd_)
        : id(id_), to(to_), fwd(fwd_) {}
    };
    int n, m;   
    bool F2;
    std::vector<T> x;
    std::vector<bool> seen;
    std::vector<std::vector<Edge>> G;

public:
    LinearSystemIncidence() = default;

    LinearSystemIncidence(int n_, std::vector<std::pair<int, int>> &E, bool F2_ = false)
    : n(n_), m(E.size()), G(n_), F2(F2_){
        for(int i = 0; i < m; i++){
            G[E[i].first].emplace_back(i, E[i].second, true);
            G[E[i].second].emplace_back(i, E[i].first, false);
        }
    }

    T dfs(std::vector<T> &c, int u){
        seen[u] = true;
        T res = c[u];
        for(Edge e : G[u]){
            if(seen[e.to]) continue;
            T tmp = dfs(c, e.to);
            if(e.fwd) x[e.id] = tmp;
            else x[e.id] = -tmp;
            res += tmp;
            if(F2){
                x[e.id] %= 2;
                if(x[e.id] < 0) x[e.id] += 2;
            }
        }
        if(F2) res %= 2;
        return res;
    }

    std::pair<bool, std::vector<T>> solve(std::vector<T> &c){
        x.assign(m, 0);
        seen.assign(n, false);
        for(int i = 0; i < n; i++){
            if(seen[i]) continue;
            if(dfs(c, i)) return {false, std::vector<T>()};
        }
        return {true, std::move(x)};
    }
};

int main(){
    int n, m;
    std::cin >> n >> m;
    std::vector<std::pair<int, int>> E;
    std::vector<int> c(n);
    for(int i = 0; i < m; i++){
        int u, v;
        std::cin >> u >> v;
        u--; v--;
        E.emplace_back(u, v);
        c[u] ^= 1;
    }

    LinearSystemIncidence<int> LSI(n, E, true);
    auto res = LSI.solve(c);

    if(res.first){
        for(int i = 0; i < m; i++){
            if(res.second[i]) std::swap(E[i].first, E[i].second);
            std::cout << E[i].first + 1 << " " << E[i].second + 1 << '\n';
        }
    }
    else std::cout << -1 << '\n';
}

