class DAG {
private:
    ll v, e;
    vvl table;
    vl in_d; // 頂点の入力次数
public:
    // v: 頂点数
    // e: 辺の数
    DAG(ll v, ll e) : v(v), e(e) {
        table.resize(v);
        in_d.resize(v);
    }

    void add(ll from, ll to) {
        table[from].eb(to);
        in_d[to]++;
    }

    // O(v + e)
    // http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=GRL_4_B
    vl sort() {
        stack<ll> st; // 入力次数が0の頂点集合

        rep(i, v) if (in_d[i] == 0) st.push(i);
        vl ans; // ソート後のグラフ

        while (!st.empty()) {
            ll i = st.top();
            st.pop();
            ans.eb(i);
            each(j, table[i]) {
                in_d[j]--;
                if (in_d[j] == 0) st.push(j);
            }
        }

        return move(ans);
    }
};

