	vector<vector<lpair> > edges;
	vector<llong> nokori;

	cin >> N >> M;
	edges.resize(N+1);
	nokori.resize(N+1);
	for (int i = 0; i < M; ++i) {
		llong to, from;
		cin >> to >> from;
		edges[to].push_back(lpair(from, i));
		edges[from].push_back(lpair(to, i));
		nokori[to]++;
		nokori[from]++;
	}

	llong root = 1;
	for (int i = 1; i <= N; ++i)
		if (edges[i].size() == 1)
			root = i;


	vector<llong> cnt(N+1, 0), usedV(N+1, 0), usedE(M, 0);
	vector<lpair> ans;
	queue<llong> q;
	q.push(root);
	while (q.size()) {
		llong now = q.front();
		q.pop();
		if (usedV[now]) continue;
		usedV[now]++;

		vector<lpair> need;
		for (auto edge : edges[now]) {
			if (usedE[edge.second]) continue;
			if (nokori[edge.first] == 1 && cnt[edge.first] % 2 == 0)
				need.push_back(edge);
		}

		llong can = nokori[now] - need.size();
		if (cnt[now] % 2 == 0) {
			can -= can % 2 == 1;
		} else {
			can -= can %2 == 0;
		}


		for (auto edge : need) {
			usedE[edge.second]++;
			ans.push_back(lpair(now, edge.first));
			cnt[now]++;
			nokori[now]--;
			nokori[edge.first]--;
