			if (can > 0) {
				ans.push_back(lpair(now, edge.first));
				cnt[now]++;
				can--;
				nokori[now]--;
				nokori[edge.first]--;
			} else {
				ans.push_back(lpair(edge.first, now));
				cnt[edge.first]++;
				nokori[now]--;
				nokori[edge.first]--;
			}

			q.push(edge.first);
		}
	}

	bool check = true;
	for (auto c : cnt)
		if (c % 2 == 1)
			check = false;

	if (ans.size() != M || check == false) {
		cout << -1 << endl;
	} else {
		for (auto edge : ans)
			cout << edge.first << " " << edge.second << endl;
	}

	return 0;
}

