bool solve()
{
	scanf("%d%d", &N, &M);
	edges.resize(N);
	for (int i{}; i < M; i++)
	{
		int A, B;
		scanf("%d%d", &A, &B);
		A--; B--;
		edges[A].push_back({B, (int)edges[B].size(), -1});
		edges[B].push_back({A, (int)edges[A].size() - 1, -1});
	}
	if (M % 2 == 1) return false;
	visited.resize(N);
	dfs(0);
	return true;
}

void dfs(int index)
{
	if (visited[index]) return;
	visited[index] = true;
	for (int i{}; i < (int)edges[index].size(); i++)
		dfs(edges[index][i].to);

	int in_count{};
	for (auto& e: edges[index])
		if (e.dir == 0)
			in_count++;
	// outの数が偶数になるように調整したい
	for (auto& e: edges[index])
	{
		if (e.dir != -1) continue;
		if ((edges[index].size() - in_count) % 2)
		{
			in_count++;
			e.dir = 0;
			edges[e.to][e.rev_i].dir = 1;
		}
		else
		{
			e.dir = 1;
			edges[e.to][e.rev_i].dir = 0;
		}
	}
}

