struct UnionFind {
    V<ll> rank;
    V<ll> parent;

    UnionFind(ll N) : rank(N, 0), parent(N) {
        iota(parent.begin(), parent.end(), 0ll);
    }

    ll find(ll child) {
        return (child == parent[child] ? child : parent[child] = find(parent[child]));
    }

    void unit(ll x, ll y) {
        ll px = find(x);
        ll py = find(y);
        if(px == py) {
            return;
        }
        if(rank[px] < rank[py]) {
            swap(px, py);
        }
        parent[py] = px;
        rank[px] += (rank[px] == rank[py]);
    }

    bool same(ll x, ll y) {
        return (find(x) == find(y));
    }
};

V<set<ll>> edges;
VV<ll> tree_edges;
V<ll> tree_parents;

void dfs(ll now, ll pre, queue<ll> &que) {
    bool leaf = true;
    for(ll nxt : tree_edges[now]) {
        if(nxt == pre) continue;
        leaf = false;
        dfs(nxt, now, que);
    }
    tree_parents[now] = pre;
    if(leaf) que.push(now);
}

