    cout.tie(0);

    int n, m;
    cin >> n >> m;

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    if (m % 2 == 1) {
        cout << -1 << "\n";
        return 0;
    }

    vector<int> size(n);
    vector<int> sum(n, 0);
    vector<bool> visited(n, false);

    priority_queue <P, vector<P>, greater<P>> q;

    for (int i = 0; i < n; i++) {
        size[i] = edge[i].size();
        q.push(P(size[i], i));
    }

    vector <P> ans;

    while (q.size()) {
        P p = q.top();
        q.pop();

        int cur = p.second;
        if (visited[cur]) continue;
        visited[cur] = true;

        bool used = false;
