        for (int ch : edge[cur]) {
            if (!visited[ch]) {
                if (used) {
                    ans.push_back(P(cur + 1, ch + 1));
                    used = false;
                } else {
                    ans.push_back(P(ch + 1, cur + 1));
                    sum[ch]++;
                }
                size[ch]--;
                q.push(P(size[ch], ch));
            }
        }
    }

    for (P p : ans) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

