void init(int n) {
  for(int i = 0; i < n; i++) {
    p[i] = i;
    ra[i] = 0;
  }
}

int f(int x) {
  return p[x] == x ? x : (p[x] = f(p[x]));
}

bool un(int a, int b) {
  int x = f(a);
  int y = f(b);
  if(x == y) return false;

  if(ra[x] > ra[y]) {
    p[x] = y;
  }
  else {
    p[y] = x;
    if(ra[x] == ra[y]) ra[x]++;
  }
  return true;
}


