void add_edge(int u,int v)
{
	e[++edge_num].to=v;
	e[edge_num].nxt=head[u];
	head[u]=edge_num;
}
int vis[1000001];
int out[1000001];
void dfs(int u,int fa)
{
	vis[u]=1;
	int flag=0;
	for(int i=head[u];i!=-1;i=e[i].nxt)
	{
		int to=e[i].to;
		if(!flag&&to!=fa&&vis[to]==0)
		{
			flag=1;
			e[i].p=-1;
			e[i^1].p=-1;
			dfs(to,u);
		}
	}
}
void get_ans(int u,int fa)
{
	for(int i=head[u];i!=-1;i=e[i].nxt)
		if(e[i].to!=fa&&e[i].p==-1)
			get_ans(e[i].to,u);
	for(int i=head[u];i!=-1;i=e[i].nxt)
		if(e[i].to!=fa&&e[i].p==-1)
		{
			if(out[e[i].to]%2==0)
			{
				e[i].p=1;
				e[i^1].p=-2;
				out[u]++;
			}
			else
			{
				e[i^1].p=1;
				e[i].p=-2;
				out[e[i].to]++;
			}
		}
}
