  vector<vector<int>> A(N, vector<int>());
  // 有向グラフの逆
  vector<vector<int>> B(N, vector<int>());
  vector<bool> used(N, false);
  queue<int> Q;
  Q.push(0);
  bool ans = true;
  while(Q.size()) {
    int p = Q.front();
    Q.pop();
    used[p] = true;
    // 使える辺の数
    int nokori = graph[p].size() - A[p].size() - B[p].size();
    if(nokori == 0 && A[p].size() % 2 != 0) {
      ans = false;
      break;
    }
    if((nokori + A[p].size()) % 2 == 0) {
      for(auto x : graph[p]) {
        if(used[x]) { continue; }
        A[p].push_back(x);
        B[x].push_back(p);
        Q.push(x);
      }
    } else {
      bool ok = false;
      for(auto x : graph[p]) {
        if(used[x]) { continue; }
        if(graph[x].size() == 1) {
          A[p].push_back(x);
          B[x].push_back(p);
          Q.push(x);
        } else {
          if(!ok) {
            A[x].push_back(p);
            B[p].push_back(x);
            Q.push(x);
            ok = true;
          } else {
            A[p].push_back(x);
            B[x].push_back(p);
            Q.push(x);
          }
        }
        if(!ok) {
          ans = false;
          break;
        }
      }
    }
  }
  if(ans) {
    REP(i, N) {
      for(auto x : A[i]) {
        cout << i << ' ' << x << endl;
      }
    }
  } else {
    cout << -1 << endl;
  }
  return 0;
}

