#define MAX_N 100000
#define MAX_M 100000

using namespace std;

struct Edge
{
    int to, idx;
};
struct Direction
{
    int from, to;
    bool defined;
};
vector<Edge> G[MAX_N];
int num_edge[MAX_N];
vector<Direction> direction;

void add_edge( int u, int v, int eidx )
{
    G[u].push_back( {v, eidx} );
    G[v].push_back( {u, eidx} );
    num_edge[u]++;
    num_edge[v]++;
}

int main( int argc, char **argv )
{
    int N, M;
    cin >> N >> M;

    for ( int i = 0; i < M; i++ )
    {
        int A, B;
        cin >> A >> B;

        add_edge( A - 1, B - 1, i );
        direction.push_back( {0, 0, false} );
    }

    bool ok = true;
    while ( M > 0 )
    {
        if ( M % 2 != 0 )
        {
            ok = false;
            break;
        }

        bool all_odd = true;
        for ( int i = 0; i < N; i++ )
        {
            if ( num_edge[i] % 2 != 0 || num_edge[i] == 0 ) continue;

            all_odd = false;

            queue<int> q;
            q.push( i );

            while ( !q.empty() )
            {
                auto v = q.front();
                q.pop();

                for ( auto e : G[v] )
                {
                    if ( direction[e.idx].defined ) continue;

                    num_edge[v]--;
                    num_edge[e.to]--;
                    M--;

                    direction[e.idx] = {v, e.to, true};

                    if ( num_edge[e.to] % 2 != 0 ) continue;
                    if ( num_edge[e.to] == 0 ) continue;

                    q.push( e.to );
                }
            }
        }

        if ( all_odd )
        {
            ok = false;
            break;
        }
    }

    if ( ok )
        for ( auto d : direction )
            cout << ( d.from + 1 ) << " " << ( d.to + 1 ) << endl;
    else
        cout << -1 << endl;

    return 0;
}

