using namespace std;
const int INF = 2147483647;

struct edge
{
  int to, cost;
};
typedef std::vector<std::vector<edge>> graph;
graph prim(const graph &g, const int size, const int init)
{
  int mincost[size] = {};
  bool used[size] = {};

  REP(i, size)
  {
    mincost[i] = INF;
  }

  mincost[init] = 0;
  graph res(size);
  priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> q;
  for (auto v : g[init])
  {
    q.push(make_pair(v.cost, make_pair(init, v.to)));
  }
  used[init] = true;

  while (!q.empty())
  {
    auto p = q.top();
    q.pop();
    auto e = p.second;

    if (used[e.second])
      continue;

    res[e.first].push_back({e.second, p.first});
    res[e.second].push_back({e.first, p.first});

    for (auto v : g[e.second])
    {
      q.push(make_pair(v.cost, make_pair(e.second, v.to)));
    }
    used[e.second] = true;
  }
  return res;
}

void dfs(graph &ans, graph &ming, int now, int parent)
{
  if (parent == -1)
  {
    for (auto v : ming[now])
    {
      dfs(ans, ming, v.to, now);
    }
    return;
  }
  if (ming[now].size() == 1)
  {
    ans[ming[now][0].to].push_back({now, 1});
    return;
  }

  for (auto v : ming[now])
  {
    if (v.to == parent)
      continue;
    dfs(ans, ming, v.to, now);
  }

  if (ans[now].size() % 2 == 0)
  {
    ans[parent].push_back({now, 1});
  }
  else
  {
    ans[now].push_back({parent, 1});
  }
  return;
}

int main()
{
  int n, m;
  cin >> n >> m;
  graph g(n);
  REP(i, m)
  {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g[a].push_back({b, 1});
    g[b].push_back({a, 1});
  }
  if (m % 2 == 1)
  {
    cout << -1 << endl;
    return 0;
  }

  // 最小全域木を構成する
  graph ming = prim(g, n, 0);
  graph ans(n);

  REP(i, n)
  {
    for (auto v : g[i])
    {
      bool flag = false;
      // 高々2回
      for (auto pr : ming[i])
      {
        if (pr.to == v.to)
          flag = true;
      }
      if (flag)
        continue;

      if (i > v.to)
        ans[i].push_back(v);
    }
  }

  dfs(ans, ming, 0, -1);

  REP(i, n)
  {
    for (auto v : ans[i])
    {
      cout << i + 1 << " " << v.to + 1 << endl;
    }
  }
}

