vb passed;
set<PL> ans;

ll dfs(ll now, ll par){
    passed[now] = true;

    vl rem; ll cnt = 0;
    for(ll c : G[now]){
        if(c != par && !passed[c]){
            cnt += dfs(c, now);
        }
        else if(c != par){
            rem.pb(c);
        }
    }

    if(par == -1) return 0;

    ll tot = cnt;
    for(ll c : rem){
        if(ans.count({now, c}) == 0 && ans.count({c, now}) == 0){
            ans.insert({now, c});
            tot++;
        }
        else if(ans.count({now, c}) > 0){
            tot++;
        }
    }

    ll res;
    if(tot%2 == 1){
        res = 0;
        ans.insert({now, par});
    }
    else{
        res = 1;
        ans.insert({par, now});
    }
    return res;
}

