            ans.push_back({p,u});
            deg[p]^=1;
        }
        return;
    }
    for (auto v: adj[u])
    {
        if (v == p || visited_ans[v]) continue;
        dfs_ans(v,u);
    }
    if (u != 1)
    {
        if (deg[u]&1)
        {
            ans.push_back({u,p});
            deg[u]^=1;
        }
