typedef pair<ll,ll> P;

//#define all(v) (v).begin(), (v).end()
#define rep(i,a,b) for (int i = (a); i < (b); i++)
#define REP(i,n) rep(i,0,n)
#define sz(s) (s).size()
#define pb push_back
#define fi first
#define se second
//#define mp make_pair

int out[100010];
int a[100010];
vector<int> G[100010];
vector<pair<int,int>> ans;
map<pair<int,int>,bool> used;

void solve() {
  int n,m;
  cin >> n >> m;
  if (m & 1) {
    cout << -1 << endl;
    return;
  }
  priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pq;
  REP(i,m) {
    int aa,bb;
    cin >> aa >> bb;
    aa--;
    bb--;
    a[aa]++;
    a[bb]++;
    G[aa].pb(bb);
    G[bb].pb(aa);
    used[{aa,bb}] = 0;
    used[{bb,aa}] = 0;
  }
  REP(i,n) {
    pq.push({a[i],i});
  }
  while (!pq.empty()) {
    pair<int,int> tp = pq.top();
    pq.pop();
    int v = tp.se;
    int num = tp.fi;
    if (a[v] != num || a[v] == 0) continue;
    if ((out[v] + a[v]) % 2 == 0) {
      for (int i = 0; i < G[v].size(); i++) {
        int to = G[v][i];
        if (used[{v,to}]) continue;
        used[{v,to}] = 1;
        used[{to,v}] = 1;
        ans.pb({v,to});
        a[v]--;
        a[to]--;
        out[v]++;
        if (a[to] != 0)
          pq.push({a[to],to});
      }
    } else {
      bool f = 0;
      for (int i = 0; i < G[v].size(); i++) {
        int to = G[v][i];
        if (used[{v,to}]) continue;
        if (out[to]&1) {
          f = 1;
          used[{v,to}] = 1;
          used[{to,v}] = 1;
          ans.pb({to,v});
          out[to]++;
          a[v]--;
          a[to]--;
          if (a[to] != 0)
            pq.push({a[to],to});
        }
      }
      if (!f) {
        for (int i = 0; i < G[v].size(); i++) {
          int to = G[v][i];
          if (used[{v,to}]) continue;
          used[{v,to}] = 1;
          used[{to,v}] = 1;
          ans.pb({to,v});
          out[to]++;
          a[v]--;
          a[to]--;
          if (a[to] != 0)
            pq.push({a[to],to});
          break;
        }
      }
      for (int i = 0; i < G[v].size(); i++) {
        int to = G[v][i];
        if (used[{v,to}]) continue;
        used[{v,to}] = 1;
        used[{to,v}] = 1;
        ans.pb({v,to});
        a[v]--;
        a[to]--;
        out[v]++;
        if (a[to] != 0)
          pq.push({a[to],to});
      }
    }
  }
  bool ok = 1;
  REP(i,n) {
    if (out[i] % 2 != 0) ok = 0;
  }
  if (!ok) {
    cout << -1 << endl;
    return;
  }
  REP(i,sz(ans)) {
    cout << ans[i].fi + 1 << " " << ans[i].se + 1 << endl;
  }
}

