int N, M;
using edge = tuple<int, int>;
using info = tuple<int, int>;
set<int> V[100010];
vector<edge> ans;
bool visited[100010];
int cnt[100010];
priority_queue<info, vector<info>, greater<info>> Q;

void Yes()
{
  assert((int)ans.size() == M);
  vector<int> c(N, 0);
  for (auto x : ans)
  {
    cout << get<0>(x) + 1 << " " << get<1>(x) + 1 << endl;
    c[get<0>(x)]++;
  }
  for (auto i = 0; i < N; i++)
  {
    assert(c[i] % 2 == 0);
  }
  exit(0);
}
void No()
{
  cout << "-1" << endl;
  exit(0);
}

void solve()
{
  for (auto i = 0; i < N; i++)
  {
    Q.push(info(V[i].size(), i));
  }
  while (!Q.empty())
  {
    // int sz = get<0>(Q.top());
    int v = get<1>(Q.top());
    Q.pop();
    if (!visited[v])
    {
      visited[v] = true;
      for (auto x : V[v])
      {
        ans.push_back(edge(x, v));
        cnt[x]++;
        V[x].erase(v);
        Q.push(info(V[x].size(), x));
      }
      V[v].clear();
      if (cnt[v] % 2 == 1)
      {
        auto it = ans.end();
        --it;
        cnt[get<0>(*it)]--;
        swap(get<0>(*it), get<1>(*it));
      }
    }
  }
}

int main()
{
  cin >> N >> M;
  for (auto i = 0; i < M; i++)
  {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    V[a].insert(b);
    V[b].insert(a);
  }
  if (M % 2 == 1)
  {
    No();
  }
  solve();
  Yes();
}

