int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    G.resize(n);
    vector<P> num(n);
    rep(i, m) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        G[a].emplace_back(b, G[b].size());
        G[b].emplace_back(a, G[a].size()-1);
        num[a].first++;
        num[b].first++;
    }
    if(m&1) {
        cout << -1 << endl;
        return 0;
    }

    vector<P> ans;
    PQG<P> pq;
    rep(i, n) {
        pq.emplace(num[i].first, i);
    }
    while(!pq.empty()) {
        int now, nn;
        tie(nn, now) = pq.top();
        pq.pop();
        if(nn != num[now].first) continue;
        bool k = !!((nn + num[now].second)&1);
        for(edge e:G[now]) {
            if(e.to == -1) continue;
            G[e.to][e.rev].to = -1;
            if(k) {
                ans.emplace_back(e.to+1, now+1);
                num[e.to].first--;
                num[e.to].second++;
                pq.emplace(num[e.to].first, e.to);
                k = false;
            } else {
                ans.emplace_back(now+1, e.to+1);
                num[e.to].first--;
                pq.emplace(num[e.to].first, e.to);
            }
        }
    }
    rep(i, m) {
        cout << ans[i] << '\n';
    }
}

