bool isBipartite(vector<vector<long int>> &graph, vector<long int> &color){

    queue<pair<long int,long int>> q;
    vector<bool> visited(graph.size());
    visited[0] = true;
    color[0] = 0;
    q.push(make_pair(0,color[0]));

    while(!q.empty()){
        auto ele = q.front();
        q.pop();

        for(auto itr = graph[ele.first].begin(); itr != graph[ele.first].end(); itr++){
            if(!visited[*itr]){
                visited[*itr] = true;
                color[*itr] = 1 - ele.second;
                q.push(make_pair(*itr,color[*itr]));
                // cout<<color[*itr]<<endl;
            }
            else{
                if(color[*itr] == color[ele.first])
                    return false;
            }
        }
    }
    return true;
}

