void Addedge(int u,int v)
{
    E[++Cnt]=Edge(u,v);
    nxt[Cnt]=head[u];
    head[u]=Cnt;
}
void bfs(int root)
{
	int tot=0;
	queue<int> que;
	que.push(root);
	vis[root]=1;
	while(!que.empty())
	{
		int u=que.front();que.pop();
		f[++tot].id=tot,f[tot].num=u;
		id[u]=tot;
		for(int i=head[u];i;i=nxt[i])
			if(!vis[E[i].v])
			{
				vis[E[i].v]=1;
				que.push(E[i].v);
			}
	}
