        int Size;
        vector<T> Num;
        BIT<T>(){Size=0;}
        BIT<T>(int S){Num.resize((Size=S)+5,0);}
        void Update(T x,int pos){
            for(int i=pos;i<=Size;i+=lowbit(i))
                Num[i]+=x;
