  vector<unordered_set<int>> edges(n);
  rep(i, m) {
    int x, y; cin >> x >> y;
    x--, y--;
    edges[x].insert(y);
    edges[y].insert(x);
  }
  if (m % 2 == 1) no();
  vector<pair<int, int>> ans;
  vector<bool> v(n);
  rep(i, n) {
    if (v[i]) continue;
    int x = edges[i].size();
    if (x % 2 == 0) {
      each(s, edges[i]) {
        ans.emplace_back(i + 1, s + 1);
        edges[s].erase(i);
      }
    } else {
      int ss = i;
      while (true) {
        if (edges[ss].size() % 2 == 0) {
          each(s, edges[ss]) {
            ans.emplace_back(ss + 1, s + 1);
            edges[s].erase(ss);
          }
          break;
        }
        int c = 0;
        each(s, edges[ss]) {
          if (++c == edges[ss].size()) {
            ss = s;
          } else {
            ans.emplace_back(ss + 1, s + 1);
            edges[s].erase(ss);
          }
        }
      }
    }
  }
  rep(i, m) cout << ans[i] << '\n';
}

