  if ( !(odd == 2 || odd == 0) ) {
    std::cout << -1 << std::endl;
    return 0;
  }

  std::vector<int> tail;
  if ( odd == 2 ) dfs(t, tail);
  else dfs(0, tail);

  for(int i=0; i<tail.size()-1; i++) {
    if ( i % 2 == 0 ) std::cout << tail[i] << " " << tail[i+1] << std::endl;
    else std::cout << tail[i+1] << " " << tail[i] << std::endl;
  }

