void dfs(ll now, ll parent){
    used[now] = true;
    for(auto to:G[now]){
        if (used[to]) continue;
        dfs(to, now);
    }
    if (parent == -1) return;

    if(odd[now]){
        ans.eb(now, parent);
        odd.reset(now);
    }else{
