long getKey(int A, int B) {
  if (A < B) {
    return A * 100000 + B;
  } else {
    return B * 100000 + A;
  }
}

void addToResult(int u, int v) {
  vcount[u] -= 1;
  vcount[v] -= 1;
  mark[getKey(u, v)] = 0;
  result.emplace_back(u, v);
}

void solve(int u) {
  color[u] = 0;

  vector<int> next;
  for (int i = 0; i < adj[u].size(); i++) {
    int v = adj[u][i];
    if (mark[getKey(u, v)]) {
      addToResult(u, v);
      next.push_back(v);
    }
  }

  for (int i = 0; i < next.size(); i++) {
    if (color[next[i]] && vcount[i] >= 2 && vcount[i] % 2 == 0) {
      solve(next[i]);
    }
  }
}

