struct UnWeightedGraph {
  struct Edge {
    int to, rev;
    bool used = false;
    Edge(int to, int rev) : to(to), rev(rev) {}
  };
  vector<vector<Edge>> edges;
  int n;
  UnWeightedGraph(int n) : n(n) {
    edges.assign(n, vector<Edge>());
  }
  void add_edge(int v, int u) {
    edges[v].emplace_back(u, (int) edges[u].size());
    edges[u].emplace_back(v, (int) edges[v].size() - 1);
  }
  vector<Edge> &operator[](int x) {
    return edges[x];
  }
};

void solve() {
  int N, M; cin >> N >> M;
  auto graph = UnWeightedGraph(N);
  rep(i, M) {
    int u, v; cin >> u >> v;
    u--, v--;
    graph.add_edge(u, v);
  }
  if (M % 2 == 1) {
    cout << -1 << '\n';
    return;
  }
  vector<bool> seen(N);
  vi32 cnt(N);
  vector<pair<int, int>> ans;
  function<void(int, int)> dfs = [&](int v, int p) {
    seen[v] = true;
    each(e, graph[v]) {
      if (e.to == p) continue;
      if (seen[e.to]) {
        if (e.used) continue;
        ans.emplace_back(v + 1, e.to + 1);
        e.used = graph[e.to][e.rev].used = true;
        cnt[v]++;
        continue;
      }
      dfs(e.to, v);
      e.used = graph[e.to][e.rev].used = true;
    }
    if (p == -1) return;
    if (cnt[v] % 2 == 0) {
      ans.emplace_back(p + 1, v + 1);
      cnt[p]++;
    } else {
      ans.emplace_back(v + 1, p + 1);
      cnt[v]++;
    }
  };
  dfs(0, -1);
  rep(i, M) cout << ans[i] << '\n';
}

