vector<bool> seen;
vector<int> cnt;

struct Edge{
  int from;
  int to;
  long cost;

  bool operator<(const Edge& o) const {
    return cost < o.cost;
  }
};

void Initpar(int n){
  par = vector<int>(n); 
  for(int i=0; i<n; i++) par.at(i) = i;
}

int root(int x){
  if(x == par.at(x)) return x;
  else par.at(x) = root(par.at(x));
}

void unite(int x, int y){
  int rx = root(x);
  int ry = root(y);
  if(rx == ry) return;
  par.at(ry) = rx;
}

bool same(int x, int y){
  return root(x) == root(y);
}

long Kruskal(vector<vector<Edge>> &MinTree, vector<Edge> &Edges){
  sort(Edges.begin(), Edges.end());
  int m = Edges.size();
  long sum_cost = 0;
  for(int i=0;i<m;i++){
    Edge ed = Edges.at(i);
    int v = ed.from;
    int nv = ed.to;
    if(same(v, nv)) continue;
    unite(v, nv);
    sum_cost += ed.cost;
    MinTree.at(v).push_back({v, nv, ed.cost});
    MinTree.at(nv).push_back({nv, v, ed.cost});
    seen.at(i) = true;
  }
  return sum_cost;
}

void dfs(vector<vector<Edge>> &MinTree, int v, int pv){
  for(Edge ed : MinTree.at(v)){
    int nv = ed.to;
    if(nv == pv) continue;
    dfs(MinTree, nv, v);
  }
  if(v == 0) return;
  if(cnt.at(v) % 2 == 0){
    cout << pv+1 << " " << v+1 << endl;
    cnt.at(pv)++;
  }else{
    cout << v+1 << " " << pv+1 << endl;
    cnt.at(v)++;
  }
  return;
}

int main(){
  int n,m;
  cin >> n >> m;
  if(m % 2 == 1){
    cout << -1 << endl;
    return 0;
  }
  vector<Edge> Edges;
  vector<vector<Edge>> MinTree(n);
  Initpar(n);
  seen = vector<bool>(m, false);
  rep(i,m){
    int a,b;
    cin >> a >> b;
    a--;b--;
    Edges.push_back({a,b,1});
  }
  Kruskal(MinTree, Edges);
  cnt = vector<int>(n, 0);
  rep(i,m){
    if(seen.at(i)) continue;
    cout << Edges.at(i).from+1 << " " << Edges.at(i).to+1 << endl;
    cnt.at(Edges.at(i).from)++;
  }
  dfs(MinTree, 0, -1);
}

