template<typename T>
struct LinearSystemIncidence {
  struct Edge {
    int id, to;
    bool fwd;
    Edge(int i, int t, bool f) : id(i), to(t), fwd(f) {}
  };

  int n, m;
  vector<T> x;
  vector<bool> seen;
  vector<vector<Edge>> G;

  LinearSystemIncidence(int n, vector<P> &E) : n(n), m(E.size()), G(n) {
    rep(i, m) {
      G[E[i].first].emplace_back(i, E[i].second, true);
      G[E[i].second].emplace_back(i, E[i].first, false);
    }
  }

  T dfs(vector<T> &b, int u) {
    seen[u] = true;
    T res = b[u];
    for (Edge e : G[u]) {
      if (seen[e.to]) continue;
      T tmp = dfs(b, e.to);
      x[e.id] = tmp * (e.fwd ? 1 : -1);
      res += tmp;

      // mod2
      x[e.id] %= 2;
      if (x[e.id] < 0) x[e.id] += 2;
      ////
    }
    res %= 2; // mod 2
    return res;
  }

  pair<bool, vector<T>> solve(vector<T> &b) {
    x.assign(m, 0);
    seen.assign(n, false);
    for (int s = 0; s < n; ++s) {
      if (seen[s]) continue;
      if (dfs(b, s)) return {false, vector<T>()};
    }
    return {true, move(x)};
  }
};


int main() {
  ll n, m; cin >> n >> m;
  vector<P> E;
  Vll c(n);
  rep(i, m) {
    int u, v; cin >> u >> v;
    --u, --v;
    E.emplace_back(u, v);
    ++c[v];
  }

  LinearSystemIncidence<ll> LSI(n, E);
  auto sol = LSI.solve(c);

  if (!sol.first) {
    cout << -1 << "\n";
    return 0;
  }
  rep(i, m) {
    if (sol.second[i] == 0) swap(E[i].first, E[i].second);
    ++E[i].first;
    ++E[i].second;
    cout << E[i].first << " " << E[i].second << "\n";
  }
  return 0;
}

