// クラスカル法
// 連結グラフの最小全域木を求める
class Kruskal {
private:
  Graph graph;
  vector<Edge> MinimumSpanningTree;
  ll minimumCost;
  void searchMinimumSpanningTree() {
    UnionFindTree uf(graph.nodes);
    sort(all(graph.edges));
    itrep(edge, graph.edges) {
      if (!uf.same(edge->from, edge->to)) {
        uf.unite(edge->from, edge->to);
        MinimumSpanningTree.push_back(*edge);
      }
    }
  }

public:
  Kruskal(Graph graph) { this->graph = graph; }
  ll getMinimumSpanningTreeCost() {
    searchMinimumSpanningTree();
    ll cost = 0;
    itrep(it, MinimumSpanningTree) { cost += it->cost; }
    return cost;
  }
};

// ダイクストラ法 O((E+V)logV)
// 最小経路問題を解くためのアルゴリズム。辺の重みに負数を含む場合は利用不可
class Dijkstra {
private:
  Graph graph;
  map<ll, vector<Edge>> fromPaths;
  vl distances;
  vl srcs;

public:
  Dijkstra(Graph graph) {
    this->graph = graph;
    itrep(edge, graph.edges) {
      fromPaths[edge->from].push_back(*edge);
      fromPaths[edge->to].push_back(Edge(edge->to, edge->from, edge->cost));
    }
  }
  void searchMinimumPathFrom(ll src) {
    // 複数回呼ばれる度に計算する
    this->distances = vl(graph.nodes + 1, INF);
    this->srcs = vl(graph.nodes + 1, INF);

    priority_queue<ll> pq;
    distances[src] = 0;
    srcs[src] = -1;

    pq.push(src);
    while (!pq.empty()) {
      int u = pq.top();
      pq.pop();

      itrep(edge, fromPaths[u]) {
        int v = edge->to;
        int w = edge->cost;
        if (distances[v] > distances[u] + w) {
          distances[v] = distances[u] + w;
          srcs[v] = u;
          pq.push(v);
        }
      }
    }
  };
  ll getDistance(ll n) { return this->distances[n]; }
  ll getFrom(ll n) { return this->srcs[n]; }
};

// ベルマンフォード O(|V||E|)
// 非負コストが含まれていても最短経路問題を解くためのアルゴリズム。閉路の検出も可能
class BellmanFord {
private:
  Graph graph;
  // 閉路が含まれるかは個々のノードごとに管理する必要あり
  vector<bool> hasNegativeCycles;
  vector<ll> distances;

public:
  BellmanFord(Graph graph) {
    this->graph = graph;
    this->distances = vector<ll>(this->graph.nodes + 1, INF);
    this->hasNegativeCycles = vector<bool>(this->graph.nodes + 1, false);
  }
  void searchMinimumPathFrom(ll src) {
    this->distances[src] = 0;

    for (ll i = 0; i < graph.nodes - 1; i++) {
      itrep(edge, graph.edges) {
        ll u = edge->from;
        ll v = edge->to;
        ll w = edge->cost;
        if (this->distances[u] + w < this->distances[v]) {
          this->distances[v] = this->distances[u] + w;
        }
      }
    }

    itrep(edge, graph.edges) {
      ll u = edge->from;
      ll v = edge->to;
      ll w = edge->cost;
      if (this->distances[u] + w < this->distances[v]) {
        this->hasNegativeCycles[v] = true;
      }
      if (this->hasNegativeCycles[u] == true) {
        this->hasNegativeCycles[v] = true;
      }
    }
  }
  ll getDistance(ll n) { return this->distances[n]; }
  bool hasNegativeCycle(ll n) { return this->hasNegativeCycles[n]; }
};

void solve(long long N, long long M, std::vector<long long> A,
           std::vector<long long> B) {
  vl connectNum(N + 1);
  vl connectedNum(N + 1, 0);
  map<ll, set<ll>> connectedNodes;

  rep(m, 0, M) {
    connectedNodes[A[m]].insert(B[m]);
    connectedNodes[B[m]].insert(A[m]);

    connectNum[A[m]]++;
    connectNum[B[m]]++;
  }

  set<pll> fewConnectedNodes;
  rep(i, 1, N + 1) { fewConnectedNodes.insert(mp(connectNum[i], i)); }

  // connectNumが少ない順番に処理する
  vector<pll> ansEdges;
  while (!fewConnectedNodes.empty()) {
    auto p = fewConnectedNodes.begin();
    ll cn = p->first;
    ll n = p->second;
    fewConnectedNodes.erase(p);

    if (connectedNodes[n].size() == 0) {
    } else if (connectedNodes[n].size() == 1) {
      ll connectNode = *(connectedNodes[n].begin());
      fewConnectedNodes.erase(mp(connectNum[connectNode], connectNode));

      if (connectedNum[n] % 2 == 0) {
        connectedNum[connectNode]++;
        connectNum[connectNode]--;
        ansEdges.push_back(mp(connectNode, n));
      } else {
        connectedNum[n]++;
        connectNum[n]--;
        ansEdges.push_back(mp(n, connectNode));
      }

      connectedNodes[connectNode].erase(n);
      fewConnectedNodes.insert(mp(connectNum[connectNode], connectNode));
    } else {
      ll connectNode = *(connectedNodes[n].begin());
      fewConnectedNodes.erase(mp(connectNum[connectNode], connectNode));

      connectedNum[n]++;
      connectNum[n]--;
      connectNum[connectNode]--;
      ansEdges.push_back(mp(n, connectNode));

      connectedNodes[connectNode].erase(n);
      connectedNodes[n].erase(connectNode);
      fewConnectedNodes.insert(mp(connectNum[connectNode], connectNode));
      fewConnectedNodes.insert(mp(connectNum[n], n));
    }
  }

  rep(i, 1, N + 1) {
    if (connectedNum[i] % 2 != 0) {
      print("-1");
      return;
    }
  }

  itrep(edge, ansEdges) { print(edge->first << " " << edge->second); }
}

