		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	stack<pair<int, vector<int>>> stk;
	for (int i = 0; i < N; i++) {
		if (out[i] == 1) {

			vector<int> visited(N), memo{i};
			stk.emplace(i, memo);

			while (!stk.empty()) {

				int now = stk.top().first;
				auto memonow = stk.top().second;
				visited[now] = 1;
				stk.pop();

				bool flag = true;
				for (const auto &e : edge[now]) {
					if (out[e] == 1) {
						out[i] ^= 1;
						out[e] ^= 1;
						flag = false;
						memonow.emplace_back(e);
						break;
