    cout.tie(0);

    int n, m;
    cin >> n >> m;

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    if (m % 2 == 1) {
        cout << -1 << "\n";
        return 0;
    }

    vector<int> size(n);
    vector<int> sum(n, 0);
    vector<bool> visited(n, false);

    priority_queue <P, vector<P>, greater<P>> q;

    for (int i = 0; i < n; i++) {
        size[i] = edge[i].size();
        q.push(P(size[i], i));
    }

    vector <P> ans;

    while (q.size()) {
        P p = q.top();
        q.pop();

        int cur = p.second;
        if (visited[cur]) continue;
        visited[cur] = true;

        if (sum[cur] == 1) {
            bool used = true;
            for (int ch : edge[cur]) {
                if (!visited[ch]) {
                    if (used) {
                        ans.push_back(P(cur + 1, ch + 1));
                        size[ch]--;
                        q.push(P(size[ch], ch));
                        used = false;
                    } else {
                        ans.push_back(P(ch + 1, cur + 1));
                        size[ch]--;
                        sum[ch] = (sum[ch] + 1) % 2;
                        q.push(P(size[ch], ch));
                    }
                }
            }
        } else {
            for (int ch : edge[cur]) {
                if (!visited[ch]) {
                    ans.push_back(P(ch + 1, cur + 1));
                    size[ch]--;
                    sum[ch] = (sum[ch] + 1) % 2;
                    q.push(P(size[ch], ch));
                }
            }
        }
    }

    for (P p : ans) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

