bool dfs(int v, int p) {
	h[v] = h[p] + 1;
	odw[v] = true;
	int deg = 0;
	for (auto it : g[v]) {
		if (odw[it]) {
			if (it != p && h[it] < h[v]) {
				deg++;
				res.pb({v, it});
			}
