using namespace std;
const int N=1e5+5;
struct edge{
	int to,next,ok;
} e[N];
int n,m,good=1,h[N];
int visited[N],check[N];
void add(int u,int v){
	e[++good]=(edge){v,h[u],0};
	h[u]=good;
}
void dfs(int u,int p){
	visited[u]=++*visited;
	for(int i=h[u];i;i=e[i].next){
		if(i^p^1){
			if(!visited[e[i].to]){
				dfs(e[i].to,i);
				if(check[e[i].to]&1){
					e[i].ok=-1;
					e[i^1].ok=1;
					check[e[i].to]^=1;
				}
				else{
					e[i].ok=1;
					e[i^1].ok=-1;
					check[u]^=1;
				}
			}
			else if(visited[e[i].to]<visited[u]){
				e[i].ok=1;
				e[i^1].ok=-1;
				check[u]^=1;
			}
		}
	}
}
