#include <bits/stdc++.h>
using namespace std;

using pii = pair<int, int>;

class union_find {
public:
    union_find(int n) : par(n, -1) {}

    int root(int x) {
        return par[x] < 0 ? x : par[x] = root(par[x]);
    }

    bool unite(int x, int y) {
        x = root(x), y = root(y);
        if(x == y) return false;
        if(par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

private:
    vector<int> par;
};

int main() {
    int n, m; cin >> n >> m;

    vector<vector<int>> g(n); // tree
    vector<int> pari(n);
    union_find uf(n);
    vector<pii> ans;
    for(int i = 0; i < m; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        if(uf.unite(a, b)) {
            ans.emplace_back(a,  b);
            pari[a] ^= 1;
        } else {
            g[a].push_back(b);
            g[b].push_back(a);
        }
    }

    function<void(int, int)> dfs = [&] (int v, int p) {
        for(auto to : g[v]) {
            if(p == to) continue;
            dfs(to, v);
        }
        if(p != -1) { // not root
            if(pari[v]) {
                ans.emplace_back(v, p);
            } else {
                ans.emplace_back(p, v);
                pari[p] ^= 1;
            }
        }
    };
    dfs(0, -1);

    if(pari[0]) {
        cout << -1 << endl;
    } else {
        for(auto const& e : ans) {
            cout << e.first + 1 << " " << e.second + 1 << endl;
        }
    }
}

