const int N=1e5;
vector<int> lnk[N+3];
int n,m,nidx;
int du[N+3],dep[N+5];
int idx[N+3];
vector<pair<int,int> >ans;
int DFS(int u,int depth,int pre){
	idx[u]=++nidx;
	dep[u]=depth;
	int ret=0;
	for(auto v : lnk[u]){
		if(v==pre) continue;
		if(dep[v]){
			if(dep[v]<dep[u]) ret++,ans.push_back(make_pair(u,v));
			continue;
		}
		int retv=DFS(v,depth+1,u);
		if(retv%2==0) ret++,ans.push_back(make_pair(u,v));
		else ans.push_back(make_pair(v,u));
	}
	return ret;
}
int main(){
	scanf("%d%d",&n,&m);
	for(int i=0;i<m;i++){
		int u,v;scanf("%d%d",&u,&v);
		lnk[u].push_back(v);
		lnk[v].push_back(u);
		du[u]++;du[v]++;
	}
	int res=DFS(1,1,0);
	if(res%2) printf("-1\n");
	else{
		for(int i=0;i<ans.size();i++)
			printf("%d %d\n",ans[i].first,ans[i].second);
	}
	return 0;
}

