void solve(int N, vector<vector<int>>&E)
{
	vector<char>used(N);
	vector<int>level(N);

	priority_queue<pair<int,int>>Q;
	for (int i = 0; i < N; i++)
	{
		Q.push(make_pair(E[i].size()%2, i));
		level[i] = E[i].size() % 2;
	}

	while (Q.size())
	{
		int l= Q.top().first;
		int v = Q.top().second;Q.pop();
		if(used[v])continue;
		if(level[v] != l)continue;
		used[v] = true;

		for (int j = 0; j < E[v].size(); j++)
		{
			int u = E[v][j];
			if(used[u])continue;
			level[u] ^= 1;
			Q.push(make_pair(level[u], u));

			if (l)
			{
				cout<<u+1<<" "<<v+1<<endl;
				l--;
			}
			else
			{
				cout<<v+1<<" "<<u+1<<endl;
			}
		}

	}
}

