      --A; --B;

      to[A].push_back({B, i});
      to[B].push_back({A, i});
    }

    vector<int> used_node(N, false);
    vector<int> used_edge(M, false);
    vector<int> C, D;
    stack<int> s;
    s.push(0);
    while(s.size()){
      int node = s.top();
      s.pop();

      int ngbr = 0;
      for(auto [next, edge] : to[node]){
        if(used_edge[edge]) continue;

        ++ngbr;
        if(!used_node[next]){
          used_node[next] = true;
          s.push(next);
        }
      }

      ngbr ^= (ngbr & 1);
      for(auto [next, edge] : to[node]){
        if(used_edge[edge] || !ngbr) continue;

        --ngbr;
        used_edge[edge] = true;
        C.push_back(node + 1); D.push_back(next + 1);
      }
    }

    for(int i = 0; i < M; i++){
      cout << C[i] << ' ' << D[i] << endl;
