class Solve {
public:
    int N, M;
    vector<vector<pair<int, bool>>> G;
    vector<pair<int, int>> ans;
    vector<int> cnt;
    vector<bool> visit;
    vector<int> restdig;

    void dfs(int v) {
        visit[v] = true;
        //辺を貼る
        for (int i = 0; i < G[v].size(); ++i) {

//        for (auto nv : G[v]) {
            auto nv = G[v][i];
            if (!nv.second) {
                if (cnt[v] % 2 == 0) {
                    //自分に向かう辺を貼る
                    ans.emplace_back(nv.first, v);
                    cnt[nv.first]++;
                } else {
                    ans.emplace_back(v, nv.first);
                    cnt[v]++;
                }
                G[v][i].second = true;
                int pt =
                        lower_bound(G[nv.first].begin(), G[nv.first].end(), make_pair(v, false)) - G[nv.first].begin();
                G[nv.first][pt].second = true;
            }
        }
        //探索する
        for (auto nv : G[v]) {
            if (!visit[nv.first]) {
                dfs(nv.first);
            }
        }
    }

    void solve() {
        cin >> N >> M;
        G.resize(N);
        cnt.resize(N);
        visit.resize(N, false);
        restdig.resize(N);
        for (int i = 0; i < M; ++i) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(make_pair(b, false));
            G[b].push_back(make_pair(a, false));
            restdig[a]++;
            restdig[b]++;
        }

        queue<int> que;
        for (int i = 0; i < N; ++i) {
            sort(all(G[i]));
            if (restdig[i] == 1) {
                que.push(i);
            }
        }

        while (!que.empty()) {
            int v = que.front();
            que.pop();


            int u = G[v][0].first;
            if (G[v][0].second) continue;

            if (cnt[v] % 2 == 0) {
                ans.emplace_back(u, v);
                cnt[u]++;
            } else {
                ans.emplace_back(v, u);
                cnt[v]++;
            }
            G[v][0].second = true;
            int pt =
                    lower_bound(G[u].begin(), G[u].end(), make_pair(v, false)) - G[u].begin();
            G[u][pt].second = true;

            restdig[v]--;
            restdig[u]--;

            if (restdig[u] == 1) {
                que.push(u);
            }
        }

        dfs(0);

//        int st = 0;
//        for (int i = 0; i < N; ++i) {
//            if (G[i].size() == 1) st = i;
//        }
//        dfs(st);


        for (int i = 0; i < N; ++i) {
            if (cnt[i] % 2) {
                cout << -1 << endl;
                return;
            }
        }

//        assert(ans.size() == M);
//        if (ans.size() != M) {
//            exit(-1);
//        }

        for (auto e : ans) {
            cout << e.first + 1 << " " << e.second + 1 << endl;
        }

    }
};


