pair<int, int> get_edge(int a, int b) {
  return a < b ? make_pair(a, b) : make_pair(b, a);
}

int check_greedy(const vector<vector<int>> &adj_lists,
                 map<pair<int, int>, int> &edge_to_dir, int cur) {
  // count number of unused edges
  int cnt_unused = 0;
  for (int nxt : adj_lists[cur]) {
    pair<int, int> edge = get_edge(cur, nxt);
    if (edge_to_dir[edge] == 0) {
      cnt_unused++;
    }
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  int N, M, as[MAX_M], bs[MAX_M];
  scanf("%d %d", &N, &M);
  for (int k = 0; k < M; k++) {
    scanf("%d %d", &as[k], &bs[k]);
    as[k]--;  // NOTE : modified input
    bs[k]--;  // NOTE : modified input
  }

  // create graph
  vector<vector<int>> adj_lists(N, vector<int>());
  map<pair<int, int>, int> edge_to_dir;
  vector<int> node_ranks(N, 0);
  for (int k = 0; k < M; k++) {
    const int a = as[k], b = bs[k];
    adj_lists[a].push_back(b);
    adj_lists[b].push_back(a);
    node_ranks[a]++;
    node_ranks[b]++;
  }

  // greedy from smallest rank
  // insert all nodes into queue
  vector<int> cs, ds, num_outs(N, 0);
  priority_queue<pair<int, int>, vector<pair<int, int>>,
                 greater<pair<int, int>>>
      que;
  for (int i = 0; i < N; i++) {
    que.push(make_pair(node_ranks[i], i));
  }
  while (!que.empty()) {
    // take node with smallest positive rank
    int cur = que.top().second, rank = que.top().first;
    que.pop();
    // printf("cur = %d, node_ranks[cur] = %d\n", cur, node_ranks[cur]);
    if (node_ranks[cur] == 0) {
      continue;
    }
    // count remaining edges
    int cnt_unused = 0;
    for (int nxt : adj_lists[cur]) {
      pair<int, int> edge = get_edge(cur, nxt);
      if (edge_to_dir[edge] == 0) {
        cnt_unused++;
      }
    }
    // printf("cur = %d, cnt_unused = %d\n", cur, cnt_unused);
    // choose direction of remaining edges
    int cnt = 0;
    const int cnt_lim =
        (cnt_unused + num_outs[cur]) % 2 == 0 ? cnt_unused : cnt_unused - 1;
    for (int nxt : adj_lists[cur]) {
      pair<int, int> edge = make_pair(cur, nxt), rev_edge = make_pair(nxt, cur);
      if (edge_to_dir[edge] == 0) {
        if (cnt < cnt_lim) {
          edge_to_dir[edge] = 1;       // out from cur
          edge_to_dir[rev_edge] = -1;  // in to nxt
          num_outs[cur]++;
          cs.push_back(cur + 1);
          ds.push_back(nxt + 1);
        } else {
          edge_to_dir[edge] = -1;     // in to cur
          edge_to_dir[rev_edge] = 1;  // out from nxt
          num_outs[nxt]++;
          cs.push_back(nxt + 1);
          ds.push_back(cur + 1);
        }
        cnt++;
        node_ranks[cur]--;
        node_ranks[nxt]--;
        que.push(make_pair(node_ranks[nxt], nxt));
        // printf("c = %d, d = %d\n", cs[cs.size() - 1], ds[ds.size() - 1]);
      }
    }
  }

  // check
  int is_possible = 1;
  for (int i = 0; i < N; i++) {
    if (num_outs[i] % 2 == 1) {
      is_possible = 0;
    }
  }

  if (is_possible) {
    for (int k = 0; k < cs.size(); k++) {
      printf("%d %d\n", cs[k], ds[k]);
    }
  } else {
    printf("-1\n");
  }

  return 0;
}

