using namespace std;
typedef pair<int, int> P;
P edge[100000];
vector<int> v[100000];
int d[100000];
int w[100000];

int main(void){
    int n, m;
    priority_queue<P, vector<P>, greater<P> > q;
    vector<P> ans;
    cin >> n >> m;
    fill(d, d+n, 0);
    fill(w, w+n, 0);

    for(int i=0;i<m;i++){
        int a, b;
        cin >> a >> b;
        edge[i] = P(--a, --b);
        v[a].push_back(i);
        v[b].push_back(i);
        d[a]++;
        d[b]++;
    }
    if(m%2 == 1){
        cout << -1 << endl;
        return 0;
    }
    for(int i=0;i<n;i++){
        q.push(P(d[i], i));
    }
    while(!q.empty()){
        int x;
        P p = q.top();
        q.pop();
        x = p.second;
        if(d[x] <= 0)continue;
        for(int i=0;i<v[x].size();i++){
            P e = edge[v[x][i]];
            int y = e.first;
            if(y == -1)continue;
            if(y == x)y = e.second;
            edge[v[x][i]] = P(-1, -1);
            if(d[y] > 0){
                if(w[x]%2 == 0){
                    ans.push_back(P(y+1, x+1));
                    //cout << y << "->" << x << endl;
                    d[x]--;
                    d[y]--;
                    w[y]++;
                }else{
                    ans.push_back(P(x+1, y+1));
                    //cout << x << "->" << y << endl;
                    d[x]--;
                    d[y]--;
                    w[x]++;
                }
                if(d[x] > 0)q.push(P(d[x], x));
                if(d[y] > 0)q.push(P(d[y], y));
                break;
            }
        }
    }
    if(ans.size() != m){
        cout << -1 << endl;
        return 0;
    }
    for(int i=0;i<m;i++){
        cout << ans[i].first << " " << ans[i].second << endl;
    }
}

