	if(m&1)
	{
		printf("-1");
		return 0;
	}
	for(int i=1;i<=m;i++)
		scanf("%d%d",&x[i],&y[i]);
	kruskal();
	dfs(1,0);
	for(auto [u,v]:res)
		printf("%d %d\n",u,v);
	return 0;
}

