using namespace std;

int main()
{
    int n, m;
    cin >> n >> m;
    vector<int> a(m);
    vector<int> b(m);
    //頂点用のデータ構造
    struct node {
        int index;
        vector<int> in;
        vector<int> out;
    };
    vector<node> nodes(n);
    map<pair<int, int>, int> edge;
    for(int i = 0; i < m; i++)
    {
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
        //辺の情報を記録
        edge[{a[i], b[i]}] = 0;
        edge[{b[i], a[i]}] = 0;
        //node iの初期化
        nodes[a[i]].index = 0;
        nodes[a[i]].out.push_back(b[i]);
        nodes[b[i]].in.push_back(a[i]);
    }
    if(m % 2 == 1){
        cout << -1 << endl;
    }else{
        //整合性を取る
        for(int i = 0; i < n; i++)
        {
            if(nodes[i].out.size() % 2 == 0) continue;
            //outのサイズが偶数出ない場合はoutをへらすかinをへらす
            //どちらも辺の状態が0のものから選ぶ
            bool in = true;
            for(int j = 0; j < nodes[i].out.size(); j++)
            {
                if(edge[{i, nodes[i].out[j]}] == 0)
                {
                    in = false;
                    int from = nodes[i].out[j];
                    nodes[i].in.push_back(from);
                    nodes[from].out.push_back(i);
                    edge[{i, from}] = -1;
                    edge[{from, i}] = 1;
                    break;
                }
            }
            if(in){
                for(int j = 0; j < nodes[i].in.size(); j++)
                {
                    if(edge[{i, nodes[i].in[j]}] == 0)
                    {
                        int to = nodes[i].in[j];
                        nodes[i].out.push_back(to);
                        nodes[to].in.push_back(i);
                        edge[{i, to}] = 1;
                        edge[{to, i}] = -1;
                    }
                }
            }
        }
        for(int i = 0; i < n; i++)
        {
            for(int j = 0; j < nodes[i].out.size(); j++)
            {
                if(edge[{i, nodes[i].out[j]}] != -1){
                    cout << i + 1 << " " << nodes[i].out[j] + 1 << endl;
                }
            }
        }
    }
}

