int main() {
  // 無向(有向)グラフの隣接行列
  int n, m, u, v;
  cin >> n >> m;

  int M[n][n]; // 頂点数が n のグラフを表す隣接行列
  for(int i = 0; i < n; i++){
    for(int j = 0; j < n; j++){
      M[i][j] = 0;
    }
  }

  vector<int> x(n);
  for(int i = 0; i < m; i++){
    cin >> u >> v;
    u--;
    v--;
    M[u][v] = 1;
    M[v][u] = 1; // 有向グラフではこの行をコメントアウト
    x.at(u)++;
    x.at(v)++;
  }

  if(m % 2 == 1){
    cout << -1 << endl;
  }
  else{
    while(m != 0){
      for(int i = 0; i < n; i++){
        if(x.at(i) >= 2 && x.at(i) % 2 == 0){
          for(int j = 0; j < n; j++){
            if(M[i][j] == 1){
              cout << i + 1 << " " << j + 1 << endl;
              M[i][j] = 0;
              M[j][i] = 0;
              x.at(i)--;
              x.at(j)--;
              m -= 2;
            }
          }
        }
      }
    }
  }
}

