class UnionFind {
	vector<int>parent;
	vector<int>rank;
public:
	UnionFind(int num) {
		num++;
		parent.resize(num);
		rank.resize(num);
		for (int i = 0; i < num; i++) {
			parent[i] = i;
			rank[i] = 0;
		}
	}
	int Find(int node) {
		if (parent[node] == node)return node;
		else return parent[node] = Find(parent[node]);
	}
	void Unite(int u, int v) {
		u = Find(u);
		v = Find(v);
		if (u == v)return;
		if (rank[u] < rank[v])parent[u] = v;
		else {
			parent[v] = u;
			if (rank[u] == rank[v])rank[u]++;
		}
	}
	bool Check_Same(int u, int v) {
		return Find(u) == Find(v);
	}
};

void Calculate_Depth(vector<vector<int>>&edge, vector<int>&depth, int stnode) {
	depth[stnode] = 0;
	queue<int>Q;
	Q.push(stnode);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (depth[i] > depth[cn] + 1) {
				depth[i] = depth[cn] + 1;
				Q.push(i);
			}
		}
	}
	return;
}

void Search(vector<vector<int>>&edge, vector<int>&depth, int node, vector<int>&dir, vector<pair<int, int>>&ans) {
	for (auto i : edge[node]) {
		if (depth[i] > depth[node])Search(edge, depth, i, dir, ans);
	}
	for (auto i : edge[node]) {
		if (depth[i] < depth[node]) {
			if (dir[node] & 1) {
				ans.push_back({ node,i });
			}
			else {
				ans.push_back({ i,node });
				dir[i]++;
			}
		}
	}
	return;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M;
	vector<int>dir(N);
	vector<vector<int>>edge(N);
	UnionFind uf(N);
	vector<pair<int, int>>ans;
	for (int i = 0; i < M; i++) {
		cin >> L >> R;
		L--;
		R--;
		if (uf.Check_Same(L, R)) {
			ans.push_back({ L,R });
			dir[L]++;
		}
		else {
			uf.Unite(L, R);
			edge[L].push_back(R);
			edge[R].push_back(L);
		}
	}
	vector<int>depth(N, MOD);
	Calculate_Depth(edge, depth, 0);
	Search(edge, depth, 0, dir, ans);
	for (auto i : ans)cout << i.first + 1 << " " << i.second + 1 << endl;
}

