    		swap(p[i].fi,p[i].se);
    	}
    }
    forn(i,m){
    	if(deg[p[i].fi]%2){
    		cout<<-1;
    		return 0;
    	}
    }
    forn(i,m){
    	cout<<p[i].fi<<" "<<p[i].se<<endl;
    }
    return 0;
}

