vector<int> pts;
set<edge> rev;
vector<int> W[100010];
set<int> V[100010];
vector<edge> ans;
bool visited[100010];
int cnt[100010];
priority_queue<info, vector<info>, greater<info>> Q;

void No()
{
  cout << "-1" << endl;
  exit(0);
}

void make_path(int v, int w)
{
  vector<int> from(N, -1);
  queue<info> P;
  P.push(info(-1, v));
  while (!P.empty())
  {
    int f = get<0>(P.front());
    int now = get<1>(P.front());
    P.pop();
    if (from[now] == -1)
    {
      from[now] = f;
      if (now == w)
      {
        break;
      }
      for (auto x : W[now])
      {
        if (from[x] == -1)
        {
          P.push(info(now, x));
        }
      }
    }
  }
  v = from[w];
  while (v != -1)
  {
    edge e = edge(v, w);
    edge f = edge(w, v);
    if (rev.find(e) == rev.end())
    {
      rev.insert(e);
      rev.insert(f);
    }
    else
    {
      rev.erase(e);
      rev.erase(f);
    }
    w = v;
    v = from[w];
  }
}

void make_rev()
{
  for (auto i = 0u; i < pts.size(); i += 2)
  {
    int v = pts[i];
    int w = pts[i + 1];
    make_path(v, w);
  }
}

void solve()
{
  for (auto i = 0; i < N; i++)
  {
    Q.push(info(V[i].size(), i));
  }
  while (!Q.empty())
  {
    // int sz = get<0>(Q.top());
    int v = get<1>(Q.top());
    Q.pop();
    if (!visited[v])
    {
      visited[v] = true;
      for (auto x : V[v])
      {
        ans.push_back(edge(x, v));
        cnt[x]++;
        V[x].erase(v);
        Q.push(info(V[x].size(), x));
      }
      if (cnt[v] % 2 == 1)
      {
        if (V[v].empty())
        {
          // nothing
        }
        else
        {
          auto ed = ans.end();
          auto it = ed - V[v].size();
          bool ok = false;
          while (it != ed)
          {
            if (cnt[get<0>(*it)] % 2 == 1)
            {
              cnt[get<0>(*it)]--;
              cnt[get<1>(*it)]++;
              swap(get<0>(*it), get<1>(*it));
              ok = true;
              break;
            }
            ++it;
          }
          if (!ok)
          {
            it--;
            cnt[get<0>(*it)]--;
            cnt[get<1>(*it)]++;
            swap(get<0>(*it), get<1>(*it));
          }
        }
      }
      V[v].clear();
    }
  }
}

void Yes()
{
  assert((int)ans.size() == M);
  vector<int> c(N, 0);
  for (auto x : ans)
  {
    c[get<0>(x)]++;
  }
  for (auto i = 0; i < N; i++)
  {
    if (c[i] % 2 == 1)
    {
      pts.push_back(i);
    }
  }
  if (!pts.empty())
  {
    make_rev();
  }
  for (auto x : ans)
  {
    if (rev.find(x) != rev.end())
    {
      swap(get<0>(x), get<1>(x));
    }
    cout << get<0>(x) + 1 << " " << get<1>(x) + 1 << endl;
  }
  exit(0);
}

int main()
{
  cin >> N >> M;
  for (auto i = 0; i < M; i++)
  {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    V[a].insert(b);
    V[b].insert(a);
    W[a].push_back(b);
    W[b].push_back(a);
  }
  if (M % 2 == 1)
  {
    No();
  }
  solve();
  Yes();
}

