		++numedge_of_node[e.second];
		neighs[e.first].insert(e.second);
		neighs[e.second].insert(e.first);
	}

	if (M % 2 == 1) {
		std::cout << "-1\n";
		return 0;
	}

	while (M > 0) {
		auto idx = std::min_element(numedge_of_node.begin(), numedge_of_node.end()) - numedge_of_node.begin();
		for (auto neigh : neighs[idx]) {
			if (parity[idx]) {
				std::cout << (idx + 1) << " " << (neigh + 1)<< "\n";
				parity[neigh] = 0;
			} else {
				std::cout << (neigh + 1) << " " << (idx + 1) << "\n";
				parity[neigh] = 1 - parity[neigh];
			}
			neighs[neigh].erase(idx);
		}
		numedge_of_node[idx] = std::numeric_limits<int>::max();
		--M;
	}
}

