int getroot(int u)
{
	return u == fa[u] ? u : fa[u] = getroot(fa[u]);
}

void addE(int u,int v,int c)
{
	edge[++id] = (Edge){v,c,first[u]};
	first[u] = id;
}

void dfs(int U,int fa)
{
	for (int i = first[U];i;i = edge[i].nxt)
		if (edge[i].to != fa)
		{
			dfs(edge[i].to,U);
			if (cnt[edge[i].to])
			{
				swap(u[edge[i].w],v[edge[i].w]);
				cnt[edge[i].to] ^= 1;
				cnt[U] ^= 1;
			}
		}
}

