	cin >> N >> M;

	if (M % 2 == 1) {
		cout << -1 << "\n";
		return 0;
	}

	int u, v;
	map<pair<int, int>, int> dir;
	vector<vector<int>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		u--, v--;
		edge[u].emplace_back(v);
		edge[v].emplace_back(u);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	struct graph {
		int now, prev, flip;
		graph(int now, int prev, int flip) :now(now), prev(prev), flip(flip) {}
	};
	queue<graph> que;
	for (const auto &e : edge[0]) {
		que.emplace(e, 0, out[0]);
		if (out[0]) {
			out[0] ^= 1;
			out[e] ^= 1;
		}
	}
	vector<int> visited(N);
	visited[0] = 1;
	while (!que.empty()) {

		auto g = que.front();
		que.pop();
		visited[g.now] = 1;

		DMP(g.prev);
		DMP(g.now);
		DMP(g.flip);

		dir[minmax(g.prev, g.now)] ^= g.flip;

		for (const auto &e : edge[g.now]) {
			if (!visited[e]) {
				que.emplace(e, g.now, g.flip);
				if (out[g.now]) {
					out[g.now] ^= 1;
					out[e] ^= 1;
					g.flip ^= 1;
				}
			}
		}

	}
	if (*min_element(visited.begin(), visited.end()) == 0) exit(-1);

	for (const auto &elem : out)DMP(elem);
	for (auto &e : dir) {
		if (e.second == 1) cout << e.first.first + 1 << " " << e.first.second + 1 << "\n";
		else cout << e.first.second + 1 << " " << e.first.first + 1 << "\n";
	}

	return 0;
}

