int main(){
    scanf("%d %d", &N, &M);
    if (M & 1){
        puts("-1");
        return 0;
    }
    for (int i=1; i<=M; i++){
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
        deg[u]++, deg[v]++;
    }
    for (int i=1; i<=N; i++) PQ.push(pii(-deg[i], i));
    while (!PQ.empty()){
        int u = PQ.top().second;
        PQ.pop();
        if (chk[deg[u]]) continue;
        vector<int> E;
        for (int v : adj[u]){
            if (chk[v]) continue;
            deg[v]--;
            PQ.push(pii(-deg[v], v));
