                ans.push_back(make_pair(nx, p));
                ct[nx]++;
            }
            edge[p][i] = -1;
            for (int j=0; j < edge[nx].size(); ++j) {
                if (edge[nx][j] == p) {
                    edge[nx][j] = -1;
                }
            }
            dfs(nx, !f);
        }
    }
}

