void build(){
	f(i,1,n)
		ff(j,0,a[i].size()){
			int v = a[i][j];
			int u = i;
			if (u>v) continue;
			b[u].pb(v);
			s[u]++;
		}
	return ;
}

void solve(){
	int cnt=0;
	bool check[N];
	memset(check,0,sizeof check);
	f(i,1,n) if (s[i]&1) odd.push(i),check[i]=1,cnt++;
		else eve.push(i);
	while (!odd.empty()){
		bool flag = 1;
		int u = odd.front();
		odd.pop();
		if (!(s[u]&1)){
			continue;
		}

		ff(i,0,b[u].size()){
			int v = b[u][i];
			if (!v) continue;
			if (!(s[v]&1)) continue;
			s[v]++;
			s[u]--;
			cnt-=2;
			eve.push(v);
			eve.push(u);
			flag = 0;
			b[u][i] = 0;
			b[v].pb(u); 
		}
	}
	while (!eve.empty()){
		bool flag = 1;
		int u = eve.front();eve.pop();
		int t1=0,t2=0;
		ff(i,0,b[u].size()){
			int v = b[u][i];
			if (!v) continue;
			if (!(s[v]&1)) continue;
			if (t1==0) t1=v;
				else {
					t2=v;
					flag=1;
					break;
				}
		}
		if (t1 && t2){
			s[t1]++;
			s[t2]++;
			s[u]-=2;
			flag = 0;
			ff(i,0,b[u].size())
				if (b[u][i]==t1 || b[u][i]==t2) b[u][i] = 0;
			b[t1].pb(u);
			b[t2].pb(u);
			eve.push(t1);
			eve.push(t2);
		}
	}
}

void print(){
	f(i,1,n)
		ff(j,0,b[i].size()){
			int u = b[i][j];
			if (!u) continue;
			printf("%d %d\n",i,u);
		}
	return ;
}

