vector <int> treeEdges[100100], degOut;
set <pair<int,int>> flipped;

int visit(int x, int par)
{
  int shouldFlip = 0;
  for (int y : treeEdges[x])
    if (y != par)
      if (visit(y, x))
      {
        flipped.insert({x, y});
        shouldFlip ^= 1;
      }
  return shouldFlip ^ degOut[x];
}

int main()
{
  int n, m, x, y;
  vector <pair<int,int>> edges;
  cin >> n >> m;
  if (m % 2)
  {
    cout << -1 << endl;
    return 0;
  }

  vector <int> ds(n);
  degOut = vector <int>(n, 0);
  for (int i = 0; i < n; i++)
    ds[i] = i;

  function<int(int)> get = [&](int x)
  {
    return x == ds[x] ? x : ds[x] = get(ds[x]);
  };

while (m--)
  {
    cin >> x >> y;
    edges.push_back({--x, --y});
    degOut[x] ^= 1;
    int dx = get(x), dy = get(y);
    if (dx != dy)
    {
      ds[dx] = dy;
      treeEdges[x].push_back(y);
      treeEdges[y].push_back(x);
    }
  }

  visit(0, -1);

  for (auto e : edges)
  {
    if (flipped.count({e.first, e.second}) || flipped.count({e.second, e.first}))
      swap(e.first, e.second);
    cout << e.first + 1 << ' ' << e.second + 1 << '\n';
  }
}

