		if (cnt[now] % 2 == 0) {
			can -= can % 2 == 1;
		} else {
			can -= can %2 == 0;
		}


		for (auto edge : need) {
			usedE[edge.second]++;
			ans.push_back(lpair(now, edge.first));
			cnt[now]++;
			nokori[now]--;
			nokori[edge.first]--;
		}
		for (auto edge : edges[now]) {
			if (usedE[edge.second]) continue;
			usedE[edge.second]++;

			if (can > 0) {
				ans.push_back(lpair(now, edge.first));
				cnt[now]++;
				can--;
				nokori[now]--;
				nokori[edge.first]--;
			} else {
				ans.push_back(lpair(edge.first, now));
				cnt[edge.first]++;
				nokori[now]--;
				nokori[edge.first]--;
			}

			q.push(edge.first);
		}
	}

	bool check = true;
	for (auto c : cnt)
		if (c % 2 == 1)
			check = false;

	// if (ans.size() != M || check == false) {
