bool eulerCircuit(int n,int start)
{
  stack<int>st;st.push(start);
  while(!st.empty())
  {
    int u=st.top();
    if(adj[u].size()==0)
    {
      path.push_back(u);
      st.pop();
    }
    else
    {
      int bg=*adj[u].begin();
      st.push(bg);
      adj[u].erase(bg);
      adj[bg].erase(u);
    }
  }
  reverse(path.begin(),path.end());
  return true;
}
