void output(int a, int b) {
    cout << a << " " << b << '\n';
}

void dfs(vector<vector<int>>& graph, int cur, int par, vector<int>& f, vector<bool>& seen, vector<bool>& done) {
    seen[cur] = true;

    for(int child : graph[cur]) {
        if(child != par) {
            if(!seen[child])
                dfs(graph, child, cur, f, seen, done);
            else if(!done[child]){
                output(cur, child);
                f[cur]++;
            }
        }
    }

    done[cur] = true;

    if(cur == 1) return;

    if(f[cur]%2) {
        output(cur, par);
    } else {
        output(par, cur);
        f[par]++;
    }
}

