        if(c>d) swap(c,d);
        l[i] = {c,d};
    }
    if(m%2==1) cout << -1 << endl;
    else{
        sort(all(l));

        // p[i] : 頂点iが含む辺の数
        // q[i] : この辺はいじってはいけない
        vll p(n), q(m);
        REP(i,n) p[i] = 0;
        REP(i,m) q[i] = 0;

        c = 0; d = 0; tmp = 0;
        REP(i,m){
            c = l[i].first;
            d = l[i].second;
            p[c-1] += 1;
            p[d-1] += 1;
        }
        REP(i,n){
            if(p[i] == 1){
                REP(j,m){
                    if(l[j].first == i){
                        q[j] == 1;
                        c = l[j].first;
                        d = l[j].second;
