                }
                else{
                    l[i] = {d,c};
                    p[d-1] += 1;
                }
            }
            else{
                l[i] = {d,c};
                p[d-1] += 1;
            }
            tmp = c;
        }
        cout << l << endl;
    }
    return 0;
}

