#define FOR(i,a,b) for(int i=(a);i<(b);++i)  
#define REP(i,n) FOR(i,0,n)  
#define FORE(i,a,b) for(int i=(a);i<=(b);++i)  
#define REPE(i,n) FORE(i,0,n)  
#define FORSZ(i,a,v) FOR(i,a,SZ(v))  
#define REPSZ(i,v) REP(i,SZ(v))  
typedef long long ll;
typedef unsigned long long ull;
ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=100000;
const int MAXM=100000;

int n,m;
int e[MAXM][2];
vector<pair<int,int>> adj[MAXN];
vector<pair<int,int>> ans;

int par[MAXN],parid[MAXN];
bool visited[MAXN];
int post[MAXN],npost;
void dfs(int at) {
	assert(!visited[at]); visited[at]=true;
	REPSZ(i,adj[at]) {
		int to=adj[at][i].first,id=adj[at][i].second; if(visited[to]) continue;
		par[to]=at,parid[to]=id; dfs(to);
	}
	post[npost++]=at;
}


int outdeg[MAXN];
bool done[MAXM];


bool solve() {
	if(m%2==1) return false;
	REP(i,n) visited[i]=false;
	par[0]=-1,parid[0]=-1; npost=0; dfs(0);
	REP(i,n) assert(visited[i]);
	assert(npost==n);

	ans.clear();
	REP(i,n) outdeg[i]=0;
	REP(i,m) done[i]=false;
	REP(i,n) if(parid[i]!=-1) done[parid[i]]=true;
	REP(i,m) if(!done[i]) { int a=e[i][0],b=e[i][1]; ++outdeg[a]; ans.PB(MP(a,b)); }
	REP(_,n) {
		int at=post[_];
		if(parid[at]==-1) { assert(outdeg[at]%2==0); continue; }
		int a=at,b=par[at]; assert(b!=-1);
		if(outdeg[at]%2==0) swap(a,b);
		++outdeg[a]; ans.PB(MP(a,b));
	}
	REP(i,n) assert(outdeg[i]%2==0);
	return true;
}

void run() {
	scanf("%d%d",&n,&m);
	REP(i,m) { int a,b; scanf("%d%d",&a,&b); --a,--b; adj[a].PB(MP(b,i)); adj[b].PB(MP(a,i)); e[i][0]=a,e[i][1]=b; }
	if(!solve()) { printf("-1\n"); return; }
	REPSZ(i,ans) printf("%d %d\n",ans[i].first+1,ans[i].second+1);
}

int main() {
	run();
	return 0;
}

