        for(auto e : G[k]) {
            odd += (deg[e] % 2 == 1);
        }
        if(odd == 0) continue;

        visited[k] = true;
        for(auto e : G[k]) {
            int u = k, v = e;
            if(used.count(minmax(u, v))) continue;
            ans.emplace_back(u, v);

            deg[u]--; deg[v]--;
            if(!visited[v]) que.emplace(deg[v], v);

            if(u > v) swap(u, v);
            used.emplace(u, v);
        }
    }

    for(auto e : ans) {
        int u, v; tie(u, v) = e;
        printf("%d %d\n", u+1, v+1);
    }
    return 0;
}

