bool isUsed(int c, int d) {
	return used.count(pii(c,d)) || used.count(pii(d,c));
}

void useEdge(int c, int d) {
	cout << c+1 << " " << d+1 << endl;
	used.insert(pii(c,d));
	used.insert(pii(d,c));
}

int main() {
	cin >> N >> M;

	if (M & 1) {
		puts("-1");
		return 0;
	}

	edge.assign(N, Vec< int >());
	for_(i,0,M) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		edge[a].push_back(b);
		edge[b].push_back(a);
	}

	// deg 1
	for_(v,0,N) {
		if (edge[v].size() == 1) {
			int c = edge[v][0], d = v;
			useEdge(c, d);
		}
	}

	Vec< int > outdeg(N, 0);
	for_(v,0,N) {
		int T = (outdeg[v] & 1 ? 1 : 0);
		for (int u : edge[v]) {
			if (isUsed(u, v)) continue;
			if (T) {
				useEdge(v, u);
				--T;
			}
			else {
				useEdge(u, v);
				++outdeg[u];
			}
		}
	}
}
