int dfs(int n){
  visit[n] = 1;
  int res = odd[n];
  for(auto p : G[n]){
    if(!visit[p.first]){
      if(dfs(p.first)){
        rev[p.second] = 1;
        res = !res;
      }
    }
  }
  return res;
}

