set<int> V[100010];
vector<edge> ans;
bool visited[100010];
int cnt[100010];
priority_queue<info, vector<info>, greater<info>> Q;

void Yes()
{
  assert((int)ans.size() == M);
  for (auto x : ans)
  {
    cout << get<0>(x) + 1 << " " << get<1>(x) + 1 << endl;
  }
  exit(0);
}
void No()
{
  cout << "-1" << endl;
  exit(0);
}

void solve()
{
  for (auto i = 0; i < N; i++)
  {
    Q.push(info(V[i].size(), i));
  }
  while (!Q.empty())
  {
    // int sz = get<0>(Q.top());
    int v = get<1>(Q.top());
    Q.pop();
    if (!visited[v])
    {
      visited[v] = true;
      for (auto x : V[v])
      {
        ans.push_back(edge(x, v));
        cnt[x]++;
        V[x].erase(v);
        Q.push(info(V[x].size(), x));
      }
      V[v].clear();
      if (cnt[v] % 2 == 1)
      {
        auto it = ans.end();
        --it;
        cnt[get<0>(*it)]--;
        swap(get<0>(*it), get<1>(*it));
      }
    }
  }
}

