				vertex[now].second += 1;
				cout << now+1 << " " << next+1 << endl;
			} else {
				vertex[next].second += 1;
				cout << next+1 << " " << now+1 << endl;
			}
		} else {
			// if the next layer is smaller than now's, decide the direction in any way
			if(vertex[next].first > layer) {
				vertex[next].second += 1;
				cout << next+1 << " " << now+1 << endl;
			}
		}
	}
}

signed main(void) {
  	int N, M;
  	cin >> N >> M;
  	vector<vector<int> > graph(N);

  	// first is the layer number, second is the number that go out from the vertex
  	vector<P> vertex(N);

  	rep(i, M) {
  		int a, b;
  		cin >> a >> b;
  		a--; b--;
  		graph[a].pb(b);
  		graph[b].pb(a);
  		vertex[i] = make_pair(-1, 0);
  	}

  	if (M%2 == 0) {
  		dfs(graph, 0, 0, vertex);
  	} else {
  		cout << -1 << endl;
  	}

	return 0;
}

