int main(void){
	int n=readi(),m=readi();
	vvc<int>g(n);
	vc<bool>o(m),vis(n);
	vc<int>a(m),b(m),s(n),t(n);
	fill(all(s),0);
	fill(all(t),0);
	fill(all(o),false);
	fill(all(vis),false);
	priority_queue<pi,vc<pi>,greater<pi> >d;
	rep(i,m){
		a[i]=readi()-1;
		b[i]=readi()-1;
		s[a[i]]++;
		s[b[i]]++;
