		g[b[i]].eb(i);
	}
	rep(i,n){
		d.push(mp(cl(s[i],t[i]),i));
	}
	while(!d.empty()){
		int v=d.top().S,c=d.top().F;
		d.pop();
		if(vis[v]||cl(s[v],t[v])!=c)continue;
		vis[v]=true;
		if(c==0){
			for(auto &i:g[v]){
				if(!o[i]){
