void dfs(int x){
    if(odd[x]) f=1-f; vis[x]=1;
    for(int i=0;i<v[x].size();i++){
        int y=v[x][i].to;
        if(vis[y]) continue;
        if(f==1){
            v[x][i].f=1-v[x][i].f;
        }
        dfs(y);
        if(f==1){
            v[x][i].f=1-v[x][i].f;
        }
    }
}

