void construct_tree(vector<vector<int>> &graph, map<pair<int, int>, int> &memo,vector<vector<int>> &tree)
{
    vector<bool> flag(graph.size(), false);
    stack<int> s;
    flag[0] = true;
    s.push(0);
    while (!s.empty())
    {
        int current = s.top();
        bool no = true;
        for (int i = 0; i < graph[current].size(); i++)
        {
            int next = graph[current][i];
            if (!flag[next])
            {
                flag[next] = true;
                s.push(next);
                tree[current].push_back(next);
                memo[{min(current, next), max(current, next)}] = 0;
                no = false;
                break;
            }
        }
        if (no)
        {
            s.pop();
        }
    }
}

int main()
{
    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> edge(m);
    vector<int> outd(n, 0);
    vector<vector<int>> graph(n, vector<int>());
    map<pair<int, int>, int> memo;
    for(int i = 0; i < m; i++)
    {
        int a, b;
        cin >> a >> b;
        int minn = min(a, b) - 1;
        int maxn = max(a, b) - 1;
        edge[i] = {minn, maxn};
        graph[minn].push_back(maxn);
        graph[maxn].push_back(minn);
    }
    if(m % 2 == 1){
        cout << -1 << endl;
    }else{
        vector<vector<int>> tree(n, vector<int>());
        construct_tree(graph, memo, tree);
        for(int i = 0; i < m; i++)
        {
            if(memo.count({edge[i]}) == 0)
            {
                memo[edge[i]] = 1;
                outd[edge[i].first]++;
                //cout << edge[i].first + 1 << " " << edge[i].second + 1 << endl;
            }
        }
        //cout << endl;
        stack<int> s;
        vector<bool> flag(n, false);
        flag[0] = true;
        s.push(0);
        while(!s.empty())
        {
            int current = s.top();
            bool no = true;
            for(int i = 0; i < tree[current].size(); i++)
            {
                int next = tree[current][i];
                if(!flag[next]){
                    flag[next] = true;
                    s.push(next);
                    no = false;
                    break;
                }
            }
            if(no)
            {
                s.pop();
                if(s.empty()) break;
                int parent = s.top();
                if(outd[current] % 2 != 0){
                    memo[{current, parent}] =  1;
                    //cout << "add " << current + 1 << " " << parent + 1 << endl;
                }else{
                    memo[{parent, current}] = 1;
                    //cout << "add " << parent + 1 << " " << current + 1 << endl;
                    outd[parent]++;
                }
            }
        }
        for(auto e : memo){
            if(e.second == 0) continue;
            //cout << e.first.first + 1 << " " << e.first.second + 1 << endl;
        }
    }
}

