vvi nodes;
vi depth, out, sub;
vpii res;
vb span;
void dfs(int u) {
    for (int v : nodes[u]) {
        if (depth[v] == 0) {
            depth[v] = 1 + depth[u];
            dfs(v);
            sub[u] += sub[v];
            ++out[u];
            span[SIZE(res)] = true;
            res.emplace_back(u, v);
        } else if (depth[v] < depth[u] - 1) {
            ++out[u];
            res.emplace_back(u, v);
        }
    }
    if (out[u]&1) ++sub[u];
}

