{
	int N, M; cin >> N >> M;
	vector<vector<int>>E(N);
	for (int i = 0; i < M; i++)
	{
		int a, b; cin >> a >> b;
		a--; b--;

		E[a].push_back(b);
		E[b].push_back(a);
	}

	if (M % 2)
	{
		cout << -1 << endl;
		return 0;
	}

	solve(N, E);

	return 0;
}

