#include <set>
using namespace std;

const int N = 1e5;
set<int> conns[N + 1];
int outs[N];

void eulerTour(int i, vector<int>& res) {
	while(! conns[i].empty()) {
		auto it = conns[i].begin();
		int t = *it;
		conns[i].erase(it);
		conns[t].erase(i);
		eulerTour(t, res);
	}
	res.push_back(i);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n, m;
	cin >> n >> m;
	for (int j = 0; j < m; ++j) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		conns[a].insert(b);
		conns[b].insert(a);
	}

	// Add auxiliary node connecting to vertices of odd degree. Now all nodes have even degree.
	// Find euler tour, and set direction of every edge to reverse of last
	// Now every time we visit a node we either add two edges to it or two edges from it,
	// so every node has both even in-degree and out-degree.

	// Take any valid solution, add auxiliary node, and add edges from auxiliary node to all odd degree nodes.
	// Now every node has both an even number of in-edges and an even number of odd-edges. Form euler tour,
	// and divide nodes along it into even and odd sides. Note that all edges appear in the tour, and distance
	// between reappearances of nodes is always even. Therefore, the graph is bipartite and all
	// odd-degree nodes are on the same side.

	for (int i = 0; i < n; ++i) {
		if (conns[i].size() & 1) {
			conns[i].insert(n);
			conns[n].insert(i);
		}
	}

	vector<int> tour;
	if (conns[n].empty()) {
		eulerTour(0, tour);
	} else {
		eulerTour(n, tour);
	}
	for (int j = 0; j+1 < tour.size(); ++j) {
		if (j & 1) ++outs[tour[j+1]];
		else ++outs[tour[j]];
	}

	bool works = true;
	for (int i = 0; i <= n; ++i) {
		if (outs[i] & 1) works = false;
	}

	if (works) {
		for (int j = 0; j+1 < tour.size(); ++j) {
			if (j & 1) cout << tour[j+1]+1 << ' ' << tour[j]+1 << '\n';
			else cout << tour[j]+1 << ' ' << tour[j+1]+1 << '\n';
		}
	} else {
		cout << "-1\n";
	}
}

