							stk.emplace(e, tmp);
						}
					}
				}
				else {
					for (int i = 0; i < memonow.size() - 1; i++) {
						dir[{min(memonow[i], memonow[i + 1]), max(memonow[i], memonow[i + 1])}] *= -1;
					}
					break;
				}
			}
		}
