set<pair<int, int>> used;

vector<pair<int, int>> ans;

void bfs(int u) {
  queue<int> q;
  q.push(u);
  vis[u] = true;

  while (q.size()) {
    int u = q.front();
    q.pop();

    bool first = true;
    for (int v: edges[u]) {

      if (used.count({u, v}) == 0) {
        if (deg[u] % 2 == 1 && first) {
          printf("%d %d\n", v+1, u+1);
          ans.emplace_back(v+1, u+1);
          first = false;
          --deg[u];
        } else {
          printf("%d %d\n", u+1, v+1);
          ans.emplace_back(u+1, v+1);
          --deg[v];
        }

        used.insert({u, v});
        used.insert({v, u});
      }

      if (vis[v]) continue;
      vis[v] = true;

      q.push(v);
    }
  }
}

