using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, M, as[MAX_M], bs[MAX_M];
  scanf("%d %d", &N, &M);
  for (int k = 0; k < M; k++) {
    scanf("%d %d", &as[k], &bs[k]);
    as[k]--;  // NOTE : modified input
    bs[k]--;  // NOTE : modified input
  }

  // create graph
  vector<vector<int>> adj_lists(N, vector<int>());
  set<pair<int, int>> remaining_edges;
  vector<int> node_ranks(N, 0);
  for (int k = 0; k < M; k++) {
    const int a = as[k], b = bs[k];
    adj_lists[a].push_back(b);
    adj_lists[b].push_back(a);
    node_ranks[a]++;
    node_ranks[b]++;
    remaining_edges.insert(make_pair(a, b));
    remaining_edges.insert(make_pair(b, a));
  }

  // greedy from smallest rank
  // insert all nodes into queue
  vector<int> cs, ds, num_outs(N, 0);
  priority_queue<pair<int, int>, vector<pair<int, int>>,
                 greater<pair<int, int>>>
      que;
  for (int i = 0; i < N; i++) {
    que.push(make_pair(node_ranks[i], i));
  }
  while (!que.empty()) {
    // take node with smallest positive rank
    int cur = que.top().second, rank = que.top().first;
    que.pop();
    // printf("cur = %d, rank = %d, node_ranks[cur] = %d\n", cur, rank,
    //        node_ranks[cur]);
    if (node_ranks[cur] == 0) {
      // printf("let's go to the next!\n");
      continue;
    }
    // choose direction of remaining edges
    int cnt = 0;
    for (int nxt : adj_lists[cur]) {
      const pair<int, int> edge = make_pair(cur, nxt),
                           rev_edge = make_pair(nxt, cur);
      if (remaining_edges.find(edge) != remaining_edges.end()) {
        remaining_edges.erase(edge);
        remaining_edges.erase(rev_edge);
        num_outs[cur]++;
        cs.push_back(cur + 1);
        ds.push_back(nxt + 1);
        cnt++;
        node_ranks[cur]--;
        node_ranks[nxt]--;
        que.push(make_pair(node_ranks[nxt], nxt));
      }
    }
    if (num_outs[cur] % 2 == 1) {
      // swap last
      int k_last = ds.size() - 1;
      const int c = ds[k_last], d = cs[k_last];
      cs[k_last] = c;
      ds[k_last] = d;
      num_outs[d - 1]--;
      num_outs[c - 1]++;
    }
    // for (int i = cs.size() - cnt; i < cs.size(); i++) {
    //   printf("c = %d, d = %d\n", cs[i], ds[i]);
    // }
  }

  // check
  int is_possible = 1;
  for (int i = 0; i < N; i++) {
    if (num_outs[i] % 2) {
      is_possible = 0;
      break;
    }
  }

  if (is_possible) {
    if (cs.size() != M || ds.size() != M) {
      printf("something is wrong...\n");
      exit(1);
    }
    for (int k = 0; k < M; k++) {
      printf("%d %d\n", cs[k], ds[k]);
    }
  } else {
    printf("-1\n");
  }

  return 0;
}

