      cin >> n >> m;
      flippy.clear(); edges.clear();
      for (int i = 1; i <= n; i++) {
            adj[i].clear();
            xr[i] = vis[i] = 0;
      }

      for (int i = 0; i < m; i++) {
            int x, y; cin >> x >> y;
            xr[y] ^= 1;
            adj[x].push_back(y);
            adj[y].push_back(x);
            edges.push_back({x, y});
      }
}

void dfs(int now, int prev) {
      vis[now] = 1;

      for (int u: adj[now]) {
            if (vis[u]) continue;
            dfs(u, now);
      }

      if (xr[now]) {
            xr[now] ^= 1; xr[prev] ^= 1;
            flippy.insert({now, prev});
            flippy.insert({prev, now});
      }
}

void solve() {
      if (m % 2) {cout << "-1\n"; return;}

      dfs(1, 0);

      for (auto u: edges) {
            if (flippy.find(u) == flippy.end()) {
                cout << u.first << ' ' << u.second << '\n';
            } else {
                cout << u.second << ' ' << u.first << '\n';
            }
      }
      cout << '\n';
}

