    par[1] = -1;
    queue<int> q;
    q.push(1);
    vector<int> tp;
    tp.push_back(1);
    while(!q.empty()) {
        int now = q.front();
        q.pop();
        for (int nxt : edge[now]) {
            if (par[nxt] == 0) {
                par[nxt] = now;
                q.push(nxt);
                tp.push_back(nxt);
            }
        }
    }
    vector<pair<int, int>> ans;
    vector<int> go(N+1, 0);
    for (int i = 1; i <= N; i++) {
        for (int j : edge[i]) {
            if (par[i] == j || par[j] == i) continue;
            if (i < j) {
                ans.push_back({i, j});
                go[i]++;
            }
        }
    }
    for (int i = (int)tp.size()-1; i >= 1; i--) {
        if (go[tp[i]]%2 == 0) {
            ans.push_back({par[tp[i]], tp[i]});
            go[par[tp[i]]]++;
        }
        else {
            ans.push_back({tp[i], par[tp[i]]});
            go[tp[i]]++;
        }
    }

    for (auto p : ans) {
        cout << p.first << " " << p.second << endl;
    }
