int solve() {
  int ret = 0;
  for (int i = 0; i < MAX; i++) {
    color[i] = WHITE;
  }

  int counter = 0;

  while (!S.empty()) {
    if (counter > 10) {
      break;
    }
    int u = *(S.begin());
    S.erase(u);
    int adjNum = 0;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j];
      if (color[v] == WHITE) adjNum++;
    }
    int base;
    if (adjNum % 2 == 0) {
      base = adjNum;
    } else base = adjNum - 1;
    if (base != 0) color[u] = BLACK;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j];
      if (color[v] == BLACK) continue;
      if (base > 0) {
        ans.pb(make_pair(u, v));
        base--;
        ret++;
      }
    }
    counter++;
  }
  return ret;
};

