int main() {

	int N, M;
	scanf("%d%d", &N, &M);

	if (M % 2 == 1) {
		printf("-1\n");
		return 0;
	}

	int u, v;
	map<pair<int, int>, int> dir;
	vector<vector<int>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		scanf("%d%d", &u, &v);
		u--, v--;
		edge[u].emplace_back(v);
		edge[v].emplace_back(u);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	stack<int> que;
	vector<int> used(N);
	used[0] = 1;
	int idx = 1;
	int fliping;
	que.emplace(0);
	while (!que.empty()) {

		int now = que.top();
		que.pop();
		fliping = out[now];

		bool all_used = true;
		for (const auto &e : edge[now]) {
			if (!used[e]) {
				dir[minmax(now, e)] ^= fliping;
				out[now] ^= fliping;
				out[e] ^= fliping;
				idx++;
				used[e] = idx;
				all_used = false;
				que.emplace(e);
				break;
			}
		}

		if (all_used && fliping) {
			for (const auto &e : edge[now]) {
				if (used[e] < used[now]) {
					dir[minmax(now, e)] ^= fliping;
					out[now] ^= fliping;
					out[e] ^= fliping;
					que.emplace(e);
					all_used = false;
				}
			}
		}
	}

	for (auto &e : dir) {
		if (e.second == 1) printf("%d %d\n", e.first.first + 1, e.first.second + 1);
		else printf("%d %d\n", e.first.second + 1, e.first.first + 1);
	}

	return 0;
}

