	INT(n, m);
	vi deg(n);
	vi ed(n);
	if(m & 1) {
		err();
	}
	using pii = pair<int, int>;
	set<pii> s, u;

	rep(i, n) {
		INT(a, b);
		a--, b--;
		ed[a]++, ed[b]++;
		s.insert({a, b});
		s.insert({b, a});
	}

	rep(i, n) { u.insert({ed[i], i}); }

	V<pii> ans;

	rep(i, m) {
		auto it = u.begin();
		int ednum, id;
		tie(ednum, id) = (*it);
		auto itr = s.lower_bound({ednum, -1});
		int a, b;
		tie(a, b) = *itr;
		s.erase({a, b});
		s.erase({b, a});

		it = u.find({ed[a], a});
		u.erase(it);
		ed[a]--;
		u.insert({ed[a], a});

		it = u.find({ed[b], b});
		u.erase(it);
		ed[b]--;
		u.insert({ed[b], b});

		if(a != id) {
			swap(a, b);
		}
		if(deg[a]) {
			ans.push_back({a+1, b+1});
			deg[a] ^= 1;
		} else {
			ans.push_back({b+1, a+1});
			deg[b] ^= 1;
		}
	}
	vout(ans, 1);

	return 0;
}

