vector2<P> g;
vector<int> d;
vector<P> edge;
vector<bool> used;

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    if(m % 2){
        cout << -1 << endl;
        return 0;
    }

    g = initVec2<P>(n, 0);
    used = vector<bool>(n);
    edge = vector<P>(m);

    rep(i, m){
        int a, b;
        cin >> a >> b;
        if(a > b){
            swap(a, b);
        }
        a--;
        b--;
        g[a].emplace_back(b, i);
        g[b].emplace_back(a, i);
        edge[i] = {a, b};
    }

    d = vector<int>(m);
    queue<P> q;
    stack<int> st;
    q.emplace(0, -1);
    while(not q.empty()){
        int v = q.front().first;
        int p = q.front().second;
        q.pop();

        if(used[v]){
            continue;
        }
        used[v] = true;
        st.push(v);

        for(P pa : g[v]){
            int u = pa.first;
            if(u == p){
                continue;
            }
            q.emplace(u, v);
        }
    }

    while(not st.empty()){
        int v = st.top();
        st.pop();
        vector<int> x;
        for(P pa : g[v]){
            int e = pa.second;
            if(d[e] != 0){
                continue;
            }
            x.push_back(e);
        }

        for(int i = 0; i + 1 < SZ(x); i += 2){
            if(edge[x[i]].first == v){
                d[x[i]] = 1;
            }else{
                d[x[i]] = -1;
            }
            if(edge[x[i+1]].first == v){
                d[x[i+1]] = 1;
            }else{
                d[x[i+1]] = -1;
            }
        }
    }

    rep(i, m){
        if(d[i] == 1){
            cout << edge[i].first + 1 << " " << edge[i].second + 1 << endl;
        }else{
            cout << edge[i].second + 1 << " " << edge[i].first + 1 << endl;
        }
    }

    return 0;
}

