	ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;

	if (M % 2 == 1) {
		cout << -1 << "\n";
		return 0;
	}

	int u, v;
	map<pair<int,int>, int> dir;
	vector<vector<pair<int,int>>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		u--, v--;
		edge[u].emplace_back(v, i);
		edge[v].emplace_back(u, i);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	queue<int> que;
	vector<int> used(M);
	for (int i = 0; i < N; i++) {
		if (out[i] == 1) {
			que.emplace(i);
		}
	}

	while (!que.empty()) {

		int now = que.front();
		que.pop();
		if (out[now] == 0) continue;

		bool flag = true;
		for (const auto &e : edge[now]) {
			if (out[e.first] == 1) {
				dir[{min(now, e.first), max(now, e.first)}] *= -1;
				out[now] ^= 1;
				out[e.first] ^= 1;
				used[e.second] = 2;
				flag = false;
				break;
			}
		}

		if (flag) {
			for (const auto &e : edge[now]) {
				if (used[e.second] != 2) {
					int next = e.first;
					dir[{min(now, next), max(now, next)}] *= -1;
					out[now] ^= 1;
					out[next] ^= 1;
					used[e.second]++;
					que.emplace(next);
					flag = false;
				}
			}
		}

		if (flag) exit(-1); //error

	}

	for (auto &e : dir) {
		if(e.second == 1) cout << e.first.first + 1 << " " << e.first.second + 1 << "\n";
		else cout << e.first.second + 1 << " " << e.first.first + 1 << "\n";
	}

	return 0;
}

