vector<bool> seen;
void dfs(const Graph &G, int v,int c) {
    seen[v] = true; // v を訪問済にする

    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) { 
        if(c%2==0) cout << v << " " << next_v << endl;
        else cout << next_v << " "<< v << endl;
        c++;
        if (seen[next_v]) continue; // next_v が探索済だったらスルー
        dfs(G, next_v,c); // 再帰的に探索
    }
}

