bool DFS(int o,int fa){
	Vis[o]=true;
	int lft=0;
	for(int i=0,_=E[o].size();i<_;i++){
		int v=E[o][i];
		if(v==fa)continue;
		if(dep[v]==0){
			dep[v]=dep[o]+1;
			bool hs=DFS(v,o);
			if(hs){
				if(lft!=0){
					ad(o,v);
					ad(o,lft);
					lft=0;
				}else{
					lft=v;
				}
			}
		}else if(dep[v]<dep[o]){
			if(lft!=0){
				ad(o,v);
				ad(o,lft);
				lft=0;
			}else{
				lft=v;
			}
		}
	}
	if(lft!=0){
		ad(o,lft);
		ad(o,fa);
		return false;
	}
	return true;
}

