ll used_cnt = 0;

void dfs(ll node) {
    if(isNodeUsed[node]) { return; }

    isNodeUsed[node] = true;
    used_cnt++;

    // 次数が偶数ならすべて自分のものにする
    if(Jisu[node] % 2 == 0) {
        for(auto& e_to : graph[node]) {
            ll a = min(node, e_to);
            ll b = max(node, e_to);
            ll e_id = edge_id[make_pair(a, b)];
            if(!isEdgeUsed[e_id]) {
                ans.push_back(make_pair(e_to, node));
                Jisu[e_to]--;
                Jisu[node]--;
                Nyuji[node]++;
                isEdgeUsed[e_id] = true;
            }
        }
    }
    else {
        // 一つ残して全部取る
        ll remain = -1;
        for(auto& e_to : graph[node]) {
            ll a = min(node, e_to);
            ll b = max(node, e_to);
            ll e_id = edge_id[make_pair(a, b)];
            if(!isEdgeUsed[e_id]) {
                if(remain == -1) {
                    remain = e_to;
                }
                else {
                    ans.push_back(make_pair(e_to, node));
                    Jisu[e_to]--;
                    Jisu[node]--;
                    Nyuji[node]++;
                    isEdgeUsed[e_id] = true;
                }
            }
        }
    }

    for(auto& e_to : graph[node]) {
        dfs(e_to);
    }
}

