    rep1(i, N)v.push_back(P(dep[i], i));
    sort(v.begin(), v.end(), greater<P>());
    for(auto p : v){
        ll idx = p.second;
        for(auto to : path[idx])if(done[to] == 0){
            if(cnt[idx] % 2){
                cnt[idx]++;
                ans.push_back(P(idx, to));
            }
            else{
                ans.push_back(P(to, idx));
                cnt[to]++;
            }
        }
        done[idx] = 1;
    }

    for(auto p : ans)cout << p.first << " " << p.second << endl;

    return 0;
}

