bool operator<(const data &l, const data &r) {
  if(l.from != r.from) return l.from < r.from;
  return l.to < r.to;
}

int n, m;
set<int> edge[10005];
vector<bool> num;
vector<data> ans;
queue<int> qu;

void solve();
void bfs();

int main() {
  cin >> n >> m;
  num.assign(n, 0);
  for(int i = 0; i < m; ++i) {
    int a, b;
    cin >> a >> b;
    edge[--a].insert(--b);
    edge[b].insert(a);
  }
  if(m % 2)
    cout << -1 << endl;
  else {
    assert(0);
    solve();
    if(ans.size() != m)
      cout << -1 << endl;
    else {
      for(int i = 0; i < m; ++i)
        cout << ans[i].from + 1 << " " << ans[i].to + 1
             << endl;
    }
  }
  return 0;
}

void solve() {
  num.assign(n, 0);
  for(int i = 0; i < n; ++i)
    if(edge[i].size() == 1) qu.push(i);
  bfs();
  for(int i = 0; i < n; ++i)
    if(edge[i].size() != 0) {
      vector<int> tmp;
      for(auto now : edge[i]) tmp.push_back(now);
      int tsize = tmp.size();
      for(int j = 0; j < tsize; ++j) {
        if(j == tsize - 1) {
          if(num[i]) {
            ans.push_back({i, tmp[j]});
            num[i] = 0;
          }
          else {
            ans.push_back({tmp[j], i});
            num[tmp[j]] = !num[tmp[j]];
          }
        }
        else {
          ans.push_back({i, tmp[j]});
          num[i] = !num[i];
        }
        edge[tmp[j]].erase(i);
        edge[i].erase(tmp[j]);
        if(edge[tmp[j]].size() == 1) qu.push(tmp[j]);
      }
      bfs();
    }
}

void bfs() {
  while(!qu.empty()) {
    int now = qu.front();
    qu.pop();
    if(edge[now].size() == 0) {
      if(num[now]) {
        ans.erase(ans.begin(), ans.end());
        return;
      }
      continue;
    }
    vector<int> tmp;
    for(auto to : edge[now]) tmp.push_back(to);
    int tsize = tmp.size();
    for(int j = 0; j < tsize; ++j) {
      int to = tmp[j];
      if(num[now]) {
        ans.push_back({now, to});
        num[now] = 0;
      }
      else {
        ans.push_back({to, now});
        num[to] = !num[to];
      }
      edge[now].erase(to);
      edge[to].erase(now);
      if(edge[to].size() == 1) qu.push(to);
    }
  }
}

