set<Pii> ans;

void dfs(int node, int par) {
    used[node] = 1;
    for(Pii child: graph[node]) {
        if(child.first == par) continue;
        if(!used[child.first]) {
            dfs(child.first, node);
            if(outdegree[child.first] % 2) {
                outdegree[node] = 1-outdegree[node];
                outdegree[child.first] = 1-outdegree[child.first];
                if(child.second) {
                    if(ans.find({node, child.first}) == ans.end()) {
                        ans.insert(Pii(child.first, node));
                        continue;
                    }
                } else {
                    if(ans.find({child.first, node}) == ans.end()) {
                        ans.insert(Pii(node, child.first));
                        continue;
                    }
                }
            }
        }
        if(child.second) {
            if(ans.find({child.first, node}) == ans.end()) ans.insert(Pii(node, child.first));
        } else {
            if(ans.find({node, child.first}) == ans.end()) ans.insert(Pii(child.first, node));
        }

    }
}

