//!  8888ba.88ba           oo           !//
//!  88  '8b  '8b                       !//
//!  88   88   88 .d8888b. dP 88d888b.  !//
//!  88   88   88 88'  '88 88 88'  '88  !//
//!  88   88   88 88.  .88 88 88    88  !//
//!  dP   dP   dP '88888P8 dP dP    dP  !//
//!=====================================!//
int main()
{
    const int N = read<int>(), M = read<int>();
    Graph G(N);
    for (int i = 0; i < M; i++) {
        const int u = read<int>() - 1, v = read<int>() - 1;
        G.addEdge(u, v, true);
    }
    if (M % 2 == 1) { return std::cout << -1 << std::endl, 0; }
    std::vector<int> in(N, 0);
    Tree T(N);
    Graph H(N);
    std::vector<int> depth(N, -1);
    auto dfs = [&](auto&& self, const int s, const int prev, const int d) -> void {
        depth[s] = d;
        for (const int to : G[s]) {
            if (to == prev) { continue; }
            if (depth[to] != -1) {
                if (depth[to] < depth[s]) { H.addEdge(s, to), in[s]++; }
            } else {
                T.addEdge(s, to), self(self, to, s, d + 1);
            }
        }
    };
    dfs(dfs, 0, -1, 0);
    SHOW(T, H);
    auto dfs2 = [&](auto&& self, const int s, const int prev) -> void {
        for (const int to : T[s]) { self(self, to, s); }
        if (prev != -1) {
            if (in[s] % 2 == 0) {
                in[prev]++, H.addEdge(prev, s);
            } else {
                in[s]++, H.addEdge(s, prev);
            }
        }
    };
    SHOW(H);
    dfs2(dfs2, 0, -1);
    for (int i = 0; i < N; i++) {
        for (const int to : H[i]) { std::cout << i + 1 << " " << to + 1 << std::endl; }
    }
    return 0;
}

