                    }
                    else if(cnt[e] == 1){
                        q.push(e);
                        break;
                    }
                }
            }
        }
        else{
            int temp = q.front();
            q.pop();
            if(used[temp]){
                continue;
            }
            used[temp] = true;
            finish++;
            for(auto e: E[temp]){
                int small = min(e, temp);
                int big = max(e, temp);
                if(!usedEdge[make_pair(small, big)]){
                    if(even[temp] % 2 == 0){
                        ans.push_back(make_pair(e, temp));
