const ll MOD=1000000007;
// const ll MOD=998244353;

vector<vector<int>> G(101010);
int deg[101010];

const int MAX_V=101010;

int par[MAX_V];
int rnk[MAX_V];
int num[MAX_V];

void init(){
  for(int i=0;i<MAX_V;i++){
    par[i]=i;
    rnk[i]=0;
    num[i]=1;
  }
}

int find(int x){
  if (par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x]);
  }
}

void unite(int x, int y){
  x = find(x);
  y = find(y);
  if (x == y) return;

  if (rnk[x] < rnk[y]){
    par[x] = y;
    num[y] += num[x];
  }else{
    par[y] = x;
    num[x] += num[y];
    if (rnk[x] == rnk[y]) rnk[x]++;
  }
}

bool same(int x, int y){
  return find(x) == find(y);
}

bool dfs(int v,int p){
  if(G[v].size()==1&&p!=-1){
    if(deg[v]%2){
      cout<<v<<" "<<p<<endl;
      return 0;
    }else{
      deg[p]++;
      return 1;
    }
  }else{
    for(int u:G[v]){
      if(u==p) continue;
      if(dfs(u,v)){
        cout<<v<<" "<<u<<endl;
        deg[v]++;
      }
    }
    if(p!=-1){
      if(deg[v]%2){
        cout<<v<<" "<<p<<endl;
        return 0;
      }else{
        return 1;
      }
    }
  }
  return 0;
}

int main(){
  int N,M; cin>>N>>M;
  if(M%2){
    cout<<-1<<endl;
    return 0;
  }
  init();
  rep(i,M){
    int A,B; cin>>A>>B;
    if(same(A,B)){
      cout<<A<<" "<<B<<endl;
      deg[A]++;
    }else{
      G[A].push_back(B);
      G[B].push_back(A);
      unite(A,B);
    }
  }
  dfs(1,-1);
  return 0;
}

