#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    int N, M;
    cin >> N >> M;
    vector<set<int>> graph(N+1);
    vector<int>A(M);
    vector<int>B(M);
    for (int i = 0; i < M; ++i) {
        cin >> A[i] >> B[i];
        graph[A[i]].insert(B[i]);
        graph[B[i]].insert(A[i]);
    }
    if(M % 2 == 1){
        cout << "-1";
        return 0;
    }

    // 全域木を求める
    vector<set<int>> spTree(N+1);
    stack<int> s1;
    vector<int>flag1(N+1, 0);
    s1.push(1);
    flag1[1] = 1;
    while (! s1.empty()){
        int t = s1.top();
        s1.pop();
        for (auto x : graph[t]) {
            if(flag1[x] == 0){
                flag1[x] = 1;
                spTree[t].insert(x);
                spTree[x].insert(t);
                s1.push(x);
            }
        }
    }

    // 頂点から出る辺の本数
    vector<int>degree(N+1, 0);

    // 木以外の辺の向きを適当に決める
    for (int i = 0; i < N; ++i) {
        if(spTree[A[i]].count(B[i]) == 0) {
            degree[A[i]]++;
            cout << A[i] << " " << B[i] << endl;
        }
    }

    // 確定済みでない辺の個数が1の頂点をstackに入れて探索
    stack<int> s2;
    for (int i = 1; i < N+1; ++i) {
        if(spTree[i].size() == 1){
            s2.push(i);
        }
    }
    while (! s2.empty()) {
        int t = s2.top();
        s2.pop();
        auto itr = spTree[t].begin();
        if(degree[t] % 2 == 0){
            cout << *itr << " " << t << endl;
            degree[*itr]++;
        } else {
            cout << t << " " << *itr << endl;
            degree[t]++;
        }
        spTree[*itr].erase(t);
        if(spTree[*itr].size() == 1){
            s2.push(*itr);
        } else if(spTree[*itr].size() == 0){
            break;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
