#define FIO ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
typedef pair<int, int> PII;

vector<ll> adj[100005];
vector<pair<ll, ll> > ans;
ll dp[100005];

ll dfs(ll x, ll parent){
    dp[x] = 1;
    ll cnt = 0;
    for(ll i = 0 ; i < adj[x].size() ; i++){
        ll y = adj[x][i];
        if(y == parent){
            continue;
        }
        if(dp[y] == 1){
            cnt++;
            ans.push_back({x, y});
        }else{
            cnt += dfs(y, x);
        }
    }
    if(parent == -1){
        return (ll)0;
    }
    if(cnt%2){
        ans.push_back({x, parent});
        cnt = 0;
    }else{
        ans.push_back({parent, x});
        cnt = 1;
    }
    return cnt;
}

int main(){
    FIO;
    ll n, m;
    cin >> n >> m;

    for(ll i = 0 ; i <= n ; i++){
        dp[i] = 0;
    }
    for(ll i = 0 ; i < m ; i++){
        ll x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    if(m%2){
        cout << "-1" << endl;
        return 0;
    }
    dfs((ll)1, -1);
    for(ll i = 0 ; i < m ; i++){
        cout << ans[i].first << " " << ans[i].second << endl;
    }
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define ll             long long int
#define eb             emplace_back
#define pii            pair <int, int>

static const int maxn = 2e5 + 5;

vector <int> graph[maxn];
int deg[maxn];
bool bad[maxn];

signed main()
{
      ios_base::sync_with_stdio(false);
      cin.tie(nullptr);
      cout.tie(nullptr);



      int tnode, tedge;
      cin >> tnode >> tedge;
      for (int e = 1; e <= tedge; e++)
      {
            int u, v;
            cin >> u >> v;
            graph[u].eb(v);
            graph[v].eb(u);
            ++deg[u];
            ++deg[v];
      }
      set <int> odd, even;
      for (int i = 1; i <= tnode; i++)
      {
            if (deg[i] & 1) odd.emplace(i);
            else even.emplace(i);
      }
      vector <pii> edges;
      while (1)
      {
            //cerr << even.size() << " --- " << odd.size() << endl;
            if (even.empty()) break;
            int from = *even.begin(); even.erase(even.begin());
            if (bad[from] == 1) continue;
            bad[from] = 1;
            for (int to : graph[from])
            {
                  if (bad[to]) continue;
                  --deg[to];
                  edges.eb(from, to);
                  if (deg[to] % 2 == 0)
                  {
                        odd.erase(to);
                        even.insert(to);
                  }
                  else
                  {
                        even.erase(to);
                        odd.insert(to);
                  }
            }
      }
      if (odd.empty() == false)
      {
            cout << "-1" << endl;
            return 0;
      }
      for (auto it : edges) cout << it.first << " " << it.second << endl;
}

