bool bfs(v2ll &line, vll &d, ll n, vec<pllll> &ans){
	queue<ll> q;
	q.push(0);
	vec<bool> passed(n, 0);
	ll now;

	while(!q.empty()){
		now = q.front(); q.pop();
		passed[now] = true;
		map<ll, ll> next;
		ll count = 0;

		for(auto t : line[now]){
			if(d[t] > 0){
				next[(1 - (d[t] % 2)) * 10000000000 + d[t] * 100000 + t] = t;
			}
			if(passed[t]) continue;
			q.push(t);
		}

		//cout << now << " " << next.size() << endl;
		for(auto t : next){
			if(d[now] == 0) break;
			if(count % 2 == 0 && min(d[now], (ll)(next.size() - count)) == 1) break;

			count++;
			d[now]--, d[t.second]--;
			ans.pb({now + 1, t.second + 1});

		}

	}

	For(i, n){
		if(d[i] != 0){
			return false;
		}
	}

	return true;
}

