void remove_edge(ll s, ll t, vector<set<ll>>& edge, ll* degree, bool* odd){
  edge[s].erase(t);
  degree[s]--;
  edge[t].erase(s);
  degree[t]--;
  odd[s] = !odd[s];
  degree[0]--;
  printf("%lld %lld\n", s, t);
  if(degree[s] == 1){
    ll another = *edge[s].begin();
    if(odd[s]) remove_edge(s, another, edge, degree, odd);
    else remove_edge(another, s, edge, degree, odd);
  }
  if(degree[t] == 1){
    ll another = *edge[t].begin();
    if(odd[t]) remove_edge(t, another, edge, degree, odd);
    else remove_edge(another, t, edge, degree, odd);
  }

}

int main(){
  ll N, M; cin >> N >> M;
  vector<set<ll>> edge(N+1);
  ll degree[N+1] = {M};
  bool odd[N+1] = {};
  rep(_, M){
    ll a, b;
    cin >> a >> b;
    edge[a].insert(b);
    degree[a]++;
    edge[b].insert(a);
    degree[b]++;
  }

  if(M % 2){
    cout << -1 << endl;
    exit(0);
  }
  repi(i, 1, N+1){
    if(degree[i] == 1){
      ll another = *edge[i].begin();
      if(odd[i]) remove_edge(i, another, edge, degree, odd);
      else remove_edge(another, i, edge, degree, odd);
    }
  }
  repi(i, 1, N+1){
    if(degree[0] == 0) break;
    while(degree[i])
      remove_edge(i, *edge[i].begin(), edge, degree, odd);
  }
  return 0;
}

