int tot,go[2*maxn],id[2*maxn],nxt[2*maxn],f1[maxn];
void ins(int x,int y,int i)
{
	go[++tot]=y;
	id[tot]=i;
	nxt[tot]=f1[x];
	f1[x]=tot;
}

bool vis[maxn],dfn[maxn],dg[maxn];
int e[maxn][2],e0;
void dfs(int k,int last)
{
	dfn[k]=1;
	for(int p=f1[k]; p; p=nxt[p]) if (!vis[id[p]])
	{
		vis[id[p]]=1;
		if (!dfn[go[p]])
		{
			dfs(go[p],k);
		} else
		{
			e[++e0][0]=k, e[e0][1]=go[p];
			dg[k]^=1;
		}
	}
	if (!last) return;
	if (dg[k]) e[++e0][0]=k, e[e0][1]=last;
		else e[++e0][0]=last, e[e0][1]=k, dg[last]^=1;
}

