    }

    while(!que.empty()){
        int t = que.top().first;
        int idx = que.top().second;

        que.pop();

        if(used[idx]){
            continue;
        }

        used[idx] = 1;

        if((edge2[idx]+out[idx]) % 2 == 1){

            for(int i = 0;i < graph[idx].size();i++){
                if(p.find(make_pair(idx, graph[idx][i])) == p.end()){

                    out[graph[idx][i]]++;

                    edge2[graph[idx][i]]--;

                    que.push(make_pair(edge2[graph[idx][i]], graph[idx][i]));

                    ans.push(make_pair(graph[idx][i], idx));

                    p.insert(make_pair(graph[idx][i], idx));
                    p.insert(make_pair(idx, graph[idx][i]));
                }
            }

        }else{

            for(int i = 0;i < graph[idx].size();i++){
                if(p.find(make_pair(idx, graph[idx][i])) == p.end()){

                    ans.push(make_pair(idx, graph[idx][i]));

                    edge2[graph[idx][i]]--;

                    que.push(make_pair(edge2[graph[idx][i]], graph[idx][i]));

                    p.insert(make_pair(graph[idx][i], idx));
                    p.insert(make_pair(idx, graph[idx][i]));
                }
            }

        }
    }

    while(!ans.empty()){
        cout << ans.front().first << " " << ans.front().second << endl;
        ans.pop();
    }



    return 0;
}

