    }

    vc<vc<int>> a(n);
    unordered_map<ll, bool> ex;
    constexpr ll A = 1e9;
    Rep(m){
        Cin(int, x, y);
        x --, y --;
        a[x].push_back(y);
        a[y].push_back(x);
        ex[A*x+y] = ex[A*y+x] = true;
    }
    vc<int> d(n+1);
