        q.pop();
        // Cout("[", e.first, " ", e.second, "]");
        if(d[e.second] == 0) continue;
        for(auto i : a[e.second]){
            if(!ex[A*e.second+i]) continue;
            for(auto j : a[i]){
                if(j == e.second || !ex[A*i+j]) continue;
                Cout(i+1, " ", e.second+1);
                Cout(i+1, " ", j+1);
                // cout << endl;
                d[e.second] --;
                d[i] -= 2;
                d[j] --;
                q.emplace(d[e.second], e.second);
                q.emplace(d[i], i);
                q.emplace(d[j], j);
                ex[A*e.second+i] = ex[A*i+e.second] = false;
                ex[A*i+j] = ex[A*j+i] = false;
                c ++;
                goto next;
            }
        }
        next:;
    }
}

