		for (const auto &e : edge[now]) {
			if (!visited[e.to]) cnt++;
		}

		if (cnt == 0 && out[now] % 2 != 0) {
			flag = false;
		}
		else {

			int cnt2 = out[now] % 2;
			vector<int> memo;

			for (const auto &e : edge[now]) {
				if (now < e.to) {
					if (cnt2 > 0) {
						out[now]++;
						ans.emplace_back(now, e.to);
						cnt2--;
					}
					else {
						out[e.to]++;
						ans.emplace_back(e.to, now);
					}
				}
				if(!visited[e.to]) memo.emplace_back(e.to);
			}

			for (const auto &e : memo) que.emplace(e);

		}
	}

	if (flag) for (const auto &e : ans) cout << e.first + 1 << " " << e.second + 1 << "\n";
	else cout << -1 << "\n";

	return 0;
}

