    }
    bool upper(int x, int y) {
        return in[x] <= in[y] && out[y] <= out[x];
    }
    int get(int x, int y) {
        if (upper(x, y)) return x;
        if (upper(y, x)) return y;
        per(i, 0, 21) {
            if (!upper(up[x][i], y)) x = up[x][i];
        }
        return up[x][0];
    }
}


inline void set_direction(int x, int y) {
    if (ans.count({y, x})) {
        ans.erase({y, x});
        --deg[y];
    }
    ++deg[x];
    ans.insert({x, y});
}

inline void reverse_direction(int x, int y) {
    if (ans.count({x, y}))
        set_direction(y, x);
    set_direction(x, y);
}

void dfs(int v) {
    used[v] = true;
    for(int to : g[v]) {
        if (!used[to]) dfs(to);
        set_direction(v, to);
    }
}

int restore(int v, int p) {
    int blc = lazy[v];
    for(int to : r[v]) {
        if (to == p) continue;
        blc += restore(to, v);
    }
    if (blc % 2 == 1) {
        reverse_direction(v, p);
    }
    return blc;
}

void reverse_on_path(int x, int y) {
    int v = lca::get(x, y);
    ++lazy[x], ++lazy[y];
    lazy[v] -= 2;
}

