bool dfs(int p, int b, int ndp = 0) {
    assert(!vis[p]);
    vis[p] = true;
    dps[p] = ndp;
    V<int> unused;
    for (int d: g[p]) {
        if (d == b) continue;
        if (vis[d]) {
            if (dps[d] > dps[p]) continue;
            // back edge
//            cerr << p << " b> " << d << endl;
            unused.push_back(d);
            continue;
        }
        if (!dfs(d, p, ndp + 1)) {
//            cerr << p << " -> " << d << endl;
            unused.push_back(d);
        }
    }

    int k = int(unused.size());
    for (int i = 0; i + 1 < k; i += 2) {
        edges.push_back({p, unused[i]});
        edges.push_back({p, unused[i + 1]});
    }
    if (k % 2 == 0) return false;
    edges.push_back({p, unused.back()});
    edges.push_back({p, b});
    return true;
}

