int dfs(int crr) {
    vis[crr] = 1;
    V<P> E;
    int children = 0;

    for (auto next : G[crr]) {
        if (vis[next.first]) {
            E.push_back(next);
            continue;
        }
        evis[next.second] = 1;
        if (dfs(next.first)) {
            children++;
            A.push_back({ crr, next.first });
        } else {
            A.push_back({ next.first, crr });
        }
    }

    for (auto e : E) {
        if (evis[e.second]) continue;
        evis[e.second] = 1;
        children++;
        A.push_back({ crr, e.first });
    }

    return (children % 2) == 0;
}

