template<typename T>
class fixed_point : T {
  public:
    explicit constexpr fixed_point (T&& t) noexcept
      : T(std::forward<T>(t)) {}
    template<typename... Args>
    constexpr decltype(auto) operator()(Args&&... args) const
      {return T::operator()(*this, std::forward<Args>(args)...);}
};
template<typename T>
static inline constexpr decltype(auto) fix (T&& t) noexcept {
  return fixed_point<T>{std::forward<T>(t)};
}
int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  size_t n, m; std::cin >> n >> m;
  auto err = [&] {
    std::cout << -1 << std::endl;
    exit(0);
  };
  if (m % 2 == 1) err();
  std::vector<std::vector<size_t>> graph(n);
  std::vector<int> out_deg(n, 0);
  for (size_t _ = 0; _ < n; _++) {
    size_t a, b; std::cin >> a >> b;
    a--, b--;
    graph.at(a).push_back(b);
    graph.at(b).push_back(a);
  }
  std::vector<int> ckd(n, false);
  std::vector<std::vector<size_t>> tree(n);
  std::vector<std::pair<size_t, size_t>> ret;
  auto insert = [&] (size_t a, size_t b) {
    ret.emplace_back(a, b);
  };
  constexpr size_t root = 0;
  fix ([&](auto dfs, size_t crr, size_t p) -> void {
    ckd.at(crr) = true;
    for (auto const& nxt : graph.at(crr)) {
      if (nxt == p) continue;
      if (ckd.at(nxt)) {
        if (crr < nxt) {
          out_deg.at(crr)++;
          insert(crr, nxt);
        }
        continue;
      }
      tree.at(crr).push_back(nxt);
      dfs(nxt, crr);
    }
  })(root, root);
  fix ([&](auto dfs, size_t crr, size_t p) -> void {
    for (auto const& nxt : tree.at(crr)) {
      if (nxt == p) continue;
      dfs(nxt, crr);
    }
    if (crr == root) return;
    if (out_deg.at(crr) % 2 == 0) {
      out_deg.at(p)++;
      insert(p, crr);
    } else {
      out_deg.at(crr)++;
      insert(crr, p);
    }
  })(root, root);
  std::for_each(out_deg.begin(), out_deg.end(), [](auto x){
    assert(x % 2 == 0);
  });
  assert(ret.size() == m);
  std::for_each(ret.begin(), ret.end(), [](auto p){
    std::cout << p.first + 1 << " " << p.second + 1 << std::endl;
  });
  return 0;
}

