int deg[100000];

bitset<100000> visited;
set<pair<int, int>> done;
vector<pair<int, int>> ans;

void dfs(int i){
    visited[i] = 1;
    for(int j : edges[i]){
        pair<int, int> p = {min(i, j), max(i, j)};
        if(done.count(p)) continue;
        done.insert(p);
        if(!visited[j]){
            tree[i].push_back(j);
            dfs(j);
        }else{
            deg[i]++;
            ans.emplace_back(i, j);
        }
    }
}

void dfs2(int i, int p){
    for(int j : tree[i]) dfs2(j, i);
    if(p == -1) return;
    if(deg[i]%2){
        ans.emplace_back(i, p);
    }else{
        ans.emplace_back(p, i);
        deg[p]++;
    }
}

