set<P> ret;

void rec(int cur, int par, const vector<vector<int>> &g, vector<int> &sum)
{
    for (auto v : g[cur])
    {
        if (v == par)
            continue;
        rec(v, cur, g, sum);
        if (sum[v] % 2)
        {
            ret.emplace(v, cur);
        }
        else
        {
            ret.emplace(cur, v);
        }
        sum[cur] += sum[v];
    }
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; i++)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    if (m % 2)
    {
        cout << -1 << endl;
        return 0;
    }
    vector<vector<int>> tr(n);
    queue<P> que;
    vector<int> used(n, 0), cnt(n, 0);
    que.push(P(0, -1));
    used[0] = 1;
    while (!que.empty())
    {
        int cur = que.front().first;
        int par = que.front().second;
        que.pop();
        for (auto v : g[cur])
        {
            if (v == par)
                continue;
            if (used[v])
            {
                if (ret.find(P(v, cur)) != ret.end())
                    continue;
                ret.emplace(cur, v);
                cnt[cur]++;
                continue;
            }
            tr[cur].push_back(v);
            cnt[cur]++;
            used[v] = 1;
            que.emplace(v, cur);
        }
    }
    vector<int> sum(n, 0);
    for (int i = 0; i < n; i++)
        if (cnt[i] % 2)
            sum[i]++;
    rec(0, -1, tr, sum);
    assert(ret.size() == m);
    vector<int> aa(n, 0);
    for (auto p : ret)
    {
        aa[p.first]++;
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }
    for (int i = 0; i < n; i++)
        assert(aa[i] % 2 == 0);
}

