typedef pair<int, int> P;
vector<int> G[100000];
int deg[100000];
bool vis[100000];
int par[100000];
vector<int> child[100000];
void build(int v, int p) {
	vis[v] = 1;
	par[v] = p;
	if (p != -1) child[p].push_back(v);
	for (int to : G[v]) {
		if (!vis[to]) build(to, v);
	}
}
void solve(int v) {
	for (int to : child[v]) {
		solve(to);
	}
	if (par[v] == -1) return;
	if (deg[v] % 2 == 0) {
		deg[par[v]]++;
		cout << (par[v] + 1) << " " << (v + 1) << endl;
	}
	else {
		deg[v]++;
		cout << (v + 1) << " " << (par[v] + 1) << endl;
	}
}
