	int N, M;
	cin >> N >> M;
	if (M % 2) {
		cout << -1 << endl;
		return 0;
	}
	vector<P> edge;
	for (int i = 0; i < M; i++) {
		int A, B;
		cin >> A >> B;
		A--; B--;
		G[A].push_back(B);
		G[B].push_back(A);
		edge.emplace_back(A, B);
	}
	build(0, -1);
	for (int i = 0; i < M; i++) {
		int A = edge[i].first, B = edge[i].second;
		if (par[A] != B && par[B] != A) {
			deg[A]++;
			cout << (A + 1) << " " << (B + 1) << endl;
		}
	}
	solve(0);
}

