  }

  stack<pair<int, int>> treeEdgeStack;
  queue<int> bfsQueue;
  bool visited[N + 1];
  int count[N + 1];
  int parent[N + 1];
  vector<string> results;
  for (int i = 1; i <= N; i++) {
    visited[i] = false;
    count[i] = 0;
    parent[i] = 0;
  }

  bfsQueue.push(1);
  visited[1] = true;

