vector<vector<int>> graph;
vector<int> degree;
vector<int> depth;
vector<pair<int, int>> ans;

void DFS(int v, int previous_v){
    for(int adjacent : graph[v]){
        if(adjacent == previous_v) continue;

        if(depth[adjacent] == -1){// just dive down
            depth[adjacent] = depth[v] + 1;
            DFS(adjacent, v);
        }
        else{
            if(depth[adjacent] > depth[v]){
                ans.push_back({v, adjacent});
                degree[v] += 1;
            }
        }
    }

    if(previous_v == -1) return;
    if(previous_v != -1){
        if(degree[v] % 2 == 1){// then use (v --> previous_v) to make degree[v] even
            ans.push_back({v, previous_v});
            degree[v] += 1;
        }
        else{// degree[v] % 2 == 0
            if(previous_v != -1){
                ans.push_back({previous_v, v});
                degree[previous_v] += 1;
            }
        }
    }
}

int main(){
    int n, m;
    cin >> n >> m;

    graph.resize(m);
    degree.resize(n);
    depth.assign(n, -1);

    for(int i=0; i<m; i++){
        int a, b;
        cin >> a >> b;
        a -= 1;
        b -= 1;

        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if(m % 2 == 1){
        cout << -1 << endl;
        return 0;
    }

    depth[0] = 0;
    DFS(0,-1);

    for(int i=0; i<m; i++){
        cout << ans[i].first + 1 << " " << ans[i].second + 1 << endl;
    }
    return 0;
}

