bool used[N];
int h[N], changed[N];
int dfs(int v, int p=-1){
    if(used[v]) return h[v] < h[p];
    used[v] = true;
    h[v] = (p == -1 ? 0 : h[p]+1);
    for(int u : g[v]){
        if(u == p)
            continue;
        changed[v] ^= 1^dfs(u, v);
    }
    return changed[v];
}

