	while(!Q.empty())Q.pop();
	for(int i=1;i<=n;i++)
		Q.push(s[i]);
	while(!Q.empty()){
		node u=Q.top();Q.pop();
		int size=u.P.size();
		for(int i=0;i<(size/2*2);i++){
			int v=u.P[i];
			int id=u.T[i];
			if(!vis[id]){
				u.cnt--;
				vis[id]=v;
				s[v].cnt--;
			}
