#include <bits/stdc++.h>
using namespace std;
using LL = long long; using PII = pair<LL, LL>; using VI = vector<LL>; using VVI = vector<VI>;
using VB = vector<bool>; using VS = vector<string>; using VP = vector<PII>;
#define VV(T)        vector<vector<T>>
#define PB           push_back
#define MP           make_pair
#define SZ(a)        LL((a).size())
#define EACH(x, c)   for (auto x : (c))
#define ALL(c)       (c).begin(), (c).end()
#define REVERSE(c)   reverse(ALL(c))
#define SORT(c)      stable_sort(ALL(c))
#define RSORT(c)     stable_sort((c).rbegin(), (c).rend())
#define FOR(i, a, b) for (LL i = (a); i < (b); ++i)
#define REP(i, n)    FOR(i, 0, n)
#define $(x)         {cout << #x << " = " << (x) << endl;}

void solve(LL N, LL M, vector<LL> A, vector<LL> B){
    if (M % 2 == 1) {
        cout << "-1" << endl;
        return;
    }
    vector<unordered_set<LL>> G(N + 1);
    REP(i, M) {
        G[A[i]].insert(B[i]);
        G[B[i]].insert(A[i]);
    }

    // determine from less out-degree node
    priority_queue<PII, VP, greater<PII>> q;   // PII = (out-degree, node)
    FOR(i, 1, N + 1) {
        q.push(MP(SZ(G[i]), i));
    }
    VB used(N + 1);
    VI out_degs(N + 1);   // out-degree of each node so far
    VP edges;
    while (!q.empty()) {
        auto v = q.top(); q.pop();
        if (!used[v.second]) {
            used[v.second] = true;
            // add outgoing edges as much as it has even num of out-edges
            LL n_edges_out = (out_degs[v.second] % 2 == 0) ? ((v.first / 2) * 2) : ((v.first % 2 == 0) ? v.first - 1 : v.first);
            REP(i, n_edges_out) {
                auto itr = G[v.second].begin();
                advance(itr, i);
                auto w = *itr;
                edges.PB(MP(v.second, w));
                G[w].erase(v.second);
                q.push(MP(SZ(G[w]), w));
            }
            // and then add incoming edges for remaining (single) edge if remain
            if (v.first - n_edges_out == 1) {
                auto itr = G[v.second].begin();
                advance(itr, n_edges_out);
                auto w = *itr;
                edges.PB(MP(w, v.second));
                G[w].erase(v.second);
                q.push(MP(SZ(G[w]), w));
                out_degs[w]++;
            }
        }
    }
    EACH(edge, edges) {
        cout << edge.first << " " << edge.second << endl;
    }
}

int main(){
    LL N;
    scanf("%lld",&N);
    LL M;
    scanf("%lld",&M);
    vector<LL> A(M);
    vector<LL> B(M);
    for(int i = 0 ; i < M ; i++){
        scanf("%lld",&A[i]);
        scanf("%lld",&B[i]);
    }
    solve(N, M, move(A), move(B));
    return 0;
}

