int dfs(vector<set<int>> &g, vector<bool> &used, int v, int p) {
    if (used[v]) return 0;
    used[v] = true;
    int c = g[v].size()-1;
    for (auto u: g[v]) {
        if (u == p) continue;
        if (dfs(g, used, u, v)) {
            g[v].erase(u);
            c--;
        } else {
            g[u].erase(v);
        }
    }
    return c%2;
}

