void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 N,M;
    cin >> N >> M;
    vector<i64> A(M),B(M);
    rep(i,0,M){
        cin >> A[i] >> B[i];
        --A[i];
        --B[i];
    }

    if(M%2!=0){
        cout << -1 << endl;
        return;
    }

    vector<i64> deg(N);
    rep(i,0,M){
        ++deg[A[i]];
        ++deg[B[i]];
    }

    i64 odd=0;
    rep(i,0,N){
        if(deg[i]%2==1) ++odd;
    }

    if(odd%2==1){
        cout << "No" << endl;
        return;
    }

    vector<set<i64>> graph(N);
    rep(i,0,M){
        graph[A[i]].insert(B[i]);
        graph[B[i]].insert(A[i]);
    }

    vector<pair<i64,i64>> ans;
    vector<i64> x(N);
    rep(u,0,N){
        i64 num=graph[u].size()/2*2,out=0;
        if(x[u]%2==1){
            if(num+1<=graph[u].size()) ++num;
            else --num;
        }
        vector<i64> erased;
        for(auto v:graph[u]){
            if(out==num) break;

            erased.emplace_back(v);
            graph[v].erase(u);
            ans.emplace_back(make_pair(u,v));
            ++out;
        }
        for(auto v:erased) graph[u].erase(v);
        for(auto v:graph[u]){
            graph[v].erase(u);
            ++x[v];
            ans.emplace_back(make_pair(v,u));
        }
    }

    rep(i,0,ans.size()){
        cout << ans[i].first+1 << " " << ans[i].second+1 << endl;
    }
}

