const int NO_CARRY = -1;

int N, M;
vector<int> parent;
vector<vector<int>> adj;
vector<tuple<int, int, int>> answer;
vector<bool> visited;
vector<int> original;

int root(int x) {
  return parent[x] = (x == parent[x] ? x : root(parent[x]));
}

int dfs(int x) {
  visited[x] = true;
  int now = NO_CARRY;
  for (int y : adj[x]) {
    if (visited[y]) {
      continue;
    }
    int z = dfs(y);
    if (z == NO_CARRY) {
      if (now == NO_CARRY) {
        now = y;
      } else {
        answer.push_back(make_tuple(now, x, y));
        now = NO_CARRY;
      }
    } else {
      answer.push_back(make_tuple(x, y, z));
    }
  }
  return now;
}

