bool dfs(vector<unordered_set<int>> &graph, vector<int> &in, vector<int> &out, vector<bool> &visit,
	 unordered_map<pair<int,int>,int> &edges, unordered_map<pair<int,int>,int> &used, int cur){

  visit[cur] = true;

  for(auto next : graph[cur]){
    if(visit[next] && used[{cur,next}]) continue;

    bool f = false;
    if(visit[next] && !used[{cur,next}]) f = true;

    used[{cur,next}] = true;
    used[{next,cur}] = true;

    if(in[cur] % 2 == 0){
      if(graph[cur].size() - in[cur] - out[cur] == 1){
	out[cur]++;
	in[next]++;
	edges[{cur,next}] = 0;
	edges[{next,cur}] = 1;
        bool r = true;
	if(f){
	  if(graph[next].size() - in[next] - out[next] == 0 && in[next] % 2 != 0){
	    r = false;
	  }
	}else{
	  r = dfs(graph,in,out,visit,edges,used,next);
	}

	if(!r){
	  out[cur]--;
	  in[next]--;

	  out[next]++;
	  in[cur]++;

	  edges[{next,cur}] = 0;
	  edges[{cur,next}] = 1;
	}
      }else{
	out[next]++;
	in[cur]++;
	edges[{next,cur}] = 0;
	edges[{cur,next}] = 1;
        bool r = true;
	if(f){
	  if(graph[next].size() - in[next] - out[next] == 0 && in[next] % 2 != 0){
	    r = false;
	  }
	}else{
	  r = dfs(graph,in,out,visit,edges,used,next);
	}

	if(!r){
	  out[next]--;
	  in[cur]--;

	  out[cur]++;
	  in[next]++;
	  edges[{cur,next}] = 0;
	  edges[{next,cur}] = 1;
	}
      }
    }else{
      out[cur]++;
      in[next]++;
      edges[{cur,next}] = 0;
      edges[{next,cur}] = 1;
      bool r = true;
      if(f){
	if(graph[next].size() - in[next] - out[next] == 0 && in[next] % 2 != 0){
	  r = false;
	}
      }else{
	r = dfs(graph,in,out,visit,edges,used,next);
      }

      if(!r){
	out[cur]--;
	in[next]--;

	out[next]++;
	in[cur]++;

	edges[{next,cur}] = 0;
	edges[{cur,next}] = 1;
      }

    }
  }

  if(in[cur] % 2 != 0) return false;
  return true;
}

