class lca_solver {
public:
    vector<vector<int>> chldren;  // chldren[i] = 頂点iの子のリスト(ただし親を含んでいる場合でも正常に動く)
    int root;
    // if root,parent is -1.
    vector<int> parent;
    vector<int> depth;
    vector<vector<int>> parent_pow2;
    lca_solver(vector<vector<int>> &children_, int root_)
            : chldren(children_), root(root_) {
        calc_parent_and_depth();
        calc_parent_pow2();
    };
    int lca(int u, int v) {
        // make sure depth(u) > depth(v).
        if (depth[u] < depth[v]) swap(u, v);
        for (size_t k = 0; k < parent_pow2.size(); k++) {
            if (((depth[u] - depth[v]) >> k) & 1) {
                u = parent_pow2[k][u];
            }
        }
        if (u == v) return u;
        for (int k = (int)parent_pow2.size() - 1; k >= 0; k--) {
            if (parent_pow2[k][u] != parent_pow2[k][v]) {
                u = parent_pow2[k][u];
                v = parent_pow2[k][v];
            }
        }
        return parent_pow2[0][u];
    }
    int dist(int u, int v) {
        return depth[u] + depth[v] - depth[lca(u, v)] * 2;
    }

private:
    void calc_parent_and_depth() {
        parent = vector<int>(chldren.size(), -1);
        depth = vector<int>(chldren.size(), -1);
        sub_calc_parent_and_depth(root, -1, 0);
    }
    void sub_calc_parent_and_depth(int cur, int par, int dep) {
        parent[cur] = par;
        depth[cur] = dep;
        for (int child : chldren[cur]) {
            if (child != par) {
                sub_calc_parent_and_depth(child, cur, dep + 1);
            }
        }
    }
    void calc_parent_pow2() {
        // parent_pow2[k][i] = 2^k parent of node i.
        parent_pow2 = vector<vector<int>>(ceil(log(chldren.size()) / log(2) + 1),
                                          vector<int>(chldren.size(), -1));
        parent_pow2[0] = parent;
        for (size_t k = 0; k + 1 < parent_pow2.size(); k++) {
            for (size_t v = 0; v < chldren.size(); v++) {
                if (parent_pow2[k][v] >= 0) {
                    parent_pow2[k + 1][v] = parent_pow2[k][parent_pow2[k][v]];
                }
            }
        }
    }
};

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 N,M;
    cin >> N >> M;
    vector<i64> A(M),B(M);
    rep(i,0,M){
