        graph[B[i]].emplace_back(A[i]);
    }

    vector<pair<i64,i64>> ans;

    vector<bool> visited(N);
    vector<bool> closed(N);
    vector<vector<int>> tree(N);
    vector<i64> out(N);
    function<void(i64,i64)> rec=[&](i64 u,i64 p){
        visited[u]=true;
        for(auto v:graph[u]){
            if(v==p) continue;
            if(closed[v]) continue;
            ++out[u];
            if(!visited[v]) {
                print(u);
                print(v);
                tree[u].emplace_back(v);
                rec(v, u);
            }else{
                print(u);
                print(v);
                ans.emplace_back(make_pair(u,v));
            }
        }
        closed[u]=true;
    };

    rec(0,-1);

    lca_solver ls(tree,0);

    vector<i64> us;
    rep(i,0,N) if(out[i]%2==1) us.emplace_back(i);

    if(us.size()%2!=0){
        cout << -1 << endl;
        return;;
    }

    print(us);

    vector<pair<i64,i64>> ps;
    rep(i,0,us.size()/2){
        ps.emplace_back(make_pair(us[i],us[i+us.size()/2]));
    }

    vector<i64> sum(N);

    for(auto p:ps){
        i64 u=p.first,v=p.second;
        i64 w=ls.lca(u,v);

        sum[w]++;
        sum[w]++;
        sum[u]--;
        sum[v]--;
    }

    print(sum);

    function<i64(i64)> dfs=[&](i64 u){
        i64 res=sum[u];
        for(auto v:tree[u]){

            i64 tmp=dfs(v);
            if(tmp%2==0) ans.emplace_back(make_pair(u,v));
            else ans.emplace_back(make_pair(v,u));
            res+=tmp;
        }
        return res;
    };
    dfs(0);

    rep(i,0,ans.size()){
        cout << ans[i].first+1 << " " << ans[i].second+1 << endl;
    }
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
