struct Edge
{
public:
    Edge(int to, int dir) : to(to), dir(dir) {}
    int to;
    int dir;
};

using Edges = vector<Edge>;
using Graph = vector<Edges>;

vector<bool> visited;

void DFS(Graph& g, int node)
{
    visited[node] = true;

    int outNum = 0;
    for (const auto& e : g[node])
    {
        if (e.dir == 1)
        {
            ++outNum;
        }
    }

    if (outNum % 2 == 0)
    {
        for (auto& e : g[node])
        {
            if (e.dir == 0)
            {
                e.dir = -1;

                for (auto& f : g[e.to])
                {
                    if (f.to == node)
                    {
                        f.dir = 1;
                        break;
                    }
                }
            }
        }
    }
    else
    {
        for (auto& e : g[node])
        {
            if (e.dir == 0)
            {
                e.dir = 1;

                for (auto& f : g[e.to])
                {
                    if (f.to == node)
                    {
                        f.dir = -1;
                        break;
                    }
                }

                break;
            }
        }
    }

    for (const auto& e : g[node])
    {
        if (visited[e.to])
        {
            continue;
        }

        DFS(g, e.to);
    }
}

