using namespace std;
#define MAXN 200006
int n , m;

int head[MAXN] , to[MAXN << 1] , nex[MAXN << 1] , ecn = -1;
void ade( int u , int v ) {
	to[++ecn] = v , nex[ecn] = head[u] , head[u] = ecn;
}
int fa[MAXN];
int find( int x ) {
	return fa[x] == x ? x : fa[x] = find( fa[x] );
}
struct e{ int u , v; } E[MAXN];
int tt[MAXN] , deg[MAXN];
void dfs( int u , int fa , int ee ) {
	for( int i = head[u] ; ~ i ; i = nex[i] ) {
		int v = to[i];
		if( v == fa ) continue;
		dfs( v , u , i );
	}
	if( u == 1 ) return;
	if( deg[u] ) {
		deg[u] ^= 1;
		if( ~ ee & 1 ) 
			swap( E[tt[ee >> 1]].u , E[tt[ee >> 1]].v );
	} else {
		deg[fa] ^= 1;
		if( ee & 1 ) 
			swap( E[tt[ee >> 1]].u , E[tt[ee >> 1]].v );
	}
}
int main() {
	memset( head , -1 , sizeof head );
	cin >> n >> m;
	if( m & 1 ) return puts("-1") , 0;
	for( int i = 1 ; i <= n ; ++ i ) fa[i] = i;
	for( int i = 1 , u , v ; i <= m ; ++ i ) {
		scanf("%d%d",&u,&v);
		E[i] = ( e ) { u , v };
		if( find( u ) != find( v ) ) {
			ade( u , v ) , ade( v , u );
			tt[ecn >> 1] = i;
			fa[find( u )] = find( v );
		} else {
			deg[u] ^= 1;
		}
	}
	dfs( 1 , 1 , 0 );
	for( int i = 1 ; i <= m ; ++ i ) printf("%d %d\n",E[i].u , E[i].v);
}

