struct edge{
  ll from, to, num;
  edge(ll a, ll b, ll c):from(a), to(b), num(c){}
};
struct graphMatSolver{
  vector<bool> used;
  vector<ll> x, v;
  vector<vector<edge>> G;
  vector<edge> E;
  ll cnt = 0;
  ll N, M;

  graphMatSolver(ll max_n, ll max_m, vll dat){
    N = max_n, M = max_m;
    used.resize(N, false);
    x.resize(M, 0);
    v.resize(N, 0);
    G.resize(N);
    for(int i=0;i<dat.size();i++) v[i] = dat[i];
  }

  void err(){
    std::cout << -1 << '\n';
    exit(0);
  }

  void add_edge(ll from, ll to){
    if(from==to) return;
    G[from].push_back(edge(from, to, cnt));
    G[to].push_back(edge(from, to, cnt));
    E.push_back(edge(from, to, cnt));
    cnt++;
  }

  ll dfs(ll now){
    ll ret = v[now];
    used[now] = true;
    for(auto e:G[now]){
      ll to = (e.to==now?e.from:e.to);
      if(used[to]) continue;
      ll tmp = dfs(to);
      if(now==e.from) x[e.num] = tmp;
      else x[e.num] = tmp;
      ret ^= tmp;
    }
    return ret;
  }

  void solve(){
    for(int i=0;i<N;i++){
      if(used[i]) continue;
      ll y = dfs(i);
      if(y!=0) err();
    }
  }

  edge & operator [](int k){
    return E[k];
  }
};

int main(int argc, char const *argv[]) {
  ll n, m;std::cin >> n >> m;
  vvl T;
  vll z(n+1, 0);
  for(int i=0;i<m;i++){
    ll a, b;scanf("%lld %lld", &a, &b);
    a--, b--;
    T.push_back(vll{a, b});
    // a -> b
    z[a]^=1;
  }

  graphMatSolver mg(n+1, m+1, z);
  for(auto e:T) mg.add_edge(e[0], e[1]);
  mg.solve();
  for(auto e:mg.E) {
    if(mg.x[e.num]){
      std::cout << e.to+1 << " " << e.from+1 << '\n';
    }else{
      std::cout << e.from+1 << " " << e.to+1 << '\n';
    }
  }

  return 0;
}

