typedef vector <VL> VVL;
typedef vector <VB> VVB;
typedef vector <VP> VVP;

const int MOD = 1000000007;
const int INF = 1000000001;
const ll LINF = 1000000000000000001LL;

int dfs(int v, int par, VVI &g, VB &vis, VP &ans) {
    vis[v] = true;

    int outc = 0;
    for (int u : g[v]) {
        if (!vis[u]) {
            outc += 1 - dfs(u, v, g, vis, ans);
        } else if (u != par) {
            if (u < v) {
                ans.pb({v, u});
                outc++;
            }
        }
    }

    if (par != -1) {
        if (outc % 2) {
            ans.pb({v, par});
        } else {
            ans.pb({par, v});
        }
    } else {
        assert(outc % 2 == 0);
    }

    return outc % 2;
}

VP solve(int n, int m, VVI &g) {
    VP ans;
    VB vis(n, false);

    int up = dfs(0, -1, g, vis, ans);

    assert(up == 0);
    assert(SIZE(ans) == m);

    return ans;
}

