	    cout << -1 << endl;
	    return 0;
	}
	vector<int> res(N+1), have(N+1, 0);
	for(int i=1; i<=N; ++i){
	    res[i]=g[i].size();
	}
	for(int i=1; i<=N; ++i){
	    vector<int> afford;
	    for(int p=0; p<g[i].size(); ++p){
	        if(g[i][p]>i){
