	                    ++have[g[i][p]];
	                }else{
	                    ans[i].push_back(g[i][p]);
	                    ++have[i];
	                }
	                --res[g[i][p]];
	                --res[i];
	            }
	            else afford.push_back(p);
	        }
	    }
	    if((have[i]+res[i])%2==0){
	        for(int p=0; p<afford.size(); ++p){
	                ans[i].push_back(g[i][afford[p]]);
	                --res[g[i][afford[p]]];
