set<ll> graph[100010];
vector<ll> Circuit(){
    stack<ll> currentPath;
    vector<ll> circuit;
    currentPath.push(0);
    ll currentV=0;
    while(!currentPath.empty()){
        if(graph[currentV].size()!=0){
            currentPath.push(currentV);
            ll nextV=*(graph[currentV].begin());
            graph[currentV].erase(nextV);
            graph[nextV].erase(currentV);
            currentV=nextV;
        }else{
            circuit.push_back(currentV);
            currentV=currentPath.top();
            currentPath.pop();
        }
    }
    return circuit;
}
