void Ins(int x,int y,int id){e[++cs].y=y;e[cs].id=id;e[cs].next=lin[x];lin[x]=cs;}
void Ins2(int x,int y,int id){Ins(x,y,id);Ins(y,x,id);}

void into(){
  scanf("%d%d",&n,&m);
  for (int i=1;i<=m;++i){
	int x,y;
	scanf("%d%d",&x,&y);
	Ins2(x,y,i);
  }
}

int vis[N+9],vis0[N+9];
int deg[N+9];
int ans0,ans[N+9][2];

void Dfs_ans0(int k,int fa){
  vis[k]=1;
  for (int i=lin[k];i;i=e[i].next){
	int y=e[i].y,id=e[i].id;
	if (y==fa) continue;
	if (!vis[y]) Dfs_ans0(y,k);
	else if (!vis0[id]){
	  vis0[id]=1;
	  ans[id][0]=k;ans[id][1]=y;
	  deg[k]^=1;
	}
  }
}

void Dfs_ans1(int k,int fa){
  for (int i=lin[k];i;i=e[i].next){
	int y=e[i].y,id=e[i].id;
	if (y==fa||vis0[id]) continue;
	Dfs_ans1(e[i].y,k);
	if (deg[y]){
	  vis0[id]=1;
	  ans[id][0]=y;ans[id][1]=k;
	  deg[y]^=1;
	}else{
	  vis0[id]=1;
	  ans[id][0]=k;ans[id][1]=y;
	  deg[k]^=1;
	}
  }
}

