bool vis[N];
int deg[N];

void bfs(int u) {
  queue<int> q;
  q.push(u);
  vis[u] = true;

  while (q.size()) {
    int u = q.front();
    q.pop();

    bool first = true;
    for (int v: edges[u]) {
      if (vis[v]) continue;
      vis[v] = true;

      if (deg[v] % 2 == 1 && first) {
        printf("%d %d\n", v+1, u+1);
        first = false;
        --deg[v];
      } else {
        printf("%d %d\n", u+1, v+1);
      }

      q.push(v);
    }
  }
}

