  scanf("%d %d", &n, &m);
  if (m % 2 == 1) return 0 * printf("-1\n");

  for (int i = 0; i < m; ++i) {
    int u, v;
    scanf("%d %d", &u, &v);
    --u, --v;

    edges[u].push_back(v);
    edges[v].push_back(u);

    ++deg[u], ++deg[v];
  }

  for (int i = 0; i < n; ++i) if (!vis[i]) bfs(i);

  return 0;
}

