  int n, m;
  cin >> n >> m;
  vector<vector<int>> graph(n+1);
  rep(i, m) {
    int a,b;
    cin >> a >> b;

    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  using pi = pair<int,int>;
  map<pi, int> e;
  vector<int> g(n, 0);
  vector<pi> ans;
  for (int i = 1; i <= n; ++i) {
    for (auto&& edge : graph[i]) {
      pi pp = {i, edge};
      pi pm = {edge, i};
      if (!e[pp] and !e[pm]) {
        e[pp] = true;
        e[pm] = true;
        if (g[i] == 0) {
          g[edge] -= 1;
          g[i] += 1;
          ans.push_back(pp);
        } else if (g[i] < 0) {
          g[i] = -g[i];
          g[i] %= 2;
          if (g[i] == 0) {
            g[edge] -= 1;
            g[i] += 1;
            ans.push_back(pp);
          } else {
            g[edge] += 1;
            g[i] = 0;
            ans.push_back(pm);
          }
        } else if (g[i] > 0) {
          g[i] %= 2;
          g[edge] -= 1;
          g[i] += 1;
          ans.push_back(pp);
        }
      }
    }
  }

  for (auto itr : g) {
    itr = -itr;
