struct Edge {
	int id, to;
};
class UnionFind {
	mutable std::vector<int> parent;
	int find(const int a) const {
		return (parent[a] >= 0) ? parent[a] = find(parent[a]) : a;
	}
public:
	UnionFind(const int size) : parent(size, -1) {};
	bool is_same(const int a, const int b) const {
		return find(a) == find(b);
	}
	void merge(const int a, const int b) {
		auto ar = find(a);
		auto br = find(b);
		if (ar != br) {
			if (parent[ar] < parent[br]) {
				parent[ar] += parent[br];
				parent[br] = ar;
			}
			else {
				parent[br] += parent[ar];
				parent[ar] = br;
			}
		}
	}
};
int main() {
	int n, m; std::cin >> n >> m;
	std::vector<std::vector<Edge>> node(n);
	for (auto i = 0; i < m; ++i) {
		int a, b; std::cin >> a >> b;
		node[a - 1].push_back({ i, b - 1 });
		node[b - 1].push_back({ i, a - 1 });
	}
	std::vector<bool> is_join(n, false);
	std::vector<bool> is_free_edge(m, false);
	std::queue<int> queue; queue.push(0); is_join[0] = true;
	std::vector<int> parent(n, -1);
	std::vector<int> child_count(n, 0);
	std::queue<int> leaf;
	while (!queue.empty()) {
		auto top = queue.front(); queue.pop();
		for (const auto& e : node[top]) if (!is_join[e.to]) {
			is_join[e.to] = true;
			is_free_edge[e.id] = true;
			parent[e.to] = top;
			queue.push(e.to);
			++child_count[top];
		}
		if (child_count[top] == 0) leaf.push(top);
	}
	std::vector<int> out_edge_count(n, 0);
	std::vector<std::pair<int, int>> result;
	for (auto i = 0; i < n; ++i) {
		for (const auto& e : node[i]) if (i < e.to && !is_free_edge[e.id]) {
			out_edge_count[i] ++;
			result.emplace_back(i, e.to);
		}
	}
	while (!leaf.empty() && leaf.front() != 0) {
		auto top = leaf.front(); leaf.pop();
		if (out_edge_count[top] % 2 == 0) {
			result.emplace_back(parent[top], top);
			out_edge_count[parent[top]]++;
		}
		else {
			result.emplace_back(top, parent[top]);
			out_edge_count[top]++;
		}
		child_count[parent[top]]--;
		if (child_count[parent[top]] == 0) leaf.push(parent[top]);
	}
	if (out_edge_count[0] % 2 == 0) {
		for (const auto& pair : result) {
			std::cout << pair.first + 1 << " " << pair.second + 1 << "\n";
		}
	}
	else {
		std::cout << -1 << std::endl;
	}
}

