{
	for(int i=1;i<=n;i++)
		ft[i]=i;
	int tot=0;
	for(int i=1;i<=m;i++)
	{
		if(Union(edge[i].u,edge[i].v))
		{
			T[edge[i].u].push_back(edge[i].v);
			T[edge[i].v].push_back(edge[i].u);
			if(rt==-1) rt=edge[i].u;
			vis[i]=1;
			tot++;
		}
		if(tot==n-1) break;
