#define SIZE 100000
using namespace std;
typedef pair<int, int> P;
int n, m, d[SIZE], used[SIZE];
P edge[SIZE];
vector<int> v[SIZE], w[SIZE];
vector<P> ans;
void f(int x){
    for(int i=0;i<w[x].size();i++){
        int y = w[x][i];
        f(y);
        if(d[y] % 2 == 1){
            d[y]++;
            ans.push_back(P(y, x));
        }else{
            d[x]++;
            ans.push_back(P(x, y));
        }
    }
}
int main(void){
    cin >> n >> m;
    queue<int> q;
    for(int i=0;i<m;i++){
        int a, b;
        cin >> a >> b;
        edge[i] = P(--a, --b);
        v[a].push_back(i);
        v[b].push_back(i);
    }

    if(m % 2 == 1){
        cout << -1 << endl;
        return 0;
    }

    fill(d, d+n, 0);
    fill(used, used+n, 0);
    q.push(0);
    used[0] = 1;
    while(!q.empty()){
        int x = q.front();
        q.pop();
        for(int i=0;i<v[x].size();i++){
            P p = edge[v[x][i]];
            int y = p.first;
            if(y == -1)continue;
            edge[v[x][i]] = P(-1, -1);
            if(y == x)y = p.second;
            if(used[y] == 0){
                w[x].push_back(y);
                q.push(y);
                used[y] = 1;
            }else{
                ans.push_back(P(x, y));
                d[x]++;
            }
        }
    }

    f(0);
    m = min(m, (int)ans.size());
    for(int i=0;i<m;i++){
        cout << ans[i].first+1 << " " << ans[i].second+1 << endl;
    }
}

