const int N=1e5+100;
int n,m,dg[N],vi[N],tag[N];
int tot,first[N],nxt[N*2],point[N*2],id[N*2];
struct node
{
	int u,v,dir;
}e[N];
inline void add_edge(int x,int y,int z)
{
	tot++;
	nxt[tot]=first[x];
	first[x]=tot;
	point[tot]=y;
	id[tot]=z;
}
void dfs(int x,int last)
{
	vi[x]=1;
	if (dg[x]&1) tag[x]++;
	for (int i=first[x];i!=-1;i=nxt[i])
	{
		int u=point[i];
		if (vi[u]) continue;
		dfs(u,id[i]);
		tag[x]+=tag[u];
	}
	if (tag[x]&1) e[last].dir^=1;
}
int main()
{
	tot=-1;
	memset(first,-1,sizeof(first));
	memset(nxt,-1,sizeof(nxt));
	scanf("%d%d",&n,&m);
	for (int i=1;i<=m;i++)
	{
		scanf("%d%d",&e[i].u,&e[i].v);
		dg[e[i].u]++;
		e[i].dir=1;
		add_edge(e[i].u,e[i].v,i);
		add_edge(e[i].v,e[i].u,i);
	}
	int cnt=0;
	for (int i=1;i<=n;i++) cnt+=(dg[i]&1);
	if (cnt&1)
	{
		printf("-1\n");
		return 0;
	}
	dfs(1,0);
	for (int i=1;i<=m;i++) if (e[i].dir==0) swap(e[i].u,e[i].v);
	for (int i=1;i<=m;i++) printf("%d %d\n",e[i].u,e[i].v);
}

