int dfs(ll now, ll prev) {
  visit[now] = 1;
  for (ll i : G[now]) {
    if (visit[i]) continue;
    dfs(i, now);
  }

  if ( cnt[now] % 2 != 0 ) {
    cnt[now]++;
    cnt[prev]++;
    rev.insert({now, prev});
    rev.insert({prev, now});
    // cout << SP << now << SP << prev << BR;
  }
  return 0;
}

