using namespace std;

#define MAXN 100005
#define fi first
#define se second

typedef pair<int, int> pii;

int A[MAXN], B[MAXN];
bool C[MAXN];
vector<pii> ed[MAXN];
bool chk[MAXN];
int num[MAXN], nn;
int cnt[MAXN], dep[MAXN], par[MAXN], pe[MAXN];

void dfs(int x) {
	//printf("dfs(%d)\n", x);
	num[nn++] = x;
	chk[x] = true;
	for(int i = 0; i < ed[x].size(); i++) {
		pii a = ed[x][i];
		if(A[a.se] == x) cnt[x]++;
		if(a.fi == par[x]) pe[x] = a.se;
		if(!chk[a.fi]) {
			dep[a.fi] = dep[x] + 1;
			par[a.fi] = x;
			dfs(a.fi);
		}
	}
}

int main() {
	int N, M;
	int u, v;

	scanf("%d%d", &N, &M);
	for(int i = 0; i < M; i++) scanf("%d%d", A + i, B + i);

	for(int i = 0; i < M; i++) {
		ed[A[i]].push_back(make_pair(B[i], i));
		ed[B[i]].push_back(make_pair(A[i], i));
	}

	if(M % 2) {
		printf("-1");
		return 0;
	}
	dfs(1);
	//for(int i = 1; i <= N; i++) printf("%d ", par[i]);
	//printf("\n");
	int l = -1;
	for(int i = 0; i < N; i++) if(cnt[num[i]] % 2) {
		if(l == -1) l = num[i];
		else {
			int a = l, b = num[i];
			//printf("%d, %d\n", a, b);
			if(dep[a] < dep[b]) swap(a, b);
			while(dep[a] > dep[b]) {
				C[pe[a]] ^= true;
				a = par[a];
			}
			while(a != b) {
				C[pe[a]] ^= true;
				C[pe[b]] ^= true;
				a = par[a];
				b = par[b];
			}
			//printf("%d\n", a);
			l = -1;
		}
	}

	//for(int i = 1; i <= N; i++) for(auto a : ed[i]) printf("%d %d %d\n", i, a.fi, (int)a.se);
	for(int i = 0; i < M; i++) {
		if(C[i]) swap(A[i], B[i]);
		printf("%d %d\n", A[i], B[i]);
	}
	return 0;
}

