typedef long long ll;
#define REP(i,n) for (int i = 0; i < n ; i++)
template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;

int N,M;
int A[100010];
int B[100010];

set < pair < int,int > > unused;
reversed_priority_queue < tuple < int, int > > que; // degree, idx

vector < int > G[100010];
int degacc[100010];

int main ()
{
    cin >> N >> M;
    REP(i,M) {
        cin >> A[i] >> B[i];
        if (A[i] > B[i]) swap(A[i], B[i]);
        unused.insert(make_pair(A[i], B[i]));
        G[A[i]].push_back(B[i]);
        G[B[i]].push_back(A[i]);
    }

    for (int i = 1; i <= N; i++) {
        que.push(tuple < int,int > ((int)G[i].size(), i));
    }

    vector < pair < int,int > > ans;
    while (!que.empty()) {
        int deg, idx;
        tie(deg, idx) = que.top();
        que.pop();
        if (deg == 0) continue;
        int cnt = 0;
        REP(i,G[idx].size()) {
            int v1 = idx;
            int v2 = G[idx][i];
            if (v1 > v2) swap(v1, v2);
            if (unused.find(make_pair(v1, v2)) != unused.end()) {
                cnt++;
            }
        }
        if (cnt != deg) {
            que.push(tuple < int,int > (cnt, idx));
            continue;
        }
        REP(i,G[idx].size()) {
            int v1 = idx;
            int v2 = G[idx][i];
            if (v1 > v2) swap(v1, v2);
            if (unused.find(make_pair(v1, v2)) != unused.end()) {
                unused.erase(unused.find(make_pair(v1, v2)));
                if (degacc[idx] % 2 == 1) {
                    degacc[idx]++;
                    ans.push_back(make_pair(idx, G[idx][i]));
                } else {
                    degacc[G[idx][i]]++;
                    ans.push_back(make_pair(G[idx][i], idx));
                }
                que.push(tuple < int,int > (deg, idx));
                continue;
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        if (degacc[i] % 2 == 1) {
            cout << -1 << endl;
            assert(false);
            return 0;
        }
    }

    REP(i,ans.size()) {
        cout << ans[i].first << " " << ans[i].second << endl;
    }

    return 0;
}

