typedef std::pair<int, int> Pii;
typedef std::set<Pii> MySet;

const int kMaxn = 1e5 + 10;

struct TT {
	int de, to, ee;
	bool operator<(const TT & t) const {
		return de < t.de;
	}
} T[kMaxn];

struct Edge {
	int to, next, tag;
} E[kMaxn << 1];

int n, m, tote = 1;
int back[kMaxn], deg[kMaxn];
int extra[kMaxn];
MySet V;

inline void AddEdge(int u, int v) {
	E[++tote] = (Edge){v, back[u]}, back[u] = tote;
	E[++tote] = (Edge){u, back[v]}, back[v] = tote;
	++deg[u], ++deg[v];
}
inline void Dec(int v) {
	V.erase(Pii(deg[v], v));
	if (--deg[v]) V.insert(Pii(deg[v], v));
}

int main() {
	scanf("%d%d", &n, &m);
	if (m & 1) {
		puts("-1");
		return 0;
	}
	for (int i = 0, u, v; i < m; i++) {
		scanf("%d%d", &u, &v);
		AddEdge(u, v);
	}

	for (int i = 1; i <= n; i++) V.insert(Pii(deg[i], i));
	for (int u, d; !V.empty(); ) {
		u = V.begin()->sec, d = V.begin()->fir;
		V.erase(V.begin());
		if (d < 2) continue;
		int cntt = 0;
		forto(u) {
			if (E[e].tag) continue;
			T[cntt++] = (TT){deg[v], v, e};
		}
		std::sort(T, T + cntt);
		int i = 0, e;
		for (; i < cntt && T[i].de == 1; i++) {
			printf("%d %d\n", u, T[i].to);
			e = T[i].ee;
			E[e].tag = E[e ^ 1].tag = 1;
			d--;
		}
		int lim = cntt & 1 ? cntt - 1 : cntt;
		for (; i < lim; i++) {
			printf("%d %d\n", u, T[i].to);
			Dec(T[i].to);
			e = T[i].ee;
			E[e].tag = E[e ^ 1].tag = 1;
			d--;
		}
	}

	return 0;
}

