const int N = 1e5+10;
const ll M = 1e9+7;

vector<int>E[N];
vector<pii>Ans;
bool Vis[N], Finished[N];

bool generate_edges(int cur, int prev){
	int edges = 0;
	Vis[cur] = true;

	for(auto i: E[cur]){
		if(i == prev)continue;
		if(Vis[i] && !Finished[i]){
			edges++;
			Ans.pb({cur, i});
		}
		else if(!Vis[i] && generate_edges(i, cur)){
			edges++;
			Ans.pb({cur, i});
		}
	}

	Finished[cur] = true;
	if(edges%2)Ans.pb({cur, prev});
	return (edges%2==0);
}

