using namespace std;
typedef long long ll;
const int MAXN = 100100;

int N, M;
vector <int> edge[MAXN];
int nord;
int ord[MAXN];
int par[MAXN];
vector <int> res[MAXN];

void flood (int cloc, int last)
{
    if (par[cloc] != -2) return;

    ord[nord++] = cloc;
    par[cloc] = last;
    for (int neigh : edge[cloc])
    {
        if (neigh == last) continue;
        flood (neigh, cloc);
    }
}

int main()
{
    ios_base::sync_with_stdio(0);
    for (int i = 0; i < MAXN; i++)
        par[i] = -2;

    cin >> N >> M;
    for (int i = 0; i < M; i++)
    {
        int a, b;
        cin >> a >> b;
        a--, b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    if (M % 2 == 1)
    {
        cout << "-1\n";
        return 0;
    }

    nord = 0;
    flood (0, -1);
    for (int i = 0; i < N; i++)
    {
        for (int neigh : edge[i])
        {
            if (neigh > i)
            {
                if (par[neigh] != i && par[i] != neigh)
                {
                    res[i].push_back(neigh);
                }
            }
        }
    }
    for (int i = N - 1; i > 0; i--)
    {
        int cloc = ord[i];
        if (res[cloc].size() % 2 == 0)
            res[par[cloc]].push_back(cloc);
        else
            res[cloc].push_back(par[cloc]);
    }

    for (int i = 0; i < N; i++)
    {
        for (int neigh : res[i])
            cout << i + 1 << " " << neigh + 1 << "\n";
    }
}

