	cin.tie(NULL);
	ll n,m;
	cin >> n >> m;
	vector <pair<ll,ll>> edge;
	vector <vector<ll>> graph;
	graph.resize(n+1);
	vector <node> degree(n+1);
	vector <bool> visited(n+1,false);
	for (int z=1;z<=n;z++){
		degree[z].index = z;
	}
	for (int z=0;z<m;z++){
		ll a,b;
		cin >> a >> b;
		graph[a].push_back(b);
		graph[b].push_back(a);
		degree[a].degree++;
		degree[b].degree++;
	}
	if (m & 1){
		cout << -1 << endl;
		return 0;
	}
	vector <ll> out(n+1,0);
	sort(degree.begin(),degree.end());
	for (int z=1;z<=n;z++){
		ll u = z;
		z = degree[z].index;
		ll best = 1;
		ll v = 0;
		ll k = 0;
		for (int x=0;x<graph[z].size();x++){
			if (visited[graph[z][x]]) continue;
			k += 1;
		}
		if ((k+out[z]) & 1){
			for (int x=0;x<graph[z].size();x++){
				if (visited[graph[z][x]]) continue;
				if (degree[graph[z][x]].degree > best){
					best = degree[graph[z][x]].degree;
					v = x;
				}
			}
			cout << graph[z][v] << " " << z << endl;
			out[graph[z][v]]++;
			graph[z].erase(graph[z].begin()+v);
		}
		for (int x=0;x<graph[z].size();x++){
			if (visited[graph[z][x]]) continue;
			if (x == graph[z].size()-1 && (out[z] % 2 == 0)){
				out[graph[z][x]]++;
				cout << graph[z][x] << " " << z << endl;
				continue;
			}
			cout << z << " " << graph[z][x] << endl;
			out[z]++;
		}
		visited[z] = true;
		z = u;
	}
}

