template<class T=int> class undigraph : public graph<T> {
public:
    using graph<T>::g;
    using graph<T>::n;
    using graph<T>::edges;
    using graph<T>::usedv;
    int eid = 0;
    undigraph(int n) : graph<T>(n) {}
    // f < t
    void add(int f, int t, T c = 1, int ty = -1, int id = -1) {
        if (!(0 <= f && f < n && 0 <= t && t < n)) {
            debugline("undigraph add");
            deb(f, t, c, ty, id);
            ole();
        }
        if (id == -1)id = eid++;
        g[f].emplace_back(f, t, c, ty, id);
        g[t].emplace_back(t, f, c, ty, id + 1);
        edges.emplace_back(f, t, c, ty, id);
    }
    void add(edge<T> &e) {
        int f = e.f, t = e.t, ty = e.ty;
        T c = e.c;
        add(f, t, c, ty);
    }
    void ing(int m, int minus = 1) {
        rep(i, m) {
            int f, t;
            cin >> f >> t;
            f -= minus;
            t -= minus;
            add(f, t);
        }
    }
    void ingc(int m, int minus = 1) {
        rep(i, m) {
            int f, t, c;
            cin >> f >> t >> c;
            f -= minus;
            t -= minus;
            add(f, t, c);
        }
    }
    void ingct(int m, int minus = 1) {
        rep(i, m) {
            int f, t, c, ty;
            cin >> f >> t >> c >> ty;
            f -= minus;
            t -= minus;
            ty -= minus;
            add(f, t, c, ty);
        }
    }
    void ingtc(int m, int minus = 1) {
        rep(i, m) {
            int f, t, c, ty;
            cin >> f >> t >> ty >> c;
            f -= minus;
            t -= minus;
            ty -= minus;
            add(f, t, c, ty);
        }
    }
    bool used(edge<T> &e) { return usedv[e.id]; }
    bool used(int id) { return usedv[id]; }
    void del(edge<T> &e) { usedv[e.id] = 1; }
    void del(int id) { usedv[id] = 1; }
    void set_edges() {
        if (sz(edges))return;
        rep(i, n)fora(e, g[i])if (e.f < e.t)edges.push_back(e);
    }
};
