vi dijkstra2(const graph<int> &g, int s, int cant_arrive = -1) {
    if (!(0 <= s && s < g.n)) {
        debugline("dijkstra");
        deb(s, g.n);
        ole();
    }
    int initValue = MAX(int);
    vi dis(g.n, initValue);
    radixheap<int> q;
    dis[s] = 0;
    q.push(0, s);
    while (!q.empty()) {
        int nowc, i;
        tie(nowc, i) = q.pop();
        if (dis[i] != nowc)continue;
        for (auto &&e  : g.g[i]) {
            int to = e.t;
            int c = nowc + e.c;
            if (dis[to] > c) {
                dis[to] = c;
                q.push(dis[to], to);
            }
        }
    }    /*基本、たどり着かないなら-1*/    if (cant_arrive == -1)for (auto &&d :dis) if (d == initValue)d = -1;
    return dis;
}
template<class T> vector<T> dijkstra(const graph<T> &g, int s, int cant_arrive = -1) {
    if (!(0 <= s && s < g.n)) {
        debugline("dijkstra");
        deb(s, g.n);
        ole();
    }
    T initValue = MAX(T);
    vector<T> dis(g.n, initValue);
    priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
    dis[s] = 0;
    q.emplace(0, s);
    while (q.size()) {
        T nowc = q.top().fi;
        int i = q.top().se;
        q.pop();
        if (dis[i] != nowc)continue;
        for (auto &&e  : g.g[i]) {
            int to = e.t;
            T c = nowc + e.c;
            if (dis[to] > c) {
                dis[to] = c;
                q.emplace(dis[to], to);
            }
        }
    }    /*基本、たどり着かないなら-1*/    if (cant_arrive == -1)for (auto &&d :dis) if (d == initValue)d = -1;
    return dis;
}
template<class T> vector<vector<T>> warshall(const graph<T> &g, int cant_arrive = -1) {
    int n = g.n;
    vector<vector<T> > dis(n, vector<T>(n, linf));
    rep(i, n)fora(e, g.g[i])chmi(dis[e.f][e.t], e.c);
    rep(i, n)dis[i][i] = 0;
    rep(k, n)rep(i, n)rep(j, n)chmi(dis[i][j], dis[i][k] + dis[k][j]);    /*基本、たどり着かないなら-1*/    if (cant_arrive == -1)rep(i, n)rep(j, n) if (dis[i][j] == linf)dis[i][j] = -1;
    return dis;
}
template<class T> class MinOp { public: T operator()(T a, T b) { return min(a, b); }};
template<typename OpFunc> struct SparseTable {
    OpFunc op;
    signed size;
    vector<signed> lg;
    vector<vector<pair<signed, signed>>> table;
    void init(const vector<pair<signed, signed>> &array, OpFunc opfunc) {
        signed n = array.size();
        op = opfunc;
        lg.assign(n + 1, 0);
        for (signed i = 1; i <= n; i++) { lg[i] = 31 - __builtin_clz(i); }
        table.assign(lg[n] + 1, array);
        for (signed i = 1; i <= lg[n]; i++) { for (signed j = 0; j < n; j++) { if (j + (1 << (i - 1)) < n) { table[i][j] = op(table[i - 1][j], table[i - 1][j + (1 << (i - 1))]); } else { table[i][j] = table[i - 1][j]; }}}
    }
    pair<signed, signed> query(signed l, signed r) {
        assert(l < r);
        return op(table[lg[r - l]][l], table[lg[r - l]][r - (1 << lg[r - l])]);
    }
};
struct PMORMQ {
    vector<signed> a;
    SparseTable<MinOp<pair<signed, signed> > > sparse_table;
    vector<vector<vector<signed> > > lookup_table;
    vector<signed> block_type;
    signed block_size, n_block;
    void init(const vector<signed> &array) {
        a = array;
        signed n = a.size();
        block_size = std::max(1, (31 - __builtin_clz(n)) / 2);
        while (n % block_size != 0) {
            a.push_back(a.back() + 1);
            n++;
        }
        n_block = n / block_size;
        vector<pair<signed, signed> > b(n_block, make_pair(INT_MAX, INT_MAX));
        for (signed i = 0; i < n; i++) { b[i / block_size] = min(b[i / block_size], make_pair(a[i], i)); }
        sparse_table.init(b, MinOp<pair<signed, signed> >());
        block_type.assign(n_block, 0);
        for (signed i = 0; i < n_block; i++) {
            signed cur = 0;
            for (signed j = 0; j < block_size - 1; j++) {
                signed ind = i * block_size + j;
                if (a[ind] < a[ind + 1]) { cur |= 1 << j; }
            }
            block_type[i] = cur;
        }
        lookup_table.assign(1 << (block_size - 1), vector<vector<signed> >(block_size, vector<signed>(block_size + 1)));
        for (signed i = 0; i < (1 << (block_size - 1)); i++) {
            for (signed j = 0; j < block_size; j++) {
                signed res = 0;
                signed cur = 0;
                signed pos = j;
                for (signed k = j + 1; k <= block_size; k++) {
                    lookup_table[i][j][k] = pos;
                    if (i & (1 << (k - 1))) { cur++; } else { cur--; }
                    if (res > cur) {
                        pos = k;
                        res = cur;
                    }
                }
            }
        }
    }
    signed query(signed l, signed r) {
        assert(l < r);
        signed lb = l / block_size;
        signed rb = r / block_size;
        if (lb == rb) { return lb * block_size + lookup_table[block_type[lb]][l % block_size][r % block_size]; }
        signed pl = lb * block_size + lookup_table[block_type[lb]][l % block_size][block_size];
        signed pr = rb * block_size + lookup_table[block_type[rb]][0][r % block_size];
        signed pos = pl;
        if (r % block_size > 0 && a[pl] > a[pr]) { pos = pr; }
        if (lb + 1 == rb) { return pos; }
        signed spv = sparse_table.query(lb + 1, rb).second;
        if (a[pos] > a[spv]) { return spv; }
        return pos;
    }
};
template<class T=int> class tree : public undigraph<T> {
    PMORMQ rmq;
    int cnt;
    vector<signed> id, in;
    bool never = true;
    bool never_hld = true;
    void dfs(int x, int p, int d, int dis = 0) {
        id[cnt] = x;
        par[x] = p;
        dep.push_back(d);
        disv[x] = dis;
        in[x] = cnt++;
        forg(gi, g[x]) {
            if (t == p) { continue; }
            dfs(t, x, d + 1, dis + c);
            id[cnt] = x;
            dep.push_back(d);
            cnt++;
        }
    }
    void precalc() {
        never = false;
        cnt = 0;
        dep.clear();
        disv.assign(n, 0);
        in.assign(n, -1);
        id.assign(2 * n - 1, -1);
        par.assign(n, -1);
        dfs(root, -1, 0);
        rmq.init(dep);
    }    /********hld**************/    int pos;
    void hld_build() {
        never_hld = false;
        pos = 0;
        vid.assign(n, -1);
        head.assign(n, 0);
        sub.assign(n, 1);
        hvy.assign(n, -1);
        hdep.assign(n, 0);
        inv.assign(n, 0);
        type.assign(n, 0);
        build();
    }
    void build(vector<int> rs = vector<int>(1, 0)) {
        int c = 0;
        for (int r:rs) {
            dfs(r);
            bfs(r, c++);
        }
    }
    void dfs(int rt) {
        stack<P> st;
        hdep[rt] = 0;
        st.emplace(rt, 0);
        while (!st.empty()) {
            int v = st.top().first;
            int &i = st.top().second;
            if (i < (int) g[v].size()) {
                int u = g[v][i++].t;
                if (u == par[v]) continue;
                hdep[u] = hdep[v] + 1;
                st.emplace(u, 0);
            } else {
                st.pop();
                int res = 0;
                forg(gi, g[v]) {
                    int u = t;
                    if (u == par[v]) continue;
                    sub[v] += sub[u];
                    if (res < sub[u]) res = sub[u], hvy[v] = u;
                }
            }
        }
    }
    void bfs(int r, int c) {
        int &k = pos;
        queue<int> q({r});
        while (!q.empty()) {
            int h = q.front();
            q.pop();
            for (int i = h; i != -1; i = hvy[i]) {
                type[i] = c;
                vid[i] = k++;
                inv[vid[i]] = i;
                head[i] = h;
                forg(gi, g[i])if (t != par[i] && t != hvy[i]) q.push(t);
            }
        }
    }
    vi vid;
public:
    using undigraph<T>::g;    using undigraph<T>::n;    using undigraph<T>::edges;    using undigraph<T>::usedv;
    vector<int> disv;
    vector<signed> dep, par;
    vector<int> head, sub, hvy, inv, type, hdep/*おそらくグループ内のdep*/;/*vid := bel()*/    int root;
    tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }
    int lca(int a, int b) {
        if (never)precalc();
        int x = in[a];
        int y = in[b];
        if (x > y) { swap(x, y); }
        int pos = rmq.query(x, y + 1);
        return id[pos];
    }
    int dis(int a, int b) {
        if (never)precalc();
        int x = in[a];
        int y = in[b];
        if (x > y) { swap(x, y); }
        int pos = rmq.query(x, y + 1);
        int p = id[pos];
        return disv[a] + disv[b] - disv[p] * 2;
    }    /*O(N) 頂点に対しての処理を渡す*/    void for_each_(int u, int v, function<void(int)> fnode) {
        int r = lca(u, v);
        while (u != r) {
            fnode(u);
            u = par[u];
        }
        while (v != r) {
            fnode(v);
            v = par[v];
        }
        fnode(r);
    }    /*******hld********/    /*[l,r) O(log(N))*/    void for_each_(int u, int v, const function<void(int, int)> &f) {
        if (never_hld)hld_build();
        while (1) {
            if (vid[u] > vid[v]) swap(u, v);
            f(max(vid[head[v]], vid[u]), vid[v] + 1);
            if (head[u] != head[v]) v = par[head[v]]; else break;
        }
    }
    void for_each_edge(int u, int v, const function<void(int, int)> &f) {
        if (never_hld)hld_build();
        while (1) {
            if (vid[u] > vid[v]) swap(u, v);
            if (head[u] != head[v]) {
                f(vid[head[v]], vid[v] + 1);
                v = par[head[v]];
            } else {
                if (u != v) f(vid[u] + 1, vid[v] + 1);
                break;
            }
        }
    }
    int bel(int v) {
