template<class T> bool close(undigraph<T> &g) {
    int n = 0;
    int e = 0;
    rep(i, g.n) {
        if (sz(g[i]))n++;
        forg(gi, g[i]) { e++; }
    }
    return (e >> 1) >= n;
}
template<class T> bool close(undigraph<T> &g, int v) {
    unionfind uf(g.n);
    rep(i, g.n) {
        forg(gi, g[i]) {
            if (f < t)break;
            if (f == t && f == v)return true;
            if (uf.same(f, v) && uf.same(t, v))return true;
            uf.unite(f, t);
        }
    }
    return false;
}
