P farthest(undigraph<> &E, int cur, int pre, int d, vi &D) {
    D[cur] = d;
    P r = {d, cur};
    forg(gi, E[cur]) if (t != pre) {
            P v = farthest(E, t, cur, d + 1, D);
            r = max(r, v);
        }
    return r;
