template<class T> vi get_close1(digraph<T> &g) {
    int n = g.n;
    queue<int> q;
    vi d = outdegree(g);
    vi res(n, 1);
    rep(i, n) {
        if (d[i] == 0) {
            q += i;
            res[i] = 0;
        }
    }
    auto rg = rev(g);
    while (q.size()) {
        auto now = q.front();
        q.pop();
        forg(gi, rg[now]) {
            if (--d[t] == 0) {
                q += t;
                res[t] = 0;
            }
        }
    }
    return res;
};
template<class T> int krus(undigraph<T> &g) {
    int res = 0;
    unionfind uf(g.n);
    if (sz(g.edges) == 0)g.set_edges();
    int i = 0;
    auto E = g.edges;
    sort(E);
    fora(e, E) { if (uf.unite(e.f, e.t)) { res += e.c; }}
    return res;
}
template<class T> vi krus_id(undigraph<T> &g) {
    unionfind uf(g.n);
    if (sz(g.edges) == 0)g.set_edges();
    int i = 0;
    auto E = g.edges;
    sort(E);
    vi res;
    fora(e, E) { if (uf.unite(e.f, e.t)) { res.push_back(e.id); }}
    return res;
}
