class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  Int N, M;
  vector<set<Int> > E;
  vector<pii> ans;
  Solver() {}
  void input() {
      cin >> N >> M;
      E = vector<set<Int>>(M);
      rep(i, M){
          Int a, b;
          cin >> a >> b;
          a--;b--;
          E[a].insert(b);
          E[b].insert(a);
      }
  }
  void solve() {
      if(M %2 ==1)return;
      set<Int> one_nodes, two_nodes, more_nodes;
      rep(i, N){
          if(E[i].size() == 1){
              one_nodes.insert(i);
          }else if(E[i].size() == 2){
              two_nodes.insert(i);
          }
          else {
              more_nodes.insert(i);
          }
      }
      while(more_nodes.size() + two_nodes.size() + one_nodes.size() > 0){
          Int now;
          FOR(a, ans){
            cerr << a.first <<' ' << a.second << endl;
          }
          if(!one_nodes.empty()) {
              now = *one_nodes.begin();
              one_nodes.erase(now);

              pp(now);
              pp( E[now].size());
              Int next = *E[now].begin();
              E[now].erase(next);
              E[next].erase(now);
              if(E[next].size() == 0)throw 1;
              Int nextnext = *E[next].begin();
              E[next].erase(nextnext);
              E[nextnext].erase(next);

              ans.push_back({next, now});
              ans.push_back({next, nextnext});

            if(E[next].size() == 0){
              two_nodes.erase(next);
            }
              if(E[next].size() == 1){
                  more_nodes.erase(next);
                  one_nodes.insert(next);
              }
              else if(E[next].size() == 2){
                  more_nodes.erase(next);
                  two_nodes.insert(next);
              }

            if(E[nextnext].size() == 0){
              one_nodes.erase(nextnext);
            }
              if(E[nextnext].size() == 1){
                  two_nodes.erase(nextnext);
                  one_nodes.insert(nextnext);
              }
              else if(E[nextnext].size() == 2){
                  more_nodes.erase(nextnext);
                  two_nodes.insert(nextnext);
              }
          }else {
            if (!two_nodes.empty()) {
              now = *two_nodes.begin();
              two_nodes.erase(now);
            }else{
              now = *more_nodes.begin();
            }
            pp( now);
            Int a = *E[now].begin();
            E[now].erase(a);
            E[a].erase(now);
            Int b = *(E[now].begin());
            E[now].erase(b);
            E[b].erase(now);
            ans.push_back({now, a});
            ans.push_back({now, b});

            if (E[a].size() == 1) {
              two_nodes.erase(a);
              one_nodes.insert(a);
            }
            else if (E[a].size() == 2) {
              more_nodes.erase(a);
              two_nodes.insert(a);
            }
            if (E[b].size() == 1) {
              two_nodes.erase(b);
              one_nodes.insert(b);
            }
            else if (E[b].size() == 2) {
              more_nodes.erase(b);
              two_nodes.insert(b);
            }
            if (E[now].size() == 1) {
              one_nodes.insert(now);
            }
            else if (E[now].size() == 2) {
              two_nodes.insert(now);
            }
          }
      }
  }
  void output() {
      if(ans.size() == 0){
          cout << -1 <<endl;
          return;
      }
      FOR(a, ans){
          cout << a.first + 1 <<' ' << a.second +1<<endl;
      }
  }
};

