void bfs(){
	memset(vis,false,sizeof(vis));
	for(int i=1;i<=n;i++)q.insert((node){i,du[i]});
	while(!q.empty()){
		node x=*(q.begin());
		q.erase(x);
		int u=x.u,t=x.d%2,cnt=0;
		vis[u]=true;
		for(int i=head[u];i;i=Next[i]){
			int v=vet[i];
