// from KACTL
struct V {
	vector<pii> outs; // (dest, edge index)
	int nins = 0;
};

vector<pii> euler_walk(vector<V>& nodes, int nedges, int src=0) {
	int c = 0;
	trav(n, nodes) c += abs(n.nins - sz(n.outs));
	if (c > 2) return {};
	vector<vector<pii>::iterator> its;
	trav(n, nodes)
		its.push_back(n.outs.begin());
	vector<bool> eu(nedges);
	vector<pii> ret, s = {{src, -1}};
	while(!s.empty()) {
		int x = s.back().first;
		auto& it = its[x], end = nodes[x].outs.end();
		while(it != end && eu[it->second]) ++it;
		if(it == end) { ret.push_back(s.back()); s.pop_back(); }
		else { s.push_back(*it); eu[it->second] = true; }
	}
	if(sz(ret) != nedges+1)
		ret.clear(); // No Eulerian cycles/paths.
	// else, non-cycle if ret.front() != ret.back()
    if (!ret.empty())
        ret.pop_back();
	return ret;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);

    // even number of outgoing edges
    // sum in_v = sum out_v
    // sum of in_v is even
    // must have an even number of edges total
    //
    // 1 -> 2
    // 1 -> 3
    int n, m;
    cin >> n >> m;

    vector<pii> edges;

    // say you make an euler tour 
    // flip every other edge on the tour!
    vector<V> nodes(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        nodes[u].outs.emplace_back(v, i);
        nodes[v].outs.emplace_back(u, i);
        ++nodes[u].nins;
        ++nodes[v].nins;

        edges.emplace_back(u, v);
    }

    if (m % 2 == 1) {
        cout << -1 << '\n';
        return 0;
    }

    int src = 0;
    for (int i = 0; i < n; ++i) {
        if (nodes[i].nins % 2 == 1) {
            src = i;
            break;
        }
    }

    vector<pii> res = euler_walk(nodes, m, src);
    if (res.empty()) {
        cout << -1 << '\n';
    }

    for (int i = 0; i < m; ++i) {
        int s, ed_id;
        tie(s, ed_id) = res[i];

        int u, v;
        tie(u, v)= edges[ed_id];
        if (s == v) {
            swap(u, v);
        }
        if (i % 2 == 1) {
            swap(u, v);
        }

        ++u; ++v;
        cout << u << ' ' << v << '\n';
    }

    return 0;
}

