bool calc(int u,int p){
	if(g[u].empty())
		return d[u];
	bool ret=d[u];
	for(auto &v:g[u])
		if(v!=p){
			bool cur=calc(v,u);
			if(cur)
				sol.push_back({v,u});
			else
				sol.push_back({u,v});
			ret^=cur;
		}
	return ret;
}
