        if(rs)
        res[x]++;
        return;
    }
    else{
        rep(i,s.size()-1){
            sta[s[i].second]=x;
            dfs(s[i].first,x,0);
        }
        if((s.size()+rs)%2){
            sta[s[s.size()-1].second]=s[s.size()-1].first;
            dfs(s[s.size()-1].first,x,1);
        }
        else{
            sta[s[s.size()-1].second]=x;
            dfs(s[s.size()-1].first,x,0);
        }
    }
}

