const int N=100005;

int n,m,cnt,last[N],dep[N],deg[N];
bool vis[N];
struct edge{int to,next;}e[N*2];

void addedge(int u,int v)
{
	e[++cnt].to=v;e[cnt].next=last[u];last[u]=cnt;
	e[++cnt].to=u;e[cnt].next=last[v];last[v]=cnt;
}

void dfs1(int x,int fa)
{
	vis[x]=1;
	dep[x]=dep[fa]+1;
	for (int i=last[x];i;i=e[i].next)
		if (!vis[e[i].to]) dfs1(e[i].to,x);
		else if (e[i].to!=fa&&dep[e[i].to]>dep[x]) deg[x]^=1,printf("%d %d\n",x,e[i].to);
}

void dfs2(int x,int fa)
{
	vis[x]=1;
	for (int i=last[x];i;i=e[i].next)
		if (!vis[e[i].to]) dfs2(e[i].to,x);
	if (!fa) return;
	if (deg[x]) deg[x]^=1,printf("%d %d\n",x,fa);
	else deg[fa]^=1,printf("%d %d\n",fa,x);
}

int main()
{
	scanf("%d%d",&n,&m);
	for (int i=1;i<=m;i++)
	{
		int x,y;scanf("%d%d",&x,&y);
		addedge(x,y);
	}
	if (m&1) {puts("-1");return 0;}
	dfs1(1,0);
	memset(vis,0,sizeof(vis));
	dfs2(1,0);
	return 0;
}

