int main() {
    int n,m;
    cin>>n>>m;
    vector<vector<int>> root(n);
    vector<int> count(n);
    vector<int> ans_count(n);

    vector<int> clear(n);
    vector<int> check(n);
    vector<pii> ans;

    rep(i,m){
        int x,y;
        cin>>x>>y;
        root[x-1].pb(y-1);
        root[y-1].pb(x-1);
    }
    rep(i,n)count[i]=root[i].size();
    rep(i,n)ans_count[i]=root[i].size();
    rep(i,n)check[i]=0;
    rep(i,n)clear[i]=0;

    priority_queue<pii,vector<pii>,greater<pii>> que;
    rep(i,n){
        if(count[i]==1){
            que.push(mp(count[i],i));
        }
    }
    if(que.empty()){
        rep(i,n){
            if(count[i]%2==1){
                que.push(mp(count[i],i));
                break;
            }
        }  
        if(que.empty()){
            que.push(mp(count[0],0));
        }
    }

    while(!que.empty()){
        pii q=que.top();
        que.pop();
        int node=q.second;

        if(clear[node]==1){
            continue;
        }
        clear[node]=1;
        int first=1;

        for(auto x:root[node]){
            if(clear[x]==1){
                continue;
            }
            if(check[node]%2==1 && first==1){
                check[node]++;
                ans.pb(mp(node,x));
            }
            else{
                check[x]++;
                ans.pb(mp(x,node));
            }

            que.push(mp(ans_count[x],x));

            ans_count[node]--;
            ans_count[x]--;

            first=0;
        } 
    }
    rep(i,n){
        if(check[i]%2==1){
            cout<<-1<<endl;
            return 0;
        }
    }
    for(auto x:ans){
        cout<<x.first+1<<" "<<x.second+1<<endl;
    }


}

