	int n, m;
	cin >> n >> m;
	vvi g(n);
	REP(i, m) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	vi d(n);
	REP(i, n) d[i] = g[i].size();
	vi c(n);
	queue<int> q;
	set<pii> rem;
	REP(i, n) {
		if (d[i] == 1)
			q.push(i);
		else
			rem.insert({d[i], i});
	}
	bool ok = true;
	vector<pii> ans;
	while (!q.empty() || !rem.empty()) {
		while (!q.empty()) {
			int p = q.front();
			q.pop();
			d[p] = 0;
			REP(i, g[p].size()) {
				if (d[g[p][i]] > 0) {
					if (c[p]) {
						ans.push_back({p, g[p][i]});
						c[p] = 0;
					} else {
						ans.push_back({g[p][i], p});
						c[g[p][i]] = 1 - c[g[p][i]];
					}
					if (d[g[p][i]] != 1) {
						rem.erase({d[g[p][i]], g[p][i]});
						rem.insert({d[g[p][i]] - 1, g[p][i]});
					}
					if (--d[g[p][i]] == 1) {

						q.push(g[p][i]);
						rem.erase({1, g[p][i]});
						break;
					}
				}
			}
			if (c[p]) {
				ok = false;
				break;
			}
		}
		if (!rem.empty()) {
			int tmp, p;
			tie(tmp, p) = *rem.begin();
			rem.erase(rem.begin());
			assert(d[p] > 1);
			d[p] = 0;
			REP(i, g[p].size()) {
				if (d[g[p][i]] > 0) {
					if (c[p]) {
						ans.push_back({p, g[p][i]});
						c[p] = 0;
					} else {
						ans.push_back({g[p][i], p});
						c[g[p][i]] = 1 - c[g[p][i]];
					}
					if (d[g[p][i]] != 1) {
						rem.erase({d[g[p][i]], g[p][i]});
						rem.insert({d[g[p][i]] - 1, g[p][i]});
					}
					if (--d[g[p][i]] == 1) {
						q.push(g[p][i]);
						rem.erase({1, g[p][i]});
					}
					tmp--;
					break;
				}
			}
			if (tmp == 1) {
				q.push(p);
			} else {
				rem.insert({tmp, p});
			}
		}
	}

	if (!ok) {
		cout << -1 << endl;
		return 0;
	}
	assert(ans.size() == m);
	REP(i, m) {
		cout << ans[i].first + 1 << " " << ans[i].second + 1 << endl;
	}
}

