#define FIO ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
typedef pair<int, int> PII;

vector<ll> adj[100005];
vector<pair<ll, ll> > ans;
ll dp[100005];

ll dfs(ll x, ll parent){
    dp[x] = 1;
    ll cnt = 0;
    for(ll i = 0 ; i < adj[x].size() ; i++){
        ll y = adj[x][i];
        if(y == parent){
            continue;
        }
        if(dp[y] == 1){
            cnt++;
            ans.push_back({x, y});
        }else if(dp[y] == 0){
            cnt += dfs(y, x);
        }
    }
    dp[x] = -1;
    if(parent == -1){
        return (ll)0;
    }
    if(cnt%2){
        ans.push_back({x, parent});
        cnt = 0;
    }else{
        ans.push_back({parent, x});
        cnt = 1;
    }
    return cnt;
}

int main(){
    FIO;
    ll n, m;
    cin >> n >> m;

    for(ll i = 0 ; i <= n ; i++){
        dp[i] = 0;
    }
    for(ll i = 0 ; i < m ; i++){
        ll x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    if(m%2){
        cout << "-1" << endl;
        return 0;
    }
    dfs((ll)1, -1);
    for(ll i = 0 ; i < m ; i++){
        cout << ans[i].first << " " << ans[i].second << endl;
    }
    return 0;
}

