        cout << -1 << endl;
        return 0;
    }
    REP(i, m){
        cin >> a[i] >> b[i];
        a[i]--, b[i]--;
        Graph[a[i]].emplace_back(b[i]);
        Graph[b[i]].emplace_back(a[i]);
    }
    UnionFind uf(n);
    REP(i, m){
        if(uf.same(a[i], b[i]))continue;
        uf.unite(a[i], b[i]);
        Tree[a[i]].emplace_back(b[i]);
        Tree[b[i]].emplace_back(a[i]);
    }
    REP(i, n)d[i] = HINF<int>();
    d[0] = 0;
    queue<int> q;
    q.push(0);
    while(!q.empty()){
        int p = q.front();
        q.pop();
        for(auto to : Tree[p]){
            if(d[to] != HINF<int>())continue;
            d[to] = d[p] + 1;
            q.push(to);
        }
    }
    vector<int> order(n);
    REP(i, n)order[i] = i;
    sort(ALL(order), _order);
    vector<pair<int, int>>ans;
    for(auto cur : order){
