bool ancestor(int v, int u) {
    return tin[v] <= tin[u] && tout[v] >= tout[u];
}

int get_lca(int v, int u) {
    if (ancestor(v,u)) return v;
    if (ancestor(u,v)) return u;
    for (int i=19;i>-1;i--) {
        if (!ancestor(up[v][i],u)) v = up[v][i];
    }
    return up[v][0];
}

void query(int v, int u){
