template<class T = lint>
struct Edge {
	int to;
	Edge(int to) : to(to){}
};

vector<pair<int, int>> ans;
bool dfs(vector<vector<Edge<int>>> &edge, map<pair<int,int>, int> &mat, int now, vector<int> visited, int N) {

	visited[now] = 1;

	int cnt = 0, two = 0;
	for (const auto &e : edge[now]) {
		if (mat[make_pair(now, e.to)] == 2) two++;
		if (mat[make_pair(now, e.to)] == 1) cnt++;
	}

	bool flag = true;
	if (two == 0 && cnt % 2 != 0) flag = false;
	else {
		int cnt2 = cnt % 2;
		vector<int> memo;
		for (const auto &e : edge[now]){
			if (mat[make_pair(now, e.to)] == 2) {
				if (cnt2 > 0) {
					mat[make_pair(now,e.to)] = 1;
					ans.emplace_back(now, e.to);
					mat[make_pair(e.to, now)] = -1;
					cnt2--;
				}
				else {
					mat[make_pair(now, e.to)] = -1;
					mat[make_pair(e.to, now)] = 1;
					ans.emplace_back(e.to, now);
				}
			}
			memo.emplace_back(e.to);
		}
		for (const auto &e : memo) if (!visited[e]) {
			visited[e] = 1;
			flag &= dfs(edge, mat, e, visited, N);
		}
	}

	return flag;

}

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;

	int u, v;
	map<pair<int,int>,int> mat;
	vector<vector<Edge<int>>> edge(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		edge[u - 1].emplace_back(v - 1);
		edge[v - 1].emplace_back(u - 1);
		mat[make_pair(u - 1, v - 1)] = 2;
		mat[make_pair(u - 1, v - 1)] = 2;
	}

	if (dfs(edge, mat, 0, vector<int>(N), N)) {
		for (const auto &e : ans) {
			cout << e.first + 1 << " " << e.second + 1 << "\n";
		}
	}
	else cout << "-1\n";

	return 0;
}

