const int MxN = (int) 1e5 + 9;
vector<int> adj[MxN + 9];
int deg[MxN + 9];
multiset<pair<int, int>> res;
bool vis[MxN + 9];

void flip(const int u, const int v) {
	pair<int, int> p = { u, v };
	if (!res.count(p))
		swap(p.first, p.second);
	assert(res.count(p));

	--deg[p.first];
	assert(deg[p.first] >= 0);
	res.erase(res.find(p));
	swap(p.first, p.second);
	res.insert(p);
	++deg[p.first];
}

void dfs(const int u) {
	vis[u] = true;
	for (const int v : adj[u])
		if (!vis[v]) {
			dfs(v);
			if (deg[v] & 1)
				flip(u, v);
		}
}

int main() {
	ios::sync_with_stdio(false);
