		int u, v;
		cin >> u >> v;
		res.insert( { u, v });
		++deg[u];
		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	assert((int)res.size() == m);

	dfs(1);
	assert(m % 2 == deg[1] % 2);

	assert(res.size() == m);
	if (deg[1] % 2) {
		cout << -1;
		return 0;
	}
	for (auto p : res)
		cout << p.first << ' ' << p.second << '\n';
	return 0;
}

