int main() {
	RF("input.txt");
	// WF("output.txt");
	DF("err.txt");

	int N, M;
	scanf("%d %d", &N, &M);
	if (M & 1) return puts("-1"), 0;
	while (M--) {
		int a, b;
		scanf("%d %d", &a, &b);
		G[a].push_back(b);
		G[b].push_back(a);
		deg[a]++, deg[b]++;
	}
	priority_queue <PII> PQ;
	for (int v = 1; v <= N; v++) PQ.push(MP(-deg[v], v));
	vector <PII> res;
	while (!PQ.empty()) {
		int vdeg = -PQ.top().X;
		int u = PQ.top().Y;
		PQ.pop();
		if (visited[u]) continue;
		visited[u] = true;
		int edge_idx = 0;
		for (; edge_idx < G[u].size() and (outdeg[u] & 1); edge_idx++) {
			int v = G[u][edge_idx];
			if (!visited[v]) {
				res.emplace_back(u, v);
				outdeg[u]++;
				deg[u]--, deg[v]--;
			}
		}
		for (; edge_idx < G[u].size(); edge_idx++) {
			int v = G[u][edge_idx];
			if (!visited[v]) {
				res.emplace_back(v, u);
				deg[u]--, deg[v]--;
				outdeg[v]++;
			}
		}
	}
	for (PII ab : res) printf("%d %d\n", ab.X, ab.Y);
