}
int pa(int x)
{
  return x==p[x]?x:p[x]=pa(p[x]);
}
bool merge(int x, int y)
{
  x = pa(x), y = pa(y);
  if (x != y)
    {
      p[x] = y;
      return true;
    }
  return false;
}
