{
  for (auto nxt : g[cur])
    if (nxt != p)
      dfs(nxt, cur);
  if ((cnt[cur]%2) == 1)
    {
      assert(p);
      answer(cur, p);
    }
  else
    {
      if (p) answer(p, cur);
    }
}

