const int INF = int(1e9 + 7);


int main() {
	int N, M;
	cin >> N >> M;

	vector<vector<Pii>> node(N);
	vector<Pii> edge(M);
	Vi num_edge(N);

	for (int i = 0; i < M; ++i) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		edge[i] = make_pair(a, b);
		node[a].emplace_back(b, i * 2);
		node[b].emplace_back(a, i * 2 + 1);
		++num_edge[a];
		++num_edge[b];
	}

	if (M % 2 != 0) {
		cout << -1 << endl;
		return 0;
	}

	Vi cond(N);
	Vi bdir(M);

	stack<int> stk;
	stk.push(0);
	while (!stk.empty()) {
		int u = stk.top();
		stk.pop();
		for (const auto& vpair : node[u]) {
			int v = vpair.first;
			int iv = vpair.second;


			int is_first;
			if (iv % 2 == 0) {
				is_first = 1;
			}
			else {
				is_first = -1;
			}
			iv = iv / 2;


			if (bdir[iv] != 0) {
				continue;
			}
			if (num_edge[v] == 0) {
				continue;
			}

			if (num_edge[u] == 1 && cond[u] % 2 == 0) {
				if (num_edge[v] == 1 && cond[v] % 2 == 0) {
					continue;
				}
				else {
					bdir[iv] = -1 * is_first;
					++cond[v];
					--num_edge[u];
					--num_edge[v];
					stk.push(v);
					continue;
				}
			}

			if (num_edge[v] == 1) {
				if (cond[v] % 2 != 0) {
					bdir[iv] = -1 * is_first;
					++cond[v];
					--num_edge[u];
					--num_edge[v];
					stk.push(v);
					continue;
				}
			}

			bdir[iv] = 1 * is_first;
			++cond[u];
			--num_edge[u];
			--num_edge[v];
			stk.push(v);
		}
	}

	for (int i = 0; i < M; ++i) {
		int fst = edge[i].first;
		int scd = edge[i].second;
		++fst; ++scd;

		if (bdir[i] == 1) {
			cout << 0 << " " << 0 << endl;
		}
		else if (bdir[i] == -1) {
			cout << 0 << " " << 0 << endl;
		}
	}
}

