const int N = 1e5+5;
int n, m;
int u[N], v[N], visited[N], visited_ans[N];
vector<int> adj[N];
vector<pair<int,int> > ans;
bool deg[N];
map<pair<int,int>,int> mp;

void dfs(int u, int p)
{
    visited[u] = 1;
    for (auto v: adj[u])
    {
        if (v == p || visited[v]) continue;
        mp[{u,v}] = mp[{v,u}] = 1;
        dfs(v,u);
    }
}

void dfs_ans(int u, int p)
{
    visited_ans[u] = 1;
    if (adj[u].size() == 1 && u != 1)
    {
        if (deg[u]&1)
        {
            ans.push_back({u,p});
            deg[u]^=1;
        }
        else
        {
            ans.push_back({p,u});
            deg[p]^=1;
        }
        return;
    }
    for (auto v: adj[u])
    {
        if (v == p || visited_ans[v]) continue;
        dfs_ans(v,u);
    }
    if (u != 1)
    {
        if (deg[u]&1)
        {
            ans.push_back({u,p});
            deg[u]^=1;
        }
        else
        {
            ans.push_back({p,u});
            deg[p]^=1;
        }
    }
}

int main()
{
    cin >> n >> m;
    if (m&1) return cout << -1,0;
    for (int i = 0; i < m; i++)
    {
        cin >> u[i] >> v[i];
        adj[u[i]].push_back(v[i]);
        adj[v[i]].push_back(u[i]);
    }
    dfs(1,1);
    for (int i = 0; i < m; i++)
    {
        if (!mp[{u[i],v[i]}])
        {
            ans.push_back({u[i],v[i]});
            deg[u[i]] ^= 1;
        }
    }
    dfs_ans(1,1);
    for (auto p: ans)
        cout << p.first << ' ' << p.second << endl;
}

