bool come[108000];

int dfs(int x, int last = -1){
    int cnt = 0;
    come[x] = true;
    vector<P> tmp;
    for(auto to:edge[x]){
        if(to == last)continue;
        if(come[to])ans.push_back(P(x, to));
        else tmp.push_back(P(x, to));
        cnt += dfs(to, x);
    }
    for(auto p:tmp){
        if(cnt % 2 == 0)ans.push_back(p);
        else{
            swap(p.first, p.second);
            ans.push_back(p);
        }
    }
    return cnt + (edge[x].size() % 2);
}

