	const int N = 1e5 + 5;
	set <int> adj[N];
	set <pii> heap;
	int n,m;
	vector <pii> ans;

    void solve(){
    	cin>>n>>m;
    	for(int i = 1;i <= n;++i){
    		int u,v;
    		cin>>u>>v;
    		adj[u].insert(v),adj[v].insert(u);
    	}
    	for(int u = 1;u <= n;++u){
    		heap.insert(mp(sz(adj[u]),u));
    	}
    	while(!heap.empty()){
    		while(!heap.empty() and heap.begin() -> fir < 2){
    			heap.erase(heap.begin());
    		}
    		if(heap.empty())break;
    		pii top = *heap.begin();
    		heap.erase(heap.begin());
    		int u = top.sec,t = top.fir;
    		if(t & 1)--t;
    		vector <int> ve;
    		for(auto v : adj[u]){
    			if(!t)break;
    			ve.emp(v);
    			ans.emp(mp(u,v));
    			heap.erase(mp(sz(adj[v]),v));
    			adj[v].erase(u);
    			heap.insert(mp(sz(adj[v]),v));
    			--t;
    		}
    		for(int i = 0;i < sz(ve);++i){
    			int v = ve[i];
    			if(adj[u].empty())break;
    			adj[u].erase(adj[u].find(v));
    		}
    		heap.insert(mp(sz(adj[u]),u));
    	}
    	for(int u = 1;u <= n;++u){
    		if(sz(adj[u]) > 0){
    			cout<<-1,exit(0);
    		}
    	}
    	for(auto res : ans){
    		cout<<res.fir<<' '<<res.sec<<'\n';
    	}
    }
}

