vector<ll> depth,cnt;
vector<pll> ans;

void dfs(ll u,ll p){
  for(auto &v:edge[u]){
    if(v==p){continue;}
    else if(depth[v]<depth[u]){
      cnt[u]++;
      ans.push_back({u,v});
      continue;
    }
    if(depth[v]!=-1){
      continue;
    }
    depth[v]=depth[u]+1;
    dfs(v,u);
  }
  if(cnt[u]&1){
    cnt[u]++;
    ans.push_back({u,p});
  }
  else if(p!=-1){
    cnt[p]++;
    ans.push_back({p,u});
  }
}

