class Dinic {
public:
struct edge {
	int a, b, cap, flow;
};
int dinic_src, dinic_dest; vector<int> d, ptr, q;
vector<edge> dinic_edge;
vector<vector<int> > dinic_graph;
int maxn=0;
void set_maxn(int n) {maxn=n;}
void add_edge (int a, int b, int cap) {
	//printf("%lld->%lld:%lld\n",a,b,cap);
	chkmax(maxn, a+1); chkmax(maxn, b+1);
	if (dinic_graph.size() < maxn) dinic_graph.resize(maxn);
	edge e1 = { a, b, cap, 0 };
	edge e2 = { b, a, 0, 0 };
	dinic_graph[a].push_back ((int) dinic_edge.size());
	dinic_edge.push_back (e1);
	dinic_graph[b].push_back ((int) dinic_edge.size());
	dinic_edge.push_back (e2);
}

bool dinic_bfs() {
	int qh=0, qt=0;
	q[qt++] = dinic_src;
	fill(d.begin(),d.end(),-1);
	d[dinic_src] = 0;
	while (qh < qt && d[dinic_dest] == -1) {
		int v = q[qh++];
		for (size_t i=0; i<dinic_graph[v].size(); ++i) {
			int id = dinic_graph[v][i],
				to = dinic_edge[id].b;
			if (d[to] == -1 && dinic_edge[id].flow < dinic_edge[id].cap) {
				q[qt++] = to;
				d[to] = d[v] + 1;
			}
		}
	}
	return d[dinic_dest] != -1;
}

int dinic_dfs (int v, int flow) {
	if (!flow)  return 0;
	if (v == dinic_dest)  return flow;
	for (; ptr[v]<(int)dinic_graph[v].size(); ++ptr[v]) {
		int id = dinic_graph[v][ptr[v]],
			to = dinic_edge[id].b;
		if (d[to] != d[v] + 1)  continue;
		int pushed = dinic_dfs (to, min (flow, dinic_edge[id].cap - dinic_edge[id].flow));
		if (pushed) {
			dinic_edge[id].flow += pushed;
			dinic_edge[id^1].flow -= pushed;
			return pushed;
		}
	}
	return 0;
}

int dinic(int src, int dest) {
	if (src==dest) return INF;
	chkmax(maxn,src+1); chkmax(maxn,dest+1);
	dinic_graph.resize(maxn);
	d.resize(maxn); ptr.resize(maxn); q.resize(maxn);
	dinic_src = src;
	dinic_dest = dest;
	int flow = 0;
	for (;;) {
		if (!dinic_bfs())  break;
		fill(ptr.begin(),ptr.end(),0);
		while (int pushed = dinic_dfs (dinic_src, INF))
			flow += pushed;
	}
	return flow;
}

void dinic_clear() {
	dinic_edge.clear();
	dinic_graph.clear();	
}
};



