const int MAX_N = 100 * 1000, MAX_M = 100 * 1000;
vector<int> adjLis[MAX_N + 1];
bitset<MAX_N + 1> markVer, EdgeDir[MAX_N + 1], isOddDeg;
stack<int> path;

void dfs1(int v) {
    markVer[v] = true;
    int u;
    for (int i = 0; i < adjLis[v].size(); i++) {
        u = adjLis[v][i];
        if (!EdgeDir[v][u] and !EdgeDir[u][v]) {
            EdgeDir[u][v] = false;
            EdgeDir[v][u] = true;
            isOddDeg[v] = !isOddDeg[v];
        }
        if (!markVer[u])
            dfs1(u);
    }
}

void dfs2(int v) {
    markVer[v] = true;
    int u;
    if (isOddDeg[v]) {
        path.push(v);
        if (path.size() > 1) {
            isOddDeg[v] = false;
            int w;
            while (path.size() > 1) {
                u = path.top();
                path.pop();
                w = path.top();
                EdgeDir[u][w] = !EdgeDir[u][w];
                EdgeDir[w][u] = !EdgeDir[w][u];
            }
            isOddDeg[w] = false;
            path.pop();
        }
    } else if (!path.empty())
        path.push(v);
    for (int i = 0; i < adjLis[v].size(); i++) {
        u = adjLis[v][i];
        if (!markVer[u])
            dfs2(u);
    }
}

