#include <iostream>
#include <vector>
#include <set>
using namespace std;

const int N = 1e5;
vector<int> conns[N];
int side[N];

bool dfs(int i) {
	bool succ = true;
	for (auto t : conns[i]) {
		if (side[t] == 0) {
			side[t] = -side[i];
			succ &= dfs(t);
		} else if (side[t] == side[i]) succ = false;
	}
	return succ;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n, m;
	cin >> n >> m;
	for (int j = 0; j < m; ++j) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		conns[a].push_back(b);
		conns[b].push_back(a);
	}

	// Take any valid solution, add auxiliary node, and add edges from auxiliary node to all odd degree nodes.
	// Now every node has both an even number of in-edges and an even number of odd-edges. Form euler tour,
	// and divide nodes along it into even and odd sides. Note that all edges appear in the tour, and distance
	// between reappearances of nodes is always even. Therefore, the graph is bipartite and all
	// odd-degree nodes are on the same side.

	side[0] = 1;
	bool fail = !dfs(0);

	if (! fail) {
		int odd_side = 0;
		for (int i = 0; i < n; ++i) {
			if (conns[i].size() & 1) {
				if (odd_side == 0) odd_side = side[i];
				else if (odd_side != side[i]) fail = true;
			}
		}
		if (! fail) {
			if (odd_side == 0) odd_side = -1;
			for (int i = 0; i < n; ++i) {
				if (side[i] == odd_side) {
					for (auto t : conns[i]) cout << t+1 << ' ' << i+1 << '\n';
				}
			}
		}
	}
	if (fail) {
		cout << "-1\n";
	}
}

