	int maxrank = 0;
	//rankごとに頂点を分類していく
	for (int i = 0; i < n; i++)
	{
		rnk[r[i]].pb(i);
		maxs(maxrank,r[i]);
	}
	//一番深い頂点から順番に見ていく
	for (int i = maxrank; i >= 2; i--) {
		for (int j = 0; j < rnk[i].size(); j++)
		{
			int x = rnk[i][j];
			if (edgenum[x] % 2 == 0) {
