using namespace std;

typedef long long int Int;

int N,M;
bool visited[N_MAX];
vector<int> G[N_MAX];
vector<pair<int,int> > Edge;
vector<pair<int,int> > show_node;
int deg_counter[N_MAX];

class UnionFind {
    private:
        int par[N_MAX];
        int rank[N_MAX];
    public:
        UnionFind(int n) {
            for(int i = 1;i <= n;i++) {
                par[i] = i;
                rank[i] = 0;
            }
        }

        int root(int x) {
            return x == par[x] ? x : par[x] = root(par[x]);
        }

        bool same(int x,int y) {
            return root(x) == root(y);
        }

        void merge(int x,int y) {
            x = root(x);
            y = root(y);
            if(x == y)
                return;

            if(rank[x] < rank[y])
                par[x] = y;
            else {
                par[y] = x;
                if(rank[x] == rank[y])
                    rank[x]++;
            }
        }
};

void dfs(int prev, int current) {
    visited[current] = true;
    for(int i = 0;i < G[current].size();i++) {
        int u = G[current][i];
        if(visited[u])
            continue;
        dfs(current,u);
    }

    if(deg_counter[current] % 2 == 1) {
        show_node.push_back(make_pair(current,prev));
        deg_counter[current]++;
    } else {
        deg_counter[prev]++;
        show_node.push_back(make_pair(prev,current));
    }

    return;
}

void solve(void) {
    UnionFind ut(N);

    vector<pair<int,int> > left;
    for(int i = 0;i < M;i++) {
        int x = Edge[i].first;
        int y = Edge[i].second;
        if(ut.same(x,y)) {
            left.push_back(make_pair(x,y));
        } else {
            ut.merge(x,y);
            G[x].push_back(y);
            G[y].push_back(x);
        }
    }

    for(int i = 0;i < left.size();i++) {
        int u = left[i].first;
        int v = left[i].second;
        show_node.push_back(make_pair(u,v));
        deg_counter[u]++;
    }

    visited[1] = true;
    for(int i = 0;i < G[1].size();i++) {
        int v = G[1][i];
        if(visited[v])
            continue;
        dfs(1, v);
    }

    for(int i = 0;i < show_node.size();i++) {
        cout<<show_node[i].first<<" "<<show_node[i].second<<endl;
    }

    return;
}
int main(void) {
    cin>>N>>M;

    for(int i = 0;i < M;i++) {
        int a,b;
        cin>>a>>b;
        Edge.push_back(make_pair(a,b));
    }

    if(M % 2 == 1) {
        cout<<-1<<endl;

        return 0;
    }

    solve();

    return 0;
}

