class Solution {
public:
	void solve() {
		scanf("%d %d", &N, &M);
		if (M & 1) {
			puts("-1");
			return;
		}
		boss = vector <int>(N + 1);
		for (int i = 1; i <= N; i++) boss[i] = i;

		G = vector <vector <int>>(N + 1, vector <int>());
		outdeg = vector <int>(N + 1, 0);
		while (M--) {
			int a, b;
			scanf("%d %d", &a, &b);
			if (find(a) != find(b)) {
				G[a].push_back(b);
				G[b].push_back(a);
				boss[find(a)] = find(b);
			}
			else {
				printf("%d %d\n", a, b);
				outdeg[a] ^= 1;
			}
		}
		visited = vector <bool>(N + 1, false);
		DFS(1, 1);
	}

protected:
	void DFS(int u, int father) {
		visited[u] = true;
		for (int v : G[u]) if (!visited[v] and v != father) DFS(v, u);
		if (u != father) {
			if (outdeg[u] & 1) {
				printf("%d %d\n", u, father);
				outdeg[u] ^= 1;
			}
			else {
				printf("%d %d\n", father, u); 
				outdeg[father] ^= 1;
			}
		}
	}

	int find(int x) {
		return boss[x] = (boss[x] == x ? x : find(boss[x]));
	}

private:
	int N, M;
	vector <int> boss;
	vector <vector <int>> G;
	vector <int> outdeg;
	vector <bool> visited;
};
