struct Edge{
  int from;
  int to;
  long cost;
  int start;
};

void update(int i){
  i += N-1;
  while(i > 0){
    i = (i-1)/2;
    pii c1 = value.at(i*2 + 1);
    pii c2 = value.at(i*2 + 2);
    if(c1.first < c2.first) value.at(i) = c1;
    else value.at(i) = c2; 
  }
}

pii query(int a, int b, int k, int l, int r){
  if(r <= a || b <= l) return pii(1e8,1e8);
  if(a <= l && r <= b) return value.at(k);
  else{
    pii c1 = query(a, b, 2*k+1, l, (l+r)/2);
    pii c2 = query(a, b, 2*k+2, (l+r)/2, r);
    if(c1.first < c2.first) return c1;
    else return c2;
  }
}

int main(){
  int n,m;
  cin >> n >> m;
  if(m % 2 == 1){
    cout << -1 << endl;
    return 0;
  }
  vector<vector<Edge>> Graph(n);
  N = 1;
  while(N < n) N *= 2;
  value = vector<pii>(2*N - 1, pii(1e8,1e8));
  is_even = vector<bool>(n, true);
  rep(i,m){
    int a,b;
    cin >> a >> b;
    a--;b--;
    Graph.at(a).push_back({a,b,1,-1});
    Graph.at(b).push_back({b,a,1,-1});
  }
  rep(i,n){
    value.at(i+N-1) = pii(Graph.at(i).size(), i);
  }
  rep(i,n){
    update(i);
  }
  int stop = 1000;
  while(stop){
    //rep(i,value.size()){
    //cout << value.at(i).first << " @ " << value.at(i).second << endl;
  //}
    //rep(i,n) cout << is_even.at(i) << endl;
    //cout << endl;
    pii mini = query(0, n, 0, 0, N);
    if(mini.first == 1e8) break;
    //cout << mini.first << " # " << mini.second << endl;
    int v = mini.second;
    bool rest_even = (mini.first % 2 == 0);
    bool adjust = (is_even.at(v) ^ rest_even);

    for(Edge &ed : Graph.at(v)){
      int nv = ed.to;
      if(value.at(nv+N-1).first == 1e8) continue;

      if(adjust){
        ed.start = nv;
        is_even.at(nv) = !is_even.at(nv);
        adjust = false;
      }else{
        if(ed.start != -1) continue;
        ed.start = v;
        is_even.at(v) = !is_even.at(v);
