      value.at(v+N-1).first--;
      if(value.at(v+N-1).first == 0) value.at(v+N-1).first = 1e8;
      update(v);
      value.at(nv+N-1).first--;
      if(value.at(nv+N-1).first == 0) value.at(nv+N-1).first = 1e8;
      update(nv);
    }
    stop--;
