      }
    }
  }
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Edge {
    int to;
    int use;
};

vector<map<int, Edge>> G;
vector<int> depth, odd, pa;

int main() {
    ll N, M;
    cin >> N >> M;
    G.resize(N);
    ll a, b;
    for ( int i = 0; i < M; i++ ) {
        cin >> a >> b;
        a--, b--;
        G[a][b] = Edge{b,1};
        G[b][a] = Edge{a,0};
    }
    depth.assign(N, -1);
    odd.assign(N, 0);
    pa.assign(N, -1);

    queue<int> q;
    q.push(0);
    depth[0] = 0;
    while ( !q.empty() ) {
        auto v = q.front();
        q.pop();

        int no = 0;
        for( auto ee : G[v] ) {
            auto e =  ee.second;
            if ( e.use == 1 ) no++;
            if ( depth[e.to] >= 0) continue;
            pa[e.to] = v;
            depth[e.to] = depth[v] + 1;
            q.push(e.to);
        }
        odd[v] = no % 2;
    }

    int oc = 0;
    for ( int i = 0; i < N; i++ ) {
        if ( odd[i] == 1 ) oc++;
    }
    if ( oc % 2 == 1 )  {
        cout << -1 << "\n";
        return 0;
    }

    priority_queue<pair<int, int>> pq;
    for ( int i = 0; i < N; i++ ) {
        pq.push(make_pair(depth[i], i));
    }

    while ( !pq.empty() ) {
        auto x = pq.top();
        pq.pop();
        int v = x.second;
        if ( pa[v] == -1 ) {
            if ( odd[v] == 1 ) {
                cout << -1 << "\n";
                return 0;
            } else {
                break;
            }
        }

        if ( odd[v] == 1 ) {
            G[v][pa[v]].use = 1 - G[v][pa[v]].use;
            G[pa[v]][v].use = 1 - G[pa[v]][v].use;
            odd[v] = 1 - odd[v];
            odd[pa[v]] = 1 - odd[pa[v]];
        }
    }

    for ( int i = 0; i < N; i++ ) {
        for ( auto g : G[i] ) {
            auto e = g.second;
            if ( e.use == 1 ) {
                cout << i+1 << " " << e.to+1 << "\n";
            }
        }
    }
    return 0;
}

