vector<int> TopologicalSort(const Graph& graph) {
	int V = graph.size();
	vector<bool> visited(V);
	vector<int> ret;
	function<void(int)> dfs = [&](int u) {
		if (visited[u])return;
		visited[u] = true;
		for (auto& i : graph[u])dfs(i.to);
		ret.push_back(u);
	};
	for (int i = 0; i < V; i++)dfs(i);
	reverse(ret.begin(), ret.end());
	return ret;
}

tuple<vector<int>, vector<pair<int, int>>> SpanningTree(const UnWeightedGraph& g, int root) {
	const int V = g.size(), nil = -2;
	vector<int> parent(V, nil);
	parent[root] = -1;
	VP depth(V); // (depth, index)
	for (int i = 0; i < V; ++i)
		depth[i].second = i;

	queue<int> q; q.push(root);
	while (!q.empty()) {
		int f = q.front(); q.pop();
		for (auto e : g[f]) {
			if (parent[e] == nil) {
				parent[e] = f;
				depth[e].first = depth[f].first + 1;
				q.push(e);
			}
		}
	}

	return { parent,depth };
}

int main() {
	int n = in, m = in;
	UnWeightedGraph g(n);
	vector<PII> edges(m);
	rep(i, m) {
		int a = in--, b = in--;
		g[a].pb(b);
		g[b].pb(a);
		edges[i] = mp(a, b);
	}

	if (m % 2 == 1) {
		out.exit(-1);
	}

	VI parent; VP depth;
	tie(parent, depth) = SpanningTree(g, 0);
	RSort(depth);

	VI cnt(n); VB used(m);
	rep(i, m) {
		auto e = edges[i];
		if (parent[e.first] != e.second && parent[e.second] != e.first) {
			out(e.first + 1, e.second + 1);
			used[i] = true;
			cnt[e.first]++;
		}
	}

	rep(i, n - 1) {
		int e = depth[i].second;
		if (cnt[e] % 2 == 0) {
			out(parent[e] + 1, e + 1);
			cnt[parent[e]]++;
		} else {
			out(e + 1, parent[e] + 1);
			cnt[e]++;
		}
	}
}

