using namespace std;

class UnionFind {
public:
	vector<int> par;

	void init(int sz) {
		par.resize(sz, -1);
	}
	int root(int pos) {
		if (par[pos] == -1) return pos;
		par[pos] = root(par[pos]);
		return par[pos];
	}
	void unite(int u, int v) {
		u = root(u); v = root(v);
		if (u == v) return;
		par[u] = v;
	}
	bool same(int u, int v) {
		if (root(u) == root(v)) return true;
		return false;
	}
};

int N, M, A[1 << 17], B[1 << 17], deg[1 << 17], pars[1 << 17]; bool used[1 << 17];
vector<int> X[1 << 17]; vector<pair<int, int>>G;
UnionFind UF;

void dfs(int pos) {
	used[pos] = true;

	for (int i = 0; i < X[pos].size(); i++) {
		if (used[X[pos][i]] == true) continue;
		pars[X[pos][i]] = pos;
		dfs(X[pos][i]);
	}
	if (pos != 1) {
		if (deg[pos] % 2 == 1) {
			G.push_back(make_pair(pos, pars[pos]));
			deg[pos] ^= 1;
		}
		else {
			G.push_back(make_pair(pars[pos], pos));
			deg[pars[pos]] ^= 1;
		}
	}
}

int main() {
	cin >> N >> M; UF.init(N + 2);
	if (M % 2 == 1) {
		cout << "-1" << endl;
		return 0;
	}
	for (int i = 1; i <= M; i++) {
		cin >> A[i] >> B[i];
		if (UF.same(A[i], B[i]) == false) {
			UF.unite(A[i], B[i]);
			X[A[i]].push_back(B[i]);
			X[B[i]].push_back(A[i]);
		}
		else {
			G.push_back(make_pair(A[i], B[i]));
			deg[A[i]] ^= 1;
		}
	}
	dfs(1);

	for (int i = 0; i < G.size(); i++) cout << G[i].first << " " << G[i].second << endl;
	return 0;
}

