set<pii> used;
vector<pii> finalEdges;
vi goingOut;
bool fail = false;

vector<bool> seen;

void dfs(int cur) {
	seen[cur] = true;
	for (int n : graph[cur]) if (!seen[n]) {
		used.insert(pii {min(cur, n), max(cur, n)});
		dfs(n);
	}
}

void calc(int cur, int par) {
	seen[cur] = true;
	for (int n : graph[cur]) if (!seen[n]) {
		calc(n, cur);
	}
	if (goingOut[cur] % 2 == 0) {
		if (par != -1) {
			finalEdges.push_back({par, cur});
			goingOut[par]++;
		}
	} else {
		if (par != -1) {
			finalEdges.push_back({cur, par});
			goingOut[cur]++;
		} else fail = true;
	}
}

