int main() {
	ll n, m;
	cin >> n >> m;
	if (m % 2) {
		cout << -1 << endl;
		return 0;
	}
	vector<pair<ll, ll>> ans;
	vector<bool> v(n, true);
	vector<set<ll>> g(n);
	set<ll> exist;
	for (ll i = 0; i < n; ++i)exist.insert(i);
	for (ll i = 0; i < m; ++i) {
		ll a, b;
		cin >> a >> b;
		--a; --b;
		g[a].insert(b);
		g[b].insert(a);
	}

	auto erase_edge = [&](auto&& erase_edge, ll i) -> void {
		ll a = *g[i].begin();
		g[i].erase(g[i].begin());
		g[a].erase(i);

		if (v[i]) {
			ans.push_back({ a,i });
			v[a] = !v[a];
		}
		else {
			ans.push_back({ i,a });
			v[i] = !v[i];
		}
		if (g[i].size() == 0)exist.erase(i);
		if (g[a].size() == 0)exist.erase(a);
		if (g[i].size() == 1)erase_edge(erase_edge, i);
		if (g[a].size() == 1)erase_edge(erase_edge, a);
	};

	for (ll i = 0; i < n; ++i) {
		if (g[i].size() == 1) {
			erase_edge(erase_edge, i);
		}
	}
	while (ans.size() < m) {
		erase_edge(erase_edge, *exist.begin());
	}

	if (exist.size() != 0)mle();
	bool flag = true;
	for (bool b : v)flag &= b;
	if (!flag)mle();

	//出力時に1-indexedに戻す
	for (auto p : ans) {
		cout << p.first + 1 << " " << p.second + 1 << endl;
	}
}

