};

struct Edge
{
	const int id_src, id_dst;
	Weight weight;

	Edge(const int id_src, const int id_dst, const Weight weight);
	Edge(const Edge &rhs);
};

struct Graph
{
	Vertices vertices;
	Edges edges;

	Graph(const int nvertices);
	Graph();
	Graph(const Graph &rhs);
	void add_edge(const Edge &edge);
	void add_edge(const int id_src, const int id_dst, const Weight w);
};

