using namespace std;

Vertex::Vertex(const int id) : id(id) {}
Vertex::Vertex(const Vertex &rhs) : id(rhs.id), edges(rhs.edges), ids_dst(rhs.ids_dst) {}
void Vertex::add_edge(const Edge &e)
{
	edges.push_back(e);
	ids_dst.push_back(e.id_dst);
}

Edge::Edge(const int id_src, const int id_dst, const Weight weight) : id_src(id_src), id_dst(id_dst), weight(weight) {}
Edge::Edge(const Edge &rhs) : id_src(rhs.id_src), id_dst(rhs.id_dst), weight(rhs.weight) {}
bool operator<(const Edge &e1, const Edge &e2)
{
	return e1.weight != e2.weight ? e1.weight > e2.weight : // !!INVERSE!!
			   e1.id_src != e2.id_src ? e1.id_src < e2.id_src : e1.id_dst < e2.id_dst;
}

Graph::Graph(const int nvertices)
{
	for (int id = 0; id < nvertices; id++)
		vertices.push_back(Vertex(id));
}
Graph::Graph() : Graph(0) {}
Graph::Graph(const Graph &rhs) : vertices(rhs.vertices), edges(rhs.edges) {}
void Graph::add_edge(const Edge &edge)
{
	edges.push_back(edge);
	vertices[edge.id_src].add_edge(edge);
}
void Graph::add_edge(const int id_src, const int id_dst, const Weight w = 1)
{
	add_edge(Edge(id_src, id_dst, w));
}

