using namespace std;
struct line{
	int u,v;
}l[100005];
int b[100005],use[100005];
int n,m,fa[100005];
int x,y;
int fir[100005],nxt[100005],to[100005],cnt;
int deg[100005],k[100005];
int fi[100005][20];
int t[100005],len;
int dep[100005];

int find(int x){
	if(x==fa[x]) return x;
	return fa[x]=find(fa[x]);
}

void kruskal(){
	for(int i=1;i<=m;i++){
		x=find(l[i].u);
		y=find(l[i].v);
		if(x==y) continue;
		if(x<y) fa[y]=x,to[++cnt]=l[i].v,nxt[cnt]=fir[l[i].u],fir[l[i].u]=cnt,deg[l[i].u]^=1,b[i]=0,k[l[i].v]=i;
		else fa[x]=y,to[++cnt]=l[i].u,nxt[cnt]=fir[l[i].v],fir[l[i].v]=cnt,deg[l[i].v]^=1,b[i]=1,k[l[i].u]=i;
		use[i]=1;
	}
	for(int i=1;i<=m;i++){
		if(use[i]==0) deg[l[i].u]^=1,b[i]=0;
	}
}

void dfs(int x,int f){
	fi[x][0]=f;
	dep[x]=dep[f]+1;
	for(int i=1;i<=19;i++) fi[x][i]=fi[fi[x][i-1]][i-1];
	for(int i=fir[x];i;i=nxt[i]){
		if(to[i]==f) continue;
		dfs(to[i],x);
	}
}

int LCA(int x,int y){
	if(dep[x]<dep[y]) swap(x,y);
	for(int i=19;i;i--){
		if(dep[fi[x][i]]>=dep[y]){
			x=fi[x][i];
		}
	}
	if(x==y) return x;
	for(int i=19;i;i--){
		if(fi[x][i]!=fi[y][i]){
			x=fi[x][i];
			y=fi[y][i];
		}
	}
	return fi[x][0];
}

void jump(int x,int y){
	if(x==y) return;
	b[k[x]]^=1;
	jump(fi[x][0],y);
}

int main(){
	scanf("%d %d",&n,&m);
	for(int i=1;i<=n;i++) fa[i]=i;
	for(int i=1;i<=m;i++){
		scanf("%d %d",&l[i].u,&l[i].v);
	}
	kruskal();
	for(int i=1;i<=n;i++){
		if(k[i]==0) dfs(i,0);
		if(deg[i]==1) t[++len]=i;
	}
	if(len&1) printf("-1\n");
	else{
		for(int i=1;i<=len;i+=2){
			int lca=LCA(t[i],t[i+1]);
			jump(t[i],lca);
			jump(t[i+1],lca);
		}
		for(int i=1;i<=m;i++){
			if(b[i]==1) printf("%d %d\n",l[i].v,l[i].u);
			else printf("%d %d\n",l[i].u,l[i].v);
		}
	}

	return 0;
}

