class EulerTour{
    public:
	int cnt;
	vector<int> first,last,used;
	vector<vector<int> > g;
	EulerTour(int n) : g(n),first(n),last(n),used(n){}
	void add(int u, int v) {
		g[u].push_back(v);
		g[v].push_back(u);
	}
	void build(){
		cnt = 0;
		dfs(0);
	}
	void dfs(int v){
        used[v] = true;
		first[v] = cnt++;
		for(int to : g[v]){
			if(!used[to]) dfs(to);
		}
		last[v] = cnt++;
	}
	P get(int v){
		return mp(first[v],last[v]);
	}
};

class RSQ{
	int n,seg,init;
	vector<int> dat;
public:
	RSQ(int siz,int def) : n(siz),init(def),seg(1){
		while(seg < n) seg *= 2;
		dat.resize(seg * 2 - 1);
		for(int i = 0;i < seg * 2 - 1;i++) dat[i] = init;
	}
	void add(int i,int x){
		i += seg - 1;
		dat[i] = x;
		while(i){
			i = (i - 1) / 2;
			dat[i] = dat[i * 2 + 1] + dat[i * 2 + 2]; //do
		}
	}
	int get(int a = 0,int b = -1,int k = 0,int l = 0,int r = -1){
		if(b == -1) b = seg;
		if(r == -1) r = seg;
		if(b <= l || r <= a) return init;
		if(a <= l && r <= b) return dat[k];
		return get(a,b,k * 2 + 1,l,(l + r) / 2) + get(a,b,k * 2 + 2,(l + r) / 2,r); //do
	}
};

bool visited[100010];
int parEdge[100010];
map<P,int> edgeNum;

void dfs(int v,vector<vector<int>> &G){
    visited[v] = true;
    for(int to : G[v]){
        if(!visited[to]){
            parEdge[to] = edgeNum[P(v,to)];
            dfs(to,G);
        }
    }
}

signed main(){
	int n,m,out[100010] = {};
    cin >> n >> m;
    EulerTour euler(n);
    RSQ rsq(2 * n,0);
    vector<P> edges;
    for(int i = 0;i < n;i++) parEdge[i] = -1;
    for(int i = 0;i < m;i++){
        int a,b;
        cin >> a >> b; a--;b--;
        euler.add(a,b);
        edges.pb(P(a,b));
        edgeNum[P(a,b)] = i;
        edgeNum[P(b,a)] = i;
        out[a]++;
    }
    if(m % 2){
        cout << -1 << endl;
        return 0;
    }
    euler.build();
    dfs(0,euler.g);
    for(int i = 0;i < n;i++){
        if(out[i] % 2) rsq.add(euler.get(i).first,1);
    }
    for(int i = 0;i < n;i++){
        if(rsq.get(euler.get(i).first,euler.get(i).second) % 2 && parEdge[i] != -1){
