using namespace std;
typedef long long ll;

void dfs(const vector<vector<int>> &graph, vector<vector<int>> &g, vector<vector<int>> &ans, int now, vector<bool> &seen) {
	//cout << "now " << now << endl;

	while(g[now].size()>1) {
		int to = g[now][0];
		ans[now].push_back(to);
		g[now].erase(g[now].begin()+0);
		rep(i, g[to].size()) {
			if(g[to][i]==now) g[to].erase(g[to].begin()+i);
		}

		to = g[now][0];
		ans[now].push_back(to);
		g[now].erase(g[now].begin()+0);
		rep(i, g[to].size()) {
			if(g[to][i]==now) g[to].erase(g[to].begin()+i);
		}
	}
	seen[now] = true;
	rep(i, graph[now].size()) {
		int nv = graph[now][i];
		if(seen[nv]) continue;
		dfs(graph, g, ans, nv, seen);
	}

	return;
}

int main() {
	// input
	int N, M;
	cin >> N >> M;

	vector<vector<int>> graph(N);
	vector<vector<int>> g(N);
	rep(i, M) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		graph[a].push_back(b);
		graph[b].push_back(a);

		g[a].push_back(b);
		g[b].push_back(a);
	}

	vector<bool> seen(N, false);
	vector<vector<int>> ans(N);
	dfs(graph, g, ans, 0, seen);

	rep(i, N) {
		if(g[i].size()==1) {
			cout << -1 << endl;
			return 0;
		}
	}

	rep(i, N) {
		rep(j, ans[i].size()) {
			cout << i << ' ' << ans[i][j] << endl;
		}
	}
	return 0;
}

