		cout << -1 << "\n";
		return 0;
	}

	int u, v;
	map<pair<int,int>, int> dir;
	vector<vector<int>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		u--, v--;
		edge[u].emplace_back(v);
		edge[v].emplace_back(u);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	queue<int> que;
	RandNum ran;
	for (int i = 0; i < N; i++) {
		if (out[i] == 1) {
			que.emplace(i);
