		bool random = true;
		for (const auto &e : edge[now]) {
			if (out[e] == 1) {
				dir[{min(now, e), max(now, e)}] *= -1;
				out[now] ^= 1;
				out[e] ^= 1;
				random = false;
				break;
			}
		}

		if (random) {
			int next = edge[now][ran(edge[now].size())];
			dir[{min(now, next), max(now, next)}] *= -1;
			out[now] ^= 1;
			out[next] ^= 1;
			que.emplace(next);
		}

	}

