  vis[u] = true;

  while (q.size()) {
    int u = q.front();
    q.pop();

    bool first = true;
    for (int v: edges[u]) {

      if (used.count({u, v}) == 0) {
        if (deg[u] % 2 == 1 && first) {
          printf("%d %d\n", v+1, u+1);
