        } else {
          printf("%d %d\n", u+1, v+1);
          --deg[v];
        }

        used.insert({u, v});
        used.insert({v, u});
      }

      if (vis[v]) continue;
      vis[v] = true;

      q.push(v);
    }
  }
}

