bool orient_graph(int v, int from, int& ord, graph& g, vector<int>& nums, vector<pair<int,int>>& edges)
{
	//printf("visit %d\n", v);
	nums[v] = ord++;
	bool even = true;

	for(auto& w : g[v]) {
		if(nums[w] != -1) {
			if(nums[w] < nums[v] && w != from) {
				edges.push_back({v, w});
				//printf("orient %d -> %d\n", v, w);
				even = !even;
			}
			continue;
		}
		bool ch_even = orient_graph(w, v, ord, g, nums, edges);
		if(!ch_even) {
			edges.push_back({w, v});
		} else {
			edges.push_back({v, w});
			even = !even;
		}
	}

	return even;
}

