void dfs(int n, int pre) {
	for (auto nxt : G[n]) {
		if (pre == nxt)continue;
		dfs(nxt, n);
	}
	if (n != 0) {
		if (!(score[n] & 1)) {
			score[pre] ^= 1;
			ans.push_back({ pre,n });
		}
		else {
			ans.push_back({ n,pre });
		}
	}
}

void solve() {
