    vvi G(N);
    vi deg(N);
    rep(i, 0, M) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
        deg[a]++;
        deg[b]++;
    }

    if (M % 2) {
        cout << -1 << endl;
        return 0;
    }

    vector<pii> ans;
    vector<bool> vis(N);
    vector<int> out(N);
    set<pii> removed;

    set<pii> vs;

    auto dfs = [&](auto fun, int v) -> void {
        if (sz(G[v]) == 1) {
            ans.push_back({G[v][0], v});
            removed.insert({G[v][0], v});
            removed.insert({v, G[v][0]});
            out[G[v][0]]++;
            deg[v]--;
            deg[G[v][0]]--;
        }

        vis[v] = true;
        for (int w : G[v]) {
            if (vis[w]) continue;
            fun(fun, w);
        }
    };
    dfs(dfs, 0);

    rep(i, 0, N) {
        if (sz(G[i]) != 1) {
            vs.insert({deg[i], i});
        }
    }

    while (sz(vs)) {
        int d, v;
        tie(d, v) = *vs.begin();
        assert(d == deg[v]);
        vs.erase(vs.begin());
        for (int w : G[v]) {
            if (removed.count({v, w})) {
                continue;
            }
            if (out[v] % 2 == 0 && deg[v] % 2 == 1) {
                d--;
                ans.push_back({w, v});
                out[w]++;
            } else {
                ans.push_back({v, w});
                out[v]++;
            }
            removed.insert({v, w});
            removed.insert({w, v});
            vs.erase({deg[w], w});
            deg[w]--;
            vs.insert({deg[w], w});
            deg[v]--;
        }
    }

    rep(i, 0, sz(ans)) {
        cout << ans[i].first + 1 << " " << ans[i].second + 1 << endl;
    }
    return (0^_^0);
}

