#define BORDER  (10000000LL)

ll edge_id(ll v1, ll v2)
{
    ll m0 = min(v1, v2);
    ll m1 = max(v1, v2);
    return (m0 * BORDER) + m1;
}

void edge_to_v(ll edge, ll &v1, ll &v2)
{
    v1 = edge / BORDER;
    v2 = edge % BORDER;
}

