				e[i].p=1,e[i^1].p=-1,out[u]++;
			else
				e[i^1].p=1,e[i].p=-1;
		}
		else if(e[i].p==0&&to!=fa)
		{
			e[i].p=1;
			e[i^1].p=-1;
			out[u]++;
		}
	}
}
