int N, M;
vector<vector<int>> G;
vector<int> depth;
vector<int> deg;
using P = pair<int, int>;
vector<P> ans;

void dfs(int cur, int pre) {
    for(auto to : G[cur]) {
        if(depth[to] == -1) {
            depth[to] = depth[cur] + 1;
            dfs(to, cur);
        } else {
            if(depth[to] > depth[cur]) {
                ans.emplace_back(cur, to);
                deg[cur]++;
            }
        }
    }
    if(pre != -1) {
        if(deg[cur] % 2) {
            ans.emplace_back(cur, pre);
            deg[cur]++;
        } else {
            ans.emplace_back(pre, cur);
            deg[pre]++;
        }
    }
}

void solve() {
    depth.assign(N, -1);
    deg.resize(N);
    depth[0] = 0;
    dfs(0, -1);
    for(auto p : ans) cout << p.first + 1 << " " << p.second + 1 << '\n';
}

