    cin >> N >> M;
    G.resize(N);
    rep(i, 0, M) {
        int a, b; cin >> a >> b;
        a--, b--;
        G[a].push_back(b); G[b].push_back(a);
    }
    if(M % 2) cout << -1 << endl;
    else solve();
    return 0;
}

