set<int> bipart[NMAX];
set<int> odd_part;

map<pair<int, int>, bool> dir;

bool match()
{
	if (odd_part.size() < 2) return false;
	int start = *odd_part.begin();

	int middle = -1;
	for(auto &i : bipart[start])
	{
		if (bipart[i].size() >= 2)
		{
			middle = i;
			break;
		}
	}
	if (middle == -1) return false;

	auto it = bipart[middle].begin();
	if (*it == start) ++it;
	if (it == bipart[middle].end()) return false;

	int finish = *it;
	dir[mp(min(start, middle), max(start, middle))] ^= 1;
	dir[mp(min(finish, middle), max(finish, middle))] ^= 1;
	color[start] = color[finish] = even;
	odd_part.erase(start);
	odd_part.erase(finish);
	for(auto &i: graf[start])
	{
		if(color[i] == even)
		{
			bipart[i].erase(start);
			bipart[start].erase(i);
		}
		else
		{
			bipart[i].insert(start);
			bipart[start].insert(i);
		}
	}
	for(auto &i: graf[finish])
	{
		if(color[i] == even)
		{
			bipart[i].erase(finish);
			bipart[finish].erase(i);
		}
		else
		{
			bipart[i].insert(finish);
			bipart[finish].insert(i);
		}
	}
	return true;
}

void build_bipart()
{
	for1(i, n)
	{
		if (color[i] == even) continue;
		for(auto& j : graf[i]) if(color[j] == odd)
		{
			color[i] = even;
			color[j] = even;
			dir[mp(min(i, j), max(i, j))] ^= 1;
			break;
		}
	}
	for1(i, n)
	{
		if (color[i] == even) continue;
		for(auto& j: graf[i]) if(color[j] == even)
		{
			bipart[i].insert(j);
			bipart[j].insert(i);
		}
		odd_part.insert(i);
	}
}

bool trecut[NMAX];
int last_odd = -1;
V in_stack;
void dfs(int nod)
{
	trecut[nod] = 1;
	in_stack.pb(nod);
	if(color[nod] == odd)
	{
		if (last_odd == -1) last_odd = nod;
		else
		{
			for(int i = in_stack.size() - 1; i >= 0; i--)
			{
				if (color[in_stack[i]] == odd) color[in_stack[i]] = even;
				int l = in_stack[i], r = in_stack[i - 1];
				dir[mp(min(l, r), max(l, r))] ^= 1;
				if (last_odd == l || last_odd == r) break;
			}
			last_odd = -1;
		}
	}
	for(auto& i: graf[nod]) if(!trecut[nod])
	{
		dfs(i);
	}
	in_stack.pop_back();
}

