namespace G {
	int head[N], nxt[N*2], to[N*2], id[N*2], eid;
	void init() {
		eid = 0;
		memset(head, -1, sizeof head);
	}
	void link( int u, int v, int w ) {
		to[eid] = v, id[eid] = w, nxt[eid] = head[u], head[u] = eid++;
		to[eid] = u, id[eid] = w, nxt[eid] = head[v], head[v] = eid++;
	}
}

namespace DSU {
	int pa[N];
	void init() {
		for( int i = 0; i < N; ++i )
			pa[i] = i;
	}
	int find( int u ) {
		return u == pa[u] ? u : pa[u] = find( pa[u] );
	}
	bool link( int u, int v ) {
		u = find(u), v = find(v);
		if( u == v ) return false;
		return pa[u] = v, true;
	}
}

void dfs( int u, int fa, int w ) {
	using namespace G;
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		if( v == fa ) continue;
		dfs(v, u, id[i]);
	}
	if( deg[u] % 2 == 1 ) {
		flip[w] ^= 1;
		++deg[u], ++deg[fa];
	}
}

