void dfs(int v, int w, vector<int> &from)
{
  if (from[w] != -1)
  {
    return;
  }
  for (auto x : V[v])
  {
    if (from[x] == -1)
    {
      from[x] = v;
      dfs(x, w, from);
    }
  }
}

void make_path(int v, int w)
{
  vector<int> from(N, -1);
  dfs(v, w, from);
  v = from[w];
  while (v != -1)
  {
    edge e = edge(v, w);
    edge f = edge(w, v);
    if (rev.find(e) == rev.end())
    {
      rev.insert(e);
      rev.insert(f);
    }
    else
    {
      rev.erase(e);
      rev.erase(f);
    }
    w = v;
    v = from[w];
  }
}

void make_rev()
{
  for (auto i = 0u; i < pts.size(); i += 2)
  {
    int v = pts[i];
    int w = pts[i + 1];
    make_path(v, w);
  }
}

void solve()
{
  for (auto i = 0; i < N; i++)
  {
    Q.push(info(V[i].size(), i));
  }
  while (!Q.empty())
  {
    // int sz = get<0>(Q.top());
    int v = get<1>(Q.top());
    Q.pop();
    if (!visited[v])
    {
      visited[v] = true;
      for (auto x : V[v])
      {
        ans.push_back(edge(x, v));
        cnt[x]++;
        V[x].erase(v);
        Q.push(info(V[x].size(), x));
      }
      if (cnt[v] % 2 == 1)
      {
        if (V[v].empty())
        {
          pts.push_back(v);
        }
        else
        {
          auto it = ans.end();
          --it;
          cnt[get<0>(*it)]--;
          swap(get<0>(*it), get<1>(*it));
        }
      }
      V[v].clear();
    }
  }
  if (!pts.empty())
  {
    make_rev();
  }
}

