        for (int j : adj_list[i]) {
            if (dfs_num[i] < dfs_num[j]) {
                adj_list_2[i].push_back(j);
            }
        }
    }
    vector<int> edge_count(n, 0);
    function<void (int)> count_edges = [&](int i) {
        int count = (int)adj_list_2[i].size();
        for (int j : dfs_children[i]) {
            count_edges(j);
            count += edge_count[j];
        }
        edge_count[i] = count;
    };
    count_edges(0);
    set<pair<int, int>> reversed_edges;
    for (int i = 0; i < n; ++i) {
        for (int j : dfs_children[i]) {
            if (edge_count[j] % 2 == 1) {
                reversed_edges.insert(make_pair(i, j));
            }
        }
    }
    vector<pair<int, int>> result;
    for (int i = 0; i < n; ++i) {
        for (int j : adj_list_2[i]) {
            if (reversed_edges.find(make_pair(i, j)) == reversed_edges.end()) {
                result.push_back(make_pair(i, j));
            } else {
                result.push_back(make_pair(j, i));
            }
        }
    }
    for (auto edge : result) {
        cout << edge.first+1 << " " << edge.second+1 << "\n";
    }
    return 0;
}

