class UnionFind {
    public:
    int n;
    vector<int> par, rank, size;  //親, 深さ, その木の要素数

    UnionFind(int n): n(n) {
        for(int i=0;i<n;++i){
            par.push_back(i);
            rank.push_back(0);
            size.push_back(1);
        }
    }

    //根を求める
    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            int p = find(par[x]);
            size[x] = size[p];
            return par[x] = p;
        }
    }

    //xとyの属する集合の併合
    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        size[x] += size[y];
        size[y] = size[x];
        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }

    //同じ集合に属するか否か
    bool is_same(int x, int y){
        return find(x) == find(y);
    }
};

class Edge {
    public:
    int to, rev, is_used;
    Edge(int to, int rev, int is_used): to(to), rev(rev), is_used(is_used) {}
};

vector<Edge> graph[V_MAX];

namespace kruskal {
    class Edge {
        public:
        int from, to, idx;
        Edge(int from, int to, int idx): from(from), to(to), idx(idx) {}
    };

    vector<kruskal::Edge> edges;

    ll kruskal(int V){
        ll ret = 0LL;
        UnionFind uf = UnionFind(V);
        for(Edge &e: edges){
            if(uf.is_same(e.from, e.to)){
                graph[e.from][e.idx].is_used = -1;
                graph[e.to][graph[e.from][e.idx].rev].is_used = 0;
            } else {
                uf.unite(e.from, e.to);
            }
        }
        return ret;
    }
}

void dfs(int node, int par) {
    for(Edge &child_edge: graph[node]) {
        if(child_edge.to == par) continue;
        if(child_edge.is_used != 1 && graph[child_edge.to][child_edge.rev].is_used != 1) continue;
        dfs(child_edge.to, node);
        if(outdegree[child_edge.to] % 2) {
            child_edge.is_used = 1 - child_edge.is_used;
            graph[child_edge.to][child_edge.rev].is_used = 1 - graph[child_edge.to][child_edge.rev].is_used;
            outdegree[node] = 1-outdegree[node];
            outdegree[child_edge.to] = 1-outdegree[child_edge.to];
        }
    }
}

