int main()
{
    int N, M;
    cin >> N >> M;

    vector<set<int>> G(N);
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        G[a].insert(b);
        G[b].insert(a);
    }

    if (M % 2 != 0) {
        cout << "-1\n";
        return 0;
    }

    vector<set<int>> R(N);
    int added = 0;

    while (added < M) {
        vector<int> vr;
        for (int i = 0; i < N; ++i)
            vr.push_back(i);
        random_shuffle(vr.begin(), vr.end());

        bool changed = false;
        for (int i : vr) {
            int rest = G[i].size();
            int ex = R[i].size();

            if (rest == 1) {
                int j = *G[i].begin();
                if (ex % 2 == 0)
                    R[j].insert(i);
                else
                    R[i].insert(j);

                G[i].erase(j);
                G[j].erase(i);
                ++added;
                changed = true;
            }
        }

        if (!changed) {
            for (int i : vr) {
                int rest = G[i].size();
                int ex = R[i].size();

                if (rest == 0)
                    continue;
                assert(rest != 1);

                int outcnt = rest;
                if (((rest % 2) ^ (ex ^ 2)) == 1)
                    --outcnt;

                vector<int> torem;
                for (int j : G[i]) {
                    if (outcnt > 0)
                        R[i].insert(j);
                    else
                        R[j].insert(i);
                    --outcnt;
                    ++added;
                    torem.push_back(j);
                }

                for (int j : torem) {
                    G[i].erase(j);
                    G[j].erase(i);
                }
                break;
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j : R[i]) {
            cout << (i + 1) << ' ' << (j + 1) << '\n';
        }
    }

    return 0;
}

