void dfs(int id, int fr) {
	rep(j, G[id].size()) {
		int to = G[id][j];
		if (to == fr)continue;
		dfs(to, id);
	}
	if (fr >= 0) {
		if (c[id]) {
			ans.push_back({ id,fr });
		}
		else {
			ans.push_back({ fr,id });
			c[fr] ^= 1;
		}
	}
}
