	vector<bool> used(m, false);
	rep(i, m) {
		int a = v[i].first, b = v[i].second;
		if (u.same(a, b))continue;
		u.unite(a, b); used[i] = true;
		G[a].push_back(b); G[b].push_back(a);
	}
	rep(i, m) {
