signed main() {
	INIT;

	VAR(int, n, m);
	VEC_ROW(int, m, a, b);

	if (m % 2 == 1) {
		OUT(-1)BR;
		return 0;
	}

	std::vector<std::set<int>> g(n);
	V<int> in(n, 0);
	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].emplace(b[i]);
		g[b[i]].emplace(a[i]);
		++in[a[i]];
		++in[b[i]];
	}

	V<int> odd;
	REP(i, n) {
		if (g[i].size() % 2 == 1) {
			odd.emplace_back(i);
		}
	}

	if (odd.size() != 0 && odd.size() != 2) {
		OUT(-1)BR;
		return 0;
	}

	V<PAIR> ans;
	int now = 0;
	if (odd.size()) now = odd[0];
	while (ans.size() < m) {
		int x, y;
		for (auto to : g[now]) {
			if (g[to].size() > 1 || (ans.size() + 1 == m && g[to].size() == 1)) {
				x = now; y = to;
				break;
			}
		}
		ans.push_back({ x, y });
		g[x].erase(y);
		g[y].erase(x);
		now = y;
	}
	int cnt = 0;
	for (auto& p : ans) {
		if (cnt++ % 2 == 0) std::swap(p.first, p.second);
		OUT(p.first + 1)SP OUT(p.second + 1)BR;
	}

	return 0;
}

