void bubble_sort(long long int num[][2], long long int n){
    long long int temp1, temp2;
    for(long long int i=0; i<n-1; i++) {
        for(long long int j=n-1; j>i; j--){
            temp1 =0;
            temp2 =0;
            if(num[j-1][1] > num[j][1]) {
                temp1 = num[j][0];
                temp2 = num[j][1];
                num[j][0] = num[j-1][0];
                num[j][1] = num[j-1][1];
                num[j-1][0] = temp1;
                num[j-1][1] = temp2;
            }
        }
    }
}

int vector_finder(vector<long long int> vec,long long int number) {
  auto itr = std::find(vec.begin(), vec.end(), number);
  size_t index = distance( vec.begin(), itr );
  if (itr != vec.end()) {
      //cout << "fount " << endl;
    return index;
  }
  else {
      //cout << "not fount " << endl;
    return -1;
  }
}

