int dfs(int v){
	used[v] = 1;
	int deg = 0;
	for(int x:gr[v]){
		if(used[x]==1)continue;
		if(used[x]==2 || !dfs(x)){	
			cout<<(v)<<" "<<x<<"\n";
			deg++;
		}else{
			cout<<x<<" "<<v<<"\n";
		}
	}
	used[v] = 2;
	return deg%2;
}
