        // choose minimum degree vertex!
        int u = degree.begin()->second;
        int v = -1;
        int d = degree.begin()->first;
        // cout << "u : " << u << " / " << degree2;
        if((d + out[u]) % 2 == 0) {
            for(auto e : adj[u]) {
                if(e->dir == 0) {
                    if(e->u == u) {
                        e->dir = 1;
                        v = e->v;
                    }
                    else {
                        e->dir = -1;
                        v = e->u;
                    }
                    degree.erase({degree2[v], v});
                    if(--degree2[v] > 0) degree.insert({degree2[v], v});
