const int MAX_N=1e6+1;
int N,M;

SETI G[MAX_N];
void nope() {
  cout<<"-1"<<endl;
  exit(0);
}
vector<II> res;
int viz[MAX_N];
int dfs(int u) {
  viz[u]=true;
  int p=0;
  while(SZ(G[u])) {
    auto it=G[u].begin();
    int v=*it;
    G[v].erase(G[v].find(u)),G[u].erase(it);
    if(viz[v]) res.emplace_back(u,v),p^=1;
    else {
      int cp=dfs(v);
      if(cp) res.emplace_back(v,u);
      else res.emplace_back(u,v);
      p^=(1-cp);
    }
  }
  return p;
}
void solve() {
  ZERO(viz);
  res.clear();
  int p=dfs(0);
  assert(p==0);
  FORR(p,res) {
    cout<<p.first+1<<" "<<p.second+1<<endl;
  }
}

