class dsu
{
	vector<int> par, siz;

public:
	dsu(int n) : par(n, -1), siz(n, 1)
	{}

	int get_class(int v)
	{
		return par[v] == -1 ? v : par[v] = get_class(par[v]);
	}

	bool unite(int a, int b)
	{
		a = get_class(a);
		b = get_class(b);

		if (a == b)
			return false;

		siz[a] += siz[b];
		par[b] = a;

		return true;
	}
};


