		if (Kr.unite(it.first, it.second))
		{
			tree[it.first].insert(it.second);
			tree[it.second].insert(it.first);
		}
		else
			ord.push_back(it);
	}

	set<int> leaves, alive;

	for (int i = 0; i < n; i++)
		if (!gr[i].empty())
		{
			alive.insert(i);

			if (gr[i].size() == 1)
				leaves.insert(i);
		}

	vector<vector<int>> ans(n);

	while (!alive.empty())
	{
		int q, w;

		if (ord.empty())
		{
			assert (!leaves.empty());

			q = *leaves.begin();
			w = *gr[q].begin();
		}
		else
		{
			q = ord.back().first;
			w = ord.back().second;

			ord.pop_back ();
		}

		if (num[q])
		{
			ans[q].push_back(w);
			num[q] = !num[q];
		}
		else
		{
			ans[w].push_back(q);
			num[w] = !num[w];
		}

		gr[q].erase(w);

		if (gr[q].size() == 1)
			leaves.insert(q);
		if (gr[q].empty())
		{
			leaves.erase(q);
			alive.erase(q);
		}

		gr[w].erase(q);

		if (gr[w].size() == 1)
			leaves.insert(w);
		if (gr[w].empty())
		{
			leaves.erase(w);
			alive.erase(w);
		}
	}

	if (count(num.begin(), num.end(), true) != 0)
	{
		cout << -1 << endl;

		return;
	}

	for (int i = 0; i < n; i++)
		for (auto j : ans[i])
			cout << i + 1 << ' ' << j + 1 << endl;
}


