int dep[Maxn + 5];
vector<pair<int, int> > edges;

int DFS(int u, int fa) {
	dep[u] = dep[fa] + 1;
	int deg = 0;
	for(int i = 0; i < (int)G[u].size(); i++) {
		int v = G[u][i];
		if(v == fa) continue;
		if(dep[v]) {
			if(dep[v] < dep[u])
				deg++, edges.push_back(make_pair(u, v));
			continue;
		}
		int degv = DFS(v, u);
		if(degv & 1) edges.push_back(make_pair(v, u));
		else edges.push_back(make_pair(u, v)), deg++;
	}
	return deg;
}

