		deg[x]^=1;
		k[to[i]]=pc[i];
		dfs(to[i],x);
	}
}

void Dfs(int x,int f){
	for(int i=fir[x];i;i=nxt[i]){
		if(to[i]==f) continue;
		Dfs(to[i],x);
		sc[x]^=sc[to[i]];
	}
	b[k[x]]^=sc[x];
}

int LCA(int x,int y){
	if(dep[x]<dep[y]) swap(x,y);
	for(int i=19;i;i--){
		if(dep[fi[x][i]]>=dep[y]){
			x=fi[x][i];
		}
	}
	if(x==y) return x;
	for(int i=19;i;i--){
		if(fi[x][i]!=fi[y][i]){
			x=fi[x][i];
			y=fi[y][i];
		}
	}
	return fi[x][0];
}


