int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> graph(n);
    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if (m % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    vector<int> parity(n);
    vector<vector<int>> tree(n);
    vector<int> leaf1;
    vector<pair<int, int>> ans;
    vector<bool> visited(n);
    set<pair<int, int>> used;
    // from, 親
    queue<pair<int, int>> que;
    que.push(make_pair(0, -1));
    visited[0] = true;
    while (!que.empty()) {
        int from = que.front().first;
        int parent = que.front().second;
        que.pop();

        int nc = 0;
        for (int to : graph[from]) {
            if (to == parent)
                continue;

            if (visited[to]) {
                if (!used.count(make_pair(from, to))) {
                    parity[from] = (parity[from] + 1) % 2;
                    ans.push_back(make_pair(from, to));
                    used.insert(make_pair(from, to));
                    used.insert(make_pair(to, from));
                }
            } else {
                tree[to].push_back(from);
                visited[to] = true;
                que.push(make_pair(to, from));
                ++nc;
            }
        }

        if (nc == 0)
            leaf1.push_back(from);
    }

    vector<int> leaf2;
    while (true) {
        if (leaf1.size() == 1 && leaf1.front() == 0)
            break;

        for (int v : leaf1) {
            if (v == 0)
                continue;

            int parent = tree[v].front();
            if (parity[v] == 1) {
                ans.push_back(make_pair(v, parent));
            } else {
                ans.push_back(make_pair(parent, v));
                parity[parent] += 1;
                parity[parent] %= 2;
            }
            leaf2.push_back(parent);
        }

        leaf1.swap(leaf2);
        leaf2.clear();
    }

    for (const auto &k : ans) {
        cout << k.first + 1 << " " << k.second + 1 << endl;
    }
    return 0;
}

