void dfs(int v) {
    used[v] = 1;

    vector<pair<ll, ll>> edgs;
    for (auto to : gr[v]) {
        bool k = 0;
         if (!usedEdge[to.second])  {
            edgs.push_back(to);
            k = 1;
            usedEdge[to.second] = 1;
        }
        if (!used[to.first]) {
            dfs(to.first);
        } 
        if (k && cnt[to.first] != 0) {
            dir[to.second] = to.first;
            edgs.pop_back();
            cnt[to.first] = 0;
        }
    }

    if (edgs.size() % 2 == 1) {
        pair<ll, ll> cr = edgs.back();
        edgs.pop_back();
        dir[cr.second] = v;
        cnt[v] = 1;
    }

    for (int i = 0; i < edgs.size(); i += 2) {
        dir[edgs[i].second] = v;
        dir[edgs[i + 1].second] = v;
    }
}

