using namespace std;

bool check(int a[], int b[], int f[], int size) {
	int c[size];
	for (int i = 0; i < size; i++) {
		if (f[i] == 0) {
			c[a[i]]++;
		} else {
			c[b[i]]++;
		}
	}

	bool flag = true;
	for (int i = 0; i < size; i++) {
		if (c[i] % 2 != 0) {
			flag = false;
			break;
		}
	}

	return flag;
}

int main(int argc, char *argv[]) {
	int n, m;
	cin >> n >> m;
	int a[m];
	int b[m];
	for (int i = 0; i < m; i++) {
		cin >> a[i] >> b[i];
	}

	int f[m];
	bool flag = true;
	while (flag) {
		if(check(a, b, f, m)) {
			break;
		}
		int index = m - 1;
		f[index] += 1;
		while (f[index] == 2) {
			f[index--] = 0;
			if (index < 0) {
				flag = false;
				break;
			}
			f[index] += 1;
		}
	}

	if (flag) {
		for (int i = 0; i < m; i++) {
			if (f[i] == 0) {
				cout << a[i] << " " << b[i] << endl;
			} else {
				cout << b[i] << " " << a[i] << endl;
			}
		}
	} else {
		cout << "-1" << endl;
	}
}

