    a--; b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  if (M % 2 == 1) {
    cout << -1 << endl;
    return 0;
  }

  int rem = M;
  int now = 0;
  while (rem > 0) {
    if (g[now].size() == 1) now = g[now][0];

    int tmin1 = g[now][0], tmin2 = g[now][1];
    int t1_i = 0, t2_i = 1;
    int tmin1_size = g[tmin1].size();
    int tmin2_size = g[tmin2].size();
    bool flag_2 = false;
    int ex_i;
    rep(i, g[now].size()) {
      int nx = g[now][i];
      if (g[nx].size() < tmin1_size) {
        tmin2 = tmin1;
        t2_i = t1_i;
        tmin2_size = tmin1_size;
        tmin1 = nx;
        t1_i = i;
        tmin1_size = g[nx].size();
      }

      if (g[nx].size() == 2) {
        rep(k, 2) {
          if (g[g[nx][k]].size() == 1) {
            flag_2 = true;
            ex_i = i;
          }
        }
      }
    }

    if (flag_2) {
      int nx = g[now][ex_i];
      rep(k, 2) ans[nx].push_back(g[nx][k]);
      g[now].erase(g[now].begin() + ex_i);
      rem -= 2;
      continue;
    }


    ans[now].push_back(tmin1);
    ans[now].push_back(tmin2);
    rem -= 2;

    int next_now;
    if (g[now].size() == 2) next_now = g[now][t2_i];

    rep(i, g[tmin1].size()) {
      if (g[tmin1][i] == now) {
        g[tmin1].erase(g[tmin1].begin() + i);
        break;
      }
    }
    rep(i, g[tmin2].size()) {
      if (g[tmin2][i] == now) {
        g[tmin2].erase(g[tmin2].begin() + i);
        break;
      }
    }

    if (t1_i > t2_i) swap(t1_i, t2_i);
    g[now].erase(g[now].begin() + t2_i);
    g[now].erase(g[now].begin() + t1_i);
    if (g[now].size() == 0) now = next_now;
  }


  rep(i, N) {
