using namespace std;

int main() {
    int N, M;
    cin >> N >> M;

    if (M % 2 != 0) {
        cout << -1 << endl;
        return 0;
    }

    vector<set<int>> graph(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        graph[u].insert(v);
        graph[v].insert(u);
    }

    vector<int> rank(N, -1);
    rank[0] = 0;
    queue<int> que;
    que.push(0);

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (auto sv : graph[v]) {
            if (rank[sv] >= 0) continue;
            rank[sv] = rank[v] + 1;
            que.push(sv);
        }
    }

    vector<int> nodes(N);
    iota(nodes.begin(), nodes.end(), 0);
    sort(nodes.begin(), nodes.end(), [&](int u, int v) {
        return rank[u] > rank[v];
    });

    vector<int> deg(N, 0);
    vector<pair<int, int>> ans;

    auto erase = [&](int v) {
        assert(!graph[v].empty());
        int u = *graph[v].begin();
        ans.emplace_back(v, u);
        ++deg[v];
        graph[v].erase(u);
        graph[u].erase(v);
    };

    for (auto v : nodes) {
        while (graph[v].size() >= 2) {
            if (deg[v] % 2 == 0) erase(v);
            erase(v);
        }
        assert(deg[v] % 2 == 0);

        if (!graph[v].empty()) {
            int u = *graph[v].begin();
            ans.emplace_back(u, v);
            ++deg[u];
            graph[v].erase(u);
            graph[u].erase(v);
        }
    }

    for (auto p : ans) {
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }
    return 0;
}

