using namespace std;

struct UF{
    int n;
    vector<int> par;
    UF(int n) : n(n) {
        for(int i = 0; i < n; i++) par.push_back(i);
    }
    int find(int a){
        if(a != par[a]) par[a] = find(par[a]);
        return par[a];
    }
    void join(int a, int b){
        par[find(a)] = find(b);
    }
};

vector<vector<int> > tree;
vector<pair<int,int> > ans;
vector<int> deg;

void dfs(int v, int p){
	for(int w : tree[v]){
		if(w == p) continue;
		dfs(w, v);
	}
	if(p >= 0){
		if(deg[v] & 1){
			deg[p] ^= 1;
			deg[v] ^= 1;
			ans.push_back({v, p});
		} else {
			ans.push_back({p, v});
		}
	}
}

int main(){
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	int n, m;
	cin >> n >> m;
	UF uf(n);
	if(m & 1){
		cout << -1 << '\n';
		return 0;
	}
	tree.resize(n);
	deg.resize(n, 0);
	for(int i = 0; i < m; i++){
		int a, b;
		cin >> a >> b;
		a--; b--;
		if(uf.find(a) == uf.find(b)){
			ans.emplace_back(a, b);
			deg[a]++;
		} else {
			uf.join(a, b);
			tree[a].push_back(b);
			tree[b].push_back(a);
		}
	}
	dfs(0, -1);
	for(auto g : ans){
		cout << g.first + 1 << " " << g.second + 1 << '\n';
	}
}

