void build_tree(ll node, vector<set<ll>>& graph, vector<vll>& tree, bool* visited){
  vll del;
  for(auto e: graph[node]){
    if(visited[e]) continue;
    visited[e] = true;
    del.push_back(e);
    graph[e].erase(node);
    tree[node].push_back(e);
    build_tree(e, graph, tree, visited);
  }
  for(ll n: del) graph[node].erase(n);
}

 void solve(ll node, ll prev, vector<vll>& tree, bool* odd){
   for(ll e: tree[node]) solve(e, node, tree, odd);
   if(prev == 0) return;
   if(odd[node]){
     odd[node] = false;
     printf("%lld %lld\n", node, prev);
