using namespace std;
int gi() {
	char ch='!'; int res=0, f=0;
	while(ch<'0' || ch>'9') { ch=getchar(); if(ch == '-') f=1; }
	while(ch>='0' && ch<='9') res=res*10+ch-'0', ch=getchar();
	return f?-res:res;
}
const int N=1e5+100;
int n,m,fa[N],deg[N],head[N],ce;
struct edge { int to,nxt; } e[N<<1];
void lnk(int a,int b) { e[++ce]=(edge){b,head[a]}, head[a]=ce; }
int getfa(int x) { return x == fa[x]?x:fa[x]=getfa(fa[x]); }
void dfs(int u,int lst) {
	for(int i=head[u];i;i=e[i].nxt) {
		int v=e[i].to;
		if(v == lst) continue;
		dfs(v,u);
	}
	if(!lst) return;
	if(deg[u]&1)
		++deg[u], printf("%d %d\n",u,lst);
	else
		++deg[lst], printf("%d %d\n",lst,u);
}
int main() {
	n=gi(), m=gi();
	if(m&1) { puts("-1"); return 0; }
	for(int i=1;i<=n;++i) fa[i]=i;
	for(int i=1,u,v,fu,fv;i<=m;++i) {
		u=gi(), v=gi(), fu=getfa(u), fv=getfa(v);
		if(fu == fv) { printf("%d %d\n",u,v); ++deg[u]; continue; }
		fa[fu]=fv, lnk(u,v), lnk(v,u);
	}
	dfs(1,0);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N = 1e5+100;
int Next[N*2],Head[N],To[N*2],Val[N*2],cnt;
int tag[N],x[N],y[N],z[N];
int n,m;
bool vis[N];
void add(int u, int v, int w){
    ++cnt; Next[cnt] = Head[u]; 
    Head[u] = cnt; To[cnt] = v; Val[cnt] = w;
}
void dfs(int u,int fa, int now){
    vis[u] = 1;
    for (int i = Head[u]; i; i = Next[i]){
        int v = To[i];
        if (vis[To[i]]) continue;
        dfs(v,u,Val[i]);
    }
    if (tag[u]){
        tag[u] ^= 1; tag[fa]^=1;
        z[now] = -z[now];
    }
}
int main(){
    scanf("%d%d",&n,&m);
    for (int i = 0; i < m; ++i){
        scanf("%d%d",&x[i],&y[i]); z[i] = 1;
        add(x[i],y[i],i); add(y[i],x[i],i);
        tag[x[i]]^=1;
    }
    if (m & 1){
        puts("-1"); return 0;
    }
    dfs(1,0,0);
    for (int i = 0; i < m; ++i){
        if (z[i] > 0) printf("%d %d\n",x[i],y[i]); else printf("%d %d\n",y[i],x[i]);
    }
    return 0;
}

