    edges.push_back({--x, --y});
    degOut[x] ^= 1;
    int dx = get(x), dy = get(y);
    if (dx != dy)
    {
      ds[dx] = dy;
      treeEdges[x].push_back(y);
      treeEdges[y].push_back(x);
    }
  }

  par = vector <int>(n, -1);
  visit(0, degOut[0]);

  for (auto e : edges)
  {
