void dfs(int v, int pe, int p) {
  used[v] = true;
  for (int i = 0; i < sz(g[v]); i++) {
    int u = g[v][i], e = ids[v][i];
    if (e == pe) {
      continue;
    }
    if (used[u]) {
      if (s[e] == -1) {
        s[e] = v;
        t[e] = u;
        need[v] ^= 1;
      }
      continue;
    }
    dfs(u, e, v);
  }
  if (need[v]) {
    assert(pe != -1);
    s[pe] = v;
    t[pe] = p;
    need[v] ^= 1;
  } else {
    if (pe != -1) {
      s[pe] = p;
      t[pe] = v;
      need[p] ^= 1;
    }
  }
}

