int dfs(int v, int pr) {
    used[v] = ++t;
    auto cur = 0;

    for (const auto& to : g[v])
        if (!used[to]) {
            cur ^= dfs(to, v);
        } else if (to != pr && used[to] < used[v]) {
            cur ^= 1;
            E.emplace_back(v, to);
        }

    if (pr != v) {
        if (cur == 1)
            E.emplace_back(v, pr);
        else
            E.emplace_back(pr, v);
    }

    return cur ^ 1;
}

