void dfs(int p, bool f)
{
    for (int i=0; i < edge[p].size(); ++i) {
        int nx = edge[p][i];
        if (nx != -1)
        {
            edge[p][i] = -1;
            for (int j = 0; j < edge[nx].size(); ++j)
            {
                if (edge[nx][j] == p)
                {
                    edge[nx][j] = -1;
                }
            }
            dfs(nx, !f);
            if (f) {
                ans.push_back(make_pair(p, nx));
                ct[p]++;
            }
            else
            {
                ans.push_back(make_pair(nx, p));
                ct[nx]++;
            }
        }
    }
}

void dfs2(int u, vector<int> &trail)
{
    while (!edge[u].empty())
    {
        int v = edge[u].back();
        edge[u].pop_back();
        for (int i = 0; i < edge[v].size(); i++)
        {
            if (edge[v][i] == u)
            {
                edge[v].erase(edge[v].begin() + i);
                break;
            }
        }
        dfs2(v, trail);
    }
    trail.push_back(u);
};

vector<int> EulerianTrail(const int s)
{
    vector<int> trail;
    dfs2(s, trail);
    for (int i=0; i < trail.size()-1; ++i)
    {
        if (i%2)
        {
            ct[trail[i]]++;
            ans.push_back(make_pair(trail[i], trail[i+1]));
        }
        else
        {
            ct[trail[i+1]]++;
            ans.push_back(make_pair(trail[i+1], trail[i]));
        }
    }
    return trail;
}

