using namespace std;

vector<int> EulerianTrail(const int s, vector<vector<int>> &g, const bool directed) {
        function<void (int, vector<int> &)> dfs = [&](int u, vector<int> &trail) {
                while (!g[u].empty()) {
                        int v = g[u].back();
                        g[u].pop_back();
                        if (!directed) {
                                for (int i = 0; i < g[v].size(); i ++) {
                                        if (g[v][i] == u) {
                                                g[v].erase(g[v].begin() + i);
                                                break;
                                        }
                                }
                        }
                        dfs(v, trail);
                }
                trail.push_back(u);
        };
        vector<int> trail;
        dfs(s, trail);
        reverse(trail.begin(), trail.end());
        return trail;
}

int main() {
        int n, m;
        scanf("%d%d", &n, &m);
        vector<vector<int>> g(n);
        vector<int> divNode(n,0);

        if(m % 2 != 0){
            cout << -1 << endl;
            return 0;
        }

        for (int i = 0; i < m; i ++) {
                int a, b;
                scanf("%d%d", &a, &b);
                a --, b --;
                g[a].push_back(b);
                g[b].push_back(a);
                divNode[a]++;
                divNode[b]++;
        }

        int startNode = 0;
        for(int i = 0;i < n;i++){
            if(divNode[i] % 2 != 0){
                startNode = i;
                break;
            }
        }

        auto trail = EulerianTrail(startNode, g, false);

        vector<pair<int, int>> ans;
        vector<int> count(n,0);
        for (int i = 0; i < trail.size() - 1; i ++) {
                int a = trail[i], b = trail[i + 1];
                // printf("a:%d b:%d\n",a,b);
                if (i & 1) {
                    // cout << "aa" << endl;
                    ans.emplace_back(a, b);
                    count[a]++;
                }else{
                    // cout << "bb" << endl;
                    ans.emplace_back(b, a);
                    count[b]++;
                }
        }
        for(int i = 0;i < n;i++){
            if(count[i] % 2 != 0){
                cout << -1 << endl;
                return 0;
            }
        }

        // printf("%d\n", (int) ans.size());
        for (int i = 0; i < ans.size(); i ++) {
                printf("%d %d\n", ans[i].first + 1, ans[i].second + 1);
        }
        return 0;
}

