		ptou ^= dfs(u,nx);
	}else if(d[u] > d[nx]+1){
		ans.push_back(P(u,nx));
		ptou ^= 1;
	}
	if(p+u) ans.push_back(ptou?P(p,u):P(u,p));
	return ptou;
}
