void dfs(ll i, ll prev){
    for(ll to : G[i]){
        if(prev==to) continue;
        parent[to] = i;
        dfs(to, i);
    }

    ll p = parent[i];

    if(i==0) return;

    if(out[i]%2==1){
        // iから出す
        // i->p
        out[i]++;
        Ans.push_back(make_pair(i, p));
    }else{
        // p->i
        out[p]++;
        Ans.push_back(make_pair(p, i));
    }
}

