#define N 10005
int n,m,fa[N],out[N];
vector<int>g[N];
inline int Find(int x)
{
	return x==fa[x]?x:fa[x]=Find(fa[x]);
}
inline void dfs(int x,int fa)
{
	for(int i=0;i<g[x].size();i++)
	{
		int v=g[x][i];
		if(v==fa)
			continue;
		dfs(v,x);
		if(out[v]&1)
			printf("%d %d\n",v,x);
		else
		{
			out[x]++;
			printf("%d %d\n",x,v);
		}	
	}
	return;
}
int main()
{
	scanf("%d%d",&n,&m);
	if(m&1)
	{
		printf("-1");
		return 0;
	}
