		fa[i]=i;
	for(int i=1;i<=m;i++)
	{
		int u,v;
		scanf("%d%d",&u,&v);
		if(Find(u)!=Find(v))
		{
			g[u].push_back(v);
			g[v].push_back(u);
			fa[Find(u)]=Find(v);
		}
		else
		{
			out[v]++;
			printf("%d %d\n",v,u);
		}
	}
