	int n, m;
	cin >> n >> m;
	vector<vector<int>> related(n);
	vector<pair<int, int>> abls(m);
	for (auto& ab : abls) {
		cin >> ab.first >> ab.second;
		if (ab.first > ab.second) swap(ab.first, ab.second);
		related[ab.first - 1].push_back(ab.second - 1);
		related[ab.second - 1].push_back(ab.first - 1);
	}
	if (m % 2 == 1) {
		cout << -1 << endl;
		return 0;
	}

	vector<bool> lockedNodes(n, false);
	vector<pair<int, int>> orientedEdges;
	bool isAllNodeUsed = false;
	while (!isAllNodeUsed){
		isAllNodeUsed = true;
		for (int i = 0; i < n; ++i) {
			auto isEmpty = false;
			if (related[i].empty()) {
				isEmpty = true;
			}
			else if (related[i].size() % 2 == 0) {
				for (auto toNode : related[i]) {
					orientedEdges.push_back(make_pair(i + 1, toNode + 1));
					related[toNode].erase(find(related[toNode].begin(), related[toNode].end(), i));
				}
				related[i].clear();
				isEmpty = true;
			}
			if (!isEmpty)isAllNodeUsed = false;
		}
	}

	for (auto ab : orientedEdges) {
		cout << ab.first << " " << ab.second << endl;
	}
	return 0;
}

