// 有向グラフの接続行列Bに対し,線形方程式 Bx = c を (必要なら mod 2 で) 解くライブラリ
template<typename T>
struct LinearSystemIncidence{
    struct Edge {
        int id, to; bool fwd;
        Edge(int i, int t, bool f) : id(i), to(t), fwd(f) {}
    };

    int n, m;
    bool mod2;
    vector<T> x;
    vector<bool> seen;
    vector<vector<Edge> > G;

    LinearSystemIncidence(int n, vector<pii> &E, bool mod2 = false) : n(n), m(E.size()), G(n), mod2(mod2){
        rep(i, 0, m){
            G[E[i].first].emplace_back(i, E[i].second, true);
            G[E[i].second].emplace_back(i, E[i].first, false);
        }
    }

    T dfs(vector<T> &c, int u){
        seen[u] = true;
        T res = c[u];
        for(auto& e: G[u]){
            if(seen[e.to]) continue;
            T tmp = dfs(c, e.to);
            if(e.fwd) x[e.id] = tmp;
            else x[e.id] = -tmp;
            res += tmp;
            if(mod2){
                x[e.id] %= 2;
                if(x[e.id] < 0) x[e.id] += 2;
            }
        }
        if(mod2) res %= 2;
        return res;
    }

    pair<bool, vector<T> > solve(vector<T> &c){
        x.assign(m, 0);
        seen.assign(n, false);
        rep(u, 0, n){
            if(seen[u]) continue;
            if(dfs(c, u)) return {false, vector<T>()};
        }
        return {true, move(x)};
    }
};

int main(){
    iosetup();
    int n, m; cin >> n >> m;
    vector<pii> es;
    vector<int> c(n);
    rep(i, 0, m){
        int u, v; cin >> u >> v; u--, v--;
        es.emplace_back(u, v);
        c[u] ^= 1;
    }

    LinearSystemIncidence<int> LSI(n, es, true);
    auto sol = LSI.solve(c);

    if(sol.first){
        rep(i, 0, m){
            if(sol.second[i]) swap(es[i].first, es[i].second);
            cout << es[i] + pii(1, 1) << endl;
        }
    }else cout << -1 << endl;

    return 0;
}

