        --a; --b;
        edges[a].emplace_back(b, i);
        edges[b].emplace_back(a, i);
        e[i] = {a, b};
    }
    if(m & 1){ cout << -1 << endl; return 0; }

    stack<int> s;
    vector<int> ord;
    s.push(0);
    vis[0] = true;
    while(!s.empty()){
        int t = s.top();
        s.pop();
        ord.emplace_back(t);
        for(auto to: edges[t]){
            if(vis[to.first]) continue;
            vis[to.first] = true;
            s.push(to.first);
        }
    }
    for(auto it=ord.rbegin();it!=ord.rend();++it){
        // 頂点 *it を見ていく
        int cnt = 0;
        for(auto ed: edges[*it]){
            if(ans[ed.second].first == ans[ed.second].second) ++cnt;
        }
        if(cnt == 0 && parity[*it]){ cout << -1 << endl; return 0; }
        if(cnt % 2 == parity[*it]){
            for(auto ed: edges[*it]){
                if(ans[ed.second].first != ans[ed.second].second) continue;
                ans[ed.second] = { *it + 1, ed.first + 1 };
            }
        }else{
            bool first = true;
            for(auto ed: edges[*it]){
                if(ans[ed.second].first != ans[ed.second].second) continue;
                if(first){
                    first = false;
                    ans[ed.second] = { ed.first + 1, *it + 1 };
                    parity[ed.first] ^= 1;
                }else ans[ed.second] = { *it + 1, ed.first + 1 };
            }
        }
    }
    for(int i=0;i<m;++i) cout << ans[i].first << " " << ans[i].second << endl;

    return 0;
}

