vector<int> adj[N];
vector<pair<int,int>> edge;

void dfs(int u) {
    vis[u] = true;
    for (auto idx : adj[u]) {
        auto &e  = edge[idx];
        int v = e.first + e.second - u;
        if (!vis[v]) {
            dfs(v);
            if (odd[v]) {
                odd[v] = !odd[v];
                odd[u] = !odd[u];
                rev[idx] = true;
            }
        }
    }
}

