bool use[100005];
bool pushed[100005];
int cnt[100005], cnt2[100005];
void solve() {
    cin >> n >> m;
    rep(i, m) {
        cin >> a[i] >> b[i];
        --a[i]; --b[i];
    }

    if (m % 2 != 0) { cout << -1 << endl; return; }
    UnionFind uf(n);
    rep(i, m) {
        if (!uf.same(a[i], b[i])) {
            ++cnt[a[i]]; ++cnt[b[i]];
            g[a[i]].emplace_back(b[i]); g[b[i]].emplace_back(a[i]);
            use[i] = true;
            uf.unite(a[i], b[i]);
        }
        else ++cnt2[a[i]];
    }

    queue<int> que;
    vector<pair<int, int>> ans;
    rep(i, n) if (cnt[i] == 1) { que.emplace(i); pushed[i] = true; }
    while (!que.empty()) {
        auto pos = que.front(); que.pop();
        if (used[pos]) continue;
        used[pos] = true;
        rep(i, sz(g[pos])) {
            auto nv = g[pos][i];
            if (!used[nv]) {
                if (cnt2[pos] % 2 == 1) {
                    ans.emplace_back(pos, nv);
                    ++cnt2[pos];
                }
                else {
                    ans.emplace_back(nv, pos);
                    ++cnt2[nv];
                }
                if (!pushed[nv]) {
                    que.push(nv);
                    pushed[nv] = true;
                }
            }
        }
    }

    rep(i, m) if (!use[i]) cout << a[i] + 1 << " " << b[i] + 1 << endl;
    for (auto& s : ans) cout << s.first + 1 << " " << s.second + 1 << endl;
}

