void dfs(ll node) {
    if(isNodeUsed[node]) { return; }

    isNodeUsed[node] = true;
    // すべて自分のものにする
    for(auto& e_to : graph[node]) {
        ll a = min(node, e_to);
        ll b = max(node, e_to);
        ll e_id = edge_id[make_pair(a, b)];
        if(!isEdgeUsed[e_id]) {
            ans.push_back(make_pair(e_to, node));
            Nyuji[e_to]--;
            Nyuji[node]--;
            assert(Nyuji[e_to] >= 0);
            assert(Nyuji[node] >= 0);
            isEdgeUsed[e_id] = true;
        }
    }

    // 次数が偶数のものへ移動
    for(auto& e_to : graph[node]) {
        if(Nyuji[e_to] % 2 == 0 && !isNodeUsed[e_to]) {
            dfs(e_to);
        }
    }
}

