        int u = e.F, id = e.S;
        if(!mark[u])
        {
            h[u] = h[v] + 1;
            I[u] = id;

            dfs(u);

            la[v] += la[u];
        }
    }
}

int get_par(int v, int H)
{
    int i = 0;
    while(H)
    {
        if(H&1)
            v = par[v][i];
        i++;
        H >>= 1;
    }
    return v;
}

int lca(int u, int v)
{
    if(h[u] > h[v]) swap(u,v);
    v = get_par(v,h[v]-h[u]);
    if(u == v) return v;

    for(int i = 19; i >= 0; i--)
        if(par[v][i] != par[u][i])
        {
            v = par[v][i];
            u = par[u][i];
        }
    return par[v][0];
}

