        e[i ^ 1].stu = -1;
        siz[e[i].y] --;
    }
    // return ;
    for(int i = head[x]; ~i; i = e[i].nxt){
        if(siz[e[i].y] == 0) continue;
        if(siz[e[i].y] & 1) continue;
        dfs(e[i].y);
    }
}

