#include <bits/stdc++.h>
using namespace std;
int N, M;
vector<vector<int>> G;
vector<vector<int>> Tree;
using P = pair<int, int>;
vector<P> edge;
map<P, bool> used;
vector<P> res;
vector<bool> deg;
vector<bool> visited;

void dfs(int p, int u) {
    visited[u] = true;
    for(int to : G[u]) {
        if(visited[to]) continue;
        dfs(u, to);
    }
    if(p != -1) {
        Tree[u].push_back(p);
        Tree[p].push_back(u);
        used[P(u, p)] = true;
        used[P(p, u)] = true;
    }
}

bool init() {
    cin >> N >> M;
    G.resize(N);
    Tree.resize(N);
    deg.resize(N, false);
    visited.resize(N, false);
    for(int i=0; i<M; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        edge.push_back(P(a, b));
        G[a].push_back(b);
        G[b].push_back(a);
    }
    if(M % 2) return false;
    dfs(-1, 0);
    return true;
}

void dfs2(int p, int u) {
    visited[u] = true;
    for(int to : Tree[u]) {
        if(visited[to]) continue;
        dfs2(u, to);
    }
    if(p != -1) {
        if(deg[u]) {
            res.push_back(P(u, p));
        } else {
            res.push_back(P(p, u));
            deg[p] = !deg[p];
        }
    }
}

void solve() {
    for(P e : edge) {
        if(!used[e] | !used[P(e.second, e.first)]) {
            res.push_back(e);
            used[e] = false;
            deg[e.first] = !deg[e.first];
        }
    }
    visited.assign(N, false);
    dfs2(-1, 0);
}

int main() {
    if(!init()) {
        cout << -1 << endl;
        return 0;
    }
    solve();
    for(P e : res) {
        cout << e.first + 1 << ' ' << e.second + 1 << endl;
    }
}

