      res.emplace_back(v, pr);
      ++deg[v];
    } else {
      if (pr != -1) {
        res.emplace_back(pr, v);
        ++deg[pr];
      }
    }
  };
  depth[0] = 0;
  Dfs(0, -1);
  for (auto& p : res) {
    cout << p.first + 1 << " " << p.second + 1 << '\n';
  }
  return 0;
}

