				nokori[edge.first]--;
			} else {
				ans.push_back(lpair(edge.first, now));
				cnt[edge.first]++;
				nokori[now]--;
				nokori[edge.first]--;
			}

			q.push(edge.first);
		}
	}

	bool check = true;
