ll cn2[100005]={0};
ll cn3[100005]={0};
bool used[100005];
bool changed=false;
bool dfs(ll s,ll t){
  if(s==t) {
    return changed=true;
  }
  for(int i=0;i<node2[s].size();i++){
    int to=node2[s][i];
    if(dfs(to,t)){
      node2[s][i]=0;
      node2[to].push_back(s);
      return true;
    }
  }
  return false;
}
int main(){
  ll n,m;
  cin>>n>>m;
  for(int i=0;i<=n;i++) used[i]=false;
  for(int i=0;i<m;i++){
    int a,b;
    cin>>a>>b;
    node[a].push_back(b);
    node[b].push_back(a);
    cnt[a]++;
    cnt[b]++;
  }
  if(m%2==1){
    cout<<-1<<endl;
    return 0;
  }
  priority_queue<P,vector<P>,greater<P>> pque;
  for(int i=1;i<=n;i++){
    pque.push(P(cnt[i],i));
  }
  vector<P> ans;
  while(!pque.empty()){
    P p=pque.top();
    pque.pop();
    ll pos=p.second;
    if(used[pos]) continue;
    //cout<<"P:"<<pos<<endl;
    used[pos]=true;
    bool f=false;
    for(int i=0;i<node[pos].size();i++){
