        cnt[to]--;
        if(!f&&cn2[pos]%2==1){
          ans.push_back(P(pos,to));
          pque.push(P(cnt[to],to));
        }
        else{
          ans.push_back(P(to,pos));
          pque.push(P(cnt[to],to));
          cn2[to]++;
        }
        f=true;
      }
    }
  }
  for(int i=0;i<m;i++) {
    cn3[ans[i].first]++;
    node2[ans[i].first].push_back(ans[i].second);
  }
  queue<ll> que;
  for(int i=1;i<=n;i++) if(cn3[i]%2==1) que.push(i);

  while(!que.empty()){
    ll s=que.front();
    que.pop();
    if(que.empty()){
      cout<<-1<<endl;
      return 0;
    }
    ll t=que.front();
    que.pop();
    dfs(s,t);
  }

  for(int i=1;i<=n;i++){
    for(int j=0;j<node2[i].size();j++){
      if(node2[i][j]!=0){
        cout<<i<<" "<<node2[i][j]<<endl;
      }
    }
  }
}

