			ans.push_back(P(v, u));
			parity[v] = !parity[v];
			continue;
		}
		dfs(u, v);
	}
	if(p != -1){
		if(parity[v]){
			ans.push_back(P(v, p));
			parity[v] = !parity[v];
		}
		else{
			ans.push_back(P(p, v));
			parity[p] = !parity[p];
		}
	}
}

