vector<Edge>MST(vector<Edge> edges){

	int cost = 0;
	vector<Edge> result;
	for (int i = 0; i < n; i++)
		make_set(i);
	sort(edges.begin(), edges.end());
	for (Edge e : edges) {
		if (find_set(e.u) != find_set(e.v)) {
			cost += e.weight;
			result.push_back(e);
			union_sets(e.u, e.v);
		}
		else {ans.pb(mp(e.u , e.v)) ;deg[e.u]++ ;}
	}
	return result ;
}
