#define MAX_N (100000)
#define MAX_M (100000)

using namespace std;

int check_bipartite(const vector<vector<int>> &adj_lists, int cur,
                    vector<int> &gs) {
  const int g_cur = gs[cur];
  for (int nxt : adj_lists[cur]) {
    if (gs[nxt] == 0) {
      gs[nxt] = -g_cur;
      if (!check_bipartite(adj_lists, nxt, gs)) {
        return 0;
      }
    } else if (gs[nxt] == g_cur) {
      return 0;
    }
  }
  return 1;
}

int main(int argc, char *argv[]) {
  // read inputs
  int N, M, as[MAX_M], bs[MAX_M];
  scanf("%d %d", &N, &M);
  for (int k = 0; k < M; k++) {
    scanf("%d %d", &as[k], &bs[k]);
    as[k]--;  // NOTE : modified input
    bs[k]--;  // NOTE : modified input
  }

  // create graph
  vector<vector<int>> adj_lists(N, vector<int>());
  for (int k = 0; k < M; k++) {
    const int a = as[k], b = bs[k];
    adj_lists[a].push_back(b);
    adj_lists[b].push_back(a);
  }

  // check whether bipartite
  vector<int> gs(N, 0);
  gs[0] = 1;
  if (check_bipartite(adj_lists, 0, gs)) {
    // check if all nodes in at least one group have even rank
    int all_even_1 = 1, all_even_m1 = 1;
    for (int i = 0; i < N; i++) {
      if (adj_lists[i].size() % 2 != 0) {
        if (gs[i] == 1) {
          all_even_1 = 0;
        } else {
          all_even_m1 = 0;
        }
      }
    }
    if (all_even_1) {
      for (int i = 0; i < N; i++) {
        if (gs[i] == 1) {
          for (int j : adj_lists[i]) {
            printf("%d %d\n", i + 1, j + 1);
          }
        }
      }
    } else if (all_even_m1) {
      for (int i = 0; i < N; i++) {
        if (gs[i] == -1) {
          for (int j : adj_lists[i]) {
            printf("%d %d\n", i + 1, j + 1);
          }
        }
      }
    } else {
      printf("-1\n");
    }
  } else {
    printf("-1\n");
  }

  return 0;
}

