using namespace std;

int N, M;
vector<pair<int, int>> graph[100005];
pair<int, int> edge[100005];
int order[100005];
bool tree[100005];
int pare[100005], parn[100005];
bool vis[100005];
int outdgr[100005];
bool used[100005];

void dfs1(int n){
    vis[n] = 1;
    for(auto e : graph[n]){
        if(e.first != parn[n] && !used[e.second]){
            used[e.second] = 1;
            if(e.first == edge[e.second].first){
                swap(edge[e.second].first, edge[e.second].second);
            }
            outdgr[n]++;
            if(!vis[e.first]){
                pare[e.first] = e.second;
                parn[e.first] = n;
                tree[e.second] = 1;
                dfs1(e.first);
            }
        }
    }
}

int dfs2(int n){
    int tot = outdgr[n]&1;
    for(auto e : graph[n]){
        if(e.first != parn[n] && tree[e.second]){
            int sub = dfs2(e.first);
            if(sub > tot){
                swap(sub, tot);
            }
            tot -= sub;
        }
    }
    if(tot&1){
        order[pare[n]]++;
    }
    return tot;
}

int main(){
    cin.sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> N >> M;
    for(int i = 1; i<=M; i++){
