        edge[i] = {a, b};
        graph[a].push_back({b, i});
        graph[b].push_back({a, i});
    }
    if(M%2 == 1){
        cout << -1 << endl;
        return 0;
    }
    dfs1(1);
    dfs2(1);
    for(int i = 1; i<=M; i++){
        if(order[i]){
            cout << edge[i].second << " " << edge[i].first << "\n";
        }
        else{
            cout << edge[i].first << " " << edge[i].second << "\n";
        }
    }
}

