vector<pint> ret;
void dfs(int now)
{
    if (e[now].empty()) return;
    int nxt = -1;
    for (auto x : e[now]) if (e[x].size() > 1) nxt = x;

    set<int> nxt_visit = e[now];

    if (e[now].size() % 2)
    {
        for (auto x : e[now]) if (nxt != x)
        {
            ret.emplace_back(now, x);
            e[now].erase(x);
            e[x].erase(now);
        }
    }
    else
    {
        for (auto x : e[now])
        {
            ret.emplace_back(now, x);
            e[now].erase(x);
            e[x].erase(now);
        }
    }
    for (auto v : nxt_visit) dfs(v);
}

