std::vector<std::set<int>> g;
std::vector<std::deque<int>> d;
std::vector<int> done, depth, par;

void dfs(int v, int p) {
    done[v] = 1;
    par[v] = p;
    bool l = true;
    for (auto to : g[v]) {
        if (to == p || done[to]) continue;
        l = false;
        depth[to] = depth[v] + 1;
        dfs(to, v);
    }
    if (!l) d[depth[v]].push_back(v);
}

int main() {
    int n, m;
    std::cin >> n >> m;
    g.resize(n + 1); d.resize(n + 1); depth.resize(n + 1); done.resize(n + 1); par.resize(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        std::cin >> u >> v;
        g[u].insert(v);
        g[v].insert(u);
    }

    if (m & 1) {
        std::cout << -1 << std::endl;
        return 0;
    }

    int r = 1;
    for (int i = 2; i <= n; i++) if (g[r].size() < g[i].size()) r = i;
    dfs(r, 0);

    int md = 0;
    while (!d[md + 1].empty()) md++;
    auto add_edge = [&](int u, int v) { std::cout << u << " " << v << std::endl; };
    for (int i = md; i >= 0; i--) {
        for (auto v : d[i]) {
            int lim = g[v].size();
            lim = lim / 2 * 2;
            std::vector<int> w(g[v].begin(), g[v].end());
            std::sort(w.begin(), w.end(), [&](int lhs, int rhs) {
                return depth[lhs] > depth[rhs];
            });
            for (int j = 0; j < lim; j++) {
                auto to = w[j];
                add_edge(v, to);
                g[v].erase(to);
                g[to].erase(v);
            }
        }
    }

    return 0;
}

