using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, M, as[MAX_M], bs[MAX_M];
  scanf("%d %d", &N, &M);
  for (int k = 0; k < M; k++) {
    scanf("%d %d", &as[k], &bs[k]);
    as[k]--;  // NOTE : modified input
    bs[k]--;  // NOTE : modified input
  }

  // create graph
  vector<set<int>> adj_lists(N, set<int>());
  for (int k = 0; k < M; k++) {
    const int a = as[k], b = bs[k];
    adj_lists[a].insert(b);
    adj_lists[b].insert(a);
  }

  // solve greedily from nodes with smallest ranks
  vector<int> cs, ds, num_outs(N, 0);
  priority_queue<pair<int, int>, vector<pair<int, int>>,
                 greater<pair<int, int>>>
      que;
  // add initial states of all nodes
  for (int i = 0; i < N; i++) {
    que.push(make_pair(adj_lists[i].size(), i));
  }
  while (!que.empty()) {
    // get front of queue
    const int cur = que.top().second, rank = que.top().first;
    que.pop();
    // return if cur has no more unused edges
    if (adj_lists[cur].size() == 0) {
      continue;
    }
    // choose the direction of unused edges
    // make all edges point away from cur
    for (int nxt : adj_lists[cur]) {
      cs.push_back(cur);
      ds.push_back(nxt);
      num_outs[cur]++;
    }
    // make the last edge point to cur if odd
    if (num_outs[cur] % 2 == 1) {
      const int nxt = ds.back();
      cs.pop_back();
      ds.pop_back();
      cs.push_back(nxt);
      ds.push_back(cur);
      num_outs[cur]--;
      num_outs[nxt]++;
    }
    // remove the edges from adj_lists
    for (int k = cs.size() - adj_lists[cur].size(); k < cs.size(); k++) {
      const int c = cs[k], d = ds[k];
      adj_lists[c].erase(d);
      adj_lists[d].erase(c);
    }
  }

  // check
  int is_possible = 1;
  for (int i = 0; i < N; i++) {
    if (num_outs[i] % 2 == 1) {
      is_possible = 0;
      break;
    }
  }

  if (is_possible) {
    if (cs.size() != M || ds.size() != M) {
      printf("something is wrong...\n");
      exit(1);
    }
    for (int k = 0; k < M; k++) {
      printf("%d %d\n", cs[k] + 1, ds[k] + 1);
    }
  } else {
    printf("-1\n");
  }

  return 0;
}

