int run1(int beg, int cur) {
	for(int i=0;i<eds[cur].size();i++) {
		if(dirs[cur][i] == 0) {
			int to = eds[cur][i];
			int rv = revs[cur][i];
			dirs[cur][i] = 1;
			dirs[to][rv] = 1;
			seqs[beg].push_back(i);
			if(to == beg) return 1;
			if(run1(beg, to)) return 1;
		}
	}
	return 0;
}
int cs = 2;
void run2(int beg) {
	int cur = beg;
	used[beg] = 1;
	for(int i=0;i<seqs[beg].size();i++) {
		dirs[cur][seqs[beg][i]] = cs;
		int to = eds[cur][seqs[beg][i]];
		int rv = revs[cur][seqs[beg][i]];
		revs[to][rv] = 5 - cs;
		cs = 5 - cs;
		if(used[to] == 0) run2(to);
		cur = to;
	}
}

