      int inkey = min(e.first, e.second);
      int outkey = max(e.first, e.second);
      ans.push_back(make_pair(outkey, inkey));
      out[outkey] += 1;
    } else {
      graph[e.first].push_back(e.second);
      graph[e.second].push_back(e.first);
      uf.unite(e.first, e.second);
    }
