set<int> edges[100005];
void solve() {
  int n, m;
  cin >> n >> m;
  if(m%2) {
    die();
  }
  for(int i = 0; i < m; i++) {
    int a, b;
    cin >> a >> b;
    edges[a].insert(b);
    edges[b].insert(a);
  }
  queue<int> q;
  int lhs = 1;
  map<int, vector<int>> dp;
  for(int i = 1; i <= n; i++) {
    if(edges[i].size() == 1) {
      q.push(i);
      dp[*edges[i].begin()].push_back(i);
    }
  }
  vector<pii> ret;
  while(!q.empty() || lhs <= n) {
    if(q.empty()) {
      while(lhs <= n && edges[lhs].empty()) lhs++;
      if(lhs > n) break;
      q.push(lhs);
    }
    int out = q.front();
    q.pop();
    if(edges[out].empty()) continue;
    int cand = edges[out].size() == 1 ? *edges[out].begin() : out;
    int need = 2;
    while(need > 0 && dp.count(cand)) {
      need--;
      int val = dp[cand].back();
      dp[cand].pop_back();
      if(dp[cand].empty()) dp.erase(cand);
      ret.emplace_back(cand, val);
      edges[cand].erase(val);
      edges[val].erase(cand);
    }
    while(need > 0) {
      need--;
      int nextCand = *edges[cand].begin();
      ret.emplace_back(cand, nextCand);
      edges[cand].erase(nextCand);
      edges[nextCand].erase(cand);
      if(edges[nextCand].size() == 1) {
        q.push(nextCand);
        dp[*edges[nextCand].begin()].push_back(nextCand);
      }
    }
  }
  for(pii out: ret) {
    cout << out.first << " " << out.second << "\n";
  }
}

