int n,m,root;
struct Edge
{
	int u,v;
	Edge(int _u=0,int _v=0){u=_u,v=_v;}
}E[MAXM+5];
struct node
{
	int id,num;
}f[MAXN+5];
bool cmp(node a,node b)
{
	return a.id>b.id;
}
void Addedge(int u,int v)
{
    E[++Cnt]=Edge(u,v);
    nxt[Cnt]=head[u];
    head[u]=Cnt;
}
void bfs(int root)
{
	int tot=0;
	queue<int> que;
	que.push(root);
	vis[root]=1;
	while(!que.empty())
	{
		int u=que.front();que.pop();
		f[++tot].id=tot,f[tot].num=u;
		id[u]=tot;
		for(int i=head[u];i;i=nxt[i])
			if(!vis[E[i].v])
			{
				vis[E[i].v]=1;
				que.push(E[i].v);
			}
	}
	//for(int i=1;i<=n;i++)
	//	printf("点%d:%d\n",i,id[i]);
	//printf("----------\n");
}
void Solve()
{
	sort(f+1,f+n+1,cmp);
	for(int i=1;i<=n;i++)
	{
		int u=f[i].num;
		//printf("u:%d\n",u);
		for(int j=head[u];j;j=nxt[j])
			if(id[E[j].v]<f[i].id)
			{
				if(ind[u]%2)
				{
					ind[u]++;
					printf("%d %d\n",u,E[j].v);					
				}
				else
				{
					ind[E[j].v]++;
					printf("%d %d\n",E[j].v,u);
				}	
			}
	}
}
