void no_ans(){
  cout<<-1<<endl;
  exit(0);
}
vector<vector<ll>>ans;
vector<vector<ll>>m;
vector<bool>used;
vector<pll> e;
void rec(ll idx){
  for (auto &&i : m[idx])
  {
    auto itr=lower_bound(e.begin(),e.end(),pll(min(i,idx),max(i,idx)));
    if(used[itr-e.begin()]==false){
      used[itr-e.begin()]=true;
      ans[idx].push_back(i);
      rec(i);
    }
  }

}
void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
  ans.resize(N);
  m.resize(N);
  used.resize(M);
  fill(used.begin(),used.end(),false);
  REP(M){
    --B[i];--A[i];
    m[A[i]].push_back(B[i]);
    m[B[i]].push_back(A[i]);
    e.push_back(pll(min(A[i],B[i]),max(A[i],B[i])));
  }
  sort(e.begin(),e.end());
  REP(N){
    if(m[i].size()%2==1)no_ans();
  }
  rec(0);
  REP(N){
    for (auto &&j : ans[i])
    {
      printf("%d %lld\n",i+1,j+1);
    }

  }
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long M;
    scanf("%lld",&M);
    std::vector<long long> A(M);
    std::vector<long long> B(M);
    for(int i = 0 ; i < M ; i++){
        scanf("%lld",&A[i]);
        scanf("%lld",&B[i]);
    }
    solve(N, M, std::move(A), std::move(B));
    return 0;
}

