void sgd(int dg, int op) {
	bo[dg] = sh[dg] = 1;
	for(int sw : v[dg]) {
		if(!bo[sw]) {
			sgd(sw, dg);
		} else {
			if(!sh[sw]) fp.push_back({dg, sw}), st[dg] ^= 1;
		}
	}
	if(dg ^ 1) {
		if(st[dg]) {
			fp.push_back({dg, op});
			st[dg] = 0;
		} else {
			fp.push_back({op, dg});
			st[op] ^= 1;
		}
	}
	sh[dg] = 0;
}

