struct edge{
    int id, from, to;
};

int n, m;
vector< set<int> > g;
vector<edge> e;
vector<int> de;

void dfs(int v){
    if(g[v].empty()){
        return;
    }

    if(((int)g[v].size() % 2 == 1) ^ (de[v] % 2 == 1)){
        int k = *g[v].begin();
        g[v].erase(g[v].begin());
        if(e[k].from == v){
            g[e[k].to].erase(k);
            swap(e[k].from, e[k].to);
        }else{
            g[e[k].from].erase(k);
        }
        ++de[e[k].from];
        dfs(e[k].from);
    }

    set<int> st = g[v];
    for(auto k : st){
        g[v].erase(k);
        if(e[k].from == v){
            g[e[k].to].erase(k);
        }else{
            g[e[k].from].erase(k);
            swap(e[k].from, e[k].to);
        }
        ++de[e[k].from];
        dfs(e[k].to);
    }

    return;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> n >> m;

    g.resize(n);
    e.resize(m);
    de.resize(n, 0);

    rep(i, m){
        int a, b;
        cin >> a >> b;
        g[--a].insert(i);
        g[--b].insert(i);
        e[i].id = i;
        e[i].from = a;
        e[i].to = b;
    }

    if(m % 2 == 1){
        cout << -1 << endl;
        return 0;
    }

    bool flag = true;
    rep(i, n){
        if((int)g[i].size() == 1){
            flag = false;
            dfs(i);
        }
    }
    if(flag){
        dfs(0);
    }

    rep(i, m){
        cout << e[i].from + 1 << " " << e[i].to + 1 << endl;
    }

    return 0;
}

