int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(15);

    int n;
    cin >> n;
    int m;
    cin >> m;
    vector<pair<int, int>> edges(m);
    vector adjs(n, vector<tuple<bool, int,int>>());
    rep(i, m)
    {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        edges[i] = {a, b};
        adjs[a].emplace_back(true, i, b);
        adjs[b].emplace_back(false, i, a);
    }

    vector used(n, false);
    vector sol(m, false); // solution vector
    auto dfs = [&](auto self, int v) -> bool {
        used[v] = true;
        // 元の出次数 mod 2
        bool ret = (count_if(adjs[v].begin(), adjs[v].end(), [](auto p) {
            return get<0>(p);
        }) % 2 != 0);
        for (auto &[b, e, u] : adjs[v])
        {
            if (used[u])
            {
                continue;
            }
            bool s = self(self, u);
            sol[e] = s; // mod 2 なので符号は気にしなくてOK
            ret = ret ^ s;
        }
        return ret;
    };

    rep(v, n)
    {
        if (used[v])
        {
            continue;
        }
        if (dfs(dfs, v))
        {
            cout << -1 << "\n";
            return 0;
        }
    }

    rep(e, m)
    {
        auto [a,b] = edges[e];
        if (sol[e])
        {
            swap(a, b);
        }
        ++a;
        ++b;
        cout << b << ' ' << a << endl;
    }

    return 0;
}

