vector< pair<ll,ll> >edge;
vector<ll> adj[100005];
vector<ll> adj_st[100005];
set< pair<ll,ll> >edges_in_st;
vector<ll> outdegree(100005,0);
vector< pair<ll,ll> >ans;

void func(ll src,vector<bool> &visited ,ll parent)
{
    visited[src]=true;
    for(auto ele:adj_st[src])
    {
        if(!visited[ele])
            func(ele,visited,src);
    }

    if(outdegree[src]&1)
    {
        if(parent==-1)
        {
            cout<<"-1";
            exit(0);
        }

        outdegree[src]++;
        ans.push_back( make_pair(src , parent) );
    }
    else
    {
        if(parent!=-1)
        {
            outdegree[parent]++;
            ans.push_back( make_pair(parent , src) );
        }
    }
}

void dfs(ll src, vector< bool> &visited)
{
    visited[src]=true;
    for(int i=0;i<adj[src].size();i++)
    {
        ll ele = adj[src][i];
        if(!visited[ele])
        {
            adj_st[src].push_back(ele);
            adj_st[ele].push_back(src);
            edges_in_st.insert( make_pair( min(src,ele) , max(src,ele) ) );
            dfs(ele,visited);
        }
    }
}

int main()
{
    fast();
    ll n,m;
    cin>>n>>m;
    for(ll i=0;i<m;i++)
    {
        ll u,v;
        cin>>u>>v;
        u--;v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
        edge.push_back( make_pair( min(u,v) , max(u,v) ) );
    }

    vector<bool> visited(n, false);
    dfs(0,visited);


    for(ll i=0;i<m;i++)
    {
        if(edges_in_st.find( edge[i] )!=edges_in_st.end())
            continue;
        outdegree[edge[i].first]++;
        ans.push_back( edge[i] );
    }
    vector<bool> visited_st(n,false);
    func(0,visited_st,-1);

    for(ll i=0;i<ans.size();i++)
        cout<<ans[i].first+1<<" "<<ans[i].second+1<<endl;

}

