        if (e[i].size() > 1) two.insert(i);
    }

    while (!one.empty() or !two.empty())
    {
        int s;
        if (!one.empty()) s = *one.begin();
        else s = *two.begin();
        int t = *e[s].begin();
        one.erase(s);
        one.erase(t);
        two.erase(s);
        two.erase(t);

        if (cou[s] % 2)
        {
        ret.emplace_back(s, t);
        cou[s]++;
        }
        else
        {
            ret.emplace_back(t, s);
            cou[t]++;
        }
        e[s].erase(t);
        e[t].erase(s);

        if (e[s].size() == 1) one.insert(s);
        if (e[s].size() > 1) two.insert(s);
        if (e[t].size() == 1) one.insert(t);
        if (e[t].size() > 1) two.insert(t);
    }

    for (auto pa : ret) printf("%d %d\n", pa.first, pa.second);
}

