using namespace std;

const int MAXN = (int) 1e5;

vector < pair <int, bool> > g[MAXN + 1];
int anc[MAXN + 1][20], deg[MAXN + 1];
int lvl[MAXN + 1], vis[MAXN + 1];

void dfs(int nod, int par) {
    lvl[nod] = lvl[par] + 1;
    vis[nod] = 1;

    anc[nod][0] = par;
    for(int bit = 1; bit < 20; bit++) {
        anc[nod][bit] = anc[anc[nod][bit - 1]][bit - 1];
    }

    for(auto it : g[nod]) {
        if(vis[it.first] == 0) {
            dfs(it.first, nod);
        }
    }
}

int sp[MAXN + 1];

inline int get_lca(int x, int y) {
    if(lvl[x] < lvl[y]) {
        swap(x, y);
    }
    for(int bit = 19; bit >= 0; bit--) {
        if(lvl[anc[x][bit]] >= lvl[y]) {
            x = anc[x][bit];
        }
    }

    if(x == y) {
        return x;
    }

    for(int bit = 19; bit >= 0; bit--) {
        if(anc[x][bit] != anc[y][bit]) {
            x = anc[x][bit];
            y = anc[y][bit];
        }
    }
    return anc[x][0];
}

void solve(int nod, int par) {
    vis[nod] = 1;
    for(auto it : g[nod]) {
        if(vis[it.first] == 0) {
            solve(it.first, nod);
            sp[nod] += sp[it.first];
        }
        else if(it.first != par && it.second == 0) {
            cout << nod << " " << it.first << "\n";
        }
    }
    if(nod != 1) {
        if(sp[nod] & 1) {
            cout << nod << " " << par << "\n";
        }
        else {
            cout << par << " " << nod << "\n";
        }
    }
}

int main() {
    //ifstream cin("A.in");
    //ofstream cout("A.out");
    int i, n, m;
    ios::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    cin >> n >> m;

    if(m & 1) {
        cout << -1;
        return 0;
    }

    for(i = 1; i <= m; i++) {
        int x, y;
        cin >> x >> y;
        g[x].push_back({y, 0});
        g[y].push_back({x, 1});
        deg[x]++;
    }

    dfs(1, 0);

    int x = 0;
    for(int y = 1; y <= n; y++) {
        if(deg[y] & 1) {
            if(x == 0) {
                x = y;
            }
            else {
                int nod = get_lca(x, y);
                sp[nod] -= 2;
                sp[x]++, sp[y]++;
                x = 0;
            }
        }
    }

    fill(vis + 1, vis + n + 1, 0);
    solve(1, 0);

    return 0;
}

