P path(int a, int b) {
    if (b > a) swap(a, b);
    return P(a, b);
}

void dfs1(vector<vector<int>> &edges, int now, int prev, set<P> &tree_edges, vector<bool> &visited) {
    if (visited[now]) return;
    visited[now] = true;

    for (int next : edges[now]) {
        if (next == prev) continue;
        if (visited[next]) continue;
        tree_edges.insert(path(now, next));
        dfs1(edges, next, now, tree_edges, visited);
    }

}

struct Triangle {
    int parent;
    vector<int> children;
};

class Tree {
    vector<vector<int>> edges;
public:
    Tree(int n) : edges(n) {}

    void edge(int i, int j) {
        edges[i].push_back(j);
        edges[j].push_back(i);
    }

    void root(int r, vector<Triangle> &leafs) {
        queue<int> vs;
        vs.push(r);
        vector<bool> check(edges.size(), false);
        check[r] = true;
        while (!vs.empty()) {
            int k = vs.front();
            Triangle triangle;
            triangle.parent = k;

            for (int i : edges[k]) {
                if (check[i]) continue;
                check[i] = true;
                triangle.children.push_back(i);
                vs.push(i);
            }
            vs.pop();
            leafs.push_back(triangle);
        }
        reverse(leafs.begin(), leafs.end());
    }
};


