struct UnionFind {
    V<ll> rank;
    V<ll> parent;

    UnionFind(ll N) : rank(N, 0), parent(N) {
        iota(parent.begin(), parent.end(), 0ll);
    }

    ll find(ll child) {
        return (child == parent[child] ? child : parent[child] = find(parent[child]));
    }

    void unit(ll x, ll y) {
        ll px = find(x);
        ll py = find(y);
        if(px == py) {
            return;
        }
        if(rank[px] < rank[py]) {
            swap(px, py);
        }
        parent[py] = px;
        rank[px] += (rank[px] == rank[py]);
    }

    bool same(ll x, ll y) {
        return (find(x) == find(y));
    }
};

V<set<ll>> edges;
VV<ll> tree_edges;
V<ll> tree_parents;

void dfs(ll now, ll pre, queue<ll> &que) {
    bool leaf = true;
    for(ll nxt : tree_edges[now]) {
        if(nxt == pre) continue;
        leaf = false;
        dfs(nxt, now, que);
    }
    tree_parents[now] = pre;
    if(leaf) que.push(now);
}

int main() {
    ll N, M;
    cin >> N >> M;
    edges.resize(N);
    tree_edges.resize(N);
    tree_parents.resize(N);
    V<PLL> all_edges(M);
    for(ll i = 0; i < M; i++) {
        ll a, b;
        cin >> a >> b;
        a--; b--;
        edges[a].insert(b);
        edges[b].insert(a);
        all_edges[i] = PLL(a, b);
    }


    UnionFind uf(N);
    for(auto &&ele : all_edges) {
        ll a, b;
        tie(a, b) = ele;
        if(uf.same(a, b)) continue;
        DEBUG(make_tuple(a,b));
        tree_edges[a].push_back(b);
        tree_edges[b].push_back(a);
        uf.unit(a, b);
    }

    queue<ll> leaves;
    dfs(0, -1, leaves);

    V<ll> cnt_in(N);

    V<PLL> ans(M);
    size_t ans_idx = 0;
    auto update_ans = [&](ll from, ll to) {
        DEBUG(PLL(from, to));
        cnt_in[from]++;
        ans[ans_idx] = PLL(from + 1, to + 1);
        ans_idx++;
    };

    V<bool> visited(N);
    while(leaves.size()) {
        ll now = leaves.front();
        leaves.pop();
        ll par = tree_parents[now];

        for(auto &&ele : edges[now]) {
            if(ele == par) continue;
            update_ans(now, ele);
            edges[ele].erase(now);
        }

        if(now == 0) break;
        if(cnt_in[now] % 2 == 0) update_ans(par, now);
        else update_ans(now, par);
        edges[par].erase(now);

        if(!visited[par]) {
            leaves.push(par);
            visited[par] = true;
        }
    }

    DEBUG(cnt_in);
    if(cnt_in[0] % 2 == 0) {
        for(auto &&ele : ans) cout << ele.first << ' ' << ele.second << endl;
    } else {
        cout << -1 << endl;
    }
    return 0;
}

