int N, M;
vector<pii> edges;
vector<vi> graph;
set<pii> used;
vector<pii> finalEdges;
vi goingOut;
bool fail = false;

vector<bool> seen;

void dfs(int cur) {
	seen[cur] = true;
	for (int n : graph[cur]) if (!seen[n]) {
		used.insert(pii {min(cur, n), max(cur, n)});
		dfs(n);
	}
}

void calc(int cur, int par) {
	seen[cur] = true;
	for (int n : graph[cur]) if (!seen[n]) {
		calc(n, cur);
	}

	if (goingOut[cur] % 2 == 0) {
		if (par != -1) {
			finalEdges.push_back({par, cur});
			goingOut[par]++;
		}
	} else {
		if (par != -1) {
			finalEdges.push_back({cur, par});
			goingOut[cur]++;
		} else fail = true;
	}
}

int main() {
	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> M;

	graph.resize(N);
	edges.resize(M);
	goingOut.resize(N);

	F0R(i, M) {
		int a, b; cin >> a >> b; --a; --b;
		edges[i] = {a, b};
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	seen = vector<bool> (N);
	dfs(0);

	for (pii e : edges) {
		pii ie = {min(e.first, e.second), max(e.first, e.second)};
		if (used.find(ie) == used.end()) {
			finalEdges.push_back(ie);
			goingOut[ie.first]++;
		}
	}
	seen = vector<bool> (N);
	calc(0, -1);

	if (fail) {
		print(-1);
	} else {
		for (pii e : finalEdges) {
			print(e.first + 1, e.second + 1);
		}
	}
}

