const int N = 100005;
int rem[N];
int parity[N];
bool visit[N];
pair<int, int> ans[N];
int es = 0;
int n,m;

void ng(){
	printf("-1\n");
	exit(0);
}

void addedge(int from, int to){
	parity[from] ^= 1;
	ans[es++] = make_pair(from, to);
	rem[from]--, rem[to]--;
}

void branch(vector<vector<int>> &g, int u){
	if(g[u].size()>2)return;
	if(g[u].size()==1){
		if(parity[u])ng();
		if(visit[g[u][0]])return;
		else addedge(g[u][0], u);
	}else{
		int v = visit[g[u][0]]?g[u][1]:g[u][0];
		if(parity[u])addedge(u, v);
		else addedge(v, u);
		branch(g, v);
	}
}

int main()
