		u--, v--;
		g[u].emplace_back(v);
		g[v].emplace_back(u);
		rem[u]++;
		rem[v]++;
	}
	if(m % 2)ng();
	for(int i=0; i<n; i++)if(!visit[i] && g[i].size()==1)branch(g, i);
	unordered_set<int> idxs;
	for(int i=0; i < n; i++)if(rem[i])idxs.insert(i);
	while(es < m){
