ll n, m, a[100000], b[100000], dir[100000], counter[100000];
set<P> G[100000];
SegmentTree<P> sgt;
const P cons = P(INF+1, -1);
P small(P a, P b) {
  if (a.first == b.first) return rand() % 2 == 0 ? a : b;
  return a.first < b.first ? a : b;
}

int main() {
  srand((unsigned)time(NULL));
  scanf("%lld%lld", &n, &m);
  for (ll i = 0; i < m; i++) {
    scanf("%lld%lld", &a[i], &b[i]);
    a[i]--, b[i]--;
  }
  if (m % 2 != 0) {
    printf("-1\n");
    return 0;
  }
  sgt.init(n, small, cons, cons);
  while (1) {
    for (ll i = 0; i < n; i++) G[i].clear();
    for (ll i = 0; i < m; i++) {
      G[a[i]].insert(P(b[i], i));
      G[b[i]].insert(P(a[i], i));
    }
    for (ll i = 0; i < n; i++) sgt.valueChange(i, P((ll)G[i].size(), i));
    ll t = 0;
    for (ll i = 0; i < m; i++) {
      P temp = sgt.rangeQuery(0, n+1);
      ll from = temp.second;
      auto p = G[from].begin();
      while (p != G[from].end() && G[p->first].size() != 1) p++;
      if (p == G[from].end()) p = G[from].begin();
      ll to = p->first, num = p->second;
      G[from].erase(P(to, num));
      G[to].erase(P(from, num));
      if (G[to].size() == 0) t++;
      sgt.valueChange(from, P((G[from].size() == 0 ? INF : G[from].size()), from));
      sgt.valueChange(to, P((G[to].size() == 0 ? INF : G[to].size()), to));
      if (temp.first == 1 && counter[from] % 2 == 0) dir[num] = (from == a[num] ? 1 : 0), counter[to]++;
      else dir[num] = (from == a[num] ? 0 : 1), counter[from]++;
    }
    if (t <= 1) break;
  }
  for (ll i = 0; i < m; i++) {
    if (dir[i] == 0) printf("%lld %lld\n", a[i]+1, b[i]+1);
    else printf("%lld %lld\n", b[i]+1, a[i]+1);
  }
}

