    for(int i=1;i<=n;i++) out[i] = -1;

    for(int i=0;i<m;i++){
        int a, b; cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    int d = 0;
    queue<pair<int, bool> > Q;
    Q.push(make_pair(1, true));
    while(!Q.empty()){
        auto p = Q.front();
        Q.pop();
        int v = p.first;
        bool isout = p.second;

        out[v] = isout; // 0 or 1

        for(int e: edge[v]){
            if(out[e] == -1){
                Q.push(make_pair(e, !isout));
            }
        }
    }

    /*
    for(int i=1;i<=n;i++){
        cout << out[i] << endl;
    }
    */

    bool pos = true;

    for(int i=1;i<=n;i++){
        if(out[i] && edge[i].size() %2){
            pos = false;
            break;
        }
    }

    if(pos){
        for(int i=1;i<=n;i++){
            if(out[i]){
                for(int e: edge[i]){
                    cout << i << " " << e << endl;
                }
            }
        }
        return 0;
    }

    pos = true;

    // inverse
    for(int i=1;i<=n;i++){
        if(!out[i] && edge[i].size() %2){
            pos = false;
            break;
        }
    }

    if(pos){
        for(int i=1;i<=n;i++){
            if(!out[i]){
                for(int e: edge[i]){
                    cout << i << " " << e << endl;
                }
            }
        }
        return 0;
    }

    cout << -1 << endl;
}

