class Lca
{
    int n, log_n;
    std::vector<std::vector<int>> parent;
    std::vector<int> depth;
    void dfs(const std::vector<std::vector<int>> &g, int v, int p, int d)
    {
        parent[0][v] = p;
        depth[v] = d;
        for (int i = 0; i < (int)g[v].size(); i++)
        {
            if (g[v][i] != p)
                dfs(g, g[v][i], v, d + 1);
        }
    }

public:
    Lca(const std::vector<std::vector<int>> &g, int root) : n((int)g.size()), log_n(0), depth(n, 0)
    {
        for (int v = n; v > 0; v /= 2)
            log_n++;
        parent.assign(log_n, std::vector<int>(n, 0));
        dfs(g, root, -1, 0);
        for (int k = 0; k < log_n - 1; k++)
        {
            for (int v = 0; v < n; v++)
            {
                if (parent[k][v] < 0)
                    parent[k + 1][v] = -1;
                else
                    parent[k + 1][v] = parent[k][parent[k][v]];
            }
        }
    }
    int query(int u, int v)
    {
        if (depth[u] > depth[v])
            std::swap(u, v);
        for (int k = 0; k < log_n; k++)
        {
            if (((depth[v] - depth[u]) >> k) & 1)
            {
                v = parent[k][v];
            }
        }
        if (u == v)
            return u;
        for (int k = log_n - 1; k >= 0; k--)
        {
            if (parent[k][u] != parent[k][v])
            {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; i++)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    if (m % 2)
    {
        cout << -1 << endl;
        return 0;
    }
    vector<vector<int>> tr(n);
    set<P> ret;
    queue<P> que;
    vector<int> used(n, 0), cnt(n, 0);
    que.push(P(0, -1));
    used[0] = 1;
    while (!que.empty())
    {
        int cur = que.front().first;
        int par = que.front().second;
        que.pop();
        for (auto v : g[cur])
        {
            if (v == par)
                continue;
            if (used[v])
            {
                if (ret.find(P(v, cur)) != ret.end())
                    continue;
                ret.emplace(cur, v);
                cnt[cur]++;
                continue;
            }
            tr[cur].push_back(v);
            cnt[cur]++;
            used[v] = 1;
            que.emplace(v, cur);
        }
    }
    vector<int> odd;
    for (int i = 0; i < n; i++)
        if (cnt[i] % 2)
            odd.push_back(i);
    vector<int> sum(n, 0);
    assert(odd.size() % 2 == 0);
    Lca(tr, 0);
    int sz = odd.size();
    Lca lca(tr, 0);
    for (int i = 0; i < sz; i += 2)
    {
        int p = lca.query(odd[i], odd[i + 1]);
        sum[p]++;
        sum[odd[i]]--;
        sum[odd[i + 1]]--;
    }
    que.emplace(0, -1);
    while (!que.empty())
    {
        int cur = que.front().first;
        int par = que.front().second;
        que.pop();
        for (auto v : tr[cur])
        {
            if (v == par)
                continue;
            if (sum[cur] % 2)
            {
                ret.emplace(v, cur);
            }
            else
            {
                ret.emplace(cur, v);
            }
            sum[v] += sum[cur];
            que.emplace(v, cur);
        }
    }
    assert(ret.size() == m);
    for (auto p : ret)
    {
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }
}

