		edge[a].push_back(b);
		edge[b].push_back(a);
	}

	// construction
	Vec< int > outdeg(N, 0);

	// deg 1
	for_(v,0,N) {
		if (edge[v].size() == 1) {
			useEdge(edge[v][0], v);
			++outdeg[edge[v][0]];
		}
	}

	// others
	for_(v,0,N) {
		int T = (outdeg[v] & 1 ? 1 : 0);
		for (int u : edge[v]) {
			if (isUsed(u, v)) continue;
			if (T) {
				useEdge(v, u);
				++outdeg[v];
				--T;
			}
			else {
				useEdge(u, v);
				++outdeg[u];
			}
		}
	}
}
