struct SegmentTree{
    private:
        int n;
        vector<pii> node;

    public:
        SegmentTree(vector<pii> v){
            int sz = v.size();
            n = 1; while(n < sz) n *= 2;
            node.resize(2 * n - 1,{INF, 0});
            for(int i = 0; i < sz; i++) node[i+n-1] = v[i];
            for(int i = n - 2; i >= 0; i--){
              if(node[2*i + 1].first < node[2*i+2].first) node[i] = node[2*i + 1];
              else node[i] = node[2*i + 2];
            }
        }

        void update(int x, int val){
            x += n - 1;
            node[x].first = val;
            while(x > 0){
                x = (x - 1) / 2;
                if(node[2*x+1].first < node[2*x+2].first) node[x] = node[2*x + 1];
                else node[x] = node[2*x + 2];
            }
        }

        pii getmin(int a, int b, int k = 0, int l = 0, int r = -1){
            if(r < 0) r = n;
            if(r <= a || b <= l) return mp(INF, 0);
            if(a <= l && r <= b) return node[k];

            auto vl = getmin(a, b, 2*k+1, l, (l+r)/2);
            auto vr = getmin(a, b, 2*k+2, (l+r)/2, r);
            if(vl.first < vr.first) return vl;
            return vr;
        }
};

