void set_is_tree(bool is_tree[], const V<t2> &ablist, ll parent, ll child)
{
        int left = 0;
        int right = ablist.size()-1;
        int idx = (left + right) / 2;
        t2 key = t2(min(parent, child), max(parent, child));

        for ( ; left <= right; idx = (left + right) / 2) {
                if (key == ablist[idx]) {
                        is_tree[idx] = true;
                        return;
                }
                if (key < ablist[idx]) {
                        right = idx - 1;
                }
                if (key > ablist[idx]) {
                        left = idx + 1;
                }
        }

        assert(false);
}

void calcp(ll points[], const V<ll> children[], ll node)
{
        ll ans = 0LL;

        for (auto c : children[node]) {
                calcp(points, children, c);
                ans += points[c] + 1;
        }

        points[node] = ans;
}

