const int MOD = 1000000007, INF = 1111111111;
using namespace std;
using lint = long long;

struct RandNum {

	mt19937 mt;
	RandNum() : mt(chrono::steady_clock::now().time_since_epoch().count()) {}

	lint operator()(lint a, lint b) {
		uniform_int_distribution<lint> dist(a, b);
		return dist(mt);
	}
	lint operator() (lint b) { return (*this)(0LL, b); }

	template<class Ite>
	void shuf(Ite first, Ite last) { shuffle(first, last, mt); }

};

int main() {

	int N, M;
	scanf("%d%d", &N, &M);

	if (M % 2 == 1) {
		printf("-1\n");
		return 0;
	}

	int u, v;
	map<pair<int, int>, int> dir;
	vector<vector<pair<int,int>>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		scanf("%d%d", &u, &v);
		u--, v--;
		edge[u].emplace_back(v, i);
		edge[v].emplace_back(u, i);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	stack<int> que;
	RandNum ran;
	for (int i = 0; i < N; i++) {
		if (out[i] == 1) {
			que.emplace(i);
		}
	}

	vector<int> used(M);
	while (!que.empty()) {

		int now = que.top();
		que.pop();
		if (out[now] == 0) continue;

		bool random = true;
		for (const auto &e : edge[now]) {
			if (out[e.first] == 1) {
				dir[{min(now, e.first), max(now, e.first)}] *= -1;
				out[now] ^= 1;
				out[e.first] ^= 1;
				used[e.second] = 2;
				random = false;
				break;
			}
		}

		if (random) {
			for (const auto &e : edge[now]) {
				if (used[e.second] != 2) {
					int next = e.first;
					dir[{min(now, next), max(now, next)}] *= -1;
					out[now] ^= 1;
					out[next] ^= 1;
					used[e.second]++;
					que.emplace(next);
					random = false;
				}
			}
		}

		if (random) {
			int next = edge[now][ran(edge[now].size() - 1)].first;
			dir[{min(now, next), max(now, next)}] *= -1;
			out[now] ^= 1;
			out[next] ^= 1;
			que.emplace(next);
		}

	}

	for (auto &e : dir) {
		if (e.second == 1) printf("%d %d\n", e.first.first + 1, e.first.second + 1);
		else printf("%d %d\n", e.first.second + 1, e.first.first + 1);
	}

	return 0;
}

