//ここから編集する
class Solve {
public:
    int N, M;
    vector<vector<pair<int, bool>>> G;
    vector<pair<int, int>> ans;
    vector<int> cnt;
    vector<bool> visit;

    void dfs(int v) {
        visit[v] = true;
        //辺を貼る
        for (int i = 0; i < G[v].size(); ++i) {

//        for (auto nv : G[v]) {
            auto nv = G[v][i];
            if (!nv.second) {
                if (cnt[v] % 2 == 0) {
                    //自分に向かう辺を貼る
                    ans.emplace_back(nv.first, v);
                    cnt[nv.first]++;
                } else {
                    ans.emplace_back(v, nv.first);
                    cnt[v]++;
                }
                G[v][i].second = true;
                int pt =
                        lower_bound(G[nv.first].begin(), G[nv.first].end(), make_pair(v, false)) - G[nv.first].begin();
                G[nv.first][pt].second = true;
            }
        }
        //探索する
        for (auto nv : G[v]) {
            if (!visit[nv.first]) {
                dfs(nv.first);
            }
        }
    }

    void solve() {
        cin >> N >> M;
        G.resize(N);
        cnt.resize(N);
        visit.resize(N, false);
        for (int i = 0; i < M; ++i) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(make_pair(b, false));
            G[b].push_back(make_pair(a, false));
        }

        for (int i = 0; i < N; ++i) {
            sort(all(G[i]));
        }

        dfs(0);

        for (int i = 0; i < N; ++i) {
            if (cnt[i] % 2) {
                cout << -1 << endl;
                return;
            }
        }

        for (auto e : ans) {
            cout << e.first + 1 << " " << e.second + 1 << endl;
        }

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

