vvi nodes;
vi depth, out, sub;
vpii res;
void dfs(int u) {
    for (int v : nodes[u]) {
        if (depth[v] == 0) {
            depth[v] = 1 + depth[u];
            dfs(v);
            sub[u] += sub[v];
        }
        if (depth[v] == 1 + depth[u] || depth[v] < depth[u] - 1) {
            ++out[u];
            res.emplace_back(u, v);
        }
    }
    if (out[u]&1) ++sub[u];
}

