vector<PII> edge;
vector<PII> ans;
int n,m;
VI edgeNum;
void solve(){
  vector<PII> notFindEdge;
  rep(i,m){
    int a = edge[i].first;
    int b = edge[i].second;
    if((edgeNum[a]/2) % 2 == 0 && (edgeNum[b]/2) % 2 == 1){
      ans.push_back({a+1,b+1});
      edgeNum[b]-=2;
    }else if((edgeNum[a]/2) % 2 == 1 && (edgeNum[b]/2) % 2 == 0){
      ans.push_back({b+1,a+1});
      edgeNum[a]-=2;
    }else{
      notFindEdge.push_back({a,b});
    }
  }
  // ここの時点で全ての頂点の無向辺の次数は偶数
  if(notFindEdge.size() % 2 == 1){
    cout << -1 << endl;
    return;
  }

  //偶数次数なら外に出して奇数次数なら貰う
  rep(i,notFindEdge.size()){
    int a = notFindEdge[i].first;
    int b = notFindEdge[i].second;
    if((edgeNum[a]/2) % 2 == 0){
      edgeNum[a]-=2;
      ans.push_back({b+1,a+1});
    }else{
      edgeNum[b]-=2;
      ans.push_back({a+1,b+1});
    }
  }

  rep(i,ans.size()) cout << ans[i].first << " " << ans[i].second << endl;
}
