using pii = pair<int, int>;

vector<pii> edges_ans;

void erase_edge(int i_c, vector<set<int>>& list_edge, vector<int>& states){
    vector<int> erased;
    if(states[i_c]%2 != 0){
        int i_d = *list_edge[i_c].begin();
        edges_ans.push_back(pii(i_c, i_d));
        list_edge[i_c].erase(i_d);
        list_edge[i_d].erase(i_c);
        erased.push_back(i_d);
        states[i_c]++;
    }
    for(const int i_d  : list_edge[i_c]){
        edges_ans.push_back(pii(i_d, i_c));
        list_edge[i_d].erase(i_c);
        erased.push_back(i_d);
        states[i_d]++;
    }
    list_edge[i_c].clear();
    for(const int i_d : erased)
    if(list_edge[i_d].size() == 1)
        erase_edge(i_d, list_edge, states);
}

