typedef pair<int,int> ii;
int n,m;
vector<int> al[100005];
bool parity[100005];

struct ufds{
    int p[100005];
    int r[100005];

    ufds(){
        for (int x=0;x<100005;x++){
            p[x]=x;
            r[x]=0;
        }
    }
    int parent(int i){return (p[i]==i)?i:p[i]=parent(p[i]);}
    bool unions(int i,int j){
        i=parent(i),j=parent(j);
        if (i==j) return false;
        if (r[i]<r[j]){
            p[i]=j;
        }
        else{
            p[j]=i;
            if (r[i]==r[j]) r[i]++;
        }
        return true;
    }
}*dsu=new ufds();

void dfs(int i,int p){
    for (auto &it:al[i]){
        if (it==p) continue;
        dfs(it,i);
    }
    if (p==-1) return;
    if (parity[i]) printf("%d %d\n",i,p);
    else printf("%d %d\n",p,i), parity[p]^=true;
}

int main(){
    scanf("%d%d",&n,&m);
    if (m&1){
        printf("-1\n");
        return 0;
    }
    int a,b;
    while (m--){
        scanf("%d%d",&a,&b);
        if (dsu->unions(a,b)){
            al[a].push_back(b);
            al[b].push_back(a);
        }
        else{
            parity[a]^=true;
            printf("%d %d\n",a,b);
        }
    }

    dfs(1,-1);
}

