    e[++tot]=(edge){head[u],v},head[u]=tot;
    e[++tot]=(edge){head[v],u},head[v]=tot;
}
void dfs(int u)
{
    for(int i=head[u];i!=0;i=e[i].nxt)
    {
        int v=e[i].to;
        if(vis[v]) continue;
        if(!in[i]&&!in[i^1])
        {
            if(out[u]) out[u]^=1,in[i]=1;
            else out[v]^=1,in[i^1]=1;
        }
    }
    for(int i=head[u];i!=0;i=e[i].nxt)
    {
        int v=e[i].to;
        if(vis[v]) continue;
        vis[v]=1;
        dfs(v);
    }
    if(out[u])
    {
        puts("-1");
        exit(0);
    } 
}
int main()
{
    int n,m;
    cin>>n>>m;
    for(int i=1;i<=m;i++)
    {
        int u,v;
        scanf("%d%d",&u,&v);
        add(u,v);
    }
    dfs(1);
    for(int u=1;u<=n;u++)
        for(int i=head[u];i!=0;i=e[i].nxt)
            if(in[i]) printf("%d %d\n",u,e[i].to);
    return 0;
}

