	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(12);

	ll n,m;
	cin >> n >> m;
	Graph g(n);
	rep(i, 0, m) {
		ll a, b;
		cin >> a >> b; --a; --b;
		g.push_undir({ a,b });
	}
	set<pll> edgeVisited;
	vll cntVisited(n);
	vector<Edge> res;
	auto visitCheck = [&](pll x) {
		return edgeVisited.find(x) != edgeVisited.end() || edgeVisited.find(pll{ x.second, x.first }) != edgeVisited.end();
	};
	auto func = [&](const Edge & e) {
		ll actSize=0;

		for (ll ei : g.out(e.to)) {
			auto& e_ = g[ei];
			pll fs = { e_.from, e_.to };
			if (!visitCheck(fs))
			{
				actSize++;
			}
		}
		if (!(actSize % 2)) {
			for (ll ei : g.out(e.to)) {
				auto& e_ = g[ei];
				pll fs = { e_.from, e_.to };
				if (!visitCheck(fs))
				{
					edgeVisited.insert(fs);
					res.push_back(e_);
				}
			}
		}
		else {
			for (ll ei : g.out(e.to)) {
				auto& e_ = g[ei];
				pll fs = { e_.from, e_.to };
				if (!visitCheck(fs) && e_.to != e.from)
				{
					edgeVisited.insert(fs);
					res.push_back(e_);
				}
			}
		}
		cntVisited[e.from] = actSize;

	};
	if (m % 2 == 1) {
		cout << -1 << endl;
		return 0;
	}
	else {
		g.dfs(0, nullAction, func);
	}
	func(Edge{ 0,0 });
	rep(i, 0, res.size()) {
		cout << res[i].from+1 << " " << res[i].to+1 << endl;
	}


	return 0;

}

