int32_t main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    #define Task        "test"
    if(fopen(Task".inp", "r")) {
        freopen(Task".inp", "r", stdin);
        freopen(Task".out", "w", stdout);
    }
    cin >> n >> m;
    for(int i = 1; i <= m; ++i) {
        cin >> e[i].u >> e[i].v;
        a[e[i].u].pb(i), a[e[i].v].pb(i);
        ++deg[e[i].u], ++deg[e[i].v];
    }
    for(int i = 1; i <= n; ++i)
        if(deg[i] % 2 == 0) pq.push(mp(1 - (deg[i] & 1), i));
    while(pq.size()) {
        pii top = pq.top(); pq.pop();
        if(top.u != 1 - (deg[top.v] & 1)) continue;
        if(deg[top.v] & 1) return cout << -1, 0;
        int u = top.v; del[u] = 1;
        for(int i: a[u]) {
            int v = e[i].u ^ e[i].v ^ u;
            if(!del[v]) {
                if(e[i].u == u) d[i] = 1;
                else d[i] = -1;
                --deg[v];
                pq.push(mp(1 - (deg[v] & 1), v));
            }
        }
    }
    for(int i = 1; i <= m; ++i) {
        if(d[i] == 1) cout << e[i].u << ' ' << e[i].v << '\n';
        else cout << e[i].v << ' ' << e[i].u << '\n';
    }
}

