using namespace std;
struct unionfind{
	vector<int> p;
	unionfind(int N){
		p = vector<int>(N, -1);
	}
	int root(int x){
		if (p[x] == -1){
			return x;
		} else {
			p[x] = root(p[x]);
			return p[x];
		}
	}
	bool same(int x, int y){
		return root(x) == root(y);
	}
	void unite(int x, int y){
		x = root(x);
		y = root(y);
		p[x] = y;
	}
};
int main(){
	int N, M;
	cin >> N >> M;
	unionfind UF(N);
	vector<vector<int>> E(N);
	vector<int> c(N, 0);
	vector<pair<int, int>> ans;
	for (int i = 0; i < M; i++){
		int A, B;
		cin >> A >> B;
		A--;
		B--;
		if (UF.same(A, B)){
			ans.push_back(make_pair(A, B));
			c[A] = 1 - c[A];
		} else {
			E[A].push_back(B);
			E[B].push_back(A);
			UF.unite(A, B);
		}
	}
	vector<int> deg(N);
	for (int i = 0; i < N; i++){
		deg[i] = E[i].size();
	}
	queue<int> Q;
	for (int i = 0; i < N; i++){
		if (deg[i] == 1){
			Q.push(i);
		}
	}
	vector<bool> used(N, false);
	while (!Q.empty()){
		int v = Q.front();
		Q.pop();
		used[v] = true;
		for (int w : E[v]){
			if (!used[w]){
				if (c[v] == 0){
					ans.push_back(make_pair(w, v));
					c[w] = 1 - c[w];
				} else {
					ans.push_back(make_pair(v, w));
					c[v] = 1 - c[v];
				}
				deg[w]--;
				if (deg[w] == 1){
					Q.push(w);
				}
			}
		}
	}
	bool ok = true;
	for (int i = 0; i < N; i++){
		if (c[i] == 1){
			ok = false;
		}
	}
	if (!ok){
		cout << -1 << endl;
	} else {
		for (int i = 0; i < M; i++){
			cout << ans[i].first + 1 << ' ' << ans[i].second + 1 << endl;
		}
	}
}

