vector<int> cnt(N,0);
vector<vector<int>> G(N);
set<P> ans;

void dfs(int n, int par){
  visited[n] = true;

  for(auto t : G[n]){
    if(t != par && !visited[t]) {
      dfs(t,n);
      if(cnt[t]%2==1){
        int x=t,y=n;
        if(x>y) swap(x,y);
        ans.erase(P(x,y));
        ans.insert(P(y,x));
        cnt[x]--; cnt[y]++;
      }
    }
  }
  return;
}

