/*
 * 重み無しグラフで、辺集合表現から隣接集合表現へ変換
 */
template<bool Directed, typename N>
std::vector<std::unordered_set<N>> edges2neighsets(const std::vector<std::pair<N, N>>& edges, N n)
{
	std::vector<std::unordered_set<N>> neighs(n);
	for (const auto& edge : edges) {
		auto a = std::get<0>(edge);
		auto b = std::get<1>(edge);
		neighs[a].insert(b);
		if (!Directed)
			neighs[b].insert(a);
	}
	return neighs;
}

/*
 * 重み付きグラフで、辺集合表現から隣接集合表現へ変換
 */
template<bool Directed, typename N, typename W>
std::vector<std::unordered_map<N, W>> edges2neighsets(const std::vector<std::tuple<N, N, W>>& edges, N n)
{
	std::vector<std::unordered_set<N>> neighs(n);
	for (const auto& edge : edges) {
		auto a = std::get<0>(edge);
		auto b = std::get<1>(edge);
		auto w = std::get<2>(edge);
		neighs[a].insert({b, w});
		if (!Directed)
			neighs[b].insert({a, w});
	}
	return neighs;
}


/*
 * 重み無し無向グラフの隣接集合表現を受け取り、深さ優先探索してノードをポストオーダーで列挙して関数を呼ぶ
 */
template<typename N, typename F>
void graph_depthfirst_postorder_call(const std::vector<std::unordered_set<N>>& neighs, N n, const F& fn, N start = 0);

template<typename N, typename F>
void graph_depthfirst_postorder_call_impl(std::vector<char>& arrived, const std::vector<std::unordered_set<N>>& neighs, N cur, const F& fn)
{
	for (auto neigh : neighs[cur]) {
		if (arrived[neigh])
			continue;
		arrived[neigh] = 1;
		graph_depthfirst_postorder_call_impl(arrived, neighs, neigh, fn);
	}
	fn(cur);
}

template<typename N, typename F>
void graph_depthfirst_postorder_call(const std::vector<std::unordered_set<N>>& neighs, N n, const F& fn, N start /* = 0 */)
{
	std::vector<char> arrived(n);
	arrived[start] = 1;
