/*
 * 重み無し無向グラフの隣接集合表現を受け取り、深さ優先探索してノードをポストオーダーで列挙して返す
 */
template<typename N>
std::vector<N> graph_depthfirst_postorder_enum(const std::vector<std::unordered_set<N>>& neighs, N n, N start = 0)
{
	std::vector<N> nodes(n);
	size_t num = 0;
	graph_depthfirst_postorder_call(neighs, n, [&nodes, &num](N node){
		nodes[num++] = node;
	}, start);
	return nodes;
}


int main()
{
