		--e.first;
		--e.second;
	}

	if (M % 2 == 1) {
		std::cout << "-1\n";
		return 0;
	}

	auto neighs = edges2neighsets<false>(E, N);
	auto nodes = graph_depthfirst_postorder_enum(neighs, N);

	std::vector<char> parity(N);
	for (auto node : nodes) {
		for (auto neigh : neighs[node]) {
			if (parity[node]) {
				std::cout << (node + 1) << " " << (neigh + 1) << "\n";
				parity[node] = 0;
			} else {
