        E[x].push_back(y);
        E[y].push_back(x);
    }
}

int D[100005];
int P[100005][20];
void dfs1(int x) {
    V[x] = 1;
    for (int i = 1; i < 20; i++)
        P[x][i] = P[P[x][i - 1]][i - 1];
    for (int i : E[x]) {
        if (V[i]) continue;
        P[i][0] = x;
        D[i] = D[x] + 1;
        dfs1(i);
    }
}

int lca(int x, int y) {
    if (D[x] < D[y]) swap(x, y);
    for (int i = 20; i--; ) {
        if ((D[x] - D[y] >> i) == 1) {
            x = P[x][i];
        }
    }
    if (x == y) return x;
    for (int i = 20; i--; ) {
        if (P[x][i] != P[y][i]) {
            x = P[x][i];
            y = P[y][i];
        }
    }
    return P[x][0];
}

int S[100005];
set<pi> rev;
void dfs2(int x) {
    V[x] = 0;
    for (int i : E[x]) {
        if (V[i]) {
            dfs2(i);
            S[x] += S[i];
            if (S[i] % 2 == 1) {
                rev.emplace(x, i);
            }
        }
    }
}

int O[100005];
void calc() {
    if (m % 2 == 1) {
        cout << -1;
        return;
    }
    dfs1(1);
    vector<int> odd;
    for (int i = 1; i <= n; i++) {
        for (int j : E[i]) {
            if (D[i] < D[j]) O[i]++;
        }
        if (O[i] % 2 == 1) {
            odd.push_back(i);
        }
    }
    for (int i = 0; i < odd.size(); i += 2) {
        int x = odd[i], y = odd[i + 1];
        S[x]++;
        S[y]++;
        S[lca(x, y)] -= 2;
    }
    dfs2(1);
    for (int i = 1; i <= n; i++) {
        for (int j : E[i]) {
            if (D[i] < D[j]) {
                if (rev.count(pi(i, j)) == 1) {
                    cout << j << ' ' << i << '\n';
                }
                else {
                    cout << i << ' ' << j << '\n';
                }
            }
        }
    }
}

