void dfs(graph &G, vector< bool > &done, vector< int > &o, int x, int p) {
	rep(i, G[x].size()) {
		edge e = G[x][i];
		if (e.d != 0 || e.to == p)
			continue;
		if (done[e.to]) {
			G[x][i].d = 1;
			o[x]++;
			G[e.to][e.c].d = -1;
		} else {
			done[e.to] = true;
			dfs(G, done, o, e.to, x);
		}
	}
}
void dfs2(graph &G, vector< int > &o, int x, int p, int j) {
	rep(i, G[x].size()) {
		edge e = G[x][i];
		if (e.to == p || e.d != 0)
			continue;
		dfs2(G, o, e.to, x, i);
	}
	if (p == -1)
		return;
	if (o[x] % 2 == 0) {
		G[p][j].d = 1;
		o[p]++;
		G[x][G[p][j].c].d = -1;
	} else {
		G[p][j].d = -1;
		G[x][G[p][j].c].d = 1;
		o[x]++;
	}
}
