        int a, b; cin >> a >> b; a--; b--;
        if(!UF.same(a, b)) {
            UF.unite(a, b);
            TREE[a].pb(b);
            TREE[b].pb(a);
        }else{
            // 全域木に入らない辺の向きを先に決める
            ans.pb({a, b});
            cost[a]++;
        }
    }

    dfs();
    for(auto [x, y] : ans){
        cout << x+1 << " " << y+1 << endl;
