#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<ll, ll> P;

int root = 0;
vector<vector<int> > g, parent;
vector<int> depth, deg, rev, leaf;
vector<bool> used;
vector<P> es;

void dfs(int v, int p, int d){
    parent[0][v] = p;
    depth[v] = d;
    used[v] = true;
    for(auto u : g[v]){
        if(used[u]) continue;
        dfs(u, v, d+1);
    }
}

void init(){
    int n = g.size();
    parent.resize(31, vector<int>(n));
    depth.resize(n);
    used.resize(n);
    dfs(root, -1, 0);
    for(int k=0;k<30;k++){
        for(int i=0;i<n;i++){
            if(parent[k][i] < 0) parent[k+1][i] = -1;
            else parent[k+1][i] = parent[k][parent[k][i]];
        }
    }
}

int lca(int u, int v){
    if(depth[u] > depth[v]) swap(u, v);
    for(int k=0;k<30;k++){
        if(((depth[v] - depth[u]) >> k) & 1){
            v = parent[k][v];
        }
        if(u == v) return u;
    }
    for(int k=29; k>=0; k--){
        if(parent[k][u] != parent[k][v]){
            u = parent[k][u];
            v = parent[k][v];
        }
    }
    return parent[0][u];
}

void dfs2(int v){
    for(auto u : g[v]){
        if(parent[0][u] == v){
            dfs2(u);
            rev[v] += rev[u];
        }
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    g.resize(n);
    deg.resize(n);
    rev.resize(n);
    for(int i=0;i<m;i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
        es.push_back(P(a,b));
        deg[a]++;
    }
    if(m%2){
        cout << -1 << endl;
        return 0;
    }
    init();
    vector<int> odd;
    for(int i=0;i<n;i++){
        if(deg[i]%2) odd.push_back(i);
    };
    for(int i=0;i<int(odd.size());i+=2){
        int u = odd[i], v = odd[i+1], w;
        w = lca(u, v);
        rev[u]++;
        rev[v]++;
        rev[w]-=2;
    }
    dfs2(root);
    for(int i=0;i<m;i++){
        int a, b, u, v;
        a = es[i].first;
        b = es[i].second;
        if(depth[a] < depth[b]){
            u = a; v = b;
        }
        else{
            u = b; v = a;
        }
        if(rev[v]%2 && u == parent[0][v]) swap(a, b);
        cout << a+1 << " " << b+1 << endl;
    }
    return 0;
}

