	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].emplace(b[i]);
		g[b[i]].emplace(a[i]);
	}

	std::set<int> s[2];
	REP(i, n) s[g[i].size() % 2].insert(i);

	if (m % 2 == 1) {
		OUT(-1)BR;
		return 0;
	}

	V<PAIR> ans;
	while (!s[1].empty()) {
		int root = *s[1].begin();
		std::stack<int> st; st.emplace(root);
		std::set<PAIR> set;
		while (!st.empty()) {
			int now = st.top();
			int to = [&] {
				for (auto& x : g[now]) {
					if (set.count(std::minmax({ x, now }))) continue;
					return x;
				}
				return -1ll;
			}();
			if (to == -1) {
				st.pop();
				if (!st.empty()) {
					set.erase(std::minmax({ st.top(), now }));
				}
			}
			else {
				st.emplace(to);
				set.insert(std::minmax({ now, to }));
				if (s[1].count(to) && st.size() % 2 == 1) {
					break;
				}
			}
		}
		if (st.empty()) break;

		V<int> v; v.reserve(st.size());
		while (!st.empty()) {
			v.emplace_back(st.top()); st.pop();
		}
		s[1].erase(v.front());
		s[1].erase(v.back());
		for (int i = 1; i < v.size(); i += 2) {
			ans.emplace_back(v[i], v[i - 1]);
			ans.emplace_back(v[i], v[i + 1]);
			g[v[i]].erase(v[i - 1]);
			g[v[i]].erase(v[i + 1]);
		}
	}
	while (!s[0].empty()) {
		int root = *s[0].begin();
		if (g[root].size() == 0) {
			s[0].erase(root);
			continue;
		}
		std::stack<int> st; st.emplace(root);
		std::set<PAIR> set;
		while (!st.empty()) {
			int now = st.top();
			int to = [&] {
				for (auto& x : g[now]) {
					if (set.count(std::minmax({ x, now }))) continue;
					return x;
				}
				return -1ll;
