    node.resize(n);
    for(int i=0; i<n; i++){
      node[i].parent=i;
      node[i].rank=0;
      node[i].size=1;
    }
  }

  int find(int x){  //return root node of x
    if(node[x].parent == x) return x;
    else{
      return node[x].parent = find(node[x].parent);
    }
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }

  int size(int at){
    return node[find(at)].size;
  }

  void unite(int x, int y){
    x = find(node[x].parent);
    y = find(node[y].parent);

    if(x==y) return;

    if(node[x].rank < node[y].rank){
      node[x].parent = y;
      node[y].size += node[x].size;
    }else if(node[x].rank > node[y].rank){
      node[y].parent = x;
      node[x].size += node[y].size;
    }else{
      node[x].rank++;
      unite(x,y);
    }
  }
};


int main(){
  int n,m;
  cin >> n,m;

  vector<pair<int,int>> e(m);
  vector<vector<int>> g(n);

  for(int i=0; i<m; i++){
    int a,b;
    cin >> a,b;
    a--; b--;
    e[i] = {a,b};
    g[a].push_back(i);
    g[b].push_back(i);
  }

  if(m % 2 != 0){
    println(-1);
    return 0;
  }

  UnionFindTree uft(n);

  vector<bool> tree_edge(m, false);
  for(int i: range(m)){
    if(uft.same(e[i].first, e[i].second)) continue;
    uft.unite(e[i].first, e[i].second);
    tree_edge[i] = true;
  }

  vector<int> out(n, 0);

  for(int i: range(m)){
    if(tree_edge[i]) continue;
    out[e[i].first]++;
  }

  vector<int> dir(m, 0);
  function<int(int, int, int)> f = [&](int pos, int par, int i) -> int{
    int& o = out[pos];
    for(auto ei: g[pos]){
      if(tree_edge[ei] == false) continue;
      int to = e[ei].first ^ e[ei].second ^ pos;
      if(to == par) continue;
      o += f(to, pos, ei);
    }

    if(par==-1) return 0;

    if(o%2){
      out[pos]++;
      if(e[i].first == pos){ // pos-par
        dir[i] = 0;
      }else{ // par-pos
        dir[i] = 1;
      }
      return 0;
    }else{
      if(e[i].first == pos){ // pos-par
        dir[i] = 1;
      }else{ // par-pos
        dir[i] = 0;
      }
      return 1;
    }
  };

  f(0, -1, -1);

  for(int i: range(m)){
    if(dir[i]) swap(e[i].first, e[i].second);
    e[i].first++;
    e[i].second++;
  }

  println(join(e, "\n"));

  return 0;
}

