int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;

	int u, v;
	vector<vector<Edge<int>>> edge(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		edge[u - 1].emplace_back(v - 1);
		edge[v - 1].emplace_back(u - 1);
	}

	bool flag = true;
	vector<pair<int, int>> ans;
	vector<int> out(N), visited(N);
	priority_queue<int, vector<int>, greater<int>> que;
	que.emplace(0);

	while (!que.empty()) {

		int now = que.top();
		que.pop();
		if (visited[now]) continue;
		visited[now] = 1;

		int cnt = 0;
		for (const auto &e : edge[now]) {
			if (!visited[e.to] && now < e.to) cnt++;
		}

		if (cnt == 0 && out[now] % 2 != 0) {
			flag = false;
		}
		else {

			int cnt2 = out[now] % 2;
			vector<int> memo;

			for (const auto &e : edge[now]) {
				if (now < e.to) {
					if (cnt2 > 0) {
						out[now]++;
						ans.emplace_back(now, e.to);
						cnt2--;
					}
					else {
						out[e.to]++;
						ans.emplace_back(e.to, now);
					}
				}
				if(!visited[e.to]) memo.emplace_back(e.to);
			}

			for (const auto &e : memo) que.emplace(e);

		}
	}

	if (flag) for (const auto &e : ans) cout << e.first + 1 << " " << e.second + 1 << "\n";
	else cout << -1 << "\n";

	return 0;
}

