template <typename F>
auto fix(F&& f) {
	return [f = std::forward<F>(f)](auto&&... args) {
		return f(f, std::forward<decltype(args)>(args)...);
	};
}

int main() {
	int n, m;
	std::cin >> n >> m;

	if (m % 2 == 1) {
		for (int i = 0, x; i < 2 * m; ++i)
			std::cin >> x;

		std::cout << -1 << std::endl;
		return 0;
	}

	std::vector<std::unordered_set<int>> edges(n);

	for (int i = 0; i < m; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a, --b;

		edges[a].insert(b);
		edges[b].insert(a);
	}

	std::vector<std::pair<int, int>> ans;
	ans.reserve(m);

	std::vector<bool> hasDebt(n);

	auto solve = fix([&](auto f, int cur) -> void {
		while (!edges[cur].empty()) {
			int next = *edges[cur].begin();

			if ((edges[cur].size() == 1 && !hasDebt[cur]) || ((edges[next].size() == 1 && hasDebt[next]))) {
				ans.emplace_back(next, cur);
				hasDebt[next] = !hasDebt[next];
			}
			else {
				ans.emplace_back(cur, next);
				hasDebt[cur] = !hasDebt[cur];
			}

			edges[cur].erase(next);
			edges[next].erase(cur);

			f(f, next);
		}
	});

	solve(0);

	for (auto&& b : hasDebt) {
		if (b || ans.size() != m) {
			throw std::out_of_range("");
		}
	}

	for (auto&& p : ans)
		std::cout << p.first + 1 << " " << p.second + 1 << std::endl;
}

