vector<vector<int>> construct(const vector<vector<int>> &adj) {
    int n = adj.size();
    vector<int> deg(n);
    for (int i = 0; i < n; i++) deg[i] = adj[i].size();
    set<pair<int, int>> es, reserve;
    vector<bool> visited(n);
    for (int i = 0; i < n; i++) {
        for (int a : adj[i]) {
            if (i < a) {
                es.insert({i, a});
            }
        }
    }
    vector<vector<int>> ret(n);
    auto reserve_edge = [&](int a, int b) {
        reserve.insert({min(a, b), max(a, b)});
    };
    auto add_edge = [&](int a, int b) {
        ret[a].push_back(b);
    };
    function<void(int)> dfs = [&](int v) {
        for (int s : adj[v]) {
            if (!visited[s]) {
                reserve_edge(s, v);
                visited[s] = true;
                dfs(s);
            }
        }
    };
    visited[0] = true;
    dfs(0);
    for (auto &e : es) {
        if (!reserve.count(e)) {
            add_edge(e.first, e.second);
        }
    }
    for (auto &e : reserve) {
        int a = e.first, b = e.second;
        if (ret[a].size() & 1) {
            add_edge(a, b);
        } else {
            add_edge(b, a);
        }
    }
    for (int i = 0; i < n; i++) {
        assert(ret[i].size() % 2 == 0);
    }
    return ret;
}

