  cin >> N >> M;

  for (int i = 0; i < M; i++) {
    int A, B;
    cin >> A >> B;
    adj[A].push_back(B);
    adj[B].push_back(A);

    mark[getKey(A, B)] = 1;
  }

  if (M % 2 != 0) {
    cout << -1 << endl;
    return 0;
  }

  for (int i = 1; i <= N; i++) {
    color[i] = 1;
    vcount[i] = adj[i].size();
  }

  for (int i = 1; i <= N; i++) {
    if (vcount[i] == 0) {
      color[i] = 0;
    } else if (color[i] && vcount[i] >= 2 && vcount[i] % 2 == 0) {
      solve(i);
    }
  }

  bool flag = true;
  for (int i = 1; i <= N; i++) {
    if (vcount[i] != 0) {
      flag = false;
      break;
    }
  }

  if (flag) {
    for (int i = 0; i < M; i++) {
      cout << result[i].first << " " << result[i].second << endl;
    }
  } else {
    cout << -1 << endl;
  }

  return 0;
}

