/* Bridges */

int bridges_dfs(int now, int path, vector<vector<pair<int,int> > > &way,
                vector<int> &visited, vector<int> &sum, vector<bool> &bridges_flag){
  int res_sum = 0;

  visited[now] = 1;

  for(auto p : way[now]) {
    if(p.second == path) continue;

    if(visited[p.first] == 1){
      sum[p.first]--;
      sum[now]++;
      bridges_flag[p.second] = false;
    }else if(visited[p.first] == 0){
      int res = bridges_dfs(p.first, p.second, way, visited, sum, bridges_flag);
      res_sum += res;
      if(res > 0) bridges_flag[p.second] = false;
    }
  }

  visited[now] = 2;
  return res_sum + sum[now];
}

//無向辺 & 多重辺考慮
vector<bool> bridges(int n, const vector<pair<int,int>> &path){
  vector<vector<pair<int,int>>>  way(n);
  vector<int> visited(n, 0), sum(n, 0);
  vector<bool> bridges_flag(path.size(), true);

  for(int i=0; i<(int)path.size(); i++){
    const auto &e = path[i];
    way[e.first].push_back({e.second, i});
    way[e.second].push_back({e.first, i});
  }

  bridges_dfs(0, -1, way, visited, sum, bridges_flag);

  return bridges_flag;
}

/* UnionFind */

struct UnionFind{
  vector<int> data;
  UnionFind(int s):data(s, -1) {}

  int root(int x){
    if(data[x] < 0) return x;
    return data[x] = root(data[x]);
  }

  bool set(int x,int y){
    x = root(x); y = root(y);
    if(x == y) return false;
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  bool check(int x, int y){
    return root(x) == root(y);
  }

  int size(int x){
    return -data[root(x)];
  }
};




