struct UF{
    int n;
    vector<int> par;
    UF(int n) : n(n) {
        for(int i = 0; i < n; i++) par.push_back(i);
    }
    int find(int a){
        if(a != par[a]) par[a] = find(par[a]);
        return par[a];
    }
    void join(int a, int b){
        par[find(a)] = find(b);
    }
};

vector<vector<int> > tree;
vector<pair<int,int> > ans;
vector<int> deg;

void dfs(int v, int p){
	for(int w : tree[v]){
		if(w == p) continue;
		dfs(w, v);
	}
	if(p >= 0){
		if(deg[v] & 1){
			deg[v] ^= 1;
			ans.push_back({v, p});
		} else {
			deg[p] ^= 1;
			ans.push_back({p, v});
		}
	}
}

