	deg.resize(n, 0);
	for(int i = 0; i < m; i++){
		int a, b;
		cin >> a >> b;
		a--; b--;
		if(uf.find(a) == uf.find(b)){
			ans.emplace_back(a, b);
			deg[a]++;
		} else {
			uf.join(a, b);
			tree[a].push_back(b);
			tree[b].push_back(a);
		}
	}
	dfs(0, -1);
	for(auto g : ans){
		cout << g.first + 1 << " " << g.second + 1 << '\n';
	}
}

