void add(int x, int y) {
	if (ans.find(mp(y, x)) != ans.end()) {
		ans.erase(mp(y, x));
		deg[y] ^= 1;		
	}
	ans.insert(mp(x, y));
	deg[x] ^= 1;
}

void dfs(int x, int p = -1) {
	u[x] = 1;
	for (int y : e[x]) {
		if (y == p) continue;
		if (u[y] == 2) continue;
		if (u[y]) {
			add(y, x);
		} else {
			dfs(y, x);
			if (deg[y]) {
				add(y, x);
			} else {
				add(x, y);
			}
		}
	}
	u[x] = 2;
}

