#define rep(i, n) for(int i = 0; i < (n); i++)
using ULL = unsigned long long;


void solve() {
	vector<pair<int, int>> ans;

	int n, m; cin >> n >> m;
	int d[100001] = {};
	int nd[100001] = {};
	bool dd[100001] = {};
	vector<pair<int, int>> e;
	rep(i, m) {
		int a, b; cin >> a >> b;
		if (a > b) swap(a, b);
		e.push_back({ a,b });
	}

	if (m % 2 == 1) { cout << -1 << endl; return; }

	sort(e.begin(), e.end());
	rep(i, e.size()) {
		if (e[i].first != 1 && d[e[i].first] == 0) {
			d[e[i].first] = e[i].second;
			nd[e[i].second]++;
		}
		else if (d[e[i].second] == 0) {
			d[e[i].second] = e[i].first;
			nd[e[i].first]++;
		}
		else {
			ans.push_back({ e[i].first,e[i].second });
			dd[e[i].first] = !dd[e[i].first];
		}
	}

	stack<int> st;
	for(int i = 2; i <= n; i++) {
		st.push(i);
		while (!st.empty()) {
			int p = st.top(); st.pop();
			if (p == 1) continue;
			if (nd[p] != 0) continue;

			if (dd[p]) {
				ans.push_back({ p, d[p] });
				dd[p] = !dd[p];
			}
			else {
				ans.push_back({ d[p],p });
				dd[d[p]] = !dd[d[p]];
			}
			st.push(d[p]);
			nd[d[p]]--;
			d[p] = 0;
		}
	}
	rep(i, ans.size()) {
		cout << ans[i].first << " " << ans[i].second << endl;
	}
}

int main() {

	solve();

	return 0;
}

