	stack<pair<int, vector<int>>> que;
	que.emplace(0, vector<int>());
	while (!que.empty()) {

		int now = que.top().first;
		auto memo = que.top().second;
		que.pop();
		visited[now] = 1;
		memo.emplace_back(now);
