            graph[from[i]].push_back(i);
            graph[to[i]].push_back(i);
        }
    }

    dfs(1,0,-1);

    for(int i=1; i<=m; i++){
        cout << to[i] << ' ' << from[i] << '\n';
    }

    return 0;
