using namespace std;
bool used[100000];
vector<pair<int, int> > graph[100001];
int degs[100001];
int main() {
    ios::sync_with_stdio(false);
    if (fopen("input.in", "r")) {
        freopen("input.in", "r", stdin);
        freopen("output.out", "w", stdout);
    }
    int n, m;
    cin >> n >> m;

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(make_pair(b, i));
        graph[b].push_back(make_pair(a, i));
        degs[a]++;
        degs[b]++;
    }
    if (m % 2) {
        cout << -1 << endl;
        return 0;
    }
    bool done = false;
    int cur = 0;
    set<int> notDone;
    int small = 0;
    for (int i = 1; i <= n; i++) {
        if ((degs[i] < degs[cur] || degs[cur] == 0) && degs[i] % 2 == 0 &&
            degs[i] != 0)
            cur = i;
        if (degs[i] != 0 && (degs[i] < degs[small] || degs[small] == 0))
            small = i;
        if (degs[i] != 0) notDone.insert(i);
    }

    while (!done) {
        done = true;
        if (degs[cur] == 0) cur = small;
        int newCur = cur;
        int numDegs = degs[newCur];
        cur = 0;
        small = 0;
        int counter = 0;
        for (auto j : graph[newCur]) {
            if (!used[j.second]) {
                counter++;
                if (numDegs % 2 == 1 && counter == numDegs - 1) break;
                used[j.second] = true;
                cout << newCur << " " << j.first << endl;
                degs[j.first]--;
                degs[newCur]--;
                if ((degs[j.first] < degs[cur] || degs[cur] == 0) &&
                    degs[j.first] % 2 == 0 && degs[j.first] != 0) {
                    done = false;
                    cur = j.first;
                }
                if (degs[j.first] == 0) notDone.erase(j.first);
            }
        }
        if (done) {
            for (auto i : notDone) {
                // cout << degs[i] << endl;

                if ((degs[i] < degs[cur] || degs[cur] == 0) &&
                    degs[i] % 2 == 0 && degs[i] != 0) {
                    cur = i;
                    done = false;
                }

                if ((degs[i] < degs[small] || degs[small] == 0)) small = i;
            }
        }
    }
}

