        E[a - 1].push_back(b - 1);
        E[b - 1].push_back(a - 1);
        cnt[a - 1]++;
        cnt[b - 1]++;
        usedEdge[make_pair(min(a - 1, b - 1), max(a - 1, b - 1))] = false;
    }

    queue<int> q;
    vector<bool> used(n, false);
    vector<pair<int, int>> ans;
    for(int i = 0; i < n; i++){
        if(cnt[i] == 1){
