            while(used[index]){
                index++;
            }
            for(auto e: E[index]){
                int small = min(e, index);
                int big = max(e, index);
                if(!usedEdge[make_pair(small, big)]){
                    if(cnt[index] == 1){
                        used[index] = true;
                        finish++;
                        if(even[index] % 2 == 0){
                            ans.push_back(make_pair(e, index));
                            even[e]++;
