                        else{
                            finish++;
                            used[e] = true;
                        }
                    }
                    else if(cnt[e] == 1){
                        q.push(e);
                        break;
                    }
                }
            }
        }
        else{
            int temp = q.front();
            q.pop();
            if(used[temp]){
                continue;
            }
            used[temp] = true;
            finish++;
            for(auto e: E[temp]){
                int small = min(e, temp);
                int big = max(e, temp);
                if(!usedEdge[make_pair(small, big)]){
                    if(even[temp] % 2 == 0){
                        ans.push_back(make_pair(e, temp));
                        even[e]++;
                    }
                    else{
                        ans.push_back(make_pair(temp, e));
                        even[temp]++;
                    }

                    usedEdge[make_pair(small, big)] = true;
                    cnt[temp]--;
                    cnt[e]--;
                    if(cnt[e] == 0){
                        if(even[e] % 2 != 0){
                            cout << -1 << endl;
                            return 0;
                        }
                        else{
                            finish++;
                            used[e] = true;
                        }
                    }
                    else if(cnt[e] == 1){
                        q.push(e);
                    }
                }
            }
        }
    }

    for(auto temp: ans){
        cout << temp.first + 1 << " " << temp.second + 1 << endl;
    }

    return 0;
}

