using namespace std;

unordered_map<long, unordered_set<long>> original_joint;

unordered_map<long, bool> in_tree;
unordered_map<long, unordered_set<long>> tree;

unordered_map<long, long> dezisuu;

void make_tree(long current) {
  in_tree[current] = true;
  for (auto it: original_joint[current]) {
    if (in_tree[it]) continue;
    tree[current].insert(it);
    make_tree(it);
  }
}

void adjust(long parent, long current) {
  for (auto it: tree[current]) {
    adjust(current, it);
  }
  if (parent == 0) return;
  if (dezisuu[current] % 2 == 1) {
    cout << current << " " << parent << endl;
    dezisuu[current]++;
  } else {
    cout << parent << " " << current << endl;
    dezisuu[parent]++;
  }
}

void solve() {
  long N, M;
  cin >> N >> M;

  if (M % 2 == 1) {
    cout << -1 << endl;
    return;
  }

  rep (i, M) {
    long A, B;
    cin >> A >> B;
    original_joint[A].insert(B);
    original_joint[B].insert(A);
  }

  make_tree(1);

  for (auto it: original_joint) {
    long from = it.first;
    for (auto to: it.second) {
      if (to < from) continue;
      if (tree[from].count(to) != 0 or tree[to].count(from) != 0) continue;
      cout << from << " " << to << endl;
      dezisuu[from]++;
    }
  }

  adjust(0, 1);
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

