	if (M%2!=0){
		cout << "-1\n";
		return 0;
	}
	for (int i = 1; i <= M; ++i){
		cin >> A >> B;
		if (A > B) swap(A,B);
		EdgeList.push_back(pli(pl(A,B),0));
		AdjList[A].push_back(i-1);
		AdjList[B].push_back(i-1);
	}
	for (int i = 1; i <= N; ++i){
		if (!check[i]){
			dfs(i);
		}
	}
	for (int i = 1; i <= N; ++i){
		if (out_degree[i]%2!=0){
			found = 0;
			dfs2(i,-1);
			out_degree[i]++;
		}
	}
	for (int i = 0; i < M; ++i){
		if (EdgeList[i].second == 1){
			cout << EdgeList[i].first.first << ' ' << EdgeList[i].first.second << '\n';
		}
