int main() {
	int n, m; std::cin >> n >> m;
	std::vector<std::vector<int>> nodes(n);
	for (auto i = 0; i < m; ++i) {
		int a, b; std::cin >> a >> b;
		nodes[a - 1].push_back(b - 1);
		nodes[b - 1].push_back(a - 1);
	}
	std::vector<int> parity(n, -1);
	std::stack<int> stack;
	auto can_make = true;
	for (auto i = 0; i < n; ++i) {
		if (nodes[i].size() % 2 == 1) {
			parity[i] = 0;
			stack.push(i);
		}
	}
	if (stack.empty()) stack.push(0);
	while (!stack.empty()) {
		auto current = stack.top(); stack.pop();
		for (const auto next : nodes[current]) {
			if (parity[next] == -1) {
				parity[next] = (parity[current] + 1) % 2;
				stack.push(next);
			}
			else if (parity[next] == parity[current]) {
				can_make = false;
				break;
			}
		}
		if (!can_make) {
			break;
		}
	}
	if (can_make) {
		for (auto i = 0; i < n; ++i) {
			if (parity[i] == 0) for (const auto next : nodes[i]) {
				std::cout << i + 1 << " " << next + 1 << "\n";
			}
		}
	}
	else {
		std::cout << -1 << "\n";
	}
}

