void construct_tree(vector<vector<int>> &graph, map<pair<int, int>, int> &memo,vector<vector<int>> &tree)
{
    vector<bool> flag(graph.size(), false);
    stack<int> s;
    flag[0] = true;
    s.push(0);
    while (!s.empty())
    {
        int current = s.top();
        bool no = true;
        for (int i = 0; i < graph[current].size(); i++)
        {
            int next = graph[current][i];
            if (!flag[next])
            {
                flag[next] = true;
                s.push(next);
                tree[current].push_back(next);
                memo[{min(current, next), max(current, next)}] = 0;
                no = false;
                break;
            }
        }
        if (no)
        {
            s.pop();
        }
    }
}

