bool visited[202020];
int dir[202020];


ll dfs(ll now, ll par, Graph &G){
	if(visited[now]) return 0;
	//dump(now)
	visited[now] = true;
	for(auto next: G[now]){
		dfs(next.to, now, G);
	}

	ll dezi = 0;
	ll par_idx = -1;
	for(auto next: G[now]){
		if(next.to == par){
			par_idx = next.idx;
			continue;
		}
		if(now < next.to && dir[next.idx]==1) dezi++;
		if(now > next.to && dir[next.idx]==0) dezi++;
	}

	//dump(dezi)

	if(par_idx == -1) return dezi;

	if(dezi%2==0){
		if(now > par) dir[par_idx] = 1;
		else dir[par_idx] = 0;
	}else{
		if(now > par) dir[par_idx] = 0;
		else dir[par_idx] = 1;
	}

	return 0;
}

