int dfs(int cur,int pre) {
	int lef=-1;
	while(E[cur].size()) {
		int x=*E[cur].begin();
		E[cur].erase(x);
		E[x].erase(cur);
		int y=dfs(x,cur);

		if(y!=-1) {
			if(lef==-1) lef=y;
			else {
				V.push_back({cur,lef});
				V.push_back({cur,y});
				lef=y;
			}
		}
	}

	if(lef!=-1) {
		if(pre!=-1) {
			V.push_back({cur,pre});
			V.push_back({cur,lef});
			return -1;
		}
	}
	return cur;

}

