ll odd_count_memo[500005];
bool check[500005];

void dfs(ll v){
    check[v] = true;
    for(int i=0;i<G1[v].size();i++){
        ll nv = G1[v][i];
        if(check[nv])continue;
        G2[v].pb(nv);
        G2[nv].pb(v);
        dfs(nv);
    }
    return;
}

ll table_search(ll a,ll b){
    ll idx = lb(table,table+m,P(a,b)) - table;
    if(table[idx].first == a && table[idx].second == b){
        return idx;
    }else{
        return table_search(b,a);
    }
}
ll count_odd(ll v,ll p){
    ll sum = 0;
    if(odd_count_memo[v] != -1){
        return odd_count_memo[v];
    }
    if(even[v] % 2 == 1)sum += 1;
    for(int i=0;i<G2[v].size();i++){
        ll nv = G2[v][i];
        if(nv == p)continue;
        sum += count_odd(nv,v);
    }
    odd_count_memo[v] = sum;
    return sum;
}
void solve_dfs(ll v,ll p){
    //pe(v);p(p);
    for(int i=0;i<G2[v].size();i++){
        ll nv = G2[v][i];
        if(nv == p)continue;
        if(count_odd(nv,v) % 2 == 1){
            ll idx = table_search(nv,v);
            swap_count[idx]++;
            solve_dfs(nv,v);
        }else{
            solve_dfs(nv,v);
        }
    }
    return;
}



