		For ( u, 1, n ) {
			if (Deg[u] & 1) {
				ll Z = 0, T, v;
				For ( i, 1, Ve[u].size() ) 
					v = Ve[u][i - 1], Z += (Deg[v] & 1), T = Z;
				if (Z & 1) {
					For ( i, 1, Ve[u].size() ) {
						v = Ve[u][i - 1];
						if (Deg[u] % 2 == 0 && T == 1) break;
						if (Deg[u] && (Deg[v] & 1)) {
							E[v].push_back(u);
							--Deg[u], ++Deg[v];
						} else E[u].push_back(v);
					}
				} else {
					For ( i, 1, Ve[u].size() ) {
						v = Ve[u][i - 1];
						if (Deg[u] % 2 == 0 && T == 1) break;
						if (Deg[u] && (Deg[v] & 1)) {
							E[v].push_back(u);
							--Deg[u], ++Deg[v]; 
						} else E[u].push_back(v);
					}
				}
			} else {
				ll Z = 0, T, v;
				For ( i, 1, Ve[u].size() ) 
					v = Ve[u][i - 1], Z += (Deg[v] & 1), T = Z;
				if (!(Z & 1)) {
					For ( i, 1, Ve[u].size() ) {
						v = Ve[u][i - 1];
						if (Deg[u] % 2 == 0 && T == 1) break;
						if (Deg[u] && (Deg[v] & 1)) {
							--T;
							E[v].push_back(u);
							--Deg[u], ++Deg[v];
						} else E[u].push_back(v);
					}
				} else {
					For ( i, 1, Ve[u].size() ) {
