void dfs(int u, int prt) {
    seen[u] = true;

    int index = -1;
    for (const auto& p : conn[u]){
        if (p.first == prt) {
            index = p.second;
            continue;
        }
        if (seen[p.first]) continue;
        dfs(p.first, u);
    }

    if (out[u] & 1) {
        out[a[index]] --;
        out[b[index]] ++;
        direction[index] = 1;
    }
}

