    swap(h[x], h[y]);
    to[h[x]] = x;
    to[h[y]] = y;
}
void up(int x) {
    int y = x / 2;
    while (y && d[h[x]] < d[h[y]]) {
        SWAP(x, y);
        x = y;
        y /= 2;
    }
}
void down(int x) {
    int y = x + x;
    while ((y <= h[0] && d[h[x]] > d[h[y]] ) ||(y < h[0] && d[h[x]] > d[h[y + 1]])) {
        if (y < h[0] && d[h[y + 1]] < d[h[y]]) y++;
        SWAP(x, y);
        x = y;
        y += y;
    }
}
