int dfs(ll now, ll par){
	ll out = 0;
	visited[now] = true;
	REP(i, G[now].size()){
		ll next = G[now][i];
		if(next == par) continue;
		if(visited[next]){
			ll dir = mp[{now, next}];
			if(dir == 0){
				out++;
				mp[{now, next}] = 1;
				mp[{next, now}] = -1;
			}
		}else{
			out += dfs(next, now);
		}
	}

	if(par == -1) return (out+1)%2;

	if(out%2 == 0){
		mp[{par, now}] = 1;
		mp[{now, par}] = -1;
		return 1;
	}else{
		mp[{par, now}] = -1;
		mp[{now, par}] = 1;
		return 0;
	}
	return (out+1)%2;
}

