class solver{
    istream& is;
    ostream& os;

    E_Set outE, E;
    ll N, M;
    vector<bool> vis;
    vector<pair<int, int>> sE;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    void make_spanning(int v){
        vis[v] = true;
        for (auto &&u : E[v]) {
            if(vis[u]) { continue; }
            sE.emplace_back(v, u);
            make_spanning(u);
        } // end u
    }

    void run(){
        is >> N >> M;
        if(!is) return;
        for (int i = 0; i < M; ++i) {
            int A, B; is >> A >> B;
            E[A].insert(B); E[B].insert(A);
        } // end i
        vis.resize(N, false);
        if(N % 2) {
            cout << -1 << endl; return;
        }
        make_spanning(1);

        for(auto&& p = sE.rbegin(); p != sE.rend(); p++){
            int v, u;
            tie(v, u) = *p;
            for (auto &&t : E[u]) {
                if(t == v) continue;
                outE[t].insert(u);
                E[t].erase(u);
            } // end t
            E[v].erase(u);
            E.erase(u);
            if(outE[u].size() % 2){
                outE[u].insert(v);
            }
            else{
                outE[v].insert(u);
            }
        }
        for (auto &&et : outE) {
            int u = et.first;
            for (auto &&v : et.second) {
                cout << u << ' ' << v << endl;
            } // end v
        } // end et
    }
};

