{
  int n, m;
  cin >> n >> m;
  graph g(n);
  REP(i, m)
  {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  bool visited[100000] = {};
  int size[100000] = {};
  REP(i, n)
  {
    size[i] = g[i].size();
  }

  if (m % 2 == 1)
  {
    cout << -1 << endl;
    return 0;
  }

  priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q;
  graph ans(n);
  q.push(make_pair(size[0], 0));
  while (!q.empty())
  {
    auto me = q.top();
    visited[me.second] = true;
    q.pop();
    int s = size[me.second];
    if (s == 0)
    {
      continue;
    }
    for (auto other : g[me.second])
    {
      if (size[other] == 0 || visited[other])
      {
        continue;
      }
      if (s % 2 == 0)
      {
        ans[me.second].push_back(other);
        size[other]--;
      }
      else
      {
        ans[other].push_back(me.second);
        size[me.second]--;
      }
