const int MOD = 1000000007, INF = 1111111111;
using namespace std;
using lint = long long;

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;

	if (M % 2 == 1) {
		cout << -1 << "\n";
		return 0;
	}

	int u, v;
	map<pair<int, int>, int> dir;
	vector<vector<int>> edge(N);
	vector<int> out(N);
	for (int i = 0; i < M; i++) {
		cin >> u >> v;
		u--, v--;
		edge[u].emplace_back(v);
		edge[v].emplace_back(u);
		if (v < u) swap(u, v);
		dir[{u, v}] = 1; // intial direction is u->v when u < v
		out[u] ^= 1;
	}

	struct graph {
		int now, prev, flip;
		graph(int now, int prev, int flip) :now(now), prev(prev), flip(flip) {}
	};
	stack<graph> que;
	que.emplace(0, -1, out[0] * -2 + 1);
	vector<int> visited(N);
	while (!que.empty()) {

		auto g = que.top();
		que.pop();
		visited[g.now] = 1;

		if (g.prev != -1) dir[minmax(g.prev, g.now)] *= g.flip;
		if (out[g.now]) g.flip *= -1;

		for (const auto &e : edge[g.now]) {
			if (!visited[e]) {
				que.emplace(e, g.now, g.flip);
