vector<ll> roots;
set<ll> rootset;
void bfs(ll start){
    queue<ll> q;
    bool visited[NODE_SIZE] = {};
    q.push(start);
    while(!q.empty()){
        ll now = q.front();
        q.pop();
        visited[now] = true;
        bool now_root = rootset.find(now) != rootset.end();
        for(ll next: edge[now]){
            if(visited[next]) continue;
            q.push(next);
            if(edge[next].size() % 2) continue;
            else if(now_root) continue;
            roots.push_back(next);
            rootset.insert(next);
        }
    }
}

void make_edge(){
    queue<ll> q;
    bool visited[NODE_SIZE] = {};
    for(ll start: roots){
        q.push(start);
    }
    while(!q.empty()){
        ll now = q.front();
        q.pop();
        if(visited[now]) continue;
        visited[now] = true;
        for(ll next: edge[now]) {
            if(visited[next]) continue;
            edge2[now].push_back(next);
            ll size = (ll) edge[next].size();

            for(ll nn: edge[next]){
                if(rootset.find(nn) != rootset.end()) {
                    size--;
                }
            }

            if(size % 2 == 0) {
                q.push(next);
            }
        }
    }
}

//DAGじゃなければ空のベクターを返すのでDAG判定も可能
vector<ll> tsort(vector<vector<ll>> g) {
    ll k = 0;
    vector<ll> in(N,0);
    vector<ll> ord(N);
    // 自分に繋がっているエッジの次数カウント
    for (auto es : g)
        for (auto e : es) in[e]++;
    queue<ll> q;
    for (ll i = 0; i < N; ++i)
        if (in[i] == 0) q.push(i);
    while (!q.empty()) {
        ll node = q.front();
        q.pop();
        ord[k++] = node;
        for (auto e : g[node])
            if (--in[e] == 0){
                q.push(e); //使ってもいいノードの追加
            }

    }
    return *max_element(in.begin(), in.end()) == 0 ? ord : vector<ll>();
}

