set<ll> graph[100010];
vector<ll> Circuit(ll startV){
    stack<ll> currentPath;
    vector<ll> circuit;
    currentPath.push(startV);
    ll currentV=startV;
    while(!currentPath.empty()){
        if(graph[currentV].size()!=0){
            currentPath.push(currentV);
            ll nextV=*(graph[currentV].begin());
            graph[currentV].erase(nextV);
            graph[nextV].erase(currentV);
            currentV=nextV;
        }else{
            circuit.push_back(currentV);
            currentV=currentPath.top();
            currentPath.pop();
        }
    }
    return circuit;
}
void Func(ll now,ll pre,ll g,vector<ll> &vs){
    vs.push_back(now);
    if(now==g){
        return;
    }
    for(auto v:graph[now]){
        if(v!=pre){
            Func(v,now,g,vs);
        }
    }
    vs.pop_back();
}
vector<ll> DeletePath(ll s,ll g){
    vector<ll> path;
    Func(s,-1,g,path);
    for(ll i=0;i<path.size()-1;i++){
        graph[path[i]].erase(path[i+1]);
        graph[path[i+1]].erase(path[i]);
    }
    return path;
}
