				dir[minmax(now, e)] ^= fliping;
				out[now] ^= fliping;
				out[e] ^= fliping;
				idx++;
				used[e] = idx;
				all_used = false;
				que.emplace(e);
				break;
			}
		}

		if (all_used) {
			for (const auto &e : edge[now]) {
				if (used[e] = used[now] - 1) {
					dir[minmax(now, e)] ^= fliping;
					out[now] ^= fliping;
					out[e] ^= fliping;
					if (!out[e]) fliping ^= 1;
					que.emplace(e);
					all_used = false;
				}
			}
		}

		if (all_used) exit(-1);

	}

	for (auto &e : dir) {
		if (e.second == 1) printf("%d %d\n", e.first.first + 1, e.first.second + 1);
		else printf("%d %d\n", e.first.second + 1, e.first.first + 1);
	}

	return 0;
}

