using vvi = vector<vector<int>>;

int N,M;

void solve(vset& ansg, vvi& tree, int idx) {
  REP(i,N) {
    if (tree[idx][i] == 1) solve(ansg, tree, i);
  }
  bool f = ansg[idx].size() % 2 == 0;
  REP(i, N) {
    if (tree[i][idx] == 1) {
      if (f)
        ansg[i].insert(idx);
      else
        ansg[idx].insert(i);
    }
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  cin >> N >> M;
  if (M % 2 != 0) {
    cout << -1 << endl;
    return 0;
  }
  auto edge = make_v<unordered_set<int>>(N);
  REP(i,M) {
    int a,b;
    cin >> a >> b;
    edge[a-1].insert(b-1);
    edge[b-1].insert(a-1);
  }
  auto tree = make_v<int>(N,N);
  auto done = make_v<int>(N);
  queue<int> q;
  q.push(0);
  done[0] = 1;
  while(q.size() > 0) {
    int v = q.front(); q.pop();
    for (auto& w : edge[v]) {
      if (done[w] == 0) {
        q.push(w);
        done[w] = 1;
        tree[v][w] = 1;
      }
    }
  }
  debug(tree);
  auto ansg = make_v<unordered_set<int>>(N);
  REP(i,N) {
    auto& es = edge[i];
    for (auto& v: es) {
      if (tree[i][v] == 0 && tree[v][i] == 0 && ansg[i].find(v) == ansg[i].end() && ansg[v].find(i) == ansg[v].end()) { // not in tree
        ansg[i].insert(v);
      }
    }
  }
  debug(ansg);
  solve(ansg, tree, 0);
  debug(ansg);
  stringstream ss;
  REP(i,N) {
    for (auto & v : ansg[i]) {
      ss << i+1 << " " << v+1 << endl;
    }
