void dfs1(int idx, int par) {
    vertex[idx] = 1;
    for (auto& nxt : G[idx]) {
        if (nxt.first == par)
            continue;
        if (!vertex[nxt.first]) {
            dfs1(nxt.first, idx);
            G2[idx].pb({nxt.first, nxt.second});
            node[nxt.second] = 1;
        }
    }
}

int dfs2(int idx, int par) {
    for (auto& nxt : G2[idx]) {
        if (nxt.first == par)
            continue;
        int tmp;
        if ((tmp = dfs2(nxt.first, idx)) % 2) {
            ans[nxt.second] = nxt.first;
        } else {
            ans[nxt.second] = idx;
            cnt[idx]++;
        }
    }
    return cnt[idx] % 2;
}

