void dfs(int v)
{
    if (vis[v] == 1)
        return;
    vis[v] = 1;
    for (int i = 0; i < graph[v].size(); i++)
    {
        int u = gg[graph[v][i]].a + gg[graph[v][i]].b - v;

        if (gg[graph[v][i]].v == 1)
            continue;

        if (curd[v] % 2 == 1)
