            ans.push_back({v, u});
            curd[v]++;
            gg[graph[v][i]].v = 1;
        }
        else
        {
            ans.push_back({u, v});
            curd[u]++;
            gg[graph[v][i]].v = 1;
        }
        dfs(u);
    }
}


