int N, M;
vector<vector<int>> tree, roads;
vector<bool> is_came;
vector<int> out;

void move(int now){
    is_came[now] = true;
    for(int i: roads[now]){
        if(!is_came[i]){
            tree[now].push_back(i);
            tree[i].push_back(now);
            move(i);
        }
    }
}

vector<pair<int, int>> change;

int dfs(int now, int back){
    int sum = out[now];
    for(int i: tree[now]){
        if(i != back){
            sum += dfs(i, now);
        }
    }
    if(sum % 2){
        change.push_back({min(now, back), max(now, back)});
    }
    return sum;
}

