        int A, B;
        cin >> A >> B;
        A--, B--;
        roads[A].push_back(B);
        roads[B].push_back(A);
        if(A > B){
            swap(A, B);
        }
        out[A]++;
        ans.insert({A, B});
    }
    move(0);
    dfs(0, -1);
    for(auto i: change){
        ans.erase({i.first, i.second});
        ans.insert({i.second, i.first});
    }
    for(auto i: ans){
        cout << i.first + 1 << " " << i.second + 1 << endl;
    }
}

