const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k, n_edge[MAX_N];
Graph graph[MAX_N];
bool visited[MAX_N];

void dfs(ll source){
    visited[source] = true;

    for (auto& e: graph[source]){
        if (visited[e.to]) continue;
        dfs(e.to);
        if (n_edge[e.to] % 2) prl2(e.to + 1, source + 1);
        else prl2(source + 1, e.to + 1), n_edge[source]++;
    }
}

void solve(){
    if (k % 2 == 1){prl(-1); return;}
    UnionFind uf(n);
    rep(i, k){
        ll a, b; in2(a, b); a--, b--;
        if (uf.root_find(a) == uf.root_find(b)){
            prl2(a + 1, b + 1);
            n_edge[a]++;
        }else{
            graph[a].pb({b, 1});
            graph[b].pb({a, 1});
            uf.unite(a, b);
        }
    }

    dfs(0);
}

int main(void){
    in2(n, k);
    // assert(x <= 50);
    solve();
    return 0;
}

