void kruskal(){
	for(int i=1;i<=m;i++){
		x=find(l[i].u);
		y=find(l[i].v);
		if(x==y) continue;
		if(x<y) fa[y]=x,to[++cnt]=l[i].v,nxt[cnt]=fir[l[i].u],fir[l[i].u]=cnt,deg[l[i].u]^=1,b[i]=0,k[l[i].v]=i;
		else fa[x]=y,to[++cnt]=l[i].u,nxt[cnt]=fir[l[i].v],fir[l[i].v]=cnt,deg[l[i].v]^=1,b[i]=1,k[l[i].u]=i;
		use[i]=1;
	}
	for(int i=1;i<=m;i++){
		if(use[i]==0) deg[l[i].u]^=1,b[i]=0;
	}
}

void dfs(int x,int f){
	fi[x][0]=f;
	dep[x]=dep[f]+1;
	for(int i=1;i<=19;i++) fi[x][i]=fi[fi[x][i-1]][i-1];
	for(int i=fir[x];i;i=nxt[i]){
		if(to[i]==f) continue;
		dfs(to[i],x);
	}
}

void Dfs(int x,int f){
	for(int i=fir[x];i;i=nxt[i]){
		if(to[i]==f) continue;
		Dfs(to[i],x);
		sc[x]^=sc[to[i]];
	}
	b[k[x]]^=sc[x];
}

int LCA(int x,int y){
	if(dep[x]<dep[y]) swap(x,y);
	for(int i=19;i;i--){
		if(dep[fi[x][i]]>=dep[y]){
			x=fi[x][i];
		}
	}
	if(x==y) return x;
	for(int i=19;i;i--){
		if(fi[x][i]!=fi[y][i]){
			x=fi[x][i];
			y=fi[y][i];
		}
	}
	return fi[x][0];
}


