template< typename T >
T prim(WeightedGraph< T > &g) {
  using Pi = pair< T, int >;
  T total = 0;
  vector< bool > used(g.size(), false);
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;
  que.emplace(0, 0);
  while(!que.empty()) {
    auto p = que.top();
    que.pop();
    if(used[p.second]) continue;
    used[p.second] = true;
    total += p.first;
    for(auto &e : g[p.second]) {
      que.emplace(e.cost, e.to);
    }
  }
  return total;
}
void dfs(vector<vector<int>> &g2, const vector<vector<int>> &tr, vector<int> &d2, int now, int prev) {
  for(int i=0;i<(int)(tr[now].size());++i) {
    dfs(g2, tr, d2, tr[now][i], now);
  }
  if(now == 0) return;
  if(d2[now] % 2) {
    g2[now].push_back(prev);
  } else {
    g2[prev].push_back(now);
    d2[prev]++;
  }
}
