template<bool Directed, class WeightType>
struct Graph{  
  int V;
  vector<unordered_map<int, WeightType>> E;
  Graph(){}
  Graph(const int v):V(v), E(v){};

  void connect(const int from, const int to, const WeightType w){
    E[from][to] = w;
    if(!Directed) E[to][from] = w;
  }

  void unconnect(const int from, const int to){
    E[from].erase(to);
    if(!Directed) E[to].erase(from);
  }

  WeightType getWeight(const int from, const int to)const
  { return E[from].count(to)?E[from][to]:1e+9; }

  bool isConnected(const int from, const int to)const
  { return E[from].count(to) != 0; }


};

