struct UnionFind {
    private:
    vector<int> par,rank;
    vector<ll> Size;
    public:
    UnionFind(int n){
        par.resize(n);
        rank.resize(n,0);
        Size.resize(n,1);
        rep(i,n){
            par[i]=i;
        }
    }
    int root(int x){
        if (par[x]==x){
            return x;
        }
        return par[x]=root(par[x]);
    }
    bool merge(int x, int y){
        x=root(x);
        y=root(y);
        if (x==y){
            return false;
        }
        if (rank[x]<rank[y]){
            swap(x,y);
        }
        if (rank[x]==rank[y]){
            ++rank[x];
        }
        par[y]=x;
        Size[x]+=Size[y];
        return true;
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    ll size(int x){
        return Size[root(x)];
    }
};

const int MAX=100010;

int N,M;
vector<int> cnt(MAX,0);
vector<vector<int>> G(MAX);
vector<edge> es;

void dfs(int v,int p){
    for (auto nv:G[v]){
        if (nv==p) continue;
        dfs(nv,v);
    }
    if (p==-1) return;
    if (cnt[v]%2==0){
        es.push_back(edge{p,v});
        ++cnt[p];
    }
    else {
        es.push_back(edge{v,p});
        ++cnt[v];
    }
}

int main(){
    cin >> N >> M;
    if (M%2==1){
        cout << -1 << endl;
        return 0;
    }
    UnionFind uf(N);
    rep(i,M){
        int a,b;
        cin >> a >> b;
        --a,--b;
        if (uf.same(a,b)){
            es.push_back(edge{a,b});
            cnt[a]++;
        }
        else {
            uf.merge(a,b);
            G[a].push_back(b);
            G[b].push_back(a);
        }
    }
    dfs(0,-1);
    rep(i,M){
        cout << ++es[i].from << ' ' << ++es[i].to << endl;
    }
}

