const li MOD = 1000000000949747713ll;


vector<pii> edges;
int cnt[MAXN];

vector<pii> g[MAXN];

set<pii> ver[MAXN];
int parent[MAXN];

void init_dsu(int n) {
    for (int i = 1; i <= n; ++i) {
        parent[i] = i;
    }
}

int get_parent(int v) {
    if (v == parent[v])
        return v;
    return parent[v] = get_parent(parent[v]);
}

void union_set(int a, int b) {
    a = get_parent(a);
    b = get_parent(b);
    if (a != b) {
        if (sz(ver[a]) < sz(ver[b]))
            swap(a, b);
        for (auto v:ver[b]) {
            ver[a].insert(v);
        }
        parent[b] = a;
    }
}

int A[MAXN], B[MAXN];
int val[MAXN];


int used[MAXN];

vector<pii> g2[MAXN];

void dfs(int v, int p) {
    used[v] = 1;
    for (pii x:g2[v]) {
        int to = x.fi;
        if (!used[to]) {
            dfs(to, x.se);
            val[v] ^= val[to];
        }
    }
    if (val[v] == 1) {
        assert(p != -1);
        swap(A[p], B[p]);
    }
}

void solve() {
    int n;
    cin >> n;
    int m;
    cin >> m;
    if (m % 2 == 1) {
        cout << -1;
        return;
    }
    for (int i = 1; i <= m; ++i) {
        cin >> A[i] >> B[i];
        if (rand() & 1)
            swap(A[i], B[i]);
        g[A[i]].pb({B[i], i});
        g[B[i]].pb({A[i], i});
        cnt[A[i]] ^= 1;
    }
    for (int i = 1; i <= m; ++i) {
        if (cnt[A[i]] && cnt[B[i]]) {
            cnt[A[i]] ^= 1;
            cnt[B[i]] ^= 1;
            swap(A[i], B[i]);
        }
    }
    init_dsu(n);
    for (int v = 1; v <= n; ++v) {
        for (pii x:g[v]) {
            int to = x.fi;
            if (cnt[to] == 1) {
                dout <<"add "<<v <<" "<<to<<endl;
                ver[v].insert({to, x.se});
            }
        }
    }
    for (int v = 1; v <= n; ++v) {
        for (pii x:g[v]) {
            int to = x.fi;
            if (cnt[v] == 0 && cnt[to] == 0) {
                union_set(v, to);

                g2[v].pb(x);
                g2[to].pb(x);
            }
        }
    }

    queue<int> q;
    for (int v = 1; v <= n; ++v) {
        if (cnt[v] == 0 && get_parent(v) == v) {
            q.push(v);
        }
    }

    for(int v=1;v<=n;++v){
        dout << v <<" "<<cnt[v]<<endl;
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        v = get_parent(v);
        dout <<v <<" : "<<sz(ver[v])<<endl;
        if (sz(ver[v]) > 1) {
            pii to1 = {-1, -1};
            while (!ver[v].empty()) {
                auto val = *ver[v].begin();
                ver[v].erase(ver[v].begin());
                if (cnt[val.fi] == 0)
                    continue;
                to1 = val;
                break;
            }
            if (to1.fi == -1)
                continue;
            pii to2 = {-1, -1};
            while (!ver[v].empty()) {
                auto val = *ver[v].begin();
                ver[v].erase(ver[v].begin());
                if (cnt[val.fi] == 0)
                    continue;
                if (val.fi == to1.fi)
                    continue;
                to2 = val;
                break;
            }
            if (to2.fi == -1) {
                ver[v].insert(to1);
                continue;
            }


            cnt[to1.fi] ^= 1;
            cnt[to2.fi] ^= 1;
            assert(cnt[to1.fi] == 0);
            assert(cnt[to2.fi] == 0);

            swap(A[to1.se], B[to1.se]);
            swap(A[to2.se], B[to2.se]);

            union_set(v, to1.fi);
            union_set(v, to2.fi);


            int v1;
            if (A[to1.se] == to1.fi) {
                v1 = B[to1.se];
            } else {
                v1 = A[to1.se];
            }
            val[v1] ^= 1;
            if (A[to2.se] == to2.fi) {
                v1 = B[to2.se];
            } else {
                v1 = A[to2.se];
            }
            val[v1] ^= 1;

            int id = to1.se;
            g2[A[id]].pb({B[id], id});
            g2[B[id]].pb({A[id], id});
            id = to2.se;
            g2[A[id]].pb({B[id], id});
            g2[B[id]].pb({A[id], id});

            q.push(v);
        }
    }

    for (int v = 1; v <= n; ++v) {
        if (cnt[v] == 1) {
            dout << "LAST " << endl;
            assert(false);
            cout << -1;
            return;
        }
    }

    dfs(1, -1);

    for(int i=1;i<=m;++i){
        cout <<A[i]<<" "<<B[i]<<"\n";
    }


}

