struct Edge {
	int to, dir;
	Edge() :to(0),dir(0){}
	Edge(int to, T dir) : to(to), dir(dir){}
};

vector<pair<int, int>> ans;
bool dfs(vector<vector<int>> &edges, int now, vector<int> visited, int N) {

	visited[now] = 1;

	int cnt = 0, two = 0;
	for (const auto &e : edges[now]) {
		if (e == 2) two++;
		if (e == 1) cnt++;
	}

	bool flag = true;
	if (two == 0 && cnt % 2 != 0) flag = false;
	else {
		int cnt2 = cnt % 2;
		vector<int> memo;
		for (int i = 0; i < N; i++) {
			if (edges[now][i] == 2) {
				if (cnt2 > 0) {
					edges[now][i] = 1;
					ans.emplace_back(now, i);
					edges[i][now] = -1;
					cnt2--;
				}
				else {
					edges[now][i] = -1;
					edges[i][now] = 1;
					ans.emplace_back(i, now);
				}
			}
			memo.emplace_back(i);
		}
		for (const auto &e : memo) if (!visited[e]) flag &= dfs(edges, e, visited, N);
	}

	return flag;

}

