using namespace std;

int n, m;
int deg[100005];
int a[100005], b[100005];
int par[100005];

vector<int> tedge[100005];

int f(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = f(par[x]);
	}
}

void dfs(int cur, int prev, int edgeid){
	for(auto id: tedge[cur]){
		int to = a[id] + b[id] - cur;
		if(to != prev){
			dfs(to, cur, id);
		}
	}
	if(edgeid == -1){
		return;
	}
	if(deg[cur] & 1){
		// point parent edge to cur
		a[edgeid] = prev;
		b[edgeid] = cur;
		deg[cur]++;
	}else{
		// point parent edge to parent
		a[edgeid] = cur;
		b[edgeid] = prev;
		deg[prev]++;
	}
}

int main(){
	scanf("%d %d", &n, &m);

	if(m & 1){
		printf("-1\n");
		return 0;
	}

	for(int i = 1; i <= n; i++){
		par[i] = i;
	}

	for(int i = 1; i <= m; i++){
		scanf("%d %d", &a[i], &b[i]);
		int pa = f(a[i]);
		int pb = f(b[i]);
		if(pa == pb){
			// point a[i] -> b[i]
			deg[b[i]]++;
		}else{
			par[pa] = pb;
			tedge[a[i]].push_back(i);
			tedge[b[i]].push_back(i);
		}
