void dfs(int u, int par) {
	mark[u] = 1;
	for (int v : adj[u]) if (!mark[v]) {
		dfs(v, u);
	}
	int pre = -1, cnt = 0;
	for (int v : adj[u]) if (alive.find({u, v}) != alive.end() && par != v) {
		++cnt;
		alive.erase({u, v});
		alive.erase({v, u});
		if (~pre) {
			res.push_back({pre, u, v});
			pre = -1;
		} else pre = v;
	}
	// cerr << u << " : " << cnt << endl;
	if (~pre && ~par) {
		res.push_back({pre, u, par});
		alive.erase({u, par});
		alive.erase({par, u});
	}
}

