struct Edge {
    int to;
    bool rev;
    Edge(int t, bool r) : to(t), rev(r) {}
};

int dfs(vector<vector<Edge>> &g, vector<bool> &used, int v) {
    used[v] = true;
    int c = g[v].size();
    for (auto &e: g[v]) {
        if (used[e.to]) continue;
        if (dfs(g, used, e.to)) {
            e.rev = true;
            c--;
        }
    }
    return c%2;
}



