using namespace std;
typedef vector<int> vi;
typedef vector<vector<int>> vvi;
typedef pair<int, int> pr;
typedef set<pr> st;

vvi g(1e5);
vvi tr(1e5);
vi pt(1e5);
vi vst(1e5);
st ans;

void tree(vvi &g, int p, int v)
{
    if (p != -1)
    {
        if (vst[v] == 1)
        {
            int lt = p > v ? v : p;
            int gr = p > v ? p : v;
            ans.insert(pr(lt, gr));
            pt[lt] ^= 1;
            return;
        }
        else
        {
            tr[p].push_back(v);
        }
    }
    vst[v] = 1;

    for (int u : g[v])
    {
        if (u != p)
        {
            tree(g, v, u);
        }
    }
}

void solve(int p, int v)
{
    for (int u : tr[v])
    {
        solve(v, u);
    }

    if (p == -1)
    {
        return;
    }

    if (pt[v] == 0)
    {
        ans.insert(pr(p, v));
        pt[p] ^= 1;
    }
    else
    {
        ans.insert(pr(v, p));
        pt[v] ^= 1;
    }
}

int main()
{
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++)
    {
        int a, b;
