        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    if (m % 2 == 0)
    {
        tree(g, -1, 0);
        solve(-1, 0);

        for (auto i : ans)
        {
            cout << i.first + 1 << " " << i.second + 1 << endl;
        }
    }
    else
    {
        cout << -1 << endl;
    }

    return 0;
}

