bool vis[MAXN], s[MAXN], x[MAXN];

int fix(int u){
	vis[u] = true;

	int r = x[u];
	for(int i : G[u]){
		int v = A[i] ^ B[i] ^ u;
		if(vis[v])continue;

		if(fix(v) == 1){
			s[i] ^= 1;
			r ^= 1;
		}
	}
	return r;
}

