using namespace std;

struct Edge
{
    int u, v;
    bool rev;

    Edge(int _u, int _v)
    {
        u = _u;
        v = _v;
        rev = false;
    }
    Edge() {};

    void show()
    {
        if (rev) swap(u, v);
        printf("%d %d\n", u + 1, v + 1);
    }
};

const int N = 1e5;

vector<Edge> edges;
vector<int> g[N];
int col[N];
bool used[N];

int getOther(Edge e, int v)
{
    return v ^ e.u ^ e.v;
}

void dfs(int v)
{
    used[v] = true;
    for (int i : g[v])
    {
        int u = getOther(edges[i], v);
        if (!used[u])
        {
            dfs(u);
            if (col[u])
            {
                col[u] ^= 1;
                col[v] ^= 1;
                edges[i].rev = true;
            }
        }
    }
}

int main()
{
    //freopen("input.txt", "r", stdin);


    int n, m;
    scanf("%d%d", &n, &m);

    for (int v = 0; v < n; ++v)
    {
        col[v] = 0;
        used[v] = false;
    }
    for (int i = 0; i < m; ++i)
    {
        static int u, v;
        scanf("%d%d", &u, &v);
        --u; --v;
        edges.push_back(Edge(u, v));
        col[u] ^= 1;
        g[u].push_back(i);
        g[v].push_back(i);
    }

    dfs(0);

    if (col[0])
        printf("No");
    else
    {
        printf("Yes\n");
        for (Edge& e : edges)
            e.show();
    }


}

