using namespace std;

typedef long long int Int;

int N,M;
set<int> E[N_MAX];
map<int,int> node_info;

vector<int> Odd,Even;
int deg_counter[N_MAX];
vector<pair<int,int> > show_node;

void check(void) {
    for(auto v: node_info) {
        if(v.second % 2 == 1)
            Odd.push_back(v.first);
        else
            Even.push_back(v.first);
    }

    return;
}

bool empty_node() {
    int ans = 0;
    for(int i = 1;i <= N;i++) {
        ans += deg_counter[i];
    }

    return ans == M;
}
void solve(void) {
    check();

    for(int i = 0;i < Even.size();i++) {
        int u = Even[i];
        if(E[u].size() % 2 == 1)
            continue;
        for(set<int>::iterator it = E[u].begin();it != E[u].end();it++) {
            show_node.push_back(make_pair(u,*it));
            E[*it].erase(u);
            deg_counter[*it]++;
        }
    }

    if(!empty_node()) {
        cout<<-1<<endl;

        return;
    }

    for(int i = 0;i < show_node.size();i++) {
        cout<<show_node[i].first<<" "<<show_node[i].second<<endl;
    }

    return;
}

int main(void) {
    cin>>N>>M;
    for(int i = 0;i < M;i++) {
        int a,b;
        cin>>a>>b;
        node_info[a]++;
        node_info[b]++;
        E[a].insert(b);
        E[b].insert(a);
    }

    solve();

    return 0;
}

