            if(edge[x[i]].first == v){
                d[x[i]] = 1;
            }else{
                d[x[i]] = -1;
            }
            if(edge[x[i+1]].first == v){
                d[x[i+1]] = 1;
            }else{
                d[x[i+1]] = -1;
            }
        }
    }

    rep(i, m){
