const int MAX = 100010;

int n, m;
vector<int> G[MAX];
vector<pii> ans;
int ord[MAX], deg[MAX];

void dfs1(int v, int pv, int &idx){
    ord[v]=idx++;
    for(int nv: G[v])if(nv!=pv){
        if(ord[nv]>=0 && ord[nv]<ord[v]){
            ans.emplace_back(v, nv);
            deg[v]^=1;
        }
        else if(ord[nv]<0) dfs1(nv, v, idx);
    }
}

void dfs2(int v, int pv){
    ord[v]=0;
    for(int nv: G[v])if(ord[nv]<0) dfs2(nv, v);
    if(pv<0) return;
    if(deg[v]){
        ans.emplace_back(v, pv);
        deg[v]^=1;
    }
    else{
        ans.emplace_back(pv, v);
        deg[pv]^=1;
    }
}

int main(){
    scanf("%d%d", &n, &m);
    if(m%2){
        printf("-1\n");
        return 0;
    }
    rep(i, m){
        int a, b;
        scanf("%d%d", &a, &b);
        --a; --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    rep(i, n){
        ord[i]=-1;
        deg[i]=0;
    }
    int idx=0;
    dfs1(0, -1, idx);
    rep(i, n) ord[i]=-1;
    dfs2(0, -1);
    for(pii e: ans) printf("%d %d\n", e.fi+1, e.se+1);
}

