int N, M;
vector<int> adj[100001];

int rem[100001];
int cnt[100001];
bool fin[100001];
bool inq[100001];

int main(void) {
    iostream::sync_with_stdio(false);
    cin.tie(nullptr), cout.tie(nullptr);

    cin >> N >> M;
    rep(i, M) {
        int a, b; cin >> a >> b;
        adj[a].pb(b);
        adj[b].pb(a);       
    }

    if (M&1) return cout << -1 << endl, 0;

    queue<int> cand;
    repp(i, 1, N+1) if ((rem[i] = sz(adj[i])) == 1) cand.push(i);

    int p = 1;
    while(p <= N) {
        int c = 0;
        if (sz(cand) > 0) {
            c = cand.front(); cand.pop();
        } else {
            c = p++;
        }
        if (fin[c]) continue;

        int u = -1;
        if (cnt[c]&1) {
            repi(i, adj[c]) if (not fin[i]) {
                if (--rem[i] < 2 and not inq[i]) inq[i] = true, cand.push(i);
                cout << c << ' ' << i << endl;
                cnt[c]++;
                u = i;
                break;
            }
        }

        repi(i, adj[c]) if (not fin[i] and u != i) {
            cout << i << ' ' << c << endl;
            if (--rem[i] < 2 and not inq[i]) inq[i] = true, cand.push(i);
            cnt[i]++;
        }

        fin[c] = true;
    }
}

