	for (int e=head[u];e;e=nex[e]){
		int v=tail[e];
		if (d[v]==-1){
			d[v]=d[u]+1; dfs1(v);
		}
		else {
			printf("%d %d\n",u,v);
			rd[u]++;
		}
	}
}
void dfs2(int u,int p){
	for (int e=head[u];e;e=nex[e]){
		int v=tail[e];
