class UnionFindTree
{
private:
    int n;
    int groupNum;       // グループの数
    vector<int> parent; // 親ノード
    vector<int> rank;   // 木の高さの上限
    vector<int> num;    // グループの要素数
    int find(int i){
        if(parent[i] == i)
            return i;
        else
            return parent[i] = find(parent[i]);
    }
public:
    UnionFindTree(int n){ // コンストラクタ
        this->n = n;
        groupNum = n;
        parent.resize(n);
        for(int i=0; i<n; ++i)
            parent[i] = i;
        rank.assign(n, 0);
        num.assign(n, 1);
    }
    void unite(int a, int b){ // aとbのグループを併合
        if((a = find(a)) != (b = find(b))){
            if(rank[a] < rank[b]){
                parent[a] = b;
                num[b] += num[a];
            }
            else{
                parent[b] = a;
                if(rank[a] == rank[b])
                    ++ rank[a];
                num[a] += num[b];
            }
            -- groupNum;
        }
    }
    bool same(int a, int b){ // aとbのグループが同じかを調べる
        return find(a) == find(b);
    }
    int getNum(){ // グループの数を返す
        return groupNum;
    }
    int getNum(int a){ // aのグループの要素数を返す
        return num[find(a)];
    }
};

vector<vector<int> > edges;
vector<bool> isEven;
vector<pair<int, int> > ans;

bool solve(int curr, int prev)
{
    for(int next : edges[curr]){
        if(next == prev)
            continue;
        if(solve(next, curr)){
            isEven[curr] = !isEven[curr];
            ans.push_back(make_pair(curr, next));
        }
        else{
            isEven[next] = !isEven[next];
            ans.push_back(make_pair(next, curr));
        }
    }
    return isEven[curr];
}

int main()
{
    int n, m;
    cin >> n >> m;
    edges.assign(n, vector<int>());
    isEven.assign(n, true);
    ans.clear();

    UnionFindTree uft(n);
    for(int i=0; i<m; ++i){
        int a, b;
        cin >> a >> b;
        -- a;
        -- b;
        if(!uft.same(a, b)){
            edges[a].push_back(b);
            edges[b].push_back(a);
            uft.unite(a, b);
        }
        else{
            ans.push_back(make_pair(a, b));
            isEven[a] = !isEven[a];
        }
    }

    if(solve(1, -1)){
