std::vector<std::vector<int>> Edge;
std::vector<int> Dist, Parent, NChildren, Out;
std::map<std::pair<int, int>, char> e;

int main(void){
    int n, m; scanf("%d%d", &n, &m);
    if(m & 1){puts("-1"); return 0;}
    Edge.resize(n);
    REP(i, m){
        int a, b; scanf("%d%d", &a, &b); a--; b--;
        Edge[a].push_back(b); Edge[b].push_back(a);
        if(a > b) std::swap(a, b);
        e[{a, b}] = 0;
    }
    Dist.assign(n, -1); Parent.resize(n); Out.assign(n, 0); NChildren.assign(n, 0);
    std::queue<int> Q;
    int root = 0;
    Q.push(root); Dist[root] = 0; Parent[root] = -1;
    while(not Q.empty()){
        int v = Q.front(); Q.pop();
        for(int nv : Edge[v]){
            if(Dist[nv] == -1){
                Dist[nv] = Dist[v] + 1; Parent[nv] = v; NChildren[v]++;
                Q.push(nv);
            }
            else if(v < nv){
                auto itr = e.find({v, nv});
                if(itr -> second == 0){
                    Out[v]++; itr->second = 1;
                }
            }
        }
    }
    std::stack<int> Stk;
    REP(i, n) if(NChildren[i] == 0) Stk.push(i);
    while(not Stk.empty()){
        int v = Stk.top(); Stk.pop();
        int pv = Parent[v];
        const std::pair<int, int> p = (v < pv) ? std::pair<int, int>(v, pv) : std::pair<int, int>(pv, v);
        auto itr = e.find(p);
        if(Out[v] & 1){
            Out[v]++; itr->second = (v < pv) ? 1 : 2;
        }
        else{
            Out[pv]++; itr->second = (v < pv) ? 2 : 1;
        }
        if((--NChildren[pv]) == 0 and pv != 0) Stk.push(pv);
    }
    for(auto& itr : e){
        int a = itr.first.first + 1, b = itr.first.second + 1;
        if(itr.second == 1) printf("%d %d\n", a, b);
        else printf("%d %d\n", b, a);
    }





    return 0;
}

