typedef pair<int, int> Pair;

int N, M;
vector<vector<int>> nbr;
map<Pair, char> dir;
vector<bool> visited;

void mkDir(int x, int y) {
  dir[make_pair(x, y)] = 1;
  dir[make_pair(y, x)] = -1;
}

void dfs(int p, int c) {
  char parity = 0;
  if (visited.at(c)) {
    mkDir(p, c);
    return;
  }
  visited.at(c) = true;
  for (int g : nbr.at(c)) {
    if (g == p) continue;
    char d = dir[make_pair(c, g)];
    if (d == 0) {
      dfs(c, g);
      d = dir[make_pair(c, g)];
    }
    if (d == 1) parity = 1 - parity;
  }
  if (p >= 1) {
    if (parity) mkDir(c, p);
    else        mkDir(p, c);
  }
  return;
}

