void getans(int v, int p = -1) {
    for (int i = 0; i < G[v].size(); i++) {
        int u = G[v][i];
        if (u == p || fake[v][i]) continue;
        getans(u, v);
    }   


    if (v != root) {
        for (int i = 0; i < G[v].size(); i++) {
            int u = G[v][i];
            if (fake[v][i] && depth[u] < depth[v]) {
                deg[v] ^= 1;
                ans.push_back(P(v, u));
            }
        }   

        if (deg[v] == 1) {
            deg[v] ^= 1;
            ans.push_back(P(v, p));
        }
        else {
            deg[p] ^= 1;
            ans.push_back(P(p, v));
        }
    } 
}


