		if (g.prev != -1) {
			dir[minmax(g.prev, g.now)] ^= g.flip;
			out[g.prev] ^= g.flip;
		}
		out[g.now] ^= g.flip;
		if (!out[g.now]) g.flip ^= 1;

		for (const auto &e : edge[g.now]) {
			if (!visited[e]) {
				que.emplace(e, g.now, g.flip);
			}
