struct UnionFind{
    vector<ll> parent;
    UnionFind(){
    }

    void initialize(ll sz){
        parent.resize(sz);
        reset();
    }

    void reset(){
        FOR(i, 0, parent.size()){
            parent[i] = i;
        }
    }

    void unite(ll a, ll b){
        if(a>b){
            swap(a, b);
        }
        ll rootA = findRoot(a);
        ll rootB = findRoot(b);
        if(rootA>rootB){
            swap(rootA, rootB);
        }
        if(rootA==rootB){
            return;
        }else{
            // 小さい方を親にする
            parent[rootB] = rootA;
        }
    }

    ll findRoot(ll a){
        if(parent[a]==a){
            return a;
        }else{
            return parent[a] = findRoot(parent[a]);
        }
    }

    map<ll, vector<ll> > getGroups(){
        map<ll, vector<ll> > G;
        FOR(i, 0, parent.size()){
            ll r = findRoot(i);
            G[r].push_back(i);
        }
        return G;
    }

    bool is_same_group(ll a, ll b){
        ll rootA = findRoot(a);
        ll rootB = findRoot(b);
        if(rootA==rootB){
            return true;
        }else{
            return false;
        }
    }
};

const int N_MAX = 100010;

vector<vector<ll> > G;

// 出次数
ll out[N_MAX];

ll parent[N_MAX];
UnionFind uf;
vector<pair<ll, ll> > Ans;

// 葉まで行って出次数見て、張る
void dfs(ll i, ll prev){
    for(ll to : G[i]){
        if(prev==to) continue;
        parent[to] = i;
        dfs(to, i);
    }

    ll p = parent[i];

    if(i==0) return;

    if(out[i]%2==1){
        // iから出す
        // i->p
        out[i]++;
        Ans.push_back(make_pair(i, p));
    }else{
        // p->i
        out[p]++;
        Ans.push_back(make_pair(p, i));
    }
}

int main(){
