        if(uf.is_same_group(a, b)){
            // 適当に方向づけ
            // a -> b
            out[a]++;
            Ans.push_back(make_pair(a, b));
        }else{
            // 辺をはる
            G[a].push_back(b);
            G[b].push_back(a);
