  Kruskal(int n = 0) : n(n) {}

  void addEdge(int u, int v) {
    n = max(n, max(u, v) + 1);
    es.push_back({u, v});
  }
  UnionFind build() {
    UnionFind uf(n);
    for (auto&& e : es) {
      int u = e.s;
      int v = e.t;
      if (!uf.isSame(u, v)) {
        uf.unite(u, v);
