	int p[N], sz[N];

	void init(int n) {
		for (int i = 1; i <= n; ++i) {
			p[i] = i;
			sz[i] = 1;
		}
	}

	int getp(int v) {
		if (v == p[v]) return v;
		p[v] = getp(p[v]);
		return p[v];
	}

	bool join(int u, int v) {
		u = getp(u);
		v = getp(v);
		if (u == v) return 0;
		if (sz[u] < sz[v]) {
			p[u] = v;
			sz[v] += sz[u];
		} else {
			p[v] = u;
			sz[u] += sz[v];
		}
		return 1;
	}
};

