    que.emplace(0, -1);
    while (!que.empty())
    {
        int cur = que.front().first;
        int par = que.front().second;
        que.pop();
        for (auto v : tr[cur])
        {
            if (v == par)
                continue;
            if (sum[cur] % 2)
            {
                ret.emplace(v, cur);
            }
            else
            {
                ret.emplace(cur, v);
            }
            sum[v] += sum[cur];
            que.emplace(v, cur);
        }
    }
    assert(ret.size() == m);
    vector<int> aa(n, 0);
    for (auto p : ret)
    {
        aa[p.first]++;
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }
    for (int i = 0; i < n; i++)
        assert(aa[i] % 2 == 0);
}

