const ll MAX_N=1e5;
ll N,M,par[MAX_N],outdeg[MAX_N];
vector<ll> G[MAX_N];
void init(ll n){
	REP(i,n)par[i]=i;
}
ll fndpar(ll v){
	if(par[v]==v)return v;
	return par[v]=fndpar(par[v]);
}
void unite(ll a,ll b){
	a=fndpar(a);
	b=fndpar(b);
	par[a]=b;
}
bool same(ll a,ll b){
	a=fndpar(a);
	b=fndpar(b);
	return a==b;
}
void prtedge(ll v,ll u){
	cout<<v+1<<' '<<u+1<<endl;
}
void dfs(ll v,ll p){
	for(auto e:G[v]){
		if(e!=p)dfs(e,v);
	}
	if(p!=-1){
		if(outdeg[v]%2==0){
			prtedge(p,v);
			outdeg[p]++;
		}else{
			prtedge(v,p);
			outdeg[v]++;
		}
	}
}
