};

vector<vector<Edge>> edg;
vector<int> cntout;

bool vis[100003];
bool func(int pos, int org) {
	if (pos != org && cntout[pos] % 2 != 0) return true;
	vis[pos] = true;

	for (auto &e : edg[pos]) {
		if (vis[e.to]) continue;

		bool ret = func(e.to, org);
		if (ret) {
			e.ort *= -1;
			cntout[pos]--;

			edg[e.to][e.rev].ort *= -1;
			cntout[e.to]++;

			vis[pos] = false;
			return true;
		}
	}
	vis[pos] = false;
	return false;
}

