Vertex V[100005];
ll C[100005];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, M;
    cin >> N >> M;
    REP(i, M) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        V[a].node.push_back(b);
        V[b].node.push_back(a);
    }
    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    SegmentTree<pll> seg([](pll a, pll b) {
        if (a.first < b.first)
            return a;
        return b;
    }, pll(INF, INF));
    seg.init(N);
    REP(i, N) {
        seg.set(i, pll(V[i].node.size(), i));
    }

    memset(C, 0, sizeof(C));
    vector<pll> ans;
    while (ans.size() < M) {
        pll t = seg.get(0, N - 1);
        vector<pll> v;
        REP(i, V[t.second].node.size()) {
            ll n = V[t.second].node[i];
            pll value = seg.get(n, n);
            if (value.first == INF)
                continue;
            v.push_back(pll(t.second, n));
        }

        ll m = (C[t.second] + v.size()) % 2;
        REP(i, v.size()) {
            pll value = seg.get(v[i].second, v[i].second);
            if (m > 0) {
                if (value.first == 1 && C[v[i].second] % 2 == 0) {
                    ans.push_back(pll(v[i].first, v[i].second));
                }
                else {
                    ans.push_back(pll(v[i].second, v[i].first));
                    C[v[i].second]++;
                    m--;
                }
            }
            else
                ans.push_back(pll(v[i].first, v[i].second));
            value.first--;
            if (value.first == 0)
                seg.set(v[i].second, pll(INF, INF));
            else
                seg.set(v[i].second, value);
        }
        seg.set(t.second, pll(INF, INF));
    }

    REP(i, ans.size()) {
        cout << ans[i].first + 1 << " " << ans[i].second + 1 << endl;
    }
    return 0;
}

