const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k;
vl as;
Graph graph[MAX_N];
ll depth[MAX_N], sz[MAX_N];
bool visited[MAX_N], tg[MAX_N];

void dfs(ll source){
    visited[source] = true;

    for (auto& e: graph[source]){
        if (visited[e.to]) continue;
        dfs(e.to);
        if (tg[source]) prl2(source + 1, e.to + 1);
        else prl2(e.to + 1, source + 1), tg[source] = !tg[source];
    }
}

ll find(ll source){
    if (depth[source] == source) return source;
    return depth[source] = find(depth[source]);
}

void mrg(ll source, ll parent){
    source = find(source);
    parent = find(parent);
    if (source == parent) return;
    if (sz[parent] < sz[source]) swap(source, parent);
    depth[source] = parent;
    sz[parent] += sz[source];
}

void solve(){
    if (k % 2 == 1){prl(-1); return;}
    rep(i, n) depth[i] = i, sz[i] = 1;
    rep(i, k){
        ll a, b; in2(a, b); a--, b--;
        if (find(a) == find(b)){
            prl2(a + 1, b + 1);
            tg[a] = !tg[a];
        }else{
            graph[a].pb({b, 1});
            graph[b].pb({a, 1});
            mrg(a, b);
        }
    }

    dfs(0);
}

int main(void){
    in2(n, k);
    // assert(x <= 50);
    solve();
    return 0;
}

