class UnionFind {
    private :
        std::vector<int> par;
        std::vector<int> sz;
    public :
        UnionFind(int n) {
            par.resize(n);
            for (int i=0; i<n; i++) par[i] = i;
            sz.assign(n, 1);
        }
        void unite(int x, int y) {
            const int x_par = find(x);
            const int y_par = find(y);
            if (x_par == y_par) return;

            if (sz[x_par] < sz[y_par]) {
                par[x_par] = y_par;
                sz[y_par] += sz[x_par];
            } else {
                par[y_par] = x_par;
                sz[x_par] += sz[y_par];
            }
        }
        int find(int x) {
            if (par[x] == x) return x;
            else return par[x] = find(par[x]);
        }
        bool same(int x, int y) { return find(x) == find(y); }
        int size(int x) { return sz[find(x)]; }
};

void dfs(int cur, int pre, const Graph &t, Graph &ans) {
    for (int nx : t[cur]) {
        if (nx != pre) dfs(nx, cur, t, ans);
    }
    if (pre != -1) {
        if ((int)ans[cur].size()%2 == 0) ans[pre].push_back(cur);
        else ans[cur].push_back(pre);
    }
}

void solve() {
    int N, M;
    cin >> N >> M;
    vector<pair<int, int>> es(M);
    for (int i=0; i<M; ++i) {
        int a, b;
        cin >> a >> b;
        es[i] = {a-1, b-1};
    }

    if (M%2 == 1) {
        cout << -1 << '\n';
        return;
    }

    UnionFind uf(N);
    Graph t(N), ans(N);
    for (auto p : es) {
        if (!uf.same(p.first, p.second)) {
            uf.unite(p.first, p.second);
            t[p.first].push_back(p.second);
            t[p.second].push_back(p.first);
        } else {
            ans[p.first].push_back(p.second);
        }
    }
    dfs(0, -1, t, ans);
    for (int i=0; i<N; ++i) {
        for (int j : ans[i]) {
            cout << i + 1 << ' ' << j + 1 << '\n';
        }
    }
}

