using PQ = priority_queue<PLL, V<PLL>, less<PLL>>;

void dfs(ll now, ll pre, PQ &que, ll d = 0) {
    bool leaf = true;
    depth[now] = d;
    for(ll nxt : tree_edges[now]) {
        if(nxt == pre) continue;
        leaf = false;
        dfs(nxt, now, que, d + 1);
    }
    tree_parents[now] = pre;
    if(leaf) que.emplace(depth[now], now);
}

