int par[MAX_N], deg[MAX_N];
bool in[MAX_N];

void dfs(int x, int p) {
	for (auto y : tree[x]) {
		if (y != p) {
			dfs(y, x);
		}
	}
	if (x == 1) return;
	if (deg[x] & 1) {
		ans[++ans_top] = std::make_pair(x, p);
		++deg[x];
	} else {
		ans[++ans_top] = std::make_pair(p, x);
		++deg[p];
	}
}

int find(int x) {
	return x == par[x] ? x : par[x] = find(par[x]);
}

void solve() {
	for (int i = 1; i <= n; ++i) {
		par[i] = i;
	}
	int tot = 0;
	for (int i = 1; i <= m; ++i) {
		int x = el[i].first, y = el[i].second;
		x = find(x);
		y = find(y);
		if (x != y) {
			in[i] = true;
			tree[el[i].first].push_back(el[i].second);
			tree[el[i].second].push_back(el[i].first);
			par[y] = x;
			++tot;
			if (tot == n - 1) break;
		}
	}
	ans_top = 0;
	for (int i = 1; i <= m; ++i) {
		if (!in[i]) {
			ans[++ans_top] = el[i];
			++deg[el[i].first];
		}
	}
	dfs(1, 0);
}

