#include <bits/stdc++.h>

using namespace std;
enum Status{
  NotExplore = 0,
  Exploring,
  Explored,
};

vector<vector<int> > tree(100000);
vector<Status> nodeStatus(100000);
vector<pair<int, int> > ans;

/// deep first search
int dfs (int currentNode, int parentNode)
{
  int isOdd = 0;
  nodeStatus[currentNode] = Status::Exploring;

  for (auto childNode : tree[currentNode]) {
    if (parentNode == childNode) continue;
    if (nodeStatus[childNode] == Status::Explored) continue;
    if (nodeStatus[childNode] == Status::Exploring) {
      isOdd ^= 1;
      ans.push_back({currentNode, childNode});
    }
    if (nodeStatus[childNode] == Status::NotExplore) {
      if (dfs(childNode, currentNode)) {
        ans.push_back({childNode, currentNode});
      } else {
        isOdd ^= 1;
        ans.push_back({currentNode, childNode});
      }
    }
  }

  nodeStatus[currentNode] = Status::Explored;
  return isOdd;
}

