{
  int N, M; cin >> N >> M;

  for (int i=0; i<M; i++) {
    int a, b; cin >> a >> b;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  if (dfs(1, 0)) {
    cout << -1 << endl;
  } else {
    for (auto p : ans) {
      cout << p.first << " " << p.second << endl;
    }
  }

}

