ll N, M;
vector<ll> graph[MAX_N];
bool isNodeUsed[MAX_N];
bool isEdgeUsed[MAX_M];
ll Jisu[MAX_N];    // 頂点 i の次数
ll Nyuji[MAX_N];   // 頂点 i の入次数
map< pair<ll, ll>, ll> edge_id;
map< ll, pair<ll, ll>> id_edge;
vector< pair<ll, ll> > ans;
ll used_cnt = 0;

void dfs(ll node) {
    if(isNodeUsed[node]) { return; }

    DBG("node: %lld\n", node);

    isNodeUsed[node] = true;
    used_cnt++;

    // 次数が偶数ならすべて自分のものにする
    for(auto& e_to : graph[node]) {
        ll a = min(node, e_to);
        ll b = max(node, e_to);
        ll e_id = edge_id[make_pair(a, b)];
        if(!isEdgeUsed[e_id]) {
            ans.push_back(make_pair(e_to, node));
            Jisu[e_to]--;
            Jisu[node]--;
            Nyuji[node]++;
            isEdgeUsed[e_id] = true;
        }
    }

    // 次数が偶数のものへ移動
    for(auto& e_to : graph[node]) {
        if(Jisu[e_to] % 2 == 0 && !isNodeUsed[e_to]) {
            dfs(e_to);
        }
    }
}

void dfs2(ll node) {
    if(isNodeUsed[node]) { return; }

    isNodeUsed[node] = true;
    used_cnt++;

    // 一つ残して全部取る
    ll remain = -1;
    for(auto& e_to : graph[node]) {
        ll a = min(node, e_to);
        ll b = max(node, e_to);
        ll e_id = edge_id[make_pair(a, b)];
        if(!isEdgeUsed[e_id]) {
            if(remain == -1) {
                remain = e_to;
            }
            else {
                ans.push_back(make_pair(e_to, node));
                Jisu[e_to]--;
                Jisu[node]--;
                Nyuji[node]++;
                isEdgeUsed[e_id] = true;
            }
        }
    }
}

