        a--; b--;
        graph[a].push_back(b);
        graph[b].push_back(a);
        Jisu[a]++;
        Jisu[b]++;
        if(a > b) { swap(a, b); }
        edge_id[make_pair(a, b)] = cnt;
        id_edge[cnt] = make_pair(a, b);
        cnt++;
    }

    if(M % 2 != 0) {
        printf("-1\n");
        return 0;
    }

    while(used_cnt < N) {
        bool isChange = true;
        {
            while(isChange) {
                isChange = false;
                REP(i, N) {
                    if(Jisu[i] % 2 == 0 && Jisu[i] != 0) {
                        isChange = true;
                        dfs(i);
                    }
                }
            }
        }
        DBG("used_cnt: %lld\n", used_cnt);
        if(used_cnt == N) { break; }

        // 残りはクリークだけのはず
        isChange = false;
        REP(i, N) {
            if(Jisu[i] % 2 != 0 && Jisu[i] > 1) {
                dfs2(i);
                isChange = true;
                break;
            }
        }
        if(used_cnt == N) { break; }
        assert(isChange);
    }

    for(auto& tmp : ans) {
        printf("%lld %lld\n", tmp.first + 1, tmp.second + 1);
    }

    return 0;
}

