void dfs(Int pos, Int pre){

  for(Int to:G[pos]){
    if(to == pre) continue;
    if(T[pos].count(to)) continue;
    if(ans.count(P(pos, to))) continue;
    if(ans.count(P(to, pos))) continue;
    ans.emplace(pos, to);
    outdeg[pos]++;
    indeg[to]++;
  }

  for(Int to:T[pos]){
    if(to == pre) continue;
    dfs(to, pos);
  }

  if(pre == -1) return;
  if(indeg[pos] % 2 == 1) {
    ans.emplace(pre, pos);
    indeg[pos]++;
    outdeg[pre]++;
  }
  else {
    ans.emplace(pos, pre);
    outdeg[pos]++;
    indeg[pre]++;
  }
}



