    u--; v--;
    g[u].insert(v);
    g[v].insert(u);
  }
  if(m & 1) {
    cout << -1;
    return 0;
  }
  vector<int> par(n, -1);
  vector<set<int>> to(n);
  vector<int> was(n);
  set<int> cur;
  function<void(int, int)> dfs = [&](int v, int p) {
    par[v] = p;
    was[v] = 1;
    for(int u : g[v]) {
      if(was[u]) continue;
      to[v].insert(u);
      dfs(u, v);
    }
    if(to[v].empty()) cur.insert(v);
  };
  dfs(0, -1);
  auto cut = [&](int u, int v) {
    g[u].erase(v);
    g[v].erase(u);
    if(u != par[v] && v != par[u]) return;
    if(v == par[u]) swap(u, v);
    par[v] = -1;
    to[u].erase(v);
    cur.erase(v);
    if(to[u].empty()) cur.insert(u);
  };
  auto link = [&](int v) {
    if(g[v].empty()) return;
    int u = *g[v].begin();
    if(to[u].empty()) cur.erase(u);
    par[v] = u;
    to[u].insert(v);
    if(to[v].empty()) cur.insert(v);
  };
