    if(to[v].size() > 1) {
      for(int a : to[v]) if(a != u) z = a;
    }
    assert(~z);
    if(g[u].find(z) != g[u].end()) {
      go(u, z, v);
      cut(u, z);
      cut(z, v);
      link(z);
    } else {
      go(u, v, z);
      if(z == par[v]) {
        cut(u, v); cut(v, z);
        link(v); link(u);
      } else {
        cut(u, v); cut(z, v);
        link(u); link(z);
      }
    }
  }
  return 0;
}

