ll MC(vector<ll> &V,ll s,ll e)
{
    if (s>e)
        return 0;
    if(DP[s][e]!=-1)
        return DP[s][e];
    if(s==e)
        return DP[s][e]=V[s];
    if(s+1==e)
        return DP[s][e]=(V[s]+V[e]);
    ll temp = 1e17;
    for(ll i=s;i<e;i++)
    {
        ll t2 = MC(V,s,i) + MC(V,i+1,e);
        if(t2 < temp)
        {
            temp = t2;
        }
    }

    return DP[s][e]=temp;
}

