typedef long long li;

li popfirst(set<li>& s) {
    li rv = *s.begin();
    s.erase(s.begin());
    return rv;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n, m;
    cin >> n >> m;

    vector<set<li>> g(n);

    for (int i = 0; i < m; ++i) {
        li a, b;
        cin >> a >> b;
        a--; b--;

        g[a].insert(b);
        g[b].insert(a);
    }

    if (m % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    set<li> leafs, nonleafs;
    for (int i = 0; i < n; ++i) {
        if (g[i].size() == 1) {
            leafs.insert(i);
        } else {
            nonleafs.insert(i);
        }
    }

    vector<li> outdegs(n);
    while (not leafs.empty() or not nonleafs.empty()) {
        li pos, next;
        bool rev;
        if (not leafs.empty()) {
            pos = popfirst(leafs);
            next = popfirst(g[pos]);
            rev = (1 - (outdegs[pos] % 2));
        } else {
            pos = *nonleafs.begin();
            if (g[pos].size() == 2) {
                popfirst(nonleafs);
                leafs.insert(pos);
            }
            next = popfirst(g[pos]);
            rev = true;
        }
        g[next].erase(pos);
        if (g[next].size() == 1) {
            nonleafs.erase(next);
            leafs.insert(next);
        } else if (g[next].size() == 0) {
            leafs.erase(next);
        }

        if (rev) {
            cout << next + 1 << " " << pos + 1 << endl;
            outdegs[next]++;
        } else {
            cout << pos + 1 << " " << next + 1 << endl;
            outdegs[pos]++;
        }

    }
    return 0;
}

