int N, M, A[112345], B[112345];
vector<map<int, bool>> edge_to;

int main() {

	scanf("%d%d", &N, &M);
	if (M % 2) {
		printf("-1\n");
		return 0;
	}
	edge_to.resize(N);
	rep(i, M) scanf("%d%d", &A[i], &B[i]);
	rep(i, M) {
		edge_to[A[i] - 1][B[i] - 1] = true;
		edge_to[B[i] - 1][A[i] - 1] = true;
	}

	vector<int> EdgeCount(N), UsedCount(N);
	set<int> firstjudge;
	rep(i, N) {
		EdgeCount[i] = edge_to[i].size();
		if (EdgeCount[i] == 1) firstjudge.insert(i);
	}
	vector<pair<int, int>> ans;

	for (auto fj : firstjudge) {
		//UsedCount[(*edge_to[fj].begin()).first]++;
		UsedCount[fj]++;
		(*edge_to[fj].begin()).second = false;
		edge_to[(*edge_to[fj].begin()).first][fj] = false;
		ans.push_back({ (*edge_to[fj].begin()).first, fj });
	}

	rep(i, N) {
		if (firstjudge.find(i) != firstjudge.end()) continue;
		if ((EdgeCount[i] - UsedCount[i]) % 2) {
			bool f = true;
			for (auto e : edge_to[i]) {
				if (f && e.second) {
					UsedCount[i]++;
					edge_to[e.first][i] = false;
					edge_to[i][e.first] = false;
					ans.push_back({ e.first, i });
					f = false;
					continue;
				}
				if (e.second) {
					UsedCount[e.first]++;
					edge_to[e.first][i] = false;
					edge_to[i][e.first] = false;
					ans.push_back({ i,e.first });
				}
			}
		}
		else {
			for (auto e : edge_to[i]) {
				if (e.second) {
					UsedCount[e.first]++;
					edge_to[e.first][i] = false;
					edge_to[i][e.first] = false;
					ans.push_back({ i,e.first });
				}
			}
		}
	}

	for (auto a : ans) {
		printf("%d %d\n", a.first + 1, a.second + 1);
	}

	return 0;
}

