	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	V<bool> visited(n, false);
	V<int> in(n, 0);
	VV<int> G(n);
	visited[0] = true;
	std::set<PAIR> set;
	{
		auto rec = [&](auto && f, int v, int par) -> void {
			for (auto& to : g[v]) if (to != par) {
				if (visited[to]) {
					if (!set.count(std::minmax(to, v))) {
						OUT(to + 1)SP OUT(v + 1)ENDL;
						set.insert(std::minmax(to, v));
						++in[to];
					}
				}
				else {
					visited[to] = true;
					G[v].emplace_back(to);
					set.insert(std::minmax(to, v));
					f(f, to, par);
				}
			}
		};
		rec(rec, 0, -1);
	}
	{
		auto rec = [&](auto && f, int v, int par) -> void {
			for (auto& to : G[v]) {
				f(f, to, v);
			}
			if (par == -1) return;
			if (in[v] % 2 == 0) {
				++in[par];
				OUT(par + 1)SP OUT(v + 1)ENDL;
			}
			else {
				++in[v];
				OUT(v + 1)SP OUT(par + 1)ENDL;
			}
		};
		rec(rec, 0, -1);
	}

	return 0;
