#define rep(i, a, b) for (ll i = (a); i < (b); i++)
#define rrep(i, a, b) for (ll i = (a)-1; i >= (b); i--)

struct Edge {
    ll a;
    ll b;
    ll opposite(ll x) {
        if (x == a) {
            return b;
        } else if (x == b) {
            return a;
        } else {
            assert(false);
            return 0;
        }
    }
};

void dfs(vector<vector<ll>>& graph, vector<Edge>& edges, vector<bool>& used, vector<ll>& number, vector<ll>& ans, ll now) {
    for (ll edge : graph[now]) {
        if (used[edge]) {
            continue;
        }
        used[edge] = true;
        ll to = edges[edge].opposite(now);
        dfs(graph, edges, used, number, ans, to);
        if (number[to] % 2 == 1) {
            ans[edge] = now;
            number[to]++;
        } else {
            ans[edge] = to;
            number[now]++;
        }
    }
}

int main() {
    ll N, M;
    cin >> N >> M;
    vector<vector<ll>> graph(N);
    vector<Edge> edges(M);
    rep(i,0,M) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        if (a > b) {
            swap(a, b);
        }
        edges[i].a = a;
        edges[i].b = b;
        graph[a].push_back(i);
        graph[b].push_back(i);
    }
    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }
    vector<ll> number(N);
    vector<bool> used(M);
    vector<ll> ans(M);
    dfs(graph, edges, used, number, ans, 0);
    rep(i,0,M) {
        cout << edges[i].opposite(ans[i]) + 1 << " " << ans[i] + 1 << endl;
    }
}

