using namespace std;

set<int> edges[100000];

bitset<100000> odd;

set<pair<int, int>> revlist;
void add(int i, int j){
    if(i > j) swap(i, j);
    pair<int, int> p = {i, j};
    if(revlist.count(p)){
        revlist.erase(p);
    }else{
        revlist.insert(p);
    }
}

bitset<100000> visited;
vector<int> ls;

void treat(){
    int sz = ls.size();
    for(int i=0; i<sz-1; i++){
        edges[ls[i]].erase(ls[i+1]);
        edges[ls[i+1]].insert(ls[i]);
    }
}

bool dfs(int i){
    visited[i] = true;
    if(odd[i]){
        treat();
        odd[i] = 0;
        return true;
    }
    for(int j : edges[i]){
        if(visited[j]) continue;
        ls.push_back(j);
        if(dfs(j)) return true;
        ls.pop_back();
    }
    return false;
}

void fail(){
    cout << -1 << endl;
    exit(0);
}

int main(){
    int N, M;
    cin >> N >> M;
    for(int i=0; i<M; i++){
        int a, b;
        cin >> a >> b;
        edges[a-1].insert(b-1);
    }

    if(M%2) fail();

    for(int i=0; i<N; i++) if(edges[i].size()%2) odd[i] = 1;

    for(int i=0; i<N; i++) if(odd[i]){
        odd[i] = 0;
        visited.reset();
        ls = {i};
        if(!dfs(i)) exit(-1);
    }

    for(int i=0; i<N; i++) for(int j : edges[i]) cout << i+1 << " " << j+1 << endl;
    return 0;
}

