        auto first_edge = s_asetEdge[sqNode].begin();
        SQWORD sqNextNode = *first_edge;
        s_asetEdge[sqNextNode].erase(sqNode);
        s_asetEdge[sqNode].erase(first_edge);
        s_avAns.emplace_back(sqNextNode, sqNode);
        vecsqNextDfsEdge.emplace_back(sqNextNode);
        s_asqDimNum[sqNode]++;
        s_asqDimNum[sqNextNode]++;
    }
    while (1) {
        if (s_asetEdge[sqNode].empty()) {
            break;
        }
        auto it = s_asetEdge[sqNode].begin();
        SQWORD sqNextNode = *it;
        s_avAns.emplace_back(sqNode, sqNextNode);
        s_asetEdge[sqNextNode].erase(sqNode);
        s_asetEdge[sqNode].erase(sqNextNode);
        vecsqNextDfsEdge.emplace_back(sqNextNode);
        s_asqDimNum[sqNextNode]++;
        s_asqDimNum[sqNode]++;
    }

    for (auto edge: vecsqNextDfsEdge) {
        execDfs(edge);
    }
}

