using namespace std;
int dim[100002];
int ptr[100002];
int ptr_tmp[100002];
int dst[100002];
int used[100002]; // 0: undef, 1: ->dst, -1: dst->
int pairwise[100002];
int main() {
    int N, M;
    int a[100000], b[100000];
    cin >> N >> M;
    for (int i=0; i<M; i++) cin >> a[i] >> b[i];
    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    for (int i=0; i<M; i++) {
        dim[a[i]]++;
        dim[b[i]]++;
    }
    int accum = 0;
    for (int v=1; v<=N; v++) {
        ptr[v] = accum;
        accum += dim[v];
    }
    ptr[N+1] = accum;

    for (int i=0; i<100002; i++) ptr_tmp[i] = ptr[i];
    for (int i=0; i<M; i++) {
        dst[ ptr_tmp[a[i]] ] = b[i];
        pairwise[ ptr_tmp[a[i]] ] = ptr_tmp[b[i]];
        dst[ ptr_tmp[b[i]] ] = a[i];
        pairwise[ ptr_tmp[b[i]] ] = ptr_tmp[a[i]];
        ptr_tmp[a[i]]++;
        ptr_tmp[b[i]]++;
    }

    queue<int> q;
    q.push(1);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        int avail = 0;
        int outdeg = 0;
        for (int i=ptr[v]; i<ptr[v+1]; i++) {
            if (used[i] == 0) avail++;
            if (used[i] == 1) outdeg++;
        }
        int out;
        if (outdeg % 2 == 0) {
            // even from avail
            out = avail / 2 * 2;
        } else {
            out = 1;
        }
        for (int i=ptr[v]; i<ptr[v+1]; i++) {
            if (used[i] == 0) {
                if (out > 0) {out--; used[i] = 1; used[pairwise[i]] = -1;}
                else {used[i] = -1; used[pairwise[i]] = 1;}
                q.push(dst[i]);
            }
        }
    }

    for (int i=1; i<=N; i++) {
        for (int j=ptr[i]; j<ptr[i+1]; j++) {
            if (used[j] == 1) {
                cout << i << " " << dst[j] << endl;
            }
        }
    }

    return 0;
}

