int main()
{
    int N, M;
    cin>>N>>M;
    vector<int> A(M), B(M);
    for (int i=0; i<M; i++)
    {
        cin>>A[i]>>B[i];
        A[i]--;
        B[i]--;
    }

    vector<int> D(N);
    vector<vector<int>> E(N);
    vector<vector<int>> EI(N);
    vector<int> C(N);
    for (int i=0; i<M; i++)
    {
        E[A[i]].push_back(B[i]);
        E[B[i]].push_back(A[i]);
        EI[A[i]].push_back(i);
        EI[B[i]].push_back(i);
        C[A[i]] ^= 1;
    }

    int c = 0;
    for (int i=0; i<N; i++)
        c += C[i];
    if (c%2!=0)
    {
        cout<<-1<<endl;
        return 0;
    }

    vector<int> PV;
    vector<int> PE;
    vector<int> V(N);
    function<void(int)> f = [&](int c)
    {
        PV.push_back(c);
        V[c] = true;

        for (int i=0; i<(int)E[c].size(); i++)
        if (!V[E[c][i]])
        {
            PE.push_back(EI[c][i]);
            f(E[c][i]);
            PE.push_back(EI[c][i]);
            PV.push_back(c);
        }
    };
    f(0);

    for (int i=0; i<(int)PV.size()-1;)
    {
        if (C[PV[i]]==0)
        {
            i++;
        }
        else
        {
            while (C[PV[i]]!=0 && i<(int)PV.size()-1)
            {
                C[PV[i]] ^= 1;
                C[PV[i+1]] ^= 1;
                D[PE[i]] ^= 1;
                i++;
            }
        }
    }

    for (int i=0; i<M; i++)
    {
        if (D[i]==0)
            cout<<A[i]+1<<" "<<B[i]+1<<endl;
        else
            cout<<B[i]+1<<" "<<A[i]+1<<endl;
    }
}

