int main(int argc, const char * argv[]) {

    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m; cin >> n >> m;
    if (m % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    vector<int> outdeg(n, 0);
    vector<edge> es(m);
    for (int i = 0; i < m; i++) {
        int a, b; cin >> a >> b; a--; b--;
        es[i].from = a;
        es[i].to = b;
        outdeg[a]++;
    }

    for (int i = 0; i < m; i++) {
        int v = min(es[i].from, es[i].to);
        if (outdeg[v] % 2 == 1) {
            swap(es[i].from, es[i].to);
            outdeg[es[i].from] = (outdeg[es[i].from] + 1) % 2;
            outdeg[es[i].to] = (outdeg[es[i].to] + 1) % 2;
        }
    }

    for (int i = 0; i < m; i++) {
        cout << es[i].from + 1 << " " << es[i].to + 1 << endl;
    }

    return 0;
}

