int const maxn = 100005;
vector<int> gr[maxn];

int used[maxn];
int cnt[maxn];
bool good = true;
set<pair<int,int>> ans;

void dfs(const int v) {
    used[v] = 1;
    for (int ne : gr[v]) {
        if (ans.find({v, ne}) == ans.end()) {
            cnt[ne] ^= 1;
            ans.insert({ne, v});
            if (!used[ne])
                dfs(ne);
        }
    }
}

int solve(int v) {
    used[v] = 1;
    for (int ne : gr[v]) {
        if (!used[ne]) {
            int res = solve(ne);
            if (res) {
                ans.erase({ne, v});
                ans.insert({v, ne});
                cnt[ne] ^= 1;
                cnt[v] ^= 1;
            }
        }
    }
    return cnt[v];
}


