void dfs(int u, int p = 0) {
    static int tme = 0;
    dfn[u] = ++tme;
    for (int v : g[u]) {
        if (v == p) continue;
        if (dfn[v]) {
            if (dfn[v] < dfn[u]) {
                tag[u] ^= 1;
                ans[u].emplace_back(v);
            }
        } else {
            dfs(v, u);
        }
    }
    if (p) {
        if (tag[u]) {
            ans[u].emplace_back(p);
        } else {
            ans[p].emplace_back(u);
            tag[p] ^= 1;
        }
    } else {
        assert(!tag[u]);
    }
}

