stack<int> path;

void dfs1(int v) {
    markVer[v] = true;
    int u;
    for (int i = 0; i < adjLis[v].size(); i++) {
        u = adjLis[v][i];
        if (!EdgeDir[v][u] and !EdgeDir[u][v]) {
            EdgeDir[u][v] = false;
            EdgeDir[v][u] = true;
            isOddDeg[v] = !isOddDeg[v];
        }
        if (!markVer[u])
            dfs1(u);
    }
}

void dfs2(int preVer, int v) {
    markVer[v] = true;
    int u;
    if (isOddDeg[v]) {
        path.push(v);
        if (path.size() > 1) {
            isOddDeg[v] = false;
            int w;
            while (path.size() > 1) {
                u = path.top();
                path.pop();
                w = path.top();
                EdgeDir[u][w] = !EdgeDir[u][w];
                EdgeDir[w][u] = !EdgeDir[w][u];
            }
            isOddDeg[w] = false;
            path.pop();
        }
    } else if (!path.empty())
        path.push(v);
    for (int i = 0; i < adjLis[v].size(); i++) {
        u = adjLis[v][i];
        if (!markVer[u])
            dfs2(v, u);
    }
    if (!path.empty())
        if (!isOddDeg[v]) {
            path.pop();
            if (path.top() != preVer) {
                path.push(v);
                path.push(preVer);
            }
        } else
            path.push(preVer);
}

