void solve() {
    cin >> n >> m;
    rep(i, m) {
        cin >> a[i] >> b[i];
        --a[i]; --b[i];
    }

    if (m % 2 != 0) { cout << -1 << endl; return; }
    UnionFind uf(n);
    rep(i, m) {
        if (!uf.same(a[i], b[i])) {
            ++cnt[a[i]]; ++cnt[b[i]];
