            use[i] = true;
            uf.unite(a[i], b[i]);
        }
        else ++cnt2[a[i]];
    }

    queue<int> que;
    vector<pair<int, int>> ans;
    rep(i, n) if (cnt[i] == 1) que.emplace(i);
    while (!que.empty()) {
        auto pos = que.front(); que.pop();
        if (used[pos]) continue;
