namespace Math_{
    int Pow(LL x,LL y,int MOD){
        int ret=1;
        while(y){
            if(y&1)
                ret=ret*x%MOD;
            y>>=1;
            x=x*x%MOD;
        }
        return ret;
    }
    void GetPrime(int N,vector<int> &Prime){
        vector<int> vis;
        vis.resize(N+5,0);
        for(int i=2;i<=N;i++){
            if(!vis[i])
                Prime.push_back(i);
            for(int j=0;j<int(Prime.size())&&Prime[j]*i<=N;j++){
                vis[Prime[j]*i]=1;
                if(i%Prime[j]==0)
                    break;
            }
        }
    }
    template<typename T> void Divide(T N,vector<PII> &A,vector<int> Prime){
        for(int i=0;i<int(Prime.size());i++){
            int p=Prime[i],cnt=0;
            while(N%p==0)
                N/=p,cnt++;
            if(cnt)
                A.push_back(make_pair(p,cnt));
            if(N==1||Prime[i]*Prime[i]>N)
                break;
        }
        if(N>1)
            A.push_back(make_pair(N,1));
    }
    void GetFac(int N,int MOD,int *fac){
        fac[0]=1;
        for(int i=1;i<=N;i++)
            fac[i]=(LL)fac[i-1]*i%MOD;
    }
    void GetFac(int N,int MOD,int *fac,int *facInv){
        GetFac(N,MOD,fac);
        facInv[N]=Pow(fac[N],MOD-2,MOD);
        for(int i=N-1;i>=0;i--)
            facInv[i]=(LL)facInv[i+1]*(i+1)%MOD;
    }
    void GetC(int N,int **C,int MOD){
        C[0][0]=1;
        for(int i=1;i<=N;i++)
            for(int j=1;j<=i;j++)
                C[i][j]=((LL)C[i-1][j-1]+(LL)C[i-1][j])%MOD;
    }
    int calC(int N,int M,int MOD,int *fac,int *facInv){
        if(M>N) return 0;
        return (LL)fac[N]*facInv[N-M]%MOD*facInv[M]%MOD;
    }
    int calC(int N,int M,int MOD){
        if(M>N) return 0;
        if(M>N-M) M=N-M;
        int ret=1,cnt=1;
        for(int i=N;i>=N-M+1;i--)
            ret=(LL)ret*i/cnt%MOD,cnt++;
        return ret;
    }
    int calA(int N,int M,int MOD,int *fac,int *facInv){
        if(M>N) return 0;
        return (LL)fac[N]*facInv[N-M+1]%MOD;
    }
    int calA(int N,int M,int MOD){
        if(M>N) return 0;
        int ret=1;
        for(int i=N;i>=N-M+1;i--)
            ret=(LL)ret*i%MOD;
        return ret;
    }
