        a--;
        b--;
        V[a].node.push_back(b);
        V[b].node.push_back(a);
    }
    if (M % 2 == 1) {
        cout << -1 << endl;
        return 0;
    }

    SegmentTree<pll> seg([](pll a, pll b) {
        if (a.first < b.first)
            return a;
        return b;
    }, pll(INF, INF));
    seg.init(N);
    REP(i, N) {
        seg.set(i, pll(V[i].node.size(), i));
    }

    memset(C, 0, sizeof(C));
    vector<pll> ans;
    while (ans.size() < M) {
        pll t = seg.get(0, N - 1);
        vector<pll> v;
        REP(i, V[t.second].node.size()) {
            ll n = V[t.second].node[i];
            pll value = seg.get(n, n);
            if (value.first == INF)
                continue;
            v.push_back(pll(t.second, n));
