void Addedge(int u,int v)
{
    E[++Cnt]=Edge(u,v);
    nxt[Cnt]=head[u];
    head[u]=Cnt;
}
void bfs(int root)
{
	int tot=0;
	queue<int> que;
	que.push(root);
	vis[root]=1;
	while(!que.empty())
	{
		int u=que.front();que.pop();
		id[u]=++tot;
		for(int i=head[u];i;i=nxt[i])
			if(!vis[E[i].v])
			{
				vis[E[i].v]=1;
				que.push(E[i].v);
			}
	}
}
void Solve()
{
	for(int i=n;i>=1;i--)
	{
		if(!v[i])
		{
			int u=i;
			if(ind[u]%2)
			{
				for(int i=head[u];i;i=nxt[i])
				{
					ind[E[i].v]++;
					v[E[i].v]=1;
					printf("%d %d\n",E[i].v,u);
				}
			}
			else
			{
				for(int i=head[u];i;i=nxt[i])
				{
					v[E[i].v]=1;
					printf("%d %d\n",u,E[i].v);
				}
			}
		}
	}
}
int main()
{
	//freopen("degree.in","r",stdin);
	//freopen("degree.out","w",stdout);
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++)
	{
		int u,v;
		scanf("%d%d",&u,&v);
		root=u;
		cnt[u]++,cnt[v]++;
		Addedge(u,v);
		Addedge(v,u); 
	}
	if(m%2)
	{
		printf("-1\n");
		return 0;
	}
	bfs(root);
	Solve();
	return 0;
}

