const int N=100005;
int vis[N],ds[N],even[N];
vector<int> G[N];
bool cmp(int x,int y){
    if (!vis[x]&&!vis[y]) return ds[x]<ds[y];
    if (!vis[x]||!vis[y]) return !vis[x];
    return ds[x]<ds[y];
}

void work(int x,int y){
    printf("%d %d\n",x,y);
}
int main(){
   // freopen("in.txt","r",stdin);
   // freopen("out.txt","w",stdout);
    int n,m;cin>>n>>m;
    if (m%2) {puts("-1");return 0;}
    for (int i=1;i<=m;i++){
        int x,y;
        scanf("%d%d",&x,&y);
        G[x].pb(y);G[y].pb(x);
        ds[x]++,ds[y]++;
    }
    int he,ta;
    static int q[N];q[he=ta=1]=1;
    for (int i=1;i<=n;i++){
        int x=q[i];vis[x]=1;
        for (int y:G[x]) if (!vis[y]) q[++ta]=y;
    }
    memset(vis,0,sizeof(vis));
    for (int i=n;i>=1;i--){
        int x=q[i];vis[x]=1;
        sort(G[x].begin(),G[x].end(),cmp);
        while (!G[x].empty()&&vis[G[x].back()]) G[x].pop_back();
        if ((ds[x]&1)^even[x]){
            work(G[x].back(),x);ds[G[x].back()]--;
            even[G[x].back()]^=1;G[x].pop_back();
        }
        for (int y:G[x]){
            work(x,y);ds[y]--;
        }
    }

    return 0;
}

