using namespace std;

typedef long long ll;

struct node
{
  bool odd = false;
  ll nokori = 0;
  vector<ll> rin = vector<ll>(0);
};

int main(int argc, char const *argv[])
{
  ll n, m;
  cin >> n >> m;
  vector<ll> a(m), b(m);
  vector<vector<ll>> edge(n, vector<ll>(0));
  vector<node> v(n);
  ll muko = m;
  vector<pair<ll, ll>> syou(n);
  REP(i, m)
  {
    cin >> a[i] >> b[i];
    a[i]--;
    b[i]--;
    v[a[i]].nokori++;
    v[a[i]].nokori++;
    v[a[i]].rin.push_back(b[i]);
    v[b[i]].rin.push_back(a[i]);
  }
  if (m % 2 == 1)
  {
    cout << -1 << endl;
    return 0;
  }
  REP(i, n)
  {
    if (v[i].nokori == 1)
    {
      v[i].nokori == 0;
      ll tmp = *v[i].rin.begin();
      v[i].rin.pop_back();
      v[tmp].nokori--;
      //v[tmp].rin.erase((ll)i);
      v[tmp].odd = !v[tmp].odd;
      edge[tmp].push_back(i);
      muko--;
    }
  }
  priority_queue<pair<ll, ll>> pqNode;
  sort(ALL(syou));
  REP(i, n)
  {
    syou[i] = {v[i].nokori, i};
    pqNode.push({v[i].nokori, i});
  }
  while (muko > 0)
  {
    node top = v[pqNode.top().second];
    //node top = v[syou[0].second];
    if (top.nokori == 0)
    {
      //syou.erase(syou.begin());
      pqNode.pop();
      continue;
    }
    for (auto e : top.rin)
    {
      node pea = v[e];
      if (top.odd)
      {
        top.odd = !top.odd;
        edge[pqNode.top().second].push_back(e);
      }
      else
      {
        pea.odd = !pea.odd;
        edge[e].push_back(pqNode.top().second);
      }
      top.nokori--;
      pea.nokori--;
      muko--;
      pqNode.push({pea.nokori, e});
    }
    //    sort(ALL(syou));
  }
  REP(i, n)
  {
    if (v[i].odd)
    {
      cout << -1 << endl;
      return 0;
    }
  }
  // output
  REP(i, n)
  {
    for (auto e : edge[i])
    {
      cout << i + 1 << " " << e + 1 << endl;
    }
  }
  return 0;
}

