using namespace std;
using ll = long long;
using P = pair<string, string>;
ll MOD = 1e9+7;
int main()
{
    int n, m;
    cin >> n >> m;
    vector<vector<int>> d(n);
    for(int i = 0; i < m; i++)
    {
        int a, b;
        cin >> a >> b;
        a--;b--;
        d[a].push_back(b);
        d[b].push_back(a);
    }
    ll size = 0;
    for(int i = 0; i < n; i++)
    {
        size += d[i].size();
    }
    size /= 2;
    if(size % 2 == 1)
    {
        cout << -1 << endl;
        return 0;
    }

    vector<vector<int>> ans(n);
    int pos = 0;
    for(int i = 0; i < n; i++)
    {
        if(d[i].size() == 1)
        {
            ans[d[i][0]].push_back(i);
            if(pos == 0) pos = d[i][0];
        }
    }
    queue<int> que;
    que.push(pos);
    vector<bool> flag(n);
    for(int i = 0; i < n; i++)
    {
        flag[i] = false;
    }

    while(que.size())
    {
        int cand = que.front();
        que.pop();
        if(flag[cand]) continue;
        flag[cand] = true;
        int ds = d[cand].size();
        int as = ans[cand].size();
        if(ds == 1) continue;
        if((ds - as) % 2 == 0)
        {
            for(int from : d[cand])
            {
                if(flag[from]) continue;
                ans[from].push_back(cand);
                que.push(from);
            }
        }
        else
        {
            int check = -1;
            for(int i = 0; i < ds; i++)
            {
                if(flag[d[cand][i]]) continue;
                if(check == -1)
                {
                    ans[cand].push_back(d[cand][i]);
                    check = 0;
                }
                else
                {
                    ans[d[cand][i]].push_back(cand);
                }
                que.push(d[cand][i]);
            }
        }
    }
    for(int i = 0; i < n; i++)
    {
        for(int to : ans[i])
        {
            cout << i+1 << " " << to + 1 << endl;
        }
    }
}

