#define range(i, m, n) for(int i = m; i < n; i++)
#define husk(i, m, n) for(int i = m; i > n; i--)

int n, m;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> m;
  vector<set<int>> g(n);
  range(i, 0, m) {
    int u, v;
    cin >> u >> v;
    u--; v--;
    g[u].insert(v);
    g[v].insert(u);
  }
  if(m & 1) {
    cout << -1;
    return 0;
  }
  vector<int> par(n, -1);
  vector<set<int>> to(n);
  vector<int> was(n);
  set<int> cur;
  function<void(int, int)> dfs = [&](int v, int p) {
    par[v] = p;
    was[v] = 1;
    for(int u : g[v]) {
      if(was[u]) continue;
      to[v].insert(u);
      dfs(u, v);
    }
    if(to[v].empty()) cur.insert(v);
  };
  dfs(0, -1);
  auto cut = [&](int u, int v) {
    g[u].erase(v);
    g[v].erase(u);
    if(u != par[v] && v != par[u]) return;
    if(v == par[u]) swap(u, v);
    par[v] = -1;
    to[u].erase(v);
    cur.erase(v);
    if(to[u].empty()) cur.insert(u);
  };
  auto link = [&](int v) {
    if(g[v].empty()) return;
    int u = *g[v].begin();
    if(to[u].empty()) cur.erase(u);
    par[v] = u;
    to[u].insert(v);
    if(to[v].empty()) cur.insert(v);
  };
  int cnt = 0;
  auto go = [&](int x, int y, int z) {
    cnt += 2;
    cout << y + 1 << " " << x + 1 << endl;
    cout << y + 1 << " " << z + 1 << endl;
  };
  while(cnt < m) {
    int u = *cur.begin();
    int v = par[u];
    assert(~v);
    int z = par[v];
    if(to[v].size() > 1) {
      for(int a : to[v]) if(a != u) {
        z = a;
        break;
      }
    }
    assert(~z);
    if(z == par[v]) {
      go(u, v, z);
      cut(u, v); cut(v, z);
      link(v); link(u);
    } else if(g[u].find(z) != g[u].end()) {
      go(u, z, v);
      cut(u, z);
      cut(z, v);
      link(z);
    } else {
      go(u, v, z);
      cut(u, v); cut(z, v);
      link(u); link(z);
    }
  }
  return 0;
}

