  REP (i, m) {
    int u, v; cin >> u >> v;
    u--; v--;
    g[u].insert(v);
    g[v].insert(u);
  }
  if (m % 2) {
    cout << -1 << endl;
    return 0;
  }

  vector<set<int>> ones(n);
  vector<ii> ans;

  auto del = [&](int u, int v) {
    g[u].erase(v);
    g[v].erase(u);
    if (ones[u].count(v)) ones[u].erase(v);
    if (ones[v].count(u)) ones[v].erase(u);
  };
  queue<int> q;
  REP (i, n) {
    if (g[i].size() == 1) {
      q.push(i);
      ones[i].insert(*g[i].begin());
    }
  }
  int idx = 0;
  while (1) {
    if (q.empty()) {
      while (idx < n && g[idx].size() == 0) idx++;
      if (idx == n) break;
      q.push(idx);
