void MAIN() {
    scanf("%d%d", &N, &M);
    REP (i, M) {
	int x, y;
	scanf("%d%d", &x, &y);
	x--; y--;
	A[i] = x;
	B[i] = y;
	G[x].push_back(i);
	G[y].push_back(i);
    }

    memset(depth, -1, sizeof depth);
    VI ord;
    ord.push_back(0);
    depth[0] = 0;
    REP (i, N) {
	int v = ord[i];
	EACH (e, G[v]) {
	    int w = A[*e]^B[*e]^v;
	    if (depth[w] == -1) {
		depth[w] = depth[v] + 1;
		ord.push_back(w);
	    }
	}
    }

    REP (i, N) {
	int v = ord[N-1-i];
	EACH (e, G[v]) {
	    int w = A[*e]^B[*e]^v;
	    if (depth[w] == depth[v] + 1) {
		if (odd[w]) {
		    A[*e] = w;
		    B[*e] = v;
		    odd[w] ^= 1;
		} else {
		    A[*e] = v;
		    B[*e] = w;
		    odd[v] ^= 1;
		}
	    } else if (depth[w] == depth[v] && v < w) {
		A[*e] = v;
		B[*e] = w;
		odd[v] ^= 1;
	    }
	}
    }

    if (*max_element(odd, odd+N) == 0) {
	REP (i, M) printf("%d %d\n", A[i]+1, B[i]+1);
    } else {
	puts("-1");
    }
}

