					c[v] ^= 1;
					res.push_back({v, u});
					wl.push(v);
				}
			}
		if(fix) return cout << -1, 0;
	}
	for(pair<int,int> e: res)
		cout << e.first << " " << e.second << endl;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 1e5 + 5, M = 20;
bool mark[N];
int cnt[N];
vector<int> g[N];
vector<pair<int, int>> E;
map<int, int> id[N];

int st[N], en[N], timer;
int par[N][M];
void pfs(int u, int p) {
  par[u][0] = (p == -1 ? u : p);
  for (int i = 1; i < M; i++) {
    par[u][i] = par[par[u][i - 1]][i - 1];
  }
  mark[u] = true;
  st[u] = timer++;
  for (int v : g[u]) {
    if (!mark[v]) {
      pfs(v, u);
    }
  }
  en[u] = timer;
}

bool is_anc(int u, int v) {
  return st[u] <= st[v] && en[u] >= en[v];
}

int lca(int u, int v) {
  if (is_anc(u, v)) {
    return u;
  }
  if (is_anc(v, u)) {
    return v;
  }
  for (int i = M - 1; ~i; i--) {
    if (!is_anc(par[u][i], v)) {
      u = par[u][i];
    }
  }
  return par[u][0];
}

int lazy[N];
int lfs(int u, int p) {
  mark[u] = true;
  for (int v : g[u]) {
    if (!mark[v]) {
      lazy[u] += lfs(v, u);
    }
  }
  assert(lazy[u] >= 0);
  if (p != -1 && lazy[u] % 2) {
    id[u][p] = 1;
    id[p][u] = 1;
  }
  return lazy[u];
}

