  }
  for (int i = 0; i < m; i++) {
    int u, v;
    cin >> u >> v;
    --u, --v;
    E.emplace_back(u, v);
    g[u].push_back(v);
    g[v].push_back(u);
    ++cnt[u];
  }
  pfs(0, -1);
  vector<int> nxt;
  for (int i = 0; i < n; i++) {
    if (cnt[i] & 1) {
      nxt.push_back(i);
    }
  }
  assert(nxt.size() % 2 == 0);
  for (int i = 0; i < nxt.size(); i += 2) {
    ++lazy[nxt[i]];
    ++lazy[nxt[i + 1]];
    ----lazy[lca(nxt[i], nxt[i + 1])];
  }
  memset(mark, false, sizeof mark);
  lfs(0, -1);
  for (auto e : E) {
    if (id[e.first][e.second]) {
      cout << e.second + 1 << ' ' << e.first + 1 << '\n';
    } else {
