        deg[v]++;
    }
    queue<int> q;
    for (int i = 0; i < N; i++) {
        if (deg[i] == 1) {
            q.push(i);
        }
    }
    vector<int> out(N, 0);
    while (!q.empty()) {
        int now = q.front();
        q.pop();
        if (deg[now] == 0) {
            flag[now] = 1;
            continue;
        }
        int adj = g[now][0];
        cout << adj + 1 << now + 1 << endl;
        out[adj] = (out[adj] + 1) % 2;
        deg[adj]--;
        if (deg[adj] == 1)
            q.push(adj);
    }

    for (int i = 0; i < N; i++) {
        if (deg[i] == 0)
            continue;
        int n;
        if (out[i] == 0) {
            n = deg[i] / 2 * 2;
        } else {
            if (deg[i] % 2 == 0) {
                n = deg[i] - 1;
            } else {
                n = deg[i];
            }
        }
        int count = 0;
        for (int j = 0; j < g[i].size(); j++) {
            int adj = g[i][j];
            if (deg[adj] == 0)
                continue;
            count++;
            if (count <= n) {
                cout << i + 1 << adj + 1 << endl;
            } else {
                cout << adj + 1 << i + 1 << endl;
                out[adj] = (out[adj] + 1) % 2;
            }
            deg[adj]--;
        }
        deg[i] = 0;
    }
}

