        par[x] = p;
        dep.push_back(d);
        disv[x] = dis;
        in[x] = cnt++;
        forg(gi, g[x]) {
            if (t == p) { continue; }
            dfs(t, x, d + 1, dis + c);
            id[cnt] = x;
            dep.push_back(d);
            cnt++;
        }
    }
    void precalc() {
        never = false;
        cnt = 0;
        dep.clear();
        disv.assign(n, 0);
        in.assign(n, -1);
        id.assign(2 * n - 1, -1);
        par.assign(n, -1);
        dfs(root, -1, 0);
        rmq.init(dep);
    }    /********hld**************/    int pos;
    void hld_build() {
        never_hld = false;
        pos = 0;
        vid.assign(n, -1);
        head.assign(n, 0);
        sub.assign(n, 1);
        hvy.assign(n, -1);
        hdep.assign(n, 0);
        inv.assign(n, 0);
        type.assign(n, 0);
        build();
    }
    void build(vector<int> rs = vector<int>(1, 0)) {
        int c = 0;
        for (int r:rs) {
            dfs(r);
            bfs(r, c++);
        }
    }
    void dfs(int rt) {
        stack<P> st;
        hdep[rt] = 0;
        st.emplace(rt, 0);
        while (!st.empty()) {
            int v = st.top().first;
            int &i = st.top().second;
            if (i < (int) g[v].size()) {
                int u = g[v][i++].t;
                if (u == par[v]) continue;
                hdep[u] = hdep[v] + 1;
                st.emplace(u, 0);
            } else {
                st.pop();
                int res = 0;
                forg(gi, g[v]) {
                    int u = t;
                    if (u == par[v]) continue;
                    sub[v] += sub[u];
                    if (res < sub[u]) res = sub[u], hvy[v] = u;
                }
            }
        }
    }
    void bfs(int r, int c) {
        int &k = pos;
        queue<int> q({r});
        while (!q.empty()) {
            int h = q.front();
            q.pop();
            for (int i = h; i != -1; i = hvy[i]) {
                type[i] = c;
                vid[i] = k++;
                inv[vid[i]] = i;
                head[i] = h;
                forg(gi, g[i])if (t != par[i] && t != hvy[i]) q.push(t);
            }
        }
    }
    vi vid;
public:
    using undigraph<T>::g;    using undigraph<T>::n;    using undigraph<T>::edges;    using undigraph<T>::usedv;
    vector<int> disv;
    vector<signed> dep, par;
    vector<int> head, sub, hvy, inv, type, hdep/*おそらくグループ内のdep*/;/*vid := bel()*/    int root;
    tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }
    int lca(int a, int b) {
        if (never)precalc();
        int x = in[a];
        int y = in[b];
        if (x > y) { swap(x, y); }
        int pos = rmq.query(x, y + 1);
        return id[pos];
    }
    int dis(int a, int b) {
        if (never)precalc();
        int x = in[a];
        int y = in[b];
        if (x > y) { swap(x, y); }
        int pos = rmq.query(x, y + 1);
        int p = id[pos];
        return disv[a] + disv[b] - disv[p] * 2;
    }    /*O(N) 頂点に対しての処理を渡す*/    void for_each_(int u, int v, function<void(int)> fnode) {
        int r = lca(u, v);
        while (u != r) {
            fnode(u);
            u = par[u];
        }
        while (v != r) {
            fnode(v);
            v = par[v];
        }
        fnode(r);
    }    /*******hld********/    /*[l,r) O(log(N))*/    void for_each_(int u, int v, const function<void(int, int)> &f) {
        if (never_hld)hld_build();
        while (1) {
            if (vid[u] > vid[v]) swap(u, v);
            f(max(vid[head[v]], vid[u]), vid[v] + 1);
            if (head[u] != head[v]) v = par[head[v]]; else break;
        }
    }
    void for_each_edge(int u, int v, const function<void(int, int)> &f) {
        if (never_hld)hld_build();
        while (1) {
            if (vid[u] > vid[v]) swap(u, v);
            if (head[u] != head[v]) {
                f(vid[head[v]], vid[v] + 1);
                v = par[head[v]];
            } else {
                if (u != v) f(vid[u] + 1, vid[v] + 1);
                break;
            }
        }
    }
    int bel(int v) {
        if (never_hld)hld_build();
        return vid[v];
    }    /*辺のクエリを扱うときどの頂点に持たせればいいか(vidを返すのでそのままupd出来る)*/    int bel(int f, int t) {
        if (never_hld)hld_build();
        return hdep[f] > hdep[t] ? vid[f] : vid[t];
    }
    int bel(edge<T> &e) {
        if (never_hld)hld_build();
        return hdep[e.f] > hdep[e.t] ? vid[e.f] : vid[e.t];
    }    /*******hld*******/};
