using namespace std;
const int N = 100010;
int _w;

int n, m, eu[N], ev[N], flip[N], deg[N];

namespace G {
	int head[N], nxt[N*2], to[N*2], id[N*2], eid;
	void init() {
		eid = 0;
		memset(head, -1, sizeof head);
	}
	void link( int u, int v, int w ) {
		to[eid] = v, id[eid] = w, nxt[eid] = head[u], head[u] = eid++;
		to[eid] = u, id[eid] = w, nxt[eid] = head[v], head[v] = eid++;
	}
}

namespace DSU {
	int pa[N];
	void init() {
		for( int i = 0; i < N; ++i )
			pa[i] = i;
	}
	int find( int u ) {
		return u == pa[u] ? u : pa[u] = find( pa[u] );
	}
	bool link( int u, int v ) {
		u = find(u), v = find(v);
		if( u == v ) return false;
		return pa[u] = v, true;
	}
}

void dfs( int u, int fa, int w ) {
	using namespace G;
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		if( v == fa ) continue;
		dfs(v, u, id[i]);
	}
	if( deg[u] % 2 == 1 ) {
		flip[w] ^= 1;
		++deg[u], ++deg[fa];
	}
}

int main() {
	_w = scanf( "%d%d", &n, &m );
	for( int i = 1; i <= m; ++i ) {
		_w = scanf( "%d%d", eu+i, ev+i );
		flip[i] = 0;
		++deg[eu[i]];
	}
	G::init();
	DSU::init();
	for( int i = 1; i <= m; ++i ) {
		int u = eu[i], v = ev[i];
		if( DSU::link(u, v) ) {
			G::link(u, v, i);
		}
	}
	int cnt_odd = 0;
	for( int i = 1; i <= n; ++i )
		if( deg[i] % 2 == 1 )
			++cnt_odd;
	if( cnt_odd % 2 == 1 ) {
		puts("-1");
		return 0;
	}
	dfs(1, 0, 0);
	for( int i = 1; i <= m; ++i ) {
		if( flip[i] ) swap( eu[i], ev[i] );
		printf( "%d %d\n", eu[i], ev[i] );
	}
	return 0;
}

