        return v;
    return parent[v] = get_parent(parent[v]);
}

void union_set(int a, int b) {
    a = get_parent(a);
    b = get_parent(b);
    if (a != b) {
        if (sz(ver[a]) < sz(ver[b]))
            swap(a, b);
        for (auto v:ver[b]) {
            ver[a].insert(v);
        }
        parent[b] = a;
