struct UnionFind {
    vector<int> d; // 根なら (-サイズ), そうでないなら親の番号
    UnionFind(int N) : d(N, -1){} // 全て根として初期化

    int root(int x) { // データ x が属する木の根を再帰で得る
        if (d[x] < 0) return x;
        return d[x] = root(d[x]);
    }

    bool unite(int x, int y) { // x と y の木を併合. 併合した場合 true
        x = root(x); y = root(y); // x <- x の根, y <- y の根
        if (x == y) return false; 
        // merge technique（データ構造をマージするテク. 小を大にくっつける）
        if (d[x] > d[y]) swap(x, y);    // x の木のサイズ > y の木のサイズにする. d[x], d[y] < 0 に注意.
        d[x] += d[y];   // x の木のサイズ += y の木のサイズ
        d[y] = x;   // y の親は x
        return true;
    }

    bool same(int x, int y) { // 2つのデータ x, y が属する木が同じなら true
        return root(x) == root(y);
    }

    int size(int x) { // 素集合のサイズ
        return -d[root(x)]; // d[root(x)] < 0 に注意.
    }
};

int n, m;
vi cost;
vvi TREE;
vector<P> ans;

void dfs(int v = 0, int p = -1){ 
    for(auto u : TREE[v]){
        if(u == p) continue;
        dfs(u, v);
    }    
    // go back : v -> p
    if(p == -1) return;
    if(cost[v] % 2 == 0){
        ans.pb({p, v});
        cost[p]++;
    }else{
        ans.pb({v, p});
        cost[v]++;
    }
}

void Main(){
    cin >> n >> m;
    if(m % 2){
        cout << -1 << endl;
        return;
    }

    TREE.resize(n);
    cost.resize(n, 0);
    UnionFind UF(n); 

    rep(i, m){
        int a, b; cin >> a >> b; a--; b--;
        if(!UF.same(a, b)) {
            UF.unite(a, b);
            TREE[a].pb(b);
            TREE[b].pb(a);
        }else{
            // 全域木に入らない辺の向きを先に決める
            ans.pb({a, b});
            cost[a]++;
        }
    }

    dfs();
    for(auto [x, y] : ans){
        cout << x+1 << " " << y+1 << endl;
    }

    return;
}

