set<int> edges[100005];
void solve() {
  int n, m;
  cin >> n >> m;
  if(m%2) {
    die();
  }
  for(int i = 0; i < m; i++) {
    int a, b;
    cin >> a >> b;
    edges[a].insert(b);
    edges[b].insert(a);
  }
  queue<int> q;
  int lhs = 1;
  for(int i = 1; i <= n; i++) {
    if(edges[i].size() == 1) {
      q.push(i);
    }
  }
  vector<pii> ret;
  while(!q.empty() || lhs <= n) {
    if(q.empty()) {
      while(lhs <= n && edges[lhs].empty()) lhs++;
      if(lhs > n) break;
      q.push(lhs);
    }
    int out = q.front();
    q.pop();
    if(edges[out].empty()) continue;
    int cand = edges[out].size() == 1 ? *edges[out].begin() : out;
    int need = 2;
    if(cand != out) {
      ret.emplace_back(cand, out);
      edges[out].erase(cand);
      edges[cand].erase(out);
      need--;
    }
    while(need--) {
      int nextCand = *edges[cand].begin();
      ret.emplace_back(cand, nextCand);
      edges[cand].erase(nextCand);
      edges[nextCand].erase(cand);
      if(edges[nextCand].size() == 1) q.push(nextCand);
    }
  }
  for(pii out: ret) {
    cout << out.first << " " << out.second << "\n";
  }
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << ": ";
    solve();
  }
}

