template<typename T >
struct edge {
  int to;
  T cost;
  edge()=default;
  edge(int to, T cost) : to(to), cost(cost) {}
};
template<typename T>
using edges=vector<edge<T>>;
template<typename T>
using WeightGraph=vector<edges<T>>;

void dfs(int idx,vector<bool> &visited,vector<bool> &tree,WeightGraph<int> &g){
	visited[idx]=true;
	for(auto e:g[idx]){
		if(visited[e.to]) continue;
		tree[e.cost]=true;
		dfs(e.to,visited,tree,g);
	}
}

void dfs2(int idx,int par,vector<bool> &tree,WeightGraph<int> &g,vector<pii> &ret,vector<bool> &odd){

	for(auto e:g[idx]){
		if(tree[e.cost]){
			if(par==e.to) continue;
			dfs2(e.to,idx,tree,g,ret,odd);
		}
	}
	if(par==-1) return;
	if(odd[idx]){
		ret.emplace_back(par,idx);
		if(odd[par]) odd[par]=false;
		else odd[par]=true;
	}else{
		ret.emplace_back(idx,par);
	}
}

