	bin101();

	int N,M;
	cin>>N>>M;
	vector<int> u(M),v(M); 
	WeightGraph<int> g(N);
	for(int i=0;i<N;i++){
		int a,b;
		cin>>a>>b;
		a--; b--;
		u[i]=a; v[i]=b;
		g[a].emplace_back(b,i);
		g[b].emplace_back(a,i);
	}
	if(M%2==1){
		cout<<-1<<endl;
		return 0;
	}
	vector<bool> odd(M,true);
	vector<bool> tree(M,false);
	vector<bool> visited(N,false);
	vector<pii> ret;
	dfs(0,visited,tree,g);
	for(int i=0;i<M;i++){
		if(tree[i]) continue;
		int a=u[i],b=v[i];
		if(odd[a]) odd[a]=false;
		else odd[a]=true;
		ret.emplace_back(a,b);
	}
	dfs2(0,-1,tree,g,ret,odd);

	for(int i=0;i<ret.size();i++){
		ret[i].first++;
		ret[i].second++;
		cout<<ret[i]<<endl;
	}
}

