int vis[100005];
int parent(int a) {
	if (par[a] == a) return a;
	return par[a] = parent(par[a]);
}

int unite(int a, int b) {
	if (parent(a) == parent(b)) return 0;
	return par[par[a]] = par[b];
}

int dfs(int at, int par = 0) {
	int ret = out[at];
	vis[at] = 1;
	for (auto& p : adj[at]) {
		if (p.first == par) continue;
		int x = dfs(p.first, at);
		if (x & 1) dir[p.second] ^= 1, x^=1, ret ^= 1;
		ret += x;
	}
	return ret;
}

void solve(int ks) {
	scanf("%d %d", &n, &m);
	for (int i = 1; i <= n; i++) par[i] = i;
	for (int i = 1; i <= m; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		::u[i] = u;
		::v[i] = v;
		// u->v
		out[u]++;
		if (unite(u, v)) {
			adj[u].push_back({ v, i });
			adj[v].push_back({ u, i });
		}
	}



	int odd = 0;
	for (int i = 1; i <= n; i++) odd += (out[i] & 1);
	if (odd & 1) {
		printf("-1\n");
		return;
	}

	for (int i = 1; i <= n; i++) if (!vis[i]) dfs(i);
	for (int i = 1; i <= m; i++) {
		if (dir[i] == 0) printf("%d %d\n", u[i], v[i]);
		else printf("%d %d\n", v[i], u[i]);
	}
}

