void dfs(vector<vector<int>>& path, vector<int>& tr, int v, vector<int>& cnt,vector<int>& u) {
	REP(i, path[v].size()) {
		int t = path[v][i];
		if (tr[t] < 0) {
			tr[t] = v;
			cnt[v]++;
			//u[cn] = 1;
			dfs(path, tr, t, cnt, u);
		}
		cn++;
	}
	return;
}
vector<P> eul;
vector<int> pos, neg;
void eular(vector<vector<int>>& path,vector<int>& tr,int v) {
	pos[v] = eul.size();
	eul.push_back(P(v,1));
	REP(i, path[v].size()) {
		int t = path[v][i];
		if (tr[t] == v) {
			eular(path, tr, t);
		}
	}
	neg[v] = eul.size();
	eul.push_back(P(v, -1));
}
vector<int> imos;
vector<P> ans;
void dfs2(vector<vector<int>>& path, vector<int>& tr, int v) {
	//eul.push_back(P(v, 1));
	REP(i, path[v].size()) {
		int t = path[v][i];
		if (tr[t] == v) {
			dfs2(path, tr, t);
		} else if(tr[v]!=t && v>t) {
			ans.push_back(P(v,t));
			imos[0]++;
			imos[neg[v]]--;
		}
	}
	//eul.push_back(P(v, -1));
}

