set<int> edges[100005];
int outdeg[100005];
void solve() {
  int n, m;
  cin >> n >> m;
  if(m%2) {
    die();
  }
  for(int i = 0; i < m; i++) {
    int a, b;
    cin >> a >> b;
    edges[a].insert(b);
    edges[b].insert(a);
  }
  queue<int> q;
  for(int i = 1; i <= n; i++) {
    if(edges[i].size() == 1) {
      q.push(i);
    }
  }
  vector<pii> ret;
  int lhs = 1;
  while(!q.empty() || lhs <= n) {
    if(q.empty()) {
      while(lhs <= n && edges[lhs].empty()) lhs++;
      if(lhs > n) break;
      q.push(lhs);
    }
    int cand = q.front();
    q.pop();
    if(edges[cand].empty()) continue;
    if(edges[cand].size() == 1) {
      int other = *edges[cand].begin();
      edges[cand].erase(other);
      edges[other].erase(cand);
      if(outdeg[cand]%2) {
        ret.emplace_back(cand, other);
        outdeg[cand]++;
      }
      else {
        ret.emplace_back(other, cand);
        outdeg[other]++;
      }
      if(edges[other].size() == 1) q.push(other);
      continue;
    }
    int other = *edges[cand].begin();
    edges[cand].erase(other);
    edges[other].erase(cand);
    ret.emplace_back(cand, other);
    outdeg[cand]++;
    if(edges[cand].size() == 1) {
      q.push(cand);
    }
    if(edges[other].size() == 1) {
      q.push(other);
    }
  }
  for(pii out: ret) {
    cout << out.first << " " << out.second << "\n";
  }
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << ": ";
    solve();
  }
}

