bool isHanten[100000];

//全域木を作る
void dfs(int v, int dep) {
	int i;

	visit[v] = true;
	depth[v] = dep;
	rep(i, et[v].size()) {
		int nv = et[v][i];
		if (visit[nv]) continue;
		tree[v].push_back(nv);
		tree[nv].push_back(v);
		parent[nv] = v;
		dfs(nv, dep + 1);
	}
}

int lca(int u, int v) {
	if (depth[u] < depth[v]) {
		swap(u, v);
	}

	if (depth[u] > depth[v]) {
		int i;
		int diff = depth[u] - depth[v];
		for (i = 19; i >= 0; i--) {
			if ((diff >> i) % 2 == 1) {
				u = parents[i][u];
			}
		}
	}

	int i;
	for (i = 19; i >= 0; i--) {
		if (parents[i][u] != parents[i][v]) {
			u = parents[i][u];
			v = parents[i][v];
		}
	}
	if (u == v) return u;
	return parent[u];
}

void fillEdge(int oya, int ko) {
	fillCnt[oya]--;
	fillCnt[ko]++;
}

int dfs2(int p, int v) {
	int i;
	int ssum = fillCnt[v];

	rep(i, tree[v].size()) {
		int nv = tree[v][i];
		if (nv == p) continue;
		ssum += dfs2(v, nv);
	}

	//辺p -- vの向きを決める
	if (v != 0) {
		int eid = edge_id[P(p, v)];
		//cout << "p, v = " << p << ", " << v << ", eid = " << eid << endl;
		if (ssum % 2 == 0) { isHanten[eid] = false; }
		else { isHanten[eid] = true; }
	}
	return ssum;
}

