	if (odd_cnt % 2 != 0) { cout << "-1" << endl; return 0; }

	parent[0] = 0;
	dfs(0, 0);
	rep(i, n) parents[0][i] = parent[i];
	rep(i, 19) {
		rep(j, n) {
			parents[i + 1][j] = parents[i][parents[i][j]];
		}
	}

	vector<int> vecs;
