void solve() {
  int n, m; cin >> n >> m;
  vector<unordered_set<int>> edges(n);
  rep(i, m) {
    int x, y; cin >> x >> y;
    x--, y--;
    edges[x].insert(y);
    edges[y].insert(x);
  }
  if (m % 2 == 1) no();
  vector<pair<int, int>> ans;
  rep(i, n) {
    int ss = i, pr = -1;
    while (true) {
      if (pr == -1 && (edges[ss].size() % 2) == 0) {
        each(s, edges[ss]) {
          ans.emplace_back(ss + 1, s + 1);
          edges[s].erase(ss);
        }
        break;
      }
      if (pr == -1) {
        int c = 0;
        each(s, edges[ss]) {
          if (++c == edges[ss].size()) {
            pr = ss, ss = s;
          } else {
            ans.emplace_back(ss + 1, s + 1);
            edges[s].erase(ss);
          }
        }
        continue;
      }
      if (pr != -1) {
        ans.emplace_back(ss + 1, pr + 1);
        edges[pr].erase(ss);
        edges[ss].erase(pr);
        pr = -1;
        if (edges[ss].size() % 2 == 1) {
          each(s, edges[ss]) {
            ans.emplace_back(ss + 1, s + 1);
            edges[s].erase(ss);
          }
          break;
        }
      }
      int c = 0;
      each(s, edges[ss]) {
        if (++c == edges[ss].size()) {
          pr = ss, ss = s;
        } else {
          ans.emplace_back(ss + 1, s + 1);
          edges[s].erase(ss);
        }
      }
    }
  }
  rep(i, m) cout << ans[i] << '\n';
}

