void make_path(int v, int w)
{
  vector<int> from(N, -1);
  queue<info> P;
  P.push(info(-1, v));
  while (!P.empty())
  {
    int f = get<0>(P.front());
    int now = get<1>(P.front());
    P.pop();
    if (from[now] == -1)
    {
      from[now] = f;
      if (now == w)
      {
        break;
      }
      for (auto x : W[now])
      {
        if (from[x] == -1)
        {
          P.push(info(now, x));
        }
      }
    }
  }
  v = from[w];
  while (v != -1)
  {
    edge e = edge(v, w);
    edge f = edge(w, v);
    if (rev.find(e) == rev.end())
    {
      rev.insert(e);
      rev.insert(f);
    }
    else
    {
      rev.erase(e);
      rev.erase(f);
    }
    w = v;
    v = from[w];
  }
}

void make_rev()
{
  for (auto i = 0u; i < pts.size(); i += 2)
  {
    int v = pts[i];
    int w = pts[i + 1];
    make_path(v, w);
  }
}

