struct UnionFind{
  vector<int> par;

  UnionFind(int N): par(N){
    for(int i=0;i<N;i++) par[i]=i;
  }

  int root(int x){
    if(par[x]==x) return x;
    else return par[x]=root(par[x]);
  }

  void unite(int x,int y){
    int rx=root(x);
    int ry=root(y);
    if(rx!=ry) par[rx]=ry;
  }

  bool sameroot(int x,int y){
    return root(x)==root(y);
  }

};


int main(){
    int N,M;
    cin>>N>>M;
    if(M%2==1){
        cout<<-1<<endl;
        return 0;
    }
    UnionFind uf(N);
    vector<int> from(N,0);
    vector<int> layer(N,0);
    vector<int> tonari[100001];
    vector<bool> visit(N,false);
    int a,b;
    for (int i = 0; i < M; ++i) {
        cin>>a>>b; a--; b--;
        if(uf.sameroot(a,b)){
            from[a]++;
            cout<<a+1<<" "<<b+1<<endl;
        }else{
            uf.unite(a,b);
            tonari[a].push_back(b);
            tonari[b].push_back(a);
        }
    }
    queue<int> q;
    priority_queue<pair<int,int>> pq;
    q.push(0);
