			if(rem[i] % 2 == 0 && parity[i] == 0){
				for(auto to: g[i]){
					if(!visit[to])addedge(i, to);
				}
				visit[i] = true;
			}
		}
	}
	for(int i=0; i < m; i++){
		printf("%d %d\n", ans[i].first+1, ans[i].second+1);
	}
