namespace dfs2 {
  void dfs(int v, int f) {
    for(auto e: G[v]) {
      int t = e.first;
      int i = e.second;
      if(t == f) continue;
      if(!used[i]) continue;
      dfs(t, v);
    }
    if(cnt[v]) { 
      ans.emplace_back(v, f);
      cnt[v] ^= 1;
    }
    else if(f != -1) {
      ans.emplace_back(f, v);
      cnt[f] ^= 1;
    }
  }
