struct edge{
    int id, from, to;
};

int n, m;
vector< set<int> > g;
vector<edge> e;
vector<int> de;

void dfs(int v){
    if(g[v].empty()){
        return;
    }

    while(!g[v].empty()){
        if(((int)g[v].size() % 2 == 1) ^ (de[v] % 2 == 1)){
            int k = *g[v].begin();
            g[v].erase(g[v].begin());
            if(e[k].from == v){
                g[e[k].to].erase(k);
                swap(e[k].from, e[k].to);
            }else{
                g[e[k].from].erase(k);
            }
            ++de[e[k].from];
            dfs(e[k].from);
        }else{
            int k = *g[v].begin();
            g[v].erase(g[v].begin());
            if(e[k].from == v){
                g[e[k].to].erase(k);
            }else{
                g[e[k].from].erase(k);
                swap(e[k].from, e[k].to);
            }
            ++de[e[k].from];
            dfs(e[k].to);
        }
    }

    return;
}

