		ed[b].push(edge(i,b,a));
		e[i] = make_pair(a, b);
		mcount[a]++;
	}

	if (m % 2 != 0) {
		cout << -1 << endl;
		return;
	}

	for (size_t i = 0; i < m; i++)
	{
		pii v = e[i];
		if (mcount[v.first] % 2 != 0) {
			mcount[v.first]--;
			mcount[v.second]++;
			swap(e[i].first, e[i].second);
		}
	}

	for (size_t i = 0; i < m; i++)
	{
		cout << e[i].first << " " << e[i].second << endl;
	}

}

