};

ll N, M;
Vertex V[100005];
pll A[100005];
pll E[100005];
bool U[100005];

bool solve()
{
    if (M % 2 == 1)
        return false;

    ll m = 0;
    while (m < M)
    {
        REP(i, N)
        {
            if (U[i])
                continue;
            if ((V[i].n.size() - V[i].m) % 2 == 1)
                continue;
            REP(j, V[i].n.size())
            {
                ll n = V[i].n[j];
                if (U[n])
                    continue;
                A[m++] = pll(i + 1, n + 1);
                V[n].m++;
            }
            U[i] = true;
        }
    }
    return true;
}

