        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        V[a].n.push_back(b);
        V[b].n.push_back(a);
        E[i] = pll(std::min(a, b), std::max(a, b));
    }

    if (!solve())
    {
        cout << -1 << endl;
    }
    else
    {
        REP(i, M)
        {
            cout << A[i].first << " " << A[i].second << endl;
        }
    }
