int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N, M;
  cin >> N >> M;
  vector<vector<ll>> G(N);
  vector<vector<ll>> G2(N);
  queue<ll> que;
  vector<bool> used(N, false);
  vector<bool> used2(N, false);
  map<pll, int> ans;
  vl leaves;

  REP(i, M) {
    ll a, b;
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(b);
    G[b].push_back(a);
    ans[make_pair(min(a, b), max(a, b))] = 1;
  }
  if (M % 2 == 1) {
    cout << -1 << endl;
    return 0;
  }

  que.push(0);

  while (!que.empty()) {
    ll a = que.front();
    que.pop();
    used[a] = true;
    ll count = 0;
    AUTO(g, G[a]) {
      if (!used[g]) {
        que.push(g);
        count++;
        ans[make_pair(min(a, g), max(a, g))] = 1;
        G2[g].push_back(a);
        G2[a].push_back(g);
      }
    }
    if (count == 0)
      leaves.push_back(a);
  }

  AUTO(l, leaves) que.push(l);

  while (!que.empty()) {
    ll a = que.front();
    que.pop();
    used2[a] = true;
    ll count = 0;
    AUTO(g, G[a]) {
      if (a < g && ans[make_pair(a, g)] == 1)
        count++;
      else if (a > g && ans[make_pair(g, a)] == -1)
        count++;
    }
    AUTO(g, G2[a]) {
      if (!used2[g]) {
        que.push(g);
        if (count % 2 == 1) {
          if (a > g)
            ans[make_pair(g, a)] = -1;
          else
            ans[make_pair(a, g)] = 1;
        }
      }
    }
  }

  AUTO(a, ans) {
    if (a.second == 1)
      cout << a.first.first + 1 << " " << a.first.second + 1 << endl;
    else if (a.second == -1)
      cout << a.first.second + 1 << " " << a.first.first + 1 << endl;
  }
  return 0;
}

