vector<pii> ans;
int dfs(int cur,int p) {
    dfn[cur] = ++dn;

    vector<int> va;
    for(auto &it:adj[cur]) if(it!=p) {
        if(dfn[it]) {
            if(dfn[it] > dfn[cur]) va.push_back(it);
        } else {
            int v=dfs(it,cur);
            if(v) va.push_back(it);
        }
    }

    for(int i=0;i+1<(int)va.size();i+=2) {
        ans.push_back({cur,va[i]});
        ans.push_back({cur,va[i+1]});
    }
    if(p) {
        if(va.size()%2) {
            ans.push_back({cur,va.back()});
            ans.push_back({cur,p});
            return 0;
        } else return 1;
    } else {
        return va.size()%2;
    }
}

