        queue<int> explore;
        explore.push(1);
        while (!explore.empty()) {
            int now = explore.front();
            explore.pop();
            for (auto next : G[now]) {
                if (tree[next] != -1 || next == 1) continue;
                tree[next] = now;
                treeCount[now]++;
                explore.push(next);
            }
        }
    }
    vector<int> count(N + 1, 0);
    vector<pair<int, int>> ans;
    auto update = [&](int from, int to) {
        ans.emplace_back(from, to);
        count[from]++;
        G[from].erase(to);
        G[to].erase(from);
    };
    queue<int> explore;
    vector<bool> check(N + 1, true);
    for (int i = 2; i <= N; i++) if (treeCount[i] == 0) {
            explore.push(i);
            check[i] = false;
    }
    while (!explore.empty()) {
        int now = explore.front();
        explore.pop();

        if (treeCount[now] != 0) {
            explore.push(now);
            continue;
        }
        {
            int next = tree[now];
            if (next == -1) continue;
            if (count[now] % 2 == 0) update(next, now);
            else update(now, next);
            if (check[next]) explore.push(next);
            check[next] = false;
            treeCount[next]--;
        }
        auto temp = G[now];
        for (auto next : temp) update(next, now);
    }
    for (auto temp : ans) {
        cout << temp.first << " " << temp.second << endl;
    }
