void solve() {
  int n, m; cin >> n >> m;

  if (m & 1) {
    cout << -1 << endl;
    return;
  }

  Graph<int> g(n+1);
  rep(i,m) {
    int a, b; cin >> a >> b;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }

  vb seen(n+1, false);
  vb finished(n+1, false);
  vi cnt(n+1, 0);
  vector<pii> ans;

  auto dfs = [&](auto dfs, int v, int p) -> void {
    seen[v] = true;
    for (auto &nv : g[v]) {
      if (nv != p && !finished[nv]) {
        if (seen[nv]) {
          ans.emplace_back(v, nv);
          ++cnt[v];
        } else {
          dfs(dfs, nv, v);
        }
      }
    }
    if (cnt[v] & 1) {
      ans.emplace_back(v, p);
    } else {
      ans.emplace_back(p, v);
      ++cnt[p];
    }
    finished[v] = true;
  };

  dfs(dfs, 1, 0);

  ans.pop_back();
  cout << ans << endl;
}


