int solve() {
	int n, m; cin >> n >> m;
	vvi g(n);
	vpii e(m); cin >> e;
	for (auto &[x, y] : e) x--, y--;
	vi token(n);
	for (int i=0;i<m;i++) {
		int u, v; tie(u, v) = e[i];
		g[u].push_back(i), g[v].push_back(i);
		token[u] ^= 1;
	}
	vi vis(n);
	function<void(int)> dfs = [&] (int u) {
		// cerr << "dfs " << u << ": " << token;
		for (auto edg : g[u]) {
			int eu, ev; tie(eu, ev) = e[edg];
			if (ev == u) swap(eu, ev);
			if (vis[ev]) continue;
			// cerr << "dfsedge " << u << ' ' << eu << ' ' << ev << endl;
			vis[ev] = 1;
			dfs(ev);
			if (token[ev]) {
				swap(e[edg].first, e[edg].second);
				token[u] ^= 1; token[ev] ^= 1;
			}
		}
		// cerr << "dfsend " << u << ": " << token;
	};
	for (int i=0;i<n;i++) if (!vis[i]) {
		vis[i] = 1;
		dfs(i);
		if (token[i]) return cout << -1 << endl, 0;
	}
	for (auto ed : e) cout << ed.first + 1 << ' ' << ed.second + 1 << endl;
	cerr << token;
	return 0;
}

