void swap_edge(vector<P> buf){
    for(int i=0;i<buf.size();i++){
        ll from = buf[i].first;
        ll to = buf[i].second;
       // pe(from);pe("->");pe(to);
        ll idx = search_int(from,to);
        swap_count[idx] ++;
    }
   // el;
