}
void dfs(bool odd,ll from,ll v){
    if(odd){
        if(from != -1)buf[buf_idx].pb(P(from,v));
    }
    if(even[v] % 2 == 1 && odd){
        // evenに戻った
        odd = false;
        swap_edge(buf[buf_idx]);
        buf_idx++;
    } else if(even[v] % 2 == 1){
        odd = true;
    }

    check[v] = true;
   // p(v);
    for(ll i=0;i<G[v].size();i++){
        ll nv = G[v][i];
        if(check[nv])continue;
        dfs(odd,v,nv);
    }
    if(even[v] % 2 == 1 && !odd){
        buf_idx--;
    } 
    if(odd){
        if(from != -1)buf[buf_idx].pop_back();
    }
    return;
}



