                if (iter0 == g.send[i].end() && iter1 == g.receive[i].end()) {
                    g.receive[i].push_back(g.v[i][j]);
                    g.send[g.v[i][j]].push_back(i);
                }
            }
        } else {

            rep(j, g.v[j].size()) {
                auto iter0 =
                    find(g.send[i].begin(), g.send[i].end(), g.v[i][j]);
                auto iter1 =
                    find(g.receive[i].begin(), g.receive[i].end(), g.v[i][j]);

                if (iter0 == g.send[i].end() && iter1 == g.receive[i].end()) {
                    g.send[i].push_back(g.v[i][j]);
                    g.receive[g.v[i][j]].push_back(i);
                }
            }
        }
    }

