    // rep(i, 0, N) cerr << dp[i] << endl;
    // セグ木で辺の数が少ない頂点を管理して辺の向きを決めていけば良さそう    
    SegmentTree seg(dp);
    rep(i, 0, M){
      auto tmp = seg.getmin(0, N);
      int cnt = tmp.first, v = tmp.second;
      // cerr << tmp << endl;
      // cerr << cnt << " " <<v << endl;
      if(cnt == 1){
        int nv = 0;
        // cerr << v << endl;
        for(auto e : g[v]){
          nv = e;
          if(ans[v].size()%2 == 1) ans[v].insert(e);
          else ans[e].insert(v);
        }
        // cerr << v << " " << nv << endl;
        g[v].erase(nv);
        g[nv].erase(v);
        seg.update(v, INF);
        seg.update(nv, g[nv].size());
      }else{
        int nv = *g[v].begin();
        // cerr << v << " " << nv << endl;
        ans[v].insert(nv);
        g[v].erase(nv);
        g[nv].erase(v);
        seg.update(v, g[v].size());
        seg.update(nv, g[nv].size());
      }
    }
    // cerr << endl;
    rep(i, 0, N) if(ans[i].size() % 2 == 1) Exit(-1); 
    rep(i, 0, N){
      for(auto nv: ans[i]){
        cout << i + 1 << " " << nv + 1 << endl;
      }
    }

    return 0;
}

