struct SegmentTree{
    vector<pll> tree;
    int n;
    int n_ex;

    SegmentTree(const vll& vec){
        n = vec.size();
        int a = 1;
        while(a < n){
            a *= 2;
        }
        n_ex = a;
        // set tree
        // parent: floor((n-1)/2)
        // child: 2n+1, 2n+2
        // leaf: n+i-1
        rep(i, 2*n_ex-1) tree.emplace_back(INF, 0);
        rep(i, n){
            update(i, vec[i]);
        }
    }

    // corresponds to vec[i] = x;
    void update(int i, ll x){
        i += n_ex - 1;
        tree[i] = make_pair(x, i-n_ex+1);
        while(i > 0){
            i = (i - 1) / 2;
            if(tree[i*2+1].first <= tree[i*2+2].first) tree[i] = tree[i*2+1];
            else tree[i] = tree[i*2+2];
        }
    }

    // range minimum query min( [a, b) );
    pll query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return make_pair(INF, -1);
        if(a <= l && r <= b) return tree[k];
        else{
            pll vl = query(a, b, k*2+1, l, (l+r)/2);
            pll vr = query(a, b, k*2+2, (l+r)/2, r);
            if(vl.first <= vr.first){
                return vl;
            }else{
                return vr;
            }
        }
    }
    // from outside
    pll query(int a, int b){
        return query(a, b, 0, 0, n_ex);
    }
};

