{
    int N, M;
    cin >> N >> M;

    vector<set<int>> G(N);
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        G[a].insert(b);
        G[b].insert(a);
    }

    if (M % 2 != 0) {
        cout << "-1\n";
        return 0;
    }

    vector<set<int>> R(N);

    vector<tuple<int, int>> rem;
    for (int i = 0; i < N; ++i) {
        if (G[i].size() == 1) {
            int j = *G[i].begin();
            R[j].insert(i);
            rem.push_back(make_tuple(i, j));
        }
    }
    for (auto t : rem) {
        int i = get<0>(t);
        int j = get<1>(t);
        G[i].erase(j);
        G[j].erase(i);
    }
    rem.clear();

    for (int i = 0; i < N; ++i) {
        int cnt = G[i].size();
        int exist = R[i].size();

        int sz = cnt;
        if (((cnt % 2) ^ (exist % 2)) != 0) {
            --sz;
        }
        assert(sz >= 0);

        int c = 0;
        for (int j : G[i]) {
            R[i].insert(j);
            rem.push_back(make_tuple(i, j));
            ++c;
            if (c == sz)
                break;
        }

        for (auto t : rem) {
            int i = get<0>(t);
            int j = get<1>(t);
            G[i].erase(j);
            G[j].erase(i);
        }
        rem.clear();
    }

    for (int i = 0; i < N; ++i) {
        for (int j : R[i]) {
            cout << (i + 1) << ' ' << (j + 1) << '\n';
        }
    }

    return 0;
}

