using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	void Solve() {
		UL N; cin >> N;
		UL M; cin >> M;
		if (M % 2) { cout << -1 << endl; return; }
		vector<pair<UL, UL>> E(M);
		rep(i, M) { cin >> E[i].first >> E[i].second; E[i].first--; E[i].second--; }
		vector<vector<UL>> E2(N);
		rep(i, M) {
			E2[E[i].first].push_back(i);
			E2[E[i].second].push_back(i);
		}
		vector<UL> E3(N, (UL)-1); E3[0] = 0;
		stack<UL> S;
		queue<UL> Q; Q.push(0);
		while (Q.size()) {
			UL p = Q.front(); Q.pop();
			for (UL e : E2[p]) {
				UL nx = E[e].first + E[e].second - p;
				if (E3[nx] != (UL)-1) continue;
				E3[nx] = e;
				Q.push(nx);
				S.push(nx);
			}
		}
		vector<UL> Deg(N);
		rep(i, M) { Deg[E[i].first]++; }
		while (S.size()) {
			UL p = S.top(); S.pop();
			if (Deg[p] % 2 == 0) continue;
			UL e = E3[p];
			Deg[E[e].first]--;
			swap(E[e].first, E[e].second);
			Deg[E[e].first]++;
		}
		rep(i, M) {
			cout << (E[i].first + 1) << " " << (E[i].second + 1) << endl;
		}
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
