  for(int i=1;i<=n;i++){
    pque.push(P(cnt[i],i));
  }
  vector<P> ans;
  while(!pque.empty()){
    P p=pque.top();
    pque.pop();
    ll pos=p.second;
    if(used[pos]) continue;
    //cout<<"P:"<<pos<<endl;
    used[pos]=true;
    bool f=false;
    for(int i=0;i<node[pos].size();i++){
