    ll s=que.front();
    que.pop();
    if(que.empty()){
      cout<<-1<<endl;
      return 0;
    }
    ll t=que.front();
    que.pop();

    for(int i=0;i<=n;i++) used2[i]=false;
    dfs(s,t);
  }

  sort(ans.begin(),ans.end());
  vector<P> v2;
  while(!change.empty()){
    v2.push_back(change.top());
    change.pop();
  }

  for(int i=0;i<m;i++){
    int p2=lower_bound(v2.begin(),v2.end(),ans[i])-v2.begin();
    int p4=lower_bound(v2.begin(),v2.end(),P(ans[i].second,ans[i].first))-v2.begin();
    if(v2[p2]==ans[i]||v2[p4]==ans[i]){
      cout<<ans[i].second<<" "<<ans[i].first<<endl;
    }
    else cout<<ans[i].first<<" "<<ans[i].second<<endl;
  }
}

