		ans[now].push_back(to);
		g[now].erase(g[now].begin()+0);
		rep(i, g[to].size()) {
			if(g[to][i]==now) g[to].erase(g[to].begin()+i);
		}

		to = g[now][0];
		ans[now].push_back(to);
		g[now].erase(g[now].begin()+0);
		rep(i, g[to].size()) {
			if(g[to][i]==now) g[to].erase(g[to].begin()+i);
		}
	}
	seen[now] = true;
	rep(i, graph[now].size()) {
		int nv = graph[now][i];
		if(seen[nv]) continue;
		dfs(graph, g, ans, nv, seen);
	}

	return;
}

