struct LinearSystemIncidence {
    struct Edge {
        int to,id;
        Edge() {}
        Edge(int to, int id) : to(to), id(id) {} 
    };
    int N,M;
    vector<vector<Edge>> G;
    vector<int> x,seen;

    LinearSystemIncidence() {}
    LinearSystemIncidence(int N) : N(N), M(0), G(N), seen(N) {}

    void add_edge(int u, int v, int id) {
        ++M;
        G[u].emplace_back(v,id);
        G[v].emplace_back(u,id);
        x.emplace_back(0);
    }

    int dfs(int v,const vector<int> &c) {
        seen[v] = true;
        int ret = c[v];
        for (const Edge &e : G[v]) {
            if (seen[e.to]) continue;
            int tmp = dfs(e.to,c);
            x[e.id] ^= tmp;
            ret ^= tmp;
        }
        return ret;
    }

    vector<int> solve(const vector<int> &c) {
        fill(x.begin(),x.end(),0);
        fill(seen.begin(),seen.end(),0);
        for (int v = 0; v < N; ++v) {
            if (seen[v]) continue;
            if (dfs(v,c)) return vector<int> {};
        }
        return move(x);
    }
};

