void removeEdge(int eind, bool changeDir) {
    if (changeDir) {
        swap(a[eind], b[eind]);
    }
    val[a[eind]] ^= 1;
    --deg[a[eind]];
    --deg[b[eind]];
    used[eind] = true;
    if (deg[a[eind]] == 1) {
        q.push(a[eind]);
    }
    if (deg[b[eind]] == 1) {
        q.push(b[eind]);
    }
}

int main() {
//    freopen("input.txt", "r", stdin);
    scanf("%d%d", &n, &m);
    forn(i, m) {
        scanf("%d%d", a + i, b + i), --a[i], --b[i];
        g[a[i]].pb(i);
        g[b[i]].pb(i);
        used[i] = false;
        ++deg[a[i]];
        ++deg[b[i]];
    }
    if (m % 2 == 1) {
        puts("-1");
        return 0;
    }
    forn(i, n) if (deg[i] == 1) {
        q.push(i);
    }
    int ind = 0;
    forn(_, m) {
        while (!q.empty() && deg[q.front()] != 1) {
            q.pop();
        }
        if (q.empty()) {
            while (used[ind]) {
                ++ind;
            }
            removeEdge(ind, false);
            continue;
        }
        int v = q.front();
        q.pop();
        int toRemove = -1;
        for (int eind : g[v]) {
            if (!used[eind]) {
