int main() {
	llong N, M;
	vector<vector<lpair> > edges;
	vector<llong> nokori;

	cin >> N >> M;
	edges.resize(N+1);
	nokori.resize(N+1);
	for (int i = 0; i < M; ++i) {
		llong to, from;
		cin >> to >> from;
		edges[to].push_back(lpair(from, i));
		edges[from].push_back(lpair(to, i));
		nokori[to]++;
		nokori[from]++;
	}

	vector<llong> cnt(N+1, 0), usedV(N+1, 0), usedE(M, 0);
	vector<lpair> ans;
	queue<llong> q;
	q.push(1);
	while (q.size()) {
		llong now = q.front();
		q.pop();
		if (usedV[now]) continue;
		usedV[now]++;

		vector<lpair> need;
		for (auto edge : edges[now]) {
			if (usedE[edge.second]) continue;
			if (nokori[edge.first] == 1 && cnt[edge.first] % 2 == 0)
				need.push_back(edge);
		}

		llong can = nokori[now] - need.size();
		if (cnt[now] % 2 == 0) {
			can -= can % 2 == 1;
		} else {
			can -= can %2 == 0;
		}


		for (auto edge : need) {
			usedE[edge.second]++;
			ans.push_back(lpair(now, edge.first));
			cnt[now]++;
			can--;
			nokori[now]--;
			nokori[edge.first]--;
		}
		for (auto edge : edges[now]) {
			if (usedE[edge.second]) continue;
			usedE[edge.second]++;

			if (can > 0) {
				ans.push_back(lpair(now, edge.first));
				cnt[now]++;
				can--;
				nokori[now]--;
				nokori[edge.first]--;
			} else {
				ans.push_back(lpair(edge.first, now));
				cnt[edge.first]++;
				nokori[now]--;
				nokori[edge.first]--;
			}

			q.push(edge.first);
		}
	}

	bool check = true;
	for (auto c : cnt)
		if (c % 2 == 1)
			check = false;

	if (ans.size() != M || check == false) {
		cout << -1 << endl;
	} else {
		for (auto edge : ans)
			cout << edge.first << " " << edge.second << endl;
	}

	return 0;
}

