#include <bits/stdc++.h>
using namespace std;

vector<int> edges_tree[100000], edges_ans[100000];

struct UnionFind {
    vector<int> par;
    vector<int> sz;

    UnionFind(int n=0){
        if(n>0) initialize(n);
    }

    void initialize(int n){
        par.resize(n);
        sz.resize(n);
        for(int i=0; i<n; i++){
            par[i] = i;
            sz[i] = 1;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(sz[x] > sz[y]) swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int x){
        return sz[find(x)];
    }
};

void dfs(int i, int p){
    for(int j : edges_tree[i]) if(j != p){
        dfs(j, i);
        if(edges_ans[j].size() % 2){
            edges_ans[j].push_back(i);
        }else{
            edges_ans[i].push_back(j);
        }
    }
}

int main(){
    int N, M;
    cin >> N >> M;

    UnionFind uf(N);

    for(int i=0; i<M; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        if(uf.same(a, b)){
            edges_ans[a].push_back(b);
        }else{
            uf.unite(a, b);
            edges_tree[a].push_back(b);
            edges_tree[b].push_back(a);
        }
    }

    if(M%2){
        cout << -1 << endl;
        return 0;
    }

    dfs(0, -1);

    for(int i=0; i<N; i++) for(int j : edges_ans[i]) cout << i+1 << " " << j+1 << endl;
    return 0;
}

