#define rep(i, N) for (int i = 0; i < (int)N; i++)

int main () {
  int N, M;
  cin >> N >> M;
  vector<vector<int>> G(N);

  rep(i,M) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  if(M % 2) {
    cout << -1 << endl;
    return 0;
  }

  vector<int> o(N, 0), used(N, 0), p(N, 0), qUsed(N, 0);
  stack<int> s;
  queue<int> q;
  s.push(0);

  while(!s.empty()) {
    int u = s.top(); s.pop();
    used[u] = 1;
    int n = 0;
    for(int v : G[u]) {
      if(used[v]) continue;
      s.push(v);
      p[v] = u;
      used[v] = 1;
      n++;
    }
    if(n == 0) {
      q.push(u);
      qUsed[u] = 1;
    }
  }

  rep(u,N) {
    for(int v: G[u]) {
      if(u < v && p[v] != u && p[u] != v) {
        printf("%d %d\n", u+1, v+1);
        o[u]++;
      }
    }
  }

  while(!q.empty()) {
    int u = q.front(); q.pop();
    if(o[u] % 2) {
      printf("%d %d\n", u+1, p[u]+1);
      o[u]++;
    } else {
      printf("%d %d\n", p[u]+1, u+1);
      o[p[u]]++;
    }
    if(p[u] != 0 && !qUsed[p[u]]) {
      q.push(p[u]);
      qUsed[p[u]] = 1;
    }
  }

  return 0;
}

