#define M 100005
using namespace std;
int n,m,cnt[M];
map<int,bool> in[M];
int main()
{
    while (~scanf("%d %d", &n, &m)) {
        MSET(cnt, 0);
        REP(i,0,n) in[i].clear();
        REP(i,1,m) {
            int x,y;
            scanf("%d %d",&x,&y);
            in[x][y] = true;
            in[y][x] = true;
            cnt[x]++;
            cnt[y]++;
        }

        if (m%2 == 1) {
            puts("-1");
            continue;
        }

        vector<pair<int,int>> ans;
        set<int> s, noko;
        REP(i,1,n) if(cnt[i]%2==0) s.insert(i);
        REP(i,1,n) if(cnt[i]) noko.insert(i);

        while ((int)ans.size() != m) {

            // even
            while (s.size()) {
                int cur = *s.begin();
                s.erase(s.begin());

                cnt[cur] = 0;
                noko.erase(cur);

                for (auto i: in[cur]) if (i.second) {
                    cnt[i.first]--;
                    in[i.first][cur] = false;
                    in[cur][i.first] = false;
                    ans.push_back( make_pair(cur, i.first) );

                    if (cnt[i.first] %2 == 0) {
                        if (cnt[i.first] == 0)
                            noko.erase(i.first);
                        else
                            s.insert(i.first);
                    } else {
                        s.erase(i.first);
                    }
                }
            }

            if ((int)ans.size() == m) break;

            bool suc = false;
            for (int cur: noko) if(cnt[cur]>=3) {
                bool first = true;
                for (auto i: in[cur]) if (i.second) {
                    if (first) { first=false; continue; }

                    cnt[i.first]--;
                    cnt[cur]--;
                    in[i.first][cur] = false;
                    in[cur][i.first] = false;
                    ans.push_back( make_pair(cur, i.first) );

                    if (cnt[i.first] %2 == 0) {
                        if (cnt[i.first] == 0)
                            noko.erase(i.first);
                        else
                            s.insert(i.first);
                    } else {
                        s.erase(i.first);
                    }
                }

                suc = true;
                break;
            }
            if (!suc) break;
        }

        if ((int)ans.size() == m) {
            for (auto i:ans) printf("%d %d\n",i.first,i.second);
        } else {
            puts("-1");
        }


    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
int edge_num=-1;
struct edge
{
	int to,p,nxt;
}e[1000001];
int head[1000001];
void add_edge(int u,int v)
{
	e[++edge_num].to=v;
	e[edge_num].nxt=head[u];
	head[u]=edge_num;
}
int cnt;
int dfn[1000001];
int out[1000001];
void dfs(int u,int fa)
{
	dfn[u]=++cnt;
	for(int i=head[u];i!=-1;i=e[i].nxt)
	{
		int to=e[i].to;
		if(dfn[to]==0)
		{
			dfs(to,u);
			if(out[to]%2==0)
				e[i].p=1,e[i^1].p=-1,out[u]++;
			else
				e[i^1].p=1,e[i].p=-1,out[to]++;
		}
		else if(dfn[to]>dfn[u])
		{
			e[i].p=1;
			e[i^1].p=-1;
			out[u]++;
		}
	}
}
int main()
{
	memset(head,-1,sizeof(head));
	int n,m;
	scanf("%d%d",&n,&m);
	if(n%2==1)
	{
		printf("-1");
		return 0;
	}
	for(int i=1;i<=m;i++)
	{
		int u,v;
		scanf("%d%d",&u,&v);
		add_edge(u,v);
		add_edge(v,u);
	}
	dfs(1,0);
	for(int i=1;i<=n;i++)
		for(int j=head[i];j!=-1;j=e[j].nxt)
			if(e[j].p==1)
				printf("%d %d\n",i,e[j].to);
    return 0;
}

