namespace Cesare {

	ll n, m, cc = 0, Deg[N], W[N], V[N];

	vector <ll> Ve[N], E[N];

	int main() {
		n = read(), m = read();
		for (R int i = 1, u, v; i <= m; ++i) 
			++Deg[u = read()], Ve[u].push_back(v = read());
		For ( i, 1, n ) if (Deg[i] & 1) ++cc;
		if (cc & 1) return puts ("-1"), 0;
		For ( u, 1, n ) {
			if (Deg[u] & 1) {
				ll Z = 0, v;
				For ( i, 1, Ve[u].size() ) 
					v = Ve[u][i - 1], Z += (Deg[v] & 1);
				if (Z & 1) {
					For ( i, 1, Ve[u].size() ) {
						v = Ve[u][i - 1];
						if (Deg[u] && (Deg[v] & 1)) {
							E[v].push_back(u);
							--Deg[u], ++Deg[v];
						} else E[u].push_back(v);
					}
				} else {
					For ( i, 1, Ve[u].size() ) {
						v = Ve[u][i - 1];
						if (Deg[u] && (Deg[v] & 1) && Z > 1) {
							--Z;
							E[v].push_back(u);
							--Deg[u], ++Deg[v]; 
						} else E[u].push_back(v);
					}
				}
			} else {
				For ( i, 1, Ve[u].size() ) {
					ll v = Ve[u][i - 1];
					E[u].push_back(v);
				}
			}
		}
		For ( u, 1, n ) For ( i, 1, E[u].size() ) 
			wlnn (u, E[u][i - 1]);
		return 0;
	} 
