using pii = pair< int, int >;
set< pii > used;

bool isUsed(int c, int d) {
	return used.count(pii(c,d)) || used.count(pii(d,c));
}

void useEdge(int c, int d) {
	cout << c+1 << " " << d+1 << endl;
	used.insert(pii(c,d));
	used.insert(pii(d,c));
}

int main() {
	cin >> N >> M;

	if (M & 1) {
		puts("-1");
		return 0;
	}

	edge.assign(N, Vec< int >());
	for_(i,0,M) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		edge[a].push_back(b);
		edge[b].push_back(a);
	}

	// construction
	Vec< int > outdeg(N, 0);

	// deg 1
	for_(v,0,N) {
		if (edge[v].size() == 1) {
			useEdge(edge[v][0], v);
			++outdeg[edge[v][0]];
		}
	}

	// others
	for_(v,0,N) {
		int T = (outdeg[v] & 1 ? 1 : 0);
		for (int u : edge[v]) {
			if (isUsed(u, v)) continue;
			if (T) {
				useEdge(v, u);
				++outdeg[v];
				--T;
			}
			else {
				useEdge(u, v);
				++outdeg[u];
			}
		}
	}
}
