	if (M % 2 == 1) { cout << -1 << endl; return 0; }

	map<edgeClass, int> mp;

	graphClass G; G.activate(N);

	bool* flags = new bool[M];
	for (int i = 0; i < M; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		G.addEdge(a, b);

		edgeClass e; e.x = a; e.y = b;
		mp.insert(make_pair(e, i));
		e.swap();
		mp.insert(make_pair(e, i));

		flags[i] = false;
	}

	graphClass* T = G.kruskal();
	for (auto itr = T->edge.begin(); itr != T->edge.end(); itr++) {
		flags[mp[*itr]] = true;
	}

	for (int i = 0; i < M; i++) {
		if (flags[i] == false) {
			deg[G.edge[i].x]++;
			cout << G.edge[i].x << " " << G.edge[i].y << endl;
		}
	}

	dfs(T, 0);

	return 0;
}

