int Solve(int v, int p = 0)
{
    tk[v] = ++cur;
    int my = 0;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        if (!tk[u])
            if (Solve(u, v)) { my++; res.push_back(ii(v, u)); }
            else res.push_back(ii(u, v));
        else if (tk[u] < tk[v]) { my++; res.push_back(ii(v, u)); }
    }
    if (my % 2) return 0;
    return 1;
}

