vector<int> v;
vector<vector<int>> G;
vector<int> odd;
int dfs(int crt, int pre) {
    v[crt] = 1;
    for (int &nextV : G[crt]) {
        if (nextV == pre) continue;
        if (v[nextV]) {
            if (crt < nextV) {
                cout << crt << " " << nextV << endl;
                odd[crt] ^= 1;
            }
        } else {
            if (dfs(nextV, crt)) {
                cout << nextV << " " << crt << endl;
            } else {
                cout << crt << " " << nextV << endl;
                odd[crt] ^= 1; 
            }
        }
    }
    return odd[crt];
}

int main(void) {
    int N, M; cin >> N >> M;
    G.resize(N+1);
    v.resize(N+1);
    odd.resize(N+1);
    for (int i = 0; i < M; i++) {
        int a, b; cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    if (N % 2) cout << -1 << endl;
    else dfs(1, 0);
}

