int main() {
	cin >> n >> m;
	for (int i = 1; i <= m; i++) {
		cin >> x >> y;
		gr[x].push_back(y);
		gr[y].push_back(x);
	}
	if (m % 2 == 1) {
		cout << -1;
		return 0;
	}
	dfs(1);
	while (ans.size() > 0) {
		cout << ans.front().first << " " << ans.front().second;
		cout << (ans.size() > 1? "\n": "");
		ans.pop();
	}
}

void dfs(int a) {
	mark[a] = true;
	for (int u = 0; u < gr[a].size(); u++) {
		if (gr[a][u] == arr_p[a])
			continue;
		if (mark[gr[a][u]] == 1) {
			outDegree[a] = (outDegree[a] + 1) % 2;
			ans.push({a, gr[a][u]});
		}
		else {
			arr_p[gr[a][u]] = a;
			dfs(gr[a][u]);
		}
	}
	if (outDegree[a] == 0 && a != 1) {
		outDegree[arr_p[a]] = (outDegree[arr_p[a]] + 1) % 2;
		ans.push({arr_p[a], a});
	}
	if (outDegree[a] == 1 && a != 1)
		ans.push({a, arr_p[a]});
}

