struct monostate {} ms;
struct uf_monostate {
    uf_monostate(__attribute__((unused)) int id) {}
    void merge(__attribute__((unused)) uf_monostate& o,
            __attribute__((unused)) const monostate& e) {}
};

template<typename T = uf_monostate, typename E = monostate>
struct union_find {
    struct node {
        int par, rnk, size; T state;
        node(int id = 0) : par(id), rnk(0), size(1), state(id) {}
        void merge(node& o, E& e) {
            if (rnk == o.rnk) rnk++;
            if (size < o.size) swap(state, o.state);
            size += o.size;
            state.merge(o.state, e);
        }
    };

    vector<node> uf;
    union_find(int N = 0) : uf(N) {
        for (int i = 0; i < N; i++)
            uf[i] = node(i);
    }

    int rep(int i) {
        if (i != uf[i].par)
            uf[i].par = rep(uf[i].par);
        return uf[i].par;
    }

    bool unio(int a, int b, E& e = ms) {
        a = rep(a), b = rep(b);
        if (a == b) return false;
        if (uf[a].rnk < uf[b].rnk) swap(a, b);
        uf[b].par = a;
        uf[a].merge(uf[b], e);
        return true;
    }

    T& state(int i) { return uf[rep(i)].state; }
};

void go(vi& out, vpii& ans, vvi& adj, int loc, int par) {
    trav (nbr, adj[loc]) if (nbr != par) {
        go(out, ans, adj, nbr, loc);
    }

    if (out[loc]&1) {
        assert(loc != par);
        ans.eb(loc, par);
        out[loc]++;
    } else if (loc != par) {
        ans.eb(par, loc);
        out[par]++;
    }
}

int main() {
    setIO();

    int N, M; re(N, M);
    if (M&1) { ps(-1); return 0; }

    vpii ans;

    vi out(N);
    union_find<> uf(N);
    vvi adj(N); F0R (e, M) {
        int a, b; re(a, b); --a, --b;
        if (uf.unio(a, b)) {
            adj[a].pb(b);
            adj[b].pb(a);
        } else {
            ans.eb(a, b);
            out[a]++;
        }
    }

    go(out, ans, adj, 0, 0);

    trav (e, ans) {
        ps(e.f + 1, e.s + 1);
    }

    return 0;
}

