int dfs(int v,int p)
{
    int last=0;
    for(auto to:G[v])
    {
        if(to==p) continue;
        int ret=dfs(to,v);
        if(ret==0)
        {
            if(last==0) last=to;
            else
            {
                ans.push_back((node){last,v,to});
                last=0;
            }
        }
        else ans.push_back((node){ret,to,v});
    }
    return last;
}
