	vector<int> ct(n + 1, 0);		// count of outgoing edges

	vector<pair<int, int>> ans;
	for (i = 0; i < m; i++) {
		if ((parent[edge[i].first] != edge[i].second) && (parent[edge[i].second] != edge[i].first)) {
			ct[edge[i].first]++;
			ans.push_back(edge[i]);
		}
	}

	// sort nodes by depth
	vector<pair<int, int>> plist;
	for (i = 1; i <= n; i++) plist.push_back({ depth[i], i });
	sort(plist.rbegin(), plist.rend());

	// arrange direction of each node
	for (i = 0; i < n - 1; i++) {
		int id = plist[i].second;
		if (ct[id] % 2 == 0) {
			ans.push_back({ parent[id], id });
			ct[parent[id]]++;
		}
		else ans.push_back({ id, parent[id] });		
	}

	for (auto p : ans) cout << p.first << " " << p.second << "\n";

	return 0;
}

