    for (int v = 1; v <= n; ++v) {
        used[v] = false;
        if (d[v] == 1) {
            kek.push_back(v);
            used[v] = true;
        }
    }

    while (!kek.empty()) {
        int v = kek.back();
        kek.pop_back();
        for (int to : g[v]) {
            if (used[to])
                continue;
            if (cnt[v] == 0) {
                st.insert({to, v});
                cnt[to] ^= 1;
            } else {
                st.insert({v, to});
                cnt[v] ^= 1;
            }
            d[to]--;
            if (d[to] == 1) {
                used[to] = 1;
                kek.push_back(to);
            }
        }
    }


