    for (auto e : edges) {
        int u = e.first, v = e.second;
        if (st.count({u, v}) || st.count({v, u}))
            continue;
        if (col[u] == 1)
            swap(u, v);
        st.insert({u, v});
    }
    fori (i, n + 1) {
        cnt[i] = 0;
    }
    for (auto e : st) {
        cnt[e.first] ^= 1;
