void solve() {


        int n;
        cin >> n;
        int m;
        cin >> m;
        REP(i, 0, m) {
                int a, b;
                cin >> a >> b;
                deg[a] ^= 1;
                deg[b] ^= 1;
                g[a].push_back(b);
                g[b].push_back(a);
        }
        set<int> ev;
        REP(i, 1, n + 1) {
                if (deg[i] == 0) {
                        ev.insert(i);
                }
        }

        VPI ans;
        int cnt = 0;
        while (!ev.empty()) {
                int v = *ev.begin();
                ev.erase(ev.begin());
                deleted[v] = true;
                cnt++;
                int odd = 0;
                int even = 0;
                for (auto x:g[v]) {
                        if (!deleted[x]) {
                                if (deg[x]) odd++;
                                else even++;
                        }
                }

                for (auto x:g[v]) {
                        if (!deleted[x]) {
                                if (odd > even || outgoing[v]) {
                                        ans.push_back(MP(v, x));
                                        deg[x] ^= 1;
                                        if (deg[x]) {
                                                ev.erase(x);
                                        } else ev.insert(x);
                                } else {
                                        ans.push_back(MP(x, v));
                                        outgoing[x] = true;
                                }

                        }
                }
        }

        if (SZ(ans) != m || cnt != n) {
                cout << "-1" << endl;
        } else {
                for (auto x:ans) cout << x.first << ' ' << x.second << endl;
        }

}

