void dfs(int x,int idx){
	for(int i=0;i<adj[x].size();i++){
		if(!used[adj[x][i].first]){
			used[adj[x][i].first]=true;
			level[adj[x][i].first]=level[x]+1;
			dfs(adj[x][i].first,adj[x][i].second);
		}
		else{
			if(level[adj[x][i].first]<level[x]-1){
				if(edge_lis[adj[x][i].second].first!=x){
					swap(edge_lis[adj[x][i].second].first,edge_lis[adj[x][i].second].second);
				}
				deg[x]++;
			}
		}
	}
	//cout<<x<<" "<<deg[x]<<endl;
	if(deg[x]&1){
		if(edge_lis[idx].first!=x){
			swap(edge_lis[idx].first,edge_lis[idx].second);
		}
		deg[x]++;
	}
	else{
		if(edge_lis[idx].first==x){
			swap(edge_lis[idx].first,edge_lis[idx].second);
		}
		deg[edge_lis[idx].first]++;
	}
}
