bool visited[100000 + 5];

int dfs(int now, int start) {
  visited[now] = true;
  if (now != start && outdeg[now] % 2 == 1) {
    visited[now] = false;
    return now;
  }
  for (auto nx : g[now]) {
    if (visited[nx]) continue;
    int nx1 = dfs(nx, start);
    if (nx1 == -1) {
      continue;
    }
    if (s[now].find(nx1) != s[now].end()) {
      s[nx1].insert(now);
      s[now].erase(nx1);
      outdeg[nx1]++;
      if (now == start) outdeg[now]--;
    }
    else {
      s[now].insert(nx1);
      s[nx1].erase(now);
      outdeg[nx1]--;
      if (now == start) outdeg[now]++;
    }
    return now;
  }
  visited[now] = false;
  return -1;
}

