int prim(){
    ll res = 0;
    priority_queue< edge_for_que, vector<edge_for_que>, greater<edge_for_que> > que;
    edge_for_que p = {0,0,0};
    que.push(p);
    while(!que.empty()){
        edge_for_que p = que.top(); que.pop();
        if(used[p.to]) continue;
        used[p.to] = true;
        res+=p.cost;
        edge e = {p.to, p.cost};
        if(p.to != 0){
            mintree[p.from].push_back(e);
        }
        rep(i,G[p.to].size()){
            edge_for_que q = {G[p.to][i].cost,G[p.to][i].to,p.to};
            que.push(q);
        }
    }
    return res;
}

