int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;
    if (M & 1) {
        cout << -1 << endl;
        return 0;
    }
    vector<vector<pii>> g(N);
    REP(i, M) {
        int A, B;
        cin >> A >> B;
        --A;
        --B;
        g[A].emplace_back(B, i);
        g[B].emplace_back(A, i);
    }

    int root = 0;
    vector<bool> used_vertices(N, false);
    vector<bool> used_edges(M, false);
    used_vertices[root] = true;
    vector<int> outdegree(N, 0);

    function<void(int, int)> dfs = [&](int v, int parent) {
        for (const pii &e: g[v]) {
            int to, id;
            tie(to, id) = e;
            if (!used_vertices[to]) {
                used_vertices[to] = true;
                dfs(to, v);
            } else if (to != parent && !used_edges[id]) {
                cout << v << ' ' << to << '\n';
                ++outdegree[v];
                used_edges[id] = true;
            }
        }
        if (parent != -1) {
            if (outdegree[v] & 1) {
                cout << v << ' ' << parent << '\n';
                ++outdegree[v];
            } else {
                cout << parent << ' ' << v << '\n';
                ++outdegree[parent];
            }
        }
    };

    dfs(root, -1);

    return 0;
}

