const int N = 1e5+5;
vl g[N];
ll vis[N];
ll d[N],p[N];
ll id=0;
map<pair<ll,ll>,ll>e;

ll dfs(ll s)
{
       vis[s]=1;
       p[id]=s;
       id++;
       ll f=d[s]%2;
       for(ll d : g[s])
       {
              if(vis[d]==0)
                     f += dfs(d);
       }
       id--;
       if(id>0)  e[{min(s,p[id-1]),max(s,p[id-1])}]+=f;
       return f;
}

void solve()
{
       ll n,m; cin>>n>>m;
       ll a[m], b[m];
       rep(i,0,m) cin>>a[i]>>b[i];
       if(m&1) { cout<<-1<<endl; return; }
       rep(i,0,m)
       {
              g[a[i]].push_back(b[i]);
              g[b[i]].push_back(a[i]);
              d[a[i]]++; // outdegree -> edge from a -> b
              e[{min(a[i],b[i]), max(a[i],b[i])}]=0;
       }
       bool need=0;
       ll i=1;
       for(i=1; i<=n; i++) { if(d[i]&1) { need=1; break; } }
       if(need) dfs(i);
       rep(i,0,m)
       {
              ll mn=min(a[i],b[i]);
              ll mx=max(a[i],b[i]);
              //cout<<(e[{mn,mx}]&1)<<endl;
              if(e[{mn,mx}]&1) cout<<b[i]<<" "<<a[i]<<endl;
              else { cout<<a[i]<<" "<<b[i]<<endl;}
       }
}

