int degv[100010];
int outv[100010];
bool visitede[100010];

bool dfs(int v, bool flip = false){ // flip ? v -> to

    for (int ei : graph.vertex_to[v]) {
        if (visitede[ei]) continue;
        visitede[ei] = true;
        int to = graph.edges[ei].to(v);

        if (flip) printer << (v+1) << ' ' << (to+1) << '\n', outv[v] += 1;
        else      printer << (to+1) << ' ' << (v+1) << '\n', outv[to] += 1;
        --degv[to];

        if ((degv[to]&1) == 0)
            return 0;

        return dfs(to, !flip);
    }
    return 0;
}


int main() {

    scanner >> N >> M;
    if (M&1) bye("-1");
    graph.resize(N);

    repeat(i, M) {
        int a, b;
        scanner >> a >> b;
        --a; --b;
        graph.connect(a, b);
    }

    vector<int> odd;
    repeat(i, N) {
        if (graph.vertex_to[i].size()&1){
            odd.push_back(i);
        }
    }
    if (odd.size()&1) bye("-1");

    repeat(i, N) {
        degv[i] = graph.vertex_to[i].size();
    }

    // パスを潰してループのみにする
    for (auto o : odd) {
        if ((degv[o]&1) == 0) continue;
        --degv[o];
        dfs(o, outv[o]&1);
    }

    repeat(i, M) {
        if (visitede[i]) continue;
        int v = graph.edges[i].u;
        int u = graph.edges[i].v;
        if (outv[v]&1) // 奇数出次数を整合
            dfs(v, outv[v]&1);
        else if (outv[u]&1) // 奇数出次数を整合
            dfs(u, outv[u]&1);
    }
    repeat(i, M) {
        if (visitede[i]) continue;
        int v = graph.edges[i].u;
        dfs(v, outv[v]&1); // 偶数ループが残るはず
    }


    return 0;
}

