bool dfs( int edgeid, int curr, int& bad )
{
    bad = c[curr];
    if(vis[curr]) {
        return true;
    }
    vis[curr]=1;
    int siz=(int)g[curr].size();
    int i;
    for(i=0; i<siz; i++) {
        int next=g[curr][i].first;
        if(vis[next]) continue;

        int bad0=0;
        bool bOk = dfs(g[curr][i].second, next, bad0 );
        if(!bOk) {
            return false;
        }
        bad += bad0;
    }
    bad = bad % 2;
    if(bad) {
        if(edgeid>=0) {
            d[edgeid]=(d[edgeid]+1)%2;
        }
        else return false;
    }

    return true;
}

