struct union_find{
    VI par;

    void init(int n){
        par.resize(n);
        REP(i,n) par[i] = i;
    }

    int find(int x){
        if (par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    void merge(int x, int y){
        x = find(x);
        y = find(y);
        if (x == y) return;
        par[x] = y;
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    if (m % 2){
        cout << -1 << endl;
        return 0;
    }
    VI a(n);
    vector<set<int>> e(n);
    vector<P> ans;
    union_find uf;
    uf.init(n);
    REP(i,m){
        int u = in() - 1, v = in() - 1;
        if (uf.same(u, v)){
            a[u] ^= 1;
            ans.emplace_back(u, v);
        }else{
            uf.merge(u, v);
            e[u].insert(v);
            e[v].insert(u);
        }
    }
    queue<int> que;
    REP(i,n){
        if (e[i].size() == 1){
            que.push(i);
        }
    }
    while (!que.empty()){
        int x = que.front();
        que.pop();
        for (int y : e[x]){
            if (a[x]){
                ans.emplace_back(x, y);
                a[x] ^= 1;
            }else{
                ans.emplace_back(y, x);
                a[y] ^= 1;
            }
            e[y].erase(x);
            if (e[y].size() == 1) que.push(y);
        }
        e[x].clear();
    }

    for (P p : ans){
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }

    return 0;
}

