void solve() {
  num.assign(n, 0);
  for(int i = 0; i < n; ++i)
    if(edge[i].size() == 1) qu.push(i);
  bfs();
  for(int i = 0; i < n; ++i)
    if(edge[i].size() != 0) {
      vector<int> tmp;
      for(auto now : edge[i]) tmp.push_back(now);
      int tsize = tmp.size();
      for(int j = 0; j < tsize; ++j) {
        if(j == tsize - 1) {
          if(num[i]) {
            ans.push_back({i, tmp[j]});
            num[i] = 0;
          }
          else {
            ans.push_back({tmp[j], i});
            num[tmp[j]] = !num[tmp[j]];
          }
          edge[tmp[j]].erase(i);
          if(edge[tmp[j]].size() == 1) qu.push(tmp[j]);
        }
        else {
          ans.push_back({i, tmp[j]});
          num[i] = !num[i];
        }
      }
      bfs();
    }
}

void bfs() {
  while(!qu.empty()) {
    int now = qu.front();
    qu.pop();
    if(edge[now].size() == 0) {
      if(num[now]) {
        ans.erase(ans.begin(), ans.end());
        return;
      }
      continue;
    }
    vector<int> tmp;
    for(auto to : edge[now]) tmp.push_back(to);
    int tsize = tmp.size();
    for(int j = 0; j < tsize; ++j) {
      int to = tmp[j];
      if(num[now])
        num[now] = 0;
      else {
        ans.push_back({to, now});
        num[to] = !num[to];
      }
      edge[now].erase(to);
      edge[to].erase(now);
      if(edge[to].size() == 1) qu.push(to);
    }
  }
}

