using namespace std;

struct graph {
	struct edge {
		int a, b;
		bool isDirected = true; // 向きが決定されたか
		bool dir = true; // trueならa -> b
	};

	int n, m;
	vector<edge> e;
	vector<vector<edge*>> g;
	vector<int> cnt;

	graph(int n, int m) {
		this->n = n; this->m = m;
		g.resize(n); e.resize(m);
		cnt.resize(n, 0);
		for (int i = 0; i < m; ++i) {
			int ai, bi; scanf("%d %d", &ai, &bi);
			--ai, --bi;
			e[i].a = ai; e[i].b = bi;
			e[i].isDirected = true; e[i].dir = true;
			g[ai].push_back(&e[i]);
			g[bi].push_back(&e[i]);
		}
	}

	// 0を根とする根付き木の辺の向きを不定にする
	void dfs(int s = 0) {
		static vector<bool> visited(n, false);
		visited[s] = true;
		for (edge* ed : g[s]) {
			int nx = (*ed).a == s ? (*ed).b : (*ed).a;
			if (!visited[nx]) {
				(*ed).isDirected = false;
				dfs(nx);
			}
		}
	}

	// 各頂点について、何本辺が(今のところ)出ているか調べる
	void count() {
		for (edge ei : e) {
			if (ei.isDirected) {
				if (ei.dir) ++cnt[ei.a];
				else ++cnt[ei.b];
			}
		}
	}

	// 根付き木の辺の向きを決定していく
	void solve(int s = 0) {
		static vector<bool> visited(n, false);
		visited[s] = true;
		for (edge* ed : g[s]) {
			int nx = (*ed).a == s ? (*ed).b : (*ed).a;
			if ((!(*ed).isDirected) && (!visited[nx])) solve(nx);
		}
		for (edge* ed : g[s]) {
			if ((*ed).isDirected) continue;
			if (cnt[s] & 1) { // 自分から生やす
				if ((*ed).a != s) (*ed).dir = false;
				++cnt[s];
			}
			else { // 自分に向ける
				if ((*ed).a == s) (*ed).dir = false;
				++cnt[(*ed).b != s ? (*ed).b : (*ed).a];
			}
			(*ed).isDirected = true;
		}
	}

	// 出力する
	void show() {
		for (auto ed : e) {
			if (ed.dir)
				cout << (ed.a + 1) << " " << (ed.b + 1) << endl;
			else
				cout << (ed.b + 1) << " " << (ed.a + 1) << endl;
		}
	}
};

int main() {
	int n, m; scanf("%d %d", &n, &m);
	if (m & 1) { // mが奇数の時は不可
		cout << -1 << endl;
	}
	else { // mが偶数の時は構築可
		graph g(n, m);
		g.dfs();
		g.count();
		g.solve();
		g.show();
	}
	return 0;
}

