			g[v[i]].erase(v[i - 1]);
			g[v[i]].erase(v[i + 1]);
		}
	}

	if (ans.size() == m) {
		REP(i, m) {
			OUT(ans[i].first + 1) SP OUT(ans[i].second + 1)BR;
		}
	}
	else {
