int root(int a){
  if(comp[a]==0)return a;
  int u=root(comp[a]);
  comp[a]=u;
  return u;
}

void input(){
  int a,b;
  scanf("%d%d",&a,&b);
  int u=root(a),v=root(b);
  if(u==v){
    printf("%s%d %d%s\n",df?"[":"",a,b,df?"]":"");
    odeg[a]^=1;
    return;
  }
  list[a]=realloc(list[a],sizeof(int)*(++deg[a]));
  list[b]=realloc(list[b],sizeof(int)*(++deg[b]));
  list[a][deg[a]-1]=b;
  list[b][deg[b]-1]=a;
  int w=(height[u]<height[v])?u:v;
  comp[u+v-w]=w;
  height[w]=height[u+v-w]+1;
}


