  srand(time(0));
  resheap();
  long long i,j,n,m,k,a,b,c,h,w,r=0,l,t;
  rs g[524288];
  mkj x[524288];
  bool fl[524288]={0},vfl[524288]={0};
  long long cnt[524288]={0};
  long long bk[524288]={0};
  data pd,od;
  scanf("%lld%lld",&n,&m);
  for(i=0;i<m;i++){
    scanf("%lld%lld",&g[i].st,&g[i].fi);
    g[i].kr=i;
    g[m+i].st=g[i].fi;
    g[m+i].fi=g[i].st;
    g[m+i].kr=i;
    bk[g[i].st]++;
    bk[g[i].fi]++;
