    if(vfl[w]==1){continue;}
    vfl[w]=1;
    c=cnt[w];
    t=0;
    for(i=x[w].st;i<x[w].st+x[w].kz;i++){
      if(fl[g[i].kr]==0){
        c++;
        t=llmax(t,bk[g[i].fi]);
      }
    }
    for(i=x[w].st;i<x[w].st+x[w].kz;i++){
      if(fl[g[i].kr]==0){
        fl[g[i].kr]=1;
        if(c%2==1 && bk[g[i].fi]==t){
          c--;
          printf("%lld %lld\n",g[i].fi,g[i].st);
          cnt[g[i].fi]++;
          bk[g[i].fi]--;
          pd.node=g[i].fi;
          pd.cost=bk[g[i].fi]+grand();
          pqpush(pd);
        }
        else{
          printf("%lld %lld\n",g[i].st,g[i].fi);
          bk[g[i].fi]--;
          pd.node=g[i].fi;
          pd.cost=bk[g[i].fi]+grand();
          pqpush(pd);
        }
      }
    }
