#define N_MAX 100000
#define M_MAX 100000

int *tree[N_MAX+1];
int tree_size[N_MAX+1] = {};
int child_num[N_MAX+1] = {};

int asc(const void *a, const void *b){
  if(*(int *)a > *(int *)b){
    return 1;
  }else if(*(int *)a == *(int *)b){
    return 0;
  }else{
    return -1;
  }
}

void input_node(int a, int b){
  if(tree_size[a] == 0){
    tree[a] = (int *)malloc(sizeof(int));
    tree_size[a] = 1;
  }else if(child_num[a] == tree_size[a]){
    tree[a] = (int *)realloc(tree[a], sizeof(int)*tree_size[a]*2);
    tree_size[a] *= 2;
  }
  tree[a][child_num[a]++] = b;
}

void delete_node(int a, int b){
  int i;

  for(i = 0; i < child_num[a]; i++){
    if(tree[a][i] == b){
      tree[a][i] = tree[a][--child_num[a]];
      tree[a][child_num[a]] = 0;
      break;
    }
  }
}

int main(void){
  int i, j;

  int n, m;
  scanf("%d%d", &n, &m);

