    printf("-1\n");
    return 0;
  }

  int a, b;
  for(i = 0; i < m; i++){
    scanf("%d%d", &a, &b);
    if(a < b) input_node(a, b);
    else input_node(b, a);
  }

  int flg = 1, cnt = 1000;
  while(flg && cnt){
    cnt--;
    flg = 0;
    for(i = 1; i <= n; i++){
      qsort(tree[i], child_num[i], sizeof(int), asc);
      if(child_num[i]%2 == 1){
        flg = 1;
        for(j = 0; j < child_num[i]; j++){
          if(child_num[tree[i][j]]%2 == 1){
            input_node(tree[i][j], i);
            delete_node(i, tree[i][j]);
            break;
          }
        }
      }
    }
  }

  for(i = 1; i <= n; i++){
    for(j = 0; j < child_num[i]; j++){
      printf("%d %d\n", i, tree[i][j]);
    }
  }

  return 0;
}

