#define MAX 200000

int N, M;
int A[MAX];
int B[MAX];

int count[MAX];

int kisuCount = 0;
int kisu[MAX];

char kisuFlag[MAX];
int kRinsetuCount[MAX];
int* kRinsetu[MAX];
int* kRinsetuIdx[MAX];
int* kTryCount[MAX];

int main(void) {
	int i, j, r;
	int ok;
	if (scanf("%d%d", &N, &M) != 2) return 1;
	for (i = 0; i < M; i++) {
		if (scanf("%d%d", &A[i], &B[i]) != 2) return 1;
	}
	for (r = 0; r < 20; r++) {
		/* ランダムにひっくり返す */
		for (i = 0; i < M; i++) {
			if (randint() % 16 == 0) {
				int t = A[i];
				A[i] = B[i];
				B[i] = t;
			}
		}

		for (i = 0; i < M; i++) {
			count[A[i] - 1]++;
		}
		for (i = 0; i < N; i++) {
			if (count[i] % 2 != 0) {
				kisu[kisuCount++] = i;
			}
		}
		for (i = 0; i < kisuCount; i++) {
			kisuFlag[kisu[i]] = 1;
		}
		for (i = 0; i < M; i++) {
			if (kisuFlag[A[i]]) {
				int idx = A[i] - 1;
				int c = ++kRinsetuCount[idx];
				kRinsetu[idx] = realloc(kRinsetu[idx], sizeof(int) * c);
				if (kRinsetu[idx] == NULL) return 1;
				kRinsetu[idx][c - 1] = B[i] - 1;
				kRinsetuIdx[idx] = realloc(kRinsetuIdx[idx], sizeof(int) * c);
				if (kRinsetuIdx[idx] == NULL) return 1;
				kRinsetuIdx[idx][c - 1] = i;
			}
		}
		for (i = 0; i < N; i++) {
			kTryCount[i] = calloc(kRinsetuCount[i], sizeof(int));
			if (kTryCount[i] == NULL) return 1;
		}
		/* 貪欲 */
		for (i = 0; i < N; i++) {
			if (kisuFlag[i] && kRinsetuCount[i] > 0) {
				for (j = 0; j < kRinsetuCount[i]; j++) {
					if (kisuFlag[kRinsetu[i][j]] && kTryCount[i][j] < 2) {
						kisuFlag[i] = 0;
						kisuFlag[kRinsetu[i][j]] = 0;
						kTryCount[i][j]++;
						{
							int idx = kRinsetuIdx[i][j], t;
							t = A[idx];
							A[idx] = B[idx];
							B[idx] = t;
						}
						break;
					}
				}
				if (kisuFlag[i]) {
					/* 奇数となるペアが見つからなかった */
					int hoge = -1, fuga = -1;
					for (j = 0; j < kRinsetuCount[i]; j++) {
						if (kTryCount[i][j] < 2) {
							if (hoge < 0 && kRinsetu[i][j] > i) {
								hoge = j;
							}
							if (fuga < 0) {
								fuga = j;
							}
						}
					}
					if (hoge < 0) hoge = fuga;
					if (hoge >= 0) {
						kisuFlag[i] = 0;
						kisuFlag[kRinsetu[i][hoge]] = 1;
						kTryCount[i][hoge]++;
						{
							int idx = kRinsetuIdx[i][hoge], t;
							t = A[idx];
							A[idx] = B[idx];
							B[idx] = t;
						}
						if (kRinsetu[i][hoge] < i) i = kRinsetu[i][hoge] - 1;
					}
				}
			}
		}
		ok = 1;
		for (i = 0; i < N; i++) {
			if (kisuFlag[i]) {
				ok = 0;
				break;
			}
		}
		if (!ok) {
			for (i = 0; i < N; i++) {
				free(kRinsetu[i]);
				free(kRinsetuIdx[i]);
				free(kTryCount[i]);
				kRinsetuCount[i] = 0;
				kRinsetu[i] = NULL;
				kRinsetuIdx[i] = NULL;
				kTryCount[i] = NULL;
			}
			memset(count, 0, sizeof(count));
			memset(kisuFlag, 0, sizeof(kisuFlag));
			kisuCount = 0;
			continue;
		}
		for (i = 0; i < M; i++) {
			printf("%d %d\n", A[i], B[i]);
		}
		return 0;
	}
	puts("-1");
	return 0;
}

