  int tree_size[N_MAX] = {};
  int child_num[N_MAX] = {};

  int a, b;
  for(i = 0; i < m; i++){
    scanf("%d%d", &a, &b);
    if(a < b) input_node(a, b, tree, tree_size, child_num);
    else input_node(b, a, tree, tree_size, child_num);
  }

  for(i = 0; i < n; i++){
    qsort(tree[i], child_num[i], sizeof(int), asc);
