#include <stdio.h>
#include <stdlib.h>

typedef struct {
	int t, h;
} edge;

typedef struct List {
	struct List *next;
	edge *e;
} list;

typedef struct {
	edge *e;
	list **inc;
} graph;

void input_graph(graph *G, int n, int m)
{
	int i;
	list *data = (list*)malloc(sizeof(list) * m * 2);
	G->e = (edge*)malloc(sizeof(edge) * m);
	G->inc = (list**)malloc(sizeof(list*) * (n + 1));
	for (i = 0; i < m; i++) {
		scanf("%d %d", &(G->e[i].t), &(G->e[i].h));
		data[i*2].e = &(G->e[i]);
		data[i*2+1].e = &(G->e[i]);
		data[i*2].next = G->inc[G->e[i].t];
		data[i*2+1].next = G->inc[G->e[i].h];
		G->inc[G->e[i].t] = &(data[i*2]);
		G->inc[G->e[i].h] = &(data[i*2+1]);
	}
}

int main()
{
	int i, N, M;
	graph G;
	scanf("%d %d", &N, &M);
	if (M % 2 == 1) {
		printf("-1\n");
		fflush(stdout);
		return 0;
	}
	input_graph(&G, N, M);

	int k = 0, v, tmp, parity[100001] = {}, flag[100001] = {}, q[100001], head, tail;
	edge *prev[100001];
	list *p;
	for (i = 1; i <= N; i++) {
		for (p = G.inc[i]; p != NULL; p = p->next) if (p->e->t == i) parity[i] ^= 1;
	}
	while (1) {
		for (i = 1; i <= N; i++) if (parity[i] == 1) break;
		if (i > N) break;

		q[0] = i;
		parity[i] = 0;
		flag[i] = ++k;
		for (head = 0, tail = 1; head < tail; head++) {
			for (p = G.inc[q[head]]; p != NULL; p = p->next) {
				v = (p->e->t == q[head])? p->e->h: p->e->t;
				if (flag[v] < k) {
					flag[v] = k;
					prev[v] = p->e;
				}
				if (parity[v] == 1) {
					parity[v] = 0;
					break;
				}
			}
			if (p != NULL) break;
		}
		if (head == tail) {
			printf("-1\n");
			fflush(stdout);
			return 0;
		} else {
			for (; v != i; v = (prev[v]->t == v)? prev[v]->h: prev[v]->t) {
				tmp = prev[v]->h;
				prev[v]->h = prev[v]->t;
				prev[v]->t = tmp;
			}
		}
	}

	for (i = 0; i < M; i++) printf("%d %d\n", G.e[i].t, G.e[i].h);
	fflush(stdout);
	return 0;
}

