import java.util.ArrayList;
import java.util.List;

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[m];
    int[] to = new int[m];
    int[] w = new int[m];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
      w[i] = i;
    }
    int[][][] g = packWU(n, from, to, w);
    int[] d = new int[m];
    boolean ret = dfs(0, g, new boolean[n], d, from);

    if (!ret) {
      out.println("No");
    } else {
      out.println("Yes");
      for (int i = 0; i < m; i++) {
        if (d[i] == 1) {
          out.println((from[i] + 1) + " " + (to[i] + 1));
        } else {
          out.println((to[i] + 1) + " " + (from[i] + 1));

        }
      }
    }
  }

  private static boolean dfs(int now, int[][][] g, boolean[] ved, int[] d, int[] from) {
    ved[now] = true;

    int out = 0;
    int in = 0;
    List<Integer> list = new ArrayList<>();
    for (int[] e : g[now]) {
      int nex = e[0];

      if (ved[nex])
        continue;

      if (!dfs(nex, g, ved, d, from)) {
        return false;
      }

    }

    for (int[] e : g[now]) {
      int k = e[1];

      if (d[k] != 0) {
        if (d[k] == 1 && from[k] == now || d[k] == 2 && from[k] != now) {
          out++;
        } else {
          in++;
        }
      } else {
        list.add(k);
      }
    }

    int cnt = list.size() + out;
    boolean flg = cnt % 2 == 1;

    for (int k : list) {
      if (from[k] == now) {
        d[k] = flg ? 2 : 1;
      } else {
        d[k] = flg ? 1 : 2;
      }
      flg = false;
    }
    if (flg) {
      return false;
    }
    return true;
  }

  public static int[][][] packWU(int n, int[] from, int[] to, int[] w) {
    int[][][] g = new int[n][][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]][2];
    for (int i = 0; i < from.length; i++) {
      --p[from[i]];
      g[from[i]][p[from[i]]][0] = to[i];
      g[from[i]][p[from[i]]][1] = w[i];
      --p[to[i]];
      g[to[i]][p[to[i]]][0] = from[i];
      g[to[i]][p[to[i]]][1] = w[i];
    }
    return g;
  }



