import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        for (int i = 0; i < m; ++i) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            Set<Integer> nextA = graph.getOrDefault(a, new HashSet<>());
            nextA.add(b);
            Set<Integer> nextB = graph.getOrDefault(b, new HashSet<>());
            nextB.add(a);
            graph.put(a, nextA);
            graph.put(b, nextB);
        }
        if (m % 2 == 1) {
            System.out.println(-1);
            return;
        }
        int[] visited = new int[n + 1];
        Map<Integer, Set<Integer>> spanningTree = new HashMap<>();
        dfs(1, visited, graph, spanningTree);

        makeDirection(n, graph, spanningTree);
        graph.entrySet().forEach(
                keyValue -> {
                    for (int value : keyValue.getValue()) {
                        System.out.println(keyValue.getKey() + " " + value);
                    }
                }
        );

    }

    // find spanning tree
    public static void dfs(
            int current, int[] visited, Map<Integer, Set<Integer>> originalGraph,
            Map<Integer, Set<Integer>> spanningTree
    ) {
        Set<Integer> connecteds = originalGraph.get(current);
        connecteds.stream()
                .filter(
                        index -> visited[index] == 0
                ).forEach(
                        index -> {
                            visited[index] = 1;
                            Set<Integer> connectedInSpanningTree =
                                    spanningTree.getOrDefault(current, new HashSet<>());
                            connectedInSpanningTree.add(index);
                            spanningTree.put(current, connectedInSpanningTree);

                            Set<Integer> connectedIndexs = spanningTree.getOrDefault(index, new HashSet<>());
                            connectedIndexs.add(current);
                            spanningTree.put(
                                    index,
                                    connectedIndexs
                            );
                            dfs(index, visited, originalGraph, spanningTree);
                        }
                );
    }

    public static void makeDirection(
            int n,
            Map<Integer, Set<Integer>> graph,
            Map<Integer, Set<Integer>> tree
    ) {
        int [] outDegrees = new int[n + 1];
        graph.forEach((key, value) -> graph.get(key).removeAll(tree.get(key)));

        // randomly make directions of the edges that are not in spanning tree
        graph.forEach(
                (key, value) -> {
                    for (Integer connected : value) {
                        // keep the edge key -> connected, remove the edge connected -> key
                        graph.get(connected).remove(key);
                        outDegrees[key]++;
                    }
                }
        );

        int [] visited = new int[n + 1];
        Deque<Integer> sortedNodes = new LinkedList<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.add(1);
        visited[1] = 1;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            sortedNodes.add(current);
      //      System.out.println("sortedNodes: " + current);

            Set<Integer> sons = tree.get(current);
            for (int son : sons) {
               if (visited[son] == 0) {
                   queue.add(son);
                   visited[son] = 1;
               }
            }
        }

        while(!sortedNodes.isEmpty()) {
            int current = sortedNodes.pollLast();
         //   System.out.println("current: " + current);
            if (current == 1) {
                break;
            }
            int father = tree.get(current).iterator().next();
        //    System.out.println("father: " + father);
            if (outDegrees[current] % 2 == 0) {
                Set<Integer> fatherConnected = graph.getOrDefault(father, new HashSet<>());
                fatherConnected.add(current);
                graph.put(father, fatherConnected);
                outDegrees[father]++;
           //     System.out.println(father + "-> " + current);
            } else {
                Set<Integer> currentConnected = graph.getOrDefault(current, new HashSet<>());
                currentConnected.add(father);
                graph.put(current, currentConnected);
                outDegrees[current]++;
         //       System.out.println(current + "-> " + father);
            }
            tree.get(current).remove(father);
            tree.get(father).remove(current);
        }

    }
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, m;
  final int[][] abs;

  List<List<Integer>> graph;
  Set<String> visited;
  List<String> edgeStack;
  List<String> output;

  Solver(int n, int m, int[][] abs) {
    this.n = n;
    this.m = m;
    this.abs = abs;
  }


  private void assignDirection(String edge1, String edge2) {
    String[] split1 = edge1.split(" ");
    String[] split2 = edge2.split(" ");
    int index11 = Integer.parseInt(split1[0]);
    int index12 = Integer.parseInt(split1[1]);
    int index21 = Integer.parseInt(split2[0]);
    int index22 = Integer.parseInt(split2[1]);
    int[] indexes = new int[]{
      index11,
      index12,
      index21,
      index22,
    };
    int srcIndex = 0;
    for (int i = 0; i < 4; i++) {
      for (int j = i+1; j < 4; j++) {
        if (indexes[i] == indexes[j]) {
          srcIndex = indexes[i];
        }
      }
    }
    if (srcIndex == 0) {
      throw new RuntimeException();
    }
    for (int index : indexes) {
      if (index == srcIndex) {
        continue;
      }
      output.add(String.format("%d %d", srcIndex, index));
    }
  }

  private void mightAssignDirection() {
    if (edgeStack.size() < 4) {
      return;
    }
    String edge1 = edgeStack.get(edgeStack.size() - 1);
    String edge2 = edgeStack.get(edgeStack.size() - 2);
    String edge3 = edgeStack.get(edgeStack.size() - 3);
    String edge4 = edgeStack.get(edgeStack.size() - 4);
    if ((edge1.equals(edge2) && edge3.equals(edge4))
        || (edge1.equals(edge4) && edge2.equals(edge3))) {
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      assignDirection(edge1, edge3);
    }
  }

  private String formatNonDirectedEdge(int index1, int index2) {
    int minIndex = Math.min(index1, index2);
    int maxIndex = Math.max(index1, index2);
    return String.format("%d %d", minIndex, maxIndex);
  }

  private void edgeDfs(int index) {
    for (int next : graph.get(index)) {
      String edge = formatNonDirectedEdge(index, next);
      if (visited.contains(edge)) {
        continue;
      }
      visited.add(edge);
      edgeStack.add(edge);
//      System.err.println(edge);
      edgeDfs(next);
      edgeStack.add(edge);
//      System.err.println(edge);
      mightAssignDirection();
    }
  }

  public List<String> solve() {
    if (n % 2 == 1) {
      return Arrays.asList("-1");
    }

    graph = new ArrayList<>();
    visited = new HashSet<>();
    edgeStack = new ArrayList<>();
    output = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }
    edgeDfs(1);
    return output;
  }
}

