    public void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        if (m % 2 != 0) {
            System.out.println("-1");
            return;
        }
        g = new ArrayList[n];
        tree = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
            tree[i] = new ArrayList<>();
        }
        depth = new int[n];
        vis = new boolean[n];
        int[] a = new int[m];
        int[] b = new int[m];
        for (int i = 0; i < m; i++) {
            a[i] = in.nextInt() - 1;
            b[i] = in.nextInt() - 1;
            g[a[i]].add(b[i]);
            g[b[i]].add(a[i]);
        }
        count = new int[n];
        dfs(0, -1, 0);
        int res = dfs2(0);
        if (res % 2 != 0) {
            throw new RuntimeException();
        }

        for (int i = 0; i < m; i++) {
            long x = map.get(toKey(a[i], b[i]));
            int u = (int)(x / 101000);
            int v = (int)(x % 101000);
            System.out.println((u + 1) + " " + (v + 1));
        }
    }

    private int dfs2(int u) {
        int res = count[u];
        for (int v : tree[u]) {
            int next = dfs2(v);
            if (next % 2 == 0) {
                res++;
                map.put(toKey(u, v), toValue(v, u));
            } else {
                map.put(toKey(u, v), toValue(u, v));
            }
        }
        return res;
    }

    void dfs(int u, int prev, int dep) {
        vis[u] = true;
        depth[u] = dep;
        for (int v : g[u]) {
            if (vis[v]) {
                if (v != prev && depth[u] < depth[v]) {
                    map.put(toKey(u, v), toValue(u, v));
                    count[v]++;
                }
                continue;
            }
            tree[u].add(v);
            dfs(v, u, dep + 1);
        }
    }

    private Long toKey(int u, int v) {
        return Math.min(u, v) * 101000L + Math.max(u, v);
    }

    private Long toValue(int u, int v) {
        return u * 101000L + v;
    }

    /* MOD_CALCULATION */
    static int MOD = 1_000_000_007;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
