			ArrayDeque<Integer> q = new ArrayDeque<>();
			q.add(1);
			int number = 1;
			boolean[] used = new boolean[n+1];
			used[1]=true;
			while(!q.isEmpty()) {
				Integer intg = q.poll();
				nodeNum[intg]=number;
				nodeRevNum[number]=intg;
				number++;
				for (Edge e : graph.get(intg)) {
					int tmp = e.from+e.to-intg;
					if (!used[tmp]) {
						q.offer(tmp);
						used[tmp]=true;
					}
				}
			}

