						if (min==null) {
							min=e;
						} else if (nodeNum[e.from+e.to-i] < nodeNum[min.from+min.to-i]) {
							min=e;
						}
					}
					min.direction=1-min.direction;
				}
			}

			for (Edge e : edgeList) {
