public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int m = In.ni();
        Tree t = new Tree(n);
        ArrayList<int[]> r = new ArrayList<>();
        UnionFindTree uf = new UnionFindTree(n);
        for (int i = 0; i < m; i++) {
            int a = In.ni() - 1;
            int b = In.ni() - 1;
            if (uf.unite(a, b)) {
                t.addEdge(a, b);
            } else {
                r.add(new int[]{a, b});
            }
        }
        t.build();
        if ((m & 1) == 1) {
            out.append(-1);
            return;
        }
        boolean[] in = new boolean[n];
        for (int i = 0; i < n; i++) in[i] = true;
        dfs(t, -1, 0, in);
        boolean[] rv = new boolean[n];
        for (int[] e : r) {
            int a = e[0];
            int b = e[1];
            out.append(a + 1).append(' ').append(b + 1).append('\n');
            rv[a] = !rv[a];
        }
        dfs(t, -1, 0, rv);
        for (int i = 1; i < n; i++) {
            if (in[i] ^= rv[i]) {
                out.append(t.parent(i) + 1).append(' ').append(i + 1).append('\n');
            } else {
                out.append(i + 1).append(' ').append(t.parent(i) + 1).append('\n');
            }
        }
    }

    public static boolean dfs(Tree t, int p, int u, boolean[] in) {
        PrimitiveIterator.OfInt iter = t.getEdges(u).iterator();
        while (iter.hasNext()) {
            int v = iter.nextInt();
            if (v != p) in[u] ^= dfs(t, u, v, in);
        }
        return in[u];
    }
}


