		from[line.a-1]=from[line.a-1]-1;
		line.setDir(false);
		from[line.b-1]=from[line.b-1]+1;
		if( dfs(list, index+1)){
			return true;
		}
		from[line.b-1]=from[line.b-1]-1;
		return false;
	}

	private static class Line{ // true >       false <
		private int a = 0;
		private int b = 0;
		private boolean dir = false;
		Line(int a, int b){
			this.a = a;
			this.b = b;
		}

		void setDir(boolean dir){
			this.dir = dir;
		}

		@Override
		public String toString(){
			if(dir){
				return a + " " + b;
			}
			return b + " " + a;
		}
	}



