  private static void dfs(int cur, int pre, int[][][] g, boolean[] ved) {
    ved[cur] = true;
    int n = g[cur].length;
    int cnt = 0;

    int r = -1;
    for (int i = 0; i < n; i++) {
      int nex = g[cur][i][0];
      int ie = g[cur][i][1];

      if (nex == pre) {
        r = i;
      }
      if (ved[nex]) {
        if (nex != pre) {
          if (g[cur][i][2] == 0) {
            g[nex][ie][2] = -1;
            g[cur][i][2] = 1;
          }
        }
      } else {
        dfs(nex, cur, g, ved);
      }
    }

    for (int[] v : g[cur]) {
      if (v[2] == 1) {
        cnt++;
      }
    }

    if (r >= 0) {
      int ri = g[cur][r][1];
      g[cur][r][2] = cnt % 2 == 0 ? -1 : 1;
      g[pre][ri][2] = cnt % 2 == 0 ? 1 : -1;
    }
  }

  public static int[][][] packWU(int n, int[] from, int[] to) {
    int[][][] g = new int[n][][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]][3];
    for (int i = 0; i < from.length; i++) {
      --p[from[i]];
      --p[to[i]];
      g[from[i]][p[from[i]]][0] = to[i];
      g[from[i]][p[from[i]]][1] = p[to[i]];
      g[to[i]][p[to[i]]][0] = from[i];
      g[to[i]][p[to[i]]][1] = p[from[i]];
    }
    return g;
  }

