import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

public class Main {
	static List<List<Hen>> list;
	static boolean[] visit;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		int m = Integer.parseInt(sa[1]);
		list = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			list.add(new ArrayList<>());
		}
		Hen[] arr = new Hen[m];
		for (int i = 0; i < m; i++) {
			sa = br.readLine().split(" ");
			Hen h = new Hen();
			h.a = Integer.parseInt(sa[0]) - 1;
			h.b = Integer.parseInt(sa[1]) - 1;
			list.get(h.a).add(h);
			list.get(h.b).add(h);
			arr[i] = h;
		}
		br.close();

		if (m % 2 == 1) {
			System.out.println(-1);
			return;
		}

		visit = new boolean[n];
		dfs(0, -1);

		PrintWriter pw = new PrintWriter(System.out);
		for (int i = 0; i < m; i++) {
			pw.println(++arr[i].c + " " + ++arr[i].d);
		}
		pw.flush();
	}

	static void dfs(int x, int p) {
		visit[x] = true;
		for (Hen h : list.get(x)) {
			int ch = h.a;
			if (ch == x) {
				ch = h.b;
			}
			if (!visit[ch] && ch != p) {
				dfs(ch, x);
			}
		}

		int cnt = 0;
		List<Hen> work = new ArrayList<>();
		for (Hen h : list.get(x)) {
			if (h.d == -1) {
				work.add(h);
			} else {
				if (h.c == x) {
					cnt++;
				}
			}
		}

		for (Hen h : work) {
			int ch = h.a;
			if (ch == x) {
				ch = h.b;
			}
			h.c = x;
			h.d = ch;
		}
		if (cnt % 2 != work.size() % 2) {
			Hen h = work.get(0);
			int tmp = h.c;
			h.c = h.d;
			h.d = tmp;
		}
	}

	static class Hen {
		int a, b, c, d = -1;
	}
}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N, M;
    static List<Edge> E;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        E = new ArrayList<>(M);
        for (int i = 0; i < M; i++) {
            E.add(new Edge(sc.nextInt()-1, sc.nextInt()-1));
        }

        PrintWriter pw = new PrintWriter(System.out);
        solve(pw);
        pw.flush();
    }

    static void solve(PrintWriter pw) {
        if( M % 2 == 1 ) {
            pw.println(-1);
            return;
        }

        Edge[][] G = adjB(N, E);
        Edge[][] T = mkTree();
        for (Node node : orderFromLeaf(N, T, 0)) {
            if( node.parent == -1 ) continue;

            // 残ってるのが偶数なら全部消費する
            // そうでないなら親へのEdge以外を消費する
            int cnt = 0;
            for (Edge e : G[node.a]) {
                if( !e.used ) {
                    cnt++;
                }
            }

            for (Edge e : G[node.a]) {
                if( e.used ) continue;

                int b = e.opposite(node.a);
                if( b == node.parent && cnt % 2 == 1 ) continue; // 親に任せる

                pw.println((node.a+1) + " " + (b+1));
                e.used = true;
            }
        }
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    static Node[] orderFromLeaf(int N, Edge[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (Edge e : G[n.a]) {
                int next = e.opposite(n.a);
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static Edge[][] mkTree() {
        UnionFind uf = new UnionFind(N);
        List<Edge> es = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            Edge e = E.get(i);
            if( !uf.isSame(e.a, e.b) ) {
                uf.unite(e.a, e.b);
                es.add( e );
            }
        }

        return adjB(N, es);
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] count;

        public UnionFind(int n) {
            parent = new int[n];
            count = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                count[i] = 1;
            }
        }

        public int root(int i) {
            if (parent[i] == i) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if (ri == rj) return ri;


            int big = count[ri] < count[rj] ? rj : ri;
            int small = big == ri ? rj : ri;
            parent[small] = big;
            count[big] += count[small];
            return big;
        }

        public int count(int a) {
            return count[root(a)];
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

    static class Edge {
        int a, b;
        boolean used;

        public Edge(int a, int b) {
            this.a = a;
            this.b = b;
        }

        public int opposite(int x) {
            return a == x ? b : a;
        }
    }

    static Edge[][] adjB(int n, List<Edge> E) {
        Edge[][] adj = new Edge[n][];
        int[] cnt = new int[n];
        for (Edge e : E) {
            cnt[e.a]++;
            cnt[e.b]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new Edge[cnt[i]];
        }
        for (Edge e : E) {
            adj[e.a][--cnt[e.a]] = e;
            adj[e.b][--cnt[e.b]] = e;
        }
        return adj;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.awt.Point;
import java.io.IOException;
import java.io.InputStream;
