	{
		int u, v;
		boolean alive;
		boolean special;
		public Edge(int u, int v) {
			this.u = u;
			this.v = v;
			alive = true;
		}
		@Override
		public String toString() {
			return "Edge [u=" + u + ", v=" + v + ", alive=" + alive + ", special=" + special + "]";
		}

