	private static void dfs(int cur, Map<Integer, Queue<Edge>> rem, List<Edge> route, Edge comein)
	{
		while(!rem.get(cur).isEmpty()) {
			Edge e = rem.get(cur).poll();
			if(e.alive) {
				e.alive = false;
				dfs(e.u ^ e.v ^ cur, rem, route, e);
			}
		}
		if(comein != null)route.add(comein);
	}



