			edges.get(a).add(b);
			edges.get(b).add(a);
		}

		PriorityQueue<Integer> pq = new PriorityQueue<>((o1, o2) -> {
			int result = Integer.compare(edges.get(o1).size(), edges.get(o2).size());
			return result;
		});
		for (int i = 0; i < n; i++) {
