				continue;
			}

			if (cnt[e] % 2 == 0 && size % 2 == 0) {
				for (int d : edges.get(e)) {
					int c = e;
					cnt[c]++;
					edges.get(d).remove(c);
					pq.add(d);
					pr(ans, c, d);
				}
				edges.get(e).clear();
				used[e] = true;
			} else if (cnt[e] % 2 == 1 && size % 2 == 0) {
				{
					int c = edges.get(e).first();
					int d = e;
					cnt[c]++;
					edges.get(c).remove(d);
					pq.add(c);
					pr(ans, c, d);
					edges.get(d).remove(c);
					pq.add(d);
				}
				{
					int c = e;
					int d = edges.get(e).first();
					cnt[c]++;
					edges.get(c).remove(d);
					pq.add(c);
					pr(ans, c, d);
					edges.get(d).remove(c);
					pq.add(d);
				}
			} else if (cnt[e] % 2 == 0 && size % 2 == 1) {
				int c = edges.get(e).first();
				int d = e;
				cnt[c]++;
				edges.get(c).remove(d);
				pq.add(c);
				pr(ans, c, d);
				edges.get(d).remove(c);
				pq.add(d);
			} else if (cnt[e] % 2 == 1 && size % 2 == 1) {
				int c = e;
				int d = edges.get(e).first();
				cnt[c]++;
				edges.get(c).remove(d);
				pq.add(c);
				pr(ans, c, d);
				edges.get(d).remove(c);
				pq.add(d);
			}
		}

		for (int i = 0; i < n; i++) {
			if (cnt[i] % 2 == 1) {
				pr.println(-1);
				return;
			}
		}

		pr.println(ans);
	}

	private static String CR = System.getProperty("line.separator");
	private static void pr(StringBuilder ans, int c, int d) {
		ans.append(c + 1);
		ans.append(' ');
		ans.append(d + 1);
		ans.append(CR);
	}

