/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BEvenDegrees solver = new BEvenDegrees();
        solver.solve(1, in, out);
        out.close();
    }

    static class BEvenDegrees {
        int[] score;
        StringBuilder sb;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();

            score = new int[n];

            List<Integer>[] adj = new List[n];
            int[] degree = new int[n];
            UnionFind uf = new UnionFind(n);
            for (int i = 0; i < n; i++)
                adj[i] = new ArrayList<>();

            sb = new StringBuilder();

            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                boolean tree = uf.union(a, b);
                if (tree) {
                    adj[a].add(b);
                    adj[b].add(a);
                    degree[a]++;
                    degree[b]++;
                } else {
                    direct(a, b);
                }
            }

            Queue<Integer> q = new ArrayDeque<>();
            BitSet visited = new BitSet();
            for (int i = 0; i < n; i++) {
                if (degree[i] == 1) {
                    q.add(i);
                }
            }

            while (!q.isEmpty()) {
                int i = q.poll();
                visited.set(i);

                for (int j : adj[i]) {
                    if (visited.get(j))
                        continue;
                    degree[j]--;
                    if (degree[j] == 1) {
                        q.add(j);
                    }
                    if (score[i] == 1) {
                        direct(i, j);
                    } else {
                        direct(j, i);
                    }
                }
            }

            boolean possible = true;
            for (int x : score) {
                if (x == 1)
                    possible = false;
            }

            out.println(possible ? sb.toString() : "-1");
        }

        void direct(int i, int j) {
            score[i] ^= 1;
            sb.append(String.format("%d %d%n", i + 1, j + 1));
        }

    }

    static class UnionFind {
        private int[] __rep;
        private int[] __size;

        public UnionFind(int n) {
            __rep = new int[n];
            __size = new int[n];
            for (int i = 0; i < n; i++) {
                __rep[i] = i;
                __size[i] = 1;
            }
        }

        public int rep(int x) {
            if (__rep[x] == x) {
                return x;
            }

            int r = rep(__rep[x]);
            __rep[x] = r;
            return r;
        }

        public int size(int x) {
            return __size[rep(x)];
        }

        public boolean union(int x, int y) {
            x = rep(x);
            y = rep(y);

            if (x == y) {
                return false;
            }

            if (size(x) < size(y)) {
                int t = x;
                x = y;
                y = t;
            }

            // now size(x) >= size(y)

            __rep[y] = x;
            __size[x] += __size[y];
            return true;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;
public class Main {

	static boolean e(int a) {
		return a % 2 == 0;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		int[][] a = new int[M+1][2];
		int[] num = new int[N+1];
		int[] out = new int[N+1];
		for(int i = 1; i <= M; i++) {
			a[i][0] = sc.nextInt();
			a[i][1] = sc.nextInt();
			num[a[i][0]]++;
			num[a[i][1]]++;
			if(a[i][1] > a[i][0]) {
				int t = a[i][0];
				a[i][0] = a[i][1];
				a[i][1] = t;
			}
		}
		Arrays.sort(a, (x,y) -> x[0] == y[0] ? x[1]-y[1] : x[0]-y[0]);
		boolean[] aout = new boolean[M+1];
		for(int i = 1; i <= M; i++) {
			if(!e(out[a[i][0]]) && e(out[a[i][1]]))
				aout[i] = true;
			else if(e(out[a[i][0]]) && !e(out[a[i][1]]));
			else {
				if(e(num[a[i][0]]) && !e(num[a[i][1]]))
					aout[i] = true;
				else if(!e(num[a[i][0]]) && e(num[a[i][1]]));
				else if(num[a[i][0]] <= num[a[i][1]])
					aout[i] = true;
			}
			num[a[i][0]]--;
			num[a[i][1]]--;
			if(aout[i])
				out[a[i][0]]++;
			else
				out[a[i][1]]++;
		}
		for(int i = 1; i <= N; i++) {
			if(!e(out[i])) {
				System.out.println(-1);
				return;
			}
		}
		for(int i = 1; i <= M; i++) {
			if(aout[i])
				System.out.println(a[i][0] + " " + a[i][1]);
			else
				System.out.println(a[i][1] + " " + a[i][0]);
		}

	}

}

import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.System.arraycopy;
import static java.lang.System.exit;
import static java.util.Arrays.copyOf;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {

	static class IntList {

		int data[] = new int[3];
		int size = 0;

		boolean isEmpty() {
			return size == 0;
		}

		int size() {
			return size;
		}

		int get(int index) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			return data[index];
		}

		void clear() {
			size = 0;
		}

		void set(int index, int value) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			data[index] = value;
		}

		void expand() {
			if (size >= data.length) {
				data = copyOf(data, (data.length << 1) + 1);
			}
		}

		void insert(int index, int value) {
			if (index < 0 || index > size) {
				throw new IndexOutOfBoundsException();
			}
			expand();
			arraycopy(data, index, data, index + 1, size++ - index);
			data[index] = value;
		}

		int delete(int index) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			int value = data[index];
			arraycopy(data, index + 1, data, index, --size - index);
			return value;
		}

		void push(int value) {
			expand();
			data[size++] = value;
		}

		int pop() {
			if (size == 0) {
				throw new NoSuchElementException();
			}
			return data[--size];
		}

		void unshift(int value) {
			expand();
			arraycopy(data, 0, data, 1, size++);
			data[0] = value;
		}

		int shift() {
			if (size == 0) {
				throw new NoSuchElementException();
			}
			int value = data[0];
			arraycopy(data, 1, data, 0, --size);
			return value;
		}
	}

	static IntList edges[];
	static byte seen[];

	static void solve() throws Exception {
		int n = scanInt(), m = scanInt();
		if (m % 2 != 0) {
			out.print(-1);
			return;
		}
		edges = new IntList[n];
		for (int i = 0; i < n; i++) {
			edges[i] = new IntList();
		}
		for (int i = 0; i < m; i++) {
			int a = scanInt() - 1, b = scanInt() - 1;
			edges[a].push(b);
			edges[b].push(a);
		}
		seen = new byte[n];
		dfs(0, -1);
	}

	static boolean dfs(int cur, int prev) {
		seen[cur] = 1;
		boolean odd = false;
		IntList ee = edges[cur];
		for (int i = 0; i < ee.size; i++) {
			int next = ee.data[i];
			if (next != prev) {
				if (seen[next] == 1) {
					out.println((cur + 1) + " " + (next + 1));
					odd = !odd;
				} else if (seen[next] == 0 && dfs(next, cur)) {
					odd = !odd;
				}
			}
		}
		if (prev >= 0) {
			out.println(odd ? (cur + 1) + " " + (prev + 1) : (prev + 1) + " " + (cur + 1));
		}
		seen[cur] = 2;
		return !odd;
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.io.*;
import java.util.*;

class Edge {
  final int minIndex, maxIndex;

  Edge(int index1, int index2) {
    minIndex = Math.min(index1, index2);
    maxIndex = Math.max(index1, index2);
  }

  public boolean equals(Object object) {
    Edge edge = (Edge) object;
    return this.minIndex == edge.minIndex && this.maxIndex == edge.maxIndex;
  }

  public int hashCode() {
    return 13 * maxIndex + minIndex;
  }
}

class Solver {
  final int n, m;
  final int[][] abs;

  List<List<Integer>> graph;
  Set<Edge> visited;
  List<Edge> edgeStack;
  List<String> output;

  Solver(int n, int m, int[][] abs) {
    this.n = n;
    this.m = m;
    this.abs = abs;
  }


  private void assignDirection(Edge edge1, Edge edge2) {
    int[] indexes = new int[]{
      edge1.minIndex,
      edge1.maxIndex,
      edge2.minIndex,
      edge2.maxIndex
    };
    int srcIndex = 0;
    for (int i = 0; i < 4; i++) {
      for (int j = i+1; j < 4; j++) {
        if (indexes[i] == indexes[j]) {
          srcIndex = indexes[i];
        }
      }
    }
    if (srcIndex == 0) {
      throw new RuntimeException();
    }
    for (int index : indexes) {
      if (index == srcIndex) {
        continue;
      }
      output.add(String.format("%d %d", srcIndex, index));
    }
  }

  private void mightAssignDirection() {
    if (edgeStack.size() < 4) {
      return;
    }
    Edge edge1 = edgeStack.get(edgeStack.size() - 1);
    Edge edge2 = edgeStack.get(edgeStack.size() - 2);
    Edge edge3 = edgeStack.get(edgeStack.size() - 3);
    Edge edge4 = edgeStack.get(edgeStack.size() - 4);
    if ((edge1.equals(edge2) && edge3.equals(edge4))
        || (edge1.equals(edge4) && edge2.equals(edge3))) {
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      assignDirection(edge1, edge3);
    }
  }

  private String formatNonDirectedEdge(int index1, int index2) {
    int minIndex = Math.min(index1, index2);
    int maxIndex = Math.max(index1, index2);
    return String.format("%d %d", minIndex, maxIndex);
  }

  private void edgeDfs(int index) {
    for (int next : graph.get(index)) {
      Edge edge = new Edge(index, next);
      if (visited.contains(edge)) {
        continue;
      }
      visited.add(edge);

      edgeStack.add(edge);
      edgeDfs(next);
      edgeStack.add(edge);

      mightAssignDirection();
    }
  }

  public List<String> solve() {
    if (m % 2 == 1) {
      return Arrays.asList("-1");
    }

    graph = new ArrayList<>();
    visited = new HashSet<>();
    edgeStack = new ArrayList<>();
    output = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }
    edgeDfs(1);
    return output;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    int[][] abs = reader.nextInt(m, 2);
    for (String line : new Solver(n, m, abs).solve()) {
      out.println(line);
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] next(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = next();
    }
    return array;
  }

  public int[] nextInt(int n) {
