import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	static int n=0;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		// 整数の入力
		n = sc.nextInt();
		int m = sc.nextInt();

		List<Line> lines = new ArrayList<>();
		for(int i = 0; i< m;i++){
			lines.add(new Line (sc.nextInt(), sc.nextInt()));
		}
		boolean result = dfs(lines, 0);
		if(!result){
			System.out.println("-1");
		} else {
			for (Line line : lines) {
				System.out.println(line);
			}
		}

	}

	private static boolean dfs(List<Line> list, int index){
		if(index == list.size()-1) {
			boolean allEven = true;
			int[] from = new int [n];
			for (Line line : list) {
				if(line.dir){
					from[line.a-1]=from[line.a-1]+1;
				} else {
					from[line.b-1]=from[line.b-1]+1;
				}
			}
			for (int i : from) {
				if(i%2!=0){
					allEven = false;
					break;
				}
			}
			return allEven;
		}
		Line line = list.get(index);
		line.setDir(true);
		if(dfs(list, index+1)){
			return true;
		}
		line.setDir(false);
		return dfs(list, index+1);
	}

	private static class Line{ // true >       false <
		private int a = 0;
		private int b = 0;
		private boolean dir = false;
		Line(int a, int b){
			this.a = a;
			this.b = b;
		}

		void setDir(boolean dir){
			this.dir = dir;
		}

		@Override
		public String toString(){
			if(dir){
				return a + " " + b;
			}
			return b + " " + a;
		}
	}



}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N, M;
    static List<Edge> E;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        E = new ArrayList<>(M);
        for (int i = 0; i < M; i++) {
            E.add(new Edge(sc.nextInt()-1, sc.nextInt()-1));
        }

        PrintWriter pw = new PrintWriter(System.out);
        solve(pw);
        pw.flush();
    }

    static void solve(PrintWriter pw) {
        if( M % 2 == 1 ) {
            pw.println(-1);
            return;
        }

        Edge[][] G = adjB(N, E);
        Edge[][] T = mkTree();
        for (Node node : orderFromLeaf(N, T, 0)) {
            // 残ってるのが偶数なら全部消費する
            // そうでないなら親へのEdge以外を消費する
            int cnt = 0;
            for (Edge e : G[node.a]) {
                if( !e.used ) {
                    cnt++;
                }
            }

            for (Edge e : G[node.a]) {
                if( e.used ) continue;

                int b = e.opposite(node.a);
                if( b == node.parent && cnt % 2 == 1 ) continue; // 親に任せる

                pw.println((node.a+1) + " " + (b+1));
                e.used = true;
            }
        }
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    static Node[] orderFromLeaf(int N, Edge[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (Edge e : G[n.a]) {
                int next = e.opposite(n.a);
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static Edge[][] mkTree() {
        UnionFind uf = new UnionFind(N);
        List<Edge> es = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            Edge e = E.get(i);
            if( !uf.isSame(e.a, e.b) ) {
                uf.unite(e.a, e.b);
                es.add( e );
            }
        }

        return adjB(N, es);
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] count;

        public UnionFind(int n) {
            parent = new int[n];
            count = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                count[i] = 1;
            }
        }

        public int root(int i) {
            if (parent[i] == i) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if (ri == rj) return ri;


            int big = count[ri] < count[rj] ? rj : ri;
            int small = big == ri ? rj : ri;
            parent[small] = big;
            count[big] += count[small];
            return big;
        }

        public int count(int a) {
            return count[root(a)];
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

    static class Edge {
        int a, b;
        boolean used;

        public Edge(int a, int b) {
            this.a = a;
            this.b = b;
        }

        public int opposite(int x) {
            return a == x ? b : a;
        }
    }

    static Edge[][] adjB(int n, List<Edge> E) {
        Edge[][] adj = new Edge[n][];
        int[] cnt = new int[n];
        for (Edge e : E) {
            cnt[e.a]++;
            cnt[e.b]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new Edge[cnt[i]];
        }
        for (Edge e : E) {
            adj[e.a][--cnt[e.a]] = e;
            adj[e.b][--cnt[e.b]] = e;
        }
        return adj;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
