    int dfs(int cur){
        seen[cur] = true;
        int ret = num[cur];
        for(int e : edge[cur]){
            if(seen[e]) continue;
            ret += dfs(e);
        }
        num2[cur] = ret%2;
        return num2[cur];
    }

    void dfs2(int cur, int flip){
        seen[cur] = true;
        long ret = num[cur];
        if(flip==1){
            ret = 1 - ret;
        }
        for(int e : edge[cur]){
            if(seen[e]) continue;
            if(num2[e]==1){
                long res = cur*1000000000l + e;
                map.remove(res);
                res = e*1000000000l + cur;
                map.add(res);
                dfs2(e,1);
                ret = 1 - ret;
            }
            else{
                dfs2(e,0);
            }
        }
        // out.println(ret);
