import java.io.*;
import java.util.*;
import java.math.*;
// import java.awt.Point;

public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    // long inf = Long.MAX_VALUE/2;
    int inf = Integer.MAX_VALUE/2;

    ArrayList<Integer>[] edge;
    int[] num, num2;
    boolean[] seen;
    HashSet<Long> map = new HashSet<>();
    void solve(){
        int n = ni();
        int m = ni();
        edge = new ArrayList[n];
        for(int i = 0; i < n; i++){
            edge[i] = new ArrayList<Integer>();
        }
        num = new int[n];
        num2 = new int[n];

        for(int i = 0; i < m; i++){
            int s = ni()-1;
            int t = ni()-1;
            long ret = s*1000000000l + t;
            map.add(ret);
            edge[s].add(t);
            edge[t].add(s);
            num[s]++;
            num[s] = num[s]%2;
        }
        int sum = 0;
        for(int i = 0; i < n; i++){
            sum += num[i];
        }
        if(sum%2!=0){
            out.println(-1);
            return;
        }
        seen = new boolean[n];
        dfs(0);
        // out.println();
        // for(int i = 0; i < n; i++){
        //     out.println(num[i] + " " + num2[i]);
        // }
        seen = new boolean[n];
        dfs2(0,0);   
        for(long i : map){
            long s = i/1000000000l;
            long t = i%1000000000l;
            out.println(s+" "+t);
        }  
    }

    int dfs(int cur){
        seen[cur] = true;
        int ret = num[cur];
        for(int e : edge[cur]){
            if(seen[e]) continue;
            ret += dfs(e);
        }
        num2[cur] = ret%2;
        return num2[cur];
    }

    void dfs2(int cur, int flip){
        seen[cur] = true;
        int ret = num[cur];
        if(flip==1){
            ret = 1 - ret;
        }
        for(int e : edge[cur]){
            if(seen[e]) continue;
            if(num2[e]==1){
                long res = cur*1000000000l + e;
                map.remove(res);
                res = e*1000000000l + cur;
                map.add(res);
                dfs2(e,1);
                ret = 1 - ret;
            }
            else{
                dfs2(e,0);
            }
        }
        // out.println(ret);
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.TreeSet;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		int m = Integer.parseInt(sa[1]);
		Map<Integer, Set<Integer>> map = new HashMap<>();
		for (int i = 0; i < m; i++) {
			sa = br.readLine().split(" ");
			int a = Integer.parseInt(sa[0]) - 1;
			int b = Integer.parseInt(sa[1]) - 1;

			Set<Integer> set1 = map.get(a);
			if (set1 == null) {
				set1 = new HashSet<>();
				map.put(a, set1);
			}
			set1.add(b);

			Set<Integer> set2 = map.get(b);
			if (set2 == null) {
				set2 = new HashSet<>();
				map.put(b, set2);
			}
			set2.add(a);
		}
		br.close();

		if (m % 2 == 1) {
			System.out.println(-1);
			return;
		}

		int[] dep = new int[n];
		Queue<Integer> que = new ArrayDeque<Integer>();
		que.add(0);
		dep[0] = 1;
		while (!que.isEmpty()) {
			Integer cur = que.poll();
			Set<Integer> set = map.get(cur);
			for (int next : set) {
				if (dep[next] == 0) {
					que.add(next);
					dep[next] = dep[cur] + 1;
				}
			}
		}

		TreeSet<Node> ts = new TreeSet<>();
		for (int i = 0; i < dep.length; i++) {
			ts.add(new Node(i, dep[i]));
		}
		for (Node cur : ts) {
			Set<Integer> set = map.get(cur.idx);
			Integer[] arr = set.toArray(new Integer[0]);
			int size = arr.length;
			int min = Integer.MAX_VALUE;
			int p = -1;
			if (size % 2 == 1) {
				for (int i = 0; i < size; i++) {
					if (min > dep[arr[i]]) {
						min = dep[arr[i]];
						p = i;
					}
				}
			}
			for (int i = 0; i < size; i++) {
				if (i == p) {
					continue;
				}
				System.out.println((cur.idx + 1) + " " + (arr[i] + 1));
				map.get(arr[i]).remove(cur.idx);
			}
		}
	}

	static class Node implements Comparable<Node> {
		int idx, dep;

		public Node (int idx, int dep) {
			this.idx = idx;
			this.dep = dep;
		}

		public int compareTo(Node o) {
			return o.dep - dep;
		}
	}
}

