        }

        public void reverse() {
            int tmp = from;
            from = to;
            to = tmp;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        List<List<Edge>> edges = new ArrayList<>();
        for (int i = 0; i < N; i++) edges.add(new ArrayList<>());

        boolean odd[] = new boolean[N];
        for (int i = 0; i < M; i++) {
            Edge e = new Edge(sc.nextInt() - 1, sc.nextInt() - 1);
            if (odd[e.to]) e.reverse();
            odd[e.from] = !odd[e.from];
            edges.get(e.from).add(e);
            edges.get(e.to).add(e);
        }

        List<Integer> todo = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            if (odd[i]) todo.add(i);
        }

        if (todo.size() % 2 != 0) {
            System.out.println(-1);
            return;
        }

        for (int u : todo) {
            if (odd[u]) {
                if (!increase(u, edges, odd) && !decrease(u, edges, odd)) {
                    System.out.println(-1);
                    return;
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (Edge e : edges.get(i)) {
                if (i == e.from) {
                    System.out.println((e.from + 1) + " " + (e.to + 1));
                }
            }
        }
    }

    static boolean increase(int s, List<List<Edge>> E, boolean[] odd) {
        LinkedList<Integer> queue = new LinkedList<>();
        Edge[] pred = new Edge[odd.length];
        queue.add(s);

        while (!queue.isEmpty()) {
            int u = queue.pollLast();

            for (Edge e : E.get(u)) {
                if ((pred[u] == null || pred[u].to == u) && e.to != u) continue;
                if (pred[u] != null && pred[u].from == u && e.from != u) continue;
                int v = e.other(u);
                if (v == s || pred[v] != null) continue;
                if (odd[v]) {
                    odd[v] = false;
                    e.reverse();
                    while (pred[u] != null) {
                        pred[u].reverse();
                        u = pred[u].other(u);
                    }
                    odd[u] = false;
                    return true;
                }
                queue.addFirst(v);
                pred[v] = e;
            }
        }
        return false;
    }

    static boolean decrease(int s, List<List<Edge>> E, boolean[] odd) {
        LinkedList<Integer> queue = new LinkedList<>();
        Edge[] pred = new Edge[odd.length];
        queue.add(s);

        while (!queue.isEmpty()) {
            int u = queue.pollLast();

            for (Edge e : E.get(u)) {
                if ((pred[u] == null || pred[u].from == u) && e.from != u) continue;
                if (pred[u] != null && pred[u].to == u && e.to != u) continue;
                int v = e.other(u);
                if (v == s || pred[v] != null) continue;
                if (odd[v]) {
                    odd[v] = false;
                    e.reverse();
                    while (pred[u] != null) {
                        pred[u].reverse();
                        u = pred[u].other(u);
                    }
                    odd[u] = false;
                    return true;
                }
                queue.addFirst(v);
                pred[v] = e;
            }
        }
        return false;
    }
}

