    int[] from = new int[m];
    int[] to = new int[m];
    int[] deg = new int[n];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
      deg[from[i]]++;
      deg[to[i]]++;
    }

    int[][] g = packU(n, from, to);
    int[] par = new int[n];
    boolean bi = dfs(0, g, par, true);

    int leaf = 0;
    int root = -1;
    for (int i = 0; i < n; i++) {
      if (deg[i] == 1) {
        leaf++;
        root = i;
      }
    }
    if (root < 0) {
      root = 0;
    }

    if (leaf % 2 == 1 || !bi) {
      System.out.println(-1);
    } else {
      StringBuilder sb = new StringBuilder();
      for (int cur = 0; cur < n; cur++) {
        for (int nex : g[cur]) {
          if (cur > nex)
            continue;

          int u = cur + 1;
          int v = nex + 1;
          if (par[cur] == par[root]) {
            int tmp = u;
            u = v;
            v = tmp;
          }
          sb.append(u + " " + v + "\n");
        }
      }
      System.out.println(sb);
    }
  }

  private static boolean dfs(int cur, int[][] g, int[] par, boolean now) {
    par[cur] = now ? 1 : -1;
    for (int nex : g[cur]) {

      if (par[nex] == 0) {
        if (!dfs(nex, g, par, !now)) {
          return false;
        }
      } else if (par[cur] == par[nex]) {
        return false;
      }
    }
    return true;
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

