                        task.add(A[j].get(0));
                        A[j].remove(0);
                        j=j-1;
                        break;
                    }
                    A[j].remove(0);
                }

                while(task.size()!=0) {
                    int i=task.get(0);
                    task.remove(0);
                    if(A[i].size()==0)continue;
                    A[A[i].get(0)].remove(Integer.valueOf(i));
                    if (A[A[i].get(0)].size() == 1) {
                        task.add(A[i].get(0));
                    }
                    if (B[i] % 2 == 0) {
                        B[A[i].get(0)]++;
                        br.append(A[i].get(0)+1);
                        br.append(" ");
                        br.append(i+1);
                        br.append("\n");
                    } else {
                        br.append(i+1);
                        br.append(" ");
                        br.append(A[i].get(0)+1);
                        br.append("\n");
                    }
                    A[i].remove(0);

                }

            }
        }
        System.out.println(br.toString());


    }
