import java.util.LinkedList;
import java.util.ListIterator;
import java.util.Scanner;

public class Main {

	private class UnionField {
		public class Node {
			public int self = 0;
			public boolean even = true;
			public boolean isReverseToParent = false;
			public int real = -1;
			public int parent = 0;
			public LinkedList<Integer> children = new LinkedList<Integer>();

			public boolean isEven() {
				int count = children.size();
				if (even == false) {
					count++;
				}
				if (count % 2 == 0) {
					return true;
				} else {
					return false;
				}
			}

			public Node(int self, int parent) {
				this.self = self;
				this.parent = parent;
			}

			public void reverse() {
				this.even = !this.even;
			}

			public void reverseToParent(Node[] nodes) {
				this.isReverseToParent = !this.isReverseToParent;
				if (parent != self) {
					nodes[parent].reverseToParent(nodes);
				}

			}

			public void addChild(int node) {
				children.add(node);
			}

			public void setReal(Node[] nodes, int node) {
				this.real = node;

				ListIterator<Integer> it = children.listIterator();
				while (it.hasNext()) {
					int c = it.next();
					if (c == node) {
						it.remove();
					} else if (c != self) {
						nodes[c].setReal(nodes, self);
					}
				}
			}
		}

		public Node nodes[] = null;

		public UnionField(int size) {
			this.nodes = new Node[size];
			for (int i=0; i<this.nodes.length; i++) {
				this.nodes[i] = new Node(i, i);
			}
		}

		public int getRoot(int node) {
			int parent = this.nodes[node].parent;
			if (parent == node) {
				return node;
			} else {
				int root = getRoot(parent);
				this.nodes[node].parent = root;
				return root;
			}
		}

		public void union(int a, int b) {
			a = getRoot(a);
			b = getRoot(b);
			if (a != b) {
				this.nodes[a].parent = b;
			}
		}

		public boolean isSame(int a, int b) {
			a = getRoot(a);
			b = getRoot(b);
			return (a == b);
		}
	}
	private class Way {
		public int a;
		public int b;
		public Way(int a, int b) {
			this.a = a;
			this.b = b;
		}

		public String toString() {
			return (a+1) + " " + (b+1);
		}
	}
	public void solve() {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();
		int M = in.nextInt();

		UnionField field = new UnionField(N);
		LinkedList<Way> unused = new LinkedList<Way>();
		for (int i=0; i<M; i++) {
			int a = in.nextInt() - 1;
			int b = in.nextInt() - 1;

			if (field.isSame(a, b)) {
				//System.err.println("Unused " + (a+1) + "," + (b+1));
				unused.add(new Way(a, b));
				field.nodes[a].reverse();
			} else {
				//System.err.println("Add " + (a+1) + "," + (b+1));
				field.union(a, b);
				field.nodes[a].addChild(b);
				field.nodes[b].addChild(a);
			}
		}
		in.close();
		field.nodes[0].setReal(field.nodes, 0);

		int count = 0;
		for (int i=0; i<N; i++) {
			if (field.nodes[i].isEven() == false) {
				count++;
				//System.err.println("odd  : " + (i+1));
			} else {
				//System.err.println("even : " + (i+1));
			}
		}
		if (count % 2 != 0) {
			System.out.println(-1);
			return;
		}

		for (int i=0; i<N; i++) {
			if (field.nodes[i].isEven() == false) {
				field.nodes[i].reverseToParent(field.nodes);
			}
		}
		for (int i=1; i<N; i++) {
			if (field.nodes[i].isReverseToParent) {
				System.out.println((i+1) + " " + (field.nodes[i].real+1));
			} else {
				System.out.println((field.nodes[i].real+1) + " " + (i+1));
			}
		}
		for (Way way : unused) {
			System.out.println(way);
		}
	}

	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
	}

}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.List;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B_EvenDegrees solver = new B_EvenDegrees();
        solver.solve(1, in, out);
        out.close();
    }

    static class B_EvenDegrees {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            if (m % 2 != 0) {
                out.println(-1);
                return;
            }
            List<Edge>[] edges = new List[n];
            for (int i = 0; i < n; i++) {
                edges[i] = new ArrayList<>();
            }
            for (int i = 0; i < m; i++) {
                Edge e = new Edge();
                e.a = in.nextInt() - 1;
                e.b = in.nextInt() - 1;
                edges[e.a].add(e);
                edges[e.b].add(e);
            }
            int[] q = new int[n];
            int qh = 0;
            int qt = 1;
            Edge[] p = new Edge[n];
            while (qh < qt) {
                int v = q[qh++];
                for (Edge e : edges[v]) {
                    int u = e.otherEnd(v);
                    if (u != 0 && p[u] == null) {
                        e.inTree = true;
                        p[u] = e;
                        q[qt++] = u;
                    }
                }
            }
            List<Edge>[] ans = new List[n];
            for (int i = 0; i < n; i++) {
                ans[i] = new ArrayList<>();
            }
            int[] deg = new int[n];
            for (int i = 0; i < n; i++) {
                for (Edge e : edges[i]) {
                    if (!e.inTree && e.a == i) {
                        ++deg[e.a];
                        ans[e.a].add(e);
                    }
                }
            }
            for (int i = n - 1; i > 0; i--) {
                int v = q[i];
                Edge e = p[v];
                if (deg[v] % 2 == 0) {
                    v = e.otherEnd(v);
                }
                ++deg[v];
                ans[v].add(e);
                if (e.a != v) {
                    e.swapEnds();
                }
            }
            for (int i = 0; i < n; i++) {
                for (Edge e : ans[i]) {
                    out.println((e.a + 1) + " " + (e.b + 1));
                }
            }
        }

        class Edge {
            int a;
            int b;
            boolean inTree;

            void swapEnds() {
                int t = a;
                a = b;
                b = t;
            }

            int otherEnd(int v) {
                return a ^ b ^ v;
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String rl = in.readLine();
                    if (rl == null) {
                        return null;
                    }
                    st = new StringTokenizer(rl);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

