/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Sparsh Sanchorawala
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BEvenDegrees solver = new BEvenDegrees();
        solver.solve(1, in, out);
        out.close();
    }

    static class BEvenDegrees {
        public void solve(int testNumber, InputReader s, PrintWriter w) {
            int n = s.nextInt(), m = s.nextInt();
            TreeSet<Integer>[] hs = new TreeSet[2];
            Edge[] edge = new Edge[m];
            int[] dir = new int[m];
            HashSet<Integer>[] adj = new HashSet[n];
            for (int i = 0; i < n; i++)
                adj[i] = new HashSet<>();
            for (int i = 0; i < m; i++) {
                edge[i] = new Edge(s.nextInt() - 1, s.nextInt() - 1);
                adj[edge[i].u].add(i);
                adj[edge[i].v].add(i);
            }
            if (m % 2 == 1) {
                w.println(-1);
                return;
            }
            hs[0] = new TreeSet<>();
            hs[1] = new TreeSet<>();
            for (int i = 0; i < n; i++)
                hs[adj[i].size() % 2].add(i);
            int[] par = new int[n];
            for (int i = 0; i < n; i++)
                par[i] = adj[i].size() % 2;
            for (int j = 0; j < n; j++) {
                int x = -1;
                int odd = 0;
                if (!hs[0].isEmpty()) {
                    x = hs[0].first();
                    hs[0].remove(x);
                } else {
                    x = hs[1].first();
                    hs[1].remove(x);
                    odd = 1;
                }
                int c = 0;
                for (int i : adj[x]) {
                    Edge e = edge[i];
                    if (c == adj[x].size() - 1 && odd == 1) {
                        if (edge[i].u == x)
                            dir[i] = 1;
                        int y = edge[i].other(x);
                        hs[par[y]].remove(y);
                        adj[y].remove(i);
                        hs[par[y]].add(y);
                    } else {
                        if (edge[i].v == x)
                            dir[i] = 1;
                        int y = edge[i].other(x);
                        hs[par[y]].remove(y);
                        adj[y].remove(i);
                        par[y] ^= 1;
                        hs[par[y]].add(y);
                    }

                    c++;
                }
            }

            for (int i = 0; i < m; i++) {
                if (dir[i] == 0) {
                    w.println((edge[i].u + 1) + " " + (edge[i].v + 1));
                } else
                    w.println((edge[i].v + 1) + " " + (edge[i].u + 1));
            }
        }

        class Edge {
            int u;
            int v;

            Edge(int u, int v) {
                this.u = u;
                this.v = v;
            }

            int other(int x) {
                return (x == u) ? v : u;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.*;
import java.util.*;

class Edge {
  final int id, dst;

  Edge(int id, int dst) {
    this.id = id;
    this.dst = dst;
  }
}

class Solver {
  final int n, m;
  final int[][] abs;

  List<List<Edge>> graph;
  boolean[] visited;
  List<Integer> edgeStack;
  List<String> output;

  Solver(int n, int m, int[][] abs) {
    this.n = n;
    this.m = m;
    this.abs = abs;
  }

  private void assignDirection(int edgeId1, int edgeId2) {
    int[] indexes = new int[]{
      abs[edgeId1][0],
      abs[edgeId1][1],
      abs[edgeId2][0],
      abs[edgeId2][1]
    };
    int srcIndex = 0;
    for (int i = 0; i < 4; i++) {
      for (int j = i+1; j < 4; j++) {
        if (indexes[i] == indexes[j]) {
          srcIndex = indexes[i];
        }
      }
    }
    if (srcIndex == 0) {
      throw new RuntimeException();
    }
    for (int index : indexes) {
      if (index == srcIndex) {
        continue;
      }
      output.add(String.format("%d %d", srcIndex, index));
    }
  }

  private void mightAssignDirection() {
    if (edgeStack.size() < 4) {
      return;
    }
    int edgeId1 = edgeStack.get(edgeStack.size() - 1);
    int edgeId2 = edgeStack.get(edgeStack.size() - 2);
    int edgeId3 = edgeStack.get(edgeStack.size() - 3);
    int edgeId4 = edgeStack.get(edgeStack.size() - 4);
    if ((edgeId1 == edgeId2 && edgeId3 == edgeId4)
        || (edgeId1 == edgeId4 && edgeId2 == edgeId3)) {
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      edgeStack.remove(edgeStack.size() - 1);
      assignDirection(edgeId1, edgeId3);
    }
  }

  private void edgeDfs(int index) {
    for (Edge edge : graph.get(index)) {
      if (visited[edge.id]) {
        continue;
      }
      visited[edge.id] = true;

      edgeStack.add(edge.id);
      edgeDfs(edge.dst);
      edgeStack.add(edge.id);

      mightAssignDirection();
    }
  }

  public List<String> solve() {
    if (m % 2 == 1) {
      return Arrays.asList("-1");
    }

    graph = new ArrayList<>();
    visited = new boolean[m];
    edgeStack = new ArrayList<>();
    output = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int i = 0; i < m; i++) {
      int a = abs[i][0];
      int b = abs[i][1];
      graph.get(a).add(new Edge(i, b));
      graph.get(b).add(new Edge(i, a));
    }
    edgeDfs(1);
    return output;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    int[][] abs = reader.nextInt(m, 2);
    for (String line : new Solver(n, m, abs).solve()) {
      out.println(line);
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

