			edges.get(b).add(a);
		}

		if (m % 2 == 1) {
			pr.println(-1);
			return;
		}

		int[] cnt = new int[n];

		PriorityQueue<Integer> pq = new PriorityQueue<>((o1, o2) -> {
			int result = Integer.compare(cnt[o2] % 2, cnt[o1] % 2);
			if (result == 0) {
				result = Integer.compare(edges.get(o1).size(), edges.get(o2).size());
			}
			return result;
		});
		for (int i = 0; i < n; i++) {
			pq.add(i);
		}

		StringBuilder ans = new StringBuilder();
		boolean[] used = new boolean[n];
		while (!pq.isEmpty()) {
			int e = pq.remove();
			int size = edges.get(e).size();

			if (size == 0) {
				continue;
			}
			if (used[e]) {
				continue;
			}

			if (cnt[e] % 2 == 0 && size % 2 == 0) {
				for (int d : edges.get(e)) {
					int c = e;
					cnt[c]++;
					edges.get(d).remove(c);
					pq.add(d);
					pr(ans, c, d);
				}
				edges.get(e).clear();
				used[e] = true;
			} else if (cnt[e] % 2 == 1 && size % 2 == 0) {
				{
					int c = edges.get(e).first();
					int d = e;
					cnt[c]++;
					edges.get(c).remove(d);
					pq.add(c);
					pr(ans, c, d);
					edges.get(d).remove(c);
					pq.add(d);
				}
				{
					int c = e;
					int d = edges.get(e).first();
					cnt[c]++;
					edges.get(c).remove(d);
					pq.add(c);
					pr(ans, c, d);
					edges.get(d).remove(c);
					pq.add(d);
				}
			} else if (cnt[e] % 2 == 0 && size % 2 == 1) {
				int c = edges.get(e).first();
				int d = e;
				cnt[c]++;
				edges.get(c).remove(d);
				pq.add(c);
				pr(ans, c, d);
				edges.get(d).remove(c);
				pq.add(d);
			} else if (cnt[e] % 2 == 1 && size % 2 == 1) {
				int c = e;
				int d = edges.get(e).first();
				cnt[c]++;
				edges.get(c).remove(d);
				pq.add(c);
				pr(ans, c, d);
				edges.get(d).remove(c);
				pq.add(d);
			}
		}

		for (int i = 0; i < n; i++) {
			if (cnt[i] % 2 == 1) {
				pr.println(-1);
				return;
			}
		}

		pr.println(ans);
	}

	private static String CR = System.getProperty("line.separator");
