            return;
        }
        StringBuilder br=new StringBuilder();
        while (true) {
            boolean breakFrag = true;
            for (int i = 0; i < N; i++) {
                if (A[i].size() == 1) {
                    A[A[i].get(0)].remove(Integer.valueOf(i));
                    if (B[i] % 2 == 0) {
                        B[A[i].get(0)]++;
                        br.append(A[i].get(0)+1);
                        br.append(" ");
                        br.append(i+1);
                        br.append("\n");
