                        br.append(i+1);
                        br.append(" ");
                        br.append(A[i].get(0)+1);
                        br.append("\n");
                    }
                    A[i].remove(0);
                    breakFrag = false;
                }
            }
            if (breakFrag) break;
        }
        for(int j=0;j<N;j++){
            ArrayList<Integer> task=new ArrayList<Integer>();
            if(A[j].size()!=0) {
