                        task.add(A[j].get(0));
                        A[j].remove(0);
                        j=j-1;

                        break;
                    }
                    A[j].remove(0);
                }

                while(task.size()!=0) {
                    int i=task.get(0);
                    task.remove(0);
                    if(A[i].size()==0)continue;
                    A[A[i].get(0)].remove(Integer.valueOf(i));
                    if (A[A[i].get(0)].size() == 1) {
