    int[] num, num2;
    boolean[] seen;
    HashSet<Long> map = new HashSet<>();
    void solve(){
        int n = ni();
        int m = ni();
        edge = new ArrayList[n];
        for(int i = 0; i < n; i++){
            edge[i] = new ArrayList<Integer>();
        }
        num = new int[n];
        num2 = new int[n];

        for(int i = 0; i < m; i++){
            int s = ni()-1;
            int t = ni()-1;
            long ret = s*1000000000l + t;
            map.add(ret);
            edge[s].add(t);
            edge[t].add(s);
            num[s]++;
            num[s] = num[s]%2;
        }
        if((m%2)!=0){
            out.println(-1);
            return;
        }
        seen = new boolean[n];
        dfs(0); 
        int[] ans = new int[n];
        for(long i : map){
            long s = i/1000000000l;
            long t = i%1000000000l;
            out.println((s+1)+" "+(t+1));
            ans[(int)s]++;
        } 
        for(int i = 0; i < n; i++){
            if(ans[i]%2!=0){
                out.println(i);
            }
        }
    }

    int dfs(int cur){
        seen[cur] = true;
        int ret = num[cur];
        System.err.println("orig: "+cur+" "+ret);
        for(int e : edge[cur]){
            if(seen[e]) continue;
            int tmp = dfs(e);
            if(tmp%2==1){
                out.println("flip: "+cur+" "+e);
                long res = cur*1000000000l + e;
                long res2 = e*1000000000l + cur;
                if(map.containsKey(res)){
                    map.remove(res);
                    map.add(res2);
                }
                else{
                    map.remove(res2);
                    map.add(res);
                }
                ret = 1 - ret;  
            }
        }
        // out.println("result: "+cur+" "+ret);
        return ret%2;
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
