		List<Line> lines = new ArrayList<>();
		for(int i = 0; i< m;i++){
			lines.add(new Line (sc.nextInt(), sc.nextInt()));
		}

		from = new boolean [n];

		boolean result = dfs(lines, 0);
		if(!result){
			System.out.println("-1");
		} else {
			for (Line line : lines) {
				System.out.println(line);
			}
		}

	}

	private static boolean dfs(List<Line> list, int index){
		if(index == list.size()) {
			boolean allEven = true;
			for (boolean i : from) {
				if(i){
					return false;
				}
			}
			return allEven;
		}
		Line line = list.get(index);
		line.setDir(true);
		from[line.a-1]=!from[line.a-1];
		if(dfs(list, index+1)){
			return true;
		}
		from[line.a-1]=!from[line.a-1];

		line.setDir(false);
		from[line.b-1]=!from[line.b-1];
		if( dfs(list, index+1)){
			return true;
		}
		from[line.b-1]=!from[line.b-1];
		return false;
	}

	private static class Line{ // true >       false <
