        public struct Edge
        {
            public int from;
            public int to;
        }

        public IEnumerable<string> Solve()
        {
            var res = Slv();
            if (res == null)
            {
                yield return "-1";
            }
            else
            {
                foreach (var e in res)
                {
                    yield return e.from.ToString() + " " + e.to.ToString();
                }
            }
        }

        public List<Edge> Slv()
        {
            n = ScanInt;
            m = ScanInt;
            if (m % 2 == 1)
            {
                return null;
            }

            es = Loop(1, n).ToDictionary(x => x, x => new HashSet<int>());
            a = new List<int>();
            b = new List<int>();
            foreach (var x in Loop(m))
            {
                var aa = ScanInt;
                var bb = ScanInt;
                a.Add(aa);
                b.Add(bb);

                es[aa].Add(bb);
                es[bb].Add(aa);
            }

            var odds = new HashSet<int>(es.Where(x => x.Value.Count % 2 == 1).Select(x => x.Key));
            var evens = new HashSet<int>(es.Where(x => x.Value.Count % 2 == 0).Select(x => x.Key));
            var res = new List<Edge>();

            var usedCount = 0;

            while (usedCount < m)
            {
                if (evens.Any() == false)
                    return null;

                var from = odds.SelectMany(x => es[x]).FirstOrDefault(x => evens.Contains(x));
                if (from == 0)
                    from = evens.First();
                var tos = es[from].OrderByDescending(x => odds.Contains(x)).Take(2).ToList();

                res.Add(new Edge() { from = from, to = tos[0] });
                res.Add(new Edge() { from = from, to = tos[1] });

                es[from].Remove(tos[0]);
                es[from].Remove(tos[1]);
                es[tos[0]].Remove(from);
                es[tos[1]].Remove(from);

                if (es[from].Any() == false)
                    evens.Remove(from);

                foreach (var to in tos)
                {
                    var toc = es[to].Count;

                    if (toc == 0)
                    {
                        odds.Remove(to);
                    }
                    else if (toc % 2 == 1)
                    {
                        odds.Add(to);
                        evens.Remove(to);
                    }
                    else
                    {
                        evens.Add(to);
                        odds.Remove(to);
                    }
                }


                usedCount += 2;
            }

            return res;
        }
    }

