class Solver
{
    public void Solve()
    {
        //Solve Code Here
        int N = Cin, M = Cin;
        var tree = new Node[N];
        for (var i = 0; i < tree.Length; i++)
        {
            tree[i] = new Node {Id = i + 1};
        }

        for (int i = 0; i < M; i++)
        {
            int a = Cin, b = Cin;
            tree[a - 1].AddConnection(tree[b - 1]);
        }

        tree = tree.OrderBy(val => val.Connections.Count).ToArray();

        foreach (var node in tree)
        {
            Transform(node);
        }

        var fromCount = new int[N];
        foreach (var connection in Connection.AllConnections)
        {
            fromCount[connection.From.Id - 1]++;
        }

        int f = 0;
        for (var i = 0; i < N; i++)
        {
            f |= fromCount[i];
        }

        if ((f & 1) != 0)
        {
            Coutln(-1);
            return;
        }

        foreach (var connection in Connection.AllConnections)
        {
            Coutln(connection.From.Id + " " + connection.To.Id);
        }
    }

    //Other Functions Here

    private void Transform(Node node)
    {
        node.Flg = true;
        int thisFromCount = 0;
        foreach (var connection in node.Connections)
        {
            if (connection.From == node)
            {
                thisFromCount++;
            }
        }

        thisFromCount &= 1;
        foreach (var connection in node.Connections)
        {
            var other = connection.Other(node);
            if (other.Flg) continue;
            if (thisFromCount > 0)
            {
                thisFromCount--;
                connection.Swap();
            }
        }
    }
}

//Other Classes Here
class Node
{
    public bool Flg { get; set; } = false;
    public int Id { get; set; }
    public List<Connection> Connections { get; } = new List<Connection>();

    public void AddConnection(Node n)
    {
        var connection = new Connection {From = this, To = n};
        this.Connections.Add(connection);
        n.Connections.Add(connection);
    }

    public static bool operator ==(Node n1, Node n2)
    {
        return n1.Id == n2.Id;
    }

    public static bool operator !=(Node n1, Node n2)
    {
        return !(n1 == n2);
    }
}

class Connection
{
    public static List<Connection> AllConnections { get; } = new List<Connection>();
    public Node From { get; set; }
    public Node To { get; set; }

    public Connection()
    {
        AllConnections.Add(this);
    }

    public void Swap()
    {
        var tmp = From;
        From = To;
        To = tmp;
    }

    public Node Other(Node n)
    {
        return From == n ? To : From;
    }
}

