public class B
{
	public static void Main()
	{
		int N = GetInt();
		int M = GetInt();
		int[] A = new int[M];
		int[] B = new int[M];		
		int[] deg = new int[N + 1];
		var adj = new List<int>[N + 1];
		for(int i = 1; i <= N; i++)
			adj[i] = new List<int>();

		for(int i = 0; i < M; i++)
		{
			A[i] = GetInt();
			B[i] = GetInt();
			adj[A[i]].Add(B[i]);
			adj[B[i]].Add(A[i]);
			deg[A[i]]++;
			deg[B[i]]++;
		}

		if(M % 2 == 1)
		{
			Console.WriteLine(-1);
			return;
		}

		int s = 1;
		for(int i = 1; i <= N; i++)
		{
			if(deg[i] % 2 == 0)
				continue;

			s = i;
			break;
		}

		var used = new HashSet<Tuple<int, int>>();
		List<int> trail = new List<int>();
		dfs(s, adj, used, trail);

		var sb = new StringBuilder();
		int prev = trail[0];
		for(int i = 1; i < trail.Count; i++)
		{
			if(i % 2 == 0)
				sb.AppendFormat($"{prev} {trail[i]}\n");
			else
				sb.AppendFormat($"{trail[i]} {prev}\n");

			prev = trail[i];
		}

		Console.Write(sb);
	}

	private static void dfs(
		int v, List<int>[] adj, HashSet<Tuple<int, int>> used, List<int> trail)
	{
		foreach(int u in adj[v])
		{
			if(used.Contains(Tuple.Create(v, u)) ||
			   used.Contains(Tuple.Create(u, v)))
			   continue;

			used.Add(Tuple.Create(v, u));
			used.Add(Tuple.Create(u, v));
			dfs(u, adj, used, trail);
		}
		trail.Add(v);
	}
}


