using System;
using System.Linq;
using System.Collections.Generic;
using System.Text;
using static System.Console;
using static System.Math;

class Program
{
    static void Main(string[] args)
    {
        int[] NM = ReadLineParseIntArray();
        int N = NM[0];
        int M = NM[1];
        if (M % 2 == 1)
        {
            WriteLine(-1);
            return;
        }

        List<int>[] Edges = new List<int>[N];
        for (int i = 0; i < N; i++)
            Edges[i] = new List<int>();

        bool[] isDecided = new bool[N];
        bool[] isOdd = new bool[N];
        for(int i = 0; i < M; i++)
        {
            int[] AB = ReadLineParseIntArray();
            Edges[AB[0] - 1].Add(AB[1] - 1);
            Edges[AB[1] - 1].Add(AB[0] - 1);
        }

        Queue<int> q = new Queue<int>();
        Queue<Tuple<int, int>> ans = new Queue<Tuple<int, int>>();

        for (int i = 0; i < N; i++)
            if (Edges[i].Count == 1)
            {
                q.Enqueue(i);
                isDecided[i] = true;
            }

        int count = 0;

        while(count != M)
        {
            int v = 0;
            if(q.Count != 0)
                v = q.Dequeue();
            else
                for(int i = 0; i < N; i++)
                    if(!isDecided[i])
                    {
                        v = i;
                        break;
                    }
            int w = 0;
            if(Edges[v].Count != 0)
                w = Edges[v][0];
            if (isOdd[v])
            {
                ans.Enqueue(new Tuple<int, int>(v, w));
                isOdd[v] = false;
            }
            else
            {
                ans.Enqueue(new Tuple<int, int>(w, v));
                isOdd[w] = isOdd[w] == false;
            }
            Edges[v].Remove(w);
            Edges[w].Remove(v);

            if (Edges[v].Count == 1)
            {
                q.Enqueue(v);
                isDecided[v] = true;
            }

            if (Edges[w].Count == 1)
            {
                q.Enqueue(w);
                isDecided[w] = true;
            }
            count++;
        }

        foreach(var tuple in ans)
        {
            WriteLine($"{tuple.Item1 + 1} {tuple.Item2 + 1}");
        }
    }
    static int ReadLineParseInt() => int.Parse(ReadLine());
    static int[] ReadLineParseIntArray() => ReadLine().Split(' ').Select(int.Parse).ToArray();
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
static string[] input = Console.ReadLine().Split(' ');
static int n = int.Parse(input[0]);
static int m = int.Parse(input[1]);
static List<int>[] nextList = new List<int>[n];
static List<int>[] childrenList = new List<int>[n];
static List<int[]> selectTreeEdges;
static int[] lookedVertexes = new int[n];//木の逆走を防ぐ
static int[] outDegree = new int[n];
static List<int> eulerTourList = new List<int>();
static int[] depths = new int[n];//木の深さ

	static void Main()
	{
  if(m % 2 == 0)
  {
    for(int i = 0; i < n; i++)
    {
      nextList[i] = new List<int>();
      childrenList[i] = new List<int>();
    }
    List<int[]> edges = new List<int[]>();

    for(int i = 0; i < m; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
      nextList[nums[0]-1].Add(nums[1]-1);
      nextList[nums[1]-1].Add(nums[0]-1);
      edges.Add(new int[2]{nums[0]-1, nums[1]-1});
    }

    SelectTreeEdges(0);
    List<int[]> notSelectEdges = NotSelectEdges(edges, selectTreeEdges);

    for(int i = 0; i < notSelectEdges.Count(); i++)
    {
      outDegree[notSelectEdges[i][0]]++;
      Console.WriteLine((notSelectEdges[i][0]+1)+" "+(notSelectEdges[i][1]+1));
    }

    for(int i = 0; i < n; i++)
    {
      lookedVertexes[i] = 0;
      nextList[i].Clear();
    }
    for(int i = 0; i < n-1; i++)
    {
      nextList[selectTreeEdges[i][0]].Add(selectTreeEdges[i][1]);
      nextList[selectTreeEdges[i][1]].Add(selectTreeEdges[i][0]);
    }

    MakeEulerTour(0);
    for(int i = 0; i < n; i++) lookedVertexes[i] = 0;
    MakeChildrenList(0);
    SearchDepths(0,0);

    for(int i = 1; i < eulerTourList.Count(); i++)
    {
      if(depths[eulerTourList[i-1]] > depths[eulerTourList[i]])
      {
        if(outDegree[eulerTourList[i-1]] % 2 == 1)
        {
          Console.WriteLine((eulerTourList[i-1]+1)+" "+(eulerTourList[i]+1));
        }else
        {
          Console.WriteLine((eulerTourList[i]+1)+" "+(eulerTourList[i-1]+1));
          outDegree[eulerTourList[i]]++;
        }
      }
    }
  }else
  {
    Console.WriteLine(-1);
  }

	}

  static void SelectTreeEdges(int rootVertex)
  {//連結グラフのnextListから、0-indexで根をrootVertexとする木の辺をO(頂点数)で1つ返す
    selectTreeEdges = new List<int[]>();
    for(int i = 0; i < n; i++) lookedVertexes[i] = 0;
    SelectTreeEdgesSub(rootVertex);
  }

  static void SelectTreeEdgesSub(int rootVertex)
  {
    lookedVertexes[rootVertex] = 1;
    for(int i = 0; i < nextList[rootVertex].Count(); i++)
    {
      if(lookedVertexes[nextList[rootVertex][i]] == 0)
      {
        if(rootVertex < nextList[rootVertex][i])
          selectTreeEdges.Add(new int[2]{rootVertex, nextList[rootVertex][i]});
        else selectTreeEdges.Add(new int[2]{nextList[rootVertex][i], rootVertex});

        SelectTreeEdgesSub(nextList[rootVertex][i]);
