    class B
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);
            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            int[] nm = ReadInts();
            int n = nm[0];
            int m = nm[1];

            HashSet<int>[] graph = new HashSet<int>[n];
            for (int i = 0; i < n; i++) graph[i] = new HashSet<int>();

            for(int i = 0; i < m; i++)
            {
                int[] cd = ReadInts();
                int c = cd[0] - 1;
                int d = cd[1] - 1;
                graph[c].Add(d);
                graph[d].Add(c);
            }

            if (m % 2 == 1)
            {
                WriteLine(-1);
                return;
            }

            List<int> leafs = new List<int>();
            for(int i = 0; i < n; i++)
            {
                if (graph[i].Count == 1) leafs.Add(i);
            }

            List<int[]> res = new List<int[]>();
            int[] fromCnts = new int[n];
            for(int i = 0; i < leafs.Count; i++)
            {
                if (graph[leafs[i]].Count == 1)
                {
                    int to = graph[leafs[i]].First();
                    res.Add(new int[2] { to, leafs[i] });
                    fromCnts[to]++;
                    graph[leafs[i]].Remove(to);
                    graph[to].Remove(leafs[i]);
                }
            }

            for(int i = 0; i < n; i++)
            {
                if (graph[i].Count == 0) continue;

                Queue<int> queue = new Queue<int>();
                queue.Enqueue(i);
                while (queue.Count > 0)
                {
                    int now = queue.Dequeue();
                    if (fromCnts[now] % 2 == 1)
                    {
                        int to = graph[now].First();
                        res.Add(new int[2] { i, to });
                        fromCnts[i]++;
                        graph[i].Remove(to);
                        graph[to].Remove(i);
                    }

                    while (graph[i].Count > 0)
                    {
                        int to = graph[i].First();
                        res.Add(new int[2] { to, i });
                        fromCnts[to]++;
                        graph[i].Remove(to);
                        graph[to].Remove(i);
                    }
                }
            }

            // Write output here
            for(int i = 0; i < res.Count; i++)
            {
                WriteLine((res[i][0] + 1) + " " + (res[i][1] + 1));
            }
        }

        private static string Read() { return ReadLine(); }
        private static char[] ReadChars() { return Array.ConvertAll(Read().Split(), a => a[0]); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
