static int m = int.Parse(input[1]);
static List<int>[] nextList = new List<int>[n];
static List<int>[] childrenList = new List<int>[n];
static List<int[]> selectTreeEdges;
static int[] lookedVertexes = new int[n];//木の逆走を防ぐ
static int[] outDegree = new int[n];
static List<int> eulerTourList = new List<int>();
static int[] depths = new int[n];//木の深さ

	static void Main()
	{

  if(m % 2 == 0)
