        while (S.Count > 0)
        {
            var e = S.First();
            var u = e.s.s;
            if (true)//今奇数出ている
            {
                int id = -1;
                foreach (var z in G[u])
                {
                    if (!state[z])
                    {
                        id = z;
                        break;
                    }
                }

                var v = G[u].First();
                if (id != -1) v = id;
                int x = 1;
                if (state[v]) x = 0;
                S.Remove(new data(x, new pair(G[v].Count, v)));
                S.Remove(e);

                SB.AppendLine($"{u + 1} {v + 1}");
                G[v].Remove(u);
                G[u].Remove(v);
                if (G[v].Count > 0)
                {
                    S.Add(new data(x, new pair(G[v].Count, v)));
                }
                if (G[u].Count > 0)
                {
                    S.Add(new data(state[u] ? 1 : 0, new pair(G[u].Count, u)));
                }
                state[u] = !state[u];
            }
            else//今偶数
            {
                int id = -1;
                foreach (var z in G[u])
                {
                    if (state[z])
                    {
                        id = z;
                        break;
                    }
                }
                var v = G[u].First();
                int x = 1;
                if (state[v]) x = 0;
                S.Remove(new data(x, new pair(G[v].Count, v)));
                S.Remove(e);

                SB.AppendLine($"{v + 1} {u + 1}");
                G[v].Remove(u);
                G[u].Remove(v);
                state[v] = !state[v];
                if (G[v].Count > 0)
                {
                    x = 1;
                    if (state[v]) x = 0;
                    S.Add(new data(x, new pair(G[v].Count, v)));
                }
                if (G[u].Count > 0)
                {
                    S.Add(new data(1, new pair(G[u].Count, u)));
                }

            }
        }
        for (int i = 0; i < N; i++)
        {
            if (state[i])
            {
                WriteLine("-1");
                return;
            }
        }

        Write(SB);
    }

