class Solver
{
    Scanner sc = new Scanner();
    //
    int[] ct;bool[] use;
    Pi[] ms;
    List<Edge>[] edge, tr;
    public void Solve()
    {
        int N, M;
        sc.Make(out N, out M);
        if (M % 2 == 1) Fail(-1);
        ms = new Pi[N];
        for (var i = 0; i < M; i++)
            ms[i] = new Pi(sc.Next<int>() - 1, sc.Next<int>() - 1);
        var uf = new UnionFind(N);
        edge = Create(N, () => new List<Edge>());
        tr = Create(N, () => new List<Edge>());
        ct = new int[N];use = new bool[N];
        for (var i = 0; i < M; i++)
        {
            int a, b;
            ms[i].Tie(out a, out b);
            if (uf.Union(a, b))
            { tr[a].Add(new Edge(b, i)); tr[b].Add(new Edge(a, i)); }
            edge[a].Add(new Edge(b, i)); edge[b].Add(new Edge(a, i));
            ct[a]++;
        }
        dfs(0, -1);

        Console.WriteLine(string.Join("\n", ms.Select(v=> { ++v.v1;++v.v2; return v.ToString(); })));
    }
    void dfs(int idx, int p)
    {
        foreach (var e in tr[idx])
            if (e.to != p) dfs(e.to, idx);
        foreach (var e in edge[idx])
            if (ct[idx] % 2 == 0) use[e.idx] = true;
            else if (!use[e.idx])
            {
                swap(ref ms[e.idx].v1, ref ms[e.idx].v2);
                if (ms[e.idx].v1 == idx)
                { ct[idx]++; ct[ms[e.idx].v2]--; }
                else { ct[idx]--; ct[ms[e.idx].v2]++; }
            }
    }
    struct Edge { public int to, idx;public Edge(int t,int i) { to = t;idx = i; } }
}

public class UnionFind
{
    protected int[] parent;
    public virtual int this[int i] { get { return Find(i); } }
    public UnionFind(int num)
    {
        parent = new int[num];
        for (var i = 0; i < num; i++)
            parent[i] = -1;
    }
    protected int Find(int i)
        => parent[i] < 0 ? i : (parent[i] = Find(parent[i]));
    public int Size(int i)
        => -parent[Find(i)];
    public virtual bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        if (parent[v1] > parent[v2])
            swap(ref v1, ref v2);
        parent[v1] += parent[v2];
        parent[v2] = v1;
        return true;
    }
}
