        sc.Multi(out n, out m);
        edges = new P[m];
        edge = new List<int>[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        cnt = new int[n];
        for (int i = 0; i < m; i++)
        {
            edges[i] = sc.P;
            --edges[i].v1;
            --edges[i].v2;
            edge[edges[i].v1].Add(i);
            edge[edges[i].v2].Add(i);
            cnt[edges[i].v1] ^= 1;
        }
        rev = new bool[m];
        int ret = dfs(0, 0, new bool[n]);
        for (int i = 0; i < n; i++)
        {
            if (cnt[i] != 0) {
                ret = 1;
            }
        }
        if (ret == 1) {
            DBG(-1);
            return;
        }
        for (int i = 0; i < m; i++)
        {
            if (rev[i]) {
                Prt(edges[i].v2 + 1, edges[i].v1 + 1);
            }
            else {
                Prt(edges[i].v1 + 1, edges[i].v2 + 1);
            }
        }
        sw.Flush();
    }
    static P[] edges;
    static List<int>[] edge;
    static int[] cnt;
    static bool[] rev;
    static int dfs(int p, int c, bool[] vis) {
        vis[p] = true;
        c ^= cnt[p];
        foreach (var i in edge[p])
        {
            int nex = edges[i].v1 + edges[i].v2 - p;
            if (vis[nex]) {
                continue;
            }
            if (c == 1) {
                rev[i] = !rev[i];
                c = 0;
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
            c = dfs(nex, c, vis);
            if (c == 1) {
                rev[i] = !rev[i];
                c = 0;
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
        }
        return c;
    }

