class Solver
{
    public void Solve()
    {
        //Solve Code Here
        int N = Cin, M = Cin;
        var tree = new Node[N];
        for (var i = 0; i < tree.Length; i++)
        {
            tree[i] = new Node {Id = i + 1};
        }

        for (int i = 0; i < M; i++)
        {
            int a = Cin, b = Cin;
            tree[a - 1].AddConnection(tree[b - 1]);
        }

        Transform(tree[0]);
        var fromCount = new int[N];
        foreach (var connection in Connection.AllConnections)
        {
            fromCount[connection.From.Id - 1]++;
        }

        int f = 0;
        for (var i = 0; i < N; i++)
        {
            f |= fromCount[i];
        }

        if ((f & 1) != 0)
        {
            Coutln(-1);
            return;
        }

        foreach (var connection in Connection.AllConnections)
        {
            Coutln(connection.From.Id + " " + connection.To.Id);
        }
    }

    //Other Functions Here
    private void Transform(Node node)
    {
        node.Flg1 = true;
        foreach (var connection in node.Connections)
        {
            var other = connection.Other(node);
            if (other.Flg1) continue;
            Transform(other);
        }

        int thisFromCount = 0;
        foreach (var connection in node.Connections)
        {
            if (connection.From == node)
            {
                thisFromCount++;
            }
        }

        thisFromCount &= 1;
        foreach (var connection in node.Connections)
        {
            var other = connection.Other(node);
            if (other.Flg2) continue;
            if (thisFromCount > 0)
            {
                thisFromCount--;
                connection.Swap();
            }
        }

        node.Flg2 = true;
    }
}

