	void Solve()
	{
		var I = G;
		int V = I[0], E = I[1];
		if (E % 2 != 0) { WriteLine(-1); return; }
		var uf = new UnionFindTree(V);
		var g = MakeArray(V, _ => new List<int>());
		for (var i = 0; i < E; i++)
		{
			I = G;
			I[0]--; I[1]--;
			g[I[0]].Add(I[1]);
			g[I[1]].Add(I[0]);
			uf.UniteCategory(I[0], I[1]);
		}
		var rs = MakeArray(V, _ => new List<int>());
		for (var i = 0; i < V; i++) rs[uf.GetRootOf(i)].Add(i);
		var ans = new List<Edge>();
		for (var r = 0; r < V; r++) if (r == uf.GetRootOf(r))
			{
				var deg = 0;
				foreach (var v in rs[r]) deg += g[v].Count;
				deg /= 2;
				if (deg % 2 != 0) { WriteLine(-1); return; }
				var V2 = rs[r].Count;
				var flag = new bool[V2];
				var st = new Stack<Pair>();
				var par = new int[V2];
				var d = new int[V2];
				var used = new HashSet<Edge>();
				st.Push(new Pair(-1, r, 0));
				while (st.Count > 0)
				{
					var pair = st.Pop();
					if (flag[pair.V]) continue;
					flag[pair.V] = true;
					par[pair.V] = pair.P;
					d[pair.V] = pair.D;
					if (pair.P >= 0) used.Add(new Edge(pair.P, pair.V));
					foreach (var u in g[pair.V]) if (!flag[u]) st.Push(new Pair(pair.V, u, pair.D + 1));
				}
				var parity = new int[V2];
				foreach (var u in rs[r])
					foreach (var v in g[u])
					{
						if (u > v) continue;
						var e = new Edge(u, v);
						if (!used.Contains(e))
						{
							ans.Add(e);
							parity[u]++;
						}
					}
				rs[r].Sort((u, v) => d[v].CompareTo(d[u]));
				foreach (var u in rs[r])
				{
					if (u == r) continue;
					if (parity[u] % 2 == 0)
					{
						ans.Add(new Edge(par[u], u));
						parity[par[u]]++;
					}
					else
					{
						ans.Add(new Edge(u, par[u]));
						parity[u]++;
					}
				}
			}
		foreach (var e in ans) WriteLine($"{e.S + 1} {e.T + 1}");
	}
}
