    static bool[] rev;
    static int dfs(int p, int c, bool[] vis) {
        vis[p] = true;
        c ^= cnt[p];
        foreach (var i in edge[p])
        {
            int nex = edges[i].v1 + edges[i].v2 - p;
            if (vis[nex]) {
                continue;
            }
            if (c == 1) {
                rev[i] = !rev[i];
                c = 0;
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
            c = dfs(nex, c, vis);
            if (c == 1) {
                rev[i] = !rev[i];
                c = 0;
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
        }
        return c;
    }

