        public static void Solve(Input input)
        {
            var n = input.NextInt();
            var m = input.NextInt();

            // V2が辺の状態を表すことにする
            // 0: 未定、1: 吸い込み、2: 吐き出し
            var connection = Enumerable.Range(0, n)
                .Select(_ => new Dictionary<int, int>())
                .ToArray();

            if (m % 2 != 0)
            {
                Console.WriteLine(-1);
                return;
            }

            for (int i = 0; i < m; i++)
            {
                var a = input.NextInt() - 1;
                var b = input.NextInt() - 1;

                connection[a].Add(b, 0);
                connection[b].Add(a, 0);
            }

            dfs(connection, new bool[n], -1, 0);

            for (int i = 0; i < n; i++)
            {
                var node = connection[i];
                foreach (var e in node.Where(x => x.Value == 2))
                {
                    Console.WriteLine($"{i + 1} {e.Key + 1}");

                }
            }
        }

        static void dfs(Dictionary<int, int>[] connection, bool[] visited, int from, int s)
        {
            if (visited[s])
            {
                return;
            }

            visited[s] = true;

            var keys1 = connection[s].Keys.ToArray();
            foreach (var e in keys1)
            {
                dfs(connection, visited, s, e);
            }

            // 出次数
            var c = connection[s].Count(x => x.Value == 2) % 2;
            var keys = connection[s].Where(x => x.Value == 0).Select(x => x.Key).ToArray();
            for (int i = 0; i < keys.Length; i++)
            {
                var e = keys[i];
                if (c > 0)
                {
                    // 吐き出しとする
                    connection[s][e] = 2;
                    connection[e][s] = 1;
                    c--;
                }
                else
                {
                    // 吸い出しとする
                    connection[s][e] = 1;
                    connection[e][s] = 2;
                }

            }
        }

        /// <summary>
        /// 値を書き換え可能なTuple（ぐらいのイメージ）
        /// </summary>
        /// <typeparam name="T"></typeparam>
        /// <typeparam name="U"></typeparam>
        public class Pair<T, U> : IComparable<Pair<T, U>>, IEquatable<Pair<T, U>>
            where T : IComparable<T>
            where U : IComparable<U>
        {
            public T V1 { get; set; }
            public U V2 { get; set; }

            public Pair(T v1, U v2)
            {
                this.V1 = v1;
                this.V2 = v2;
            }

            public Pair(Pair<T, U> src)
            {
                this.V1 = src.V1;
                this.V2 = src.V2;
            }

            public int CompareTo(Pair<T, U> other)
            {
                var r = this.V1.CompareTo(other.V1);
                if (r == 0) r = this.V2.CompareTo(other.V2);

                return r;
            }

            public bool Equals(Pair<T, U> other)
            {
                return other != null && this.CompareTo(other) == 0;
            }

            public override string ToString()
            {
                return $"{V1} {V2}";
            }

            public override bool Equals(object obj)
            {
                return Equals(obj as Pair<T, U>);
            }

            public override int GetHashCode()
            {
                var hashCode = 1989511945;
                hashCode = hashCode * -1521134295 + V1.GetHashCode();
                hashCode = hashCode * -1521134295 + V2.GetHashCode();
                return hashCode;
            }

            public static bool operator ==(Pair<T, U> a, Pair<T, U> b)
            {
                if (object.ReferenceEquals(a, null))
                {
                    return object.ReferenceEquals(b, null);
                }

                return a.Equals(b);
            }

            public static bool operator !=(Pair<T, U> a, Pair<T, U> b)
                => !(a == b);
            public static bool operator <(Pair<T, U> a, Pair<T, U> b)
                => a.CompareTo(b) < 0;
            public static bool operator <=(Pair<T, U> a, Pair<T, U> b)
                => a.CompareTo(b) <= 0;
            public static bool operator >(Pair<T, U> a, Pair<T, U> b)
                => a.CompareTo(b) > 0;
            public static bool operator >=(Pair<T, U> a, Pair<T, U> b)
                => a.CompareTo(b) >= 0;
        }

