        for(int i = 0; i < m; i++)
        {
            a = ri - 1; b = ri - 1;
            if (a > b) { t = a; a = b; b = t; }
            v[a].Add(b);
        }
        if (m % 2 == 1) { Write(-1); return; }
        even = new bool[n];
        even[0] = true;
        Think(0);
    }

