                Write($"{v[i][0]+1} {i+1}");
                even[v[i][0]] = !even[v[i][0]];
                v[i].RemoveAt(0);
                foreach (var k in v[i])
                {
                    Write($"{i+1} {k+1}");
                }
                Think(i + 1);
            }
        }
