    //優先度付きキュー（実装はヒープ)
    class PriorityQueue<T>
    {
        private List<HeapNode> heap = new List<HeapNode>();

        public int Count
        {
            get
            {
                return heap.Count;
            }
        }

        public void Enqueue(T item, double priority)
        {
            HeapNode node = new HeapNode(item, priority);
            heap.Add(node);

            int index = heap.Count - 1;

            while (index > 0)
            {
                int indexParent = (index - 1) / 2;
                HeapNode parent = heap[indexParent];
                if (priority > parent.Priority)
                {
                    Swap(index, indexParent);
                    index = indexParent;
                }
                else
                {
                    break;
                }
            }
        }

        public T Dequeue()
        {
            if (heap.Count == 0)
            {
                throw new Exception("No item in priorityQueue");
            }

            T item = heap[0].Node;
            heap[0] = heap[heap.Count - 1];
            heap.RemoveAt(heap.Count - 1);
            if (heap.Count > 0)
            {
                HeapNode node = heap[0];
                int index = 0;
                while (true)
                {
                    int indexL = 2 * index + 1;
                    int indexR = 2 * index + 2;
                    if (indexL >= heap.Count) //子なし(Leaf)
                    {
                        break;
                    }
                    else //子が存在
                    {
                        HeapNode childBetter = heap[indexL];
                        int indexBetter = indexL;
                        if (indexR < heap.Count && heap[indexL].Priority < heap[indexR].Priority)
                        {
                            childBetter = heap[indexR];
                            indexBetter = indexR;
                        }

                        if (node.Priority < childBetter.Priority)
                        {
                            Swap(index, indexBetter);
                            //node = childBetter; 参照なのでスワップで自動的に子を参照してる
                            index = indexBetter;
                        }
                        else
                        {
                            break;
                        }
                    }
                }
            }
            return item;
        }

        public T Peek()
        {
            if (heap.Count == 0)
            {
                throw new Exception("No item in priorityQueue");
            }
            return heap[0].Node;
        }

        private void Swap(int i, int j)
        {
            HeapNode hn = heap[i];
            heap[i] = heap[j];
            heap[j] = hn;
        }


        class HeapNode
        {
            public T Node { get; }
            public double Priority { get; }
            public HeapNode(T item, double priority)
            {
                Node = item;
                Priority = priority;
            }
        }

    }

    class Node
    {
        public HashSet<int> hs = new HashSet<int>();
        public int id;
        public int dn;
        public int Connects { get { return hs.Count; } }
    }


    class B
    {
        static void Main(string[] args)
        {
            int[] a = Console.ReadLine().Split(' ').Select(o => int.Parse(o)).ToArray();
            int N = a[0], M = a[1];


            Dictionary<int, Node> edgeDic = new Dictionary<int, Node>();
            for (int i = 1; i <= N; i++)
            {
                HashSet<int> hs = new HashSet<int>();
                Node n = new Node(); n.hs = hs; n.id = i;
                edgeDic.Add(i, n);
            }

            for (int i = 0; i < M; i++)
            {
                int[] c = Console.ReadLine().Split(' ').Select(o => int.Parse(o)).ToArray();
                int A = c[0], B = c[1];
                edgeDic[A].hs.Add(B); edgeDic[B].hs.Add(A);
            }

            PriorityQueue<Node> pq = new PriorityQueue<Node>();
            foreach (var pair in edgeDic)
            {
                Node n = pair.Value;
                pq.Enqueue(n, -n.hs.Count);
            }


            if (M % 2 == 1)
            {
                Console.WriteLine(-1);
                return;
            }
            else
            {

                List<int[]> dlist = new List<int[]>();

                while (pq.Count>0)
                {
                    Node n=pq.Dequeue();
                    if (n.Connects == 0) continue;
                    int node = n.id;
                    int op = n.hs.ElementAt(0);
                    Node nop = edgeDic[op];

                    int[] d;
                    if (n.dn % 2 == 0)
                    {
                        d = new int[] { op, node };
                        nop.dn++;
                    }
                    else
                    {
                        d = new int[] { node, op };
                        n.dn++;
                    }

                    dlist.Add(d);
                    n.hs.Remove(op);
                    nop.hs.Remove(node);
                    if (n.Connects > 0) pq.Enqueue(n, -n.Connects);
                    if (nop.Connects > 0) pq.Enqueue(nop, -nop.Connects);
                }

                foreach (int[] arr in dlist)
                {
                    Console.WriteLine(arr[0] + " " + arr[1]);
                }
            }
        }

    }
}

