                    int node = nse.id;


                    int op = nse.hs.ElementAt(0);
                    Node nop = edgeDic[op];

                    int[] d;
                    if (nse.dn % 2 == 0)
                    {
                        d = new int[] { op, node };
                        nop.dn++;
                    }
                    else
                    {
                        d = new int[] { node, op };
                        nse.dn++;
                    }

                    dlist.Add(d);
                    nse.hs.Remove(op);
                    nop.hs.Remove(node);
                    if(nse.dn % 2 == 1)
                    if (nse.Connects > 0) pq.Enqueue(nse, nse.Priority);
                    if (nop.Connects > 0) pq.Enqueue(nop, nop.Priority);
