public class Solver
{
	private int N;
	private int M;
	private int[] A;
	private int[] B;
	private int[] deg;
	private HashSet<Tuple<int, int>> used;
	private List<int>[] adj;
	private StringBuilder ans = new StringBuilder();

	public Solver()
	{
		N = GetInt();
		M = GetInt();
		A = new int[M];
		B = new int[M];
		deg = new int[N + 1];
		used = new HashSet<Tuple<int, int>>();
		adj = new List<int>[N + 1];
		for(int i = 1; i <= N; i++)
			adj[i] = new List<int>();

		for(int i = 0; i < M; i++)
		{
			A[i] = GetInt();
			B[i] = GetInt();
			adj[A[i]].Add(B[i]);
			adj[B[i]].Add(A[i]);
		}
	}

	public void Solve()
	{
		if(M % 2 == 1)
		{
			Console.WriteLine(-1);
			return;
		}

		List<int> order = bfs();
		for(int i = 0; i < N; i++)
		{
			int v = order[i];
			foreach(int u in adj[v])
			{				
				if(used.Contains(Tuple.Create(v, u)) || 
				   used.Contains(Tuple.Create(u, v)))
					continue;

				if(deg[v] % 2 == 1)
				{
					ans.AppendFormat($"{v} {u}\n");
					deg[v]++;
				}
				else
				{
					ans.AppendFormat($"{u} {v}\n");
					deg[u]++;
				}

				used.Add(Tuple.Create(v, u));
				used.Add(Tuple.Create(u, v));
			}
		}

		Console.Write(ans);
	}

	private List<int> bfs()
	{
		var order = new List<int>(N);

		var isInMST = new HashSet<Tuple<int, int>>();
		bool[] visited = new bool[N + 1];	
		var queue = new Queue<int>();		
		visited[1] = true;
		order.Add(1);
		queue.Enqueue(1);
		while(queue.Count > 0)
		{
			int v = queue.Dequeue();
			foreach(int u in adj[v])
			{
				if(used.Contains(Tuple.Create(v, u)) || 
				   used.Contains(Tuple.Create(u, v)) ||
				   isInMST.Contains(Tuple.Create(v, u)) || 
				   isInMST.Contains(Tuple.Create(u, v)))
					continue;

				if(visited[u])
				{
					ans.AppendFormat($"{v} {u}\n");
					used.Add(Tuple.Create(v, u));
					used.Add(Tuple.Create(u, v));
					deg[v]++;
				}
				else
				{
					visited[u] = true;
					order.Add(u);
					queue.Enqueue(u);
					isInMST.Add(Tuple.Create(v, u));
					isInMST.Add(Tuple.Create(u, v));
				}
			}
		}

		order.Reverse();
		return order;
	}
}


