        for (int i = 1; i <= N; i++) if (G[i].Count() == 1) Q.Enqueue(i);

        while (Q.Count() != 0)
        {
            int x = Q.Dequeue();
            int y = G[x].First();
            G[y].Remove(x);
            G[x].Remove(y);
            Console.WriteLine(y + " " + x);
            ok[y] += 1;
