        var G = new HashSet<int>[N];
        for (int i = 0; i < G.Length; i++)
        {
            G[i] = new HashSet<int>();
        }

        for (int i = 0; i < M; i++)
        {
            A[i] = cin.nextint - 1;
            B[i] = cin.nextint - 1;
            G[A[i]].Add(B[i]);
            G[B[i]].Add(A[i]);
        }
