using System.IO;
using System.Reflection;
using static System.Math;
using System.Numerics;
static class Program{
	const int mod=(int)1e9+7;
	static List<int>[] li;
	static List<string> la;
	static bool[] b;
	static int[][] h;
	static StringBuilder sb=new StringBuilder();
	static void Main(){
		Sc sc=new Sc();
		int[] s=sc.Ia;
		int n=s[0],m=s[1];
		li=new List<int>[n+1];
		b=new bool[n+1];
		h=new int[n+1][];
		la=new List<string>();
		for(int i=1;i<=n;i++){
			li[i]=new List<int>();
			h[i]=new int[2];
		}
		for(int i=0;i<m;i++){
			int[] e=sc.Ia;
			li[e[0]].Add(e[1]);
			li[e[1]].Add(e[0]);
		}
		int p=0;
		var pq=new Pq<Mo<int>>(32,true);
		for(int i=1;i<=n;i++){
			pq.Push(new Mo<int>(li[i].Count,i));
		}
		int ans=0;
		if(s[1]%2==1){ans=-1;}
		while(pq.cnt>0&&p<s[0]){
			var e=pq.Top;
			pq.Pop();
			if(b[e.d]){continue;}
			p++;
			b[e.d]=true;
			ans+=e.n;
			for(int i=0;i<li[e.d].Count;i++){
				if(!b[li[e.d][i]]){
					if(h[e.d][0]+h[e.d][1]==li[e.d].Count-1){
						if(h[e.d][1]%2==1){
							h[e.d][1]++;
							h[li[e.d][i]][0]++;
							sb.Append(li[e.d][i]+" "+e.d+"\n");
						}
						else{
							h[e.d][0]++;
							h[li[e.d][i]][1]++;
							sb.Append(e.d+" "+li[e.d][i]+"\n");
						}
					}
					else{
						h[e.d][0]++;
						h[li[e.d][i]][1]++;
						sb.Append(e.d+" "+li[e.d][i]+"\n");
					}
					pq.Push(new Mo<int>(li[li[e.d][i]].Count-(h[li[e.d][i]][0]+h[li[e.d][i]][1]),li[e.d][i]));
				}
			}
		}
		for(int i=1;i<=n;i++){
			if(h[i][0]%2==1){ans=-1;}
		}
		if(ans==-1){Console.WriteLine("{0}",ans);}
		else{Console.Write(sb);}
	}
}
