public class Program
{
    private int N, M;
    private List<int>[] Edge;
    private bool[] Cnt;
    private StringBuilder Sb;
    private bool[] B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        if (M % 2 == 1)
        {
            Console.WriteLine(-1);
            return;
        }

        Edge = new List<int>[N];
        Cnt = new bool[N];

        for (int i = 0; i < N; i++)
        {
            Edge[i] = new List<int>();
        }

        for (int i = 0; i < M; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            Edge[a].Add(b);
            Edge[b].Add(a);
        }
        B = new bool[N];
        Sb = new StringBuilder();
        Search(0, -1);
        Console.Write(Sb.ToString());
    }


    private void Search(int i, int parent)
    {
        B[i] = true;
        foreach (var j in Edge[i])
        {
            if (B[j])
            {
                if (j != parent && i < j)
                {
                    Cnt[i] = !Cnt[i];
                    Sb.AppendLine($"{i + 1} {j + 1}");
                }
            }
            else
            {
                Search(j, i);
            }
        }

        if (parent != -1)
        {
            if (Cnt[i])
            {
                Sb.AppendLine($"{i + 1} {parent + 1}");
                Cnt[i] = false;
            }
            else
            {
                Sb.AppendLine($"{parent + 1} {i + 1}");
                Cnt[parent] = !Cnt[parent];
            }
        }
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

