using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;
using System.Security.Principal;
using System.Text;


struct E
{
    public int A, B;

    public E(int a, int b)
    {
        if (a > b)
        {
            int t = a;
            a = b;
            b = t;
        }

        A = a;
        B = b;
    }
}

public class Program
{
    private int N, M;
    private HashSet<int>[] EdgeAr;
    private HashSet<E> Edges;

    private int[] Cnt;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();

        Cnt = new int[N];
        EdgeAr = new HashSet<int>[N];
        for (int i = 0; i < N; i++)
        {
            EdgeAr[i] = new HashSet<int>();
        }

        Edges = new HashSet<E>();
        for (int i = 0; i < M; i++)
        {
            int a = sc.NextInt()-1;
            int b = sc.NextInt()-1;
            Cnt[a]++;
            Cnt[b]++;
            EdgeAr[a].Add(b);
            EdgeAr[b].Add(a);
            Edges.Add(new E(a, b));
        }

        // 出てる辺が奇数本
        HashSet<int> oddNode = new HashSet<int>();

        for (int i = 0; i < N; i++)
        {
            if (Cnt[i] % 2 == 1)
            {
                oddNode.Add(i);
            }
        }

        StringBuilder sb = new StringBuilder();

        while (Edges.Count > 0)
        {
            if (oddNode.Count == 0)
            { 
                // 適当に選ぶ
                E e1 = Edges.ToArray()[0];
                int a = e1.A;
                int b = e1.B;
                // a <- b -> c

                Edges.Remove(e1);
                EdgeAr[a].Remove(b);
                EdgeAr[b].Remove(a);
                int c = EdgeAr[b].ToArray()[0];
                Edges.Remove(new E(b, c));
                EdgeAr[b].Remove(c);
                EdgeAr[c].Remove(b);
                oddNode.Add(a);
                oddNode.Add(c);
                sb.AppendLine($"{b + 1} {a + 1}");
                sb.AppendLine($"{b + 1} {c + 1}");
            }
            else
            {
                int a = oddNode.ToArray()[0];
                int b = EdgeAr[a].ToArray()[0];
                Edges.Remove(new E(a,b));
                EdgeAr[a].Remove(b);
                EdgeAr[b].Remove(a);
                if (EdgeAr[b].Count <= 0)
                {
                    Console.WriteLine(-1);
                    return;
                }
                // a <- b -> c
                int c = EdgeAr[b].ToArray()[0];
                oddNode.Remove(a);
                if (oddNode.Contains(c))
                {
                    oddNode.Remove(c);
                }
                else
                {
                    oddNode.Add(c);
                }
                EdgeAr[b].Remove(c);
                EdgeAr[c].Remove(b);
                Edges.Remove(new E(b, c));
                sb.AppendLine($"{b + 1} {a + 1}");
                sb.AppendLine($"{b + 1} {c + 1}");
            }
        }
        Console.Write(sb.ToString());
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

