        public IEnumerable<string> Solve()
        {
            n = ScanInt;
            m = ScanInt;
            if (m % 2 == 1)
            {
                yield return "-1";
                yield break;
            }

            es = Loop(n + 1).ToDictionary(x => x, x => new HashSet<int>());
            a = new List<int>();
            b = new List<int>();
            foreach (var x in Loop(m))
            {
                var aa = ScanInt;
                var bb = ScanInt;
                a.Add(aa);
                b.Add(bb);

                es[aa].Add(bb);
                es[bb].Add(aa);
            }

            var oddTos = new HashSet<int>(es.Where(x => x.Value.Count % 2 == 1).Select(x => x.Key));
            if (oddTos.Count != 0 && oddTos.Count != 2)
            {
                yield return "-1";
                yield break;
            }

            var oddFroms = new HashSet<int>();
            var usedCount = 0;

            while (usedCount < m)
            {
                if (oddFroms.Any())
                {
                    var from = oddFroms.First();
                    oddFroms.Remove(from);

                    var to = es[from].FirstOrDefault(x => es[from].Contains(x) && oddTos.Contains(x));
                    if (to == 0)
                    {
                        to = es[from].First();
                    }

                    yield return from.ToString() + " " + to.ToString();

                    if (oddTos.Contains(to))
                        oddTos.Remove(to);
                    else
                        oddTos.Add(to);

                    es[to].Remove(from);
                    es[from].Remove(to);
                }
                else if (oddTos.Any())
                {
                    var to = oddTos.First();
                    oddTos.Remove(to);

                    var from = es[to].First();

                    yield return from.ToString() + " " + to.ToString();

                    oddFroms.Add(from);

                    es[to].Remove(from);
                    es[from].Remove(to);
                }
                else
                {
                    var to = es.First(x => x.Value.Any()).Key;
                    var from = es[to].First();

                    yield return from.ToString() + " " + to.ToString();

                    oddTos.Add(to);
                    oddFroms.Add(from);

                    es[to].Remove(from);
                    es[from].Remove(to);
                }

                usedCount++;
            }



        }
    }

