  {//連結グラフのnextListから、0-indexで根をrootVertexとする木の辺をO(頂点数)で1つ返す
    selectTreeEdges = new List<int[]>();
    for(int i = 0; i < n; i++) lookedVertexes[i] = 0;
    SelectTreeEdgesSub(rootVertex);
  }

  static void SelectTreeEdgesSub(int rootVertex)
  {
    lookedVertexes[rootVertex] = 1;
    for(int i = 0; i < nextList[rootVertex].Count(); i++)
    {
      if(lookedVertexes[nextList[rootVertex][i]] == 0)
      {
        if(rootVertex < nextList[rootVertex][i])
          selectTreeEdges.Add(new int[2]{rootVertex, nextList[rootVertex][i]});
        else selectTreeEdges.Add(new int[2]{nextList[rootVertex][i], rootVertex});

        SelectTreeEdgesSub(nextList[rootVertex][i]);
      }
    }
  }

  static void MakeEulerTour(int vertexNum)
  {//0-indexで根の頂点番号から始めて、木のオイラーツアーをO(頂点数)で生成
    eulerTourList.Clear();

