  static void EulerTour(int vertexNum)
  {
    eulerTourList.Add(vertexNum);
    lookedVertexes[vertexNum] = 1;//木の逆走を防ぐ

    for(int i = 0; i < nextList[vertexNum].Count(); i++)
    {
      if(lookedVertexes[nextList[vertexNum][i]] == 0)//木の逆走を防ぐ
      {
        EulerTour(nextList[vertexNum][i]);
        eulerTourList.Add(vertexNum);
      }
    }
  }

  static List<int[]> NotSelectEdges(List<int[]> edges, List<int[]> removes)
  {//edgesからremovesを除いた辺をO(辺数)で返す
    List<int[]> answers = new List<int[]>();

    for(int i = 0; i < edges.Count(); i++)
    {
      if(edges[i][0] > edges[i][1])
      {
        int swapMemo = edges[i][0];
        edges[i][0] = edges[i][1];
        edges[i][1] = swapMemo;
      }
    }
    /*
    for(int i = 0; i < removes.Count(); i++)
    {
      if(removes[i][0] > removes[i][1])
      {
        int swapMemo = removes[i][0];
        removes[i][0] = removes[i][1];
        removes[i][1] = swapMemo;
      }
    }
    */
    var sorted = edges.OrderBy(a => a[0]).ThenBy(a => a[1]).ToList();
    var sortedSub = removes.OrderBy(a => a[0]).ThenBy(a => a[1]).ToList();

    int edgeMemo = 0;
    for(int i = 0; i < edges.Count(); i++)
    {
      while((sorted[i][0] > sortedSub[edgeMemo][0])
        || (sorted[i][0] == sortedSub[edgeMemo][0] && sorted[i][1] > sortedSub[edgeMemo][1]))
      {
        if(edgeMemo == removes.Count()-1) break;
        else edgeMemo++;
      }

      if(sorted[i][0] != sortedSub[edgeMemo][0] || sorted[i][1] != sortedSub[edgeMemo][1])
      {
        answers.Add(new int[2]{sorted[i][0], sorted[i][1]});
      }
    }

    return answers;
  }

  static void MakeChildrenList(int rootNum)
  {//nextListからchildrenListを、引数を0-indexの根の番号としてO(頂点数)で作る
    lookedVertexes[rootNum]++;//木の逆走を防ぐ
    for(int i = 0; i < nextList[rootNum].Count(); i++)
    {
      if(lookedVertexes[nextList[rootNum][i]] == 0)
      {
        childrenList[rootNum].Add(nextList[rootNum][i]);
        MakeChildrenList(nextList[rootNum][i]);
      }
    }
  }

  static void SearchDepths(int vertexNum, int depth)
  {//頂点数nとchildrenListから、引数の頂点の深さ及び、その子の深さをO(頂点数)で設定
    depths[vertexNum] = depth;//深さを設定

    for(int i = 0; i < childrenList[vertexNum].Count; i++)
    {
      SearchDepths(childrenList[vertexNum][i],depth+1);//子の深さを設定
    }
  }

