        static void Method(string[] args)
        {
            int[] nm = ReadInts();
            int n = nm[0];
            int m = nm[1];

            HashSet<int>[] graph = new HashSet<int>[n];
            for (int i = 0; i < n; i++) graph[i] = new HashSet<int>();

            for(int i = 0; i < m; i++)
            {
                int[] cd = ReadInts();
                int c = cd[0] - 1;
                int d = cd[1] - 1;
                graph[c].Add(d);
                graph[d].Add(c);
            }

            if (m % 2 == 1)
            {
                WriteLine(-1);
                return;
            }

            PriorityQueue<int> queue = new PriorityQueue<int>();
            for(int i = 0; i < n; i++)
            {
                queue.Enqueue(graph[i].Count, i);
            }

            List<int[]> res = new List<int[]>();
            int[] fromCnts = new int[n];
            while (queue.Count > 0)
            {
                var pair = queue.Dequeue();
                int now = pair.Value;
                if (graph[now].Count == 0) continue;

                int remain = 0;
                if (fromCnts[now] % 2 == 0)
                {
                    if (graph[now].Count % 2 == 0) remain = graph[now].Count;
                    else remain = graph[now].Count - 1;
                }
                else
                {
                    if (graph[now].Count % 2 == 0) remain = graph[now].Count - 1;
                    else remain = graph[now].Count;
                }

                for(int i = 0; i < remain; i++)
                {
                    int to = graph[now].First();
                    res.Add(new int[2] { now, to });
                    fromCnts[now]++;
                    graph[now].Remove(to);
                    graph[to].Remove(now);
                }

                if (graph[now].Count > 0)
                {
                    int to = graph[now].First();
                    res.Add(new int[2] { to, now });
                    fromCnts[to]++;
                    graph[now].Remove(to);
                    graph[to].Remove(now);
                }
            }

            // Write output here
            for(int i = 0; i < res.Count; i++)
            {
                WriteLine((res[i][0] + 1) + " " + (res[i][1] + 1));
            }
        }

        class PriorityQueue<T>
        {
            private readonly List<KeyValuePair<long, T>> list;

            public int Count { get; private set; }

            public PriorityQueue()
            {
                list = new List<KeyValuePair<long, T>>();
                Count = 0;
            }

            private void Add(KeyValuePair<long, T> pair)
            {
                if (Count == list.Count)
                {
                    list.Add(pair);
                }
                else
                {
                    list[Count] = pair;
                }
                Count++;
            }

            private void Swap(int a, int b)
            {
                KeyValuePair<long, T> tmp = list[a];
                list[a] = list[b];
                list[b] = tmp;
            }

            public void Enqueue(long key, T value)
            {
                Add(new KeyValuePair<long, T>(key, value));
                int c = Count - 1;
                while (c > 0)
                {
                    int p = (c - 1) / 2;
                    if (list[c].Key >= list[p].Key) break;

                    Swap(p, c);
                    c = p;
                }
            }

            public KeyValuePair<long, T> Top()
            {
                return list[0];
            }

            public KeyValuePair<long, T> Dequeue()
            {
                KeyValuePair<long, T> pair = list[0];
                Count--;
                if (Count == 0) return pair;

                list[0] = list[Count];
                int p = 0;
                while (true)
                {
                    int c1 = p * 2 + 1;
                    int c2 = p * 2 + 2;
                    if (c1 >= Count) break;

                    int c = (c2 >= Count || list[c1].Key < list[c2].Key)
                        ? c1 : c2;
                    if (list[c].Key >= list[p].Key) break;

                    Swap(p, c);
                    p = c;
                }
                return pair;
            }
        }

