        var SB = new SB();
        while (S.Count > 0)
        {
            var e = S.First();
            var u = e.s;
            if (state[u])//今奇数出ている
            {
                var v = G[u].First();
                S.Remove(new pair(G[v].Count, v));
                S.Remove(e);

                SB.AppendLine($"{u + 1} {v + 1}");
                G[v].Remove(u);
                G[u].Remove(v);
                if (G[v].Count > 0)
                {
                    S.Add(new pair(G[v].Count, v));
                }
                if (G[u].Count > 0)
                {
                    S.Add(new pair(G[u].Count, u));
                }
                state[u] = false;
            }
            else//今偶数
            {
                int id = -1;
                foreach (var z in G[u])
                {
                    if (state[z])
                    {
                        id = z;
                        break;
                    }
                }
                var v = G[u].First();
                if (id != -1) v = id;
                S.Remove(new pair(G[v].Count, v));
                S.Remove(e);

                SB.AppendLine($"{v + 1} {u + 1}");
                G[v].Remove(u);
                G[u].Remove(v);
                if (G[v].Count > 0)
                {
                    S.Add(new pair(G[v].Count, v));
                }
                if (G[u].Count > 0)
                {
                    S.Add(new pair(G[u].Count, u));
                }
                state[v] = !state[v];
            }
        }
        for (int i = 0; i < N; i++)
        {
            if (state[i])
            {
                WriteLine("-1");
                return;
            }
        }

        Write(SB);
    }

