        {
            if (rev[i]) {
                Prt(edges[i].v2 + 1, edges[i].v1 + 1);
            }
            else {
                Prt(edges[i].v1 + 1, edges[i].v2 + 1);
            }
        }
        sw.Flush();
    }
    static P[] edges;
    static List<int>[] edge;
    static int[] cnt;
    static bool[] rev;
    static int dfs(int p, int c, bool[] vis) {
        vis[p] = true;
        c ^= cnt[p];
        foreach (var i in edge[p])
        {
            int nex = edges[i].v1 + edges[i].v2 - p;
            if (vis[nex]) {
                continue;
            }
            if (c == 1) {
                rev[i] = true;
                c = 0;
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
            c = dfs(nex, c, vis);
        }
        return c;
    }

