                ret = 1;
            }
        }
        if (ret == 1) {
            DBG(-1);
            return;
        }
        for (int i = 0; i < m; i++)
        {
            if (rev[i]) {
                Prt(edges[i].v2 + 1, edges[i].v1 + 1);
            }
            else {
                Prt(edges[i].v1 + 1, edges[i].v2 + 1);
            }
        }
        sw.Flush();
    }
    static P[] edges;
    static List<int>[] edge;
    static int[] cnt;
    static bool[] rev;
    static void dfs(int p, bool[] vis) {
        vis[p] = true;
        foreach (var i in edge[p])
        {
            int nex = edges[i].v1 + edges[i].v2 - p;
            if (vis[nex]) {
                continue;
            }
            if (cnt[p] == 1) {
                rev[i] = !rev[i];
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
            dfs(nex, vis);
            if (cnt[nex] == 1) {
                rev[i] = !rev[i];
                cnt[p] ^= 1;
                cnt[nex] ^= 1;
            }
        }
    }

    static void DBG(string a) => Console.WriteLine(a);
    static void DBG<T>(IEnumerable<T> a) => DBG(string.Join(" ", a));
