      edgesSub[i] = new int[2];
      edgesSub[i][0] = edges[i,0];
      edgesSub[i][1] = edges[i,1];
    }
    for(int i = 0; i < y; i++)
    {
      removesSub[i] = new int[2];
      removesSub[i][0] = removes[i,0];
      removesSub[i][1] = removes[i,1];
    }

    for(int i = 0; i < x; i++)
