class Program
{
    static void Main(string[] args)
    {
        int[] NM = ReadLineParseIntArray();
        int N = NM[0];
        int M = NM[1];
        if (M % 2 == 1)
        {
            WriteLine(-1);
            return;
        }

        List<int>[] Edges = new List<int>[N];
        for (int i = 0; i < N; i++)
            Edges[i] = new List<int>();

        bool[] isDecided = new bool[N];
        bool[] isOdd = new bool[N];
        for(int i = 0; i < M; i++)
        {
            int[] AB = ReadLineParseIntArray();
            Edges[AB[0] - 1].Add(AB[1] - 1);
            Edges[AB[1] - 1].Add(AB[0] - 1);
        }

        Queue<int> q = new Queue<int>();
        Queue<Tuple<int, int>> ans = new Queue<Tuple<int, int>>();

        for (int i = 0; i < N; i++)
            if (Edges[i].Count == 1)
            {
                q.Enqueue(i);
                isDecided[i] = true;
            }

        int count = 0;

        while(count != M)
        {
            int v = 0;
            if(q.Count != 0)
                v = q.Dequeue();
            else
                for(int i = 0; i < N; i++)
                    if(!isDecided[i])
                    {
                        v = i;
                        break;
                    }
            int w = 0;
            if(Edges[v].Count != 0)
                w = Edges[v][0];
            if (isOdd[v])
            {
                ans.Enqueue(new Tuple<int, int>(v, w));
                isOdd[v] = false;
            }
            else
            {
                ans.Enqueue(new Tuple<int, int>(w, v));
                isOdd[w] = isOdd[w] == false;
            }
            Edges[v].Remove(w);
            Edges[w].Remove(v);

            if (Edges[v].Count == 1)
            {
                q.Enqueue(v);
                isDecided[v] = true;
            }

            if (Edges[w].Count == 1)
            {
                q.Enqueue(w);
                isDecided[w] = true;
            }
            count++;
        }

        for(int i = 0; i < N; i++)
        {
            if (isOdd[i])
            {
                WriteLine(-1);
                return;
            }
        }

        foreach(var tuple in ans)
        {
            WriteLine($"{tuple.Item1 + 1} {tuple.Item2 + 1}");
        }
    }
    static int ReadLineParseInt() => int.Parse(ReadLine());
    static int[] ReadLineParseIntArray() => ReadLine().Split(' ').Select(int.Parse).ToArray();
}

