class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, m;
        sc.Multi(out n, out m);
        edge = new List<int>[n];
        edges = new P[m];
        ec = new int[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        for (int i = 0; i < m; i++)
        {
            int u, v;
            sc.Multi(out u, out v);
            --u;
            --v;
            edges[i] = new P(u, v);
            edge[u].Add(i);
            edge[v].Add(i);
            ++ec[u];
        }
        vis = new bool[n];
        rev = new bool[m];

        if (dfs(0, 0) == 1) {
            Prt(-1);
            return;
        }
        for (int i = 0; i < m; i++)
        {
            if (!rev[i]) {
                Prt(edges[i].v1 + 1, edges[i].v2 + 1);
            }
            else {
                Prt(edges[i].v2 + 1, edges[i].v1 + 1);
            }
        }

    }
    int[] ec;
    P[] edges;
    List<int>[] edge;
    bool[] rev;
    bool[] vis;
    int dfs(int p, int r) {
        vis[p] = true;
        r ^= ec[p] % 2;
        foreach (var item in edge[p])
        {
            int to = edges[item].v1 + edges[item].v2 - p;
            if (vis[to]) continue;

            if (r == 1) {
                rev[item] = !rev[item];
            }
            r = dfs(to, r);
            if (r == 1) {
                rev[item] = !rev[item];
            }
        }
        return r;
    }

}

