public class Prog
{
    public struct Pair { public int x, y; public Pair(int x, int y) { this.x = x; this.y = y; } }
    public static void Solve()
    {
        int N = NextInt();
        int M = NextInt();
        if (M % 2 == 1) { Console.WriteLine(-1); return; }
        //作れる
        HashSet<int>[] G = new HashSet<int>[N + 1];
        for (int i = 0; i <= N; i++) G[i] = new HashSet<int>();
        int[] A = new int[M];
        int[] B = new int[M];
        for (int i = 0; i < M; i++)
        {
            A[i] = NextInt();
            B[i] = NextInt();
            G[A[i]].Add(B[i]);
            G[B[i]].Add(A[i]);
        }

        //流入1からは確定で流れるでok
        Queue<int> Q = new Queue<int>();
        int[] ok = new int[N + 1];
        for (int i = 1; i <= N; i++) if (G[i].Count() == 1) Q.Enqueue(i);

        while (Q.Count() != 0)
        {
            int x = Q.Dequeue();
            int y = G[x].First();
            G[y].Remove(x);
            G[x].Remove(y);
            Console.WriteLine(y + " " + x);
            ok[y] += 1;
        }

        //あとは方向適当に決める
        Q = new Queue<int>();
        for (int i = 1; i <= N; i++)
            if (G[i].Count() != 0) Q.Enqueue(i);

        while (Q.Count() != 0)
        {
            int x = Q.Dequeue();
            //辺列挙
            //なるべく流す優先
            List<int> e = G[x].ToList();
            for (int i = 0; i < e.Count(); i++)
            {
                if (ok[x] % 2 == 1)
                {
                    //流す
                    int y = e[i];
                    G[y].Remove(x);
                    G[x].Remove(y);
                    Console.WriteLine(x + " " + y);
                    ok[x] += 1;
                }
                else if (i + 1 < e.Count())
                {
                    //2粉ガス
                    int y0 = e[i], y1 = e[i + 1];
                    G[y0].Remove(x);
                    G[x].Remove(y0);
                    G[y1].Remove(x);
                    G[x].Remove(y1);
                    Console.WriteLine(x + " " + y0);
                    Console.WriteLine(x + " " + y1);
                    ok[x] += 2;
                    i += 1;
                }
                else
                {
                    //流入させる
                    int y = e[i];
                    G[y].Remove(x);
                    G[x].Remove(y);
                    Console.WriteLine(y + " " + x);
                    ok[y] += 1;
                }
            }
        }
    }
    public static void Main()
    {
        var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    public static long RepPow(long x, long p, long m = 1000000007)
    {
        if (p == 0) return 1;
        if (p == 1) return x % m;
        long b = RepPow(x, p / 2, m) % m;
        if (p % 2 == 0) { return (b * b) % m; }
        else { return (x * ((b * b) % m)) % m; }
    }
}
