    public void Solve()
    {
        n = ri;
        m = ri;
        int t = 0;
        v = new List<int>[n];
        for(int i = 0; i < n; i++) { v[i] = new List<int>(); }
        int a = 0, b = 0;
        for(int i = 0; i < m; i++)
        {
            a = ri - 1; b = ri - 1;
            if (a > b) { t = a; a = b; b = t; }
            v[a].Add(b);
        }
        if (m % 2 == 1) { Write(-1); return; }
        even = new bool[n];
        even[0] = v[0].Count % 2 == 0;
        Think(0);
    }

    void Think(int i)
    {
        if (i == n) return;
        if (v[i].Count > 0)
        {
            if (even[i])
            {
                foreach (var k in v[i])
                {
                    Write($"{i+1} {k+1}");
                }
                Think(i + 1);
            }
            else
            {
                Write($"{v[i][0]+1} {i+1}");
                even[v[i][0]] = !even[v[i][0]];
                v[i].RemoveAt(0);
                foreach (var k in v[i])
                {
                    Write($"{i+1} {k+1}");
                }
                Think(i + 1);
            }
        }
    }

