namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			int m = cin.Int();
			var to = new List<int>[n];
			var path = new List<int>[n];
			for (int i = 0; i < n; i++) {
				to[i] = new List<int>();
				path[i] = new List<int>();
			}

			for (int i = 0; i < m; i++) {
				int a = cin.Int();
				int b = cin.Int();
				to[a - 1].Add(b - 1);
