				for (int j = 0; j < to[i].Count; j++) {
					if (to[i][j] > i) {
						if (to[i].Count % 2 == 1 && innum[i] % 2 == 0) {
							sb.AppendLine($"{to[i][j] + 1} {i + 1}");
