							sb.AppendLine($"{to[i][j] + 1} {i + 1}");
							innum[i]++;
							outnum[to[i][j]]++;
						} else {
							sb.AppendLine($"{i + 1} {to[i][j] + 1}");
							outnum[i]++;
							innum[to[i][j]]++;
						}
					}
				}
			}

