type Item struct {
  Comparison  int
  Index int
}
type PriorityQueue []*Item
func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
  return pq[i].Comparison < pq[j].Comparison
}
func (pq PriorityQueue) Swap(i, j int) {
  pq[i], pq[j] = pq[j], pq[i]
}
func (pq *PriorityQueue) Pop() interface{} {
  old := *pq
  n := len(old)
  item := old[n - 1]
  *pq = old[0:n - 1]
  return item
}
func (pq *PriorityQueue) Push(x interface{}) {
  item := x.(*Item)
  *pq = append(*pq, item)
}

type Node struct {
  Index int
  Degree int
  Edge []int
}
func Node2Item(N Node) *Item {
  I := Item{len(N.Edge), N.Index}
  return &I
}

func Search(A *[]int, a int) int {
  N := len((*A))
  if (*A)[0] == a { return 0 }
  if (*A)[N - 1] == a { return N - 1 }
  high, low := N - 1, 0
  for high - low > 1 {
    med := (high + low) / 2
    if (*A)[med] == a { return med }
    if a < (*A)[med] {
      high = med
    } else {
      low = med
    }
  }
  return -1
}

func main() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  G := make([]Node, N)
  for i := range G {
    e := make([]int, 0)
    G[i] = Node{i, 0, e}
  }
  E := make([][]int, M)
  for i := range E {
    AB := NextIntVec()
    A, B := AB[0] - 1, AB[1] - 1
    E[i] = []int{A, B}
    G[A].Edge = append(G[A].Edge, i)
    G[B].Edge = append(G[B].Edge, i)
  }
  var PQ PriorityQueue
  for _, node := range G {
    heap.Push(&PQ, Node2Item(node))
  }
  for len(PQ) > 0 {
    s := heap.Pop(&PQ).(*Item).Index
    if len(G[s].Edge) == 0 { continue }
    for _, e := range G[s].Edge {
      t := E[e][0]
      if t == s { t = E[e][1] }
      if G[s].Degree % 2 > 0 {
        G[s].Degree++
        E[e] = []int{s, t}
      } else {
        G[t].Degree++
        E[e] = []int{t, s}
      }
      j := Search(&G[t].Edge, e)
      if j < len(G[t].Edge) - 1 {
        G[t].Edge = append(G[t].Edge[:j], G[t].Edge[j + 1:]...)
      } else {
        G[t].Edge = G[t].Edge[:j]
      }
      heap.Push(&PQ, Node2Item(G[t]))
    }
    G[s].Edge = make([]int, 0)
  }
  directable := true
  for _, node := range G {
    if node.Degree % 2 > 0 {
      Write(-1)
      directable = false
      break
    }
  }
  if directable {
    for i, e := range E {
      E[i] = []int{e[0] + 1, e[1] + 1}
      WriteIntVec(&E[i])
    }
  }
  Output()
}

