type UnionFind struct {
	// for children, the value is its parent index. for root, the value is -1 * the size of the group
	parents []int
}

func NewUnionFind(n int) *UnionFind {
	uf := &UnionFind{}

	uf.parents = make([]int, n)

	for i := range uf.parents {
		uf.parents[i] = -1
	}

	return uf
}

func (uf *UnionFind) root(x int) int {
	if uf.parents[x] < 0 {
		return x
	}

	r := uf.root(uf.parents[x])
	uf.parents[x] = r
	return r
}

func (uf *UnionFind) same(x, y int) bool {
	return uf.root(x) == uf.root(y)
}

func (uf *UnionFind) merge(x, y int) {
	xr := uf.root(x)
	yr := uf.root(y)

	if xr == yr {
		return
	}

	// make less index one as a root
	if xr > yr {
		xr, yr = yr, xr
	}

	uf.parents[xr] += uf.parents[yr]
	uf.parents[yr] = xr
}

func (uf *UnionFind) size(x int) int {
	return -uf.parents[uf.root(x)]
}

func (uf *UnionFind) groupCount() (res int) {
	for _, parent := range uf.parents {
		if parent < 0 {
			res++
		}
	}

	return
}

// コストを考えない Kruskal
func GetMinEdgeList(edgeList [][]int) [][]int {
	uf := NewUnionFind(len(edgeList))

	minEdgeList := make([][]int, len(edgeList))
	for i := range minEdgeList {
		minEdgeList[i] = make([]int, 0)
	}

	for u, uEdges := range edgeList {
		for _, v := range uEdges {
			if u > v || uf.same(u, v) {
				continue
			}

			minEdgeList[u] = append(minEdgeList[u], v)
			minEdgeList[v] = append(minEdgeList[v], u)
			uf.merge(u, v)
		}
	}

	return minEdgeList
}

// big - small. small はソートされている必要がある
func edgeListDiff(big [][]int, small [][]int) [][]int {
	res := make([][]int, len(big))

	for i := range res {
		res[i] = make([]int, 0)
	}

	for u, uEdgeList := range big {
		for _, v := range uEdgeList {
			i := sort.SearchInts(small[u], v)

			if i < len(small[u]) && small[u][i] == v {
				continue
			}

			res[u] = append(res[u], v)
		}
	}

	return res
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()
	M := io.NextInt()

	edgeList := make([][]int, N)
	for i := range edgeList {
		edgeList[i] = make([]int, 0)
	}

	for i := 0; i < M; i++ {
		a := io.NextInt() - 1
		b := io.NextInt() - 1
		edgeList[a] = append(edgeList[a], b)
		edgeList[b] = append(edgeList[b], a)
	}

	// 1. 最小全域木を作る
	// 2. それ以外の辺については適当に方向を決めてしまう
	// 3. 最小全域木について根を適当に設けて、木の子から向きを確定させていく

	// 1. 最小全域木を作る
	minEdgeList := GetMinEdgeList(edgeList)

	for _, uEdges := range minEdgeList {
		sort.Ints(uEdges)
	}

	notMinEdgeList := edgeListDiff(edgeList, minEdgeList)

	resEdgeList := make([][]int, N)
	for u := range resEdgeList {
		resEdgeList[u] = make([]int, 0)
	}

	// 2. それ以外の辺については適当に方向を決めてしまう
	for u, uEdges := range notMinEdgeList {
		for _, v := range uEdges {
			if u > v {
				continue
			}

			// u -> v
			resEdgeList[u] = append(resEdgeList[u], v)
		}
	}

	// 3. 最小全域木について根を適当に設けて、木の子から向きを確定させていく
	var rec func(u, p int)

	rec = func(u, p int) {
		_ = edgeList[0]
		for _, v := range minEdgeList[u] {
			if v == p {
				continue
			}

			rec(v, u)
		}

		if p == -1 {
			return
		}

		curOutCt := len(resEdgeList[u])
		var from, to int

		if curOutCt%2 == 1 {
			from, to = u, p
		} else {
			from, to = p, u
		}

		resEdgeList[from] = append(resEdgeList[from], to)
	}

	rec(0, -1)

	if len(resEdgeList[0])%2 != 0 {
		io.Println(-1)
		return
	}

	for u, uEdges := range resEdgeList {
		for _, v := range uEdges {
			io.Println(u+1, v+1)
		}
	}
}

