import (
  "bufio"
  "container/list"
  "fmt"
  "os"
  "strconv"
  "strings"
)

func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  n,m := input.NextInts()
  if m%2 == 1 { fmt.Println(-1);return }
  uf := NewUnionFind(n)
  es := []Edge{}
  num := make([]int,n)
  tree := make([][]int,n)
  extra := make([][]int,n)
  for i:=0;i<m;i++ {
    a,b := input.NextInts()
    a,b = a-1,b-1
    if uf.Same(a,b) {
      extra[a] = append(extra[a],b)
      es = append(es,Edge{a,b})
      num[a]++
    } else {
      uf.Unite(a,b)
      tree[a] = append(tree[a],b)
      tree[b] = append(tree[b],a)
    }
  }
  order := order_from_leaf(tree)
  for _,node := range order {
    if node.par < 0 { continue }
    par := node.par
    v := node.id
    if num[v]%2 == 0 {
      es = append(es,Edge{par,v})
      num[par]++
    } else {
      es = append(es,Edge{v,par})
    }
  }
  for _,e := range es { fmt.Println(e.fm+1,e.to+1) }
}

type Edge struct { fm,to int }
type Node struct { par,id int }
func order_from_leaf(tree [][]int) []Node {
  n := len(tree)
  order := make([]Node,n)
  q := list.New()
  q.PushBack(Node{-1,0})
  i := n-1
  for q.Len() > 0 {
    p := q.Remove(q.Front()).(Node)
    order[i] = p
    i--
    for _,e := range tree[p.id] {
      if e == p.par { continue }
      q.PushBack(Node{p.id,e})
    }
  }
  return order
}

type UnionFind struct { par,rank []int }
func NewUnionFind(n int) UnionFind {
  par := make([]int,n)
  rank := make([]int,n)
  for i:=0;i<n;i++ { par[i] = i }
  return UnionFind{par,rank}
}
func(u UnionFind) Find(i int) int {
  if u.par[i] == i { return i }
  u.par[i] = u.Find(u.par[i])
  return u.par[i]
}
func(u UnionFind) Same(i,j int) bool { return u.Find(i) == u.Find(j) }
func(u UnionFind) Unite(i,j int) {
  i,j = u.Find(i),u.Find(j)
  if i == j { return }
  if u.rank[i] < u.rank[j] { u.par[i] = j;return }
  u.par[j] = i
  if u.rank[i] == u.rank[j] { u.rank[i]++ }
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInts() (int,int) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}

