  return len(N.Edge)
}
func Eval2(N Node) int {
  return -len(N.Edge)
}
const p = 1000000
func Solve(G []Node, E *[][]int, f func(Node) int) []int {
  N := len(G)
  var PQ PriorityQueue
  for _, node := range G {
    heap.Push(&PQ, Node2Item(node, f))
  }
  for len(PQ) > 0 {
    s := heap.Pop(&PQ).(*Item).Index
    if len(G[s].Edge) == 0 { continue }
    deg := ((G[s].Outbound + len(G[s].Edge)) / 2) * 2
    for _, e := range G[s].Edge {
      t := (*E)[e][0]
      if t == s { t = (*E)[e][1] }
      if G[s].Outbound < deg {
        G[s].Outbound++
        (*E)[e] = []int{s, t}
      } else {
        G[t].Outbound++
        (*E)[e] = []int{t, s}
      }
      j := Search(&G[t].Edge, e)
      G[t].Edge = append(G[t].Edge[:j], G[t].Edge[j + 1:]...)
      heap.Push(&PQ, Node2Item(G[t], f))
    }
    G[s].Edge = make([]int, 0)
  }
  D := make([]int, N)
  for _, e := range (*E) {
    D[e[0]]++
  }
  return D
}

func Search(A *[]int, a int) int {
  N := len((*A))
  if (*A)[0] == a { return 0 }
  if (*A)[N - 1] == a { return N - 1 }
  high, low := N - 1, 0
  for high - low > 1 {
    med := (high + low) / 2
    if (*A)[med] == a { return med }
    if a < (*A)[med] {
      high = med
    } else {
      low = med
    }
  }
  return -1
}

func main() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  G := make([]Node, N)
  for i := range G {
    e := make([]int, 0)
    G[i] = Node{i, 0, 0, e}
  }
  E := make([][]int, M)
  for i := range E {
    AB := NextIntVec()
    A, B := AB[0] - 1, AB[1] - 1
    E[i] = []int{A, B}
    G[A].Edge = append(G[A].Edge, i)
    G[A].Degree++
    G[B].Edge = append(G[B].Edge, i)
    G[B].Degree++
  }
  D := Solve(G, &E, Eval1)
  undirectable := false
  directable := true
  for _, d := range D {
    if d % 2 > 0 {
      undirectable = true
      break
    }
  }
  if undirectable {
    D := Solve(G, &E, Eval2)
    for _, d := range D {
      if d % 2 > 0 {
        directable = false
        break
      }
    }
  }
  if directable {
    for i, e := range E {
      E[i] = []int{e[0] + 1, e[1] + 1}
      WriteIntVec(&E[i])
    }
  } else {
    Write(-1)
  }
  Output()
}

