func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  n,m := input.NextInts()
  if m%2 == 1 { fmt.Println(-1);return }
  g := make([][]int,n)
  for i:=0;i<m;i++ {
    a,b := input.NextInts()
    g[a-1] = append(g[a-1],b-1)
    g[b-1] = append(g[b-1],a-1)
  }
  var pq PriorityQueue
  heap.Init(&pq)
  for i:=0;i<n;i++ {
    if len(g[i])%2 == 0 { heap.Push(&pq,&Item{len(g[i]),i}) }
  }
  num := make([]int,n)
  es := []Edge{}
  used := make(map[Edge]struct{})
  for len(es) < m {
    item := heap.Pop(&pq).(*Item)
    if item.n != len(g[item.node])-num[item.node] { continue }
    for _,to := range g[item.node] {
      if _,ok := used[Edge{item.node,to}];ok { continue }
      num[to]++
      if (len(g[to])-num[to])%2 == 0 { heap.Push(&pq,&Item{len(g[to])-num[to],to}) }
      used[Edge{item.node,to}] = struct{}{}
      used[Edge{to,item.node}] = struct{}{}
      es = append(es,Edge{item.node,to})
    }
  }
  for _,e := range es { fmt.Println(e.c+1,e.d+1) }
}

