func main() {
	var n, m int
	fmt.Scan(&n)
	fmt.Scan(&m)

	if m%2 != 0 {
		fmt.Println("-1")
		return
	}

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	edges := make([][]int, n)
	direction := make(map[int]map[int]bool)
	outboundCountOdd := make(map[int]bool)
	for i := 0; i < n; i++ {
		edges[i] = []int{}
	}

	for i := 0; i < m; i++ {
		scanner.Scan()
		a, _ := strconv.Atoi(scanner.Text())
		scanner.Scan()
		b, _ := strconv.Atoi(scanner.Text())
		a--
		b--

		edges[a] = append(edges[a], b)
		edges[b] = append(edges[b], a)
		if _, ok := direction[a]; !ok {
			direction[a] = make(map[int]bool)
		}
		direction[a][b] = true
		if _, ok := outboundCountOdd[a]; ok {
			delete(outboundCountOdd, a)
		} else {
			outboundCountOdd[a] = true
		}
	}

	for len(outboundCountOdd) > 0 {
		var first, second int
		for k := range outboundCountOdd {
			first = k
			break
		}
		delete(outboundCountOdd, first)
		if len(outboundCountOdd) == 0 {
			fmt.Println("-1")
			return
		}
		for k := range outboundCountOdd {
			second = k
			break
		}
		delete(outboundCountOdd, second)

		e := make(map[int]map[int]bool)
		seen := make(map[int]bool)
		var dfs func(node int, e map[int]map[int]bool) map[int]map[int]bool
		dfs = func(node int, e map[int]map[int]bool) map[int]map[int]bool {
			if node == second {
				return e
			}
			seen[node] = true

			for i := 0; i < len(edges[node]); i++ {
				n := edges[node][i]
				if seen[n] {
					continue
				}

				if _, ok := e[node]; !ok {
					e[node] = make(map[int]bool)
				}
				e[node][n] = true
				ret := dfs(n, e)
				if ret != nil {
					return ret
				}
				delete(e[node], n)
			}

			return nil
		}
		ret := dfs(first, e)

		for k1, v := range ret {
			for k2 := range v {
				if direction[k1][k2] {
					delete(direction[k1], k2)
