const p = 1000000
func Solve(G []Node, E *[][]int, f func(Node) int) []int {
  N := len(G)
  var PQ PriorityQueue
  for _, node := range G {
    heap.Push(&PQ, Node2Item(node, f))
  }
  for len(PQ) > 0 {
    s := heap.Pop(&PQ).(*Item).Index
    if len(G[s].Edge) == 0 { continue }
    deg := ((G[s].Outbound + len(G[s].Edge)) / 2) * 2
    for _, e := range G[s].Edge {
      t := (*E)[e][0]
      if t == s { t = (*E)[e][1] }
      if G[s].Outbound < deg {
        G[s].Outbound++
        (*E)[e] = []int{s, t}
      } else {
        G[t].Outbound++
        (*E)[e] = []int{t, s}
      }
      j := Search(&G[t].Edge, e)
      G[t].Edge = append(G[t].Edge[:j], G[t].Edge[j + 1:]...)
      heap.Push(&PQ, Node2Item(G[t], f))
    }
    G[s].Edge = make([]int, 0)
  }
  D := make([]int, N)
  for _, e := range (*E) {
    D[e[0]]++
  }
  return D
}

