  }
  E := make([][]int, M)
  for i := range E {
    AB := NextIntVec()
    A, B := AB[0] - 1, AB[1] - 1
    E[i] = []int{A, B}
    G[A].Edge = append(G[A].Edge, i)
    G[A].Degree++
    G[B].Edge = append(G[B].Edge, i)
    G[B].Degree++
  }
  D := Solve(G, &E, UndefEdges)
  undirectable := false
  directable := true
  for _, d := range D {
    if d % 2 > 0 {
      undirectable = true
      break
    }
  }
  if undirectable {
    D := Solve(G, &E, UEandDegree)
    for _, d := range D {
      if d % 2 > 0 {
        directable = false
        break
      }
    }
  }
  if directable {
    for i, e := range E {
      E[i] = []int{e[0] + 1, e[1] + 1}
      WriteIntVec(&E[i])
    }
  } else {
    Write(-1)
  }
  Output()
}

