type graph = {n: int; m: int; e: (int * int) array; adj: (int list) array}
type spanningTree = {root: int; p: int array; ch: (int list) array}

let fullRep (n, m, e0) : graph = let res = {
  n;
  m;
  e=Array.init (2*m) (fun i ->
    let (u, v) = e0.(i/2) in
    if i mod 2 = 0 then (u, v)
    else (v, u))
  ;
  adj=
    let adj = Array.make n [] in
    for i=0 to m-1 do
      let (u, v) = e0.(i) in
      adj.(u) <- (2*i) :: adj.(u);
      adj.(v) <- (2*i+1) :: adj.(v)
    done;
    adj
}
in
Array.iteri (fun u is -> List.iter (fun i -> let (u', v) = res.e.(i) in assert (u' = u); assert (List.mem (i lxor 1) res.adj.(v))) is) res.adj;
for i=0 to 2*m-1 do
  let (u, v) = res.e.(i) in
  assert (res.e.(i lxor 1) = (v, u))
done;
res

let root (rt : int) ({n; e; adj} : graph) : spanningTree =
  let p = Array.make n (-1) in
  let ch = Array.make n [] in
  let vis = Array.make n false in
  let rec go u i =
    vis.(u) <- true;
    p.(u) <- i;
    List.iter
      (fun j ->
        let (_, v) = e.(j) in
        if not vis.(v) then begin
          ch.(u) <- j :: ch.(u);
          go v (j lxor 1)
        end)
      adj.(u)
  in
  go rt (-1);
  Array.iteri (fun u is -> List.iter (fun i -> let (u', v) = e.(i) in assert (u' = u); assert (p.(v) = (i lxor 1))) is) ch;
  {root=rt; p; ch}

type edgeSet = {h: (int, unit) Hashtbl.t; outDeg: bool array}
let addEdge s g i =
  Hashtbl.add s.h i ();
  let (u, _) = g.e.(i) in s.outDeg.(u) <- not s.outDeg.(u)

let solve (g : graph) : (edgeSet option) =
  if g.m mod 2 = 1 then None
  else
  let t = root 0 g in
  let te = Hashtbl.create (g.n-1) in
  let rec dfs u =
