            --deg[u];
            --deg[v];
            ++cnt[u];
            sets[u].removeKey(v);
            sets[v].removeKey(u);
            if (deg[u] > 0) {
              q.insert(Entry(deg[u], u));
            }
            if (deg[v] > 0) {
              q.insert(Entry(deg[v], v));
            }
          }
        }
