int N, M;
int[] A, B;

int[][] G;
int[] dep;
int[][] ans;

void dfs(int u, int p) {
  dep[u] = (p == -1) ? 0 : (dep[p] + 1);
  foreach (i; G[u]) {
    const v = A[i] ^ B[i] ^ u;
    if (v != p) {
      if (dep[v] == -1) {
        ans[i] = [u, v];
        dfs(v, u);
      } else {
        if (dep[u] > dep[v]) {
          ans[i] = [u, v];
        }
      }
    }
  }
}

