using namespace std;
vector< vector<int> > adj;
vector< pair<int,int> > res;
int check[1000000],num,v,out[1000000],n,m,u;
void DFS(int pos,int par){
	check[pos]=++num;
	for(int i=0;i<adj[pos].size();i++){
		int nxt=adj[pos][i];
		if(check[nxt]==0){
			DFS(nxt,pos);
			if(out[nxt]%2==1){
				res.push_back(make_pair(nxt,pos));
				out[nxt]++;
			}else{
				res.push_back(make_pair(pos,nxt));
				out[pos]++;
			}
		}else if(nxt!=par&&check[nxt]<check[pos]){
			out[pos]++;
			res.push_back(make_pair(pos,nxt));
		}
	}
}
