var (N, M) = input(int, 2)
if M mod 2 == 1:
  echo "-1"; quit(0)
var edge = newseq2[int](N + 1, 0)
var edges = newseq[tuple[v: int, u: int]]()
for i in 1 .. M:
  var (a, b) = input(int, 2)
  edge[a].add(b)
  edge[b].add(a)
  edges.add((a, b))
var nodes = newseq[tuple[idx: int, height: int]]()
var visited = newseq[bool](N + 1)
var tb = inittable[tuple[v: int, u: int], int]()
# 0: 全域木 / 1: v -> u / 2: u -> v
proc dfs(v: int, height: int) =
  visited[v] = true
  nodes.add((v, height))
  for u in edge[v]:
    if not visited[u]:
      tb[(v, u)] = 0
      tb[(u, v)] = 0
      dfs(u, height + 1)
dfs(1, 0)
nodes = nodes.sortedByIt(-it.height)
var outdeg = newseq[int](N + 1)
for e in edges:
  var (v, u) = e
  if tb.haskey((v, u)):
    continue
  else:
    tb[(v, u)] = 1
    tb[(u, v)] = 2
    outdeg[v] += 1
for d in nodes:
  var (v, _) = d
  for u in edge[v]:
    if tb[(v, u)] == 0:
      if outdeg[v] mod 2 == 1:
        tb[(v, u)] = 1
        tb[(u, v)] = 2
        outdeg[v] += 1
        break
      else:
        tb[(u, v)] = 1
        tb[(v, u)] = 2
        outdeg[u] += 1
        break
for e in edges:
  var (v, u) = e
  if tb[(v, u)] == 1:
    echo v, " ", u
  elif tb[(u, v)] == 1:
    echo u, " ", v
  else:
    assert false

