import sys
sys.setrecursionlimit(30000)
input = sys.stdin.readline


def dfs(adj, cur, path):
    while len(adj[cur]):
        nxt = adj[cur].pop()
        adj[nxt].remove(cur)
        dfs(adj, nxt, path)
    path.append(cur)


def main():
    N, M = map(int, input().split())
    adj = [set() for _ in range(N)]
    for _ in range(M):
        A, B = map(int, input().split())
        adj[A-1].add(B-1)
        adj[B-1].add(A-1)
    if M % 2 == 1:
        print(-1)
        return
    edges = []
    for i in range(N):
        if len(adj[i]) % 2 == 1:
            edges.append(i)
    if len(edges) == 0:
        start = 0
    elif len(edges) == 2:
        start = edges[0]
    else:
        print(-1)
    path = []
    dfs(adj, start, path)
    for i in range(len(path) - 1):
        a, b = path[i] + 1, path[i+1] + 1
        if i % 2 == 0:
            print(a, b)
        else:
            print(b, a)


if __name__ == "__main__":
