import sys


def solve(n, m, links, parents):
    if m % 2 == 1:
        print(-1)
        return

    fixed = [len(l) % 2 == 0 for l in links]

    def reverse_links(s, t):
        v = s
        while v != t:
            p = parents[v]
            links[p][v] ^= 1
            v = p

    # print(links)
    # print(parents)
    # print(fixed)

    tmp_vertices = set()
    tmp_pair = -1
    for v in range(n):
        if fixed[v]:
            continue
        exist_pair = tmp_pair != -1
        p = parents[v]
        if not exist_pair:
            tmp_vertices.add(v)
            while p != -1:
                tmp_vertices.add(p)
                p = parents[p]
        elif v in tmp_vertices:
            reverse_links(tmp_pair, v)
        else:
            while p != -1:
                if p in tmp_vertices:
                    reverse_links(v, p)
                    reverse_links(tmp_pair, p)
                    break
                p = parents[p]
        if exist_pair:
            tmp_vertices.clear()
            tmp_pair = -1
        else:
            tmp_pair = v

        # print(v, tmp_vertices, tmp_pair)

    if tmp_pair != -1:
        print(-1)
        return

    ans = []
    for v in range(n):
        for u, d in links[v].items():
            if d == 0:
                ans.append('{} {}'.format(v + 1, u + 1))
            else:
                ans.append('{} {}'.format(u + 1, v + 1))
    print('\n'.join(ans))


