class UnionFind:
  def __init__(self, N):
    self.par = list(range(N))

  def union(self, x, y):
    x = self.find(x)
    y = self.find(y)
    if x != y:
      self.par[x] = y
    return

  def find(self, x):
    if self.par[x] == x:
      return x
    else:
      return self.find(self.par[x])

