class Graph:
    #コンストラクタ
    def __init__(self):
        self._nodes=[]
        self._edges=[]
        self._neighbors={}

    def __getitem__(self, node: int):
        return self.neighbors(node)

    def add_node(self,node: int):
        if node not in self._nodes:
            self._nodes.append(node)
            self._neighbors[node]=[]

    def add_edge(self,u: int,v: int):
        if ((u,v) not in self._edges or
            (v,u) not in self._edges):
            self._edges.append((u,v))
            self.add_node(u)
            self.add_node(v)
            self._neighbors[u].append(v)
            self._neighbors[v].append(u)

    def remove_edge(self,u: int,v: int):
        _removed=False
        if (u,v) in self._edges:
            self._edges.remove((u,v))
            _removed=True
        elif (v,u) in self._edges:
            self._edges.remove((v,u))
            _removed=True

        if _removed:
            self._neighbors[u].remove(v)
            self._neighbors[v].remove(u)

    def nodes(self):
        return list(self._nodes)

    def edges(self):
        return list(self._edges)

    def degree(self, node):
        return len(self._neighbors[node])

    def neighbors(self,node):
        return list(self._neighbors[node])

    def number_of_nodes(self):
        return len(self._nodes)

