class LinearSystemIncidence:
    '''
    need repair
    https://atcoder.jp/contests/agc035/submissions/13967640
    '''
    def __init__(self, N, edges, mod2=False, idx1=True):
        self.N = N
        self.M = len(edges)
        self.mod2 = mod2
        self.X = [0] * self.M
        self.seen = [False] * self.N
        self.G = [list() for _ in range(self.N)]
        for i, (u, v) in enumerate(edges):
            u -= idx1; v -= idx1
            self.G[u].append((i, v))
            self.G[v].append((i, ~u))

    def dfs(self, b, u):
        self.seen[u] = True
        for eid, v in self.G[u]:
            fwd = (v >= 0)
            if not fwd:
                v = ~v
            if self.seen[v]:
                continue
            tmp = self.dfs(b, v)
            self.X[eid] = tmp if fwd else -tmp
            b[u] += tmp


            if self.mod2:
                self.X[eid] &= 1
        if self.mod2:
            b[u] &= 1
        return b[u]

    def solve(self, b):
        for s in range(self.N):
            if self.seen[s]:
                continue
            if self.dfs(b, s):
                return False, list()
        return True, self.X


def main():
    N, M = map(int, input().split())
    E = [tuple(map(int, input().split())) for _ in range(M)]
    C = [0] * N
    for u, v in E:
        C[u-1] += 1

    solver = LinearSystemIncidence(N, E, mod2=True)
