        edgenum[a-1] += 1
        edgenum[b-1] += 1
    if M % 2 == 1: print(-1)
    else:
        flag = 0
        for i in range(N):
            if edgenum[i] == 1:
                flag = i
                break
        q = collections.deque()
        outedge = [set() for _ in range(N)]
        outnum = [0] * N
        visited = [False] * N
        q.append(flag)
        while q:
            now = q.popleft()
            if not visited[now]:
                visited[now] = True
                for next in edge[now]:
                    if not visited[next]: q.append(next)
                    if next not in outedge[now] and now not in outedge[next]:
                        if outnum[now] % 2 == 0 and edgenum[now] == 1:
                            outedge[next] |= {now}
                            outnum[next] += 1
                        else:
                            outedge[now] |= {next}
                            outnum[now] += 1
                        edgenum[next] -= 1
                        edgenum[now] -= 1

        for i in range(N):
