import heapq


def solve(N: int, M: int, A: "List[int]", B: "List[int]"):
    if M % 2 != 0:
        print(-1)
        return

    adj = defaultdict(set)
    for a, b in zip(A, B):
        adj[a].add(b)
        adj[b].add(a)

    res = set()
    count = [0 for _ in range(N)]
    defined = [0 for _ in range(N)]

    pQ = deque([0], N)
    pvisited = [False for _ in range(N)]
    Q = []
    while len(pQ) > 0:
        u = pQ.popleft()
        pvisited[u] = True
        if len(adj[u]) == 1:
            defined[u] = 1
            heapq.heappush(Q, (0, u))
        for v in adj[u]:
            if pvisited[v]:
                continue
            pQ.append(v)
    if len(Q) == 0:
        Q = [(len(adj[0]), 0)]
