def solve(n, m, links, parents):
    if m % 2 == 1:
        print(-1)
        return

    fixed = [len(l) % 2 == 0 for l in links]

    def reverse_links(s, t):
        v = s
        while v != t:
            p = parents[v]
            links[p][v] ^= 1
            v = p

    # print(links)
    # print(parents)
    # print(fixed)

    tmp_vertices = set()
    tmp_pair = -1
    for v in range(n - 1, -1, -1):
        if fixed[v]:
            continue
        exist_pair = tmp_pair != -1
        u = v
        p = parents[v]
        if not exist_pair:
            tmp_vertices.add(u)
        if v == 0 and exist_pair:
            reverse_links(tmp_pair, v)
        else:
            # print(v, u, p, exist_pair, tmp_vertices, tmp_pair)
            while p != -1:
                if not exist_pair:
                    tmp_vertices.add(p)
                else:
                    if p in tmp_vertices:
                        reverse_links(v, p)
                        reverse_links(tmp_pair, p)
                u = p
                p = parents[u]
        if exist_pair:
            tmp_vertices.clear()
            tmp_pair = -1
        else:
            tmp_pair = v

    ans = []
    for v in range(n):
        for u, d in links[v].items():
            if d == 0:
                ans.append('{} {}'.format(v + 1, u + 1))
            else:
                ans.append('{} {}'.format(u + 1, v + 1))
    print('\n'.join(ans))


