import sys
from collections import defaultdict, deque
import heapq


def solve(N: int, M: int, A: "List[int]", B: "List[int]"):
    if M % 2 != 0:
        print(-1)
        return

    adj = defaultdict(set)
    for a, b in zip(A, B):
        adj[a].add(b)
        adj[b].add(a)

    res = set()
    count = [0 for _ in range(N)]
    freedom = [len(adj[i]) for i in range(N)]

    minlen = min((len(adj[i]) for i in range(N)))
    Q = [(len(adj[i]), i) for i in range(N) if len(adj[i]) == minlen]
    heapq.heapify(Q)
    while len(Q) > 0:
        i, u = heapq.heappop(Q)
        for v in adj[u]:
            if (u, v) in res:
                continue
            if (v, u) in res:
                continue
            if count[u] % 2 == 0:
                res.add((v, u))
                count[v] += 1
            else:
                res.add((u, v))
                count[u] += 1
            freedom[v] -= 1
            freedom[u] -= 1
            heapq.heappush(Q, (freedom[v], v))

    for c, d in res:
        print(c+1, d+1)

    return


