def dfs(G):
    visited = [False]*(G.number_of_nodes()+1)
    v=list(G.nodes())[0]
    yield v
    visited[v]=True
    stack = [(v, iter(G[v]))]
    while stack:
        parent,children = stack[-1]
        try:
            child=next(children)
            if not visited[child]:
                yield child
                visited[child]=True
                stack.append((child, iter(G[child])))
        except StopIteration:
            stack.pop()

