import sys


def solve(n, m, d_links):
    if m % 2 == 1:
        print(-1)
        return

    parents = [-1] * n
    fixed = [False] * n
    for v in range(n):
        children = 0
        for u in d_links[v]:
            if u < v:
                continue
            parents[u] = v
            children += 1
        if children % 2 == 0:
            fixed[v] = True

    # print(parents)
    # print(fixed)

    rev_links = [set() for _ in range(n)]

    for v in range(n - 1, -1, -1):
        if fixed[v]:
            continue
        u = v
        p = parents[v]
        while True:
            rev_links[p].add(u)
            if fixed[p] == False:
                fixed[v] = fixed[p] = True
                break
            u = p
            p = parents[u]
            if p == -1:
                print(-1)
                return
    # print(rev_links)

    ans = []
    for v in range(n):
        for u in rev_links[v]:
            ans.append('{} {}'.format(u + 1, v + 1))
        for u in d_links[v].difference(rev_links[v]):
            if u < v:
                continue
            ans.append('{} {}'.format(v + 1, u + 1))
    print('\n'.join(ans))


