def solve():

    N, M = list(map(int, input().split()))
    graph = [[0 for i in range(N)] for j in range(N)]

    for i in range(M):
        A, B = list(map(int, input().split()))
        graph[A-1][B-1] = 1
        graph[B-1][A-1] = 1

    result = []
    finish = [0 for i in range(N)]
    out_num = [0 for i in range(N)]

    while np.sum(graph) != 0:
        for i in range(N):
            if finish[i] == 1:
                continue
            if np.sum(graph[i])==2:
                for j in range(N):
                    if graph[i][j] == 1:
                        graph[i][j] = 0
                        graph[j][i] = 0
                        result.append([i,j])
                        out_num[i] += 1
                else:
                    finish[i] = 0
                break
        else:
            print("-1")
            return

    if np.sum(graph) != 0:
        print("-1")
        return

    for r in result:
        print(str(r[0]+1) + " " +str(r[1]+1))


