from collections import deque


def solve(n, m, links):
    if m % 2 == 1:
        print(-1)
        return

    topological = [{} for _ in range(n)]
    parents = [-1] * n
    q = deque([0])
    while q:
        v = q.popleft()
        for u in links[v]:
            if v in topological[u]:
                continue
            topological[v][u] = 0
            if parents[u] == -1:
                parents[u] = v
            q.append(u)

    fixed = [len(l) % 2 == 0 for l in topological]

    def reverse_links(s, t):
        v = s
        while v != t:
            p = parents[v]
            topological[p][v] ^= 1
            v = p

    tmp_trace = set()
    tmp_pair = -1
    for v in range(n):
        if fixed[v]:
            continue
        if tmp_pair == -1:
            u = v
            while u != -1:
                tmp_trace.add(u)
                u = parents[u]
            tmp_pair = v
        else:
            u = v
            while u != -1:
                if u in tmp_trace:
                    reverse_links(v, u)
                    reverse_links(tmp_pair, u)
                    break
                u = parents[u]
            else:
                print(tmp_pair, v)
                print(tmp_trace)
                raise AssertionError
            fixed[v] = fixed[tmp_pair] = True
            tmp_trace.clear()
            tmp_pair = -1

        # print(v, tmp_trace, tmp_pair)

    assert tmp_pair == -1

    ans = []
    for v in range(n):
        for u, d in topological[v].items():
            if d == 0:
                ans.append('{} {}'.format(v + 1, u + 1))
            else:
                ans.append('{} {}'.format(u + 1, v + 1))
    print('\n'.join(ans))


