            tmp_vertices.add(v)
            while p != -1:
                tmp_vertices.add(p)
                p = parents[p]
        elif v == 0:
            reverse_links(tmp_pair, v)
        else:
            # print(v, u, p, exist_pair, tmp_vertices, tmp_pair)
            while p != -1:
                if p in tmp_vertices:
