class LinearSystemIncidence:
    '''
    need repair
    https://atcoder.jp/contests/agc035/submissions/13967640
    '''
    def __init__(self, N, edges, mod2=False, idx1=True):
        self.N = N
        self.M = len(edges)
        self.mod2 = mod2
        self.X = [0] * self.M
        self.seen = [False] * self.N
        self.G = [list() for _ in range(self.N)]
        for i, (u, v) in enumerate(edges):
            u -= idx1; v -= idx1
            self.G[u].append((i, v))
            self.G[v].append((i, ~u))

    def dfs(self, b, u):
        self.seen[u] = True
        ret = b[u]
        for eid, v in self.G[u]:
            fwd = (v >= 0)
            if not fwd:
                v = ~v
            if self.seen[v]:
                continue
            tmp = self.dfs(b, v)
            self.X[eid] = tmp if fwd else -tmp
            ret += tmp

            if self.mod2:
                self.X[eid] &= 1
        if self.mod2:
            ret &= 1
        return ret

    def _solve(self, b):
        for s in range(self.N):
            if self.seen[s]:
                continue
            if self.dfs(b, s):
                return False, list()
        return True, self.X

    def solve(self, b):
        par = [-1] * self.N
        for s in range(self.N):
            if self.seen[s]:
                continue
            q = [s]
            while q:
                u = q[-1]
                if self.seen[u] > 1:
                    q.pop()
                elif self.seen[u]:
                    for eid, v in self.G[u]:
                        fwd = (v >= 0)
                        if not fwd:
                            v = ~v
                        if self.seen[v] > 1 and par[v] == u:
                            self.X[eid] = b[v] if fwd else -b[v]
                            b[u] += b[v]
                            if self.mod2:
                                self.X[eid] &= 1
                    self.seen[u] += 1
                    if self.mod2:
                        b[u] &= 1
                    q.pop()

                else:
                    self.seen[u] = True
                    for eid, v in self.G[u]:
                        fwd = (v >= 0)
                        if not fwd:
                            v = ~v
                        if not self.seen[v]:
                            par[v] = u
                            q.append(v)
            if b[s]:
                return False, list()
        return True, self.X


