def solve():
    N, M = map(int, input().split())
    if M%2:
        return '-1'
    E = [set() for _ in range(N+1)]
    for _ in range(M):
        a,b = map(int, input().split())
        E[a].add(b)
        E[b].add(a)
    q = [(0,1,1)]
    v = set()
    T = [set() for _ in range(N+1)]
    L = []
    V = []
    while q:
        n_, n, d = q.pop()
        if n not in v:
            T[n].add(n_)
            T[n_].add(n)
            v.add(n)
            V.append((d,n))
            if E[n]-v:
                q.extend([(n,u, d+1) for u in E[n]-v])
            else:
                L.append(n)

    A = [0 for _ in range(N+1)]
    res = []
    c = set()
    for d, n in sorted(V, reverse=1):
        c.add(n)
        if (A[n]+len(E[n]))%2:
            res.extend([(u,n) for u in E[n]-c])
            for u in E[n]-c:
                A[u] += 1
                E[u] -= {n}
        else:
            res.extend([(n,u) for u in E[n]-c])
            for u in E[n]-c:
                A[n] += 1
                E[u] -= {n}
    if any(a%2 for a in A):
        return '-1'
    else:
        return '\n'.join(['{} {}'.format(*e,) for e in res])


