use std::collections::BTreeSet;

fn main() {
    read!(n = usize, m = usize);
    if m % 2 == 1 {
        println!("-1");
    } else {
        let mut edges = BTreeSet::new();
        let mut adj = vec![BTreeSet::new(); n];
        let mut node_to_deg = vec![0; n];
        readx_loop!(|a = usize_, b = usize_| {
            let (a, b) = if a < b { (a, b) } else { (b, a) };
            edges.insert((a, b));
            adj[a].insert(b);
            adj[b].insert(a);
            node_to_deg[a] += 1;
            node_to_deg[b] += 1;
        });

        let mut deg_to_nodes = vec![BTreeSet::new(); n];
        for (v, &deg) in node_to_deg.iter().enumerate() {
            deg_to_nodes[deg].insert(v);
        }
        let mut is_odd = vec![false; n];
        let mut ans = Vec::new();

        while ans.len() < m {
            let (v1, v2) = match deg_to_nodes[1].iter().next().cloned() {
                Some(v1) => {
                    dbg!(v1);
                    let v2 = *adj[v1].iter().next().unwrap();
                    if is_odd[v1] {
                        (v1, v2)
                    } else {
                        (v2, v1)
                    }
                },
                None => dbg!(edges.iter().next().unwrap().clone())
            };

            let v1_deg = node_to_deg[v1];
            let v2_deg = node_to_deg[v2];
            ans.push((v1, v2));
            let (a, b) = if v1 < v2 { (v1, v2) } else { (v2, v1) };
            edges.remove(&(a, b));
            adj[v1].remove(&v2);
            adj[v2].remove(&v1);
            node_to_deg[v1] -= 1;
            node_to_deg[v2] -= 1;
            deg_to_nodes[v1_deg].remove(&v1);
            deg_to_nodes[v1_deg - 1].insert(v1);
            deg_to_nodes[v2_deg].remove(&v2);
            deg_to_nodes[v2_deg - 1].insert(v2);
            is_odd[v1] = !is_odd[v1];
        }

        with_stdout(|mut f| {
            for (v1, v2) in ans {
                writeln!(f, "{} {}", v1+1, v2+1).unwrap();
            }
        })
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    let mut tree = vec![vec![]; n];
    let mut used = vec![false; n];
    let mut visit = vec![false; n];
    dfs(0, &mut visit, &graph, &mut tree, &mut used);

    let mut ans = vec![vec![]; n];
    for u in 0..n {
        for &(v, i) in graph[u].iter() {
            if !used[i] {
                ans[u].push(v);
                used[i] = true;
            }
        }
    }

    answer_dfs(0, 0, &mut ans, &tree);
    for i in 0..n {
        for &next in ans[i].iter() {
            println!("{} {}", i + 1, next + 1);
        }
    }
}

fn answer_dfs(v: usize, p: usize, graph: &mut Vec<Vec<usize>>, tree: &Vec<Vec<usize>>) {
    for &next in tree[v].iter() {
        answer_dfs(next, v, graph, tree);
    }
    if v == p {
        return;
    }
    if graph[v].len() % 2 == 0 {
        graph[p].push(v);
    } else {
        graph[v].push(p);
    }
}

fn dfs(
    v: usize,
    visit: &mut Vec<bool>,
    graph: &Vec<Vec<(usize, usize)>>,
    tree: &mut Vec<Vec<usize>>,
    used: &mut Vec<bool>,
) {
    visit[v] = true;
    for &(next, i) in graph[v].iter() {
        if !visit[next] {
            tree[v].push(next);
            dfs(next, visit, graph, tree, used);
            used[i] = true;
        }
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }
    let mut used = vec![false; m];
    dfs(0, &mut vec![false; n], &graph, &mut used);

    let mut direction = vec![None; m];
    for v in 0..n {
        for &(next, edge_id) in graph[v].iter() {
            if !used[edge_id] && direction[edge_id].is_none() {
                direction[edge_id] = Some((v, next));
            }
        }
    }
    dfs2(0, 0, &graph, &used, &mut direction);
    for i in 0..m {
        let (from, to) = direction[i].unwrap();
        println!("{} {}", from + 1, to + 1);
    }
}

fn dfs2(
    v: usize,
    p: usize,
    graph: &Vec<Vec<(usize, usize)>>,
    used: &[bool],
    direction: &mut [Option<(usize, usize)>],
) {
    for &(next, edge_id) in graph[v].iter() {
        if p == next {
            continue;
        }
        if used[edge_id] {
            dfs2(next, v, graph, used, direction);
        }
    }

    let forward = graph[v]
        .iter()
        .flat_map(|&(_, edge_id)| direction[edge_id])
        .filter(|&(from, _)| from == v)
        .count();

    for &(next, edge_id) in graph[v].iter() {
        if used[edge_id] && direction[edge_id].is_none() {
            if forward % 2 == 0 {
                direction[edge_id] = Some((next, v));
            } else {
                direction[edge_id] = Some((v, next));
            }
        }
    }
}

fn dfs(v: usize, visited: &mut [bool], graph: &Vec<Vec<(usize, usize)>>, used: &mut [bool]) {
    visited[v] = true;
    for &(next, edge_id) in graph[v].iter() {
        if visited[next] {
            continue;
        }
        used[edge_id] = true;
        dfs(next, visited, graph, used);
    }
}

