fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let m: usize = sc.cin();
    if m % 2 == 1 {
        put!(-1);
        return;
    }

    let mut g = vec![vec![]; n];
    let mut edges = vec![];
    use std::collections::HashSet;
    let mut directed_edges = HashSet::new();  // contains(u, v) iff u->v

    for _ in 0..m {
        let a = sc.cin::<usize>() - 1;
        let b = sc.cin::<usize>() - 1;
        g[a].push(b);
        g[b].push(a);
        edges.push((a, b));
    }

    use std::collections::BinaryHeap;

    let mut degs: Vec<usize> = (0..n).map(|i| g[i].len()).collect();  // un-assigned
    let mut q = BinaryHeap::new();
    for i in 0..n { q.push((-(degs[i] as i32), i)); }

    fn direction(u: usize, v: usize, memo: &HashSet<(usize, usize)>) -> Option<bool> {
        if memo.contains(&(u, v)) {
            Some(true)
        } else if memo.contains(&(v, u)) {
            Some(false)
        } else {
            None
        }
    }

    while let Some((_, u)) = q.pop() {
        if degs[u] == 0 { continue }
        let mut count = 0;
        let mut unk = vec![];
        for &v in g[u].iter() {
            match direction(u, v, &directed_edges) {
                Some(true) => {
                    count += 1;
                }
                Some(false) => {
                }
                None => {
                    unk.push(v);
                }
            }
        }
        degs[u] = 0;
        match (count % 2 == 0, unk.len()) {
            (true, 0) => {}
            (false, 0) => {
                put!(-1);
                return;  // failed
            }
            (true, _) => {
                let m = if unk.len() % 2 == 0 {
                    unk.len()
                } else {
                    unk.len() - 1
                };
                for &v in unk[0..m].iter() {
                    directed_edges.insert((u, v));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
                for &v in unk[m..].iter() {
                    directed_edges.insert((v, u));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
            }
            (false, _) => {
                let m = if unk.len() % 2 == 0 {
                    unk.len() - 1
                } else {
                    unk.len()
                };
                for &v in unk[0..m].iter() {
                    directed_edges.insert((u, v));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
                for &v in unk[m..].iter() {
                    directed_edges.insert((v, u));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
            }
        }
    }

    for u in 0..n {
        let mut count = 0;
        for &v in g[u].iter() {
            match direction(u, v, &directed_edges) {
                Some(true) => { count += 1 }
                Some(false) => {}
                _ => {}
            }
        }
        if count % 2 != 0 {
            panic!("invalid");
        }
    }

    let mut ans = vec![];
    for (u, v) in edges {
        match direction(u, v, &directed_edges) {
            Some(true) => { ans.push((u, v)); }
            Some(false) => { ans.push((v, u)); }
            _ => {
                put!(-1);
                return;
            }
        }
    }

    for (u, v) in ans {
        put!(u + 1, v + 1);
    }

}

