#[allow(dead_code)]
fn add_bi_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    graph[dest].push(Edge::new(*index, dest, src, weight));
    *index += 1;
}
#[allow(dead_code)]
fn add_uni_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    *index += 1;
}

fn dfs(g: &Graph, from: usize, parent: usize, parents: &mut Vec<usize>, orders: &mut Vec<usize>) {
    let n = g.len();
    if parents[from] != n {
        return;
    }
    parents[from] = parent;
    orders.push(from);
    for e in g[from].iter() {
        if e.dest == parent {
            continue;
        }
        dfs(g, e.dest, from, parents, orders);
    }
}

