            edges[a].remove(&to);
            edges[to].remove(&a);
            if edges[to].len() == 1 {
                que.push_front(to);
            } else if used[to] % 2 == 1 {
                que2.push_front(to);
            }
        }

        while let Some(a) = que2.pop_back() {
            if !edges[a].is_empty() && used[a] % 2 == 1 {
                let to = edges[a].iter().cloned().next().unwrap();
                edges[a].remove(&to);
                edges[to].remove(&a);
                used[a] += 1;
                answers.push((a, to));
                if edges[a].len() == 1 {
                    que.push_front(a);
                }
                if edges[to].len() == 1 {
                    que.push_front(to);
                }
            }
        }
        for a in 0..n {
            if !edges[a].is_empty() {
                let to = edges[a].iter().cloned().next().unwrap();
                edges[a].remove(&to);
                edges[to].remove(&a);
                used[a] += 1;
                answers.push((a, to));

                if edges[a].len() == 1 {
                    que.push_front(a);
                } else if used[a] % 2 == 1 {
                    que2.push_front(to);
                }
                if edges[to].len() == 1 {
                    que.push_front(to);
                }
                continue 'outer;
            }
        }
    }

    for ans in answers {
        println!("{} {}", ans.0 + 1, ans.1 + 1);
    }
}

