const M: i64 = 1_000_000_007;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let m: usize = sc.cin();
    if m % 2 == 1 {
        put!(-1);
        return;
    }

    let mut g = vec![vec![]; n];
    let mut edges = vec![];
    use std::collections::HashSet;
    let mut directed_edges = HashSet::new();  // contains(u, v) iff u->v

    for _ in 0..m {
        let a = sc.cin::<usize>() - 1;
        let b = sc.cin::<usize>() - 1;
        g[a].push(b);
        g[b].push(a);
        edges.push((a, b));
    }

    use std::collections::BinaryHeap;

    let mut degs: Vec<usize> = (0..n).map(|i| g[i].len()).collect();  // un-assigned
    let mut q = BinaryHeap::new();
    for i in 0..n { q.push((-(degs[i] as i32), i)); }

    fn direction(u: usize, v: usize, memo: &HashSet<(usize, usize)>) -> Option<bool> {
        if memo.contains(&(u, v)) {
            Some(true)
        } else if memo.contains(&(v, u)) {
            Some(false)
        } else {
            None
        }
    }

    while let Some((_, u)) = q.pop() {
        if degs[u] == 0 { continue }
        let mut count = 0;
        let mut unk = vec![];
        for &v in g[u].iter() {
            match direction(u, v, &directed_edges) {
                Some(true) => {
                    count += 1;
                }
                Some(false) => {
                }
                None => {
                    unk.push(v);
                }
            }
        }
        degs[u] = 0;
        match (count % 2 == 0, unk.len()) {
            (true, 0) => {}
            (false, 0) => {
                put!(-1);
                return;  // failed
            }
            (true, _) => {
                let m = (unk.len() / 2) * 2;
                for &v in unk[0..m].iter() {
                    directed_edges.insert((u, v));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
                for &v in unk[m..].iter() {
                    directed_edges.insert((v, u));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
            }
            (false, _) => {
                let m = ((unk.len() - 1) / 2) * 2 + 1;
                for &v in unk[0..m].iter() {
                    directed_edges.insert((u, v));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
                for &v in unk[m..].iter() {
                    directed_edges.insert((v, u));
                    degs[v] -= 1;
                    q.push((-(degs[v] as i32), v));
                }
            }
        }
    }

    for (u, v) in edges {
        match direction(u, v, &directed_edges) {
            Some(true) => {
                put!(u+1, v+1);
            }
            Some(false) => {
                put!(v+1, u+1);
            }
            _ => {
                trace!("Err", u, v);
            }
        }
    }

}

use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    let mut vis = vec![false; n];
    let mut edges: Vec<Option<(usize, usize)>> = vec![None; m];
    vis[0] = true;
    dfs(0, 0, &graph, &mut edges, &mut vis);
    for e in edges.into_iter() {
        let (from, to) = e.unwrap();
        sc.write(format!("{} {}\n", from + 1, to + 1));
    }
}

fn dfs(
    v: usize,
    p: usize,
    graph: &Vec<Vec<(usize, usize)>>,
    edges: &mut Vec<Option<(usize, usize)>>,
    vis: &mut Vec<bool>,
) {
    for &(next, _) in graph[v].iter() {
        if vis[next] {
            continue;
        }
        vis[next] = true;
        dfs(next, v, graph, edges, vis);
    }

    let mut out = 0;
    for &(next, edge_id) in graph[v].iter() {
        if next == p {
            continue;
        }
        if edges[edge_id].is_none() {
            edges[edge_id] = Some((v, next));
        }
        let (from, _) = edges[edge_id].unwrap();
        if from == v {
            out += 1;
        }
    }
    for &(next, edge_id) in graph[v].iter() {
        if next == p {
            assert!(edges[edge_id].is_none());
            if out % 2 == 0 {
                edges[edge_id] = Some((next, v));
            } else {
                edges[edge_id] = Some((v, next));
            }
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

