use std::collections::{HashMap, HashSet, VecDeque};

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        #[allow(unused_mut)]
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};
    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };
    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };
    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };
    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };
    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        _n: usize, // node count
        m: usize, // edge count
        edges: [(usize1, usize1); m], // usize1 translate 1-origin to 0-origin
    }

    let mut edgemap = HashMap::new();

    for (n0, n1) in edges {
        edgemap.entry(n0).or_insert(HashSet::new()).insert(n1);
        edgemap.entry(n1).or_insert(HashSet::new()).insert(n0);
    }

    let mut ansset = HashSet::new();
    let mut visitedge = HashSet::new();
    let mut visitnode = HashSet::new();
    let mut origincnts = HashMap::new();
    let mut q = VecDeque::new();

    q.push_back(0);
    while q.len() > 0 {
        let n = q.pop_front().unwrap();
        visitnode.insert(n);
        match edgemap.get(&n) {
            Some(nexts) => {
                let l = nexts.len();
                if l == 0 {
                    continue;
                }
                for (i, &nx) in nexts.iter().enumerate() {
                    let edgekey = if n < nx { (n, nx) } else { (nx, n) };
                    if !visitnode.contains(&nx) {
                        q.push_back(nx);
                    }
                    if visitedge.contains(&edgekey) {
                        continue;
                    }

                    if i == l - 1 && *(origincnts.entry(n).or_insert(0)) % 2 == 0 {
                        ansset.insert((nx, n));
                        let ocnt = origincnts.entry(nx).or_insert(0);
                        *ocnt += 1;
                    } else {
                        ansset.insert((n, nx));
                        let ocnt = origincnts.entry(n).or_insert(0);
                        *ocnt += 1;
                    }
                    visitedge.insert(edgekey);
                }
            }
            None => {}
        }
    }

    // check ans
    let mut cntmap = HashMap::new();
    for (x, _) in ansset.clone() {
        let cnt = cntmap.entry(x).or_insert(0);
        *cnt += 1
    }

    if cntmap.iter().all(|(_, v)| v % 2 == 0) {
        for (x, y) in ansset {
            println!("{} {}", x + 1, y + 1);
        }
    } else {
        println!("-1");
    }
}

