fn solve() {
    let (n, m) = get!(usize, usize);
    let ab = get!(usize, usize; m);

    if m % 2 == 1 {
        println!("-1");
        return;
    }

    let mut nodes = vec![Vec::new(); n + 1];
    for (a, b) in ab {
        nodes[a].push(b);
        nodes[b].push(a);
    }

    let mut parent = vec![None; n + 1];
    let mut queue = VecDeque::new();
    queue.push_back(1);
    parent[1] = Some(0);
    let mut leaves = Vec::new();
    let mut res = BTreeSet::new();
    let mut outn = vec![0; n + 1];
    while let Some(node) = queue.pop_front() {
        let mut updated = false;
        for &next in &nodes[node] {
            if let Some(par) = parent[next] {
                if node != 1 && parent[node].unwrap() != next && !res.contains(&(next, node)) {
                    res.insert((node, next));
                    outn[node] += 1;
                }
                continue;
            }
            updated = true;
            parent[next] = Some(node);
            queue.push_back(next);
        }
        if !updated {
            leaves.push(node);
        }
    }

    for leaf in leaves {
        let mut current = leaf;
        while let Some(par) = parent[current] {
            if outn[current] % 2 == 0 {
                res.insert((par, current));
                outn[par] += 1;
            } else {
                res.insert((current, par));
            }
            if par == 1 {
                break;
            }
            current = par;
        }
    }
    for (src, dst) in res {
        println!("{} {}", src, dst);
    }
}

use std::collections::{BTreeSet, BinaryHeap};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![BTreeSet::new(); n];
    let mut deg = vec![0; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].insert(b);
        graph[b].insert(a);
        deg[a] += 1;
        deg[b] += 1;
    }

    let mut forward = vec![0; n];
    let mut ans = vec![];
    let mut heap = BinaryHeap::new();
    for i in 0..n {
        heap.push((-deg[i], i));
    }
    while let Some((d, v)) = heap.pop() {
        if -d != deg[v] {
            continue;
        }

        if (deg[v] + forward[v]) % 2 == 1 {
            let to = v;
            let from = *graph[v].iter().next().unwrap();
            ans.push((from, to));
            assert!(graph[to].remove(&from));
            assert!(graph[from].remove(&to));
            deg[to] -= 1;
            deg[from] -= 1;
            forward[from] += 1;
            if deg[to] > 0 {
                heap.push((-deg[to], to));
            }
            if deg[from] > 0 {
                heap.push((-deg[from], from));
            }
        } else {
            let from = v;
            let to = graph[v].clone();
            for to in to.into_iter() {
                ans.push((from, to));
                assert!(graph[to].remove(&from));
                assert!(graph[from].remove(&to));
                deg[to] -= 1;
                deg[from] -= 1;
                forward[from] += 1;
                if deg[to] > 0 {
                    heap.push((-deg[to], to));
                }
            }
        }
    }
    assert!(forward.iter().all(|&f| f % 2 == 0));
    assert_eq!(forward.iter().sum::<i64>(), m as i64);

    for (from, to) in ans.into_iter() {
        println!("{} {}", from + 1, to + 1);
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

