#[derive(Debug, Clone)]
pub struct TreeRec {
    pub n: usize,
    deg: Vec<usize>,
    ans: Vec<(usize, usize)>,
}
impl TreeRec {
    pub fn new(n: usize, deg: Vec<usize>, ans: Vec<(usize, usize)>) -> Self {
        Self { n, deg, ans }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) {
        for a in graph.adjacency(u).iter().filter(|a| a.to != p) {
            self.dfs(a.to, u, graph);
            let (x, y) = if self.deg[a.to] % 2 == 0 {
                (u, a.to)
            } else {
                (a.to, u)
            };
            self.ans.push((x, y));
            self.deg[x] += 1;
        }
    }
}

