fn run() {
    input! {
        n: usize,
        m: usize,
        edges: [(usize1, usize1); m],
    }
    if edges.len() % 2 != 0 {
        println!("-1");
        return;
    }

    let mut vs = vec![vec![]; n];
    for i in 0..m {
        vs[edges[i].0].push(i);
        vs[edges[i].1].push(i);
    }
    let mut queue = VecDeque::new();
    let mut used = HashSet::new();
    let mut dist = vec![usize::max_value(); m];
    let mut order = Vec::new();
    queue.push_back(0);
    used.insert(0);
    dist[0] = 0;
    while let Some(e) = queue.pop_front() {
        order.push(e);
        for &ne in &vs[edges[e].0] {
            if !used.contains(&ne) {
                used.insert(ne);
                queue.push_back(ne);
                dist[ne] = dist[e] + 1;
            }
        }
        for &ne in &vs[edges[e].1] {
            if !used.contains(&ne) {
                used.insert(ne);
                queue.push_back(ne);
                dist[ne] = dist[e] + 1;
            }
        }
    }
    let mut used = HashSet::new();
    order.reverse();
    for &e in &order {
        if used.contains(&e) {
            continue;
        }
        used.insert(e);
        let mut pe = usize::max_value();
        let mut common = usize::max_value();
        let mut d = 0;
        for &ne in &vs[edges[e].0] {
            if !used.contains(&ne) {
                if d <= dist[ne] {
                    d = dist[ne];
                    pe = ne;
                    common = edges[e].0;
                }
            }
        }
        for &ne in &vs[edges[e].1] {
            if !used.contains(&ne) {
                if d <= dist[ne] {
                    d = dist[ne];
                    pe = ne;
                    common = edges[e].1;
                }
            }
        }
        assert!(pe != usize::max_value());
        used.insert(pe);
        println!(
            "{} {}",
            common + 1,
            if common == edges[e].0 {
                edges[e].1 + 1
            } else {
                edges[e].0 + 1
            }
        );
        println!(
            "{} {}",
            common + 1,
            if common == edges[pe].0 {
                edges[pe].1 + 1
            } else {
                edges[pe].0 + 1
            }
        );
    }
}

//{{{ ---- template ----
fn main() {
    let _ = ::std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub trait SetMinMax {
    fn set_min(&mut self, v: Self) -> bool;
    fn set_max(&mut self, v: Self) -> bool;
}

impl<T> SetMinMax for T
where
    T: PartialOrd,
{
    fn set_min(&mut self, v: T) -> bool {
        *self > v && {
            *self = v;
            true
        }
    }
    fn set_max(&mut self, v: T) -> bool {
        *self < v && {
            *self = v;
            true
        }
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

