fn dfs(
    v: usize,
    graph: &Vec<Vec<usize>>,
    ans: &mut Vec<(usize, usize)>,
    visited: &mut Vec<usize>,
    prev: Option<usize>,
    id: &mut usize,
) -> bool {
    // eprintln!("v = {}", v);
    // end
    let mut count = 0;
    *id += 1;
    visited[v] = *id;
    for &next in &graph[v] {
        if Some(next) == prev {
            continue;
        }
        if visited[next] == 0 {
            if dfs(next, graph, ans, visited, Some(v), id) {
                // eprintln!("v = {}, {} -> {}", v, next, v);
                ans.push((next, v));
            } else {
                // eprintln!("v = {}, {} -> {}", v, v, next);
                ans.push((v, next));
                count += 1;
            }
        } else if visited[v] > visited[next] {
            // eprintln!("v = {}, {} -> {}", v, v, next);
            ans.push((v, next));
            count += 1;
        }
    }
    count % 2 != 0
}

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        es: [(usize1, usize1); m],
    }
    let mut graph = vec![vec![]; n];
    if m % 2 != 0 {
        writeln!(buf, "-1");
        return buf;
    }
    for &(s, t) in &es {
        graph[s].push(t);
        graph[t].push(s);
    }
    let mut ans = vec![];
    let mut visited = vec![0; n];
    let mut id = 0;
    dfs(0, &graph, &mut ans, &mut visited, None, &mut id);
    for &(s, t) in &ans {
        writeln!(buf, "{} {}", s + 1, t + 1);
    }
    buf
}

