use std::io::Write;

fn run() {
    input! {
        n: usize,
        m: usize,
        e: [(usize1, usize1); m],
    }
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut g = vec![vec![]; n];
    for (a, b) in e {
        g[a].push(b);
        g[b].push(a);
    }
    let mut parent = vec![n; n];
    let mut q = vec![];
    let mut back = vec![];
    let root = 0;
    parent[root] = root;
    let mut stack = vec![root];
    while let Some(v) = stack.pop() {
        q.push(v);
        for &u in g[v].iter() {
            if parent[u] == n {
                parent[u] = v;
                stack.push(u);
            } else if u != parent[v] {
                back.push((std::cmp::min(u, v), std::cmp::max(u, v)));
            }
        }
    }
    back.sort();
    back.dedup();
    assert!(back.len() == m - n + 1);
    let mut deg = vec![0; n];
    for &(a, _) in back.iter() {
        deg[a] += 1;
    }
    let mut ans = back;
    for &v in q.iter().rev() {
        if v == root {
            assert!(deg[v] % 2 == 0);
        } else {
            let p = parent[v];
            if deg[v] % 2 == 0 {
                deg[p] += 1;
                ans.push((p, v));
            } else {
                deg[v] += 1;
                ans.push((v, p));
            }
        }
    }
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    for (a, b) in ans {
        writeln!(out, "{} {}", a + 1, b + 1).ok();
    }
}

fn main() {
    run();
}

