        }
        tree[cur].insert(to);
        dfs(to, edges, tree, used);
    }
}

fn dfs2(
    cur: usize,
    tree: &Vec<HashSet<usize>>,
    count: &Vec<i32>,
    pairs: &mut Vec<(usize, usize)>,
) -> bool {
    let mut remainder = count[cur] % 2 == 1;
    for &to in tree[cur].iter() {
        let ret = dfs2(to, tree, count, pairs);
        if ret {
            pairs.push((to, cur));
        } else {
            pairs.push((cur, to));
            remainder = !remainder;
        }
        // remainder ^= ret;
    }
    remainder
}

