fn main() {
    input! {
        _n: usize, // node count
        m: usize, // edge count
        edges: [(usize1, usize1); m], // usize1 translate 1-origin to 0-origin
    }

    let mut edgemap = HashMap::new();
    let mut edgecnt = HashMap::new();

    for (n0, n1) in edges {
        edgemap.entry(n0).or_insert(HashSet::new()).insert(n1);
        edgemap.entry(n1).or_insert(HashSet::new()).insert(n0);
        {
            let c0 = edgecnt.entry(n0).or_insert(0);
            *c0 += 1;
        }
        {
            let c1 = edgecnt.entry(n1).or_insert(0);
            *c1 += 1;
        }
    }

    let mut anss = Vec::new();
    let mut visitedge = HashSet::new();
    let mut visitnode = HashSet::new();
    let mut origincnts = HashMap::new();
    let mut q = VecDeque::new();

    q.push_back(0);
    while q.len() > 0 {
        let n = q.pop_back().unwrap();
        visitnode.insert(n);
        match edgemap.get(&n) {
            Some(nexts) => {
                for (i, &nx) in nexts.iter().enumerate() {
                    let edgekey = if n < nx { (n, nx) } else { (nx, n) };
                    if !visitnode.contains(&nx) {
                        q.push_back(nx);
                    }
                    if visitedge.contains(&edgekey) {
                        continue;
                    }
                    // print!("i:{} ", i);
                    // print!("{}({})-", n + 1, origincnts.entry(n).or_insert(0));
                    // print!("{}({}) ", nx + 1, origincnts.entry(nx).or_insert(0));
                    if edgecnt[&n] == 1 && *(origincnts.entry(n).or_insert(0)) % 2 == 0 {
                        // println!("dest");
                        anss.push((nx, n));
                        let ocnt = origincnts.entry(nx).or_insert(0);
                        *ocnt += 1;
                    } else if edgecnt[&nx] == 1 && *(origincnts.entry(nx).or_insert(0)) % 2 == 1 {
                        // println!("dest");
                        anss.push((nx, n));
                        let ocnt = origincnts.entry(nx).or_insert(0);
                        *ocnt += 1;
                    } else {
                        // println!("origin");
                        anss.push((n, nx));
                        let ocnt = origincnts.entry(n).or_insert(0);
                        *ocnt += 1;
                    }
                    {
                        let ec = edgecnt.entry(n).or_insert(0);
                        *ec -= 1;
                    }
                    {
                        let ec = edgecnt.entry(nx).or_insert(0);
                        *ec -= 1;
                    }
                    visitedge.insert(edgekey);
                }
            }
            None => {}
        }
    }

    // check ans
    let mut cntmap = HashMap::new();
    for (x, _) in anss.clone() {
        let cnt = cntmap.entry(x).or_insert(0);
        *cnt += 1
    }

    if cntmap.iter().all(|(_, v)| v % 2 == 0) {
        for (x, y) in anss {
            println!("{} {}", x + 1, y + 1);
        }
    } else {
        println!("-1");
    }
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    if m % 2 == 1 {
        println!("-1");
        return;
    }

    let mut edges: Vec<Option<(usize, usize)>> = vec![None; n];
    let mut vis = vec![false; n];
    dfs(0, 0, &graph, &mut edges, &mut vis);
    for i in 0..m {
        let (from, to) = edges[i].unwrap();
        sc.write(format!("{} {}\n", from + 1, to + 1));
    }
}

fn dfs(
    v: usize,
    p: usize,
    graph: &Vec<Vec<(usize, usize)>>,
    edges: &mut Vec<Option<(usize, usize)>>,
    vis: &mut Vec<bool>,
) {
    vis[v] = true;
    for &(next, _) in graph[v].iter() {
        if !vis[next] {
            dfs(next, v, graph, edges, vis);
        }
    }

    for &(next, edge_id) in graph[v].iter() {
        if next == p {
            continue;
        }
        if edges[edge_id].is_none() {
            edges[edge_id] = Some((v, next));
        }
    }

    let mut out = 0;
    for &(_, i) in graph[v].iter() {
        if let Some((from, _)) = edges[i] {
            if from == v {
                out += 1;
            }
        }
    }

    for &(next, edge_id) in graph[v].iter() {
        if next == p {
            if out % 2 == 0 {
                edges[edge_id] = Some((p, v));
            } else {
                edges[edge_id] = Some((v, p));
            }
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

