use std::collections::{HashSet, BTreeSet};

fn dfs(
    v: usize,
    adj: &[BTreeSet<usize>],
    visited: &mut HashSet<(usize, usize)>,
    res: &mut Vec<(usize, usize)>
) {
    for &next in &adj[v] {
        let (a, b) = if v < next { (v, next) } else { (next, v) };
        if !visited.contains(&(a, b)) {
            res.push((a, b));
            visited.insert((a, b));
            dfs(next, adj, visited, res);
        }
    }
}

fn main() {
    read!(n = usize, m = usize);
    if m % 2 == 1 {
        println!("-1");
    } else {
        let mut adj = vec![BTreeSet::new(); n];
        let mut node_to_deg = vec![0; n];
        readx_loop!(|a = usize_, b = usize_| {
            let (a, b) = if a < b { (a, b) } else { (b, a) };
            adj[a].insert(b);
            adj[b].insert(a);
            node_to_deg[a] += 1;
            node_to_deg[b] += 1;
        });

        let mut edges = Vec::new();
        dfs(0, &adj, &mut HashSet::new(), &mut edges);
        edges.reverse();

        let mut deg_to_nodes = vec![BTreeSet::new(); n];
        for (v, &deg) in node_to_deg.iter().enumerate() {
            deg_to_nodes[deg].insert(v);
        }
        let mut is_odd = vec![false; n];
        let mut ans = Vec::new();

        for (a, b) in edges {
            let (v1, v2) = if deg_to_nodes[1].contains(&a) {
                if is_odd[a] { (a, b) } else { (b, a) }
            } else if deg_to_nodes[1].contains(&b) {
                if is_odd[b] { (b, a) } else { (a, b) }
            } else {
                (a, b)
            };

            let v1_deg = node_to_deg[v1];
            let v2_deg = node_to_deg[v2];
            ans.push((v1, v2));
            adj[v1].remove(&v2);
            adj[v2].remove(&v1);
            node_to_deg[v1] -= 1;
            node_to_deg[v2] -= 1;
            deg_to_nodes[v1_deg].remove(&v1);
            deg_to_nodes[v1_deg - 1].insert(v1);
            deg_to_nodes[v2_deg].remove(&v2);
            deg_to_nodes[v2_deg - 1].insert(v2);
            is_odd[v1] = !is_odd[v1];
        }

        dbg!(adj);
        dbg!(node_to_deg);
        dbg!(deg_to_nodes);
        dbg!(is_odd);

        with_stdout(|mut f| {
            for (v1, v2) in ans {
                writeln!(f, "{} {}", v1+1, v2+1).unwrap();
            }
        })
    }
}

