        &self.graph[from]
    }
}
#[derive(Debug)]
pub struct GraphRec {
    n: usize,
    m: usize,
    visited: Vec<bool>,
    out: Vec<usize>,
    ab: Vec<(usize, usize)>,
}
impl GraphRec {
    pub fn new(n: usize, ab: Vec<(usize, usize)>) -> GraphRec {
        let m = ab.len();
        GraphRec {
            n: n,
            m: m,
            visited: vec![false; n],
            out: vec![0; n],
            ab: ab,
        }
    }
    pub fn dfs(&mut self, u: usize, p: Option<usize>, graph: &Graph) {
        for v in graph.adjacency(u) {
            if !self.visited[v.to] {
                self.out[self.ab[v.id].0] -= 1;
                self.visited[v.to] = true;
                self.dfs(v.to, Some(v.id), graph);
            }
        }
        if let Some(i) = p {
            let v = if self.ab[i].0 == u {
                self.ab[i].1
            } else {
                self.ab[i].0
            };
            self.ab[i] = if self.out[u] % 2 == 1 { (u, v) } else { (v, u) };
            self.out[self.ab[i].0] += 1;
        }
    }
}
fn main() {
    input! { n, m, ab: [(usize1, usize1); m] };
    if m % 2 == 1 {
        println!("{}", -1);
        return;
    }
    let mut graph = Graph::new(n);
    let mut rec = GraphRec::new(n, ab);
    for &(a, b) in rec.ab.iter() {
        graph.add_undirected_edge(a, b);
        rec.out[a] += 1;
    }
    rec.visited[0] = true;
    rec.dfs(0, None, &graph);
    for i in 0..m {
        println!("{} {}", rec.ab[i].0 + 1, rec.ab[i].1 + 1);
    }
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    let mut edge_used = vec![false; m];
    let mut vis = vec![false; n];
    vis[0] = true;
    let mut answer = vec![None; m];
    dfs(0, &mut vis, &graph, &mut edge_used, &mut answer);
    for e in answer.into_iter() {
        let (from, to) = e.unwrap();
        println!("{} {}", from + 1, to + 1);
    }
}

fn dfs(
    v: usize,
    vis: &mut Vec<bool>,
    graph: &Vec<Vec<(usize, usize)>>,
    edge_used: &mut Vec<bool>,
    answer: &mut Vec<Option<(usize, usize)>>,
) {
    for &(next, id) in graph[v].iter() {
        if vis[next] {
            continue;
        }
        vis[next] = true;
        edge_used[id] = true;
        dfs(next, vis, graph, edge_used, answer);
    }

    let mut forward = 0;
    for &(next, id) in graph[v].iter() {
        match answer[id] {
            None => {
                if !edge_used[id] {
                    answer[id] = Some((v, next));
                    forward += 1;
                }
            }
            Some((from, _)) => {
                if from == v {
                    forward += 1;
                }
            }
        }
    }

    if v != 0 {
        let e = graph[v]
            .iter()
            .filter(|&&(_, id)| answer[id].is_none())
            .map(|&(next, id)| (id, v, next))
            .collect::<Vec<_>>();
        assert_eq!(e.len(), 1);
        let (id, v, next) = e[0];
        if forward % 2 == 0 {
            answer[id] = Some((next, v));
        } else {
            answer[id] = Some((v, next));
        }
    }
}

