fn solve() {
    let (n, m) = get!(usize, usize);
    let ab = get!(usize, usize; m);

    if m % 2 == 1 {
        println!("-1");
        return;
    }

    let mut nodes = vec![Vec::new(); n + 1];
    for (a, b) in ab {
        nodes[a].push(b);
        nodes[b].push(a);
    }

    let mut vec = (1..n + 1).collect::<Vec<_>>();
    vec.sort_by_key(|&e| nodes[e].len());

    let mut set = BTreeSet::new();
    for node in vec {
        let mut outb = 0;
        let mut undecided = Vec::new();
        for &next in &nodes[node] {
            if set.contains(&(node, next)) {
                outb += 1;
            } else if !set.contains(&(next, node)) {
                undecided.push(next);
            }
        }
        if outb % 2 == 1 {
            if undecided.is_empty() {
                println!("-1");
                return;
            }
            let next = undecided.pop().unwrap();
            set.insert((node, next));
        }
        for next in undecided {
            set.insert((next, node));
        }
    }

    for (src, dst) in set {
        println!("{} {}", src, dst);
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![vec![]; n];
    let mut edges = vec![];
    for i in 0..m {
        let x = sc.read::<usize>() - 1;
        let y = sc.read::<usize>() - 1;
        graph[x].push((y, i));
        graph[y].push((x, i));
        edges.push((x, y));
    }

    let mut used = vec![false; m];
    let mut tree = vec![vec![]; n];
    let mut vis = vec![false; n];
    vis[0] = true;
    dfs(0, &graph, &mut used, &mut vis, &mut tree);
    let mut ans = vec![vec![]; n];
    for (v, e) in graph.into_iter().enumerate() {
        for (u, edge_id) in e.into_iter() {
            if used[edge_id] {
                continue;
            }
            used[edge_id] = true;
            ans[v].push(u);
        }
    }

    ans_dfs(0, &tree, &mut ans);

    for from in 0..n {
        for &to in ans[from].iter() {
            println!("{} {}", from + 1, to + 1);
        }
    }
}

fn ans_dfs(v: usize, tree: &Vec<Vec<usize>>, graph: &mut Vec<Vec<usize>>) {
    for &next in tree[v].iter() {
        ans_dfs(next, tree, graph);
        if graph[next].len() % 2 == 0 {
            graph[v].push(next);
        } else {
            graph[next].push(v);
        }
    }
}

fn dfs(
    v: usize,
    graph: &Vec<Vec<(usize, usize)>>,
    used: &mut Vec<bool>,
    vis: &mut Vec<bool>,
    tree: &mut Vec<Vec<usize>>,
) {
    for &(next, edge_id) in graph[v].iter() {
        if used[edge_id] {
            continue;
        }
        if vis[next] {
            continue;
        }
        vis[next] = true;
        used[edge_id] = true;
        tree[v].push(next);
        dfs(next, graph, used, vis, tree);
    }
}

