use std::collections::{BTreeSet, BinaryHeap};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![BTreeSet::new(); n];
    let mut deg = vec![0; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].insert(b);
        graph[b].insert(a);
        deg[a] += 1;
        deg[b] += 1;
    }

    let mut forward = vec![0; n];
    let mut ans = vec![];
    let mut heap = BinaryHeap::new();
    for i in 0..n {
        heap.push((-deg[i], i));
    }
    while let Some((d, v)) = heap.pop() {
        if -d != deg[v] {
            continue;
        }

        if (deg[v] + forward[v]) % 2 == 1 {
            let to = v;
            let from = *graph[v].iter().next().unwrap();
            ans.push((from, to));
            assert!(graph[to].remove(&from));
            assert!(graph[from].remove(&to));
            deg[to] -= 1;
            deg[from] -= 1;
            forward[from] += 1;
            if deg[to] > 0 {
                heap.push((-deg[to], to));
            }
            if deg[from] > 0 {
                heap.push((-deg[from], from));
            }
        } else {
            let from = v;
            let to = graph[v].clone();
            for to in to.into_iter() {
                ans.push((from, to));
                assert!(graph[to].remove(&from));
                assert!(graph[from].remove(&to));
                deg[to] -= 1;
                deg[from] -= 1;
                forward[from] += 1;
                if deg[to] > 0 {
                    heap.push((-deg[to], to));
                }
            }
        }
    }
    for (from, to) in ans.into_iter() {
        println!("{} {}", from + 1, to + 1);
    }
}

