use std::collections::HashSet;

fn dfs(
    v: usize,
    adj: &[HashSet<usize>],
    visited_nodes: &mut [bool],
    visited_edges: &mut HashSet<(usize, usize)>,
    is_odd: &mut [bool],
    ans: &mut Vec<(usize, usize)>
) {
    visited_nodes[v] = true;
    for &next in &adj[v] {
        let (a, b) = if v < next { (v, next) } else { (next, v) };
        if visited_edges.contains(&(a, b)) {
            continue;
        }
        visited_edges.insert((a, b));

        if visited_nodes[next] {
            ans.push((v, next));
            is_odd[v] = !is_odd[v];
        } else {
            dfs(next, adj, visited_nodes, visited_edges, is_odd, ans);
            if is_odd[next] {
                ans.push((next, v));
                is_odd[next] = !is_odd[next];
            } else {
                ans.push((v, next));
                is_odd[v] = !is_odd[v];
            }
        }
    }
}

fn main() {
    read!(n = usize, m = usize);
    let mut edges = HashSet::new();
    let mut adj = vec![HashSet::new(); n];
    readx_loop!(|a = usize_, b = usize_| {
        let (a, b) = if a < b { (a, b) } else { (b, a) };
        edges.insert((a, b));
        adj[a].insert(b);
        adj[b].insert(a);
    });

    if m % 2 == 1 {
        println!("-1");
    } else {
        let mut ans = Vec::new();
        dfs(0, &adj, &mut vec![false; n], &mut HashSet::new(), &mut vec![false; n], &mut ans);
        with_stdout(|mut f| {
            for (a, b) in ans {
                writeln!(f, "{} {}", a+1, b+1).unwrap();
            }
        });
    }
}

use std::collections::{BTreeSet, BinaryHeap};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    if m % 2 == 1 {
        println!("-1");
        return;
    }
    let mut graph = vec![BTreeSet::new(); n];
    let mut deg = vec![0; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].insert(b);
        graph[b].insert(a);
        deg[a] += 1;
        deg[b] += 1;
    }

    let mut forward = vec![0; n];
    let mut ans = vec![];
    let mut heap = BinaryHeap::new();
    for i in 0..n {
        heap.push((-deg[i], i));
    }
    while let Some((d, v)) = heap.pop() {
        if -d != deg[v] {
            continue;
        }

        if (deg[v] + forward[v]) % 2 == 1 {
            let to = v;
            let from = *graph[v].iter().next().unwrap();
            ans.push((from, to));
            assert!(graph[to].remove(&from));
            assert!(graph[from].remove(&to));
            deg[to] -= 1;
            deg[from] -= 1;
            forward[from] += 1;
            if deg[to] > 0 {
                heap.push((-deg[to], to));
            }
            if deg[from] > 0 {
                heap.push((-deg[from], from));
            }
        } else {
            let from = v;
            let to = graph[v].clone();
            for to in to.into_iter() {
                ans.push((from, to));
                assert!(graph[to].remove(&from));
                assert!(graph[from].remove(&to));
                deg[to] -= 1;
                deg[from] -= 1;
                forward[from] += 1;
                if deg[to] > 0 {
                    heap.push((-deg[to], to));
                }
            }
            assert!(graph[v].is_empty());
        }
    }
    assert!(forward.iter().all(|&f| f % 2 == 0));
    //    assert_eq!(forward.iter().sum::<i64>(), m as i64);

    for (from, to) in ans.into_iter() {
        println!("{} {}", from + 1, to + 1);
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

