fn main() {
    input! { n, m, ab: [(usize1, usize1); m] };
    if m % 2 == 1 {
        println!("{}", -1);
        return;
    }
    let mut graph = (0..n)
        .map(|_| std::collections::HashMap::new())
        .collect::<Vec<_>>();
    let mut rev = vec![None; m];
    let mut visited = vec![false; n];
    let mut out = vec![0; n];
    for (i, &(a, b)) in ab.iter().enumerate() {
        graph[a].insert(b, i);
        graph[b].insert(a, i);
    }
    let mut s = vec![];
    for i in 0..n {
        if graph[i].len() == 1 {
            s.push(i);
        }
    }
    let mut res = vec![];
    while let Some(u) = s.pop() {
        visited[u] = true;
        if let Some((&v, &i)) = graph[u].iter().next() {
            if out[u] % 2 == 1 {
                res.push((u, v));
                out[u] += 1;
                rev[i] = Some(ab[i].0 == v);
            } else {
                res.push((v, u));
                out[v] += 1;
                rev[i] = Some(ab[i].0 == u);
            }
            graph[u].remove(&v);
            graph[v].remove(&u);
            if graph[v].len() == 1 {
                s.push(v);
            }
        }
    }
    for i in 0..n {
        if !visited[i] {
            s.push(i);
            break;
        }
    }
    while let Some(u) = s.pop() {
        let mut b = vec![];
        for (&v, &i) in graph[u].iter() {
            if rev[i].is_none() {
                b.push((v, i));
            }
        }
        b.sort_by_key(|&(v, _i)| ((out[v] + 1) % 2, out[v]));
        for &(v, i) in b.iter() {
            // let v = if ab[i].0 == u { ab[i].1 } else { ab[i].0 };
            if graph[v].len() == 1 {
                if out[v] % 2 == 1 {
                    res.push((v, u));
                    out[v] += 1;
                    rev[i] = Some(ab[i].0 == u);
                } else {
                    res.push((u, v));
                    out[u] += 1;
                    rev[i] = Some(ab[i].0 == v);
                }
            } else {
                if out[u] % 2 == 1 {
                    res.push((u, v));
                    out[u] += 1;
                    rev[i] = Some(ab[i].0 == v);
                } else {
                    res.push((v, u));
                    out[v] += 1;
                    rev[i] = Some(ab[i].0 == u);
                }
            }
            graph[u].remove(&v);
            graph[v].remove(&u);
            visited[v] = true;
            s.push(v);
        }
    }
    for i in 0..m {
        let (u, v) = if rev[i].unwrap_or(false) {
            (ab[i].1, ab[i].0)
        } else {
            ab[i]
        };
        println!("{} {}", u + 1, v + 1);
    }
}

pub trait Readable {
    type Output;
