struct UnionFind {
    n: usize,
    parent: Vec<usize>,
    count: Vec<usize>
}

impl UnionFind {
    fn new(n: usize) -> Self {
        let mut p = vec![0; n];
        for i in 0..n {
            p[i] = i;
        }
        UnionFind { n: n, parent: p, count: vec![1; n] }
    }

    fn find(&mut self, a: usize) -> usize {
        if self.parent[a] == a {
            return a;
        }
        let par = self.parent[a];
        self.parent[a] = self.find(par);
        self.parent[a]
    }

    fn unite(&mut self, a: usize, b: usize) {
        let a = self.find(a);
        let b = self.find(b);
        if a == b {
            return;
        }
        let ca = self.count[a];
        let cb = self.count[b];
        let total = ca + cb;
        self.count[b] = total;
        self.count[a] = total;
        if ca < cb {
            self.parent[a] = b;
        } else {
            self.parent[b] = a;
        }
    }

    fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }

    fn count(&mut self, a: usize) -> usize {
        let a = self.find(a);
        self.count[a]
    }
}


fn dfs(now: usize, par: usize, parent: &mut Vec<usize>, tree: &Vec<Vec<usize>>, outdeg: &Vec<usize>, flag: &mut Vec<usize>) {
    parent[now] = par;
    for &to in &tree[now] {
        if to == par {
            continue;
        }
        dfs(to, now, parent, tree, outdeg, flag);
    }
    if outdeg[now] % 2 == 1 {
        flag[now] += 1;
    }
    if par != tree.len() {
        flag[par] += flag[now];
    }
}

fn verify(n: usize, edges: &Vec<(usize, usize)>) -> bool {
    let mut ok = true;
    let mut deg = vec![0; n];
    for &e in edges {
        deg[e.0] += 1;
    }
    for i in 0..n {
        if deg[i] % 2 == 1 {
            return false
        }
    }
    true
}

fn main() {
    input! {
        n: usize, m: usize,
        edges: [(usize1, usize1); m],
    };

    let mut uf = UnionFind::new(n);
    let mut tree = vec![vec![]; n];
    let mut outtree = vec![];
    for &e in &edges {
        if uf.same(e.0, e.1) {
            outtree.push(e);
            continue;
        }
        uf.unite(e.0, e.1);
        tree[e.0].push(e.1);
        tree[e.1].push(e.0);
    }

    let mut outdeg = vec![0; n];
    for i in 0..n {
        outdeg[i] = tree[i].len();
        if i != 0 {
            outdeg[i] -= 1;
        }
    }

    let mut ans = vec![];
    for &e in &outtree {
        ans.push(e);
        outdeg[e.0] += 1;
    }

    let mut parent = vec![0; n];
    let mut flag = vec![0; n];

    // println!("{:?}", outdeg);

    dfs(0, n, &mut parent, &tree, &mut outdeg, &mut flag);

    // println!("{:?} {:?}", parent, flag);

    for i in 1..n {
        if flag[i] % 2 == 1 {
            ans.push((i, parent[i]));
        } else {
            ans.push((parent[i], i));
        }
    }

    if verify(n, &ans) {
        println!("Yes");
        for &e in &ans {
            println!("{} {}", e.0+1, e.1+1);
        }
    } else {
        println!("No");
    }
}

