            } else {
                if edges[to].len() == 1 && used[to] % 2 == 1 {
                    println!("-1");
                    return;
                }
                used[a] += 1;
                answers.push((a, to));
            }
            edges[a].remove(&to);
            edges[to].remove(&a);
            if edges[to].len() == 1 {
                que.push_front(to);
            } else if used[to] % 2 == 1 {
                que2.push_front(to);
            }
        }

        while let Some(a) = que2.pop_back() {
            if !edges[a].is_empty() && used[a] % 2 == 1 {
                let to = edges[a].iter().cloned().next().unwrap();
                edges[a].remove(&to);
                edges[to].remove(&a);
                used[a] += 1;
                answers.push((a, to));
                if edges[a].len() == 1 {
                    que.push_front(a);
                }
                if edges[to].len() == 1 {
                    que.push_front(to);
                }
