fn dfs(v: usize, p: usize, mut nex: usize, g: &mut Vec<HashSet<usize>>, pre: &mut Vec<usize>) {
    let n = g.len();
    dbg!(&v);
    for &w in g[v].clone().iter() {
        if w == p {
            continue;
        }
        if pre[w] < n && pre[v] < pre[w] {
            continue;
        }
        if pre[w] == n {
            pre[w] = nex;
            nex += 1;
            dfs(w, v, nex, g, pre);
            if g[w].len() % 2 == 1 {
                g[w].remove(&v);
            } else {
                g[v].remove(&w);
            }
        } else {
            g[w].remove(&v);
        }
    }
}


