    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    if m % 2 == 1 {
        println!("-1");
        return;
    }

    let mut edges: Vec<Option<(usize, usize)>> = vec![None; n];
    let mut vis = vec![false; n];
    dfs(0, 0, &graph, &mut edges, &mut vis);
