fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (writeln!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      m: usize,
      abs: [(usize1,usize1); m],
    }
    if m%2 == 1 {
        return puts!("{}", "-1");
    }
    let mut edges = vec![vec![]; n];
    let mut cnt = vec![0; n];
    for &(a,b) in abs.iter() {
        cnt[a] += 1;
        cnt[b] += 1;

        edges[a].push(b);
        edges[b].push(a);
    }
    // debug!(edges);

    let mut es = vec![];
    for i in 0..n {
        es.push((i, cnt[i]));
    }
    es.sort_by_key(|v| v.1);
    es.reverse();

    use std::collections::HashSet;
    let mut used = HashSet::new();

    let mut ans = vec![];
    for &(i, _) in es.iter() {
        let mut selected = vec![];
        for &nd in edges[i].iter() {
            let mut tmp = (i, nd);
            if i > nd {
                tmp = (nd, i);
            }
            if !used.contains(&tmp) {
                selected.push((cnt[nd], nd));
            }
        }
        selected.sort();
        // debug!(i, selected);
        let rem = selected.len() % 2;
        if rem == 1 {
            selected.pop();
        }

        for (_, nd) in selected {
            let mut tmp = (i, nd);
            if i > nd {
                tmp = (nd, i);
            }
            used.insert(tmp);
            ans.push((i, nd));
            cnt[nd] -= 1;
        }
        cnt[i] = rem;
    }


    for a in ans {
        puts!("{} {}", a.0+1, a.1+1);
    }
}

