fn main() {
    let v = read_vec::<usize>();
    let (n, m) = (v[0], v[1]);
    let mut edges = vec![HashSet::new(); n];
    for _ in 0..m {
        let v = read_vec::<usize>();
        let (a, b) = (v[0] - 1, v[1] - 1);
        edges[a].insert(b);
        edges[b].insert(a);
    }
    if n % 2 == 1 {
        println!("-1");
        return;
    }

    let mut que = VecDeque::new();
    for i in 0..n {
        if edges[i].len() == 1 {
            que.push_back(i);
        }
    }

    let mut answers = vec![];
    let mut used = vec![0; n];

    let mut que2 = VecDeque::new();

    'outer: while answers.len() != n {
        while let Some(a) = que.pop_back() {
            if edges[a].is_empty() {
                if used[a] % 2 == 1 {
                    println!("-1");
                    return;
                }
                continue;
            }
            let to = edges[a].iter().cloned().next().unwrap();
            if used[a] % 2 == 0 {
                used[to] += 1;
                answers.push((to, a));
            } else {
                if edges[to].len() == 1 && used[to] % 2 == 1 {
                    println!("-1");
                    return;
                }
                used[a] += 1;
                answers.push((a, to));
            }
            edges[a].remove(&to);
            edges[to].remove(&a);
            if edges[to].len() == 1 {
                que.push_front(to);
            }
            if used[to] % 2 == 1 {
                que2.push_front(to);
            }
        }

        while let Some(a) = que2.pop_back() {
            if !edges[a].is_empty() && used[a] % 2 == 1 {
                let to = edges[a].iter().cloned().next().unwrap();
                edges[a].remove(&to);
                edges[to].remove(&a);
                used[a] += 1;
                answers.push((a, to));
                if edges[a].len() == 1 {
                    que.push_front(a);
                }
                if edges[to].len() == 1 {
                    que.push_front(to);
                }
            }
        }
        for a in 0..n {
            if !edges[a].is_empty() {
                let to = edges[a].iter().cloned().next().unwrap();
                edges[a].remove(&to);
                edges[to].remove(&a);
                used[a] += 1;
                answers.push((a, to));

                if edges[a].len() == 1 {
                    que.push_front(a);
                }
                if edges[to].len() == 1 {
                    que.push_front(to);
                }
                if used[a] % 2 == 1 {
                    que2.push_front(to);
                }
                continue 'outer;
            }
        }
    }

    for ans in answers {
        println!("{} {}", ans.0 + 1, ans.1 + 1);
    }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

