fn main() {
    input! {
        _n: usize, // node count
        m: usize, // edge count
        edges: [(usize1, usize1); m], // usize1 translate 1-origin to 0-origin
    }

    let mut edgemap = HashMap::new();
    let mut edgecnt = HashMap::new();

    for (n0, n1) in edges {
        edgemap.entry(n0).or_insert(HashSet::new()).insert(n1);
        edgemap.entry(n1).or_insert(HashSet::new()).insert(n0);
        {
            let c0 = edgecnt.entry(n0).or_insert(0);
            *c0 += 1;
        }
        {
            let c1 = edgecnt.entry(n1).or_insert(0);
            *c1 += 1;
        }
    }

    let mut anss = Vec::new();
    let mut visitedge = HashSet::new();
    let mut visitnode = HashSet::new();
    let mut origincnts = HashMap::new();
    let mut q = VecDeque::new();

    q.push_back(0);
    while q.len() > 0 {
        let n = q.pop_back().unwrap();
        visitnode.insert(n);
        match edgemap.get(&n) {
            Some(nexts) => {
                for (i, &nx) in nexts.iter().enumerate() {
                    let edgekey = if n < nx { (n, nx) } else { (nx, n) };
                    if !visitnode.contains(&nx) {
                        q.push_back(nx);
                    }
                    if visitedge.contains(&edgekey) {
                        continue;
                    }
                    // print!("i:{} ", i);
                    // print!("{}({})-", n + 1, origincnts.entry(n).or_insert(0));
                    // print!("{}({}) ", nx + 1, origincnts.entry(nx).or_insert(0));
                    if edgecnt[&n] == 1 && *(origincnts.entry(n).or_insert(0)) % 2 == 0 {
                        // println!("dest");
                        anss.push((nx, n));
                        let ocnt = origincnts.entry(nx).or_insert(0);
                        *ocnt += 1;
                    } else if edgecnt[&nx] == 1 && *(origincnts.entry(nx).or_insert(0)) % 2 == 1 {
                        // println!("dest");
                        anss.push((nx, n));
                        let ocnt = origincnts.entry(nx).or_insert(0);
                        *ocnt += 1;
                    } else {
                        // println!("origin");
                        anss.push((n, nx));
                        let ocnt = origincnts.entry(n).or_insert(0);
                        *ocnt += 1;
                    }
                    let ec = edgecnt.entry(n).or_insert(0);
                    *ec -= 1;
                    let ec = edgecnt.entry(nx).or_insert(0);
                    *ec -= 1;
                    visitedge.insert(edgekey);
                }
            }
            None => {}
        }
    }

    // check ans
    let mut cntmap = HashMap::new();
    for (x, _) in anss.clone() {
        let cnt = cntmap.entry(x).or_insert(0);
        *cnt += 1
    }

    if cntmap.iter().all(|(_, v)| v % 2 == 0) {
        for (x, y) in anss {
            println!("{} {}", x + 1, y + 1);
        }
    } else {
        println!("-1");
    }
}

