fn main() {
    input!{
    n: usize,
    m: i32,
    ab: [(usize, usize); m]
    }
    let ab: Vec<(usize, usize)> = ab;
    let mut table= vec![vec![0; n + 1]; n + 1];
    let mut counts = vec![0; n + 1];

    for &x in ab.iter() {
        let (a, b) = x;
        table[a][b] = 1;
        counts[a] = counts[a] + 1;
    }

    for a in 1..n + 1 {
        if counts[a] % 2 == 0 {
            // nothing
        } else {
            for b in 1..n + 1 {
                if table[a][b] == 1 {
                    table[a][b] = 0;
                    table[b][a] = 1;
                    counts[a] = counts[a] - 1;
                    counts[b] = counts[b] + 1;
                    break;
                }
            }
        }
    }

    if counts.iter().all(|c| c % 2 == 0) {
        for (_a, aa) in table.iter().enumerate() {
            for (_b, &b) in aa.iter().enumerate() {
                if b > 0 {
                    println!("{} {}", _a, _b)
                }
            }
        }
    } else {
        println!("{}", -1);
    }
}

