fn run() {
    input! {
        n: usize,
        m: usize,
        edges: [(usize1, usize1); m],
    }
    if edges.len() % 2 != 0 {
        println!("-1");
        return;
    }

    let mut vs = vec![vec![]; n];
    for i in 0..m {
        vs[edges[i].0].push(i);
        vs[edges[i].1].push(i);
    }
    let mut queue = VecDeque::new();
    let mut used = HashSet::new();
    let mut used_v = HashSet::new();
    let mut dist = vec![usize::max_value(); m];
    let mut order = Vec::new();
    let mut orders = vec![VecDeque::new(); n];
    queue.push_back(0);
    used.insert(0);
    dist[0] = 0;
    while let Some(e) = queue.pop_front() {
        order.push(e);
        orders[edges[e].0].push_back(e);
        orders[edges[e].1].push_back(e);
        if !used_v.contains(&edges[e].0) {
            used_v.insert(edges[e].0);
            for &ne in &vs[edges[e].0] {
                if !used.contains(&ne) {
                    used.insert(ne);
                    queue.push_back(ne);
                    dist[ne] = dist[e] + 1;
                }
            }
        }
        if !used_v.contains(&edges[e].1) {
            used_v.insert(edges[e].1);
            for &ne in &vs[edges[e].1] {
                if !used.contains(&ne) {
                    used.insert(ne);
                    queue.push_back(ne);
                    dist[ne] = dist[e] + 1;
                }
            }
        }
    }
    let mut used = HashSet::new();
    order.reverse();
    for &e in &order {
        if used.contains(&e) {
            continue;
        }
        used.insert(e);
        let mut pe = usize::max_value();
        let mut common = usize::max_value();
        let mut d = 0;
        while let Some(&ne) = orders[edges[e].0].back() {
            if used.contains(&ne) {
                orders[edges[e].0].pop_back();
                continue;
            }
            if d <= dist[ne] {
                pe = ne;
                common = edges[e].0;
            }
            break;
        }
        while let Some(&ne) = orders[edges[e].1].back() {
            if used.contains(&ne) {
                orders[edges[e].1].pop_back();
                continue;
            }
            if d <= dist[ne] {
                pe = ne;
                common = edges[e].1;
            }
            break;
        }
        assert!(pe != usize::max_value());
        used.insert(pe);
        println!(
            "{} {}",
            common + 1,
            if common == edges[e].0 {
                edges[e].1 + 1
            } else {
                edges[e].0 + 1
            }
        );
        println!(
            "{} {}",
            common + 1,
            if common == edges[pe].0 {
                edges[pe].1 + 1
            } else {
                edges[pe].0 + 1
            }
        );
    }
}

