fn main() {
    input! {
        n: usize, m: usize,
        edges: [(usize1, usize1); m]
    };
    if m % 2 == 1 {
        println!("-1");
        return;
    }

    let mut uf = UnionFind::new(n);
    let mut tree = vec![vec![]; n];
    let mut deg = vec![0; n];
    let mut ans = vec![];

    let mut edgemap = HashMap::new();
    for (idx, &(u,v)) in edges.iter().enumerate() {
        if uf.same(u, v) {
            deg[u] += 1;
            ans.push((u+1, v+1));
        } else {
            uf.unite(u, v);
            tree[u].push(v);
            tree[v].push(u);
            edgemap.insert((u,v), idx);
            edgemap.insert((v,u), idx);
        }
    }

    let mut visited = vec![0; m];
    let (count, parent, order) = dfs_cpo(&tree, 0);
    for i in 0..n {
        let v = order[i];
        let mut peid = m;
        for &to in &tree[v] {
            let eid = *edgemap.get(&(v, to)).unwrap();
            if visited[eid] != 0 {
                continue;
            }
            if Some(to) == parent[v] {
                peid = eid;
            } else {
                deg[v] += 1;
                ans.push((v+1, to+1));
                visited[eid] = ifv!(v < to, 1, -1);
            }
        }
        if let Some(p) = parent[v] {
            if deg[v] % 2 == 1 {
                deg[v] += 1;
                ans.push((v+1, p+1));
                visited[peid] = ifv!(v < p, 1, -1);
            }
        } else {
            assert!(i == n-1, deg[v] % 2 == 0);
        }
    }

    for &(u, v) in &ans {
        println!("{} {}", u, v);
    }

}
